    private sealed record Tl1SensorEnvelope(
        int PassiveFirmRange,
        int PassiveApproximateRange,
        int ActiveLevel1FirmRange,
        int ActiveLevel1ApproximateRange,
        int ActiveLevel2FirmRange,
        int ActiveLevel2ApproximateRange)
    {
        public string ProfileId { get; init; } = "tl1-production";
        public bool SingleActiveMode { get; init; }
        public bool CausalEwResolution { get; init; }
        public int NormalActivePowerCost { get; init; } = 2;
        public int HighActivePowerCost { get; init; } = 2;
        public int OverloadAdditionalPowerCost { get; init; } =
            ActiveSensorOverloadProfile.Tl1.AdditionalTacticalPowerCost;
        public int OverloadFirmBonus { get; init; } =
            ActiveSensorOverloadProfile.Tl1.FirmRangeBonus;
        public int OverloadApproximateBonus { get; init; } =
            ActiveSensorOverloadProfile.Tl1.ApproximateRangeBonus;
        public int DiscriminationResistance { get; init; }
        public int PointBlankBurnThroughResistance { get; init; }

        public static Tl1SensorEnvelope FromBaseline(Tl1BaselineCatalog baseline) => new(
            baseline.GetInt("passive_firm_range"),
            baseline.GetInt("passive_approx_range"),
            baseline.GetInt("active_range_level_1_firm"),
            baseline.GetInt("active_range_level_1_approx"),
            baseline.GetInt("active_range_level_2_firm"),
            baseline.GetInt("active_range_level_2_approx"))
        {
            NormalActivePowerCost = 1,
            HighActivePowerCost = 2,
        };

        public static Tl1SensorEnvelope FromFoundation(
            SensorEwFoundationProfile profile) => new(
                profile.PassiveFirmRange,
                profile.PassiveApproximateRange,
                profile.ActiveFirmRange,
                profile.ActiveApproximateRange,
                profile.ActiveFirmRange,
                profile.ActiveApproximateRange)
            {
                ProfileId = profile.Id,
                SingleActiveMode = true,
                CausalEwResolution = true,
                NormalActivePowerCost = profile.ActivePowerCost,
                OverloadAdditionalPowerCost = profile.ActiveOverloadAdditionalPowerCost,
                OverloadFirmBonus = profile.ActiveOverloadFirmBonus,
                OverloadApproximateBonus = profile.ActiveOverloadApproximateBonus,
                DiscriminationResistance = profile.DiscriminationResistance,
                PointBlankBurnThroughResistance = profile.PointBlankBurnThroughResistance,
            };

        public ActiveSensorOverloadProfile ToOverloadProfile() => new(
            OverloadAdditionalPowerCost,
            OverloadFirmBonus,
            OverloadApproximateBonus,
            StrainCost: ActiveSensorOverloadProfile.Tl1.StrainCost,
            StrainLimit: ActiveSensorOverloadProfile.Tl1.StrainLimit);

        public SensorEwFoundationProfile ToFoundationProfile() => new(
            ProfileId,
            PassiveFirmRange,
            PassiveApproximateRange,
            ActiveLevel1FirmRange,
            ActiveLevel1ApproximateRange,
            NormalActivePowerCost,
            OverloadAdditionalPowerCost,
            OverloadFirmBonus,
            OverloadApproximateBonus,
            DiscriminationResistance,
            PointBlankBurnThroughResistance);
    }

    private sealed record SensorTurnState(
        Tl1OperationalTrackPolicy Policy,
        int ActivePower,
        int FirmRange,
        int ApproximateRange,
        bool ActiveSensorInstalledAndFunctional,
        bool UnfundedActiveRequest,
        bool Overloaded = false)
    {
        public bool EstablishedFirm => Policy == Tl1OperationalTrackPolicy.EstablishedFirm;
    }

    private sealed record EwTurnState(
        int EcmRating,
        int EccmRating)
    {
        public static EwTurnState Inactive { get; } = new(0, 0);
    }

    private sealed record AdaptiveEccmOverloadResult(
        int Rating,
        bool Activated);

    public static int Run(
        string studyPath,
        string baselinePath,
        string outputDirectory,
        int? trialsOverride,
        int jobs,
        bool preflightOnly)
    {
        Tl1IntegratedTacticalCombatStudyDocument study =
            JsonSerializer.Deserialize<Tl1IntegratedTacticalCombatStudyDocument>(
                File.ReadAllText(studyPath),
                JsonOptions()) ?? throw new InvalidOperationException(
                    "TL1 integrated tactical-combat study could not be read.");
        Tl1BaselineCatalog baseline = Tl1BaselineCatalog.Load(baselinePath);
        string baselineHash = baseline.Sha256;
        Tl1SensorEnvelope sensorEnvelope = Tl1SensorEnvelope.FromBaseline(baseline);
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles =
            LoadTechnologyProfiles(studyPath, study, baseline);
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles =
            LoadAuxiliaryProfiles(studyPath, study);
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles =
            LoadSensorEwProfiles(studyPath, study);
        LoadedTl1AiDoctrineRegistry? aiDoctrineRegistry =
            LoadAiDoctrineRegistry(studyPath, study);
        Validate(
            study, baselineHash, technologyProfiles, auxiliaryProfiles, sensorEwProfiles,
            aiDoctrineRegistry);
        WeaponFamily[] requiredWeaponFamilies = RequiredWeaponFamiliesForStudy(study.Id);
        Console.WriteLine(
            $"TL1 integrated tactical-combat preflight: {study.Variants.Count} variants; " +
            $"weapon-family coverage: {string.Join(", ", requiredWeaponFamilies.Select(family => family.ToString().ToLowerInvariant()))}; " +
            "fixed or policy-driven range handling; 33 1/3% internal criticals; layered defenses; " +
            $"independent missile travel; {technologyProfiles.Count} technology " +
            "profiles; passed.");
        if (preflightOnly)
        {
            return 0;
        }

        int trials = trialsOverride ?? study.TrialsPerVariant;
        if (trials <= 0)
        {
            throw new InvalidOperationException("Trials per variant must be positive.");
        }
        if (jobs <= 0)
        {
            throw new InvalidOperationException("Jobs must be positive.");
        }

        var results = new Tl1IntegratedTacticalCombatVariantSummary[
            study.Variants.Count];
        var options = new ParallelOptions
        {
            MaxDegreeOfParallelism = Math.Min(jobs, study.Variants.Count),
        };
        Parallel.ForEach(
            study.Variants.Select((variant, index) => (variant, index)),
            options,
            item =>
            {
                results[item.index] = RunVariant(
                    study,
                    study.MasterSeed,
                    item.variant,
                    technologyProfiles,
                    auxiliaryProfiles,
                    sensorEnvelope,
                    sensorEwProfiles,
                    aiDoctrineRegistry,
                    trials);
                Tl1IntegratedTacticalCombatVariantSummary result =
                    results[item.index];
                Console.WriteLine(
                    $"RESULT {result.Id}: mean {result.MeanTurns:F2}, " +
                    $"P90 {result.P90Turns:F2}, final range " +
                    $"{result.MeanFinalRange:F2}, range changes " +
                    $"{result.MeanRangeChanges:F2}, mission kill " +
                    $"{result.OffensiveMissionKillPercent + result.MobilityMissionKillPercent:F2}%.");
            });

        IReadOnlyList<Tl1IntegratedTacticalCombatGate> gates = BuildGates(
            study, results, technologyProfiles, auxiliaryProfiles, sensorEnvelope);
        WriteOutputs(
            study,
            baselineHash,
            trials,
            results,
            gates,
            technologyProfiles,
            auxiliaryProfiles,
            aiDoctrineRegistry,
            outputDirectory);
        IReadOnlyList<Tl1IntegratedTacticalCombatGate> failedGates = gates
            .Where(gate => !gate.Passed)
            .ToArray();
        foreach (Tl1IntegratedTacticalCombatGate gate in failedGates)
        {
            Console.Error.WriteLine(
                $"FAILED GATE {gate.Id}: {gate.Detail}");
        }
        Console.WriteLine(
            $"TL1 Integrated Tactical Combat: {results.Length} variants, " +
            $"{trials} trials each, {failedGates.Count} failed gates. Output: " +
            Path.GetFullPath(outputDirectory));
        return failedGates.Count == 0 ? 0 : 1;
    }

    private static Tl1IntegratedTacticalCombatVariantSummary RunVariant(
        Tl1IntegratedTacticalCombatStudyDocument study,
        ulong masterSeed,
        Tl1IntegratedTacticalCombatVariantDocument variant,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        Tl1SensorEnvelope sensorEnvelope,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles,
        LoadedTl1AiDoctrineRegistry? aiDoctrineRegistry,
        int trials)
    {
        Tl1IntegratedShipBuildDocument? buildA = ResolveBuild(study, variant.SideABuildId);
        Tl1IntegratedShipBuildDocument? buildB = ResolveBuild(study, variant.SideBBuildId);
        Tl1SensorEnvelope variantSensorEnvelopeA = ApplySensorEnvelopeOverrides(
            ResolveSensorEnvelope(
                variant.SideASensorEwProfileId ?? variant.SensorEwProfileId,
                sensorEnvelope, sensorEwProfiles),
            variant, sideA: true);
        Tl1SensorEnvelope variantSensorEnvelopeB = ApplySensorEnvelopeOverrides(
            ResolveSensorEnvelope(
                variant.SideBSensorEwProfileId ?? variant.SensorEwProfileId,
                sensorEnvelope, sensorEwProfiles),
            variant, sideA: false);
        var accumulator = new IntegratedAccumulator();
        for (int trial = 0; trial < trials; trial++)
        {
            try
            {
                accumulator.Add(RunTrial(
                    study.Id, masterSeed, variant, technologyProfiles, auxiliaryProfiles,
                    variantSensorEnvelopeA, variantSensorEnvelopeB,
                    buildA, buildB, aiDoctrineRegistry, trial));
            }
            catch (Exception exception)
            {
                Console.Error.WriteLine(
                    $"TRIAL ERROR variant '{variant.Id}' trial {trial}: {exception}");
                accumulator.AddError();
            }
        }
        return accumulator.ToSummary(
            variant, technologyProfiles, auxiliaryProfiles, buildA, buildB, trials);
    }

    private static IntegratedTrialOutcome RunTrial(
        string studyId,
        ulong masterSeed,
        Tl1IntegratedTacticalCombatVariantDocument variant,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        Tl1SensorEnvelope sensorEnvelopeA,
        Tl1SensorEnvelope sensorEnvelopeB,
        Tl1IntegratedShipBuildDocument? buildA,
        Tl1IntegratedShipBuildDocument? buildB,
        LoadedTl1AiDoctrineRegistry? aiDoctrineRegistry,
        int trialIndex)
    {
        ulong salt = StableVariantSalt(variant);
        IntegratedCombatProfile profile = ResolveProfile(
            variant, technologyProfiles, auxiliaryProfiles);
        IntegratedSide sideA = CreateSide(
            "A",
            variant.SideAFamily,
            variant.SideASecondaryFamily,
            variant,
            profile,
            buildA,
            TrialSeedDeriver.Derive(
                masterSeed,
                "checkpoint-39-track-a",
                trialIndex,
                salt),
            TrialSeedDeriver.Derive(
                masterSeed,
                "checkpoint-39-exposure-a",
                trialIndex,
                salt + 1UL));
        IntegratedSide sideB = CreateSide(
            "B",
            variant.SideBFamily,
            variant.SideBSecondaryFamily,
            variant,
            profile,
            buildB,
            TrialSeedDeriver.Derive(
                masterSeed,
                "checkpoint-39-track-b",
                trialIndex,
                salt + 2UL),
            TrialSeedDeriver.Derive(
                masterSeed,
                "checkpoint-39-exposure-b",
                trialIndex,
                salt + 3UL));
        var attackRandom = new DeterministicRandomStream(
            TrialSeedDeriver.Derive(
                masterSeed,
                "checkpoint-39-attacks",
                trialIndex,
                salt + 4UL));
        var pdsRandom = new DeterministicRandomStream(
            TrialSeedDeriver.Derive(
                masterSeed,
                "checkpoint-39-pds",
                trialIndex,
                salt + 5UL));
        var repairRandomA = new DeterministicRandomStream(
            TrialSeedDeriver.Derive(
                masterSeed,
                "checkpoint-39-repair-a",
                trialIndex,
                salt + 6UL));
        var repairRandomB = new DeterministicRandomStream(
            TrialSeedDeriver.Derive(
                masterSeed,
                "checkpoint-39-repair-b",
                trialIndex,
                salt + 7UL));

        var diagnostics = new IntegratedDiagnosticTelemetry();
        int currentRange = variant.InitialRangeHexes ??
            InitialRange(variant.MovementMode);
        int positionA = 0;
        int positionB = currentRange;
        bool finiteTacticalMap =
            (studyId == Tl1BilateralTacticalGeometryStudyId ||
             studyId == Tl1ScriptedOverloadTacticsStudyId ||
             studyId == Tl1BilateralOverloadCounterplayStudyId ||
             studyId == Tl1SensorEwCandidateCombatStudyId ||
             studyId == Tl1EcmPowerCostCounterplayStudyId ||
             studyId == Tl1SensorDiscriminationBurnthroughStudyId ||
             studyId == Tl1ReactiveEwSubphaseStudyId ||
             studyId == Tl1EwAiDoctrineStudyId ||
             studyId == Tl1ApproximateTrackDegradedFireStudyId ||
             studyId == Tl1AppliedDegradedFireFamilyCandidateStudyId ||
             studyId == Tl1DegradedFireEccmValueStudyId ||
             studyId == Tl2SensorEwDiscriminationIsolationStudyId ||
             studyId == Tl2EwPowerPressureTallViabilityStudyId ||
             studyId == Tl2TacticalComputerEwPermutationStudyId ||
             studyId == Tl2PowerReactorProgressionPermutationStudyId ||
             studyId == Tl2ShieldCapacityPowerIntegrationStudyId ||
             studyId == Tl2ArmorApAiShieldIntegrationStudyId ||
             studyId == Tl2WeaponPenetrationLayeredDefenseStudyId ||
             studyId == CrossTlBuildPermutationScreeningStudyId ||
             studyId == CrossTlPowerAwareInformationControlScreeningStudyId ||
             studyId == CrossTlGeneralizedLegalBuildScreeningStudyId ||
             studyId == CrossTlMatchedReadinessSpaceScreeningStudyId ||
             IsAdaptiveEncounterStudy(studyId)) &&
            variant.TacticalMapRadius is int mapRadius && mapRadius > 0;
        HexMap? tacticalMap = finiteTacticalMap
            ? HexMap.CreateHexagon(variant.TacticalMapRadius!.Value)
            : null;
        (HexCoord coordinateA, HexCoord coordinateB) = finiteTacticalMap
            ? InitialFiniteCoordinates(tacticalMap!, currentRange)
            : (HexCoord.Zero, HexCoord.Zero);
        HexCoord encounterBearingA = coordinateA;
        HexCoord encounterBearingB = coordinateB;
        TacticalFuelRules fuelRules = new(
            variant.StartingFuel ?? TacticalFuelRules.Baseline.StartingFuel,
            variant.MovementFuelPerHex ?? TacticalFuelRules.Baseline.FuelPerTraversedHex,
            variant.EvasiveManeuverFuelCost ?? TacticalFuelRules.Baseline.EvasiveManeuverFuelCost);
        int fuelA = fuelRules.StartingFuel;
        int fuelB = fuelRules.StartingFuel;
        int boundaryTurnsA = 0;
        int boundaryTurnsB = 0;
        int minimumRange = currentRange;
        int maximumRange = currentRange;
        int minimumPostMovementRange = int.MaxValue;
        int postMovementFiringWindows = 0;
        int postMovementReadyWindowsA = 0;
        int postMovementReadyWindowsB = 0;
        int postMovementReadyWindowsMutual = 0;
        int rangeChanges = 0;
        int orderRequests = 0;
        int orderCoercions = 0;
        int scriptedRequests = 0;
        int preferredRequests = 0;
        int movementA = 0;
        int movementB = 0;
        int immobileMovementCoercions = 0;
        int missileReroutes = 0;
        int targetMovementReroutes = 0;
        int missileDistanceTraveled = 0;
        int maximumObservedMissileDistance = 0;
        int missileLaunches = 0;
        int missileTerminalAttacks = 0;
        int missileHits = 0;
        int missilesRangeExhausted = 0;
        int pdsAttempts = 0;
        int pdsIntercepts = 0;
        int immobileBonusAttacks = 0;
        int sameTurnImmobileBonusViolations = 0;
        int criticalSelections = 0;
        int repairAttempts = 0;
        int repairActivations = 0;
        int invalidRepairAttempts = 0;
        int? firstCriticalTurn = null;
        int? firstConsequentialTurn = null;
        bool mobilityLossObserved = false;
        int turns = 0;
        var missiles = new List<IntegratedMissile>();
        IntegratedResolutionCause resolutionCause =
            IntegratedResolutionCause.Unresolved;
        IntegratedWinner winner = IntegratedWinner.Unresolved;
        bool terminalFlightOnly = false;
        int disengagementProgressA = 0;
        int disengagementProgressB = 0;
        bool requestedOpenA = false;
        bool requestedOpenB = false;

        ITacticalOrderPolicy policyA = CreatePolicy(
            variant.MovementMode,
            side: "A");
        ITacticalOrderPolicy policyB = CreatePolicy(
            variant.MovementMode,
            side: "B");
        TacticalPreviousTurnOutcome previousA = TacticalPreviousTurnOutcome.None;
        TacticalPreviousTurnOutcome previousB = TacticalPreviousTurnOutcome.None;
        bool adaptiveEncounter = IsAdaptiveEncounterStudy(studyId) &&
            variant.MovementMode == Tl1IntegratedMovementMode.EngageAdaptive;
        var combatBlackboardA = new TacticalCombatBlackboard(sideB.Id);
        var combatBlackboardB = new TacticalCombatBlackboard(sideA.Id);
        bool observableEcmEmissionA = false;
        bool observableEcmEmissionB = false;
        bool observableActiveSensorEmissionA = false;
        bool observableActiveSensorEmissionB = false;
        bool closureExhaustedA = false;
        bool closureExhaustedB = false;

        bool statefulAuxiliaryPower = IsStatefulAuxiliaryStudy(studyId);
        while (turns < MaximumTurns)
        {
            turns++;
            bool inboundA = missiles.Any(missile => missile.TargetId == sideA.Id);
            bool inboundB = missiles.Any(missile => missile.TargetId == sideB.Id);
            repairActivations += statefulAuxiliaryPower
                ? BeginSideTurnStateful(
                    sideA, sideB, inboundA, diagnostics)
                : BeginSideTurn(sideA, diagnostics);
            repairActivations += statefulAuxiliaryPower
                ? BeginSideTurnStateful(
                    sideB, sideA, inboundB, diagnostics)
                : BeginSideTurn(sideB, diagnostics);

            ShipCombatTurnSnapshot snapshotA =
                ShipCombatTurnSnapshot.Capture(sideA.Ship);
            ShipCombatTurnSnapshot snapshotB =
                ShipCombatTurnSnapshot.Capture(sideB.Ship);
            mobilityLossObserved |= snapshotA.IsImmobile || snapshotB.IsImmobile;

            bool operationalSensorStudy = studyId == Tl1OperationalSensorStudyId ||
                studyId == Tl1TrackAwareAcquisitionStudyId ||
                studyId == Tl1BilateralTacticalGeometryStudyId ||
                studyId == Tl1ScriptedOverloadTacticsStudyId ||
                studyId == Tl1BilateralOverloadCounterplayStudyId ||
                studyId == Tl1SensorEwCandidateCombatStudyId ||
                studyId == Tl1EcmPowerCostCounterplayStudyId ||
                studyId == Tl1SensorDiscriminationBurnthroughStudyId ||
                studyId == Tl1ReactiveEwSubphaseStudyId ||
                studyId == Tl1EwAiDoctrineStudyId ||
                studyId == Tl1ApproximateTrackDegradedFireStudyId ||
                studyId == Tl1AppliedDegradedFireFamilyCandidateStudyId ||
                studyId == Tl1DegradedFireEccmValueStudyId ||
                studyId == Tl2SensorEwDiscriminationIsolationStudyId ||
                studyId == Tl2EwPowerPressureTallViabilityStudyId ||
                studyId == Tl2TacticalComputerEwPermutationStudyId ||
                studyId == Tl2PowerReactorProgressionPermutationStudyId ||
                studyId == Tl2ShieldCapacityPowerIntegrationStudyId ||
                studyId == Tl2ArmorApAiShieldIntegrationStudyId ||
                studyId == Tl2WeaponPenetrationLayeredDefenseStudyId ||
                studyId == CrossTlBuildPermutationScreeningStudyId ||
                studyId == CrossTlPowerAwareInformationControlScreeningStudyId ||
                studyId == CrossTlGeneralizedLegalBuildScreeningStudyId ||
                studyId == CrossTlMatchedReadinessSpaceScreeningStudyId ||
                IsAdaptiveEncounterStudy(studyId);
            TurnSystems systemsA = operationalSensorStudy
                ? TurnSystems.Inactive
                : AllocateDefensiveSystems(sideA, sideB, inboundA);
            TurnSystems systemsB = operationalSensorStudy
                ? TurnSystems.Inactive
                : AllocateDefensiveSystems(sideB, sideA, inboundB);

            if (!terminalFlightOnly)
            {
                if (finiteTacticalMap)
                {
                    int initialTurnRange = currentRange;
                    HexCoord oldCoordinateA = coordinateA;
                    HexCoord oldCoordinateB = coordinateB;
                    TacticalOrderPlan planA;
                    TacticalOrderPlan planB;
                    FiniteTacticalMove moveA;
                    FiniteTacticalMove moveB;

                    if (adaptiveEncounter)
                    {
                        UpdateAdaptiveEncounterContact(
                            turns, currentRange, sensorEnvelopeA,
                            observableEcmEmissionB, observableActiveSensorEmissionB,
                            combatBlackboardA);
                        UpdateAdaptiveEncounterContact(
                            turns, currentRange, sensorEnvelopeB,
                            observableEcmEmissionA, observableActiveSensorEmissionA,
                            combatBlackboardB);
                    }

                    // Movement-phase overload commitments are resolved for both
                    // ships from the same pre-Movement geometry before either
                    // ship moves. The second mover may react geometrically, but
                    // cannot retroactively add STL-overload power.
                    RecordSensorOverloadPlanningOpportunity(
                        sideA, variant.SideATrackPolicy, variant.SideANetEwRangePenalty,
                        sensorEnvelopeA, variant.SideASensorOverloadPolicy, diagnostics);
                    RecordSensorOverloadPlanningOpportunity(
                        sideB, variant.SideBTrackPolicy, variant.SideBNetEwRangePenalty,
                        sensorEnvelopeB, variant.SideBSensorOverloadPolicy, diagnostics);
                    int movementAllowanceA = PrepareSafeStlOverload(
                        sideA,
                        variant.SideAStlOverloadPolicy,
                        currentRange,
                        ref fuelA,
                        diagnostics);
                    int movementAllowanceB = PrepareSafeStlOverload(
                        sideB,
                        variant.SideBStlOverloadPolicy,
                        currentRange,
                        ref fuelB,
                        diagnostics);

                    if (variant.MovementOrder == Tl1IntegratedMovementOrder.SideBFirst)
                    {
                        planB = ChooseEncounterOrders(
                            policyB,
                            BuildDecisionContext(
                                turns,
                                currentRange,
                                sideB,
                                sideA,
                                missiles,
                                previousB,
                                variant.MovementMode,
                                variant.SideBTrackPolicy,
                                variant.SideBNetEwRangePenalty,
                                sensorEnvelopeB,
                                variant.SideBSensorOverloadPolicy,
                                movementAllowanceB,
                                adaptiveEncounter ? combatBlackboardB : null,
                                adaptiveEncounter ? combatBlackboardB.ContactEstablished : null),
                            adaptiveEncounter,
                            combatBlackboardB);
                        int availableB = Math.Min(
                            movementAllowanceB,
                            fuelRules.AffordableMovementHexes(fuelB, evasiveManeuvers: false));
                        moveB = ResolveEncounterMovement(
                            tacticalMap!, coordinateB, coordinateA, availableB, planB,
                            adaptiveEncounter && !combatBlackboardB.ContactEstablished,
                            encounterBearingB);
                        fuelB -= fuelRules.MovementCost(moveB.MovementHexes, evasiveManeuvers: false);
                        coordinateB = moveB.Destination;
                        currentRange = coordinateA.DistanceTo(coordinateB);
                        if (adaptiveEncounter)
                        {
                            UpdateAdaptiveEncounterContact(
                                turns, currentRange, sensorEnvelopeA,
                                observableEcmEmissionB, observableActiveSensorEmissionB,
                                combatBlackboardA);
                        }

                        planA = ChooseEncounterOrders(
                            policyA,
                            BuildDecisionContext(
                                turns,
                                currentRange,
                                sideA,
                                sideB,
                                missiles,
                                previousA,
                                variant.MovementMode,
                                variant.SideATrackPolicy,
                                variant.SideANetEwRangePenalty,
                                sensorEnvelopeA,
                                variant.SideASensorOverloadPolicy,
                                movementAllowanceA,
                                adaptiveEncounter ? combatBlackboardA : null,
                                adaptiveEncounter ? combatBlackboardA.ContactEstablished : null),
                            adaptiveEncounter,
                            combatBlackboardA);
                        int availableA = Math.Min(
                            movementAllowanceA,
                            fuelRules.AffordableMovementHexes(fuelA, evasiveManeuvers: false));
                        moveA = ResolveEncounterMovement(
                            tacticalMap!, coordinateA, coordinateB, availableA, planA,
                            adaptiveEncounter && !combatBlackboardA.ContactEstablished,
                            encounterBearingA);
                        fuelA -= fuelRules.MovementCost(moveA.MovementHexes, evasiveManeuvers: false);
                        coordinateA = moveA.Destination;
                    }
                    else
                    {
                        planA = ChooseEncounterOrders(
                            policyA,
                            BuildDecisionContext(
                                turns,
                                currentRange,
                                sideA,
                                sideB,
                                missiles,
                                previousA,
                                variant.MovementMode,
                                variant.SideATrackPolicy,
                                variant.SideANetEwRangePenalty,
                                sensorEnvelopeA,
                                variant.SideASensorOverloadPolicy,
                                movementAllowanceA,
                                adaptiveEncounter ? combatBlackboardA : null,
                                adaptiveEncounter ? combatBlackboardA.ContactEstablished : null),
                            adaptiveEncounter,
                            combatBlackboardA);
                        int availableA = Math.Min(
                            movementAllowanceA,
                            fuelRules.AffordableMovementHexes(fuelA, evasiveManeuvers: false));
                        moveA = ResolveEncounterMovement(
                            tacticalMap!, coordinateA, coordinateB, availableA, planA,
                            adaptiveEncounter && !combatBlackboardA.ContactEstablished,
                            encounterBearingA);
                        fuelA -= fuelRules.MovementCost(moveA.MovementHexes, evasiveManeuvers: false);
                        coordinateA = moveA.Destination;
                        currentRange = coordinateA.DistanceTo(coordinateB);
                        if (adaptiveEncounter)
                        {
                            UpdateAdaptiveEncounterContact(
                                turns, currentRange, sensorEnvelopeB,
                                observableEcmEmissionA, observableActiveSensorEmissionA,
                                combatBlackboardB);
                        }

                        planB = ChooseEncounterOrders(
                            policyB,
                            BuildDecisionContext(
                                turns,
                                currentRange,
                                sideB,
                                sideA,
                                missiles,
                                previousB,
                                variant.MovementMode,
                                variant.SideBTrackPolicy,
                                variant.SideBNetEwRangePenalty,
                                sensorEnvelopeB,
                                variant.SideBSensorOverloadPolicy,
                                movementAllowanceB,
                                adaptiveEncounter ? combatBlackboardB : null,
                                adaptiveEncounter ? combatBlackboardB.ContactEstablished : null),
                            adaptiveEncounter,
                            combatBlackboardB);
                        int availableB = Math.Min(
                            movementAllowanceB,
                            fuelRules.AffordableMovementHexes(fuelB, evasiveManeuvers: false));
                        moveB = ResolveEncounterMovement(
                            tacticalMap!, coordinateB, coordinateA, availableB, planB,
                            adaptiveEncounter && !combatBlackboardB.ContactEstablished,
                            encounterBearingB);
                        fuelB -= fuelRules.MovementCost(moveB.MovementHexes, evasiveManeuvers: false);
                        coordinateB = moveB.Destination;
                    }

                    currentRange = coordinateA.DistanceTo(coordinateB);
                    if (adaptiveEncounter)
                    {
                        closureExhaustedA = combatBlackboardA.ContactEstablished &&
                            (currentRange == 0 ||
                             BuildTacticalSnapshot(sideA).IsImmobile ||
                             (planA.RangeOrder == RangeOrder.Close &&
                              currentRange >= initialTurnRange));
                        closureExhaustedB = combatBlackboardB.ContactEstablished &&
                            (currentRange == 0 ||
                             BuildTacticalSnapshot(sideB).IsImmobile ||
                             (planB.RangeOrder == RangeOrder.Close &&
                              currentRange >= initialTurnRange));
                    }
                    requestedOpenA = planA.RangeOrder == RangeOrder.Open;
                    requestedOpenB = planB.RangeOrder == RangeOrder.Open;
                    orderRequests += 2;
                    if (variant.MovementMode == Tl1IntegratedMovementMode.PreferredRange)
                    {
                        preferredRequests += 2;
                    }
                    else
                    {
                        scriptedRequests += 2;
                    }
                    RecordFiniteMovementStatus(
                        sideA, planA, moveA, diagnostics,
                        ref orderCoercions, ref immobileMovementCoercions);
                    RecordFiniteMovementStatus(
                        sideB, planB, moveB, diagnostics,
                        ref orderCoercions, ref immobileMovementCoercions);
                    movementA += moveA.MovementHexes;
                    movementB += moveB.MovementHexes;
                    if (currentRange != initialTurnRange)
                    {
                        rangeChanges++;
                    }
                    minimumRange = Math.Min(
                        minimumRange,
                        Math.Min(moveA.ClosestApproachHexes, moveB.ClosestApproachHexes));
                    maximumRange = Math.Max(
                        maximumRange,
                        Math.Max(moveA.FarthestSeparationHexes, moveB.FarthestSeparationHexes));
                    boundaryTurnsA += tacticalMap!.IsBoundary(coordinateA) ? 1 : 0;
                    boundaryTurnsB += tacticalMap.IsBoundary(coordinateB) ? 1 : 0;
                    previousA = new TacticalPreviousTurnOutcome(
                        planA.RangeOrder,
                        initialTurnRange,
                        currentRange - initialTurnRange);
                    previousB = new TacticalPreviousTurnOutcome(
                        planB.RangeOrder,
                        initialTurnRange,
                        currentRange - initialTurnRange);

                    // Scalar positions remain a compatibility projection for legacy
                    // helpers. CP65 combat geometry and missiles use HexCoord below.
                    positionA = 0;
                    positionB = currentRange;
                    foreach (IntegratedMissile missile in missiles)
                    {
                        HexCoord? oldTarget = missile.LastPlannedTargetCoordinate;
                        HexCoord newTarget = missile.TargetId == "A"
                            ? coordinateA
                            : coordinateB;
                        missileReroutes++;
                        if (oldTarget is HexCoord old && old != newTarget)
                        {
                            targetMovementReroutes++;
                        }
                        missile.LastPlannedTargetCoordinate = newTarget;
                        missile.LastPlannedTargetPosition = missile.TargetId == "A"
                            ? positionA
                            : positionB;
                    }
                }
                else
                {
                    TacticalOrderPlan planA = policyA.ChooseOrders(
                        BuildDecisionContext(
                            turns,
                            currentRange,
                            sideA,
                            sideB,
                            missiles,
                            previousA,
                            variant.MovementMode,
                            variant.SideATrackPolicy,
                            variant.SideANetEwRangePenalty,
                            sensorEnvelopeA));
                    TacticalOrderPlan planB = policyB.ChooseOrders(
                        BuildDecisionContext(
                            turns,
                            currentRange,
                            sideB,
                            sideA,
                            missiles,
                            previousB,
                            variant.MovementMode,
                            variant.SideBTrackPolicy,
                            variant.SideBNetEwRangePenalty,
                            sensorEnvelopeB));
                    requestedOpenA = planA.RangeOrder == RangeOrder.Open;
                    requestedOpenB = planB.RangeOrder == RangeOrder.Open;
                    orderRequests += 2;
                    if (variant.MovementMode == Tl1IntegratedMovementMode.PreferredRange)
                    {
                        preferredRequests += 2;
                    }
                    else
                    {
                        scriptedRequests += 2;
                    }

                    RangeOrderResolution movement = RangeOrderResolver.Resolve(
                        currentRange,
                        BuildTacticalSnapshot(sideA),
                        planA,
                        BuildTacticalSnapshot(sideB),
                        planB);
                    diagnostics.RecordOrderStatus(movement.SideA.Status);
                    diagnostics.RecordOrderStatus(movement.SideB.Status);
                    if (movement.SideA.Status is
                        RangeOrderResolutionStatus.StlUnavailable or
                        RangeOrderResolutionStatus.NoMovementResolved)
                    {
                        orderCoercions++;
                    }
                    if (movement.SideB.Status is
                        RangeOrderResolutionStatus.StlUnavailable or
                        RangeOrderResolutionStatus.NoMovementResolved)
                    {
                        orderCoercions++;
                    }
                    if ((sideA.Ship.GetComponent("stl").Condition is
                            ComponentCondition.Disabled or ComponentCondition.Destroyed) &&
                        planA.RangeOrder != RangeOrder.Hold &&
                        movement.SideA.MovementHexes == 0)
                    {
                        immobileMovementCoercions++;
                    }
                    if ((sideB.Ship.GetComponent("stl").Condition is
                            ComponentCondition.Disabled or ComponentCondition.Destroyed) &&
                        planB.RangeOrder != RangeOrder.Hold &&
                        movement.SideB.MovementHexes == 0)
                    {
                        immobileMovementCoercions++;
                    }

                    int oldPositionA = positionA;
                    int oldPositionB = positionB;
                    positionA += movement.SideADisplacement;
                    positionB += movement.SideBDisplacement;
                    currentRange = movement.FinalRangeHexes;
                    movementA += movement.SideA.MovementHexes;
                    movementB += movement.SideB.MovementHexes;
                    if (movement.RangeChanged)
                    {
                        rangeChanges++;
                    }
                    minimumRange = Math.Min(minimumRange, currentRange);
                    maximumRange = Math.Max(maximumRange, currentRange);
                    previousA = new TacticalPreviousTurnOutcome(
                        planA.RangeOrder,
                        movement.InitialRangeHexes,
                        movement.NetRangeChange);
                    previousB = new TacticalPreviousTurnOutcome(
                        planB.RangeOrder,
                        movement.InitialRangeHexes,
                        movement.NetRangeChange);

                    foreach (IntegratedMissile missile in missiles)
                    {
                        int oldTargetPosition = missile.TargetId == "A"
                            ? oldPositionA
                            : oldPositionB;
                        int newTargetPosition = missile.TargetId == "A"
                            ? positionA
                            : positionB;
                        missileReroutes++;
                        if (oldTargetPosition != newTargetPosition)
                        {
                            targetMovementReroutes++;
                        }
                        missile.LastPlannedTargetPosition = newTargetPosition;
                    }

                }

                // CP95 instrumentation: ordinary direct-fire and launch eligibility use
                // the final post-Movement geometry, not movement-path closest approach.
                // Preserve path closest approach separately in MinimumRange while recording
                // the actual firing-window range reached on each combat turn.
                postMovementFiringWindows++;
                minimumPostMovementRange = Math.Min(minimumPostMovementRange, currentRange);
                bool postMovementReadyA = PostMovementReadyWindowReached(
                    currentRange, variant.SideAMaximumReadyRangeHexes);
                bool postMovementReadyB = PostMovementReadyWindowReached(
                    currentRange, variant.SideBMaximumReadyRangeHexes);
                postMovementReadyWindowsA += postMovementReadyA ? 1 : 0;
                postMovementReadyWindowsB += postMovementReadyB ? 1 : 0;
                postMovementReadyWindowsMutual += postMovementReadyA && postMovementReadyB ? 1 : 0;

                SensorTurnState sensorStateA;
                SensorTurnState sensorStateB;
                IntegratedTrackQuality trackA;
                IntegratedTrackQuality trackB;

                if (studyId == Tl1ReactiveEwSubphaseStudyId ||
                    studyId == Tl1EwAiDoctrineStudyId ||
                    studyId == Tl1ApproximateTrackDegradedFireStudyId ||
                    studyId == Tl1AppliedDegradedFireFamilyCandidateStudyId ||
                    studyId == Tl1DegradedFireEccmValueStudyId ||
                    studyId == Tl2SensorEwDiscriminationIsolationStudyId ||
                    studyId == Tl2EwPowerPressureTallViabilityStudyId ||
                    studyId == Tl2TacticalComputerEwPermutationStudyId ||
                    studyId == Tl2PowerReactorProgressionPermutationStudyId ||
                    studyId == Tl2ShieldCapacityPowerIntegrationStudyId ||
                    studyId == Tl2ArmorApAiShieldIntegrationStudyId ||
                    studyId == Tl2WeaponPenetrationLayeredDefenseStudyId ||
                    studyId == CrossTlBuildPermutationScreeningStudyId ||
                    studyId == CrossTlPowerAwareInformationControlScreeningStudyId ||
                    studyId == CrossTlGeneralizedLegalBuildScreeningStudyId ||
                    studyId == CrossTlMatchedReadinessSpaceScreeningStudyId ||
                    IsAdaptiveEncounterStudy(studyId))
                {
                    // The current reactive-EW studies use the explicit pre-combat EW response window.
                    // Final movement geometry is already authoritative here. Sensors observe
                    // first, both ECM declarations are applied, then ECCM may respond only
                    // when the observable post-ECM track was actually degraded. No initiative
                    // value enters this resolver and there is no second ECM response layer.
                    Tl1OperationalTrackPolicy effectiveTrackPolicyA =
                        adaptiveEncounter && !combatBlackboardA.ContactEstablished
                            ? Tl1OperationalTrackPolicy.PassiveOnly
                            : variant.SideATrackPolicy;
                    Tl1OperationalTrackPolicy effectiveTrackPolicyB =
                        adaptiveEncounter && !combatBlackboardB.ContactEstablished
                            ? Tl1OperationalTrackPolicy.PassiveOnly
                            : variant.SideBTrackPolicy;
                    TacticalObservableStateSignature priorObservableStateA =
                        BuildAdaptiveObservableState(
                            sideA,
                            observableEcmEmissionB,
                            observableActiveSensorEmissionB,
                            variant.SideAEccmNormalRatingOverride ?? 1);
                    TacticalObservableStateSignature priorObservableStateB =
                        BuildAdaptiveObservableState(
                            sideB,
                            observableEcmEmissionA,
                            observableActiveSensorEmissionA,
                            variant.SideBEccmNormalRatingOverride ?? 1);
                    Tl1IntegratedSensorOverloadPolicy effectiveSensorOverloadA =
                        adaptiveEncounter
                            ? AdaptiveSensorOverloadPolicy(
                                sideA, combatBlackboardA, currentRange,
                                closureExhaustedA, priorObservableStateA,
                                variant.SideAEccmNormalRatingOverride ?? 1)
                            : variant.SideASensorOverloadPolicy;
                    Tl1IntegratedSensorOverloadPolicy effectiveSensorOverloadB =
                        adaptiveEncounter
                            ? AdaptiveSensorOverloadPolicy(
                                sideB, combatBlackboardB, currentRange,
                                closureExhaustedB, priorObservableStateB,
                                variant.SideBEccmNormalRatingOverride ?? 1)
                            : variant.SideBSensorOverloadPolicy;

                    sensorStateA = AllocateOperationalSensor(
                        sideA, effectiveTrackPolicyA,
                        variant.SideANetEwRangePenalty, currentRange, sensorEnvelopeA,
                        effectiveSensorOverloadA, diagnostics);
                    sensorStateB = AllocateOperationalSensor(
                        sideB, effectiveTrackPolicyB,
                        variant.SideBNetEwRangePenalty, currentRange, sensorEnvelopeB,
                        effectiveSensorOverloadB, diagnostics);

                    bool doctrineEwA = studyId == Tl1EwAiDoctrineStudyId ||
                        studyId == CrossTlPowerAwareInformationControlScreeningStudyId ||
                        studyId == CrossTlGeneralizedLegalBuildScreeningStudyId ||
                        studyId == CrossTlMatchedReadinessSpaceScreeningStudyId ||
                        IsAdaptiveEncounterStudy(studyId) ||
                        (studyId == Tl1DegradedFireEccmValueStudyId &&
                         !string.IsNullOrWhiteSpace(variant.SideAAiDoctrineId));
                    bool doctrineEwB = studyId == Tl1EwAiDoctrineStudyId ||
                        studyId == CrossTlPowerAwareInformationControlScreeningStudyId ||
                        studyId == CrossTlGeneralizedLegalBuildScreeningStudyId ||
                        studyId == CrossTlMatchedReadinessSpaceScreeningStudyId ||
                        IsAdaptiveEncounterStudy(studyId) ||
                        (studyId == Tl1DegradedFireEccmValueStudyId &&
                         !string.IsNullOrWhiteSpace(variant.SideBAiDoctrineId));
                    int ecmRatingA;
                    int ecmRatingB;
                    if (adaptiveEncounter && !combatBlackboardA.ContactEstablished)
                    {
                        ecmRatingA = 0;
                    }
                    else if (doctrineEwA)
                    {
                        Tl1AiDoctrineDefinitionDocument doctrineA = ResolveAiDoctrine(
                            aiDoctrineRegistry, variant.SideAAiDoctrineId, variant.Id, "A");
                        ecmRatingA = AllocateDoctrineEcm(
                            sideA, sideB, inboundA, doctrineA,
                            variant.SideAEcmNormalPowerCostOverride ?? 1,
                            variant.SideAEccmNormalPowerCostOverride ?? 1,
                            variant.SideAEcmNormalRatingOverride ?? 1,
                            variant.SideAEccmNormalRatingOverride ?? 1,
                            variant.SideAEcmFullStrengthNormalPowerCostOverride,
                            variant.SideAEccmFullStrengthNormalPowerCostOverride, diagnostics);
                    }
                    else
                    {
                        ecmRatingA = AllocateOperationalEcm(
                            sideA, variant.SideAEcmPolicy,
                            variant.SideAEcmNormalPowerCostOverride, diagnostics,
                            normalRating: variant.SideAEcmNormalRatingOverride ?? 1,
                            fullStrengthNormalPowerCostOverride: variant.SideAEcmFullStrengthNormalPowerCostOverride);
                    }
                    if (adaptiveEncounter && !combatBlackboardB.ContactEstablished)
                    {
                        ecmRatingB = 0;
                    }
                    else if (doctrineEwB)
                    {
                        Tl1AiDoctrineDefinitionDocument doctrineB = ResolveAiDoctrine(
                            aiDoctrineRegistry, variant.SideBAiDoctrineId, variant.Id, "B");
                        ecmRatingB = AllocateDoctrineEcm(
                            sideB, sideA, inboundB, doctrineB,
                            variant.SideBEcmNormalPowerCostOverride ?? 1,
                            variant.SideBEccmNormalPowerCostOverride ?? 1,
                            variant.SideBEcmNormalRatingOverride ?? 1,
                            variant.SideBEccmNormalRatingOverride ?? 1,
                            variant.SideBEcmFullStrengthNormalPowerCostOverride,
                            variant.SideBEccmFullStrengthNormalPowerCostOverride, diagnostics);
                    }
                    else
                    {
                        ecmRatingB = AllocateOperationalEcm(
                            sideB, variant.SideBEcmPolicy,
                            variant.SideBEcmNormalPowerCostOverride, diagnostics,
                            normalRating: variant.SideBEcmNormalRatingOverride ?? 1,
                            fullStrengthNormalPowerCostOverride: variant.SideBEcmFullStrengthNormalPowerCostOverride);
                    }

                    SensorEwFoundationProfile ewProfileA = sensorEnvelopeA.ToFoundationProfile();
                    SensorEwFoundationProfile ewProfileB = sensorEnvelopeB.ToFoundationProfile();
                    PreCombatElectronicWarfareTrackPair afterEcm =
                        PreCombatElectronicWarfareResolver.ResolveAfterEcmDeclarations(
                            currentRange,
                            BuildPreCombatEwParticipant(
                                ewProfileA, sensorStateA, ecmRatingA, eccmRating: 0),
                            BuildPreCombatEwParticipant(
                                ewProfileB, sensorStateB, ecmRatingB, eccmRating: 0));

                    int eccmRatingA;
                    int eccmRatingB;
                    if (doctrineEwA)
                    {
                        Tl1AiDoctrineDefinitionDocument doctrineA = ResolveAiDoctrine(
                            aiDoctrineRegistry, variant.SideAAiDoctrineId, variant.Id, "A");
                        eccmRatingA = AllocateDoctrineEccm(
                            sideA, sideB, inboundA, doctrineA,
                            variant.SideAEcmNormalPowerCostOverride ?? 1,
                            variant.SideAEccmNormalPowerCostOverride ?? 1,
                            variant.SideAEcmNormalRatingOverride ?? 1,
                            variant.SideAEccmNormalRatingOverride ?? 1,
                            variant.SideAEcmFullStrengthNormalPowerCostOverride,
                            variant.SideAEccmFullStrengthNormalPowerCostOverride,
                            afterEcm.SideA.EcmDegradedFirm, diagnostics);
                    }
                    else
                    {
                        eccmRatingA = AllocateOperationalEccm(
                            sideA, variant.SideAEccmPolicy,
                            variant.SideAEccmNormalPowerCostOverride,
                            afterEcm.SideA.EcmDegradedFirm, diagnostics,
                            normalRating: variant.SideAEccmNormalRatingOverride ?? 1,
                            fullStrengthNormalPowerCostOverride: variant.SideAEccmFullStrengthNormalPowerCostOverride);
                    }
                    if (doctrineEwB)
                    {
                        Tl1AiDoctrineDefinitionDocument doctrineB = ResolveAiDoctrine(
                            aiDoctrineRegistry, variant.SideBAiDoctrineId, variant.Id, "B");
                        eccmRatingB = AllocateDoctrineEccm(
                            sideB, sideA, inboundB, doctrineB,
                            variant.SideBEcmNormalPowerCostOverride ?? 1,
                            variant.SideBEccmNormalPowerCostOverride ?? 1,
                            variant.SideBEcmNormalRatingOverride ?? 1,
                            variant.SideBEccmNormalRatingOverride ?? 1,
                            variant.SideBEcmFullStrengthNormalPowerCostOverride,
                            variant.SideBEccmFullStrengthNormalPowerCostOverride,
                            afterEcm.SideB.EcmDegradedFirm, diagnostics);
                    }
                    else
                    {
                        eccmRatingB = AllocateOperationalEccm(
                            sideB, variant.SideBEccmPolicy,
                            variant.SideBEccmNormalPowerCostOverride,
                            afterEcm.SideB.EcmDegradedFirm, diagnostics,
                            normalRating: variant.SideBEccmNormalRatingOverride ?? 1,
                            fullStrengthNormalPowerCostOverride: variant.SideBEccmFullStrengthNormalPowerCostOverride);
                    }

                    PreCombatElectronicWarfareTrackPair finalEw =
                        PreCombatElectronicWarfareResolver.ResolveAfterEccmResponses(
                            currentRange,
                            BuildPreCombatEwParticipant(
                                ewProfileA, sensorStateA, ecmRatingA, eccmRatingA),
                            BuildPreCombatEwParticipant(
                                ewProfileB, sensorStateB, ecmRatingB, eccmRatingB));

                    bool eccmOverloadActivatedA = false;
                    bool eccmOverloadActivatedB = false;
                    if (adaptiveEncounter)
                    {
                        TacticalObservableStateSignature currentObservableStateA =
                            BuildAdaptiveObservableState(
                                sideA, ecmRatingB > 0, sensorStateB.ActivePower > 0,
                                variant.SideAEccmNormalRatingOverride ?? 1);
                        TacticalObservableStateSignature currentObservableStateB =
                            BuildAdaptiveObservableState(
                                sideB, ecmRatingA > 0, sensorStateA.ActivePower > 0,
                                variant.SideBEccmNormalRatingOverride ?? 1);
                        if (finalEw.SideA.FinalTrack != SensorEwFoundationTrackState.Firm &&
                            closureExhaustedA && afterEcm.SideA.EcmDegradedFirm)
                        {
                            AdaptiveEccmOverloadResult escalated =
                                TryAdaptiveEccmOverload(
                                    sideA, eccmRatingA, currentRange,
                                    combatBlackboardA, currentObservableStateA,
                                    variant.SideAEccmNormalRatingOverride ?? 1,
                                    diagnostics);
                            eccmRatingA = escalated.Rating;
                            eccmOverloadActivatedA = escalated.Activated;
                        }
                        if (finalEw.SideB.FinalTrack != SensorEwFoundationTrackState.Firm &&
                            closureExhaustedB && afterEcm.SideB.EcmDegradedFirm)
                        {
                            AdaptiveEccmOverloadResult escalated =
                                TryAdaptiveEccmOverload(
                                    sideB, eccmRatingB, currentRange,
                                    combatBlackboardB, currentObservableStateB,
                                    variant.SideBEccmNormalRatingOverride ?? 1,
                                    diagnostics);
                            eccmRatingB = escalated.Rating;
                            eccmOverloadActivatedB = escalated.Activated;
                        }
                        if (eccmOverloadActivatedA || eccmOverloadActivatedB)
                        {
                            finalEw = PreCombatElectronicWarfareResolver.ResolveAfterEccmResponses(
                                currentRange,
                                BuildPreCombatEwParticipant(
                                    ewProfileA, sensorStateA, ecmRatingA, eccmRatingA),
                                BuildPreCombatEwParticipant(
                                    ewProfileB, sensorStateB, ecmRatingB, eccmRatingB));
                        }
                    }

                    trackA = ToIntegratedTrackQuality(finalEw.SideA.FinalTrack);
                    trackB = ToIntegratedTrackQuality(finalEw.SideB.FinalTrack);
                    if (adaptiveEncounter)
                    {
                        observableEcmEmissionA = ecmRatingA > 0;
                        observableEcmEmissionB = ecmRatingB > 0;
                        observableActiveSensorEmissionA = sensorStateA.ActivePower > 0;
                        observableActiveSensorEmissionB = sensorStateB.ActivePower > 0;
                        if (trackA != IntegratedTrackQuality.None ||
                            observableEcmEmissionB || observableActiveSensorEmissionB)
                        {
                            combatBlackboardA.EstablishContact(turns);
                        }
                        if (trackB != IntegratedTrackQuality.None ||
                            observableEcmEmissionA || observableActiveSensorEmissionA)
                        {
                            combatBlackboardB.EstablishContact(turns);
                        }

                        TacticalObservableStateSignature currentObservableStateA =
                            BuildAdaptiveObservableState(
                                sideA, observableEcmEmissionB, observableActiveSensorEmissionB,
                                variant.SideAEccmNormalRatingOverride ?? 1);
                        TacticalObservableStateSignature currentObservableStateB =
                            BuildAdaptiveObservableState(
                                sideB, observableEcmEmissionA, observableActiveSensorEmissionA,
                                variant.SideBEccmNormalRatingOverride ?? 1);
                        if (eccmOverloadActivatedA && trackA != IntegratedTrackQuality.Firm)
                        {
                            combatBlackboardA.RecordOverloadFailure(
                                TacticalEscalationKind.EccmOverload,
                                currentRange,
                                currentObservableStateA);
                        }
                        if (eccmOverloadActivatedB && trackB != IntegratedTrackQuality.Firm)
                        {
                            combatBlackboardB.RecordOverloadFailure(
                                TacticalEscalationKind.EccmOverload,
                                currentRange,
                                currentObservableStateB);
                        }
                        if (sensorStateA.Overloaded && trackA != IntegratedTrackQuality.Firm)
                        {
                            combatBlackboardA.RecordOverloadFailure(
                                TacticalEscalationKind.ActiveSensorOverload,
                                currentRange,
                                currentObservableStateA);
                        }
                        if (sensorStateB.Overloaded && trackB != IntegratedTrackQuality.Firm)
                        {
                            combatBlackboardB.RecordOverloadFailure(
                                TacticalEscalationKind.ActiveSensorOverload,
                                currentRange,
                                currentObservableStateB);
                        }
                        if (combatBlackboardA.ContactEstablished)
                        {
                            combatBlackboardA.RecordTrackObservation(
                                currentRange,
                                ToPlayerTrackQuality(trackA),
                                observableEcmEmissionB,
                                observableActiveSensorEmissionB,
                                afterEcm.SideA.EcmDegradedFirm);
                        }
                        if (combatBlackboardB.ContactEstablished)
                        {
                            combatBlackboardB.RecordTrackObservation(
                                currentRange,
                                ToPlayerTrackQuality(trackB),
                                observableEcmEmissionA,
                                observableActiveSensorEmissionA,
                                afterEcm.SideB.EcmDegradedFirm);
                        }
                    }

                    // EW owns the post-Movement response window. Defensive/combat systems
                    // allocate only after final track quality is established, so TP left
                    // uncommitted before EW can be spent reactively without double spending.
                    systemsA = AllocateDefensiveSystems(sideA, sideB, inboundA);
                    systemsB = AllocateDefensiveSystems(sideB, sideA, inboundB);
                }
                else
                {
                    // Preserve the frozen historical ordering and telemetry semantics for
                    // older frozen studies so their archived evidence stays reproducible.
                    bool explicitEwCounterplay =
                        studyId == Tl1BilateralOverloadCounterplayStudyId ||
                        studyId == Tl1SensorEwCandidateCombatStudyId ||
                        studyId == Tl1EcmPowerCostCounterplayStudyId ||
                        studyId == Tl1SensorDiscriminationBurnthroughStudyId;
                    EwTurnState ewStateA = explicitEwCounterplay
                        ? AllocateOperationalEw(
                            sideA, variant.SideAEcmPolicy, variant.SideAEccmPolicy,
                            variant.SideAEcmNormalPowerCostOverride,
                            variant.SideAEccmNormalPowerCostOverride,
                            diagnostics,
                            ecmNormalRating: variant.SideAEcmNormalRatingOverride ?? 1,
                            eccmNormalRating: variant.SideAEccmNormalRatingOverride ?? 1)
                        : EwTurnState.Inactive;
                    EwTurnState ewStateB = explicitEwCounterplay
                        ? AllocateOperationalEw(
                            sideB, variant.SideBEcmPolicy, variant.SideBEccmPolicy,
                            variant.SideBEcmNormalPowerCostOverride,
                            variant.SideBEccmNormalPowerCostOverride,
                            diagnostics,
                            ecmNormalRating: variant.SideBEcmNormalRatingOverride ?? 1,
                            eccmNormalRating: variant.SideBEccmNormalRatingOverride ?? 1)
                        : EwTurnState.Inactive;
                    int effectiveEwPenaltyA = sensorEnvelopeA.CausalEwResolution
                        ? variant.SideANetEwRangePenalty
                        : checked(variant.SideANetEwRangePenalty +
                            Math.Max(0, ewStateB.EcmRating - ewStateA.EccmRating));
                    int effectiveEwPenaltyB = sensorEnvelopeB.CausalEwResolution
                        ? variant.SideBNetEwRangePenalty
                        : checked(variant.SideBNetEwRangePenalty +
                            Math.Max(0, ewStateA.EcmRating - ewStateB.EccmRating));

                    sensorStateA = operationalSensorStudy
                        ? AllocateOperationalSensor(
                            sideA, variant.SideATrackPolicy,
                            effectiveEwPenaltyA, currentRange, sensorEnvelopeA,
                            variant.SideASensorOverloadPolicy, diagnostics)
                        : EstablishedFirmSensorState(sensorEnvelopeA);
                    sensorStateB = operationalSensorStudy
                        ? AllocateOperationalSensor(
                            sideB, variant.SideBTrackPolicy,
                            effectiveEwPenaltyB, currentRange, sensorEnvelopeB,
                            variant.SideBSensorOverloadPolicy, diagnostics)
                        : EstablishedFirmSensorState(sensorEnvelopeB);
                    if (operationalSensorStudy)
                    {
                        systemsA = AllocateDefensiveSystems(sideA, sideB, inboundA);
                        systemsB = AllocateDefensiveSystems(sideB, sideA, inboundB);
                    }
                    trackA = sensorEnvelopeA.CausalEwResolution
                        ? ResolveFoundationTrackQuality(
                            sensorEnvelopeA, sensorEnvelopeB, sensorStateA, sensorStateB,
                            ewStateA, ewStateB, currentRange)
                        : ResolveTrackQuality(sensorStateA, currentRange);
                    trackB = sensorEnvelopeB.CausalEwResolution
                        ? ResolveFoundationTrackQuality(
                            sensorEnvelopeB, sensorEnvelopeA, sensorStateB, sensorStateA,
                            ewStateB, ewStateA, currentRange)
                        : ResolveTrackQuality(sensorStateB, currentRange);
                }
                diagnostics.RecordSensorEvaluation("A", sensorStateA, trackA);
                diagnostics.RecordSensorEvaluation("B", sensorStateB, trackB);

                DirectCommit directA = CommitDirectAttack(
                    sideA,
                    sideB,
                    currentRange,
                    systemsA.EvasiveActive,
                    systemsB.EvasiveActive,
                    snapshotB,
                    attackRandom.NextD100(),
                    trackQuality: trackA,
                    allowsApproximateTrackFire: variant.SideAAllowsApproximateDirectFire,
                    tacticalComputerApproximateTrackAccuracyPenalty: variant.SideAApproximateDirectFireAccuracyPenalty);
                DirectCommit directB = CommitDirectAttack(
                    sideB,
                    sideA,
                    currentRange,
                    systemsB.EvasiveActive,
                    systemsA.EvasiveActive,
                    snapshotA,
                    attackRandom.NextD100(),
                    trackQuality: trackB,
                    allowsApproximateTrackFire: variant.SideBAllowsApproximateDirectFire,
                    tacticalComputerApproximateTrackAccuracyPenalty: variant.SideBApproximateDirectFireAccuracyPenalty);
                DirectCommit secondaryDirectA = sideA.HasSecondaryWeapon &&
                        sideA.SecondaryFamily != WeaponFamily.Missile
                    ? CommitDirectAttack(
                        sideA,
                        sideB,
                        currentRange,
                        systemsA.EvasiveActive,
                        systemsB.EvasiveActive,
                        snapshotB,
                        attackRandom.NextD100(),
                        secondary: true,
                        trackQuality: trackA,
                        allowsApproximateTrackFire: variant.SideAAllowsApproximateDirectFire,
                        tacticalComputerApproximateTrackAccuracyPenalty: variant.SideAApproximateDirectFireAccuracyPenalty)
                    : DirectCommit.None;
                DirectCommit secondaryDirectB = sideB.HasSecondaryWeapon &&
                        sideB.SecondaryFamily != WeaponFamily.Missile
                    ? CommitDirectAttack(
                        sideB,
                        sideA,
                        currentRange,
                        systemsB.EvasiveActive,
                        systemsA.EvasiveActive,
                        snapshotA,
                        attackRandom.NextD100(),
                        secondary: true,
                        trackQuality: trackB,
                        allowsApproximateTrackFire: variant.SideBAllowsApproximateDirectFire,
                        tacticalComputerApproximateTrackAccuracyPenalty: variant.SideBApproximateDirectFireAccuracyPenalty)
                    : DirectCommit.None;
                diagnostics.RecordDirectAction("A", directA);
                diagnostics.RecordDirectAction("B", directB);
                diagnostics.RecordDirectAction("A", secondaryDirectA);
                diagnostics.RecordDirectAction("B", secondaryDirectB);
                foreach (DirectCommit commitment in new[]
                    { directA, directB, secondaryDirectA, secondaryDirectB })
                {
                    if (commitment.Fired && commitment.TargetMobilityBonus > 0)
                    {
                        immobileBonusAttacks++;
                    }
                }
                if ((!snapshotB.IsImmobile &&
                        (directA.TargetMobilityBonus != 0 ||
                         secondaryDirectA.TargetMobilityBonus != 0)) ||
                    (!snapshotA.IsImmobile &&
                        (directB.TargetMobilityBonus != 0 ||
                         secondaryDirectB.TargetMobilityBonus != 0)))
                {
                    sameTurnImmobileBonusViolations++;
                }

                MissileLaunchCommit launchA = CommitMissileLaunch(
                    sideA,
                    sideB,
                    positionA,
                    positionB,
                    missiles,
                    hasFirmTrack: trackA == IntegratedTrackQuality.Firm,
                    attackerCoordinate: finiteTacticalMap ? coordinateA : null,
                    targetCoordinate: finiteTacticalMap ? coordinateB : null);
                MissileLaunchCommit launchB = CommitMissileLaunch(
                    sideB,
                    sideA,
                    positionB,
                    positionA,
                    missiles,
                    hasFirmTrack: trackB == IntegratedTrackQuality.Firm,
                    attackerCoordinate: finiteTacticalMap ? coordinateB : null,
                    targetCoordinate: finiteTacticalMap ? coordinateA : null);
                MissileLaunchCommit secondaryLaunchA =
                    sideA.HasSecondaryWeapon &&
                    sideA.SecondaryFamily == WeaponFamily.Missile
                        ? CommitMissileLaunch(
                            sideA,
                            sideB,
                            positionA,
                            positionB,
                            missiles,
                            secondary: true,
                            hasFirmTrack: trackA == IntegratedTrackQuality.Firm,
                            attackerCoordinate: finiteTacticalMap ? coordinateA : null,
                            targetCoordinate: finiteTacticalMap ? coordinateB : null)
                        : MissileLaunchCommit.None;
                MissileLaunchCommit secondaryLaunchB =
                    sideB.HasSecondaryWeapon &&
                    sideB.SecondaryFamily == WeaponFamily.Missile
                        ? CommitMissileLaunch(
                            sideB,
                            sideA,
                            positionB,
                            positionA,
                            missiles,
                            secondary: true,
                            hasFirmTrack: trackB == IntegratedTrackQuality.Firm,
                            attackerCoordinate: finiteTacticalMap ? coordinateB : null,
                            targetCoordinate: finiteTacticalMap ? coordinateA : null)
                        : MissileLaunchCommit.None;
                diagnostics.RecordMissileLaunch("A", launchA);
                diagnostics.RecordMissileLaunch("B", launchB);
                diagnostics.RecordMissileLaunch("A", secondaryLaunchA);
                diagnostics.RecordMissileLaunch("B", secondaryLaunchB);
                missileLaunches += launchA.Launched ? 1 : 0;
                missileLaunches += launchB.Launched ? 1 : 0;
                missileLaunches += secondaryLaunchA.Launched ? 1 : 0;
                missileLaunches += secondaryLaunchB.Launched ? 1 : 0;

                if (adaptiveEncounter)
                {
                    bool actionA = directA.Fired || secondaryDirectA.Fired ||
                        launchA.Launched || secondaryLaunchA.Launched;
                    bool actionB = directB.Fired || secondaryDirectB.Fired ||
                        launchB.Launched || secondaryLaunchB.Launched;
                    if (actionA)
                    {
                        combatBlackboardA.RecordOwnAttack(currentRange);
                        combatBlackboardB.EstablishContact(turns);
                        combatBlackboardB.RecordObservedOpponentAttack(currentRange);
                    }
                    if (actionB)
                    {
                        combatBlackboardB.RecordOwnAttack(currentRange);
                        combatBlackboardA.EstablishContact(turns);
                        combatBlackboardA.RecordObservedOpponentAttack(currentRange);
                    }
                }

                DamageApplication damageToB = ApplyDirectAttack(directA, sideB);
                DamageApplication secondaryDamageToB = ApplyDirectAttack(
                    secondaryDirectA, sideB);
                DamageApplication damageToA = ApplyDirectAttack(directB, sideA);
                DamageApplication secondaryDamageToA = ApplyDirectAttack(
                    secondaryDirectB, sideA);
                diagnostics.RecordDamage(damageToA);
                diagnostics.RecordDamage(damageToB);
                diagnostics.RecordDamage(secondaryDamageToA);
                diagnostics.RecordDamage(secondaryDamageToB);
                RecordDamage(
                    turns,
                    damageToA,
                    damageToB,
                    ref criticalSelections,
                    ref firstCriticalTurn,
                    ref firstConsequentialTurn,
                    ref mobilityLossObserved,
                    ref sameTurnImmobileBonusViolations,
                    directA,
                    directB);
                RecordDamage(
                    turns,
                    secondaryDamageToA,
                    secondaryDamageToB,
                    ref criticalSelections,
                    ref firstCriticalTurn,
                    ref firstConsequentialTurn,
                    ref mobilityLossObserved,
                    ref sameTurnImmobileBonusViolations,
                    secondaryDirectA,
                    secondaryDirectB);
            }

            if (operationalSensorStudy && terminalFlightOnly)
            {
                systemsA = AllocateDefensiveSystems(sideA, sideB, inboundA);
                systemsB = AllocateDefensiveSystems(sideB, sideA, inboundB);
            }

            MissileTurnResult missileResult = AdvanceMissiles(
                missiles,
                sideA,
                sideB,
                positionA,
                positionB,
                snapshotA,
                snapshotB,
                systemsA,
                systemsB,
                pdsRandom,
                attackRandom,
                diagnostics,
                finiteTacticalMap ? tacticalMap : null,
                finiteTacticalMap ? coordinateA : null,
                finiteTacticalMap ? coordinateB : null);
            missileDistanceTraveled += missileResult.DistanceTraveled;
            maximumObservedMissileDistance = Math.Max(
                maximumObservedMissileDistance,
                missileResult.MaximumObservedDistanceTraveled);
            missileTerminalAttacks += missileResult.TerminalAttacks;
            missileHits += missileResult.Hits;
            missilesRangeExhausted += missileResult.RangeExhausted;
            pdsAttempts += missileResult.PdsAttempts;
            pdsIntercepts += missileResult.PdsIntercepts;
            immobileBonusAttacks += missileResult.ImmobileBonusAttacks;
            sameTurnImmobileBonusViolations +=
                missileResult.SameTurnImmobileBonusViolations;
            criticalSelections += missileResult.CriticalSelections;
            if (missileResult.CriticalSelections > 0)
            {
                firstCriticalTurn ??= turns;
            }
            if (missileResult.ConsequentialConditionSteps > 0)
            {
                firstConsequentialTurn ??= turns;
            }
            mobilityLossObserved |= missileResult.MobilityLossObserved;

            bool destroyedA = sideA.Ship.IsPendingDestruction ||
                sideA.Ship.Defense.CurrentHull == 0;
            bool destroyedB = sideB.Ship.IsPendingDestruction ||
                sideB.Ship.Defense.CurrentHull == 0;
            if (destroyedA)
            {
                sideA.Ship.CompleteDamagePhase();
            }
            if (destroyedB)
            {
                sideB.Ship.CompleteDamagePhase();
            }

            if (!terminalFlightOnly && !destroyedA && !destroyedB &&
                variant.DamageControl ==
                    Tl1IntegratedDamageControlMode.ComponentFirstReserveOne)
            {
                DamageControlTurnResult dcA = AttemptDamageControl(
                    sideA,
                    repairRandomA);
                DamageControlTurnResult dcB = AttemptDamageControl(
                    sideB,
                    repairRandomB);
                repairAttempts += dcA.Attempts + dcB.Attempts;
                invalidRepairAttempts += dcA.InvalidAttempts + dcB.InvalidAttempts;
            }

            if (!terminalFlightOnly)
            {
                UpdateDisengagementProgress(
                    profile,
                    sideA,
                    sideB,
                    currentRange,
                    positionA,
                    variant.MovementMode == Tl1IntegratedMovementMode.ScriptedPursuit &&
                        sideA.Id == "B",
                    requestedOpenA,
                    missiles,
                    ref disengagementProgressA);
                UpdateDisengagementProgress(
                    profile,
                    sideB,
                    sideA,
                    currentRange,
                    positionB,
                    variant.MovementMode == Tl1IntegratedMovementMode.ScriptedPursuit &&
                        sideB.Id == "B",
                    requestedOpenB,
                    missiles,
                    ref disengagementProgressB);
                TerminalAssessment terminal = AssessTerminal(
                    sideA,
                    sideB,
                    currentRange,
                    disengagementProgressA,
                    disengagementProgressB);
                if (terminal.IsTerminal)
                {
                    winner = terminal.Winner;
                    resolutionCause = terminal.Cause;
                    terminalFlightOnly = true;
                }
            }
            else
            {
                TerminalAssessment terminal = AssessTerminal(
                    sideA,
                    sideB,
                    currentRange,
                    disengagementProgressA,
                    disengagementProgressB);
                if (terminal.IsTerminal)
                {
                    winner = terminal.Winner;
                    resolutionCause = StrongerCause(
                        resolutionCause,
                        terminal.Cause);
                }
            }

            if (terminalFlightOnly && missiles.Count == 0)
            {
                break;
            }
        }

        if (!terminalFlightOnly)
        {
            TerminalAssessment terminal = AssessTerminal(
                sideA,
                sideB,
                currentRange,
                disengagementProgressA,
                disengagementProgressB);
            if (terminal.IsTerminal)
            {
                winner = terminal.Winner;
                resolutionCause = terminal.Cause;
            }
        }

        return new IntegratedTrialOutcome(
            turns,
            winner,
            resolutionCause,
            turns > LongCombatThreshold,
            currentRange,
            minimumRange,
            maximumRange,
            minimumPostMovementRange == int.MaxValue ? currentRange : minimumPostMovementRange,
            postMovementFiringWindows,
            postMovementReadyWindowsA,
            postMovementReadyWindowsB,
            postMovementReadyWindowsMutual,
            rangeChanges,
            orderRequests,
            orderCoercions,
            scriptedRequests,
            preferredRequests,
            movementA,
            movementB,
            fuelRules.StartingFuel - fuelA,
            fuelRules.StartingFuel - fuelB,
            fuelA,
            fuelB,
            boundaryTurnsA,
            boundaryTurnsB,
            immobileMovementCoercions,
            missileReroutes,
            targetMovementReroutes,
            missileDistanceTraveled,
            maximumObservedMissileDistance,
            missileLaunches,
            missileTerminalAttacks,
            missileHits,
            missilesRangeExhausted,
            pdsAttempts,
            pdsIntercepts,
            immobileBonusAttacks,
            sameTurnImmobileBonusViolations,
            criticalSelections,
            firstCriticalTurn,
            firstConsequentialTurn,
            mobilityLossObserved,
            repairAttempts,
            repairActivations,
            invalidRepairAttempts,
            sideA.Ship.DamageControl.RepairKitsRemaining +
                sideB.Ship.DamageControl.RepairKitsRemaining,
            sideA.Ship.Defense.CurrentHull + sideB.Ship.Defense.CurrentHull,
            diagnostics);
    }
    private static void UpdateAdaptiveEncounterContact(
        int turnNumber,
        int currentRange,
        Tl1SensorEnvelope observerEnvelope,
        bool targetEcmEmissionObserved,
        bool targetActiveSensorEmissionObserved,
        TacticalCombatBlackboard blackboard)
    {
        if (blackboard.ContactEstablished)
        {
            return;
        }
        if (targetEcmEmissionObserved || targetActiveSensorEmissionObserved ||
            currentRange <= observerEnvelope.PassiveApproximateRange)
        {
            blackboard.EstablishContact(turnNumber);
        }
    }

    private static TacticalOrderPlan ChooseEncounterOrders(
        ITacticalOrderPolicy policy,
        TacticalDecisionContext context,
        bool adaptiveEncounter,
        TacticalCombatBlackboard blackboard)
    {
        if (adaptiveEncounter && !blackboard.ContactEstablished)
        {
            return new TacticalOrderPlan(
                RangeOrder.Close,
                "No target contact: execute deterministic one-hex search movement toward the system center.");
        }
        return policy.ChooseOrders(context);
    }

    private static FiniteTacticalMove ResolveEncounterMovement(
        HexMap map,
        HexCoord origin,
        HexCoord actualTarget,
        int availableMovementHexes,
        TacticalOrderPlan plan,
        bool searchingWithoutContact,
        HexCoord tieBreakReference)
    {
        if (!searchingWithoutContact)
        {
            return FiniteTacticalMovementResolver.Resolve(
                map, origin, actualTarget, availableMovementHexes, plan, tieBreakReference);
        }

        EncounterSearchMove search = EncounterSearchMovementResolver.ResolveTowardCenter(
            map, origin, availableMovementHexes);
        int closest = search.Path.Min(cell => cell.DistanceTo(actualTarget));
        int farthest = search.Path.Max(cell => cell.DistanceTo(actualTarget));
        return new FiniteTacticalMove(
            search.Origin,
            search.Destination,
            search.Path,
            search.Destination.DistanceTo(actualTarget),
            closest,
            farthest,
            search.MovementHexes,
            search.EndedOnBoundary,
            plan.RangeOrder,
            plan.DesiredRangeHexes);
    }

    private static (HexCoord SideA, HexCoord SideB) InitialFiniteCoordinates(
        HexMap map,
        int initialRange)
    {
        ArgumentNullException.ThrowIfNull(map);
        if (initialRange < 0 || initialRange > map.Radius * 2)
        {
            throw new ArgumentOutOfRangeException(nameof(initialRange));
        }

        int left = initialRange / 2;
        int right = initialRange - left;
        var sideA = new HexCoord(-left, 0);
        var sideB = new HexCoord(right, 0);
        if (!map.Contains(sideA) || !map.Contains(sideB) ||
            sideA.DistanceTo(sideB) != initialRange)
        {
            throw new InvalidOperationException(
                "Unable to place the bilateral study at the requested initial range.");
        }
        return (sideA, sideB);
    }

    private static void RecordFiniteMovementStatus(
        IntegratedSide side,
        TacticalOrderPlan plan,
        FiniteTacticalMove move,
        IntegratedDiagnosticTelemetry diagnostics,
        ref int orderCoercions,
        ref int immobileMovementCoercions)
    {
        bool stlUnavailable = side.Ship.GetComponent("stl").Condition is
            ComponentCondition.Disabled or ComponentCondition.Destroyed;
        RangeOrderResolutionStatus status = stlUnavailable &&
                plan.RangeOrder != RangeOrder.Hold
            ? RangeOrderResolutionStatus.StlUnavailable
            : move.MovementHexes == 0
                ? RangeOrderResolutionStatus.NoMovementRequired
                : RangeOrderResolutionStatus.Executed;
        diagnostics.RecordOrderStatus(status);
        if (status == RangeOrderResolutionStatus.StlUnavailable)
        {
            orderCoercions++;
            immobileMovementCoercions++;
        }
    }

    private static int BeginSideTurn(
        IntegratedSide side,
        IntegratedDiagnosticTelemetry diagnostics)
    {
        if (side.Ship.IsDestroyed)
        {
            side.PdsAttemptsThisTurn = 0;
            return 0;
        }
        int activations = side.Ship.PendingRepairs.Count;
        side.Ship.ApplyPendingRepairsAtTurnRefresh();
        side.Ship.BeginTurn();
        ResetPoweredDefenseAuxiliary(side);
        SynchronizeSelectedAuxiliaryState(side);
        side.RecycleThisTurn = side.RecycleNextTurn;
        side.RecycleNextTurn = false;
        side.SecondaryRecycleThisTurn = side.SecondaryRecycleNextTurn;
        side.SecondaryRecycleNextTurn = false;
        side.Power.BeginTurn(CurrentReactorOutput(side));
        PrepareAuxiliaryPower(side);
        CommitPoweredDefenseAuxiliary(side);
        if (side.Profile.BaseShieldRechargeEnabled)
        {
            bool selectedAuxiliaryFunctional =
                SelectedAuxiliaryFunctional(side);
            int tacticalRate = selectedAuxiliaryFunctional &&
                    side.Auxiliary.HasShieldStabilizer
                ? side.Auxiliary.ShieldRechargePerPower
                : 1;
            int tacticalCap = selectedAuxiliaryFunctional &&
                    side.Auxiliary.HasShieldStabilizer
                ? side.Auxiliary.ShieldRechargePowerCap
                : 2;
            bool flexiblePowerAux = !side.Auxiliary.LegacyIntegratedSuite &&
                ((selectedAuxiliaryFunctional &&
                    (side.Auxiliary.HasCombatBattery ||
                     side.Auxiliary.HasPowerCapacitor)) ||
                    side.Auxiliary.HasAuxiliaryReactor);
            int requestedTacticalPower = side.Ship.Defense.CurrentShieldCapacity <
                    side.Ship.Defense.EffectiveShieldMaximum &&
                side.Power.SpendablePower > 0 &&
                ((selectedAuxiliaryFunctional &&
                    side.Auxiliary.HasShieldStabilizer) || flexiblePowerAux)
                    ? Math.Min(1, tacticalCap)
                    : 0;
            var shieldRechargeProfile = new ShieldRechargeProfile(
                operationalBaseRecharge: side.Technology.ShieldBaseRecharge,
                tacticalRechargePerPower: tacticalRate,
                operationalTacticalPowerCap: tacticalCap,
                degradedBaseRecharge: 0,
                degradedTacticalPowerCap: Math.Min(1, tacticalCap));
            ShieldRechargeResult recharge = ShieldRechargeService.ApplyTurnStart(
                side.Ship.Defense,
                side.Ship.GetComponent("shield-generator").Condition,
                shieldRechargeProfile,
                side.Power,
                requestedTacticalPower);
            diagnostics.RecordShieldRecharge(
                side.Id, recharge, requestedTacticalPower > 0, deniedByReserve: false);
        }
        if (side.Auxiliary.HasShieldBattery &&
            SelectedAuxiliaryFunctional(side) &&
            side.ShieldBatteryChargesRemaining > 0 &&
            side.Ship.Defense.CurrentShieldCapacity <
                side.Ship.Defense.EffectiveShieldMaximum)
        {
            int restored = side.Ship.Defense.RestoreShields(
                side.Auxiliary.ShieldBatteryRestore);
            if (restored > 0)
            {
                side.ShieldBatteryChargesRemaining--;
                side.AuxiliaryShieldRestored += restored;
                diagnostics.TacticalShieldRestored += restored;
            }
        }
        if (side.Ship.Defense.CurrentShieldCapacity == 0)
        {
            diagnostics.ShieldlessShipTurns++;
        }
        side.PdsAttemptsThisTurn = 0;
        return activations;
    }

    private static int BeginSideTurnStateful(
        IntegratedSide side,
        IntegratedSide opponent,
        bool hasInboundMissile,
        IntegratedDiagnosticTelemetry diagnostics)
    {
        if (side.Ship.IsDestroyed)
        {
            side.PdsAttemptsThisTurn = 0;
            return 0;
        }

        int activations = side.Ship.PendingRepairs.Count;
        side.Ship.ApplyPendingRepairsAtTurnRefresh();
        side.Ship.BeginTurn();
        ResetPoweredDefenseAuxiliary(side);
        SynchronizeSelectedAuxiliaryState(side);
        side.RecycleThisTurn = side.RecycleNextTurn;
        side.RecycleNextTurn = false;
        side.SecondaryRecycleThisTurn = side.SecondaryRecycleNextTurn;
        side.SecondaryRecycleNextTurn = false;
        side.Power.BeginTurn(CurrentReactorOutput(side));
        int backgroundCommitment = Math.Min(
            side.BackgroundTacticalPowerCommitment,
            side.Power.SpendablePower);
        if (backgroundCommitment > 0)
        {
            side.Power.IncreasePoweredSystem(
                "checkpoint-53-background-tactical-load",
                backgroundCommitment);
        }
        side.StatefulCombatBattery?.BeginTurn();
        side.StatefulCapacitor?.BeginTurn();
        foreach (IndependentCombatBatteryInstallation battery in side.IndependentCombatBatteries)
        {
            battery.State.BeginTurn();
        }
        foreach (IndependentCapacitorInstallation capacitor in side.IndependentCapacitors)
        {
            capacitor.State.BeginTurn();
        }

        bool selectedAuxiliaryFunctional = SelectedAuxiliaryFunctional(side);
        int plannedPdsPower = PlannedPdsPower(
            side, opponent, hasInboundMissile);
        int plannedEvasivePower = PlannedEvasivePower(side);
        int plannedAttackPower = ReadyAttackPowerCost(side);
        int plannedPoweredDefensePower = PlannedPoweredDefensePower(side);
        int plannedTacticalRechargePower =
            side.Profile.BaseShieldRechargeEnabled &&
            ShieldCanRecharge(side) &&
            ShieldNeedsTacticalRechargeAfterBase(side)
                ? 1
                : 0;
        int plannedPackagePower = plannedPdsPower + plannedEvasivePower +
            plannedAttackPower + plannedPoweredDefensePower +
            plannedTacticalRechargePower;

        if (selectedAuxiliaryFunctional &&
            side.Power.SpendablePower < plannedPackagePower)
        {
            if (side.Auxiliary.HasIndependentPowerComponents)
            {
                DischargeIndependentAuxiliaryPower(
                    side, plannedPackagePower);
            }
            else if (side.StatefulCombatBattery is { CurrentCharges: > 0 } battery)
            {
                int discharged = battery.Discharge(side.Power);
                side.AuxiliaryPowerDischarged += discharged;
            }
            else if (side.StatefulCapacitor is { StoredPower: > 0 } capacitor)
            {
                int discharged = capacitor.Discharge(side.Power, 1);
                side.AuxiliaryPowerDischarged += discharged;
            }
        }

        CommitPoweredDefenseAuxiliary(side);

        if (side.Profile.BaseShieldRechargeEnabled)
        {
            int tacticalRate = selectedAuxiliaryFunctional &&
                    side.Auxiliary.HasShieldStabilizer
                ? side.Auxiliary.ShieldRechargePerPower
                : 1;
            int tacticalCap = selectedAuxiliaryFunctional &&
                    side.Auxiliary.HasShieldStabilizer
                ? side.Auxiliary.ShieldRechargePowerCap
                : 2;
            int reserveAfterRecharge = plannedPdsPower +
                plannedEvasivePower + plannedAttackPower;
            bool tacticalRechargeOpportunity = ShieldCanRecharge(side) &&
                ShieldNeedsTacticalRechargeAfterBase(side);
            bool tacticalRechargeDeniedByReserve = tacticalRechargeOpportunity &&
                side.Power.SpendablePower <= reserveAfterRecharge;
            int requestedTacticalPower = tacticalRechargeOpportunity &&
                !tacticalRechargeDeniedByReserve
                    ? Math.Min(1, tacticalCap)
                    : 0;
            var shieldRechargeProfile = new ShieldRechargeProfile(
                operationalBaseRecharge: side.Technology.ShieldBaseRecharge,
                tacticalRechargePerPower: tacticalRate,
                operationalTacticalPowerCap: tacticalCap,
                degradedBaseRecharge: 0,
                degradedTacticalPowerCap: Math.Min(1, tacticalCap));
            ShieldRechargeResult recharge = ShieldRechargeService.ApplyTurnStart(
                side.Ship.Defense,
                side.Ship.GetComponent("shield-generator").Condition,
                shieldRechargeProfile,
                side.Power,
                requestedTacticalPower);
            diagnostics.RecordShieldRecharge(
                side.Id, recharge, tacticalRechargeOpportunity,
                tacticalRechargeDeniedByReserve);
        }

        if (side.Auxiliary.HasIndependentPowerComponents &&
            selectedAuxiliaryFunctional)
        {
            RechargeIndependentCapacitors(
                side, plannedPdsPower + plannedEvasivePower + plannedAttackPower +
                    plannedPoweredDefensePower);
        }
        else if (side.StatefulCapacitor is { StoredPower: 0 } emptyCapacitor &&
            selectedAuxiliaryFunctional &&
            !emptyCapacitor.OperationUsedThisTurn &&
            side.Auxiliary.CapacitorChargeRate > 0)
        {
            int reserveAfterCharge = plannedPdsPower +
                plannedEvasivePower + plannedAttackPower +
                plannedPoweredDefensePower;
            if (side.Power.SpendablePower > reserveAfterCharge)
            {
                int charged = emptyCapacitor.Charge(side.Power, 1);
                side.AuxiliaryPowerRecharged += charged;
            }
        }

        if (side.Auxiliary.HasShieldBattery &&
            selectedAuxiliaryFunctional &&
            side.ShieldBatteryChargesRemaining > 0 &&
            side.Ship.Defense.CurrentShieldCapacity <
                side.Ship.Defense.EffectiveShieldMaximum)
        {
            int restored = side.Ship.Defense.RestoreShields(
                side.Auxiliary.ShieldBatteryRestore);
            if (restored > 0)
            {
                side.ShieldBatteryChargesRemaining--;
                side.AuxiliaryShieldRestored += restored;
                diagnostics.TacticalShieldRestored += restored;
            }
        }
        if (side.Ship.Defense.CurrentShieldCapacity == 0)
        {
            diagnostics.ShieldlessShipTurns++;
        }
        side.PdsAttemptsThisTurn = 0;
        return activations;
    }

    private static void ResetPoweredDefenseAuxiliary(IntegratedSide side)
    {
        side.Ship.Defense.ShieldArmor = side.Technology.ShieldArmor;
        side.Ship.Defense.ClearTemporaryPrimaryArmorProtectionBonus();
    }

    private static bool BuildShieldHardenerFunctional(IntegratedSide side) =>
        side.Build?.ShieldHardener == true &&
        side.Ship.GetComponent("shield-hardener").Condition is
            ComponentCondition.Operational or ComponentCondition.Degraded;

    private static int PlannedPoweredDefensePower(IntegratedSide side)
    {
        int hardenerPower = BuildShieldHardenerFunctional(side)
            ? side.Build!.ShieldHardenerPowerCost
            : SelectedAuxiliaryFunctional(side) && side.Auxiliary.HasShieldHardener
                ? side.Auxiliary.ShieldHardenerPower
                : 0;
        int energizedArmorPower = SelectedAuxiliaryFunctional(side) &&
            side.Auxiliary.HasEnergizedArmor
                ? side.Auxiliary.EnergizedArmorPower
                : 0;
        return hardenerPower + energizedArmorPower;
    }

    private static void CommitPoweredDefenseAuxiliary(IntegratedSide side)
    {
        if (BuildShieldHardenerFunctional(side))
        {
            int power = side.Build!.ShieldHardenerPowerCost;
            if (side.Power.SpendablePower >= power)
            {
                side.Power.IncreasePoweredSystem("shield-hardener", power);
                side.Ship.Defense.ShieldArmor = checked(
                    side.Technology.ShieldArmor + side.Build.ShieldHardenerArmor);
            }
        }
        else if (SelectedAuxiliaryFunctional(side) && side.Auxiliary.HasShieldHardener &&
            side.Power.SpendablePower >= side.Auxiliary.ShieldHardenerPower)
        {
            side.Power.IncreasePoweredSystem(
                "shield-hardener",
                side.Auxiliary.ShieldHardenerPower);
            side.Ship.Defense.ShieldArmor = checked(
                side.Technology.ShieldArmor +
                side.Auxiliary.ShieldHardenerStrength);
        }

        if (SelectedAuxiliaryFunctional(side) && side.Auxiliary.HasEnergizedArmor &&
            side.Power.SpendablePower >= side.Auxiliary.EnergizedArmorPower)
        {
            side.Power.IncreasePoweredSystem(
                "energized-armor",
                side.Auxiliary.EnergizedArmorPower);
            side.Ship.Defense.SetTemporaryPrimaryArmorProtectionBonus(
                side.Auxiliary.EnergizedArmorProtectionBonus);
        }
    }

    private static void DischargeIndependentAuxiliaryPower(
        IntegratedSide side,
        int requiredPackagePower)
    {
        int deficit = Math.Max(0, requiredPackagePower - side.Power.SpendablePower);
        if (deficit <= 0)
        {
            return;
        }

        // This is a deterministic screening doctrine, not a player restriction:
        // reusable capacitor energy is spent before finite battery charges. Every
        // installed AUX component retains its own once-per-turn operation limit.
        foreach (IndependentCapacitorInstallation capacitor in side.IndependentCapacitors)
        {
            if (deficit <= 0) break;
            if (!IndependentPowerComponentFunctional(side, capacitor.ComponentId) ||
                capacitor.State.StoredPower <= 0 ||
                capacitor.State.OperationUsedThisTurn) continue;
            int requested = Math.Min(deficit, capacitor.State.DischargeRate);
            int discharged = capacitor.State.Discharge(side.Power, requested);
            side.AuxiliaryPowerDischarged += discharged;
            deficit = Math.Max(0, requiredPackagePower - side.Power.SpendablePower);
        }
        foreach (IndependentCombatBatteryInstallation battery in side.IndependentCombatBatteries)
        {
            if (deficit <= 0) break;
            if (!IndependentPowerComponentFunctional(side, battery.ComponentId) ||
                battery.State.CurrentCharges <= 0 ||
                battery.State.DischargesThisTurn >= battery.State.DischargeLimitPerTurn) continue;
            int discharged = battery.State.Discharge(side.Power);
            side.AuxiliaryPowerDischarged += discharged;
            deficit = Math.Max(0, requiredPackagePower - side.Power.SpendablePower);
        }
    }

    private static void RechargeIndependentCapacitors(
        IntegratedSide side,
        int reserveAfterCharge)
    {
        foreach (IndependentCapacitorInstallation capacitor in side.IndependentCapacitors)
        {
            if (!IndependentPowerComponentFunctional(side, capacitor.ComponentId) ||
                capacitor.State.OperationUsedThisTurn ||
                capacitor.State.RechargeBlockedThisTurn ||
                capacitor.State.StoredPower >= capacitor.State.Capacity)
            {
                continue;
            }
            int spare = side.Power.SpendablePower - reserveAfterCharge;
            if (spare <= 0)
            {
                break;
            }
            int requested = Math.Min(
                spare,
                Math.Min(capacitor.State.ChargeRate,
                    capacitor.State.Capacity - capacitor.State.StoredPower));
            if (requested <= 0) continue;
            int charged = capacitor.State.Charge(side.Power, requested);
            side.AuxiliaryPowerRecharged += charged;
        }
    }

    private static int PlannedPdsPower(
        IntegratedSide side,
        IntegratedSide opponent,
        bool hasInboundMissile)
    {
        bool missileThreat = hasInboundMissile ||
            opponent.Family == WeaponFamily.Missile ||
            ((side.Build is not null || opponent.Build is not null) &&
             opponent.SecondaryFamily == WeaponFamily.Missile);
        bool pdsAmmunitionAvailable =
            side.PdsAmmunitionRemaining is null or > 0;
        int functionalCount = FunctionalPdsComponentIds(side).Count;
        return side.Profile.PdsEnabled && functionalCount > 0 &&
            missileThreat && pdsAmmunitionAvailable
                ? EffectivePdsPower(side) * functionalCount
                : 0;
    }

    private static int PlannedEvasivePower(IntegratedSide side)
    {
        bool evasiveInstalled = side.Auxiliary.LegacyIntegratedSuite ||
            side.Auxiliary.EvasiveManeuvers;
        return side.Profile.EvasiveManeuversEnabled && evasiveInstalled &&
            side.Ship.CapabilitySnapshot.HasEvasiveManeuvers
                ? 1
                : 0;
    }

    private static bool ShieldCanRecharge(IntegratedSide side) =>
        side.Ship.GetComponent("shield-generator").Condition is
            ComponentCondition.Operational or ComponentCondition.Degraded;

    private static bool ShieldNeedsTacticalRechargeAfterBase(IntegratedSide side)
    {
        int baseRecharge = side.Ship.GetComponent("shield-generator").Condition ==
                ComponentCondition.Operational
            ? side.Technology.ShieldBaseRecharge
            : 0;
        int projected = Math.Min(
            side.Ship.Defense.EffectiveShieldMaximum,
            side.Ship.Defense.CurrentShieldCapacity + baseRecharge);
        return projected < side.Ship.Defense.EffectiveShieldMaximum;
    }

    private static void PrepareAuxiliaryPower(IntegratedSide side)
    {
        bool shieldDamaged = side.Ship.Defense.CurrentShieldCapacity <
            side.Ship.Defense.EffectiveShieldMaximum;
        if (!shieldDamaged || !SelectedAuxiliaryFunctional(side))
        {
            return;
        }
        if (side.Auxiliary.HasCombatBattery &&
            side.CombatBatteryChargesRemaining > 0)
        {
            side.Power.AddGeneratedPower(side.Auxiliary.CombatBatteryGain);
            side.CombatBatteryChargesRemaining--;
            side.AuxiliaryPowerDischarged += side.Auxiliary.CombatBatteryGain;
        }
        else if (side.Auxiliary.HasPowerCapacitor &&
            side.CapacitorStoredPower > 0)
        {
            int discharged = Math.Min(
                side.Auxiliary.CapacitorDischargeRate,
                side.CapacitorStoredPower);
            side.Power.AddGeneratedPower(discharged);
            side.CapacitorStoredPower -= discharged;
            side.AuxiliaryPowerDischarged += discharged;
        }
    }

    private static SensorTurnState EstablishedFirmSensorState(
        Tl1SensorEnvelope envelope) => new(
            Tl1OperationalTrackPolicy.EstablishedFirm,
            0,
            envelope.PassiveFirmRange,
            envelope.PassiveApproximateRange,
            false,
            false);

    private static SensorTurnState AllocateOperationalSensor(
        IntegratedSide side,
        Tl1OperationalTrackPolicy policy,
        int netEwRangePenalty,
        int currentRange,
        Tl1SensorEnvelope envelope,
        Tl1IntegratedSensorOverloadPolicy overloadPolicy =
            Tl1IntegratedSensorOverloadPolicy.None,
        IntegratedDiagnosticTelemetry? diagnostics = null)
    {
        if (netEwRangePenalty < 0)
        {
            throw new InvalidOperationException(
                "Net EW range penalty cannot be negative.");
        }
        if (policy == Tl1OperationalTrackPolicy.EstablishedFirm)
        {
            return EstablishedFirmSensorState(envelope);
        }

        int passiveFirm = Math.Max(0, envelope.PassiveFirmRange - netEwRangePenalty);
        int passiveApprox = Math.Max(
            passiveFirm,
            envelope.PassiveApproximateRange - netEwRangePenalty);
        ShipComponentState activeSensor = side.Ship.GetComponent("active-sensors");
        bool installedAndFunctional = side.Build?.ActiveSensor == true &&
            (activeSensor.Condition is
                ComponentCondition.Operational or ComponentCondition.Degraded);
        if (policy == Tl1OperationalTrackPolicy.PassiveOnly ||
            !installedAndFunctional ||
            currentRange <= passiveFirm)
        {
            return new SensorTurnState(
                policy, 0, passiveFirm, passiveApprox, installedAndFunctional, false);
        }

        if (envelope.SingleActiveMode)
        {
            return AllocateSingleModeOperationalSensor(
                side, policy, currentRange, envelope, passiveFirm, passiveApprox,
                activeSensor, diagnostics, overloadPolicy);
        }

        int level1Firm = Math.Max(
            0, envelope.ActiveLevel1FirmRange - netEwRangePenalty);
        int level1Approx = Math.Max(
            level1Firm, envelope.ActiveLevel1ApproximateRange - netEwRangePenalty);
        int level2Firm = Math.Max(
            0, envelope.ActiveLevel2FirmRange - netEwRangePenalty);
        int level2Approx = Math.Max(
            level2Firm, envelope.ActiveLevel2ApproximateRange - netEwRangePenalty);
        int listedOverloadedFirm = checked(
            level2Firm + ActiveSensorOverloadProfile.Tl1.FirmRangeBonus);
        if (overloadPolicy == Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded &&
            currentRange > level2Firm && currentRange <= listedOverloadedFirm &&
            activeSensor.Condition == ComponentCondition.Operational)
        {
            diagnostics?.RecordSensorOverloadRequest(side.Id);
            if (side.ActiveSensorStrain + ActiveSensorOverloadProfile.Tl1.StrainCost >
                ActiveSensorOverloadProfile.Tl1.StrainLimit)
            {
                diagnostics?.RecordOverloadDeniedStrain(side.Id);
            }
            else if (side.Power.SpendablePower <
                envelope.HighActivePowerCost + ActiveSensorOverloadProfile.Tl1.AdditionalTacticalPowerCost)
            {
                diagnostics?.RecordOverloadDeniedPower(side.Id);
            }
            ActiveSensorOverloadResult overload =
                ActiveSensorOverloadService.ResolveSafe(
                    ActiveSensorOverloadProfile.Tl1,
                    activeSensor.Condition,
                    side.ActiveSensorStrain,
                    Math.Max(0, side.Power.SpendablePower - envelope.HighActivePowerCost));
            int overloadedFirm = level2Firm + overload.FirmRangeBonus;
            int overloadedApprox = level2Approx + overload.ApproximateRangeBonus;
            if (overload.BenefitApplied &&
                currentRange <= overloadedFirm &&
                side.Power.SpendablePower >=
                    envelope.HighActivePowerCost + overload.AdditionalTacticalPowerCost)
            {
                int totalPower = envelope.HighActivePowerCost + overload.AdditionalTacticalPowerCost;
                side.Power.IncreasePoweredSystem("active-sensors", totalPower);
                side.ActiveSensorStrain += overload.StrainApplied;
                return new SensorTurnState(
                    policy, totalPower, overloadedFirm, overloadedApprox, true, false, true);
            }
        }

        int requestedPower = currentRange <= level1Firm
            ? envelope.NormalActivePowerCost
            : envelope.HighActivePowerCost;
        if (currentRange > level2Approx)
        {
            requestedPower = envelope.HighActivePowerCost;
        }

        int affordablePower;
        if (policy == Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive)
        {
            // Acquisition-first operational doctrine: if passive sensing cannot
            // produce Firm after movement, fund the minimum active-sensor
            // setting first. Any remaining Tactical Power is then available
            // to FullVolleyFirst/PDS allocation and weapon commits.
            affordablePower = Math.Clamp(side.Power.SpendablePower, 0, envelope.HighActivePowerCost);
        }
        else
        {
            int offensiveReserve = ReadyAttackPowerCost(side);
            affordablePower = Math.Clamp(
                side.Power.SpendablePower - offensiveReserve, 0, envelope.HighActivePowerCost);
        }
        int committedPower = Math.Min(requestedPower, affordablePower);
        bool unfunded = committedPower < requestedPower;
        if (committedPower > 0)
        {
            side.Power.IncreasePoweredSystem("active-sensors", committedPower);
        }

        if (committedPower >= envelope.HighActivePowerCost)
        {
            return new SensorTurnState(
                policy, committedPower, level2Firm, level2Approx, true, unfunded);
        }
        if (committedPower >= envelope.NormalActivePowerCost)
        {
            return new SensorTurnState(
                policy, committedPower, level1Firm, level1Approx, true, unfunded);
        }
        return new SensorTurnState(
            policy, 0, passiveFirm, passiveApprox, true, unfunded);
    }

    private static SensorTurnState AllocateSingleModeOperationalSensor(
        IntegratedSide side,
        Tl1OperationalTrackPolicy policy,
        int currentRange,
        Tl1SensorEnvelope envelope,
        int passiveFirm,
        int passiveApprox,
        ShipComponentState activeSensor,
        IntegratedDiagnosticTelemetry? diagnostics,
        Tl1IntegratedSensorOverloadPolicy overloadPolicy)
    {
        int activeFirm = envelope.ActiveLevel1FirmRange;
        int activeApprox = envelope.ActiveLevel1ApproximateRange;
        int normalPower = envelope.NormalActivePowerCost;
        ActiveSensorOverloadProfile overloadProfile = envelope.ToOverloadProfile();
        int listedOverloadedFirm = checked(activeFirm + overloadProfile.FirmRangeBonus);

        if (overloadPolicy == Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded &&
            currentRange > activeFirm && currentRange <= listedOverloadedFirm &&
            activeSensor.Condition == ComponentCondition.Operational)
        {
            diagnostics?.RecordSensorOverloadRequest(side.Id);
            if (side.ActiveSensorStrain + overloadProfile.StrainCost >
                overloadProfile.StrainLimit)
            {
                diagnostics?.RecordOverloadDeniedStrain(side.Id);
            }
            else if (side.Power.SpendablePower <
                normalPower + overloadProfile.AdditionalTacticalPowerCost)
            {
                diagnostics?.RecordOverloadDeniedPower(side.Id);
            }

            ActiveSensorOverloadResult overload =
                ActiveSensorOverloadService.ResolveSafe(
                    overloadProfile,
                    activeSensor.Condition,
                    side.ActiveSensorStrain,
                    Math.Max(0, side.Power.SpendablePower - normalPower));
            int overloadedFirm = activeFirm + overload.FirmRangeBonus;
            int overloadedApprox = activeApprox + overload.ApproximateRangeBonus;
            int totalPower = normalPower + overload.AdditionalTacticalPowerCost;
            if (overload.BenefitApplied &&
                currentRange <= overloadedFirm &&
                side.Power.SpendablePower >= totalPower)
            {
                side.Power.IncreasePoweredSystem("active-sensors", totalPower);
                side.ActiveSensorStrain += overload.StrainApplied;
                return new SensorTurnState(
                    policy, totalPower, overloadedFirm, overloadedApprox,
                    true, false, true);
            }
        }

        int affordablePower;
        if (policy == Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive)
        {
            affordablePower = side.Power.SpendablePower;
        }
        else
        {
            affordablePower = Math.Max(
                0, side.Power.SpendablePower - ReadyAttackPowerCost(side));
        }

        bool funded = affordablePower >= normalPower;
        if (funded)
        {
            side.Power.IncreasePoweredSystem("active-sensors", normalPower);
            return new SensorTurnState(
                policy, normalPower, activeFirm, activeApprox, true, false);
        }

        return new SensorTurnState(
            policy, 0, passiveFirm, passiveApprox, true, true);
    }

    private static IntegratedTrackQuality ResolveFoundationTrackQuality(
        Tl1SensorEnvelope observerEnvelope,
        Tl1SensorEnvelope targetEnvelope,
        SensorTurnState observerSensor,
        SensorTurnState targetSensor,
        EwTurnState observerEw,
        EwTurnState targetEw,
        int currentRange)
    {
        SensorEwFoundationProfile observerProfile = observerEnvelope.ToFoundationProfile();
        SensorEwFoundationProfile targetProfile = targetEnvelope.ToFoundationProfile();
        SensorEwFoundationEvaluationResult result =
            SensorEwFoundationResolver.Evaluate(
                currentRange,
                observerProfile,
                targetProfile,
                new SensorEwFoundationEvaluationContext(
                    observerSensor.ActivePower > 0 ? SensorMode.Active : SensorMode.Passive,
                    ObserverActiveSensorOverloaded: observerSensor.Overloaded,
                    TargetActiveSensorsEnabled: targetSensor.ActivePower > 0,
                    TargetActiveSensorOverloaded: targetSensor.Overloaded,
                    TargetEcmRating: targetEw.EcmRating,
                    ObserverEccmRating: observerEw.EccmRating,
                    HasLineOfSight: true));

        return ToIntegratedTrackQuality(result.FinalTrack);
    }

    private static PreCombatElectronicWarfareParticipant BuildPreCombatEwParticipant(
        SensorEwFoundationProfile profile,
        SensorTurnState sensorState,
        int ecmRating,
        int eccmRating) =>
        new(
            profile,
            sensorState.ActivePower > 0 ? SensorMode.Active : SensorMode.Passive,
            sensorState.Overloaded,
            sensorState.ActivePower > 0,
            ecmRating,
            eccmRating,
            HasLineOfSight: true);

    private static IntegratedTrackQuality ToIntegratedTrackQuality(
        SensorEwFoundationTrackState track) =>
        track switch
        {
            SensorEwFoundationTrackState.Firm => IntegratedTrackQuality.Firm,
            SensorEwFoundationTrackState.Approximate =>
                IntegratedTrackQuality.Approximate,
            _ => IntegratedTrackQuality.None,
        };

    private static IntegratedTrackQuality ResolveTrackQuality(
        SensorTurnState sensor,
        int currentRange)
    {
        if (sensor.EstablishedFirm)
        {
            return IntegratedTrackQuality.Firm;
        }
        if (currentRange <= sensor.FirmRange)
        {
            return IntegratedTrackQuality.Firm;
        }
        if (currentRange <= sensor.ApproximateRange)
        {
            return IntegratedTrackQuality.Approximate;
        }
        return IntegratedTrackQuality.None;
    }

    private static TurnSystems AllocateDefensiveSystems(
        IntegratedSide side,
        IntegratedSide opponent,
        bool hasInboundMissile)
    {
        if (side.Ship.IsDestroyed)
        {
            return TurnSystems.Inactive;
        }
        bool missileThreat = hasInboundMissile ||
            opponent.Family == WeaponFamily.Missile ||
            ((side.Build is not null || opponent.Build is not null) &&
             opponent.SecondaryFamily == WeaponFamily.Missile);
        bool pdsAmmunitionAvailable =
            side.PdsAmmunitionRemaining is null or > 0;
        IReadOnlyList<string> functionalPds = FunctionalPdsComponentIds(side);
        int offensiveReserve = side.PowerDoctrine switch
        {
            Tl1TacticalPowerDoctrine.DefenseFirst => 0,
            Tl1TacticalPowerDoctrine.PrimaryFireFirst =>
                ReadyAttackPowerCostForBay(side, secondary: false),
            Tl1TacticalPowerDoctrine.FullVolleyFirst => ReadyAttackPowerCost(side),
            _ => 0,
        };
        int pdsPowerBudget = Math.Max(0, side.Power.SpendablePower - offensiveReserve);
        var pdsReactionsList = new List<string>();
        int committedPdsPower = 0;
        if (side.Profile.PdsEnabled && missileThreat && pdsAmmunitionAvailable)
        {
            foreach (string componentId in functionalPds)
            {
                int remainingBudget = pdsPowerBudget - committedPdsPower;
                (int power, int reactions) = EffectivePdsReadinessMode(side, remainingBudget);
                if (reactions <= 0) break;
                committedPdsPower = checked(committedPdsPower + power);
                pdsReactionsList.AddRange(Enumerable.Repeat(componentId, reactions));
            }
        }
        string[] pdsReactions = pdsReactionsList.ToArray();
        if (committedPdsPower > 0)
        {
            side.Power.Spend(committedPdsPower);
        }

        bool evasiveInstalled = side.Auxiliary.LegacyIntegratedSuite ||
            side.Auxiliary.EvasiveManeuvers;
        bool evasiveReady = side.Profile.EvasiveManeuversEnabled &&
            evasiveInstalled && side.Ship.CapabilitySnapshot.HasEvasiveManeuvers &&
            side.Power.SpendablePower > 0;
        if (evasiveReady)
        {
            int attackCost = ReadyAttackPowerCost(side);
            if (attackCost > 0 && side.Power.SpendablePower <= attackCost)
            {
                evasiveReady = false;
            }
        }
        if (evasiveReady)
        {
            side.Power.Spend(1);
        }
        return new TurnSystems(pdsReactions, evasiveReady);
    }

    private static IReadOnlyList<string> FunctionalPdsComponentIds(
        IntegratedSide side)
    {
        var ids = new List<string>();
        for (int index = 1; index <= side.InstalledPdsCount; index++)
        {
            string id = index == 1 ? "pds" : $"pds-{index}";
            ShipComponentState component = side.Ship.GetComponent(id);
            if (component.Condition is
                ComponentCondition.Operational or ComponentCondition.Degraded)
            {
                ids.Add(id);
            }
        }
        return ids;
    }

    private static int EffectivePdsChance(IntegratedSide side, string componentId)
    {
        int chance;
        if (side.Build?.PdsBaseChance is int buildBaseChance)
        {
            int computerBonus = ComponentPerformance.TargetingComputerBonus(
                side.Technology.TargetingBonus,
                side.Ship.GetComponent("targeting-computer").Condition);
            chance = Math.Clamp(buildBaseChance + computerBonus, 0, 95);
        }
        else
        {
            chance = side.Build is not null || side.Auxiliary.LegacyIntegratedSuite
                ? side.Technology.EffectivePdsChance
                : Math.Clamp(
                    side.Auxiliary.PdsBaseChance + side.Technology.TargetingBonus,
                    0,
                    95);
        }
        return ComponentPerformance.PdsBaseAccuracy(
            chance,
            side.Ship.GetComponent(componentId).Condition);
    }

    private static int EffectivePdsPower(IntegratedSide side) =>
        side.Build?.PdsPowerCost ??
        (side.Build is not null || side.Auxiliary.LegacyIntegratedSuite
            ? side.Technology.PdsPower
            : side.Auxiliary.PdsPower);

    private static int EffectivePdsReactionCapacity(IntegratedSide side) =>
        Math.Clamp(side.Build?.PdsReactionCapacity ?? 1, 1, 2);

    private static (int Power, int Reactions) EffectivePdsReadinessMode(
        IntegratedSide side, int availablePower)
    {
        int primaryPower = EffectivePdsPower(side);
        int primaryReactions = EffectivePdsReactionCapacity(side);
        if (primaryPower == 0 || availablePower >= primaryPower)
        {
            return (primaryPower, primaryReactions);
        }
        if (side.Build?.PdsFallbackPowerCost is int fallbackPower &&
            side.Build.PdsFallbackReactionCapacity is int fallbackReactions &&
            fallbackPower >= 0 && fallbackPower < primaryPower &&
            fallbackReactions is >= 1 and <= 2 && fallbackReactions < primaryReactions &&
            availablePower >= fallbackPower)
        {
            return (fallbackPower, fallbackReactions);
        }
        return (0, 0);
    }

    internal static (int Power, int Reactions) PdsReadinessModeForSelfTest(
        int primaryPower, int primaryReactions, int? fallbackPower, int? fallbackReactions, int availablePower)
    {
        if (primaryPower < 0 || primaryReactions is < 1 or > 2 || availablePower < 0 ||
            ((fallbackPower is null) != (fallbackReactions is null)))
        {
            throw new InvalidOperationException("Invalid scalable PDS readiness self-test input.");
        }
        if (primaryPower == 0 || availablePower >= primaryPower)
        {
            return (primaryPower, primaryReactions);
        }
        if (fallbackPower is int fp && fallbackReactions is int fr &&
            fp >= 0 && fp < primaryPower && fr is >= 1 and <= 2 && fr < primaryReactions &&
            availablePower >= fp)
        {
            return (fp, fr);
        }
        return (0, 0);
    }

    internal static (int Power, int Reactions) PdsReadinessForSelfTest(
        int powerCost, int reactionCapacity, int installedCount, int availablePower)
    {
        if (powerCost < 0 || reactionCapacity is < 1 or > 2 || installedCount < 0 || availablePower < 0)
        {
            throw new InvalidOperationException("Invalid PDS readiness self-test input.");
        }
        int ready = powerCost == 0
            ? installedCount
            : Math.Min(installedCount, availablePower / powerCost);
        return (ready * powerCost, ready * reactionCapacity);
    }

    private static int? InitialBuildPdsAmmunition(
        int installedCount, string? pdsFamily, int? perInstallationAmmunition)
    {
        if (installedCount < 0 || perInstallationAmmunition is < 0)
        {
            throw new InvalidOperationException("PDS ammunition initialization received an invalid count.");
        }
        if (perInstallationAmmunition is int explicitAmmunition)
        {
            return checked(installedCount * explicitAmmunition);
        }
        return string.IsNullOrWhiteSpace(pdsFamily)
            ? checked(installedCount * KineticPdsAmmunitionCapacity)
            : null;
    }

    internal static int? InitialBuildPdsAmmunitionForSelfTest(
        int installedCount, string? pdsFamily, int? perInstallationAmmunition) =>
        InitialBuildPdsAmmunition(installedCount, pdsFamily, perInstallationAmmunition);

    private static void ConsumePdsAmmunition(IntegratedSide side)
    {
        if (side.PdsAmmunitionRemaining is int remaining && remaining > 0)
        {
            side.PdsAmmunitionRemaining = remaining - 1;
        }
    }

    private static void SpendAttackPower(
        TacticalPowerLedger power,
        int tacticalPowerCost)
    {
        ArgumentNullException.ThrowIfNull(power);
        if (tacticalPowerCost < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(tacticalPowerCost));
        }
        if (tacticalPowerCost > 0)
        {
            power.Spend(tacticalPowerCost);
        }
    }

    internal static (int SpentPower, int SpendablePower) SpendAttackPowerForSelfTest(
        int envelope,
        int tacticalPowerCost)
    {
        var ledger = new TacticalPowerLedger();
        ledger.BeginTurn(envelope);
        SpendAttackPower(ledger, tacticalPowerCost);
        return (ledger.SpentPower, ledger.SpendablePower);
    }

    private static int ReadyAttackPowerCost(IntegratedSide side)
    {
        int total = ReadyAttackPowerCostForBay(side, secondary: false);
        if (side.HasSecondaryWeapon)
        {
            total += ReadyAttackPowerCostForBay(side, secondary: true);
        }
        return total;
    }

    private static int ReadyAttackPowerCostForBay(
        IntegratedSide side,
        bool secondary)
    {
        WeaponFamily family = WeaponFamilyForBay(side, secondary);
        ShipComponentState weapon = side.Ship.GetComponent(
            WeaponComponentId(secondary));
        ConditionedWeaponPerformance performance = ComponentPerformance.Weapon(
            family,
            weapon.Condition,
            NormalDamage(side, secondary),
            NormalPowerCost(side, secondary),
            damagePointScale: DamagePointScale.Legacy);
        bool recycling = secondary
            ? side.SecondaryRecycleThisTurn
            : side.RecycleThisTurn;
        if (!performance.CanFire || recycling ||
            !SupportAvailable(side, secondary))
        {
            return 0;
        }
        return performance.TacticalPowerCost;
    }

    private static int PrepareSafeStlOverload(
        IntegratedSide side,
        Tl1IntegratedStlOverloadPolicy policy,
        int preMovementRange,
        ref int fuel,
        IntegratedDiagnosticTelemetry diagnostics)
    {
        int normalMovement = BuildTacticalSnapshot(side).AvailableStlMovement;
        if (policy != Tl1IntegratedStlOverloadPolicy.SafeRangePressure ||
            side.Ship.IsDestroyed)
        {
            return normalMovement;
        }

        RangeDecisionDoctrine doctrine = DoctrineFor(side.Family);
        bool rangePressure =
            preMovementRange < doctrine.PreferredMinimumRangeHexes ||
            preMovementRange > doctrine.PreferredMaximumRangeHexes;
        if (!rangePressure)
        {
            return normalMovement;
        }

        diagnostics.RecordStlOverloadRequest(side.Id);
        ShipComponentState drive = side.Ship.GetComponent("stl");
        if (side.StlStrain + StlDriveOverloadProfile.Tl1.StrainCost >
            StlDriveOverloadProfile.Tl1.StrainLimit)
        {
            diagnostics.RecordOverloadDeniedStrain(side.Id);
            return normalMovement;
        }
        if (side.Power.SpendablePower < StlDriveOverloadProfile.Tl1.TacticalPowerCost)
        {
            diagnostics.RecordOverloadDeniedPower(side.Id);
            return normalMovement;
        }

        StlDriveOverloadResult overload = StlDriveOverloadService.Resolve(
            StlDriveOverloadProfile.Tl1,
            drive.Condition,
            side.StlStrain,
            side.Power.SpendablePower,
            fuel);
        if (!overload.BenefitApplied ||
            overload.Outcome != StlDriveOverloadOutcome.SafeSuccess)
        {
            return normalMovement;
        }

        side.Power.IncreasePoweredSystem("stl-overload", overload.TacticalPowerCost);
        fuel -= overload.ExtraFuelCost;
        side.StlStrain += overload.StrainApplied;
        diagnostics.RecordStlOverload(side.Id);
        return overload.EffectiveMovement;
    }

    private static void RecordSensorOverloadPlanningOpportunity(
        IntegratedSide side,
        Tl1OperationalTrackPolicy trackPolicy,
        int netEwRangePenalty,
        Tl1SensorEnvelope sensorEnvelope,
        Tl1IntegratedSensorOverloadPolicy sensorOverloadPolicy,
        IntegratedDiagnosticTelemetry diagnostics)
    {
        if (sensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded)
        {
            return;
        }
        int normalFirm = MaximumFirmRangeForMovementPlan(
            side, trackPolicy, netEwRangePenalty, sensorEnvelope,
            Tl1IntegratedSensorOverloadPolicy.None);
        int overloadFirm = MaximumFirmRangeForMovementPlan(
            side, trackPolicy, netEwRangePenalty, sensorEnvelope,
            sensorOverloadPolicy);
        RangeDecisionDoctrine doctrine = DoctrineFor(side.Family);
        if (overloadFirm > normalFirm &&
            doctrine.PreferredMaximumRangeHexes > normalFirm)
        {
            diagnostics.RecordSensorOverloadPlanningOpportunity(side.Id);
        }
    }

    private sealed record FunctionalEwInstallation(string ComponentId, int Rating, ComponentCondition Condition);

    private static FunctionalEwInstallation? ResolveFunctionalEwInstallation(
        IntegratedSide side, bool isEcm, int fallbackRating)
    {
        string baseId = isEcm ? "ecm" : "eccm";
        IReadOnlyList<int> ratings = isEcm
            ? side.Build?.EcmSuiteRatings ?? (IReadOnlyList<int>)Array.Empty<int>()
            : side.Build?.EccmSuiteRatings ?? (IReadOnlyList<int>)Array.Empty<int>();
        bool legacyInstalled = isEcm
            ? side.Build?.EcmSuite == true
            : side.Build?.EccmSuite == true;
        if (ratings.Count == 0)
        {
            if (!legacyInstalled) return null;
            ShipComponentState legacy = side.Ship.GetComponent(baseId);
            return legacy.Condition is ComponentCondition.Operational or ComponentCondition.Degraded
                ? new FunctionalEwInstallation(baseId, fallbackRating, legacy.Condition)
                : null;
        }
        FunctionalEwInstallation? best = null;
        for (int i = 0; i < ratings.Count; i++)
        {
            string componentId = i == 0 ? baseId : $"{baseId}-{i + 1}";
            ShipComponentState component = side.Ship.GetComponent(componentId);
            if (component.Condition is ComponentCondition.Disabled or ComponentCondition.Destroyed) continue;
            int rating = ratings[i];
            var candidate = new FunctionalEwInstallation(componentId, rating, component.Condition);
            if (best is null || candidate.Rating > best.Rating ||
                (candidate.Rating == best.Rating &&
                 ComponentPerformance.AdditionalCommittedPower(
                    isEcm ? ShipComponentKind.Ecm : ShipComponentKind.Eccm, candidate.Condition) <
                 ComponentPerformance.AdditionalCommittedPower(
                    isEcm ? ShipComponentKind.Ecm : ShipComponentKind.Eccm, best!.Condition)))
            {
                best = candidate;
            }
        }
        return best;
    }

    internal static int ResolveHighestFunctionalEwRatingForSelfTest(
        IReadOnlyList<int> ratings, IReadOnlyList<bool> functional)
    {
        if (ratings.Count != functional.Count)
        {
            throw new InvalidOperationException("EW self-test rating/function arrays must have equal length.");
        }
        int best = 0;
        for (int i = 0; i < ratings.Count; i++)
        {
            if (ratings[i] < 1 || ratings[i] > 4)
            {
                throw new InvalidOperationException("EW self-test ratings must be between 1 and 4.");
            }
            if (functional[i]) best = Math.Max(best, ratings[i]);
        }
        return best;
    }

    private static EwTurnState AllocateOperationalEw(
        IntegratedSide side,
        Tl1IntegratedEwPowerPolicy ecmPolicy,
        Tl1IntegratedEwPowerPolicy eccmPolicy,
        int? ecmNormalPowerCostOverride,
        int? eccmNormalPowerCostOverride,
        IntegratedDiagnosticTelemetry diagnostics,
        int ecmNormalRating = 1,
        int eccmNormalRating = 1)
    {
        if (ecmPolicy == Tl1IntegratedEwPowerPolicy.ReactiveNormal)
        {
            throw new InvalidOperationException(
                "ReactiveNormal is an ECCM response policy and cannot be used for ECM.");
        }
        FunctionalEwInstallation? ecm = ResolveFunctionalEwInstallation(side, isEcm: true, ecmNormalRating);
        FunctionalEwInstallation? eccm = ResolveFunctionalEwInstallation(side, isEcm: false, eccmNormalRating);

        int ecmStrain = side.EcmStrain;
        int ecmRating = ecm is null ? 0 : AllocateEwSystem(
            side, ecm.ComponentId, installed: true, ecmPolicy,
            ecmNormalPowerCostOverride ?? 1,
            ref ecmStrain, diagnostics, isEcm: true, normalRating: ecm.Rating);
        side.EcmStrain = ecmStrain;

        int eccmStrain = side.EccmStrain;
        int eccmRating = eccm is null ? 0 : AllocateEwSystem(
            side, eccm.ComponentId, installed: true, eccmPolicy,
            eccmNormalPowerCostOverride ?? 1,
            ref eccmStrain, diagnostics, isEcm: false, normalRating: eccm.Rating);
        side.EccmStrain = eccmStrain;

        return new EwTurnState(ecmRating, eccmRating);
    }

    private static int AllocateOperationalEcm(
        IntegratedSide side,
        Tl1IntegratedEwPowerPolicy policy,
        int? normalPowerCostOverride,
        IntegratedDiagnosticTelemetry diagnostics,
        int normalRating = 1,
        int? fullStrengthNormalPowerCostOverride = null)
    {
        if (policy == Tl1IntegratedEwPowerPolicy.ReactiveNormal)
        {
            throw new InvalidOperationException(
                "ReactiveNormal is an ECCM response policy and cannot be used for ECM.");
        }
        FunctionalEwInstallation? installation = ResolveFunctionalEwInstallation(side, isEcm: true, normalRating);
        if (installation is null) return 0;
        int strain = side.EcmStrain;
        int rating = AllocateEwSystem(
            side, installation.ComponentId, installed: true, policy,
            normalPowerCostOverride ?? 1,
            ref strain, diagnostics, isEcm: true, normalRating: installation.Rating,
            fullStrengthNormalPowerCostOverride: fullStrengthNormalPowerCostOverride);
        side.EcmStrain = strain;
        return rating;
    }

    private static int AllocateOperationalEccm(
        IntegratedSide side,
        Tl1IntegratedEwPowerPolicy policy,
        int? normalPowerCostOverride,
        bool reactiveNeeded,
        IntegratedDiagnosticTelemetry diagnostics,
        int normalRating = 1,
        int? fullStrengthNormalPowerCostOverride = null)
    {
        if (policy == Tl1IntegratedEwPowerPolicy.ReactiveNormal && !reactiveNeeded)
        {
            return 0;
        }
        FunctionalEwInstallation? installation = ResolveFunctionalEwInstallation(side, isEcm: false, normalRating);
        if (installation is null) return 0;
        int strain = side.EccmStrain;
        int rating = AllocateEwSystem(
            side, installation.ComponentId, installed: true, policy,
            normalPowerCostOverride ?? 1,
            ref strain, diagnostics, isEcm: false, normalRating: installation.Rating,
            fullStrengthNormalPowerCostOverride: fullStrengthNormalPowerCostOverride);
        side.EccmStrain = strain;
        return rating;
    }

    private static TacticalObservableStateSignature BuildAdaptiveObservableState(
        IntegratedSide side,
        bool opponentEcmEmissionObserved,
        bool opponentActiveSensorEmissionObserved,
        int eccmFallbackRating)
    {
        FunctionalEwInstallation? eccm = ResolveFunctionalEwInstallation(
            side, isEcm: false, eccmFallbackRating);
        ComponentCondition eccmCondition = eccm?.Condition ??
            side.Ship.GetComponent("eccm").Condition;
        ComponentCondition activeSensorCondition =
            side.Ship.GetComponent("active-sensors").Condition;
        return new TacticalObservableStateSignature(
            opponentEcmEmissionObserved,
            opponentActiveSensorEmissionObserved,
            eccmCondition,
            activeSensorCondition);
    }

    private static Tl1IntegratedSensorOverloadPolicy AdaptiveSensorOverloadPolicy(
        IntegratedSide side,
        TacticalCombatBlackboard blackboard,
        int currentRange,
        bool closureExhausted,
        TacticalObservableStateSignature observableState,
        int eccmFallbackRating)
    {
        if (!blackboard.ContactEstablished || !closureExhausted ||
            blackboard.LastTrackQuality is null or TacticalTrackQuality.Firm)
        {
            return Tl1IntegratedSensorOverloadPolicy.None;
        }
        if (side.ActiveSensorStrain + ActiveSensorOverloadProfile.Tl1.StrainCost >
            ActiveSensorOverloadProfile.Tl1.StrainLimit)
        {
            blackboard.RecordSafeStrainExhausted(
                TacticalEscalationKind.ActiveSensorOverload);
            return Tl1IntegratedSensorOverloadPolicy.None;
        }
        if (!blackboard.CanAttemptOverload(
                TacticalEscalationKind.ActiveSensorOverload,
                currentRange,
                observableState))
        {
            return Tl1IntegratedSensorOverloadPolicy.None;
        }

        FunctionalEwInstallation? eccm = ResolveFunctionalEwInstallation(
            side, isEcm: false, eccmFallbackRating);
        bool eccmIsStillThePreferredEscalation =
            blackboard.LastFirmTrackDegradedByObservedEcm &&
            eccm is not null &&
            eccm.Condition == ComponentCondition.Operational &&
            side.EccmStrain + 1 <= SafeEwOverloadStrainLimit &&
            side.Power.SpendablePower >= EwOverloadAdditionalPowerCost &&
            blackboard.CanAttemptOverload(
                TacticalEscalationKind.EccmOverload,
                currentRange,
                observableState);
        return eccmIsStillThePreferredEscalation
            ? Tl1IntegratedSensorOverloadPolicy.None
            : Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded;
    }

    private static AdaptiveEccmOverloadResult TryAdaptiveEccmOverload(
        IntegratedSide side,
        int currentEccmRating,
        int currentRange,
        TacticalCombatBlackboard blackboard,
        TacticalObservableStateSignature observableState,
        int eccmFallbackRating,
        IntegratedDiagnosticTelemetry diagnostics)
    {
        if (currentEccmRating <= 0 ||
            !blackboard.CanAttemptOverload(
                TacticalEscalationKind.EccmOverload,
                currentRange,
                observableState))
        {
            return new AdaptiveEccmOverloadResult(currentEccmRating, false);
        }

        FunctionalEwInstallation? installation = ResolveFunctionalEwInstallation(
            side, isEcm: false, eccmFallbackRating);
        if (installation is null ||
            installation.Condition != ComponentCondition.Operational)
        {
            return new AdaptiveEccmOverloadResult(currentEccmRating, false);
        }

        if (side.EccmStrain + 1 > SafeEwOverloadStrainLimit)
        {
            blackboard.RecordSafeStrainExhausted(
                TacticalEscalationKind.EccmOverload);
            return new AdaptiveEccmOverloadResult(currentEccmRating, false);
        }

        diagnostics.RecordEwOverloadRequest(side.Id, isEcm: false);
        if (side.Power.SpendablePower < EwOverloadAdditionalPowerCost)
        {
            diagnostics.RecordOverloadDeniedPower(side.Id);
            return new AdaptiveEccmOverloadResult(currentEccmRating, false);
        }

        side.Power.IncreasePoweredSystem(installation.ComponentId, EwOverloadAdditionalPowerCost);
        diagnostics.RecordEwPower(side.Id, isEcm: false, EwOverloadAdditionalPowerCost);
        side.EccmStrain++;
        diagnostics.RecordEwOverloadActivation(side.Id, isEcm: false);
        return new AdaptiveEccmOverloadResult(
            checked(currentEccmRating + EwOverloadRatingBonus),
            true);
    }

    private static TacticalTrackQuality ToPlayerTrackQuality(
        IntegratedTrackQuality quality) => quality switch
        {
            IntegratedTrackQuality.Firm => TacticalTrackQuality.Firm,
            IntegratedTrackQuality.Approximate => TacticalTrackQuality.Approximate,
            IntegratedTrackQuality.None => TacticalTrackQuality.Lost,
            _ => throw new ArgumentOutOfRangeException(nameof(quality)),
        };

    private static Tl1AiDoctrineDefinitionDocument ResolveAiDoctrine(
        LoadedTl1AiDoctrineRegistry? registry,
        string? doctrineId,
        string variantId,
        string side)
    {
        if (registry is null)
        {
            throw new InvalidOperationException(
                $"Variant '{variantId}' requires an AI doctrine registry for Side {side}.");
        }
        if (string.IsNullOrWhiteSpace(doctrineId) ||
            !registry.ById.TryGetValue(doctrineId, out Tl1AiDoctrineDefinitionDocument? doctrine))
        {
            throw new InvalidOperationException(
                $"Variant '{variantId}' references unknown Side {side} AI doctrine '{doctrineId}'.");
        }
        return doctrine;
    }

    private static bool EwComponentAvailable(IntegratedSide side, bool isEcm, int fallbackRating) =>
        ResolveFunctionalEwInstallation(side, isEcm, fallbackRating) is not null;

    private static int EffectiveRatedEwPowerCost(
        IntegratedSide side, string componentId, int baseNormalPowerCost,
        int normalRating, bool isEcm, int? fullStrengthNormalPowerCostOverride = null)
    {
        int normalPower = RatedEwNormalPowerCost(
            baseNormalPowerCost, normalRating, fullStrengthNormalPowerCostOverride);
        ShipComponentState component = side.Ship.GetComponent(componentId);
        return checked(normalPower +
            ComponentPerformance.AdditionalCommittedPower(
                isEcm ? ShipComponentKind.Ecm : ShipComponentKind.Eccm,
                component.Condition));
    }

    private static int RatedEwNormalPowerCost(
        int baseNormalPowerCost, int normalRating, int? fullStrengthNormalPowerCostOverride)
    {
        if (baseNormalPowerCost < 1 || normalRating < 1 || normalRating > 4 ||
            fullStrengthNormalPowerCostOverride is <= 0)
        {
            throw new InvalidOperationException("EW normal power cost/rating is outside the supported range.");
        }
        return fullStrengthNormalPowerCostOverride ?? checked(baseNormalPowerCost * normalRating);
    }

    internal static int EffectiveRatedEwPowerCostForSelfTest(
        int baseNormalPowerCost, int normalRating, int? fullStrengthNormalPowerCostOverride = null) =>
        RatedEwNormalPowerCost(baseNormalPowerCost, normalRating, fullStrengthNormalPowerCostOverride);

    private static ElectronicWarfareDoctrineContext BuildEwDoctrineContext(
        IntegratedSide side,
        IntegratedSide opponent,
        bool hasInboundMissile,
        int ecmBaseNormalPowerCost,
        int eccmBaseNormalPowerCost,
        int ecmNormalRating,
        int eccmNormalRating,
        int? ecmFullStrengthNormalPowerCostOverride,
        int? eccmFullStrengthNormalPowerCostOverride,
        bool firmTrackWasDegradedByObservedEcm)
    {
        FunctionalEwInstallation? ecm = ResolveFunctionalEwInstallation(side, isEcm: true, ecmNormalRating);
        FunctionalEwInstallation? eccm = ResolveFunctionalEwInstallation(side, isEcm: false, eccmNormalRating);
        return new ElectronicWarfareDoctrineContext(
            SpendableTacticalPower: side.Power.SpendablePower,
            EcmNormalPowerCost: ecm is null ? int.MaxValue : EffectiveRatedEwPowerCost(
                side, ecm.ComponentId, ecmBaseNormalPowerCost, ecm.Rating, isEcm: true,
                fullStrengthNormalPowerCostOverride: ecmFullStrengthNormalPowerCostOverride),
            EccmNormalPowerCost: eccm is null ? int.MaxValue : EffectiveRatedEwPowerCost(
                side, eccm.ComponentId, eccmBaseNormalPowerCost, eccm.Rating, isEcm: false,
                fullStrengthNormalPowerCostOverride: eccmFullStrengthNormalPowerCostOverride),
            ReadyOffensivePower: ReadyAttackPowerCost(side),
            PlannedPdsPower: PlannedPdsPower(side, opponent, hasInboundMissile),
            EcmAvailable: ecm is not null,
            EccmAvailable: eccm is not null,
            FirmTrackWasDegradedByObservedEcm: firmTrackWasDegradedByObservedEcm);
    }

    private static int AllocateDoctrineEcm(
        IntegratedSide side,
        IntegratedSide opponent,
        bool hasInboundMissile,
        Tl1AiDoctrineDefinitionDocument doctrine,
        int ecmNormalPowerCost,
        int eccmNormalPowerCost,
        int ecmNormalRating,
        int eccmNormalRating,
        int? ecmFullStrengthNormalPowerCostOverride,
        int? eccmFullStrengthNormalPowerCostOverride,
        IntegratedDiagnosticTelemetry diagnostics)
    {
        ElectronicWarfareDoctrineContext context = BuildEwDoctrineContext(
            side, opponent, hasInboundMissile, ecmNormalPowerCost,
            eccmNormalPowerCost, ecmNormalRating, eccmNormalRating,
            ecmFullStrengthNormalPowerCostOverride, eccmFullStrengthNormalPowerCostOverride,
            firmTrackWasDegradedByObservedEcm: false);
        if (!ElectronicWarfareDoctrineService.ShouldActivateEcm(
                doctrine.EcmHeuristic, context))
        {
            return 0;
        }
        return AllocateOperationalEcm(
            side, Tl1IntegratedEwPowerPolicy.Normal, ecmNormalPowerCost, diagnostics,
            normalRating: ecmNormalRating,
            fullStrengthNormalPowerCostOverride: ecmFullStrengthNormalPowerCostOverride);
    }

    private static int AllocateDoctrineEccm(
        IntegratedSide side,
        IntegratedSide opponent,
        bool hasInboundMissile,
        Tl1AiDoctrineDefinitionDocument doctrine,
        int ecmNormalPowerCost,
        int eccmNormalPowerCost,
        int ecmNormalRating,
        int eccmNormalRating,
        int? ecmFullStrengthNormalPowerCostOverride,
        int? eccmFullStrengthNormalPowerCostOverride,
        bool firmTrackWasDegradedByObservedEcm,
        IntegratedDiagnosticTelemetry diagnostics)
    {
        ElectronicWarfareDoctrineContext context = BuildEwDoctrineContext(
            side, opponent, hasInboundMissile, ecmNormalPowerCost,
            eccmNormalPowerCost, ecmNormalRating, eccmNormalRating,
            ecmFullStrengthNormalPowerCostOverride, eccmFullStrengthNormalPowerCostOverride,
            firmTrackWasDegradedByObservedEcm);
        if (!ElectronicWarfareDoctrineService.ShouldActivateEccm(
                doctrine.EccmHeuristic, context))
        {
            return 0;
        }
        return AllocateOperationalEccm(
            side, Tl1IntegratedEwPowerPolicy.Normal, eccmNormalPowerCost,
            reactiveNeeded: true, diagnostics, normalRating: eccmNormalRating,
            fullStrengthNormalPowerCostOverride: eccmFullStrengthNormalPowerCostOverride);
    }

    private static int AllocateEwSystem(
        IntegratedSide side,
        string componentId,
        bool installed,
        Tl1IntegratedEwPowerPolicy policy,
        int baseNormalPowerCost,
        ref int strain,
        IntegratedDiagnosticTelemetry diagnostics,
        bool isEcm,
        int normalRating = 1,
        int? fullStrengthNormalPowerCostOverride = null)
    {
        if (!installed || policy == Tl1IntegratedEwPowerPolicy.None)
        {
            return 0;
        }
        if (baseNormalPowerCost < 1)
        {
            throw new InvalidOperationException(
                $"{componentId} normal Tactical Power cost must be positive.");
        }
        if (normalRating < 1 || normalRating > 4)
        {
            throw new InvalidOperationException(
                $"{componentId} normal rating must be between 1 and 4.");
        }

        ShipComponentState component = side.Ship.GetComponent(componentId);
        if (component.Condition is ComponentCondition.Disabled or ComponentCondition.Destroyed)
        {
            return 0;
        }

        bool overloadRequested = policy == Tl1IntegratedEwPowerPolicy.SafeOverload;
        if (overloadRequested)
        {
            diagnostics.RecordEwOverloadRequest(side.Id, isEcm);
        }

        int normalPower = checked(RatedEwNormalPowerCost(
                baseNormalPowerCost, normalRating, fullStrengthNormalPowerCostOverride) +
            ComponentPerformance.AdditionalCommittedPower(
                isEcm ? ShipComponentKind.Ecm : ShipComponentKind.Eccm,
                component.Condition));
        if (side.Power.SpendablePower < normalPower)
        {
            if (overloadRequested)
            {
                diagnostics.RecordOverloadDeniedPower(side.Id);
            }
            return 0;
        }

        side.Power.IncreasePoweredSystem(componentId, normalPower);
        diagnostics.RecordEwPower(side.Id, isEcm, normalPower);
        int rating = normalRating;

        if (overloadRequested && component.Condition == ComponentCondition.Operational)
        {
            if (strain + 1 > SafeEwOverloadStrainLimit)
            {
                diagnostics.RecordOverloadDeniedStrain(side.Id);
            }
            else if (side.Power.SpendablePower < EwOverloadAdditionalPowerCost)
            {
                diagnostics.RecordOverloadDeniedPower(side.Id);
            }
            else
            {
                side.Power.IncreasePoweredSystem(componentId, EwOverloadAdditionalPowerCost);
                diagnostics.RecordEwPower(side.Id, isEcm, EwOverloadAdditionalPowerCost);
                strain++;
                rating = checked(rating + EwOverloadRatingBonus);
                diagnostics.RecordEwOverloadActivation(side.Id, isEcm);
            }
        }

        return rating;
    }

    private static TacticalDecisionContext BuildDecisionContext(
        int turn,
        int currentRange,
        IntegratedSide own,
        IntegratedSide target,
        IReadOnlyList<IntegratedMissile> missiles,
        TacticalPreviousTurnOutcome previous,
        Tl1IntegratedMovementMode movementMode,
        Tl1OperationalTrackPolicy trackPolicy,
        int netEwRangePenalty,
        Tl1SensorEnvelope sensorEnvelope,
        Tl1IntegratedSensorOverloadPolicy sensorOverloadPolicy =
            Tl1IntegratedSensorOverloadPolicy.None,
        int? movementOverride = null,
        TacticalCombatBlackboard? combatBlackboard = null,
        bool? targetKnownOverride = null)
    {
        RangeDecisionDoctrine doctrine = DoctrineFor(own.Family);
        if (movementMode == Tl1IntegratedMovementMode.TrackAwareOpponentRange)
        {
            doctrine = TrackAwareDoctrineFor(
                own,
                doctrine,
                trackPolicy,
                netEwRangePenalty,
                sensorEnvelope,
                sensorOverloadPolicy);
        }
        else if (movementMode == Tl1IntegratedMovementMode.EngageAdaptive)
        {
            int ownMaximumRange = WeaponMaximumRange(own);
            doctrine = new RangeDecisionDoctrine(
                preferredMinimumRangeHexes: 0,
                preferredMaximumRangeHexes: ownMaximumRange,
                maximumUsefulWeaponRangeHexes: ownMaximumRange,
                withdrawWhenDisarmed: true);
        }

        bool targetKnown = targetKnownOverride ?? true;
        TacticalShipDecisionSnapshot ownSnapshot = movementMode == Tl1IntegratedMovementMode.EngageAdaptive
            ? new TacticalShipDecisionSnapshot(
                own.Id,
                own.Ship.GetComponent("stl").Condition,
                movementOverride ?? own.NormalStlMovement,
                HasUsableOffense(own),
                0,
                WeaponMaximumRange(own))
            : BuildTacticalSnapshot(own, movementOverride);
        ObservedTargetSnapshot observedTarget = movementMode == Tl1IntegratedMovementMode.EngageAdaptive
            ? new ObservedTargetSnapshot(
                target.Id,
                targetKnown,
                false,
                combatBlackboard?.MaximumObservedOpponentAttackRangeHexes is not null,
                0,
                combatBlackboard?.MaximumObservedOpponentAttackRangeHexes ?? 0)
            : new ObservedTargetSnapshot(
                target.Id,
                true,
                target.Ship.GetComponent("stl").Condition is
                    ComponentCondition.Disabled or ComponentCondition.Destroyed,
                HasUsableOffense(target),
                DoctrineFor(target.Family).PreferredMinimumRangeHexes,
                DoctrineFor(target.Family).MaximumUsefulWeaponRangeHexes);

        return new TacticalDecisionContext(
            turn,
            ownSnapshot,
            observedTarget,
            currentRange,
            missiles.Select(missile => new ObservedMissileTrack(
                    missile.Id,
                    missile.OwnerId,
                    missile.Coordinate is HexCoord missileCoordinate &&
                            missile.LastPlannedTargetCoordinate is HexCoord targetCoordinate
                        ? missileCoordinate.DistanceTo(targetCoordinate)
                        : Math.Abs(missile.LastPlannedTargetPosition - missile.Position),
                    missile.TargetId == own.Id))
                .ToArray(),
            movementMode == Tl1IntegratedMovementMode.ScriptedPursuit &&
                own.Id == "B"
                    ? TacticalObjective.Withdraw
                    : TacticalObjective.Engage,
            doctrine,
            previous,
            combatBlackboard);
    }

    private static RangeDecisionDoctrine TrackAwareDoctrineFor(
        IntegratedSide side,
        RangeDecisionDoctrine weaponDoctrine,
        Tl1OperationalTrackPolicy trackPolicy,
        int netEwRangePenalty,
        Tl1SensorEnvelope sensorEnvelope,
        Tl1IntegratedSensorOverloadPolicy sensorOverloadPolicy)
    {
        int maximumFirmRange = MaximumFirmRangeForMovementPlan(
            side,
            trackPolicy,
            netEwRangePenalty,
            sensorEnvelope,
            sensorOverloadPolicy);
        int effectiveMaximum = Math.Min(
            weaponDoctrine.MaximumUsefulWeaponRangeHexes,
            maximumFirmRange);
        int preferredMinimum = Math.Min(
            weaponDoctrine.PreferredMinimumRangeHexes,
            effectiveMaximum);
        int preferredMaximum = Math.Min(
            weaponDoctrine.PreferredMaximumRangeHexes,
            effectiveMaximum);
        return new RangeDecisionDoctrine(
            preferredMinimum,
            preferredMaximum,
            effectiveMaximum,
            weaponDoctrine.WithdrawWhenDisarmed);
    }

    private static int MaximumFirmRangeForMovementPlan(
        IntegratedSide side,
        Tl1OperationalTrackPolicy trackPolicy,
        int netEwRangePenalty,
        Tl1SensorEnvelope sensorEnvelope,
        Tl1IntegratedSensorOverloadPolicy sensorOverloadPolicy)
    {
        if (trackPolicy == Tl1OperationalTrackPolicy.EstablishedFirm)
        {
            return int.MaxValue;
        }

        int passiveFirm = Math.Max(
            0, sensorEnvelope.PassiveFirmRange - netEwRangePenalty);
        if (trackPolicy == Tl1OperationalTrackPolicy.PassiveOnly)
        {
            return passiveFirm;
        }

        ShipComponentState activeSensor = side.Ship.GetComponent("active-sensors");
        bool installedAndFunctional = side.Build?.ActiveSensor == true &&
            (activeSensor.Condition is
                ComponentCondition.Operational or ComponentCondition.Degraded);
        if (!installedAndFunctional)
        {
            return passiveFirm;
        }

        int offensiveReserve = ReadyAttackPowerCost(side);
        int spendablePower = side.Power.SpendablePower;
        int sensorPowerBudget = offensiveReserve <= spendablePower
            ? Math.Max(0, spendablePower - offensiveReserve)
            : spendablePower;
        if (sensorEnvelope.SingleActiveMode)
        {
            int activeFirm = Math.Max(
                0, sensorEnvelope.ActiveLevel1FirmRange - netEwRangePenalty);
            ActiveSensorOverloadProfile overloadProfile =
                sensorEnvelope.ToOverloadProfile();
            if (sensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded &&
                activeSensor.Condition == ComponentCondition.Operational &&
                side.ActiveSensorStrain + overloadProfile.StrainCost <=
                    overloadProfile.StrainLimit &&
                sensorPowerBudget >= sensorEnvelope.NormalActivePowerCost +
                    overloadProfile.AdditionalTacticalPowerCost)
            {
                return checked(activeFirm + overloadProfile.FirmRangeBonus);
            }
            return sensorPowerBudget >= sensorEnvelope.NormalActivePowerCost
                ? activeFirm
                : passiveFirm;
        }
        int level2Firm = Math.Max(
            0, sensorEnvelope.ActiveLevel2FirmRange - netEwRangePenalty);
        if (sensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded &&
            activeSensor.Condition == ComponentCondition.Operational &&
            side.ActiveSensorStrain + ActiveSensorOverloadProfile.Tl1.StrainCost <=
                ActiveSensorOverloadProfile.Tl1.StrainLimit &&
            sensorPowerBudget >= sensorEnvelope.HighActivePowerCost +
                ActiveSensorOverloadProfile.Tl1.AdditionalTacticalPowerCost)
        {
            return checked(level2Firm + ActiveSensorOverloadProfile.Tl1.FirmRangeBonus);
        }
        int affordableActivePower = Math.Clamp(
            sensorPowerBudget, 0, sensorEnvelope.HighActivePowerCost);
        if (affordableActivePower >= sensorEnvelope.HighActivePowerCost)
        {
            return level2Firm;
        }
        return affordableActivePower >= sensorEnvelope.NormalActivePowerCost
            ? Math.Max(0, sensorEnvelope.ActiveLevel1FirmRange - netEwRangePenalty)
            : passiveFirm;
    }

    private static TacticalShipDecisionSnapshot BuildTacticalSnapshot(
        IntegratedSide side,
        int? movementOverride = null)
    {
        RangeDecisionDoctrine doctrine = DoctrineFor(side.Family);
        return new TacticalShipDecisionSnapshot(
            side.Id,
            side.Ship.GetComponent("stl").Condition,
            movementOverride ?? side.NormalStlMovement,
            HasUsableOffense(side),
            doctrine.PreferredMinimumRangeHexes,
            doctrine.MaximumUsefulWeaponRangeHexes);
    }

    private static ITacticalOrderPolicy CreatePolicy(
        Tl1IntegratedMovementMode mode,
        string side) => mode switch
        {
            Tl1IntegratedMovementMode.HoldRange2 or
            Tl1IntegratedMovementMode.HoldRange3 or
            Tl1IntegratedMovementMode.HoldRange4 or
            Tl1IntegratedMovementMode.HoldRange5 =>
                new ScriptedTacticalOrderPolicy(
                    new Dictionary<int, RangeOrder>(),
                    RangeOrder.Hold),
            Tl1IntegratedMovementMode.ScriptedPursuit =>
                new ScriptedTacticalOrderPolicy(
                    new Dictionary<int, RangeOrder>(),
                    side == "A" ? RangeOrder.Close : RangeOrder.Open),
            Tl1IntegratedMovementMode.PreferredRange =>
                new PreferredRangeTacticalPolicy(),
            Tl1IntegratedMovementMode.OpponentAwareRange or
            Tl1IntegratedMovementMode.TrackAwareOpponentRange =>
                new OpponentAwareRangeTacticalPolicy(),
            Tl1IntegratedMovementMode.EngageAdaptive =>
                new AdaptiveEngageTacticalPolicy(),
            _ => throw new ArgumentOutOfRangeException(nameof(mode)),
        };

    private static RangeDecisionDoctrine DoctrineFor(WeaponFamily family) => family switch
    {
        WeaponFamily.Kinetic => new RangeDecisionDoctrine(1, 2, 4),
        WeaponFamily.Energy => new RangeDecisionDoctrine(3, 4, 5),
        WeaponFamily.Missile => new RangeDecisionDoctrine(4, 6, 6),
        _ => throw new ArgumentOutOfRangeException(nameof(family)),
    };

    private static int InitialRange(Tl1IntegratedMovementMode mode) => mode switch
    {
        Tl1IntegratedMovementMode.HoldRange2 => 2,
        Tl1IntegratedMovementMode.HoldRange3 => 3,
        Tl1IntegratedMovementMode.HoldRange4 => 4,
        Tl1IntegratedMovementMode.HoldRange5 => 5,
        Tl1IntegratedMovementMode.ScriptedPursuit or
        Tl1IntegratedMovementMode.PreferredRange or
        Tl1IntegratedMovementMode.OpponentAwareRange or
        Tl1IntegratedMovementMode.TrackAwareOpponentRange => 4,
        Tl1IntegratedMovementMode.EngageAdaptive => 10,
        _ => throw new ArgumentOutOfRangeException(nameof(mode)),
    };

    private static DirectCommit CommitDirectAttack(
        IntegratedSide attacker,
        IntegratedSide target,
        int currentRange,
        bool attackerEvasive,
        bool targetEvasive,
        ShipCombatTurnSnapshot targetSnapshot,
        int roll,
        bool secondary = false,
        IntegratedTrackQuality trackQuality = IntegratedTrackQuality.Firm,
        bool allowsApproximateTrackFire = false,
        int tacticalComputerApproximateTrackAccuracyPenalty = 0)
    {
        if (secondary && !attacker.HasSecondaryWeapon)
        {
            return DirectCommit.None;
        }
        WeaponFamily family = WeaponFamilyForBay(attacker, secondary);
        if (family == WeaponFamily.Missile || attacker.Ship.IsDestroyed)
        {
            return DirectCommit.None;
        }
        if (currentRange > WeaponMaximumRange(attacker, secondary))
        {
            return DirectCommit.Prevented(
                WeaponActionPreventionReason.OutOfRange);
        }
        bool degradedTrackFire = trackQuality == IntegratedTrackQuality.Approximate &&
            allowsApproximateTrackFire;
        if (trackQuality != IntegratedTrackQuality.Firm && !degradedTrackFire)
        {
            return DirectCommit.Prevented(
                WeaponActionPreventionReason.TrackUnavailable);
        }
        if (degradedTrackFire && tacticalComputerApproximateTrackAccuracyPenalty <= 0)
        {
            throw new InvalidOperationException(
                "Approximate-track direct fire requires a positive Tactical Computer fire-control penalty.");
        }
        ShipComponentState weapon = attacker.Ship.GetComponent(
            WeaponComponentId(secondary));
        ConditionedWeaponPerformance performance = ComponentPerformance.Weapon(
            family,
            weapon.Condition,
            NormalDamage(attacker, secondary),
            NormalPowerCost(attacker, secondary),
            damagePointScale: DamagePointScale.Legacy);
        if (!performance.CanFire)
        {
            return DirectCommit.Prevented(
                WeaponActionPreventionReason.SystemUnavailable);
        }
        bool recycling = secondary
            ? attacker.SecondaryRecycleThisTurn
            : attacker.RecycleThisTurn;
        if (recycling)
        {
            return DirectCommit.Prevented(
                WeaponActionPreventionReason.Recycling);
        }
        if (!SupportAvailable(attacker, secondary))
        {
            return DirectCommit.Prevented(
                WeaponActionPreventionReason.SupportUnavailable);
        }
        if (attacker.Power.SpendablePower < performance.TacticalPowerCost)
        {
            return DirectCommit.Prevented(
                WeaponActionPreventionReason.InsufficientPower);
        }

        SpendAttackPower(attacker.Power, performance.TacticalPowerCost);
        ConsumeAmmunition(attacker, secondary);
        if (secondary)
        {
            attacker.SecondaryRecycleNextTurn =
                performance.RequiresFullRecycleTurnAfterFire;
        }
        else
        {
            attacker.RecycleNextTurn =
                performance.RequiresFullRecycleTurnAfterFire;
        }
        int computerBonus = ComponentPerformance.TargetingComputerBonus(
            attacker.Technology.TargetingBonus,
            attacker.Ship.GetComponent("targeting-computer").Condition);
        int targetEvasivePenalty = ComponentPerformance.EvasiveDefenseBonus(
            10,
            target.Ship.GetComponent("evm").Condition);
        int shooterEvasivePenalty =
            ComponentPerformance.EvasiveAttackPenaltyMagnitude(
                5,
                attacker.Ship.GetComponent("evm").Condition);
        shooterEvasivePenalty = ApplyEvasiveCompensationForSelfTest(
            shooterEvasivePenalty,
            attacker.Build?.TacticalComputerEvasiveCompensation ?? 0,
            attacker.Ship.GetComponent("targeting-computer").Condition);
        var accuracyProfile = new DirectFireAccuracyProfile(
            baseChance: 50,
            weaponAccuracy: attacker.Technology.Weapon(family).AccuracyBonus,
            targetingComputerBonus: computerBonus,
            rangePenaltyPerHex: 5,
            targetEvasivePenalty: targetEvasivePenalty,
            shooterEvasivePenalty: shooterEvasivePenalty);
        DirectFireAccuracyResult accuracy = DirectFireAccuracyCalculator.Calculate(
            accuracyProfile,
            currentRange,
            targetEvasive,
            attackerEvasive,
            otherModifiers: degradedTrackFire
                ? -tacticalComputerApproximateTrackAccuracyPenalty
                : 0,
            targetStlCondition: targetSnapshot.StlCondition);
        bool hit = DirectFireHitResolver.IsHit(
            DirectFireHitResolver.Resolve(roll, accuracy.FinalChance));
        return new DirectCommit(
            true,
            true,
            hit,
            PacketFor(attacker, performance.Damage, secondary),
            accuracy.TargetMobilityBonus,
            accuracy.FinalChance,
            WeaponActionPreventionReason.None);
    }

    private static MissileLaunchCommit CommitMissileLaunch(
        IntegratedSide attacker,
        IntegratedSide target,
        int attackerPosition,
        int targetPosition,
        ICollection<IntegratedMissile> missiles,
        bool secondary = false,
        bool hasFirmTrack = true,
        HexCoord? attackerCoordinate = null,
        HexCoord? targetCoordinate = null)
    {
        if (secondary && !attacker.HasSecondaryWeapon)
        {
            return MissileLaunchCommit.None;
        }
        WeaponFamily family = WeaponFamilyForBay(attacker, secondary);
        if (family != WeaponFamily.Missile || attacker.Ship.IsDestroyed)
        {
            return MissileLaunchCommit.None;
        }
        int launchRange = attackerCoordinate is HexCoord launchCoordinate &&
                targetCoordinate is HexCoord targetLaunchCoordinate
            ? launchCoordinate.DistanceTo(targetLaunchCoordinate)
            : Math.Abs(targetPosition - attackerPosition);
        if (launchRange > attacker.Technology.Missile.MaximumRange)
        {
            return MissileLaunchCommit.Prevented(
                WeaponActionPreventionReason.OutOfRange);
        }
        if (!hasFirmTrack)
        {
            return MissileLaunchCommit.Prevented(
                WeaponActionPreventionReason.TrackUnavailable);
        }
        ShipComponentState launcher = attacker.Ship.GetComponent(
            WeaponComponentId(secondary));
        ConditionedWeaponPerformance performance = ComponentPerformance.Weapon(
            WeaponFamily.Missile,
            launcher.Condition,
            NormalDamage(attacker, secondary),
            NormalPowerCost(attacker, secondary),
            damagePointScale: DamagePointScale.Legacy);
        if (!performance.CanFire)
        {
            return MissileLaunchCommit.Prevented(
                WeaponActionPreventionReason.SystemUnavailable);
        }
        bool recycling = secondary
            ? attacker.SecondaryRecycleThisTurn
            : attacker.RecycleThisTurn;
        if (recycling)
        {
            return MissileLaunchCommit.Prevented(
                WeaponActionPreventionReason.Recycling);
        }
        if (!SupportAvailable(attacker, secondary))
        {
            return MissileLaunchCommit.Prevented(
                WeaponActionPreventionReason.SupportUnavailable);
        }
        if (attacker.Power.SpendablePower < performance.TacticalPowerCost)
        {
            return MissileLaunchCommit.Prevented(
                WeaponActionPreventionReason.InsufficientPower);
        }

        SpendAttackPower(attacker.Power, performance.TacticalPowerCost);
        ConsumeAmmunition(attacker, secondary);
        if (secondary)
        {
            attacker.SecondaryRecycleNextTurn =
                performance.RequiresFullRecycleTurnAfterFire;
        }
        else
        {
            attacker.RecycleNextTurn =
                performance.RequiresFullRecycleTurnAfterFire;
        }
        int conditionedTargeting = ComponentPerformance.TargetingComputerBonus(
            attacker.Technology.TargetingBonus,
            attacker.Ship.GetComponent("targeting-computer").Condition);
        int guidance = Math.Clamp(
            attacker.Technology.Missile.GuidanceChance +
                conditionedTargeting - attacker.Technology.TargetingBonus,
            5,
            95);
        missiles.Add(new IntegratedMissile(
            $"{attacker.Id}-m-{attacker.MissilesLaunched + 1}",
            attacker.Id,
            target.Id,
            attackerPosition,
            targetPosition,
            performance.Damage,
            attacker.Technology.Missile.ShieldPenetration,
            attacker.Technology.Missile.ArmorPenetration,
            guidance,
            attacker.Technology.MissileMove,
            attacker.Technology.Missile.MaximumRange,
            attacker.Build?.StandardOnboardMissileNavigationSensor ?? false,
            attackerCoordinate,
            targetCoordinate));
        attacker.MissilesLaunched++;
        return new MissileLaunchCommit(
            true,
            true,
            WeaponActionPreventionReason.None);
    }

    private static MissileTurnResult AdvanceMissiles(
        List<IntegratedMissile> missiles,
        IntegratedSide sideA,
        IntegratedSide sideB,
        int positionA,
        int positionB,
        ShipCombatTurnSnapshot snapshotA,
        ShipCombatTurnSnapshot snapshotB,
        TurnSystems systemsA,
        TurnSystems systemsB,
        DeterministicRandomStream pdsRandom,
        DeterministicRandomStream attackRandom,
        IntegratedDiagnosticTelemetry diagnostics,
        HexMap? tacticalMap = null,
        HexCoord? coordinateA = null,
        HexCoord? coordinateB = null)
    {
        if (tacticalMap is not null && coordinateA is HexCoord finiteA &&
            coordinateB is HexCoord finiteB)
        {
            return AdvanceMissilesFiniteMap(
                missiles, sideA, sideB, tacticalMap, finiteA, finiteB,
                snapshotA, snapshotB, systemsA, systemsB, pdsRandom,
                attackRandom, diagnostics);
        }

        if (sideA.Build is null && sideB.Build is null)
        {
            return AdvanceMissilesLegacy(
                missiles, sideA, sideB, positionA, positionB, snapshotA, snapshotB,
                systemsA, systemsB, pdsRandom, attackRandom, diagnostics);
        }

        int distanceTraveled = 0;
        int maximumObserved = 0;
        int terminalAttacks = 0;
        int hits = 0;
        int rangeExhausted = 0;
        int pdsAttempts = 0;
        int pdsIntercepts = 0;
        int immobileBonusAttacks = 0;
        int sameTurnViolations = 0;
        int criticalSelections = 0;
        int consequentialSteps = 0;
        bool mobilityLoss = false;
        var terminalMissiles = new List<IntegratedMissile>();

        foreach (IntegratedMissile missile in missiles.ToArray())
        {
            IntegratedSide target = missile.TargetId == "A" ? sideA : sideB;
            if (target.Ship.IsDestroyed)
            {
                missiles.Remove(missile);
                continue;
            }
            int targetPosition = missile.TargetId == "A" ? positionA : positionB;
            missile.LastPlannedTargetPosition = targetPosition;
            int distance = Math.Abs(targetPosition - missile.Position);
            int remainingRange = missile.MaximumTravelHexes - missile.DistanceTraveled;
            int step = Math.Min(missile.SpeedHexesPerTurn, Math.Min(distance, remainingRange));
            if (step > 0)
            {
                missile.Position += Math.Sign(targetPosition - missile.Position) * step;
                missile.DistanceTraveled += step;
                distanceTraveled += step;
                maximumObserved = Math.Max(maximumObserved, missile.DistanceTraveled);
            }
            distance = Math.Abs(targetPosition - missile.Position);
            if (distance > 0 && missile.DistanceTraveled >= missile.MaximumTravelHexes)
            {
                rangeExhausted++;
                missiles.Remove(missile);
                continue;
            }
            if (distance == 0)
            {
                terminalMissiles.Add(missile);
            }
        }

        terminalAttacks = terminalMissiles.Count;
        var intercepted = new HashSet<string>(StringComparer.Ordinal);
        ApplyComposedShipPds(
            terminalMissiles, "A", sideA, systemsA, pdsRandom, intercepted,
            ref pdsAttempts, ref pdsIntercepts);
        ApplyComposedShipPds(
            terminalMissiles, "B", sideB, systemsB, pdsRandom, intercepted,
            ref pdsAttempts, ref pdsIntercepts);

        foreach (IntegratedMissile missile in terminalMissiles)
        {
            IntegratedSide target = missile.TargetId == "A" ? sideA : sideB;
            TurnSystems targetSystems = missile.TargetId == "A" ? systemsA : systemsB;
            ShipCombatTurnSnapshot targetSnapshot = missile.TargetId == "A"
                ? snapshotA
                : snapshotB;
            if (!intercepted.Contains(missile.Id) && !target.Ship.IsDestroyed)
            {
                int mobilityBonus = ComponentPerformance.TargetMobilityAccuracyBonus(
                    targetSnapshot.StlCondition);
                int chance = Math.Clamp(
                    missile.GuidanceChance -
                        (targetSystems.EvasiveActive ? 10 : 0) +
                        mobilityBonus,
                    5,
                    95);
                if (mobilityBonus > 0)
                {
                    immobileBonusAttacks++;
                }
                if (!targetSnapshot.IsImmobile && mobilityBonus != 0)
                {
                    sameTurnViolations++;
                }
                diagnostics.RecordMissileTerminalAttack(chance);
                if (attackRandom.NextD100() <= chance)
                {
                    DamageApplication damage = ApplyPacket(
                        target,
                        new AttackPacket(
                            missile.Damage,
                            missile.ShieldPenetration,
                            missile.ArmorPenetration));
                    hits++;
                    diagnostics.MissileTerminalHits++;
                    diagnostics.RecordDamage(damage);
                    criticalSelections += damage.CriticalSelections;
                    consequentialSteps += damage.ConsequentialConditionStep ? 1 : 0;
                    mobilityLoss |= damage.StlBecameImmobileThisTurn;
                }
            }
            missiles.Remove(missile);
        }

        return new MissileTurnResult(
            distanceTraveled,
            maximumObserved,
            terminalAttacks,
            hits,
            rangeExhausted,
            pdsAttempts,
            pdsIntercepts,
            immobileBonusAttacks,
            sameTurnViolations,
            criticalSelections,
            consequentialSteps,
            mobilityLoss);
    }

    private static MissileTurnResult AdvanceMissilesFiniteMap(
        List<IntegratedMissile> missiles,
        IntegratedSide sideA,
        IntegratedSide sideB,
        HexMap map,
        HexCoord coordinateA,
        HexCoord coordinateB,
        ShipCombatTurnSnapshot snapshotA,
        ShipCombatTurnSnapshot snapshotB,
        TurnSystems systemsA,
        TurnSystems systemsB,
        DeterministicRandomStream pdsRandom,
        DeterministicRandomStream attackRandom,
        IntegratedDiagnosticTelemetry diagnostics)
    {
        int distanceTraveled = 0;
        int maximumObserved = 0;
        int terminalAttacks = 0;
        int hits = 0;
        int rangeExhausted = 0;
        int pdsAttempts = 0;
        int pdsIntercepts = 0;
        int immobileBonusAttacks = 0;
        int sameTurnViolations = 0;
        int criticalSelections = 0;
        int consequentialSteps = 0;
        bool mobilityLoss = false;
        var terminalMissiles = new List<IntegratedMissile>();

        foreach (IntegratedMissile missile in missiles.ToArray())
        {
            IntegratedSide target = missile.TargetId == "A" ? sideA : sideB;
            if (target.Ship.IsDestroyed)
            {
                missiles.Remove(missile);
                continue;
            }

            HexCoord targetCoordinate = missile.TargetId == "A"
                ? coordinateA
                : coordinateB;
            missile.LastPlannedTargetCoordinate = targetCoordinate;
            if (missile.Coordinate is not HexCoord missileCoordinate)
            {
                throw new InvalidOperationException(
                    "Finite-map missile is missing an authoritative coordinate.");
            }

            FiniteMissileAdvance advance = FiniteMissileMovementResolver.Resolve(
                map,
                missileCoordinate,
                targetCoordinate,
                missile.SpeedHexesPerTurn,
                missile.MaximumTravelHexes,
                missile.DistanceTraveled);
            missileCoordinate = advance.Destination;
            missile.DistanceTraveled = advance.TotalDistanceTraveled;
            distanceTraveled += advance.DistanceTraveledThisPhase;
            maximumObserved = Math.Max(maximumObserved, missile.DistanceTraveled);
            missile.Coordinate = missileCoordinate;

            if (advance.RangeExhausted)
            {
                rangeExhausted++;
                missiles.Remove(missile);
                continue;
            }
            if (advance.Terminal)
            {
                terminalMissiles.Add(missile);
            }
        }

        terminalAttacks = terminalMissiles.Count;
        var intercepted = new HashSet<string>(StringComparer.Ordinal);
        ApplyComposedShipPds(
            terminalMissiles, "A", sideA, systemsA, pdsRandom, intercepted,
            ref pdsAttempts, ref pdsIntercepts);
        ApplyComposedShipPds(
            terminalMissiles, "B", sideB, systemsB, pdsRandom, intercepted,
            ref pdsAttempts, ref pdsIntercepts);

        foreach (IntegratedMissile missile in terminalMissiles)
        {
            IntegratedSide target = missile.TargetId == "A" ? sideA : sideB;
            TurnSystems targetSystems = missile.TargetId == "A" ? systemsA : systemsB;
            ShipCombatTurnSnapshot targetSnapshot = missile.TargetId == "A"
                ? snapshotA
                : snapshotB;
            if (!intercepted.Contains(missile.Id) && !target.Ship.IsDestroyed)
            {
                int mobilityBonus = ComponentPerformance.TargetMobilityAccuracyBonus(
                    targetSnapshot.StlCondition);
                int chance = Math.Clamp(
                    missile.GuidanceChance -
                        (targetSystems.EvasiveActive ? 10 : 0) +
                        mobilityBonus,
                    5,
                    95);
                if (mobilityBonus > 0)
                {
                    immobileBonusAttacks++;
                }
                if (!targetSnapshot.IsImmobile && mobilityBonus != 0)
                {
                    sameTurnViolations++;
                }
                diagnostics.RecordMissileTerminalAttack(chance);
                if (attackRandom.NextD100() <= chance)
                {
                    DamageApplication damage = ApplyPacket(
                        target,
                        new AttackPacket(
                            missile.Damage,
                            missile.ShieldPenetration,
                            missile.ArmorPenetration));
                    hits++;
                    diagnostics.MissileTerminalHits++;
                    diagnostics.RecordDamage(damage);
                    criticalSelections += damage.CriticalSelections;
                    consequentialSteps += damage.ConsequentialConditionStep ? 1 : 0;
                    mobilityLoss |= damage.StlBecameImmobileThisTurn;
                }
            }
            missiles.Remove(missile);
        }

        return new MissileTurnResult(
            distanceTraveled,
            maximumObserved,
            terminalAttacks,
            hits,
            rangeExhausted,
            pdsAttempts,
            pdsIntercepts,
            immobileBonusAttacks,
            sameTurnViolations,
            criticalSelections,
            consequentialSteps,
            mobilityLoss);
    }

    private static void ApplyComposedShipPds(
        IReadOnlyList<IntegratedMissile> terminalMissiles,
        string targetId,
        IntegratedSide target,
        TurnSystems systems,
        DeterministicRandomStream pdsRandom,
        ISet<string> intercepted,
        ref int attempts,
        ref int intercepts)
    {
        if (!systems.PdsReady)
        {
            return;
        }

        var threats = terminalMissiles
            .Where(missile => missile.TargetId == targetId)
            .ToList();
        if (threats.Count == 0)
        {
            return;
        }

        int reactionIndex = 0;
        for (int sweep = 0; sweep < 2; sweep++)
        {
            var eligible = threats
                .Where(missile => !intercepted.Contains(missile.Id))
                .ToList();
            ShuffleDeterministically(eligible, pdsRandom);
            foreach (IntegratedMissile missile in eligible)
            {
                if (reactionIndex >= systems.PdsReactionComponentIds.Count)
                {
                    return;
                }
                if (target.PdsAmmunitionRemaining is int remaining && remaining <= 0)
                {
                    return;
                }

                string componentId = systems.PdsReactionComponentIds[reactionIndex++];
                target.PdsAttemptsThisTurn++;
                attempts++;
                int pdsChance = EffectivePdsChance(target, componentId);
                ConsumePdsAmmunition(target);
                if (pdsRandom.NextD100() <= pdsChance)
                {
                    intercepted.Add(missile.Id);
                    intercepts++;
                }
            }
        }
    }

    private static void ShuffleDeterministically<T>(
        IList<T> values,
        DeterministicRandomStream random)
    {
        for (int index = values.Count - 1; index > 0; index--)
        {
            int swapIndex = checked((int)(random.NextUInt64() % (ulong)(index + 1)));
            (values[index], values[swapIndex]) = (values[swapIndex], values[index]);
        }
    }

    private static MissileTurnResult AdvanceMissilesLegacy(
        List<IntegratedMissile> missiles,
        IntegratedSide sideA,
        IntegratedSide sideB,
        int positionA,
        int positionB,
        ShipCombatTurnSnapshot snapshotA,
        ShipCombatTurnSnapshot snapshotB,
        TurnSystems systemsA,
        TurnSystems systemsB,
        DeterministicRandomStream pdsRandom,
        DeterministicRandomStream attackRandom,
        IntegratedDiagnosticTelemetry diagnostics)
    {
        int distanceTraveled = 0;
        int maximumObserved = 0;
        int terminalAttacks = 0;
        int hits = 0;
        int rangeExhausted = 0;
        int pdsAttempts = 0;
        int pdsIntercepts = 0;
        int immobileBonusAttacks = 0;
        int sameTurnViolations = 0;
        int criticalSelections = 0;
        int consequentialSteps = 0;
        bool mobilityLoss = false;

        foreach (IntegratedMissile missile in missiles.ToArray())
        {
            IntegratedSide target = missile.TargetId == "A" ? sideA : sideB;
            if (target.Ship.IsDestroyed)
            {
                missiles.Remove(missile);
                continue;
            }
            int targetPosition = missile.TargetId == "A" ? positionA : positionB;
            missile.LastPlannedTargetPosition = targetPosition;
            int distance = Math.Abs(targetPosition - missile.Position);
            int remainingRange = missile.MaximumTravelHexes - missile.DistanceTraveled;
            int step = Math.Min(missile.SpeedHexesPerTurn, Math.Min(distance, remainingRange));
            if (step > 0)
            {
                missile.Position += Math.Sign(targetPosition - missile.Position) * step;
                missile.DistanceTraveled += step;
                distanceTraveled += step;
                maximumObserved = Math.Max(maximumObserved, missile.DistanceTraveled);
            }
            distance = Math.Abs(targetPosition - missile.Position);
            if (distance > 0 && missile.DistanceTraveled >= missile.MaximumTravelHexes)
            {
                rangeExhausted++;
                missiles.Remove(missile);
                continue;
            }
            if (distance > 0)
            {
                continue;
            }

            terminalAttacks++;
            TurnSystems targetSystems = missile.TargetId == "A"
                ? systemsA
                : systemsB;
            ShipCombatTurnSnapshot targetSnapshot = missile.TargetId == "A"
                ? snapshotA
                : snapshotB;
            bool intercepted = false;
            if (targetSystems.PdsReady && target.PdsAttemptsThisTurn < 1)
            {
                target.PdsAttemptsThisTurn++;
                pdsAttempts++;
                int pdsChance = EffectivePdsChance(target, "pds");
                ConsumePdsAmmunition(target);
                intercepted = pdsRandom.NextD100() <= pdsChance;
                if (intercepted)
                {
                    pdsIntercepts++;
                }
            }
            if (!intercepted)
            {
                int mobilityBonus = ComponentPerformance.TargetMobilityAccuracyBonus(
                    targetSnapshot.StlCondition);
                int chance = Math.Clamp(
                    missile.GuidanceChance -
                        (targetSystems.EvasiveActive ? 10 : 0) +
                        mobilityBonus,
                    5,
                    95);
                if (mobilityBonus > 0)
                {
                    immobileBonusAttacks++;
                }
                if (!targetSnapshot.IsImmobile && mobilityBonus != 0)
                {
                    sameTurnViolations++;
                }
                diagnostics.RecordMissileTerminalAttack(chance);
                if (attackRandom.NextD100() <= chance)
                {
                    DamageApplication damage = ApplyPacket(
                        target,
                        new AttackPacket(
                            missile.Damage,
                            missile.ShieldPenetration,
                            missile.ArmorPenetration));
                    hits++;
                    diagnostics.MissileTerminalHits++;
                    diagnostics.RecordDamage(damage);
                    criticalSelections += damage.CriticalSelections;
                    consequentialSteps += damage.ConsequentialConditionStep ? 1 : 0;
                    mobilityLoss |= damage.StlBecameImmobileThisTurn;
                }
            }
            missiles.Remove(missile);
        }

        return new MissileTurnResult(
            distanceTraveled,
            maximumObserved,
            terminalAttacks,
            hits,
            rangeExhausted,
            pdsAttempts,
            pdsIntercepts,
            immobileBonusAttacks,
            sameTurnViolations,
            criticalSelections,
            consequentialSteps,
            mobilityLoss);
    }


    private static DamageApplication ApplyDirectAttack(
        DirectCommit commitment,
        IntegratedSide target)
    {
        if (!commitment.Fired || !commitment.Hit)
        {
            return DamageApplication.None;
        }
        return ApplyPacket(target, commitment.Packet);
    }

    private static DamageApplication ApplyPacket(
        IntegratedSide target,
        AttackPacket packet)
    {
        ComponentCondition stlBefore = target.Ship.GetComponent("stl").Condition;
        ShipDamageResolution resolution = ShipDamageResolver.ResolvePacket(
            target.Ship,
            packet);
        SynchronizeSelectedAuxiliaryState(target);
        ComponentCondition stlAfter = target.Ship.GetComponent("stl").Condition;
        bool consequential = resolution.InternalEvents.Any(internalEvent =>
            internalEvent.Transition?.Changed == true &&
            internalEvent.Selection is not null &&
            IsConsequentialComponent(target.Ship.GetComponent(
                internalEvent.Selection.ComponentId).Definition.Kind));
        bool stlBecameImmobile =
            (stlBefore is ComponentCondition.Operational or ComponentCondition.Degraded) &&
            (stlAfter is ComponentCondition.Disabled or ComponentCondition.Destroyed);
        LayeredDamageResolution layered = resolution.LayeredDamage;
        return new DamageApplication(
            resolution.InternalEvents.Count(internalEvent =>
                internalEvent.Selection is not null),
            consequential,
            stlBecameImmobile,
            layered.ShieldAbsorption,
            layered.ShieldArmorPrevented,
            layered.ArmorLayers.Sum(layer => layer.DamagePrevented),
            layered.ArmorLayers.Sum(layer => layer.IntegrityDamage),
            layered.ArmorLayers.Sum(layer => layer.ProtectionDamage),
            layered.HullDamage);
    }

    private static void RecordDamage(
        int turn,
        DamageApplication damageToA,
        DamageApplication damageToB,
        ref int criticalSelections,
        ref int? firstCriticalTurn,
        ref int? firstConsequentialTurn,
        ref bool mobilityLossObserved,
        ref int sameTurnImmobileBonusViolations,
        DirectCommit directA,
        DirectCommit directB)
    {
        criticalSelections +=
            damageToA.CriticalSelections + damageToB.CriticalSelections;
        if (damageToA.CriticalSelections > 0 || damageToB.CriticalSelections > 0)
        {
            firstCriticalTurn ??= turn;
        }
        if (damageToA.ConsequentialConditionStep ||
            damageToB.ConsequentialConditionStep)
        {
            firstConsequentialTurn ??= turn;
        }
        mobilityLossObserved |= damageToA.StlBecameImmobileThisTurn ||
            damageToB.StlBecameImmobileThisTurn;
        if (damageToA.StlBecameImmobileThisTurn &&
            directB.TargetMobilityBonus != 0)
        {
            sameTurnImmobileBonusViolations++;
        }
        if (damageToB.StlBecameImmobileThisTurn &&
            directA.TargetMobilityBonus != 0)
        {
            sameTurnImmobileBonusViolations++;
        }
    }

    private static DamageControlTurnResult AttemptDamageControl(
        IntegratedSide side,
        DeterministicRandomStream repairRandom)
    {
        DamageControlEligibility eligibility =
            DamageControlService.EvaluateEligibility(side.Ship, side.Power);
        if (!eligibility.CanAttempt)
        {
            return DamageControlTurnResult.None;
        }

        ShipComponentState? component = SelectComponentRepairTarget(side.Ship);
        if (component is not null)
        {
            if (component.Condition is not
                (ComponentCondition.Degraded or ComponentCondition.Disabled))
            {
                return new DamageControlTurnResult(0, 1);
            }
            DamageControlService.AttemptComponentRepair(
                side.Ship,
                component.Definition.Id,
                side.Power,
                DamageControlRoll(side, repairRandom));
            return new DamageControlTurnResult(1, 0);
        }

        bool reserveOne = side.Ship.DamageControl.RepairKitsRemaining <= 1;
        bool hullThresholdReached = side.Ship.Defense.CurrentHull <= side.Technology.Hull / 2;
        if (!reserveOne && hullThresholdReached && eligibility.HasRepairableHullDamage)
        {
            DamageControlService.AttemptHullRepair(
                side.Ship,
                side.Power,
                DamageControlRoll(side, repairRandom));
            return new DamageControlTurnResult(1, 0);
        }
        return DamageControlTurnResult.None;
    }

    private static ShipComponentState? SelectComponentRepairTarget(
        ShipDamageState ship) => ship.Components
        .Where(component => component.Condition is
            ComponentCondition.Degraded or ComponentCondition.Disabled)
        .OrderBy(component => RepairPriority(component.Definition.Kind))
        .ThenBy(component => component.Definition.Id, StringComparer.Ordinal)
        .FirstOrDefault();

    private static int RepairPriority(ShipComponentKind kind) => kind switch
    {
        ShipComponentKind.KineticWeapon or
        ShipComponentKind.EnergyWeapon or
        ShipComponentKind.MissileLauncher => 0,
        ShipComponentKind.KineticMagazine or
        ShipComponentKind.MissileMagazine or
        ShipComponentKind.PowerCapacitor => 1,
        ShipComponentKind.ShieldGenerator => 2,
        ShipComponentKind.MainReactor => 3,
        ShipComponentKind.StlDrive => 4,
        ShipComponentKind.TargetingComputer => 5,
        ShipComponentKind.PointDefense => 6,
        ShipComponentKind.EvasiveManeuverSystem => 7,
        _ => 10,
    };

    private static TerminalAssessment AssessTerminal(
        IntegratedSide sideA,
        IntegratedSide sideB,
        int currentRange,
        int disengagementProgressA,
        int disengagementProgressB)
    {
        bool destroyedA = sideA.Ship.IsDestroyed;
        bool destroyedB = sideB.Ship.IsDestroyed;
        if (destroyedA || destroyedB)
        {
            return new TerminalAssessment(
                true,
                DetermineWinner(destroyedA, destroyedB),
                IntegratedResolutionCause.Destruction);
        }

        bool offensiveA = IsOffensiveMissionKilled(sideA);
        bool offensiveB = IsOffensiveMissionKilled(sideB);
        if (offensiveA || offensiveB)
        {
            return new TerminalAssessment(
                true,
                DetermineWinner(offensiveA, offensiveB),
                IntegratedResolutionCause.OffensiveMissionKill);
        }

        bool disengagedA = disengagementProgressA >= DisengagementTurnsRequired;
        bool disengagedB = disengagementProgressB >= DisengagementTurnsRequired;
        if (disengagedA || disengagedB)
        {
            return new TerminalAssessment(
                true,
                disengagedA && disengagedB
                    ? IntegratedWinner.Mutual
                    : disengagedA
                        ? IntegratedWinner.SideA
                        : IntegratedWinner.SideB,
                IntegratedResolutionCause.Disengagement);
        }

        // A qualifying withdrawal owns the terminal outcome while its escape clock is
        // running. Otherwise the pursuing ship's inability to keep the withdrawing
        // target inside its current weapon envelope would be misclassified as a
        // mobility mission kill after the first out-of-range turn, before the explicit
        // three-turn disengagement rule could ever complete.
        bool mobilityA = disengagementProgressB == 0 &&
            IsMobilityMissionKilled(sideA, currentRange);
        bool mobilityB = disengagementProgressA == 0 &&
            IsMobilityMissionKilled(sideB, currentRange);
        if (mobilityA || mobilityB)
        {
            return new TerminalAssessment(
                true,
                DetermineWinner(mobilityA, mobilityB),
                IntegratedResolutionCause.MobilityMissionKill);
        }
        return TerminalAssessment.None;
    }

    private static IntegratedWinner DetermineWinner(bool terminalA, bool terminalB)
    {
        if (terminalA && terminalB)
        {
            return IntegratedWinner.Mutual;
        }
        return terminalA ? IntegratedWinner.SideB : IntegratedWinner.SideA;
    }

    private static IntegratedResolutionCause StrongerCause(
        IntegratedResolutionCause first,
        IntegratedResolutionCause second)
    {
        if (first == IntegratedResolutionCause.Destruction ||
            second == IntegratedResolutionCause.Destruction)
        {
            return IntegratedResolutionCause.Destruction;
        }
        if (first == IntegratedResolutionCause.OffensiveMissionKill ||
            second == IntegratedResolutionCause.OffensiveMissionKill)
        {
            return IntegratedResolutionCause.OffensiveMissionKill;
        }
        if (first == IntegratedResolutionCause.MobilityMissionKill ||
            second == IntegratedResolutionCause.MobilityMissionKill)
        {
            return IntegratedResolutionCause.MobilityMissionKill;
        }
        if (first == IntegratedResolutionCause.Disengagement ||
            second == IntegratedResolutionCause.Disengagement)
        {
            return IntegratedResolutionCause.Disengagement;
        }
        return IntegratedResolutionCause.Unresolved;
    }

    private static void UpdateDisengagementProgress(
        IntegratedCombatProfile profile,
        IntegratedSide withdrawingSide,
        IntegratedSide opponent,
        int currentRange,
        int withdrawingPosition,
        bool hasWithdrawalObjective,
        bool requestedOpen,
        IReadOnlyList<IntegratedMissile> missiles,
        ref int progress)
    {
        if (!profile.EscapeDisengagementEnabled ||
            !hasWithdrawalObjective ||
            !requestedOpen ||
            OpponentCanThreatenAtRange(opponent, currentRange) ||
            HasViableInboundMissile(withdrawingSide, withdrawingPosition, missiles))
        {
            progress = 0;
            return;
        }
        progress++;
    }

    private static bool OpponentCanThreatenAtRange(
        IntegratedSide opponent,
        int currentRange) =>
        HasUsableOffense(opponent) &&
        currentRange <= WeaponMaximumRange(opponent);

    private static bool HasViableInboundMissile(
        IntegratedSide side,
        int sidePosition,
        IReadOnlyList<IntegratedMissile> missiles) => missiles.Any(missile =>
        missile.TargetId == side.Id &&
        Math.Abs(sidePosition - missile.Position) <=
            missile.MaximumTravelHexes - missile.DistanceTraveled);

    private static bool IsOffensiveMissionKilled(IntegratedSide side)
    {
        if (HasUsableOffense(side))
        {
            return false;
        }
        return !side.Ship.PendingRepairs.Any(repair =>
            repair.Kind == PendingRepairKind.Component &&
            repair.ComponentId is string id &&
            side.Ship.GetComponent(id).Definition.Capabilities
                .HasFlag(ShipComponentCapability.Offense));
    }

    private static bool IsMobilityMissionKilled(
        IntegratedSide side,
        int currentRange)
    {
        bool immobile = side.Ship.GetComponent("stl").Condition is
            ComponentCondition.Disabled or ComponentCondition.Destroyed;
        if (!immobile || currentRange <= WeaponMaximumRange(side))
        {
            return false;
        }
        return !side.Ship.PendingRepairs.Any(repair =>
            repair.Kind == PendingRepairKind.Component &&
            repair.ComponentId == "stl");
    }

    private static bool HasUsableOffense(IntegratedSide side) =>
        HasUsableOffense(side, secondary: false) ||
        (side.HasSecondaryWeapon && HasUsableOffense(side, secondary: true));

    private static bool HasUsableOffense(IntegratedSide side, bool secondary)
    {
        ShipComponentState weapon = side.Ship.GetComponent(
            WeaponComponentId(secondary));
        return (weapon.Condition is
                ComponentCondition.Operational or ComponentCondition.Degraded) &&
            SupportAvailable(side, secondary);
    }

    private static bool SupportAvailable(IntegratedSide side) =>
        SupportAvailable(side, secondary: false);

    private static bool SupportAvailable(IntegratedSide side, bool secondary)
    {
        WeaponFamily family = WeaponFamilyForBay(side, secondary);
        ShipComponentState support = side.Ship.GetComponent(
            WeaponSupportComponentId(side, secondary));
        bool conditionAvailable = support.Condition is
            ComponentCondition.Operational or ComponentCondition.Degraded;
        if (!conditionAvailable)
        {
            return false;
        }
        return family == WeaponFamily.Energy || support.CurrentContents > 0;
    }

    private static void ConsumeAmmunition(IntegratedSide side) =>
        ConsumeAmmunition(side, secondary: false);

    private static void ConsumeAmmunition(IntegratedSide side, bool secondary)
    {
        WeaponFamily family = WeaponFamilyForBay(side, secondary);
        if (family != WeaponFamily.Energy)
        {
            side.Ship.GetComponent(WeaponSupportComponentId(side, secondary))
                .ConsumeContents(1);
        }
    }

    private static WeaponFamily WeaponFamilyForBay(
        IntegratedSide side,
        bool secondary) => secondary
            ? side.SecondaryFamily ?? throw new InvalidOperationException(
                "Secondary weapon family requested on a one-bay combat side.")
            : side.Family;

    private static string WeaponComponentId(bool secondary) =>
        secondary ? "secondary-weapon" : "main-weapon";

    private static string WeaponSupportComponentId(
        IntegratedSide side,
        bool secondary) => secondary &&
            (side.IndependentMainWeaponSupport || side.SecondaryFamily != side.Family)
                ? "secondary-support"
                : "weapon-support";

    private static int NormalDamage(IntegratedSide side) =>
        NormalDamage(side, secondary: false);

    private static int NormalDamage(IntegratedSide side, bool secondary) =>
        side.Technology.Weapon(WeaponFamilyForBay(side, secondary)).Damage;

    private static int NormalPowerCost(IntegratedSide side) =>
        NormalPowerCost(side, secondary: false);

    private static int NormalPowerCost(IntegratedSide side, bool secondary) =>
        side.Technology.Weapon(WeaponFamilyForBay(side, secondary)).PowerCost;

    private static AttackPacket PacketFor(IntegratedSide side, int damage) =>
        PacketFor(side, damage, secondary: false);

    private static AttackPacket PacketFor(
        IntegratedSide side,
        int damage,
        bool secondary)
    {
        ScalingWeaponProfile weapon = side.Technology.Weapon(
            WeaponFamilyForBay(side, secondary));
        return new AttackPacket(
            damage,
            weapon.ShieldPenetration,
            weapon.ArmorPenetration);
    }

    private static int WeaponMaximumRange(IntegratedSide side)
    {
        int maximum = WeaponMaximumRange(side, secondary: false);
        if (side.HasSecondaryWeapon)
        {
            maximum = Math.Max(
                maximum,
                WeaponMaximumRange(side, secondary: true));
        }
        return maximum;
    }

    private static int WeaponMaximumRange(
        IntegratedSide side,
        bool secondary) =>
        side.Technology.Weapon(WeaponFamilyForBay(side, secondary)).MaximumRange;

    private static bool IsConsequentialComponent(ShipComponentKind kind) => kind is
        ShipComponentKind.MainReactor or
        ShipComponentKind.AuxiliaryReactor or
        ShipComponentKind.StlDrive or
        ShipComponentKind.ShieldGenerator or
        ShipComponentKind.KineticWeapon or
        ShipComponentKind.EnergyWeapon or
        ShipComponentKind.MissileLauncher or
        ShipComponentKind.KineticMagazine or
        ShipComponentKind.MissileMagazine or
        ShipComponentKind.PowerCapacitor or
        ShipComponentKind.TargetingComputer or
        ShipComponentKind.PointDefense or
        ShipComponentKind.EvasiveManeuverSystem;

    private static bool SelectedAuxiliaryFunctional(IntegratedSide side) =>
        !side.Auxiliary.UsesSelectedComponent ||
        side.Ship.GetComponent("selected-aux").Condition is
            ComponentCondition.Operational or ComponentCondition.Degraded;

    private static bool IndependentPowerComponentFunctional(
        IntegratedSide side,
        string componentId) =>
        side.Ship.GetComponent(componentId).Condition is
            ComponentCondition.Operational or ComponentCondition.Degraded;

    private static void SynchronizeSelectedAuxiliaryState(IntegratedSide side)
    {
        if (!side.Auxiliary.HasShieldBooster)
        {
            return;
        }
        bool shieldGeneratorPresent = side.Ship.GetComponent(
            "shield-generator").Condition != ComponentCondition.Destroyed;
        bool functional = SelectedAuxiliaryFunctional(side) &&
            shieldGeneratorPresent;
        bool applied = side.Ship.Defense.TemporaryShieldOvercapacity > 0;
        if (functional && !applied)
        {
            side.Ship.Defense.AddTemporaryShieldOvercapacity(
                side.Auxiliary.ShieldCapacityBonus);
        }
        else if (!functional && applied)
        {
            side.Ship.Defense.ClearTemporaryShieldOvercapacity();
        }
    }

    private static int DamageControlRoll(
        IntegratedSide side,
        DeterministicRandomStream repairRandom)
    {
        int roll = repairRandom.NextD100();
        if (side.Auxiliary.HasRepairDrones &&
            !SelectedAuxiliaryFunctional(side))
        {
            roll = Math.Min(
                100,
                roll + side.Auxiliary.DamageControlChanceBonus);
        }
        return roll;
    }

    private static int CurrentReactorOutput(IntegratedSide side)
    {
        int main = side.Ship.Components
            .Where(component => component.Definition.Kind == ShipComponentKind.MainReactor)
            .Sum(component => component.Condition switch
            {
                ComponentCondition.Operational => side.ReactorOutputPerMain,
                ComponentCondition.Degraded => Math.Max(
                    1,
                    (int)Math.Ceiling(side.ReactorOutputPerMain * 0.6)),
                ComponentCondition.Disabled => 1,
                ComponentCondition.Destroyed => 0,
                _ => 0,
            });
        int auxiliary = 0;
        if (side.Auxiliary.HasAuxiliaryReactor && side.Build is null)
        {
            ComponentCondition condition =
                side.Ship.GetComponent("aux-reactor").Condition;
            auxiliary = side.Auxiliary.LegacyIntegratedSuite
                ? condition == ComponentCondition.Operational ? 1 : 0
                : condition switch
                {
                    ComponentCondition.Operational =>
                        side.Auxiliary.AuxiliaryReactorOutput,
                    ComponentCondition.Degraded => Math.Max(
                        1,
                        (int)Math.Ceiling(
                            side.Auxiliary.AuxiliaryReactorOutput * 0.5)),
                    _ => 0,
                };
        }
        return main + auxiliary;
    }

    internal static TechnologyCombatProfile ApplyTacticalComputerTargetingOverride(
        TechnologyCombatProfile technology,
        int? targetingBonusOverride)
    {
        if (targetingBonusOverride is not int targetingBonus)
        {
            return technology;
        }
        int localPdsBaseChance = technology.EffectivePdsChance - technology.TargetingBonus;
        return technology with
        {
            TargetingBonus = targetingBonus,
            EffectivePdsChance = Math.Clamp(localPdsBaseChance + targetingBonus, 0, 95),
        };
    }

    internal static TechnologyCombatProfile ApplyShieldCapacityOverride(
        TechnologyCombatProfile technology,
        int? shieldCapacityOverride)
    {
        if (shieldCapacityOverride is not int shieldCapacity)
        {
            return technology;
        }
        if (shieldCapacity < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(shieldCapacityOverride));
        }
        return technology with { ShieldCapacity = shieldCapacity };
    }

    internal static TechnologyCombatProfile ApplyArmorOverrides(
        TechnologyCombatProfile technology,
        int? armorIntegrityOverride,
        int? armorProtectionOverride)
    {
        if (armorIntegrityOverride is null && armorProtectionOverride is null)
        {
            return technology;
        }
        int armorIntegrity = armorIntegrityOverride ?? technology.ArmorIntegrity;
        int armorProtection = armorProtectionOverride ?? technology.ArmorProtection;
        if (armorIntegrity < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(armorIntegrityOverride));
        }
        if (armorProtection < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(armorProtectionOverride));
        }
        return technology with
        {
            ArmorIntegrity = armorIntegrity,
            ArmorProtection = armorProtection,
        };
    }

    private static IntegratedSide CreateSide(
        string id,
        WeaponFamily family,
        WeaponFamily? secondaryFamily,
        Tl1IntegratedTacticalCombatVariantDocument variant,
        IntegratedCombatProfile profile,
        Tl1IntegratedShipBuildDocument? build,
        ulong trackSeed,
        ulong exposureSeed)
    {
        TechnologyCombatProfile technology = id == "A"
            ? profile.SideA
            : profile.SideB;
        technology = ApplyTacticalComputerTargetingOverride(
            technology,
            id == "A"
                ? variant.SideATacticalComputerTargetingBonusOverride
                : variant.SideBTacticalComputerTargetingBonusOverride);
        AuxiliaryCombatProfile auxiliary = id == "A"
            ? profile.SideAAuxiliary
            : profile.SideBAuxiliary;
        if (family is not
            (WeaponFamily.Kinetic or WeaponFamily.Energy or WeaponFamily.Missile))
        {
            throw new ArgumentOutOfRangeException(nameof(family));
        }
        if (secondaryFamily is not null && secondaryFamily is not
            (WeaponFamily.Kinetic or WeaponFamily.Energy or WeaponFamily.Missile))
        {
            throw new ArgumentOutOfRangeException(nameof(secondaryFamily));
        }
        ShipComponentKind weaponKind = family switch
        {
            WeaponFamily.Kinetic => ShipComponentKind.KineticWeapon,
            WeaponFamily.Energy => ShipComponentKind.EnergyWeapon,
            WeaponFamily.Missile => ShipComponentKind.MissileLauncher,
            _ => throw new ArgumentOutOfRangeException(nameof(family)),
        };
        ShipComponentState support = family switch
        {
            WeaponFamily.Kinetic => Storage(
                "weapon-support",
                ShipComponentKind.KineticMagazine,
                1,
                (technology.Kinetic.Ammunition ?? 100) +
                    auxiliary.KineticAmmunitionBonus,
                ShipComponentCapability.Offense),
            WeaponFamily.Missile => Storage(
                "weapon-support",
                ShipComponentKind.MissileMagazine,
                1,
                (technology.Missile.Ammunition ?? MissileMagazineCapacity) +
                    auxiliary.MissileAmmunitionBonus,
                ShipComponentCapability.Offense),
            WeaponFamily.Energy => Component(
                "weapon-support",
                ShipComponentKind.PowerCapacitor,
                1,
                ShipComponentCapability.Offense),
            _ => throw new ArgumentOutOfRangeException(nameof(family)),
        };
        int mainReactorCount = build?.MainReactorCount ?? 1;
        bool shieldInstalled = build?.ShieldGenerator ?? true;
        bool sensorInstalled = build?.ActiveSensor ?? true;
        int pdsCount = build?.KineticPdsCount ?? (auxiliary.HasPds ? 1 : 0);
        bool pdsInstalled = pdsCount > 0;
        bool evmInstalled = build is null && (auxiliary.LegacyIntegratedSuite ||
            auxiliary.EvasiveManeuvers);
        bool auxReactorInstalled = build is null && auxiliary.HasAuxiliaryReactor;
        bool selectedAuxInstalled = !auxiliary.LegacyIntegratedSuite &&
            !auxiliary.Counterfactual && auxiliary.UsesSelectedComponent;
        ShipComponentKind selectedAuxKind = auxiliary.HasLegacySelectedPowerComponent &&
                auxiliary.CombatBatteryGain > 0
            ? ShipComponentKind.CombatBattery
            : auxiliary.HasLegacySelectedPowerComponent &&
                    auxiliary.CapacitorCapacity > 0
                ? ShipComponentKind.PowerCapacitor
                : auxiliary.HasShieldBattery
                    ? ShipComponentKind.ShieldBattery
                    : ShipComponentKind.GenericDamageableAuxiliary;
        var components = new List<ShipComponentState>
        {
            Component(
                "reactor",
                ShipComponentKind.MainReactor,
                2,
                ShipComponentCapability.PowerSource),
            Component(
                "stl",
                ShipComponentKind.StlDrive,
                2,
                ShipComponentCapability.StandardStlMovement),
            Component(
                "ftl",
                ShipComponentKind.FtlDrive,
                1,
                ShipComponentCapability.FtlDeparture),
            Component(
                "shield-generator",
                ShipComponentKind.ShieldGenerator,
                shieldInstalled ? 1 : 0,
                shieldInstalled
                    ? ShipComponentCapability.ActiveDefense
                    : ShipComponentCapability.None),
            Component(
                "main-weapon",
                weaponKind,
                1,
                ShipComponentCapability.Offense),
            support,
            Electronics("targeting-computer", ShipComponentKind.TargetingComputer),
            sensorInstalled
                ? Electronics("active-sensors", ShipComponentKind.ActiveSensors)
                : Component(
                    "active-sensors",
                    ShipComponentKind.ActiveSensors,
                    0,
                    ShipComponentCapability.None),
            build?.EcmSuite == true
                ? Electronics("ecm", ShipComponentKind.Ecm)
                : Component("ecm", ShipComponentKind.Ecm, 0, ShipComponentCapability.None),
            build?.EccmSuite == true
                ? Electronics("eccm", ShipComponentKind.Eccm)
                : Component("eccm", ShipComponentKind.Eccm, 0, ShipComponentCapability.None),
            Component(
                "pds",
                ShipComponentKind.PointDefense,
                pdsInstalled ? 1 : 0,
                pdsInstalled
                    ? ShipComponentCapability.ActiveDefense
                    : ShipComponentCapability.None),
            Component(
                "evm",
                ShipComponentKind.EvasiveManeuverSystem,
                evmInstalled ? 1 : 0,
                evmInstalled
                    ? ShipComponentCapability.ActiveDefense |
                        ShipComponentCapability.EvasiveManeuvers
                    : ShipComponentCapability.None),
            Component(
                "aux-reactor",
                ShipComponentKind.AuxiliaryReactor,
                auxReactorInstalled ? 1 : 0,
                auxReactorInstalled
                    ? ShipComponentCapability.PowerSource
                    : ShipComponentCapability.None),
            Component(
                "selected-aux",
                selectedAuxKind,
                selectedAuxInstalled ? 1 : 0,
                ShipComponentCapability.None),
            Component(
                "shield-hardener",
                ShipComponentKind.GenericDamageableAuxiliary,
                build?.ShieldHardener == true ? 1 : 0,
                build?.ShieldHardener == true
                    ? ShipComponentCapability.ActiveDefense
                    : ShipComponentCapability.None),
        };
        for (int reactorIndex = 2; reactorIndex <= mainReactorCount; reactorIndex++)
        {
            components.Add(Component(
                $"reactor-{reactorIndex}",
                ShipComponentKind.MainReactor,
                2,
                ShipComponentCapability.PowerSource));
        }
        for (int pdsIndex = 2; pdsIndex <= pdsCount; pdsIndex++)
        {
            components.Add(Component(
                $"pds-{pdsIndex}",
                ShipComponentKind.PointDefense,
                1,
                ShipComponentCapability.ActiveDefense));
        }
        if (build is not null)
        {
            for (int ecmIndex = 2; ecmIndex <= build.EcmSuiteRatings.Count; ecmIndex++)
            {
                components.Add(Electronics($"ecm-{ecmIndex}", ShipComponentKind.Ecm));
            }
            for (int eccmIndex = 2; eccmIndex <= build.EccmSuiteRatings.Count; eccmIndex++)
            {
                components.Add(Electronics($"eccm-{eccmIndex}", ShipComponentKind.Eccm));
            }
        }
        foreach (AuxiliaryPowerComponentProfile powerComponent in auxiliary.PowerComponents)
        {
            ShipComponentKind kind = powerComponent.Kind switch
            {
                AuxiliaryPowerComponentKind.CombatBattery => ShipComponentKind.CombatBattery,
                AuxiliaryPowerComponentKind.PowerCapacitor => ShipComponentKind.PowerCapacitor,
                _ => ShipComponentKind.GenericDamageableAuxiliary,
            };
            components.Add(Component(
                $"power-aux-{powerComponent.Id}",
                kind,
                1,
                ShipComponentCapability.None));
        }
        if (secondaryFamily is WeaponFamily installedSecondaryFamily)
        {
            ShipComponentKind secondaryWeaponKind = installedSecondaryFamily switch
            {
                WeaponFamily.Kinetic => ShipComponentKind.KineticWeapon,
                WeaponFamily.Energy => ShipComponentKind.EnergyWeapon,
                WeaponFamily.Missile => ShipComponentKind.MissileLauncher,
                _ => throw new ArgumentOutOfRangeException(nameof(secondaryFamily)),
            };
            components.Add(Component(
                "secondary-weapon",
                secondaryWeaponKind,
                1,
                ShipComponentCapability.Offense));
            if (build is not null || installedSecondaryFamily != family)
            {
                ShipComponentState secondarySupport = installedSecondaryFamily switch
                {
                    WeaponFamily.Kinetic => Storage(
                        "secondary-support",
                        ShipComponentKind.KineticMagazine,
                        1,
                        (technology.Kinetic.Ammunition ?? 100) +
                            auxiliary.KineticAmmunitionBonus,
                        ShipComponentCapability.Offense),
                    WeaponFamily.Missile => Storage(
                        "secondary-support",
                        ShipComponentKind.MissileMagazine,
                        1,
                        (technology.Missile.Ammunition ?? MissileMagazineCapacity) +
                            auxiliary.MissileAmmunitionBonus,
                        ShipComponentCapability.Offense),
                    WeaponFamily.Energy => Component(
                        "secondary-support",
                        ShipComponentKind.PowerCapacitor,
                        1,
                        ShipComponentCapability.Offense),
                    _ => throw new ArgumentOutOfRangeException(nameof(secondaryFamily)),
                };
                components.Add(secondarySupport);
            }
        }
        int shieldCapacity = shieldInstalled ? technology.ShieldCapacity : 0;
        var armorLayers = new List<ArmorLayerState>();
        if (auxiliary.HasAblativeArmor)
        {
            armorLayers.Add(new ArmorLayerState(
                "auxiliary-ablative-armor",
                pristineProtection: auxiliary.AblativeProtection,
                currentProtection: auxiliary.AblativeProtection,
                pristineIntegrity: auxiliary.AblativeIntegrity,
                currentIntegrity: auxiliary.AblativeIntegrity));
        }
        armorLayers.Add(new ArmorLayerState(
            "primary-armor",
            pristineProtection: technology.ArmorProtection,
            currentProtection: technology.ArmorProtection,
            pristineIntegrity: technology.ArmorIntegrity,
            currentIntegrity: technology.ArmorIntegrity));
        var defense = new LayeredDefenseState(
            pristineShieldCapacity: shieldCapacity,
            currentShieldCapacity: shieldCapacity,
            shieldArmor: technology.ShieldArmor,
            armorLayers: armorLayers,
            pristineHull: technology.Hull,
            currentHull: technology.Hull);
        if (auxiliary.HasShieldBooster)
        {
            defense.AddTemporaryShieldOvercapacity(
                auxiliary.ShieldCapacityBonus);
        }
        var damageControlProfile = new DamageControlProfile(
            capacityPerTurn: 1,
            startingRepairKits: DamageControlProfile.Tl1.StartingRepairKits +
                auxiliary.ExtraRepairKits,
            tacticalPowerCost: DamageControlProfile.Tl1.TacticalPowerCost,
            degradedRepairChancePercent: Math.Min(
                100,
                DamageControlProfile.Tl1.DegradedRepairChancePercent +
                    auxiliary.DamageControlChanceBonus),
            disabledRepairChancePercent: Math.Min(
                100,
                DamageControlProfile.Tl1.DisabledRepairChancePercent +
                    auxiliary.DamageControlChanceBonus),
            hullRepairChancePercent: Math.Min(
                100,
                DamageControlProfile.Tl1.HullRepairChancePercent +
                    auxiliary.DamageControlChanceBonus));
        var ship = new ShipDamageState(
            defense,
            new InternalDamageTrack(
                InternalCriticalDensity.Percent33,
                variant.ProtectedCompartmentation,
                trackSeed,
                technology.Hull),
            components,
            exposureSeed,
            isPlayerShip: true,
            damageControlProfile: damageControlProfile);
        int normalMovement = technology.ShipMove;
        int backgroundTacticalPowerCommitment = id == "A"
            ? variant.SideABackgroundTacticalPowerCommitment
            : variant.SideBBackgroundTacticalPowerCommitment;
        Tl1TacticalPowerDoctrine powerDoctrine = id == "A"
            ? variant.SideATacticalPowerDoctrine
            : variant.SideBTacticalPowerDoctrine;
        int reactorOutputPerMain = (id == "A"
            ? variant.SideAReactorOutputOverride
            : variant.SideBReactorOutputOverride) ?? technology.ReactorOutput;
        return new IntegratedSide(
            id,
            family,
            secondaryFamily,
            ship,
            new TacticalPowerLedger(),
            profile,
            technology,
            auxiliary,
            build,
            normalMovement,
            backgroundTacticalPowerCommitment,
            powerDoctrine,
            reactorOutputPerMain);
    }

    private static ShipComponentState Component(
        string id,
        ShipComponentKind kind,
        int exposure,
        ShipComponentCapability capabilities) => new(
        new ShipComponentDefinition(
            id,
            kind,
            exposure,
            CriticalExposureGroup.None,
            capabilities));

    private static ShipComponentState Storage(
        string id,
        ShipComponentKind kind,
        int exposure,
        int capacity,
        ShipComponentCapability capabilities) => new(
        new ShipComponentDefinition(
            id,
            kind,
            exposure,
            CriticalExposureGroup.None,
            capabilities),
        pristineCapacity: capacity,
        currentContents: capacity);

    private static ShipComponentState Electronics(
        string id,
        ShipComponentKind kind) => new(
        new ShipComponentDefinition(
            id,
            kind,
            criticalExposure: 0,
            exposureGroup: CriticalExposureGroup.Electronics));

    private static IntegratedCombatProfile ResolveProfile(
        Tl1IntegratedTacticalCombatVariantDocument variant,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        string sideAId = string.IsNullOrWhiteSpace(variant.SideAProfileId)
            ? "tl1-production"
            : variant.SideAProfileId;
        string sideBId = string.IsNullOrWhiteSpace(variant.SideBProfileId)
            ? "tl1-production"
            : variant.SideBProfileId;
        if (!technologyProfiles.TryGetValue(sideAId, out TechnologyCombatProfile? foundA) ||
            foundA is null ||
            !technologyProfiles.TryGetValue(sideBId, out TechnologyCombatProfile? foundB) ||
            foundB is null)
        {
            throw new InvalidOperationException(
                $"Variant '{variant.Id}' references an unknown technology profile.");
        }
        TechnologyCombatProfile sideA = ApplyVariantOverrides(
            foundA, variant, sideA: true);
        TechnologyCombatProfile sideB = ApplyVariantOverrides(
            foundB, variant, sideA: false);
        string sideAAuxiliaryId = string.IsNullOrWhiteSpace(
            variant.SideAAuxiliaryProfileId)
                ? AuxiliaryCombatProfile.LegacyId
                : variant.SideAAuxiliaryProfileId;
        string sideBAuxiliaryId = string.IsNullOrWhiteSpace(
            variant.SideBAuxiliaryProfileId)
                ? AuxiliaryCombatProfile.LegacyId
                : variant.SideBAuxiliaryProfileId;
        if (!auxiliaryProfiles.TryGetValue(
                sideAAuxiliaryId, out AuxiliaryCombatProfile? sideAAuxiliary) ||
            sideAAuxiliary is null ||
            !auxiliaryProfiles.TryGetValue(
                sideBAuxiliaryId, out AuxiliaryCombatProfile? sideBAuxiliary) ||
            sideBAuxiliary is null)
        {
            throw new InvalidOperationException(
                $"Variant '{variant.Id}' references a missing Auxiliary profile.");
        }
        if (!sideAAuxiliary.LegacyIntegratedSuite &&
            sideAAuxiliary.TechnologyLevel > sideA.TechnologyLevel ||
            !sideBAuxiliary.LegacyIntegratedSuite &&
            sideBAuxiliary.TechnologyLevel > sideB.TechnologyLevel)
        {
            throw new InvalidOperationException(
                $"Variant '{variant.Id}' installs an Auxiliary profile above its ship TL.");
        }
        return new IntegratedCombatProfile(
            string.IsNullOrWhiteSpace(variant.ProfileLabel)
                ? $"{sideA.Id}+{sideAAuxiliary.Id}-vs-{sideB.Id}+{sideBAuxiliary.Id}"
                : variant.ProfileLabel,
            sideA,
            sideB,
            sideAAuxiliary,
            sideBAuxiliary,
            variant.BaseShieldRechargeEnabled ?? true,
            variant.EvasiveManeuversEnabled ?? true,
            variant.PdsEnabled ?? true,
            variant.EscapeDisengagementEnabled ?? true);
    }

    private static Tl1IntegratedShipBuildDocument? ResolveBuild(
        Tl1IntegratedTacticalCombatStudyDocument study,
        string? buildId)
    {
        if (string.IsNullOrWhiteSpace(buildId))
        {
            return null;
        }
        return study.Builds.FirstOrDefault(build =>
                string.Equals(build.Id, buildId, StringComparison.Ordinal))
            ?? throw new InvalidOperationException(
                $"Integrated combat variant references unknown build '{buildId}'.");
    }

    private static TechnologyCombatProfile ApplyVariantOverrides(
        TechnologyCombatProfile profile,
        Tl1IntegratedTacticalCombatVariantDocument variant,
        bool sideA)
    {
        int movement = sideA
            ? variant.SideAStlMovementHexes ?? profile.ShipMove
            : variant.SideBStlMovementHexes ?? profile.ShipMove;
        int missileSpeed = (sideA
            ? variant.SideAMissileSpeedHexesPerTurnOverride
            : variant.SideBMissileSpeedHexesPerTurnOverride) ??
            variant.MissileSpeedHexesPerTurn ?? profile.MissileMove;
        int missileRange = variant.MissileMaximumTravelHexes ??
            profile.Missile.MaximumRange;
        int kineticDamage = variant.KineticDamage ?? profile.Kinetic.Damage;
        int kineticApen = variant.KineticArmorPenetration ??
            profile.Kinetic.ArmorPenetration;
        int? armorIntegrityOverride = sideA
            ? variant.SideAPrimaryArmorIntegrityOverride
            : variant.SideBPrimaryArmorIntegrityOverride;
        int? armorProtectionOverride = sideA
            ? variant.SideAPrimaryArmorProtectionOverride
            : variant.SideBPrimaryArmorProtectionOverride;
        armorProtectionOverride ??= variant.PrimaryArmorProtection;
        int? shieldCapacityOverride = sideA
            ? variant.SideAShieldCapacityOverride
            : variant.SideBShieldCapacityOverride;
        int? weaponShieldPenetrationOverride = sideA
            ? variant.SideAWeaponShieldPenetrationOverride
            : variant.SideBWeaponShieldPenetrationOverride;
        int? weaponArmorPenetrationOverride = sideA
            ? variant.SideAWeaponArmorPenetrationOverride
            : variant.SideBWeaponArmorPenetrationOverride;
        int? primaryWeaponDamageOverride = sideA
            ? variant.SideAPrimaryWeaponDamageOverride
            : variant.SideBPrimaryWeaponDamageOverride;
        int? primaryWeaponPowerCostOverride = sideA
            ? variant.SideAPrimaryWeaponPowerCostOverride
            : variant.SideBPrimaryWeaponPowerCostOverride;
        int? primaryWeaponAccuracyBonusOverride = sideA
            ? variant.SideAPrimaryWeaponAccuracyBonusOverride
            : variant.SideBPrimaryWeaponAccuracyBonusOverride;
        if (movement < 0 || missileSpeed <= 0 || missileRange <= 0 ||
            kineticDamage <= 0 || kineticApen < 0 ||
            armorIntegrityOverride is < 0 || armorProtectionOverride is < 0 ||
            weaponShieldPenetrationOverride is < 0 || weaponArmorPenetrationOverride is < 0 ||
            primaryWeaponDamageOverride is <= 0 || primaryWeaponPowerCostOverride is < 0 ||
            primaryWeaponAccuracyBonusOverride is < 0)
        {
            throw new InvalidOperationException(
                $"Variant '{variant.Id}' contains an invalid integrated combat profile.");
        }
        TechnologyCombatProfile adjusted = profile with
        {
            ShipMove = movement,
            MissileMove = missileSpeed,
            Kinetic = profile.Kinetic with
            {
                Damage = kineticDamage,
                ArmorPenetration = kineticApen,
            },
            Missile = profile.Missile with
            {
                MaximumRange = missileRange,
            },
        };
        adjusted = ApplyArmorOverrides(
            adjusted, armorIntegrityOverride, armorProtectionOverride);
        adjusted = ApplyShieldCapacityOverride(adjusted, shieldCapacityOverride);
        adjusted = ApplyPrimaryWeaponPenetrationOverrides(
            adjusted,
            sideA ? variant.SideAFamily : variant.SideBFamily,
            weaponShieldPenetrationOverride,
            weaponArmorPenetrationOverride);
        return ApplyPrimaryWeaponPerformanceOverrides(
            adjusted,
            sideA ? variant.SideAFamily : variant.SideBFamily,
            primaryWeaponDamageOverride,
            primaryWeaponPowerCostOverride,
            primaryWeaponAccuracyBonusOverride);
    }

    internal static TechnologyCombatProfile ApplyPrimaryWeaponPerformanceOverrides(
        TechnologyCombatProfile profile,
        WeaponFamily family,
        int? damage,
        int? powerCost,
        int? accuracyBonus)
    {
        ScalingWeaponProfile original = profile.Weapon(family);
        ScalingWeaponProfile adjusted = original with
        {
            Damage = damage ?? original.Damage,
            PowerCost = powerCost ?? original.PowerCost,
            AccuracyBonus = accuracyBonus ?? original.AccuracyBonus,
        };
        return family switch
        {
            WeaponFamily.Kinetic => profile with { Kinetic = adjusted },
            WeaponFamily.Energy => profile with { Energy = adjusted },
            WeaponFamily.Missile => profile with { Missile = adjusted },
            _ => throw new InvalidOperationException(
                $"Unsupported weapon family '{family}' for performance override."),
        };
    }

    internal static TechnologyCombatProfile ApplyPrimaryWeaponPenetrationOverrides(
        TechnologyCombatProfile profile,
        WeaponFamily family,
        int? shieldPenetration,
        int? armorPenetration)
    {
        ScalingWeaponProfile original = profile.Weapon(family);
        ScalingWeaponProfile adjusted = original with
        {
            ShieldPenetration = shieldPenetration ?? original.ShieldPenetration,
            ArmorPenetration = armorPenetration ?? original.ArmorPenetration,
        };
        return family switch
        {
            WeaponFamily.Kinetic => profile with { Kinetic = adjusted },
            WeaponFamily.Energy => profile with { Energy = adjusted },
            WeaponFamily.Missile => profile with { Missile = adjusted },
            _ => throw new InvalidOperationException(
                $"Unsupported weapon family '{family}' for penetration override."),
        };
    }

    private static IReadOnlyDictionary<string, TechnologyCombatProfile>
        LoadTechnologyProfiles(
            string studyPath,
            Tl1IntegratedTacticalCombatStudyDocument study,
            Tl1BaselineCatalog baseline)
    {
        if (string.IsNullOrWhiteSpace(study.TechnologyProfileCatalog))
        {
            return new Dictionary<string, TechnologyCombatProfile>(
                StringComparer.Ordinal)
            {
                ["tl1-production"] =
                    TechnologyCombatProfileCatalog.BuildTl1(baseline),
            };
        }
        return TechnologyCombatProfileCatalog.Load(
            ResolveStudyRelativePath(
                studyPath, study.TechnologyProfileCatalog),
            baseline);
    }

    private static IReadOnlyDictionary<string, AuxiliaryCombatProfile>
        LoadAuxiliaryProfiles(
            string studyPath,
            Tl1IntegratedTacticalCombatStudyDocument study)
    {
        if (string.IsNullOrWhiteSpace(study.AuxiliaryProfileCatalog))
        {
            return AuxiliaryCombatProfileCatalog.LegacyOnly();
        }
        return AuxiliaryCombatProfileCatalog.Load(
            ResolveStudyRelativePath(
                studyPath, study.AuxiliaryProfileCatalog));
    }

    private static IReadOnlyDictionary<string, SensorEwFoundationProfile>
        LoadSensorEwProfiles(
            string studyPath,
            Tl1IntegratedTacticalCombatStudyDocument study)
    {
        if (string.IsNullOrWhiteSpace(study.SensorEwProfileCatalog))
        {
            return new Dictionary<string, SensorEwFoundationProfile>(StringComparer.Ordinal);
        }

        JsonSerializerOptions sensorEwCatalogOptions = JsonOptions();
        // Tl1SensorEwFoundationStudy is a positional record whose public
        // property names are PascalCase, while the authoritative catalog
        // JSON is camelCase. The foundation runner intentionally accepts
        // that catalog case-insensitively; the integrated runner must use
        // the same binding contract.
        sensorEwCatalogOptions.PropertyNameCaseInsensitive = true;
        Tl1SensorEwFoundationStudy catalog = JsonSerializer.Deserialize<
            Tl1SensorEwFoundationStudy>(
                File.ReadAllText(ResolveStudyRelativePath(
                    studyPath, study.SensorEwProfileCatalog)),
                sensorEwCatalogOptions) ?? throw new InvalidOperationException(
                    "Sensor/EW profile catalog could not be read.");

        if (catalog.Candidates is null)
        {
            throw new InvalidOperationException(
                "Sensor/EW profile catalog candidates could not be bound.");
        }

        return catalog.Candidates.ToDictionary(
            candidate => candidate.Id,
            candidate => new SensorEwFoundationProfile(
                candidate.Id,
                candidate.PassiveFirmRange,
                candidate.PassiveApproximateRange,
                candidate.ActiveFirmRange,
                candidate.ActiveApproximateRange,
                candidate.ActivePowerCost,
                candidate.ActiveOverloadAdditionalPowerCost,
                candidate.ActiveOverloadFirmBonus,
                candidate.ActiveOverloadApproximateBonus,
                candidate.DiscriminationResistance,
                candidate.PointBlankBurnThroughResistance),
            StringComparer.Ordinal);
    }

    private static LoadedTl1AiDoctrineRegistry? LoadAiDoctrineRegistry(
        string studyPath,
        Tl1IntegratedTacticalCombatStudyDocument study)
    {
        if (string.IsNullOrWhiteSpace(study.AiDoctrineCatalog))
        {
            return null;
        }

        string path = ResolveStudyRelativePath(studyPath, study.AiDoctrineCatalog);
        string json = File.ReadAllText(path);
        JsonSerializerOptions options = JsonOptions();
        options.PropertyNameCaseInsensitive = true;
        Tl1AiDoctrineRegistryDocument document = JsonSerializer.Deserialize<
            Tl1AiDoctrineRegistryDocument>(json, options) ??
            throw new InvalidOperationException(
                "AI doctrine registry could not be read.");
        if (document.SchemaVersion != "star-cluster-ai-doctrine-registry-v1" ||
            string.IsNullOrWhiteSpace(document.RegistryVersion) ||
            document.Doctrines is null || document.Doctrines.Count == 0)
        {
            throw new InvalidOperationException(
                "AI doctrine registry identity or doctrine list is invalid.");
        }
        if (document.Doctrines.Any(doctrine =>
                string.IsNullOrWhiteSpace(doctrine.Id) ||
                doctrine.Domain != "electronic-warfare" ||
                doctrine.InformationPolicy.UsesHiddenEnemyRatings))
        {
            throw new InvalidOperationException(
                "AI doctrine registry contains an invalid or hidden-information doctrine.");
        }
        var byId = document.Doctrines.ToDictionary(
            doctrine => doctrine.Id, doctrine => doctrine, StringComparer.Ordinal);
        string hash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(json)))
            .ToLowerInvariant();
        return new LoadedTl1AiDoctrineRegistry(path, hash, document, byId);
    }

    private static Tl1SensorEnvelope ResolveSensorEnvelope(
        string? profileId,
        Tl1SensorEnvelope baselineEnvelope,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (string.IsNullOrWhiteSpace(profileId))
        {
            return baselineEnvelope;
        }
        if (!sensorEwProfiles.TryGetValue(profileId, out
                SensorEwFoundationProfile? profile))
        {
            throw new InvalidOperationException(
                $"Unknown Sensor/EW profile '{profileId}'.");
        }
        return Tl1SensorEnvelope.FromFoundation(profile);
    }

    private static Tl1SensorEnvelope ApplySensorEnvelopeOverrides(
        Tl1SensorEnvelope envelope,
        Tl1IntegratedTacticalCombatVariantDocument variant,
        bool sideA)
    {
        int? passiveFirm = sideA
            ? variant.SideASensorPassiveFirmRangeOverride
            : variant.SideBSensorPassiveFirmRangeOverride;
        int? passiveApprox = sideA
            ? variant.SideASensorPassiveApproximateRangeOverride
            : variant.SideBSensorPassiveApproximateRangeOverride;
        int? lowFirm = sideA
            ? variant.SideASensorActiveLowFirmRangeOverride
            : variant.SideBSensorActiveLowFirmRangeOverride;
        int? lowApprox = sideA
            ? variant.SideASensorActiveLowApproximateRangeOverride
            : variant.SideBSensorActiveLowApproximateRangeOverride;
        int? lowPower = sideA
            ? variant.SideASensorActiveLowPowerCostOverride
            : variant.SideBSensorActiveLowPowerCostOverride;
        int? highFirm = sideA
            ? variant.SideASensorActiveHighFirmRangeOverride
            : variant.SideBSensorActiveHighFirmRangeOverride;
        int? highApprox = sideA
            ? variant.SideASensorActiveHighApproximateRangeOverride
            : variant.SideBSensorActiveHighApproximateRangeOverride;
        int? highPower = sideA
            ? variant.SideASensorActiveHighPowerCostOverride
            : variant.SideBSensorActiveHighPowerCostOverride;

        bool anyOverride = passiveFirm is not null || passiveApprox is not null ||
            lowFirm is not null || lowApprox is not null || lowPower is not null ||
            highFirm is not null || highApprox is not null || highPower is not null;
        if (!anyOverride) return envelope;

        int resolvedPassiveFirm = passiveFirm ?? envelope.PassiveFirmRange;
        int resolvedPassiveApprox = passiveApprox ?? envelope.PassiveApproximateRange;
        int resolvedLowFirm = lowFirm ?? envelope.ActiveLevel1FirmRange;
        int resolvedLowApprox = lowApprox ?? envelope.ActiveLevel1ApproximateRange;
        int resolvedLowPower = lowPower ?? envelope.NormalActivePowerCost;
        bool hasHighMode = highFirm is not null || highApprox is not null || highPower is not null;
        if (hasHighMode && (highFirm is null || highApprox is null || highPower is null))
        {
            throw new InvalidOperationException(
                $"Variant '{variant.Id}' must declare all TL3 High Active sensor range/power values together.");
        }
        int resolvedHighFirm = hasHighMode ? highFirm!.Value : resolvedLowFirm;
        int resolvedHighApprox = hasHighMode ? highApprox!.Value : resolvedLowApprox;
        int resolvedHighPower = hasHighMode ? highPower!.Value : resolvedLowPower;
        if (resolvedPassiveFirm < 0 || resolvedPassiveApprox < resolvedPassiveFirm ||
            resolvedLowFirm < resolvedPassiveFirm || resolvedLowApprox < resolvedLowFirm ||
            resolvedLowPower <= 0 || resolvedHighFirm < resolvedLowFirm ||
            resolvedHighApprox < resolvedHighFirm || resolvedHighPower < resolvedLowPower)
        {
            throw new InvalidOperationException(
                $"Variant '{variant.Id}' contains an invalid normal sensor-mode envelope.");
        }

        return new Tl1SensorEnvelope(
            resolvedPassiveFirm,
            resolvedPassiveApprox,
            resolvedLowFirm,
            resolvedLowApprox,
            resolvedHighFirm,
            resolvedHighApprox)
        {
            ProfileId = envelope.ProfileId + (hasHighMode ? "+tl3-dual-active" : "+runtime-low"),
            SingleActiveMode = !hasHighMode,
            CausalEwResolution = true,
            NormalActivePowerCost = resolvedLowPower,
            HighActivePowerCost = resolvedHighPower,
            OverloadAdditionalPowerCost = envelope.OverloadAdditionalPowerCost,
            OverloadFirmBonus = envelope.OverloadFirmBonus,
            OverloadApproximateBonus = envelope.OverloadApproximateBonus,
            DiscriminationResistance = envelope.DiscriminationResistance,
            PointBlankBurnThroughResistance = envelope.PointBlankBurnThroughResistance,
        };
    }

    internal static (int LowFirm, int LowApprox, int LowPower, int HighFirm, int HighApprox, int HighPower, bool SingleActiveMode)
        ApplySensorEnvelopeOverridesForSelfTest(
            int lowFirm, int lowApprox, int lowPower,
            int highFirm, int highApprox, int highPower)
    {
        var baseline = new Tl1SensorEnvelope(1, 3, 3, 4, 3, 4)
        {
            ProfileId = "cp102-self-test",
            SingleActiveMode = true,
            CausalEwResolution = true,
            NormalActivePowerCost = 1,
            HighActivePowerCost = 1,
        };
        var variant = new Tl1IntegratedTacticalCombatVariantDocument
        {
            Id = "cp102-sensor-self-test",
            SideASensorActiveLowFirmRangeOverride = lowFirm,
            SideASensorActiveLowApproximateRangeOverride = lowApprox,
            SideASensorActiveLowPowerCostOverride = lowPower,
            SideASensorActiveHighFirmRangeOverride = highFirm,
            SideASensorActiveHighApproximateRangeOverride = highApprox,
            SideASensorActiveHighPowerCostOverride = highPower,
        };
        Tl1SensorEnvelope adjusted = ApplySensorEnvelopeOverrides(baseline, variant, sideA: true);
        return (
            adjusted.ActiveLevel1FirmRange, adjusted.ActiveLevel1ApproximateRange, adjusted.NormalActivePowerCost,
            adjusted.ActiveLevel2FirmRange, adjusted.ActiveLevel2ApproximateRange, adjusted.HighActivePowerCost,
            adjusted.SingleActiveMode);
    }

    internal static int ApplyEvasiveCompensationForSelfTest(
        int shooterPenaltyMagnitude,
        int normalCompensation,
        ComponentCondition tacticalComputerCondition)
    {
        if (shooterPenaltyMagnitude < 0 || normalCompensation < 0)
        {
            throw new InvalidOperationException(
                "Evasive penalty magnitude and compensation must be non-negative.");
        }
        int conditionedCompensation = ComponentPerformance.TargetingComputerBonus(
            normalCompensation, tacticalComputerCondition);
        return Math.Max(0, shooterPenaltyMagnitude - conditionedCompensation);
    }

    private static string ResolveStudyRelativePath(
        string studyPath,
        string value)
    {
        if (Path.IsPathRooted(value)) return value;
        DirectoryInfo? directory = new FileInfo(
            Path.GetFullPath(studyPath)).Directory;
        while (directory is not null)
        {
            if (File.Exists(Path.Combine(
                    directory.FullName, "StarCluster.Calibration.sln")))
            {
                return Path.GetFullPath(Path.Combine(directory.FullName, value));
            }
            directory = directory.Parent;
        }
        throw new InvalidOperationException(
            "Repository root could not be located for technology profiles.");
    }

    private static ulong StableVariantSalt(
        Tl1IntegratedTacticalCombatVariantDocument variant)
    {
        string text;
        if (!string.IsNullOrWhiteSpace(variant.ComparisonGroup))
        {
            text = $"paired|{variant.ComparisonGroup}";
        }
        else if (string.IsNullOrWhiteSpace(variant.SideAAuxiliaryProfileId) &&
            string.IsNullOrWhiteSpace(variant.SideBAuxiliaryProfileId))
        {
            text = string.Join(
                "|",
                variant.SideAFamily,
                variant.SideBFamily,
                variant.MovementMode,
                variant.InitialRangeHexes,
                variant.ProtectedCompartmentation,
                variant.DamageControl,
                variant.ProfileLabel,
                variant.SideAProfileId,
                variant.SideBProfileId,
                variant.SideAStlMovementHexes,
                variant.SideBStlMovementHexes,
                variant.MissileSpeedHexesPerTurn,
                variant.MissileMaximumTravelHexes,
                variant.KineticDamage,
                variant.KineticArmorPenetration,
                variant.PrimaryArmorProtection,
                variant.BaseShieldRechargeEnabled,
                variant.EvasiveManeuversEnabled,
                variant.PdsEnabled,
                variant.EscapeDisengagementEnabled);
        }
        else
        {
            text = string.Join(
                "|",
                variant.SideAFamily,
                variant.SideBFamily,
                variant.MovementMode,
                variant.InitialRangeHexes,
                variant.ProtectedCompartmentation,
                variant.DamageControl,
                variant.ProfileLabel,
                variant.SideAProfileId,
                variant.SideBProfileId,
                variant.SideAAuxiliaryProfileId,
                variant.SideBAuxiliaryProfileId,
                variant.SideAStlMovementHexes,
                variant.SideBStlMovementHexes,
                variant.MissileSpeedHexesPerTurn,
                variant.MissileMaximumTravelHexes,
                variant.KineticDamage,
                variant.KineticArmorPenetration,
                variant.PrimaryArmorProtection,
                variant.BaseShieldRechargeEnabled,
                variant.EvasiveManeuversEnabled,
                variant.PdsEnabled,
                variant.EscapeDisengagementEnabled);
        }
        if (variant.SideASecondaryFamily is not null ||
            variant.SideBSecondaryFamily is not null)
        {
            text += $"|secondary|{variant.SideASecondaryFamily}|{variant.SideBSecondaryFamily}";
        }
        if (!string.IsNullOrWhiteSpace(variant.SideABuildId) ||
            !string.IsNullOrWhiteSpace(variant.SideBBuildId))
        {
            text += $"|build|{variant.SideABuildId}|{variant.SideBBuildId}";
        }
        if (string.IsNullOrWhiteSpace(variant.ComparisonGroup))
        {
            text += $"|power-doctrine|{variant.SideATacticalPowerDoctrine}|{variant.SideBTacticalPowerDoctrine}" +
                $"|reactor-output|{variant.SideAReactorOutputOverride}|{variant.SideBReactorOutputOverride}";
        }
        byte[] hash = SHA256.HashData(Encoding.UTF8.GetBytes(text));
        return BitConverter.ToUInt64(hash, 0);
    }

    private static int RequiredVariantCountForStudy(string studyId)
    {
        return studyId switch
        {
            PrimaryStudyId => RequiredPrimaryVariantCount,
            DiagnosticStudyId => RequiredDiagnosticVariantCount,
            MinimalTacticsStudyId => RequiredMinimalTacticsVariantCount,
            Tl1ComposedShipStudyId => RequiredTl1ComposedShipVariantCount,
            Tl1PowerDoctrineStudyId => RequiredTl1PowerDoctrineVariantCount,
            Tl1OperationalSensorStudyId => RequiredTl1OperationalSensorVariantCount,
            Tl1TrackAwareAcquisitionStudyId => RequiredTl1TrackAwareAcquisitionVariantCount,
            Tl1BilateralTacticalGeometryStudyId => RequiredTl1BilateralTacticalGeometryVariantCount,
            Tl1ScriptedOverloadTacticsStudyId => RequiredTl1ScriptedOverloadTacticsVariantCount,
            Tl1BilateralOverloadCounterplayStudyId => RequiredTl1BilateralOverloadCounterplayVariantCount,
            Tl1SensorEwCandidateCombatStudyId => RequiredTl1SensorEwCandidateCombatVariantCount,
            Tl1EcmPowerCostCounterplayStudyId => RequiredTl1EcmPowerCostCounterplayVariantCount,
            Tl1SensorDiscriminationBurnthroughStudyId => RequiredTl1SensorDiscriminationBurnthroughVariantCount,
            Tl1ReactiveEwSubphaseStudyId => RequiredTl1ReactiveEwSubphaseVariantCount,
            Tl1EwAiDoctrineStudyId => RequiredTl1EwAiDoctrineVariantCount,
            Tl1ApproximateTrackDegradedFireStudyId =>
                RequiredTl1ApproximateTrackDegradedFireVariantCount,
            Tl1AppliedDegradedFireFamilyCandidateStudyId =>
                RequiredTl1AppliedDegradedFireFamilyCandidateVariantCount,
            Tl1DegradedFireEccmValueStudyId =>
                RequiredTl1DegradedFireEccmValueVariantCount,
            Tl2CandidateStudyId => RequiredTl2CandidateVariantCount,
            Tl2AttributionStudyId => RequiredTl2AttributionVariantCount,
            Tl2DefensiveRefinementStudyId =>
                RequiredTl2DefensiveRefinementVariantCount,
            Tl2DynamicWeaponChoiceStudyId =>
                RequiredTl2DynamicWeaponChoiceVariantCount,
            Tl2OpponentAwareRangeStudyId =>
                RequiredTl2OpponentAwareRangeVariantCount,
            Tl2SensorEwDiscriminationIsolationStudyId =>
                RequiredTl2SensorEwDiscriminationIsolationVariantCount,
            Tl2EwPowerPressureTallViabilityStudyId =>
                RequiredTl2EwPowerPressureTallViabilityVariantCount,
            Tl2TacticalComputerEwPermutationStudyId =>
                RequiredTl2TacticalComputerEwPermutationVariantCount,
            Tl2PowerReactorProgressionPermutationStudyId =>
                RequiredTl2PowerReactorProgressionPermutationVariantCount,
            Tl2ShieldCapacityPowerIntegrationStudyId =>
                RequiredTl2ShieldCapacityPowerIntegrationVariantCount,
            Tl2ArmorApAiShieldIntegrationStudyId =>
                RequiredTl2ArmorApAiShieldIntegrationVariantCount,
            Tl2WeaponPenetrationLayeredDefenseStudyId =>
                RequiredTl2WeaponPenetrationLayeredDefenseVariantCount,
            CrossTlBuildPermutationScreeningStudyId =>
