            AdaptiveEngageEncounterStudyId =>
                RequiredAdaptiveEngageEncounterVariantCount,
            CrossTlAdaptiveEngageProgressionScreeningStudyId =>
                RequiredCrossTlAdaptiveEngageProgressionScreeningVariantCount,
            CrossTlExactEdgeProgressionScreeningStudyId =>
                RequiredCrossTlExactEdgeProgressionScreeningVariantCount,
            Tl3Cp102TransitionSmokeStudyId =>
                RequiredTl3Cp102TransitionSmokeVariantCount,
            AuxiliaryPerformanceScreeningStudyId =>
                RequiredAuxiliaryPerformanceScreeningVariantCount,
            ArchitectureDerivedAuxiliaryStudyId =>
                RequiredArchitectureDerivedAuxiliaryVariantCount,
            StatefulAuxiliaryTuningStudyId =>
                RequiredStatefulAuxiliaryTuningVariantCount,
            AuxiliaryRefinementStudyId =>
                RequiredAuxiliaryRefinementVariantCount,
            Tl2AblativeCandidateStudyId =>
                RequiredTl2AblativeCandidateVariantCount,
            AuxiliaryPowerStressStudyId =>
                RequiredAuxiliaryPowerStressVariantCount,
            Tl3StandardProfileStudyId =>
                RequiredTl3StandardProfileVariantCount,
            Tl3TwoBayLoadoutStudyId =>
                RequiredTl3TwoBayLoadoutVariantCount,
            Tl3AuxiliaryLoadoutStudyId =>
                RequiredTl3AuxiliaryLoadoutVariantCount,
            Tl3PowerEnvelopeStudyId =>
                RequiredTl3PowerEnvelopeVariantCount,
            Tl3LowTechProfileStudyId =>
                RequiredTl3LowTechProfileVariantCount,
            Tl3LowTechAuxStudyId =>
                RequiredTl3LowTechAuxVariantCount,
            Tl3LowTechAuxIsolationStudyId =>
                RequiredTl3LowTechAuxIsolationVariantCount,
            Tl3LowTechPowerStudyId =>
                RequiredTl3LowTechPowerVariantCount,
            Tl3DefensiveMicrostepStudyId =>
                RequiredTl3DefensiveMicrostepVariantCount,
            Tl3AuxiliaryRetestStudyId =>
                RequiredTl3AuxiliaryRetestVariantCount,
            Tl3ShieldBreakpointStudyId =>
                RequiredTl3ShieldBreakpointVariantCount,
            Tl3CrossTlAuxStudyId =>
                RequiredTl3CrossTlAuxVariantCount,
            Tl3PowerCharacteristicStudyId =>
                RequiredTl3PowerCharacteristicVariantCount,
            Tl3EqualCapacityPowerStudyId =>
                RequiredTl3EqualCapacityPowerVariantCount,
            Tl4FoundationTransitionStudyId =>
                RequiredTl4FoundationTransitionVariantCount,
            Tl4TwoBayLoadoutStudyId =>
                RequiredTl4TwoBayLoadoutVariantCount,
            Tl4SpecializationResistanceStudyId =>
                RequiredTl4SpecializationResistanceVariantCount,
            Tl4NaturalPowerStudyId =>
                RequiredTl4NaturalPowerVariantCount,
            Tl4MixedPowerStudyId =>
                RequiredTl4MixedPowerVariantCount,
            Tl4SingleMainAxisStudyId =>
                RequiredTl4SingleMainAxisVariantCount,
            Tl4FoundationPackageStudyId =>
                RequiredTl4FoundationPackageVariantCount,
            Tl4SingleMainSpecializationResistanceStudyId =>
                RequiredTl4SingleMainSpecializationResistanceVariantCount,
            Tl4PoweredDefenseIsolationStudyId =>
                RequiredTl4PoweredDefenseIsolationVariantCount,
            Tl4PoweredDefensePowerPairingStudyId =>
                RequiredTl4PoweredDefensePowerPairingVariantCount,
            Tl4SingleMainNaturalPowerStudyId =>
                RequiredTl4SingleMainNaturalPowerVariantCount,
            _ => throw new InvalidOperationException(
                $"Unsupported integrated tactical-combat study '{studyId}'."),
        };
    }

    private static void Validate(
        Tl1IntegratedTacticalCombatStudyDocument study,
        string baselineHash,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles,
        LoadedTl1AiDoctrineRegistry? aiDoctrineRegistry)
    {
        if (study.SchemaVersion != SchemaVersion)
        {
            throw new InvalidOperationException(
                "Unexpected TL1 integrated tactical-combat schema.");
        }
        if (!string.Equals(
                study.BaselineSha256,
                baselineHash,
                StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                "TL1 integrated tactical-combat baseline hash mismatch.");
        }
        int requiredCount = RequiredVariantCountForStudy(study.Id);
        if (study.Variants.Count != requiredCount)
        {
            throw new InvalidOperationException(
                $"Study '{study.Id}' requires exactly {requiredCount} variants; " +
                $"found {study.Variants.Count}.");
        }
        if (study.Variants.Select(variant => variant.Id)
            .Distinct(StringComparer.Ordinal).Count() != study.Variants.Count)
        {
            throw new InvalidOperationException(
                "Integrated tactical-combat variant IDs must be unique.");
        }
        if (study.Variants.Any(variant => variant.SideAFamily == WeaponFamily.Hybrid ||
            variant.SideBFamily == WeaponFamily.Hybrid ||
            variant.SideASecondaryFamily == WeaponFamily.Hybrid ||
            variant.SideBSecondaryFamily == WeaponFamily.Hybrid))
        {
            throw new InvalidOperationException(
                "Integrated tactical-combat studies support kinetic, energy, and missile only.");
        }
        bool multiBayScreeningStudy = IsTl3CandidateStudy(study.Id) || IsCheckpoint57Study(study.Id) ||
            study.Id == Tl1ComposedShipStudyId ||
            study.Id == Tl1PowerDoctrineStudyId ||
            study.Id == Tl1OperationalSensorStudyId ||
            study.Id == Tl1TrackAwareAcquisitionStudyId ||
            study.Id == Tl1BilateralTacticalGeometryStudyId ||
            study.Id == Tl1ScriptedOverloadTacticsStudyId ||
            study.Id == Tl1BilateralOverloadCounterplayStudyId ||
            study.Id == Tl1SensorEwCandidateCombatStudyId ||
            study.Id == Tl1EcmPowerCostCounterplayStudyId ||
            study.Id == Tl1SensorDiscriminationBurnthroughStudyId ||
            study.Id == Tl1ReactiveEwSubphaseStudyId ||
            study.Id == Tl1EwAiDoctrineStudyId ||
            study.Id == Tl1ApproximateTrackDegradedFireStudyId ||
            study.Id == Tl1AppliedDegradedFireFamilyCandidateStudyId ||
            study.Id == Tl1DegradedFireEccmValueStudyId ||
            study.Id == CrossTlGeneralizedLegalBuildScreeningStudyId ||
            study.Id == CrossTlMatchedReadinessSpaceScreeningStudyId ||
            study.Id == CrossTlAdaptiveEngageProgressionScreeningStudyId ||
            study.Id == CrossTlExactEdgeProgressionScreeningStudyId ||
            study.Id == Tl3Cp102TransitionSmokeStudyId;
        foreach (Tl1IntegratedTacticalCombatVariantDocument variant in study.Variants)
        {
            if (!multiBayScreeningStudy &&
                (variant.SideASecondaryFamily is not null ||
                 variant.SideBSecondaryFamily is not null))
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' uses a second weapon bay outside the Checkpoint 54 TL3 screening studies.");
            }
            string sideAProfileId = string.IsNullOrWhiteSpace(variant.SideAProfileId)
                ? "tl1-production"
                : variant.SideAProfileId;
            string sideBProfileId = string.IsNullOrWhiteSpace(variant.SideBProfileId)
                ? "tl1-production"
                : variant.SideBProfileId;
            if (!technologyProfiles.ContainsKey(sideAProfileId) ||
                !technologyProfiles.ContainsKey(sideBProfileId))
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' references a missing technology profile.");
            }
            if (variant.InitialRangeHexes is < 0 or > 20)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' has an invalid initial range.");
            }
            if (variant.SideAReactorOutputOverride is < 1 or > 20 ||
                variant.SideBReactorOutputOverride is < 1 or > 20)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' has an invalid reactor-output sensitivity override.");
            }
            if (variant.SideAShieldCapacityOverride is < 0 or > 100 ||
                variant.SideBShieldCapacityOverride is < 0 or > 100)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' has an invalid shield-capacity sensitivity override.");
            }
            if (variant.SideAPrimaryArmorIntegrityOverride is < 0 or > 100 ||
                variant.SideBPrimaryArmorIntegrityOverride is < 0 or > 100 ||
                variant.SideAPrimaryArmorProtectionOverride is < 0 or > 100 ||
                variant.SideBPrimaryArmorProtectionOverride is < 0 or > 100)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' has an invalid primary-armor sensitivity override.");
            }
            if (variant.SideATacticalComputerTargetingBonusOverride is < 0 or > 50 ||
                variant.SideBTacticalComputerTargetingBonusOverride is < 0 or > 50)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' has an invalid Tactical Computer targeting-bonus override.");
            }
            if (variant.SideANetEwRangePenalty is < 0 or > 3 ||
                variant.SideBNetEwRangePenalty is < 0 or > 3)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' has an invalid net EW range penalty.");
            }
            if (variant.SideAEcmNormalPowerCostOverride is < 1 or > 20 ||
                variant.SideBEcmNormalPowerCostOverride is < 1 or > 20 ||
                variant.SideAEccmNormalPowerCostOverride is < 1 or > 20 ||
                variant.SideBEccmNormalPowerCostOverride is < 1 or > 20)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' has an invalid EW normal-power cost override.");
            }
            if (variant.SideAEcmNormalRatingOverride is < 1 or > 4 ||
                variant.SideBEcmNormalRatingOverride is < 1 or > 4 ||
                variant.SideAEccmNormalRatingOverride is < 1 or > 4 ||
                variant.SideBEccmNormalRatingOverride is < 1 or > 4)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' has an invalid EW normal-rating override.");
            }
            if (!string.IsNullOrWhiteSpace(variant.SideASensorEwProfileId) &&
                !sensorEwProfiles.ContainsKey(variant.SideASensorEwProfileId))
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' references unknown Side-A Sensor/EW profile '{variant.SideASensorEwProfileId}'.");
            }
            if (!string.IsNullOrWhiteSpace(variant.SideBSensorEwProfileId) &&
                !sensorEwProfiles.ContainsKey(variant.SideBSensorEwProfileId))
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' references unknown Side-B Sensor/EW profile '{variant.SideBSensorEwProfileId}'.");
            }
            if (variant.SideAEcmPolicy == Tl1IntegratedEwPowerPolicy.ReactiveNormal ||
                variant.SideBEcmPolicy == Tl1IntegratedEwPowerPolicy.ReactiveNormal)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' uses ReactiveNormal as an ECM policy; it is reserved for ECCM response windows.");
            }
            ValidateApproximateDirectFireControl(
                variant.Id, "A", variant.SideAAllowsApproximateDirectFire,
                variant.SideAApproximateDirectFireAccuracyPenalty);
            ValidateApproximateDirectFireControl(
                variant.Id, "B", variant.SideBAllowsApproximateDirectFire,
                variant.SideBApproximateDirectFireAccuracyPenalty);
            _ = ResolveProfile(variant, technologyProfiles, auxiliaryProfiles);
        }


        if (study.Id == PrimaryStudyId)
        {
            ValidatePrimaryCoverage(study);
        }
        else if (study.Id == DiagnosticStudyId)
        {
            ValidateDiagnosticCoverage(study);
        }
        else if (study.Id == MinimalTacticsStudyId)
        {
            ValidateMinimalTacticsCoverage(study);
        }
        else if (study.Id == Tl1ComposedShipStudyId)
        {
            ValidateTl1ComposedShipCoverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (study.Id == Tl1PowerDoctrineStudyId)
        {
            ValidateTl1PowerDoctrineCoverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (study.Id == Tl1OperationalSensorStudyId)
        {
            ValidateTl1OperationalSensorCoverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (study.Id == Tl1TrackAwareAcquisitionStudyId)
        {
            ValidateTl1TrackAwareAcquisitionCoverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (study.Id == Tl1BilateralTacticalGeometryStudyId)
        {
            ValidateTl1BilateralTacticalGeometryCoverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (study.Id == Tl1ScriptedOverloadTacticsStudyId)
        {
            ValidateTl1ScriptedOverloadTacticsCoverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (study.Id == Tl1BilateralOverloadCounterplayStudyId)
        {
            ValidateTl1BilateralOverloadCounterplayCoverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (study.Id == Tl1SensorEwCandidateCombatStudyId)
        {
            ValidateTl1SensorEwCandidateCombatCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == Tl1EcmPowerCostCounterplayStudyId)
        {
            ValidateTl1EcmPowerCostCounterplayCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == Tl1SensorDiscriminationBurnthroughStudyId)
        {
            ValidateTl1SensorDiscriminationBurnthroughCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == Tl1ReactiveEwSubphaseStudyId)
        {
            ValidateTl1ReactiveEwSubphaseCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == Tl1EwAiDoctrineStudyId)
        {
            ValidateTl1EwAiDoctrineCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles,
                aiDoctrineRegistry);
        }
        else if (study.Id == Tl1ApproximateTrackDegradedFireStudyId)
        {
            ValidateTl1ApproximateTrackDegradedFireCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == Tl1AppliedDegradedFireFamilyCandidateStudyId)
        {
            ValidateTl1AppliedDegradedFireFamilyCandidateCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == Tl1DegradedFireEccmValueStudyId)
        {
            ValidateTl1DegradedFireEccmValueCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles,
                aiDoctrineRegistry);
        }
        else if (study.Id == Tl2CandidateStudyId)
        {
            ValidateTl2CandidateCoverage(study, technologyProfiles);
        }
        else if (study.Id == Tl2AttributionStudyId)
        {
            ValidateTl2AttributionCoverage(study, technologyProfiles);
        }
        else if (study.Id == Tl2DefensiveRefinementStudyId)
        {
            ValidateTl2DefensiveRefinementCoverage(study, technologyProfiles);
        }
        else if (study.Id == Tl2DynamicWeaponChoiceStudyId)
        {
            ValidateTl2DynamicWeaponChoiceCoverage(study, technologyProfiles);
        }
        else if (study.Id == Tl2OpponentAwareRangeStudyId)
        {
            ValidateTl2OpponentAwareRangeCoverage(study, technologyProfiles);
        }
        else if (study.Id == Tl2SensorEwDiscriminationIsolationStudyId)
        {
            ValidateTl2SensorEwDiscriminationIsolationCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == Tl2EwPowerPressureTallViabilityStudyId)
        {
            ValidateTl2EwPowerPressureTallViabilityCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == Tl2TacticalComputerEwPermutationStudyId)
        {
            ValidateTl2TacticalComputerEwPermutationCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == Tl2PowerReactorProgressionPermutationStudyId)
        {
            ValidateTl2PowerReactorProgressionPermutationCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == Tl2ShieldCapacityPowerIntegrationStudyId)
        {
            ValidateTl2ShieldCapacityPowerIntegrationCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == Tl2ArmorApAiShieldIntegrationStudyId)
        {
            ValidateTl2ArmorApAiShieldIntegrationCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == Tl2WeaponPenetrationLayeredDefenseStudyId)
        {
            ValidateTl2WeaponPenetrationLayeredDefenseCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == CrossTlBuildPermutationScreeningStudyId)
        {
            ValidateCrossTlBuildPermutationScreeningCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == CrossTlPowerAwareInformationControlScreeningStudyId)
        {
            ValidateCrossTlPowerAwareInformationControlScreeningCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == CrossTlGeneralizedLegalBuildScreeningStudyId)
        {
            ValidateCrossTlGeneralizedLegalBuildScreeningCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == CrossTlMatchedReadinessSpaceScreeningStudyId)
        {
            ValidateCrossTlMatchedReadinessSpaceScreeningCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles);
        }
        else if (study.Id == AdaptiveEngageEncounterStudyId)
        {
            ValidateAdaptiveEngageEncounterCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles,
                aiDoctrineRegistry);
        }
        else if (study.Id == CrossTlAdaptiveEngageProgressionScreeningStudyId)
        {
            ValidateCrossTlAdaptiveEngageProgressionCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles,
                aiDoctrineRegistry);
        }
        else if (study.Id == CrossTlExactEdgeProgressionScreeningStudyId)
        {
            ValidateCrossTlExactEdgeProgressionCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles,
                aiDoctrineRegistry);
        }
        else if (study.Id == Tl3Cp102TransitionSmokeStudyId)
        {
            ValidateTl3Cp102TransitionSmokeCoverage(
                study, technologyProfiles, auxiliaryProfiles, sensorEwProfiles,
                aiDoctrineRegistry);
        }
        else if (study.Id is AuxiliaryPerformanceScreeningStudyId or
            ArchitectureDerivedAuxiliaryStudyId or
            StatefulAuxiliaryTuningStudyId or
            AuxiliaryRefinementStudyId)
        {
            ValidateAuxiliaryPerformanceScreeningCoverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (study.Id == Tl2AblativeCandidateStudyId)
        {
            ValidateTl2AblativeCandidateCoverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (study.Id == AuxiliaryPowerStressStudyId)
        {
            ValidateAuxiliaryPowerStressCoverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (IsTl3CandidateStudy(study.Id))
        {
            ValidateTl3CandidateCoverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (IsTl3LowTechCapstoneStudy(study.Id))
        {
            ValidateTl3LowTechCapstoneCoverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (IsCheckpoint56Study(study.Id))
        {
            ValidateCheckpoint56Coverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (IsCheckpoint57Study(study.Id))
        {
            ValidateCheckpoint57Coverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else if (IsCheckpoint58Study(study.Id))
        {
            ValidateCheckpoint58Coverage(
                study, technologyProfiles, auxiliaryProfiles);
        }
        else
        {
            throw new InvalidOperationException(
                $"Unsupported integrated tactical-combat study '{study.Id}'.");
        }
    }

    private static void ValidateTl2CandidateCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles)
    {
        string[] candidateIds = technologyProfiles.Keys
            .Where(id => id.StartsWith("tl2-", StringComparison.Ordinal))
            .OrderBy(id => id, StringComparer.Ordinal)
            .ToArray();
        if (candidateIds.Length != 3)
        {
            throw new InvalidOperationException(
                $"TL2 candidate grid requires exactly three candidate profiles; found {candidateIds.Length}.");
        }
        WeaponFamily[] families =
        {
            WeaponFamily.Kinetic,
            WeaponFamily.Energy,
            WeaponFamily.Missile,
        };
        Tl1IntegratedMovementMode[] ranges =
        {
            Tl1IntegratedMovementMode.HoldRange2,
            Tl1IntegratedMovementMode.HoldRange3,
            Tl1IntegratedMovementMode.HoldRange4,
            Tl1IntegratedMovementMode.HoldRange5,
        };
        foreach (string candidate in candidateIds)
        foreach (WeaponFamily familyA in families)
        foreach (WeaponFamily familyB in families)
        foreach (Tl1IntegratedMovementMode range in ranges)
        {
            RequireTechnologyPair(
                study, candidate, candidate, familyA, familyB, range);
            RequireTechnologyPair(
                study, candidate, "tl1-production", familyA, familyB, range);
            RequireTechnologyPair(
                study, "tl1-production", candidate, familyA, familyB, range);
        }
    }

    private static void ValidateTl2AttributionCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles)
    {
        string[] profileIds = technologyProfiles.Keys
            .Where(id => id.StartsWith("tl2-", StringComparison.Ordinal))
            .OrderBy(id => id, StringComparer.Ordinal)
            .ToArray();
        if (!profileIds.SequenceEqual(
                RequiredTl2AttributionProfileIds.OrderBy(
                    id => id, StringComparer.Ordinal),
                StringComparer.Ordinal))
        {
            throw new InvalidOperationException(
                "TL2 attribution catalog does not contain the exact 19 required profiles.");
        }

        WeaponFamily[] families =
        {
            WeaponFamily.Kinetic,
            WeaponFamily.Energy,
            WeaponFamily.Missile,
        };
        Tl1IntegratedMovementMode[] fixedRanges =
        {
            Tl1IntegratedMovementMode.HoldRange2,
            Tl1IntegratedMovementMode.HoldRange3,
            Tl1IntegratedMovementMode.HoldRange4,
            Tl1IntegratedMovementMode.HoldRange5,
        };
        foreach (string profileId in RequiredTl2AttributionProfileIds)
        foreach (WeaponFamily familyA in families)
        foreach (WeaponFamily familyB in families)
        foreach (Tl1IntegratedMovementMode range in fixedRanges)
        {
            RequireTechnologyPair(
                study, profileId, "tl1-production", familyA, familyB, range);
            RequireTechnologyPair(
                study, "tl1-production", profileId, familyA, familyB, range);
        }

        Tl1IntegratedMovementMode[] dynamicModes =
        {
            Tl1IntegratedMovementMode.ScriptedPursuit,
            Tl1IntegratedMovementMode.PreferredRange,
        };
        foreach (string profileId in Tl2AttributionMovementProfileIds)
        foreach (WeaponFamily familyA in families)
        foreach (WeaponFamily familyB in families)
        foreach (Tl1IntegratedMovementMode mode in dynamicModes)
        {
            RequireTechnologyDynamicPair(
                study, profileId, "tl1-production", familyA, familyB, mode);
            RequireTechnologyDynamicPair(
                study, "tl1-production", profileId, familyA, familyB, mode);
        }

        foreach (string profileId in Tl2AttributionSameTlProfileIds)
        foreach (WeaponFamily familyA in families)
        foreach (WeaponFamily familyB in families)
        foreach (Tl1IntegratedMovementMode range in fixedRanges)
        {
            RequireTechnologyPair(
                study, profileId, profileId, familyA, familyB, range);
        }

        if (study.Variants.Any(variant =>
            variant.ProtectedCompartmentation ||
            variant.DamageControl != Tl1IntegratedDamageControlMode.None ||
            !(variant.BaseShieldRechargeEnabled ?? true) ||
            (variant.EvasiveManeuversEnabled ?? true) ||
            !(variant.PdsEnabled ?? true) ||
            (variant.EscapeDisengagementEnabled ?? true)))
        {
            throw new InvalidOperationException(
                "TL2 attribution lanes must use the registered minimal-tactics contract.");
        }

        TechnologyCombatProfile production = technologyProfiles["tl1-production"];
        TechnologyCombatProfile nullControl =
            technologyProfiles["tl2-attr-null-control"];
        if (!SameCombatVector(production, nullControl))
        {
            throw new InvalidOperationException(
                "The TL2 null-vector control must exactly match the TL1 combat vector.");
        }
    }

    private static void ValidateTl2DefensiveRefinementCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles)
    {
        string[] profileIds = technologyProfiles.Keys
            .Where(id => id.StartsWith("tl2-", StringComparison.Ordinal))
            .OrderBy(id => id, StringComparer.Ordinal)
            .ToArray();
        if (!profileIds.SequenceEqual(
                RequiredTl2DefensiveRefinementProfileIds.OrderBy(
                    id => id, StringComparer.Ordinal),
                StringComparer.Ordinal))
        {
            throw new InvalidOperationException(
                "TL2 defensive-refinement catalog does not contain the exact nine required profiles.");
        }

        WeaponFamily[] families =
        {
            WeaponFamily.Kinetic,
            WeaponFamily.Energy,
            WeaponFamily.Missile,
        };
        Tl1IntegratedMovementMode[] fixedRanges =
        {
            Tl1IntegratedMovementMode.HoldRange2,
            Tl1IntegratedMovementMode.HoldRange3,
            Tl1IntegratedMovementMode.HoldRange4,
            Tl1IntegratedMovementMode.HoldRange5,
        };
        foreach (string profileId in RequiredTl2DefensiveRefinementProfileIds)
        foreach (WeaponFamily familyA in families)
        foreach (WeaponFamily familyB in families)
        {
            foreach (Tl1IntegratedMovementMode range in fixedRanges)
            {
                RequireTechnologyPair(
                    study, profileId, "tl1-production", familyA, familyB, range);
                RequireTechnologyPair(
                    study, "tl1-production", profileId, familyA, familyB, range);
            }
            RequireRefinementLane(
                study, profileId, "tl1-production", familyA, familyB,
                Tl1IntegratedMovementMode.PreferredRange,
                "tl2-r45-preferred-range", escapeEnabled: false);
            RequireRefinementLane(
                study, "tl1-production", profileId, familyA, familyB,
                Tl1IntegratedMovementMode.PreferredRange,
                "tl2-r45-preferred-range", escapeEnabled: false);
            RequireRefinementLane(
                study, profileId, "tl1-production", familyA, familyB,
                Tl1IntegratedMovementMode.ScriptedPursuit,
                "tl2-r45-pursuit-combat", escapeEnabled: false);
            RequireRefinementLane(
                study, "tl1-production", profileId, familyA, familyB,
                Tl1IntegratedMovementMode.ScriptedPursuit,
                "tl2-r45-escape-control", escapeEnabled: true);
        }

        foreach (string profileId in Tl2DefensiveRefinementSameTlProfileIds)
        foreach (WeaponFamily familyA in families)
        foreach (WeaponFamily familyB in families)
        foreach (Tl1IntegratedMovementMode range in fixedRanges)
        {
            RequireTechnologyPair(
                study, profileId, profileId, familyA, familyB, range);
        }

        if (study.Variants.Any(variant =>
            variant.ProtectedCompartmentation ||
            variant.DamageControl != Tl1IntegratedDamageControlMode.None ||
            !(variant.BaseShieldRechargeEnabled ?? true) ||
            (variant.EvasiveManeuversEnabled ?? true) ||
            !(variant.PdsEnabled ?? true)))
        {
            throw new InvalidOperationException(
                "TL2 defensive-refinement lanes must use the registered minimal-tactics contract.");
        }
        if (study.Variants.Any(variant =>
            (variant.ProfileLabel == "tl2-r45-escape-control") !=
                (variant.EscapeDisengagementEnabled ?? true)))
        {
            throw new InvalidOperationException(
                "Only the registered escape-control lanes may enable disengagement.");
        }

        TechnologyCombatProfile production = technologyProfiles["tl1-production"];
        TechnologyCombatProfile nullControl =
            technologyProfiles["tl2-r45-null-control"];
        if (!SameCombatVector(production, nullControl))
        {
            throw new InvalidOperationException(
                "The Checkpoint 45 TL2 null-vector control must exactly match TL1.");
        }
    }

    private static void ValidateTl2DynamicWeaponChoiceCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles)
    {
        string[] profileIds = technologyProfiles.Keys
            .Where(id => id.StartsWith("tl2-", StringComparison.Ordinal))
            .OrderBy(id => id, StringComparer.Ordinal)
            .ToArray();
        if (!profileIds.SequenceEqual(
                RequiredTl2DynamicWeaponChoiceProfileIds.OrderBy(
                    id => id, StringComparer.Ordinal),
                StringComparer.Ordinal))
        {
            throw new InvalidOperationException(
                "TL2 dynamic weapon-choice catalog does not contain the exact two required profiles.");
        }

        Tl1IntegratedMovementMode[] fixedRanges =
        {
            Tl1IntegratedMovementMode.HoldRange2,
            Tl1IntegratedMovementMode.HoldRange3,
            Tl1IntegratedMovementMode.HoldRange4,
        };
        foreach (string profileId in RequiredTl2DynamicWeaponChoiceProfileIds)
        foreach ((WeaponFamily first, WeaponFamily second) in
            Tl2DynamicWeaponChoicePairs)
        {
            foreach ((WeaponFamily familyA, WeaponFamily familyB) in new[]
            {
                (first, second),
                (second, first),
            })
            {
                foreach (Tl1IntegratedMovementMode fixedRange in fixedRanges)
                {
                    RequireDynamicWeaponChoiceLane(
                        study,
                        profileId,
                        familyA,
                        familyB,
                        fixedRange,
                        initialRange: null,
                        "tl2-r46-fixed-mutual-control");
                }
                for (int initialRange = 1; initialRange <= 6; initialRange++)
                {
                    RequireDynamicWeaponChoiceLane(
                        study,
                        profileId,
                        familyA,
                        familyB,
                        Tl1IntegratedMovementMode.PreferredRange,
                        initialRange,
                        "tl2-r46-dynamic-preferred-range");
                }
            }
        }

        if (study.Variants.Any(variant =>
            variant.SideAProfileId != variant.SideBProfileId ||
            variant.SideAProfileId is null ||
            !RequiredTl2DynamicWeaponChoiceProfileIds.Contains(
                variant.SideAProfileId, StringComparer.Ordinal) ||
            variant.SideAFamily == variant.SideBFamily ||
            variant.ProtectedCompartmentation ||
            variant.DamageControl != Tl1IntegratedDamageControlMode.None ||
            !(variant.BaseShieldRechargeEnabled ?? true) ||
            (variant.EvasiveManeuversEnabled ?? true) ||
            !(variant.PdsEnabled ?? true) ||
            (variant.EscapeDisengagementEnabled ?? true)))
        {
            throw new InvalidOperationException(
                "TL2 dynamic weapon-choice lanes must use same-profile cross-family minimal tactics without disengagement.");
        }

        if (study.Variants.Where(variant =>
                variant.MovementMode == Tl1IntegratedMovementMode.PreferredRange)
            .Any(variant => variant.InitialRangeHexes is < 1 or > 6))
        {
            throw new InvalidOperationException(
                "Every dynamic weapon-choice lane must declare an initial range from 1 through 6.");
        }
        if (study.Variants.Where(variant =>
                variant.MovementMode != Tl1IntegratedMovementMode.PreferredRange)
            .Any(variant => variant.InitialRangeHexes.HasValue))
        {
            throw new InvalidOperationException(
                "Fixed mutual-envelope controls must use their movement-mode range without an override.");
        }
    }

    private static void ValidateTl2OpponentAwareRangeCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles)
    {
        string[] profileIds = technologyProfiles.Keys
            .Where(id => id.StartsWith("tl2-", StringComparison.Ordinal))
            .OrderBy(id => id, StringComparer.Ordinal)
            .ToArray();
        if (!profileIds.SequenceEqual(
                RequiredTl2DynamicWeaponChoiceProfileIds.OrderBy(
                    id => id, StringComparer.Ordinal),
                StringComparer.Ordinal))
        {
            throw new InvalidOperationException(
                "TL2 opponent-aware range catalog does not contain the exact two required profiles.");
        }

        foreach (string profileId in RequiredTl2DynamicWeaponChoiceProfileIds)
        foreach ((WeaponFamily first, WeaponFamily second) in
            Tl2DynamicWeaponChoicePairs)
        foreach ((WeaponFamily familyA, WeaponFamily familyB) in new[]
        {
            (first, second),
            (second, first),
        })
        foreach (int initialRange in Enumerable.Range(1, 6))
        {
            RequireDynamicWeaponChoiceLane(
                study,
                profileId,
                familyA,
                familyB,
                Tl1IntegratedMovementMode.PreferredRange,
                initialRange,
                "tl2-r47-family-preferred-control");
            RequireDynamicWeaponChoiceLane(
                study,
                profileId,
                familyA,
                familyB,
                Tl1IntegratedMovementMode.OpponentAwareRange,
                initialRange,
                "tl2-r47-opponent-aware-range");
        }

        foreach (string profileId in RequiredTl2DynamicWeaponChoiceProfileIds)
        foreach ((WeaponFamily familyA, WeaponFamily familyB) in new[]
        {
            (WeaponFamily.Kinetic, WeaponFamily.Energy),
            (WeaponFamily.Energy, WeaponFamily.Kinetic),
        })
        {
            RequireDynamicWeaponChoiceLane(
                study,
                profileId,
                familyA,
                familyB,
                Tl1IntegratedMovementMode.HoldRange5,
                initialRange: null,
                "tl2-r47-fixed-range5-control");
        }

        if (study.Variants.Any(variant =>
            variant.SideAProfileId != variant.SideBProfileId ||
            variant.SideAProfileId is null ||
            !RequiredTl2DynamicWeaponChoiceProfileIds.Contains(
                variant.SideAProfileId, StringComparer.Ordinal) ||
            variant.SideAFamily == variant.SideBFamily ||
            variant.ProtectedCompartmentation ||
            variant.DamageControl != Tl1IntegratedDamageControlMode.None ||
            !(variant.BaseShieldRechargeEnabled ?? true) ||
            (variant.EvasiveManeuversEnabled ?? true) ||
            !(variant.PdsEnabled ?? true) ||
            (variant.EscapeDisengagementEnabled ?? true)))
        {
            throw new InvalidOperationException(
                "TL2 opponent-aware range lanes must use same-profile cross-family minimal tactics without disengagement.");
        }

        if (study.Variants.Where(variant => variant.MovementMode is
                Tl1IntegratedMovementMode.PreferredRange or
                Tl1IntegratedMovementMode.OpponentAwareRange)
            .Any(variant => variant.InitialRangeHexes is < 1 or > 6))
        {
            throw new InvalidOperationException(
                "Every dynamic range-policy lane must declare an initial range from 1 through 6.");
        }
        if (study.Variants.Where(variant =>
                variant.MovementMode == Tl1IntegratedMovementMode.HoldRange5)
            .Any(variant => variant.InitialRangeHexes.HasValue))
        {
            throw new InvalidOperationException(
                "Fixed Range 5 controls must use their movement-mode range without an override.");
        }
    }

    private static void ValidateAuxiliaryPerformanceScreeningCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        if (!technologyProfiles.ContainsKey("tl1-production") ||
            !technologyProfiles.ContainsKey("tl2-production"))
        {
            throw new InvalidOperationException(
                "Auxiliary screening requires accepted TL1 and TL2 production profiles.");
        }
        bool architectureDerived = study.Id is ArchitectureDerivedAuxiliaryStudyId or
            StatefulAuxiliaryTuningStudyId or AuxiliaryRefinementStudyId;
        bool statefulTuning = study.Id == StatefulAuxiliaryTuningStudyId;
        bool checkpoint53Refinement = study.Id == AuxiliaryRefinementStudyId;
        int expectedTl1 = checkpoint53Refinement ? 7 : architectureDerived ? 8 : 7;
        int expectedTl2 = architectureDerived ? 9 : 14;
        int tl2Capacity = architectureDerived ? 1 : 2;
        string legalLabel = checkpoint53Refinement
            ? "aux-r53-refined-legal-matrix"
            : statefulTuning
                ? "aux-r52-stateful-legal-matrix"
                : architectureDerived
                    ? "aux-r51-architecture-legal-matrix"
                    : "aux-r48-legal-matrix";
        string diagnosticLabel = checkpoint53Refinement
            ? "aux-r53-no-aux-diagnostic"
            : statefulTuning
                ? "aux-r52-no-aux-diagnostic"
                : architectureDerived
                    ? "aux-r51-no-aux-diagnostic"
                    : "aux-r48-no-aux-diagnostic";
        int expectedLegal = checkpoint53Refinement ? 768 : architectureDerived ? 867 : 1323;
        int expectedDiagnostics = checkpoint53Refinement ? 102 : architectureDerived ? 108 : 132;
        int expectedTl1v1 = checkpoint53Refinement ? 147 : architectureDerived ? 192 : 147;
        int expectedTl2v2 = architectureDerived ? 243 : 588;
        int expectedCrossTl = checkpoint53Refinement ? 378 : architectureDerived ? 432 : 588;

        string[] tl1Aux = auxiliaryProfiles.Values
            .Where(profile => !profile.LegacyIntegratedSuite &&
                !profile.Counterfactual && profile.TechnologyLevel == 1)
            .Select(profile => profile.Id)
            .OrderBy(id => id, StringComparer.Ordinal)
            .ToArray();
        string[] tl2Aux = auxiliaryProfiles.Values
            .Where(profile => !profile.LegacyIntegratedSuite &&
                !profile.Counterfactual && profile.TechnologyLevel == 2)
            .Select(profile => profile.Id)
            .OrderBy(id => id, StringComparer.Ordinal)
            .ToArray();
        if (tl1Aux.Length != expectedTl1 || tl2Aux.Length != expectedTl2)
        {
            throw new InvalidOperationException(
                $"Auxiliary screening requires {expectedTl1} TL1 and {expectedTl2} TL2 legal combat profiles; " +
                $"found {tl1Aux.Length} and {tl2Aux.Length}.");
        }
        AuxiliaryCombatProfile[] none = auxiliaryProfiles.Values
            .Where(profile => profile.Counterfactual && !profile.LegacyIntegratedSuite)
            .OrderBy(profile => profile.TechnologyLevel)
            .ToArray();
        if (none.Length != 2 || none[0].TechnologyLevel != 1 ||
            none[1].TechnologyLevel != 2)
        {
            throw new InvalidOperationException(
                "Auxiliary screening requires one counterfactual no-AUX profile at TL1 and TL2.");
        }
        if (study.Variants.Count(variant =>
                variant.ProfileLabel == legalLabel) != expectedLegal ||
            study.Variants.Count(variant =>
                variant.ProfileLabel == diagnosticLabel) != expectedDiagnostics)
        {
            throw new InvalidOperationException(
                $"Auxiliary screening must contain {expectedLegal} legal variants and {expectedDiagnostics} isolated no-AUX diagnostics.");
        }
        if (study.Variants.Any(variant =>
            variant.SideAFamily != variant.SideBFamily ||
            variant.MovementMode != Tl1IntegratedMovementMode.OpponentAwareRange ||
            variant.InitialRangeHexes is null ||
            variant.ProtectedCompartmentation ||
            variant.DamageControl !=
                Tl1IntegratedDamageControlMode.ComponentFirstReserveOne ||
            !(variant.BaseShieldRechargeEnabled ?? true) ||
            !(variant.EvasiveManeuversEnabled ?? true) ||
            !(variant.PdsEnabled ?? true) ||
            (variant.EscapeDisengagementEnabled ?? true) ||
            string.IsNullOrWhiteSpace(variant.SideAAuxiliaryProfileId) ||
            string.IsNullOrWhiteSpace(variant.SideBAuxiliaryProfileId)))
        {
            throw new InvalidOperationException(
                "Auxiliary screening variants must use same-family opponent-aware combat, explicit AUX loadouts, ordinary recharge, Damage Control, and no disengagement.");
        }
        foreach (Tl1IntegratedTacticalCombatVariantDocument variant in study.Variants)
        {
            AuxiliaryCombatProfile auxA = auxiliaryProfiles[
                variant.SideAAuxiliaryProfileId!];
            AuxiliaryCombatProfile auxB = auxiliaryProfiles[
                variant.SideBAuxiliaryProfileId!];
            int tlA = technologyProfiles[variant.SideAProfileId!].TechnologyLevel;
            int tlB = technologyProfiles[variant.SideBProfileId!].TechnologyLevel;
            if (auxA.TechnologyLevel != tlA || auxB.TechnologyLevel != tlB)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' must use the TL-appropriate AUX profile on both ships.");
            }
            int capacityA = tlA == 1 ? 1 : tl2Capacity;
            int capacityB = tlB == 1 ? 1 : tl2Capacity;
            if (auxA.CapacityCost > capacityA || auxB.CapacityCost > capacityB)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' exceeds the active Auxiliary Capacity context.");
            }
            int expectedRange = variant.SideAFamily switch
            {
                WeaponFamily.Kinetic => 3,
                WeaponFamily.Energy => 4,
                WeaponFamily.Missile => 5,
                _ => throw new InvalidOperationException("Unsupported AUX screening family."),
            };
            if (variant.InitialRangeHexes != expectedRange)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' uses an unexpected family control range.");
            }
            bool legalLane = variant.ProfileLabel == legalLabel;
            if (legalLane && (auxA.Counterfactual || auxB.Counterfactual))
            {
                throw new InvalidOperationException(
                    $"Legal AUX matrix variant '{variant.Id}' contains a no-AUX loadout.");
            }
            if (!legalLane && variant.ProfileLabel != diagnosticLabel)
            {
                throw new InvalidOperationException(
                    $"Variant '{variant.Id}' uses an unexpected AUX study partition.");
            }
            if (!legalLane && !auxA.Counterfactual && !auxB.Counterfactual)
            {
                throw new InvalidOperationException(
                    $"No-AUX diagnostic '{variant.Id}' does not contain a counterfactual loadout.");
            }
        }
        int tl1v1 = study.Variants.Count(variant =>
            variant.ProfileLabel == legalLabel &&
            variant.SideAProfileId == "tl1-production" &&
            variant.SideBProfileId == "tl1-production");
        int tl2v2 = study.Variants.Count(variant =>
            variant.ProfileLabel == legalLabel &&
            variant.SideAProfileId == "tl2-production" &&
            variant.SideBProfileId == "tl2-production");
        int tl1v2 = study.Variants.Count(variant =>
            variant.ProfileLabel == legalLabel &&
            variant.SideAProfileId != variant.SideBProfileId);
        if (tl1v1 != expectedTl1v1 || tl2v2 != expectedTl2v2 ||
            tl1v2 != expectedCrossTl)
        {
            throw new InvalidOperationException(
                $"Auxiliary matrix band counts must be {expectedTl1v1}/{expectedTl2v2}/{expectedCrossTl}; " +
                $"found {tl1v1}/{tl2v2}/{tl1v2}.");
        }
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantDocument> group in
            study.Variants.GroupBy(variant => variant.ComparisonGroup ?? string.Empty,
                StringComparer.Ordinal))
        {
            int expected = group.First().SideAProfileId == group.First().SideBProfileId &&
                group.First().SideAAuxiliaryProfileId ==
                    group.First().SideBAuxiliaryProfileId
                ? 1
                : 2;
            if (group.Count() != expected)
            {
                throw new InvalidOperationException(
                    $"Auxiliary comparison group '{group.Key}' requires {expected} orientation lane(s); found {group.Count()}.");
            }
        }
    }

    private static void RequireDynamicWeaponChoiceLane(
        Tl1IntegratedTacticalCombatStudyDocument study,
        string profileId,
        WeaponFamily familyA,
        WeaponFamily familyB,
        Tl1IntegratedMovementMode mode,
        int? initialRange,
        string profileLabel)
    {
        int count = study.Variants.Count(variant =>
            variant.SideAProfileId == profileId &&
            variant.SideBProfileId == profileId &&
            variant.SideAFamily == familyA &&
            variant.SideBFamily == familyB &&
            variant.MovementMode == mode &&
            variant.InitialRangeHexes == initialRange &&
            variant.ProfileLabel == profileLabel &&
            !variant.ProtectedCompartmentation &&
            variant.DamageControl == Tl1IntegratedDamageControlMode.None &&
            (variant.BaseShieldRechargeEnabled ?? true) &&
            !(variant.EvasiveManeuversEnabled ?? true) &&
            (variant.PdsEnabled ?? true) &&
            !(variant.EscapeDisengagementEnabled ?? true));
        if (count != 1)
        {
            throw new InvalidOperationException(
                $"TL2 dynamic weapon-choice study requires one {profileId} " +
                $"{familyA}/{familyB} {profileLabel} lane at " +
                $"range {(initialRange?.ToString(CultureInfo.InvariantCulture) ?? mode.ToString())}; found {count}.");
        }
    }

    private static void RequireRefinementLane(
        Tl1IntegratedTacticalCombatStudyDocument study,
        string sideAProfile,
        string sideBProfile,
        WeaponFamily familyA,
        WeaponFamily familyB,
        Tl1IntegratedMovementMode mode,
        string profileLabel,
        bool escapeEnabled)
    {
        int count = study.Variants.Count(variant =>
            variant.SideAProfileId == sideAProfile &&
            variant.SideBProfileId == sideBProfile &&
            variant.SideAFamily == familyA &&
            variant.SideBFamily == familyB &&
            variant.MovementMode == mode &&
            variant.ProfileLabel == profileLabel &&
            !variant.ProtectedCompartmentation &&
            variant.DamageControl == Tl1IntegratedDamageControlMode.None &&
            (variant.BaseShieldRechargeEnabled ?? true) &&
            !(variant.EvasiveManeuversEnabled ?? true) &&
            (variant.PdsEnabled ?? true) &&
            (variant.EscapeDisengagementEnabled ?? true) == escapeEnabled);
        if (count != 1)
        {
            throw new InvalidOperationException(
                $"TL2 defensive-refinement study requires one {profileLabel} " +
                $"{sideAProfile} versus {sideBProfile} {familyA}/{familyB} lane; " +
                $"found {count}.");
        }
    }

    private static bool SameCombatVector(
        TechnologyCombatProfile first,
        TechnologyCombatProfile second) =>
        first.Hull == second.Hull &&
        first.ArmorIntegrity == second.ArmorIntegrity &&
        first.ArmorProtection == second.ArmorProtection &&
        first.ShieldCapacity == second.ShieldCapacity &&
        first.ShieldBaseRecharge == second.ShieldBaseRecharge &&
        first.ShieldArmor == second.ShieldArmor &&
        first.ReactorOutput == second.ReactorOutput &&
        first.TargetingBonus == second.TargetingBonus &&
        first.EffectivePdsChance == second.EffectivePdsChance &&
        first.PdsPower == second.PdsPower &&
        first.StandardCombatPowerCommitment ==
            second.StandardCombatPowerCommitment &&
        first.ShipMove == second.ShipMove &&
        first.MissileMove == second.MissileMove &&
        SameWeaponVector(first.Kinetic, second.Kinetic) &&
        SameWeaponVector(first.Energy, second.Energy) &&
        SameWeaponVector(first.Missile, second.Missile);

    private static bool SameWeaponVector(
        ScalingWeaponProfile first,
        ScalingWeaponProfile second) =>
        first.Family == second.Family &&
        first.Damage == second.Damage &&
        first.ShieldPenetration == second.ShieldPenetration &&
        first.ArmorPenetration == second.ArmorPenetration &&
        first.AccuracyBonus == second.AccuracyBonus &&
        first.GuidanceChance == second.GuidanceChance &&
        first.MaximumRange == second.MaximumRange &&
        first.PowerCost == second.PowerCost &&
        first.Ammunition == second.Ammunition;

    private static void RequireTechnologyDynamicPair(
        Tl1IntegratedTacticalCombatStudyDocument study,
        string sideAProfile,
        string sideBProfile,
        WeaponFamily familyA,
        WeaponFamily familyB,
        Tl1IntegratedMovementMode mode)
    {
        int count = study.Variants.Count(variant =>
            variant.SideAProfileId == sideAProfile &&
            variant.SideBProfileId == sideBProfile &&
            variant.SideAFamily == familyA &&
            variant.SideBFamily == familyB &&
            variant.MovementMode == mode &&
            !variant.ProtectedCompartmentation &&
            variant.DamageControl == Tl1IntegratedDamageControlMode.None &&
            (variant.BaseShieldRechargeEnabled ?? true) &&
            !(variant.EvasiveManeuversEnabled ?? true) &&
            (variant.PdsEnabled ?? true) &&
            !(variant.EscapeDisengagementEnabled ?? true));
        if (count != 1)
        {
            throw new InvalidOperationException(
                $"TL2 attribution study requires one {sideAProfile} versus " +
                $"{sideBProfile} {familyA}/{familyB} {mode} lane; found {count}.");
        }
    }

    private static void RequireTechnologyPair(
        Tl1IntegratedTacticalCombatStudyDocument study,
        string sideAProfile,
        string sideBProfile,
        WeaponFamily familyA,
        WeaponFamily familyB,
        Tl1IntegratedMovementMode range)
    {
        int count = study.Variants.Count(variant =>
            variant.SideAProfileId == sideAProfile &&
            variant.SideBProfileId == sideBProfile &&
            variant.SideAFamily == familyA &&
            variant.SideBFamily == familyB &&
            variant.MovementMode == range &&
            !variant.ProtectedCompartmentation &&
            variant.DamageControl == Tl1IntegratedDamageControlMode.None &&
            (variant.BaseShieldRechargeEnabled ?? true) &&
            !(variant.EvasiveManeuversEnabled ?? true) &&
            (variant.PdsEnabled ?? true) &&
            !(variant.EscapeDisengagementEnabled ?? true));
        if (count != 1)
        {
            throw new InvalidOperationException(
                "TL2 candidate grid requires exactly one minimal-tactics variant " +
                $"for {sideAProfile}/{sideBProfile}/{familyA}/{familyB}/{range}; found {count}.");
        }
    }

    private static void ValidatePrimaryCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study)
    {
        WeaponFamily[] families =
        {
            WeaponFamily.Kinetic,
            WeaponFamily.Energy,
            WeaponFamily.Missile,
        };
        foreach (WeaponFamily familyA in families)
        foreach (WeaponFamily familyB in families)
        foreach (Tl1IntegratedDamageControlMode damageControl in
            Enum.GetValues<Tl1IntegratedDamageControlMode>())
        {
            foreach (Tl1IntegratedMovementMode mode in new[]
            {
                Tl1IntegratedMovementMode.HoldRange2,
                Tl1IntegratedMovementMode.HoldRange4,
                Tl1IntegratedMovementMode.ScriptedPursuit,
            })
            {
                int count = study.Variants.Count(variant =>
                    variant.SideAFamily == familyA &&
                    variant.SideBFamily == familyB &&
                    variant.MovementMode == mode &&
                    !variant.ProtectedCompartmentation &&
                    variant.DamageControl == damageControl);
                if (count != 1)
                {
                    throw new InvalidOperationException(
                        "Each fixed/scripted family pairing requires one ordinary " +
                        $"{damageControl} variant; missing {familyA}/{familyB}/{mode}.");
                }
            }
            foreach (bool protectedCompartmentation in new[] { false, true })
            {
                int count = study.Variants.Count(variant =>
                    variant.SideAFamily == familyA &&
                    variant.SideBFamily == familyB &&
                    variant.MovementMode ==
                        Tl1IntegratedMovementMode.PreferredRange &&
                    variant.ProtectedCompartmentation == protectedCompartmentation &&
                    variant.DamageControl == damageControl);
                if (count != 1)
                {
                    throw new InvalidOperationException(
                        "Each preferred-range family pairing requires ordinary " +
                        "and Protected variants for both Damage Control states.");
                }
            }
        }
    }

    private static void ValidateDiagnosticCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study)
    {
        string[] requiredProfiles =
        {
            "production-1-2",
            "godot-3-2",
            "legacy-4-1",
            "overload-equivalent-2-2",
        };
        foreach (string profile in requiredProfiles)
        {
            if (!study.Variants.Any(variant =>
                string.Equals(variant.ProfileLabel, profile,
                    StringComparison.Ordinal)))
            {
                throw new InvalidOperationException(
                    $"Diagnostic study is missing movement profile '{profile}'.");
            }
        }

        (int Damage, int Apen)[] kineticArms =
        {
            (3, 0),
            (4, 0),
            (5, 0),
            (4, 1),
        };
        foreach ((int damage, int apen) in kineticArms)
        {
            if (!study.Variants.Any(variant =>
                (variant.KineticDamage ?? 4) == damage &&
                (variant.KineticArmorPenetration ?? 0) == apen &&
                (variant.PrimaryArmorProtection ?? 0) == 1))
            {
                throw new InvalidOperationException(
                    $"Diagnostic study is missing kinetic arm DAM {damage}/APEN {apen}.");
            }
        }
        foreach ((bool shield, bool evm) in new[]
        {
            (true, true),
            (false, true),
            (true, false),
            (false, false),
        })
        {
            if (!study.Variants.Any(variant =>
                (variant.BaseShieldRechargeEnabled ?? true) == shield &&
                (variant.EvasiveManeuversEnabled ?? true) == evm))
            {
                throw new InvalidOperationException(
                    "Diagnostic study is missing a Shield-recharge/EvM control arm.");
            }
        }
    }

    private static void ValidateMinimalTacticsCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study)
    {
        WeaponFamily[] families =
        {
            WeaponFamily.Kinetic,
            WeaponFamily.Energy,
            WeaponFamily.Missile,
        };
        Tl1IntegratedMovementMode[] fixedRanges =
        {
            Tl1IntegratedMovementMode.HoldRange2,
            Tl1IntegratedMovementMode.HoldRange3,
            Tl1IntegratedMovementMode.HoldRange4,
            Tl1IntegratedMovementMode.HoldRange5,
        };

        foreach (WeaponFamily familyA in families)
        foreach (WeaponFamily familyB in families)
        foreach (Tl1IntegratedMovementMode mode in fixedRanges)
        {
            int primaryCount = study.Variants.Count(variant =>
                variant.ProfileLabel == "minimal-primary-ap0" &&
                variant.SideAFamily == familyA &&
                variant.SideBFamily == familyB &&
                variant.MovementMode == mode &&
                !variant.ProtectedCompartmentation &&
                variant.DamageControl == Tl1IntegratedDamageControlMode.None &&
                (variant.PrimaryArmorProtection ?? 0) == 0 &&
                (variant.BaseShieldRechargeEnabled ?? true) &&
                !(variant.EvasiveManeuversEnabled ?? true) &&
                (variant.PdsEnabled ?? true) &&
                !(variant.EscapeDisengagementEnabled ?? true));
            if (primaryCount != 1)
            {
                throw new InvalidOperationException(
                    "Minimal-tactics AP 0 grid requires exactly one no-adaptation " +
                    $"variant for {familyA}/{familyB}/{mode}.");
            }

            int apOneCount = study.Variants.Count(variant =>
                variant.ProfileLabel == "control-ap1" &&
                variant.SideAFamily == familyA &&
                variant.SideBFamily == familyB &&
                variant.MovementMode == mode &&
                !variant.ProtectedCompartmentation &&
                variant.DamageControl == Tl1IntegratedDamageControlMode.None &&
                (variant.PrimaryArmorProtection ?? 0) == 1 &&
                (variant.BaseShieldRechargeEnabled ?? true) &&
                !(variant.EvasiveManeuversEnabled ?? true) &&
                (variant.PdsEnabled ?? true) &&
                !(variant.EscapeDisengagementEnabled ?? true));
            if (apOneCount != 1)
            {
                throw new InvalidOperationException(
                    "Minimal-tactics AP 1 diagnostic grid requires exactly one " +
                    $"variant for {familyA}/{familyB}/{mode}.");
            }
        }

        foreach (WeaponFamily familyA in families)
        foreach (WeaponFamily familyB in families)
        {
            RequireSingleRangeFourControl(
                study, familyA, familyB, "control-damcon",
                variant => variant.DamageControl ==
                    Tl1IntegratedDamageControlMode.ComponentFirstReserveOne &&
                    !variant.ProtectedCompartmentation &&
                    !(variant.EvasiveManeuversEnabled ?? true) &&
                    (variant.BaseShieldRechargeEnabled ?? true) &&
                    (variant.PdsEnabled ?? true) &&
                    !(variant.EscapeDisengagementEnabled ?? true));
            RequireSingleRangeFourControl(
                study, familyA, familyB, "control-evm",
                variant =>
                    variant.DamageControl == Tl1IntegratedDamageControlMode.None &&
                    !variant.ProtectedCompartmentation &&
                    (variant.EvasiveManeuversEnabled ?? true) &&
                    (variant.BaseShieldRechargeEnabled ?? true) &&
                    (variant.PdsEnabled ?? true) &&
                    !(variant.EscapeDisengagementEnabled ?? true));
            RequireSingleRangeFourControl(
                study, familyA, familyB, "control-protected",
                variant =>
                    variant.DamageControl == Tl1IntegratedDamageControlMode.None &&
                    variant.ProtectedCompartmentation &&
                    !(variant.EvasiveManeuversEnabled ?? true) &&
                    (variant.BaseShieldRechargeEnabled ?? true) &&
                    (variant.PdsEnabled ?? true) &&
                    !(variant.EscapeDisengagementEnabled ?? true));
            RequireSingleRangeFourControl(
                study, familyA, familyB, "control-shield-off",
                variant =>
                    variant.DamageControl == Tl1IntegratedDamageControlMode.None &&
                    !variant.ProtectedCompartmentation &&
                    !(variant.EvasiveManeuversEnabled ?? true) &&
                    !(variant.BaseShieldRechargeEnabled ?? true) &&
                    (variant.PdsEnabled ?? true) &&
                    !(variant.EscapeDisengagementEnabled ?? true));
        }

        foreach ((WeaponFamily familyA, WeaponFamily familyB) in new[]
        {
            (WeaponFamily.Missile, WeaponFamily.Missile),
            (WeaponFamily.Kinetic, WeaponFamily.Missile),
            (WeaponFamily.Missile, WeaponFamily.Kinetic),
            (WeaponFamily.Energy, WeaponFamily.Missile),
            (WeaponFamily.Missile, WeaponFamily.Energy),
        })
        {
            RequireSingleRangeFourControl(
                study, familyA, familyB, "control-pds-off",
                variant =>
                    variant.DamageControl == Tl1IntegratedDamageControlMode.None &&
                    !variant.ProtectedCompartmentation &&
                    !(variant.EvasiveManeuversEnabled ?? true) &&
                    (variant.BaseShieldRechargeEnabled ?? true) &&
                    !(variant.PdsEnabled ?? true) &&
                    !(variant.EscapeDisengagementEnabled ?? true));
        }
    }

    private static void ValidateTl1ComposedShipCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        var expectedBuilds = new Dictionary<string, (int Weapons, int Reactors,
            bool Sensor, bool Shield, int Pds, int Used, int Free)>(StringComparer.Ordinal)
        {
            ["balanced_generalist_major"] = (1, 1, true, true, 1, 33, 2),
            ["dual_main_striker_major"] = (2, 1, true, false, 0, 34, 1),
            ["dual_reactor_power_core"] = (1, 2, true, false, 0, 34, 1),
            ["pds_saturator"] = (1, 1, false, false, 5, 35, 0),
            ["dual_main_dual_pds"] = (2, 1, false, false, 2, 35, 0),
            ["shielded_pds_fortress"] = (1, 1, false, true, 3, 34, 1),
        };
        if (study.Builds.Count != expectedBuilds.Count ||
            study.Builds.Select(build => build.Id).Distinct(StringComparer.Ordinal).Count() !=
                study.Builds.Count)
        {
            throw new InvalidOperationException(
                "Checkpoint 61 composed-ship study requires exactly six unique legal builds.");
        }
        foreach (var pair in expectedBuilds)
        {
            string id = pair.Key;
            var expected = pair.Value;
            Tl1IntegratedShipBuildDocument build = study.Builds.SingleOrDefault(candidate =>
                    string.Equals(candidate.Id, id, StringComparison.Ordinal))
                ?? throw new InvalidOperationException(
                    $"Checkpoint 61 composed-ship study is missing build '{id}'.");
            if (build.MainWeaponCount != expected.Weapons ||
                build.MainReactorCount != expected.Reactors ||
                build.ActiveSensor != expected.Sensor ||
                build.ShieldGenerator != expected.Shield ||
                build.KineticPdsCount != expected.Pds ||
                build.UsedSpace != expected.Used ||
                build.FreeSupportSpace != expected.Free)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 61 build '{id}' does not match the accepted Checkpoint 60 envelope.");
            }
            int recomputedSpace = 13 + 6 * build.MainWeaponCount +
                6 * build.MainReactorCount + (build.ActiveSensor ? 3 : 0) +
                (build.ShieldGenerator ? 3 : 0) + 2 * build.KineticPdsCount;
            if (recomputedSpace != build.UsedSpace ||
                35 - recomputedSpace != build.FreeSupportSpace ||
                recomputedSpace > 35)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 61 build '{id}' violates the accepted 35-Space arithmetic.");
            }
        }

        if (!technologyProfiles.TryGetValue(
                "tl1-production", out TechnologyCombatProfile? tl1) ||
            tl1 is null || tl1.TechnologyLevel != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 61 requires the accepted TL1 production technology profile.");
        }
        if (!auxiliaryProfiles.TryGetValue(
                "aux-r53-none-tl1", out AuxiliaryCombatProfile? noAux) ||
            noAux is null || !noAux.Counterfactual || noAux.CapacityCost != 0 ||
            noAux.HasPds || noAux.HasAuxiliaryReactor || noAux.EvasiveManeuvers)
        {
            throw new InvalidOperationException(
                "Checkpoint 61 requires the zero-effect TL1 no-AUX diagnostic profile.");
        }

        WeaponFamily[] families =
        {
            WeaponFamily.Kinetic,
            WeaponFamily.Energy,
            WeaponFamily.Missile,
        };
        foreach (string buildId in expectedBuilds.Keys)
        foreach (WeaponFamily familyA in families)
        foreach (WeaponFamily familyB in families)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] matches = study.Variants.Where(variant =>
                variant.SideABuildId == buildId &&
                variant.SideBBuildId == "balanced_generalist_major" &&
                variant.SideAFamily == familyA &&
                variant.SideBFamily == familyB).ToArray();
            if (matches.Length != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 61 requires one {buildId} {familyA}-vs-{familyB} variant.");
            }
            Tl1IntegratedTacticalCombatVariantDocument variant = matches[0];
            int weaponCount = expectedBuilds[buildId].Weapons;
            if ((weaponCount == 2 && variant.SideASecondaryFamily != familyA) ||
                (weaponCount == 1 && variant.SideASecondaryFamily is not null) ||
                variant.SideBSecondaryFamily is not null ||
                variant.SideAProfileId != "tl1-production" ||
                variant.SideBProfileId != "tl1-production" ||
                variant.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                variant.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                variant.MovementMode != Tl1IntegratedMovementMode.OpponentAwareRange ||
                variant.InitialRangeHexes != 4 ||
                variant.ProtectedCompartmentation ||
                variant.DamageControl != Tl1IntegratedDamageControlMode.ComponentFirstReserveOne ||
                !(variant.BaseShieldRechargeEnabled ?? true) ||
                (variant.EvasiveManeuversEnabled ?? true) ||
                !(variant.PdsEnabled ?? true) ||
                (variant.EscapeDisengagementEnabled ?? true) ||
                variant.SideABackgroundTacticalPowerCommitment != 0 ||
                variant.SideBBackgroundTacticalPowerCommitment != 0)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 61 variant '{variant.Id}' violates the composed-ship control contract.");
            }
        }
    }

    private static void ValidateTl1PowerDoctrineCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        var expectedBuilds = new Dictionary<string, (int Weapons, int Reactors,
            bool Sensor, bool Shield, int Pds, int Used, int Free)>(StringComparer.Ordinal)
        {
            ["balanced_generalist_major"] = (1, 1, true, true, 1, 33, 2),
            ["pds_saturator"] = (1, 1, false, false, 5, 35, 0),
            ["dual_main_dual_pds"] = (2, 1, false, false, 2, 35, 0),
            ["shielded_pds_fortress"] = (1, 1, false, true, 3, 34, 1),
        };
        if (study.Builds.Count != expectedBuilds.Count ||
            study.Builds.Select(build => build.Id).Distinct(StringComparer.Ordinal).Count() !=
                study.Builds.Count)
        {
            throw new InvalidOperationException(
                "Checkpoint 62 power-doctrine study requires exactly four unique composed builds.");
        }
        foreach (var pair in expectedBuilds)
        {
            Tl1IntegratedShipBuildDocument build = study.Builds.SingleOrDefault(candidate =>
                    string.Equals(candidate.Id, pair.Key, StringComparison.Ordinal))
                ?? throw new InvalidOperationException(
                    $"Checkpoint 62 power-doctrine study is missing build '{pair.Key}'.");
            var expected = pair.Value;
            if (build.MainWeaponCount != expected.Weapons ||
                build.MainReactorCount != expected.Reactors ||
                build.ActiveSensor != expected.Sensor ||
                build.ShieldGenerator != expected.Shield ||
                build.KineticPdsCount != expected.Pds ||
                build.UsedSpace != expected.Used ||
                build.FreeSupportSpace != expected.Free)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 62 build '{pair.Key}' does not match the accepted Checkpoint 60/61 envelope.");
            }
        }

        if (!technologyProfiles.TryGetValue(
                "tl1-production", out TechnologyCombatProfile? tl1) ||
            tl1 is null || tl1.TechnologyLevel != 1 || tl1.ReactorOutput != 5)
        {
            throw new InvalidOperationException(
                "Checkpoint 62 requires the accepted TL1 production profile with its unchanged 5-TP reactor baseline.");
        }
        if (!auxiliaryProfiles.TryGetValue(
                "aux-r53-none-tl1", out AuxiliaryCombatProfile? noAux) ||
            noAux is null || !noAux.Counterfactual || noAux.CapacityCost != 0 ||
            noAux.HasPds || noAux.HasAuxiliaryReactor || noAux.EvasiveManeuvers)
        {
            throw new InvalidOperationException(
                "Checkpoint 62 requires the zero-effect TL1 no-AUX diagnostic profile.");
        }

        WeaponFamily[] families =
        {
            WeaponFamily.Kinetic,
            WeaponFamily.Energy,
            WeaponFamily.Missile,
        };
        Tl1TacticalPowerDoctrine[] doctrines =
        {
            Tl1TacticalPowerDoctrine.DefenseFirst,
            Tl1TacticalPowerDoctrine.PrimaryFireFirst,
            Tl1TacticalPowerDoctrine.FullVolleyFirst,
        };
        int[] reactorOutputs = { 4, 5, 6 };
        foreach (string buildId in expectedBuilds.Keys)
        foreach (WeaponFamily familyA in families)
        foreach (Tl1TacticalPowerDoctrine doctrine in doctrines)
        foreach (int reactorOutput in reactorOutputs)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] matches = study.Variants.Where(variant =>
                variant.SideABuildId == buildId &&
                variant.SideBBuildId == "balanced_generalist_major" &&
                variant.SideAFamily == familyA &&
                variant.SideBFamily == WeaponFamily.Missile &&
                variant.SideATacticalPowerDoctrine == doctrine &&
                variant.SideAReactorOutputOverride == reactorOutput).ToArray();
            if (matches.Length != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 62 requires one {buildId}/{familyA}/{doctrine}/R{reactorOutput} variant.");
            }
            Tl1IntegratedTacticalCombatVariantDocument variant = matches[0];
            int weaponCount = expectedBuilds[buildId].Weapons;
            if ((weaponCount == 2 && variant.SideASecondaryFamily != familyA) ||
                (weaponCount == 1 && variant.SideASecondaryFamily is not null) ||
                variant.SideBSecondaryFamily is not null ||
                variant.SideAProfileId != "tl1-production" ||
                variant.SideBProfileId != "tl1-production" ||
                variant.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                variant.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                variant.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.DefenseFirst ||
                variant.SideBReactorOutputOverride != 5 ||
                variant.MovementMode != Tl1IntegratedMovementMode.OpponentAwareRange ||
                variant.InitialRangeHexes != 4 ||
                variant.ProtectedCompartmentation ||
                variant.DamageControl != Tl1IntegratedDamageControlMode.ComponentFirstReserveOne ||
                !(variant.BaseShieldRechargeEnabled ?? true) ||
                (variant.EvasiveManeuversEnabled ?? true) ||
                !(variant.PdsEnabled ?? true) ||
                (variant.EscapeDisengagementEnabled ?? true) ||
                variant.SideABackgroundTacticalPowerCommitment != 0 ||
                variant.SideBBackgroundTacticalPowerCommitment != 0)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 62 variant '{variant.Id}' violates the power-doctrine sensitivity control contract.");
            }
        }
    }

