        {
            Tl1IntegratedTacticalCombatVariantDocument[] lane = study.Variants.Where(variant =>
                variant.SideABuildId == buildId &&
                variant.SideAFamily == familyA).ToArray();
            if (lane.Length != regimes.Length ||
                lane.Select(variant => variant.ComparisonGroup)
                    .Distinct(StringComparer.Ordinal).Count() != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 64 requires one five-regime paired lane for {buildId}/{familyA}.");
            }

            foreach (var regime in regimes)
            {
                Tl1IntegratedTacticalCombatVariantDocument[] matches = lane.Where(variant =>
                    variant.SideBBuildId == "balanced_generalist_major" &&
                    variant.SideBFamily == WeaponFamily.Missile &&
                    variant.ProfileLabel == regime.Label &&
                    variant.SideATrackPolicy == regime.Policy &&
                    variant.SideANetEwRangePenalty == regime.Ew &&
                    variant.MovementMode == regime.Movement).ToArray();
                if (matches.Length != 1)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 64 requires one {buildId}/{familyA}/{regime.Label} variant.");
                }
                Tl1IntegratedTacticalCombatVariantDocument variant = matches[0];
                int weaponCount = expectedBuilds[buildId].Weapons;
                if ((weaponCount == 2 && variant.SideASecondaryFamily != familyA) ||
                    (weaponCount == 1 && variant.SideASecondaryFamily is not null) ||
                    variant.SideBSecondaryFamily is not null ||
                    variant.SideAProfileId != "tl1-production" ||
                    variant.SideBProfileId != "tl1-production" ||
                    variant.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                    variant.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                    variant.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                    variant.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                    variant.SideAReactorOutputOverride != 5 ||
                    variant.SideBReactorOutputOverride != 5 ||
                    variant.SideBTrackPolicy != Tl1OperationalTrackPolicy.EstablishedFirm ||
                    variant.SideBNetEwRangePenalty != 0 ||
                    variant.InitialRangeHexes != 4 ||
                    variant.ProtectedCompartmentation ||
                    variant.DamageControl != Tl1IntegratedDamageControlMode.ComponentFirstReserveOne ||
                    !(variant.BaseShieldRechargeEnabled ?? true) ||
                    (variant.EvasiveManeuversEnabled ?? true) ||
                    !(variant.PdsEnabled ?? true) ||
                    (variant.EscapeDisengagementEnabled ?? true) ||
                    variant.SideABackgroundTacticalPowerCommitment != 0 ||
                    variant.SideBBackgroundTacticalPowerCommitment != 0)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 64 variant '{variant.Id}' violates the track-aware acquisition control contract.");
                }
            }
        }
    }

    private static void ValidateTl1BilateralTacticalGeometryCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        if (study.Builds.Count != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 65 requires exactly one balanced-generalist construction package so movement geometry is not confounded by odd-build composition.");
        }
        Tl1IntegratedShipBuildDocument build = study.Builds.Single();
        if (build.Id != "balanced_generalist_major" ||
            build.MainWeaponCount != 1 || build.MainReactorCount != 1 ||
            !build.ActiveSensor || !build.ShieldGenerator ||
            build.KineticPdsCount != 1 || build.UsedSpace != 33 ||
            build.FreeSupportSpace != 2)
        {
            throw new InvalidOperationException(
                "Checkpoint 65 requires the accepted 33-Space balanced-generalist package on both sides.");
        }
        int recomputedSpace = 13 + 6 * build.MainWeaponCount +
            6 * build.MainReactorCount + (build.ActiveSensor ? 3 : 0) +
            (build.ShieldGenerator ? 3 : 0) + 2 * build.KineticPdsCount;
        if (recomputedSpace != build.UsedSpace || recomputedSpace > 35)
        {
            throw new InvalidOperationException(
                "Checkpoint 65 balanced-generalist construction arithmetic drifted.");
        }

        if (!technologyProfiles.TryGetValue(
                "tl1-production", out TechnologyCombatProfile? tl1) ||
            tl1 is null || tl1.TechnologyLevel != 1 || tl1.ReactorOutput != 5)
        {
            throw new InvalidOperationException(
                "Checkpoint 65 requires the accepted TL1 production profile with 5 TP reactor output.");
        }
        if (!auxiliaryProfiles.TryGetValue(
                "aux-r53-none-tl1", out AuxiliaryCombatProfile? noAux) ||
            noAux is null || !noAux.Counterfactual || noAux.CapacityCost != 0 ||
            noAux.HasPds || noAux.HasAuxiliaryReactor || noAux.EvasiveManeuvers)
        {
            throw new InvalidOperationException(
                "Checkpoint 65 requires the zero-effect TL1 no-AUX diagnostic profile.");
        }

        WeaponFamily[] families =
        {
            WeaponFamily.Kinetic,
            WeaponFamily.Energy,
            WeaponFamily.Missile,
        };
        var regimes = new[]
        {
            (Code: "ef", Movement: Tl1IntegratedMovementMode.OpponentAwareRange,
                Track: Tl1OperationalTrackPolicy.EstablishedFirm, Ew: 0),
            (Code: "op-clear", Movement: Tl1IntegratedMovementMode.TrackAwareOpponentRange,
                Track: Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive, Ew: 0),
            (Code: "op-ew1", Movement: Tl1IntegratedMovementMode.TrackAwareOpponentRange,
                Track: Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive, Ew: 1),
        };
        Tl1IntegratedMovementOrder[] orders =
        {
            Tl1IntegratedMovementOrder.SideAFirst,
            Tl1IntegratedMovementOrder.SideBFirst,
        };

        foreach (WeaponFamily familyA in families)
        foreach (WeaponFamily familyB in families)
        foreach (var regime in regimes)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] lane = study.Variants.Where(variant =>
                variant.SideAFamily == familyA &&
                variant.SideBFamily == familyB &&
                variant.MovementMode == regime.Movement &&
                variant.SideATrackPolicy == regime.Track &&
                variant.SideBTrackPolicy == regime.Track &&
                variant.SideANetEwRangePenalty == regime.Ew &&
                variant.SideBNetEwRangePenalty == regime.Ew).ToArray();
            if (lane.Length != 2 ||
                lane.Select(variant => variant.ComparisonGroup)
                    .Distinct(StringComparer.Ordinal).Count() != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 65 requires one paired movement-order lane for {familyA}/{familyB}/{regime.Code}.");
            }
            foreach (Tl1IntegratedMovementOrder order in orders)
            {
                Tl1IntegratedTacticalCombatVariantDocument variant = lane.SingleOrDefault(candidate =>
                        candidate.MovementOrder == order)
                    ?? throw new InvalidOperationException(
                        $"Checkpoint 65 is missing {order} for {familyA}/{familyB}/{regime.Code}.");
                if (variant.SideABuildId != "balanced_generalist_major" ||
                    variant.SideBBuildId != "balanced_generalist_major" ||
                    variant.SideASecondaryFamily is not null ||
                    variant.SideBSecondaryFamily is not null ||
                    variant.SideAProfileId != "tl1-production" ||
                    variant.SideBProfileId != "tl1-production" ||
                    variant.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                    variant.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                    variant.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                    variant.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                    variant.SideAReactorOutputOverride != 5 ||
                    variant.SideBReactorOutputOverride != 5 ||
                    variant.InitialRangeHexes != 4 ||
                    variant.TacticalMapRadius != 5 ||
                    variant.StartingFuel != 200 ||
                    variant.MovementFuelPerHex != 2 ||
                    variant.EvasiveManeuverFuelCost != 1 ||
                    variant.ProtectedCompartmentation ||
                    variant.DamageControl != Tl1IntegratedDamageControlMode.ComponentFirstReserveOne ||
                    !(variant.BaseShieldRechargeEnabled ?? true) ||
                    (variant.EvasiveManeuversEnabled ?? true) ||
                    !(variant.PdsEnabled ?? true) ||
                    (variant.EscapeDisengagementEnabled ?? true) ||
                    variant.SideABackgroundTacticalPowerCommitment != 0 ||
                    variant.SideBBackgroundTacticalPowerCommitment != 0)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 65 variant '{variant.Id}' violates the finite-map bilateral control contract.");
                }
            }
        }
    }

    private static void RequireSingleRangeFourControl(
        Tl1IntegratedTacticalCombatStudyDocument study,
        WeaponFamily familyA,
        WeaponFamily familyB,
        string profileLabel,
        Func<Tl1IntegratedTacticalCombatVariantDocument, bool> predicate)
    {
        int count = study.Variants.Count(variant =>
            variant.ProfileLabel == profileLabel &&
            variant.SideAFamily == familyA &&
            variant.SideBFamily == familyB &&
            variant.MovementMode == Tl1IntegratedMovementMode.HoldRange4 &&
            (variant.PrimaryArmorProtection ?? 0) == 0 &&
            predicate(variant));
        if (count != 1)
        {
            throw new InvalidOperationException(
                $"Minimal-tactics study requires one {profileLabel} Range 4 " +
                $"control for {familyA}/{familyB}.");
        }
    }

    private static void ValidateTl1ScriptedOverloadTacticsCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        if (study.Variants.Count != RequiredTl1ScriptedOverloadTacticsVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 66 requires exactly {RequiredTl1ScriptedOverloadTacticsVariantCount} scripted-overload variants.");
        }
        var expectedPairs = new (WeaponFamily A, WeaponFamily B)[]
        {
            (WeaponFamily.Kinetic, WeaponFamily.Missile),
            (WeaponFamily.Missile, WeaponFamily.Kinetic),
            (WeaponFamily.Energy, WeaponFamily.Missile),
            (WeaponFamily.Missile, WeaponFamily.Energy),
            (WeaponFamily.Missile, WeaponFamily.Missile),
        };
        var expectedPlans = new (Tl1IntegratedStlOverloadPolicy Stl, Tl1IntegratedSensorOverloadPolicy Sensor)[]
        {
            (Tl1IntegratedStlOverloadPolicy.None, Tl1IntegratedSensorOverloadPolicy.None),
            (Tl1IntegratedStlOverloadPolicy.SafeRangePressure, Tl1IntegratedSensorOverloadPolicy.None),
            (Tl1IntegratedStlOverloadPolicy.None, Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded),
            (Tl1IntegratedStlOverloadPolicy.SafeRangePressure, Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded),
        };
        foreach ((WeaponFamily familyA, WeaponFamily familyB) in expectedPairs)
        foreach (int ew in new[] { 0, 1 })
        foreach ((Tl1IntegratedStlOverloadPolicy stl, Tl1IntegratedSensorOverloadPolicy sensor) in expectedPlans)
        foreach (Tl1IntegratedMovementOrder order in new[]
        {
            Tl1IntegratedMovementOrder.SideAFirst,
            Tl1IntegratedMovementOrder.SideBFirst,
        })
        {
            Tl1IntegratedTacticalCombatVariantDocument[] matches = study.Variants
                .Where(v => v.SideAFamily == familyA && v.SideBFamily == familyB &&
                    v.SideANetEwRangePenalty == ew && v.SideBNetEwRangePenalty == ew &&
                    v.SideAStlOverloadPolicy == stl &&
                    v.SideASensorOverloadPolicy == sensor &&
                    v.SideBStlOverloadPolicy == Tl1IntegratedStlOverloadPolicy.None &&
                    v.SideBSensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.None &&
                    v.MovementOrder == order)
                .ToArray();
            if (matches.Length != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 66 matrix mismatch for {familyA}/{familyB}/EW{ew}/{stl}/{sensor}/{order}.");
            }
            Tl1IntegratedTacticalCombatVariantDocument v = matches[0];
            if (v.MovementMode != Tl1IntegratedMovementMode.TrackAwareOpponentRange ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.TacticalMapRadius != 5 || v.InitialRangeHexes != 4 ||
                v.StartingFuel != 200 || v.MovementFuelPerHex != 2 ||
                v.EvasiveManeuverFuelCost != 1 ||
                v.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideAReactorOutputOverride != 5 || v.SideBReactorOutputOverride != 5 ||
                v.EvasiveManeuversEnabled != false || v.EscapeDisengagementEnabled != false)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 66 fixed-control mismatch in variant '{v.Id}'.");
            }
        }
        if (!technologyProfiles.TryGetValue("tl1-production", out TechnologyCombatProfile? production) ||
            production is null || production.ReactorOutput != 5 ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1"))
        {
            throw new InvalidOperationException(
                "Checkpoint 66 requires the accepted TL1 production profile and zero-effect AUX control.");
        }
    }

    private static void ValidateTl1BilateralOverloadCounterplayCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        if (study.Variants.Count != RequiredTl1BilateralOverloadCounterplayVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 67 requires exactly {RequiredTl1BilateralOverloadCounterplayVariantCount} bilateral overload/EW variants.");
        }
        if (study.Builds.Count != 2)
        {
            throw new InvalidOperationException(
                "Checkpoint 67 requires the accepted balanced generalist and the explicit 35-Space EW fixture.");
        }
        Tl1IntegratedShipBuildDocument baseBuild = study.Builds.Single(build =>
            build.Id == "balanced_generalist_major");
        Tl1IntegratedShipBuildDocument ewBuild = study.Builds.Single(build =>
            build.Id == "balanced_generalist_ew_major");
        if (baseBuild.MainWeaponCount != 1 || baseBuild.MainReactorCount != 1 ||
            !baseBuild.ActiveSensor || !baseBuild.ShieldGenerator ||
            baseBuild.KineticPdsCount != 1 || baseBuild.EcmSuite || baseBuild.EccmSuite ||
            baseBuild.UsedSpace != 33 || baseBuild.FreeSupportSpace != 2)
        {
            throw new InvalidOperationException(
                "Checkpoint 67 base construction must remain the accepted 33-Space balanced generalist.");
        }
        if (ewBuild.MainWeaponCount != 1 || ewBuild.MainReactorCount != 1 ||
            !ewBuild.ActiveSensor || !ewBuild.ShieldGenerator ||
            ewBuild.KineticPdsCount != 1 || !ewBuild.EcmSuite || !ewBuild.EccmSuite ||
            ewBuild.UsedSpace != 35 || ewBuild.FreeSupportSpace != 0)
        {
            throw new InvalidOperationException(
                "Checkpoint 67 EW fixture must use both 1-Space EW support systems and exactly fill the 35-Space cruiser envelope.");
        }
        int baseSpace = 13 + 6 * baseBuild.MainWeaponCount +
            6 * baseBuild.MainReactorCount + (baseBuild.ActiveSensor ? 3 : 0) +
            (baseBuild.ShieldGenerator ? 3 : 0) + 2 * baseBuild.KineticPdsCount +
            (baseBuild.EcmSuite ? 1 : 0) + (baseBuild.EccmSuite ? 1 : 0);
        int ewSpace = 13 + 6 * ewBuild.MainWeaponCount +
            6 * ewBuild.MainReactorCount + (ewBuild.ActiveSensor ? 3 : 0) +
            (ewBuild.ShieldGenerator ? 3 : 0) + 2 * ewBuild.KineticPdsCount +
            (ewBuild.EcmSuite ? 1 : 0) + (ewBuild.EccmSuite ? 1 : 0);
        if (baseSpace != 33 || ewSpace != 35)
        {
            throw new InvalidOperationException(
                "Checkpoint 67 construction Space arithmetic drifted.");
        }
        if (!technologyProfiles.TryGetValue("tl1-production", out TechnologyCombatProfile? production) ||
            production is null || production.TechnologyLevel != 1 || production.ReactorOutput != 5 ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1"))
        {
            throw new InvalidOperationException(
                "Checkpoint 67 requires the accepted TL1 5-TP production profile and zero-effect AUX control.");
        }

        var stlPairs = new (WeaponFamily A, WeaponFamily B)[]
        {
            (WeaponFamily.Kinetic, WeaponFamily.Missile),
            (WeaponFamily.Energy, WeaponFamily.Missile),
            (WeaponFamily.Missile, WeaponFamily.Kinetic),
        };
        var stlPlans = new (Tl1IntegratedStlOverloadPolicy A, Tl1IntegratedStlOverloadPolicy B)[]
        {
            (Tl1IntegratedStlOverloadPolicy.None, Tl1IntegratedStlOverloadPolicy.None),
            (Tl1IntegratedStlOverloadPolicy.SafeRangePressure, Tl1IntegratedStlOverloadPolicy.None),
            (Tl1IntegratedStlOverloadPolicy.None, Tl1IntegratedStlOverloadPolicy.SafeRangePressure),
            (Tl1IntegratedStlOverloadPolicy.SafeRangePressure, Tl1IntegratedStlOverloadPolicy.SafeRangePressure),
        };
        foreach ((WeaponFamily familyA, WeaponFamily familyB) in stlPairs)
        foreach (int ew in new[] { 0, 1 })
        foreach (Tl1IntegratedMovementOrder order in new[]
        {
            Tl1IntegratedMovementOrder.SideAFirst,
            Tl1IntegratedMovementOrder.SideBFirst,
        })
        foreach ((Tl1IntegratedStlOverloadPolicy stlA, Tl1IntegratedStlOverloadPolicy stlB) in stlPlans)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] matches = study.Variants.Where(v =>
                v.SideABuildId == "balanced_generalist_major" &&
                v.SideBBuildId == "balanced_generalist_major" &&
                v.SideAFamily == familyA && v.SideBFamily == familyB &&
                v.SideANetEwRangePenalty == ew && v.SideBNetEwRangePenalty == ew &&
                v.MovementOrder == order &&
                v.SideAStlOverloadPolicy == stlA && v.SideBStlOverloadPolicy == stlB &&
                v.SideASensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.None &&
                v.SideBSensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.None &&
                v.SideAEcmPolicy == Tl1IntegratedEwPowerPolicy.None &&
                v.SideBEcmPolicy == Tl1IntegratedEwPowerPolicy.None &&
                v.SideAEccmPolicy == Tl1IntegratedEwPowerPolicy.None &&
                v.SideBEccmPolicy == Tl1IntegratedEwPowerPolicy.None).ToArray();
            if (matches.Length != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 67 bilateral STL matrix mismatch for {familyA}/{familyB}/EW{ew}/{order}/{stlA}/{stlB}.");
            }
        }

        var ewPackages = new (Tl1IntegratedSensorOverloadPolicy SensorA,
            Tl1IntegratedEwPowerPolicy EcmB, Tl1IntegratedEwPowerPolicy EccmA)[]
        {
            (Tl1IntegratedSensorOverloadPolicy.None, Tl1IntegratedEwPowerPolicy.None, Tl1IntegratedEwPowerPolicy.None),
            (Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded, Tl1IntegratedEwPowerPolicy.None, Tl1IntegratedEwPowerPolicy.None),
            (Tl1IntegratedSensorOverloadPolicy.None, Tl1IntegratedEwPowerPolicy.SafeOverload, Tl1IntegratedEwPowerPolicy.None),
            (Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded, Tl1IntegratedEwPowerPolicy.SafeOverload, Tl1IntegratedEwPowerPolicy.None),
            (Tl1IntegratedSensorOverloadPolicy.None, Tl1IntegratedEwPowerPolicy.SafeOverload, Tl1IntegratedEwPowerPolicy.SafeOverload),
            (Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded, Tl1IntegratedEwPowerPolicy.SafeOverload, Tl1IntegratedEwPowerPolicy.SafeOverload),
        };
        foreach (Tl1IntegratedMovementOrder order in new[]
        {
            Tl1IntegratedMovementOrder.SideAFirst,
            Tl1IntegratedMovementOrder.SideBFirst,
        })
        foreach (var package in ewPackages)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] matches = study.Variants.Where(v =>
                v.SideABuildId == "balanced_generalist_ew_major" &&
                v.SideBBuildId == "balanced_generalist_ew_major" &&
                v.SideAFamily == WeaponFamily.Missile && v.SideBFamily == WeaponFamily.Missile &&
                v.MovementOrder == order &&
                v.SideAStlOverloadPolicy == Tl1IntegratedStlOverloadPolicy.None &&
                v.SideBStlOverloadPolicy == Tl1IntegratedStlOverloadPolicy.None &&
                v.SideASensorOverloadPolicy == package.SensorA &&
                v.SideBSensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.None &&
                v.SideAEcmPolicy == Tl1IntegratedEwPowerPolicy.None &&
                v.SideBEcmPolicy == package.EcmB &&
                v.SideAEccmPolicy == package.EccmA &&
                v.SideBEccmPolicy == Tl1IntegratedEwPowerPolicy.None &&
                v.SideANetEwRangePenalty == 0 && v.SideBNetEwRangePenalty == 0).ToArray();
            if (matches.Length != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 67 post-Movement EW package mismatch for {order}/{package.SensorA}/{package.EcmB}/{package.EccmA}.");
            }
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            if (v.MovementMode != Tl1IntegratedMovementMode.TrackAwareOpponentRange ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.TacticalMapRadius != 5 || v.InitialRangeHexes != 4 ||
                v.StartingFuel != 100 || v.MovementFuelPerHex != 2 ||
                v.EvasiveManeuverFuelCost != 1 ||
                v.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideAReactorOutputOverride != 5 || v.SideBReactorOutputOverride != 5 ||
                v.EvasiveManeuversEnabled != false || v.EscapeDisengagementEnabled != false)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 67 fixed-control mismatch in variant '{v.Id}'.");
            }
        }
    }

    private static void ValidateTl1SensorEwCandidateCombatCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (study.Variants.Count != RequiredTl1SensorEwCandidateCombatVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 69 requires exactly {RequiredTl1SensorEwCandidateCombatVariantCount} Sensor/EW candidate combat variants.");
        }
        if (study.Builds.Count != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 69 requires exactly one fixed 35-Space EW-capable combat fixture.");
        }

        Tl1IntegratedShipBuildDocument build = study.Builds.Single();
        if (build.Id != "balanced_generalist_ew_major" ||
            build.MainWeaponCount != 1 || build.MainReactorCount != 1 ||
            !build.ActiveSensor || !build.ShieldGenerator ||
            build.KineticPdsCount != 1 || !build.EcmSuite || !build.EccmSuite ||
            build.UsedSpace != 35 || build.FreeSupportSpace != 0)
        {
            throw new InvalidOperationException(
                "Checkpoint 69 must hold the accepted 35-Space EW-capable fixture constant across the candidate study.");
        }
        int usedSpace = 13 + 6 * build.MainWeaponCount +
            6 * build.MainReactorCount + (build.ActiveSensor ? 3 : 0) +
            (build.ShieldGenerator ? 3 : 0) + 2 * build.KineticPdsCount +
            (build.EcmSuite ? 1 : 0) + (build.EccmSuite ? 1 : 0);
        if (usedSpace != 35)
        {
            throw new InvalidOperationException(
                "Checkpoint 69 construction Space arithmetic drifted.");
        }
        if (!technologyProfiles.TryGetValue("tl1-production", out TechnologyCombatProfile? production) ||
            production is null || production.TechnologyLevel != 1 || production.ReactorOutput != 5 ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1"))
        {
            throw new InvalidOperationException(
                "Checkpoint 69 requires the accepted TL1 5-TP production profile and zero-effect AUX control.");
        }

        var expectedProfiles = new Dictionary<string, (int PF, int PA, int AF, int AA, int OB)>(StringComparer.Ordinal)
        {
            ["balanced-0"] = (1, 3, 3, 4, 1),
            ["balanced-1"] = (1, 2, 3, 4, 1),
            ["balanced-2"] = (1, 2, 3, 4, 2),
        };
        foreach (KeyValuePair<string, (int PF, int PA, int AF, int AA, int OB)> entry in expectedProfiles)
        {
            string id = entry.Key;
            (int PF, int PA, int AF, int AA, int OB) expected = entry.Value;
            if (!sensorEwProfiles.TryGetValue(id, out SensorEwFoundationProfile? profile) ||
                profile.PassiveFirmRange != expected.PF ||
                profile.PassiveApproximateRange != expected.PA ||
                profile.ActiveFirmRange != expected.AF ||
                profile.ActiveApproximateRange != expected.AA ||
                profile.ActivePowerCost != 1 ||
                profile.ActiveOverloadAdditionalPowerCost != 1 ||
                profile.ActiveOverloadFirmBonus != expected.OB ||
                profile.ActiveOverloadApproximateBonus != expected.OB)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 69 Sensor/EW candidate '{id}' does not match the approved range/power definition.");
            }
        }

        var pairings = new (WeaponFamily A, WeaponFamily B, string Code)[]
        {
            (WeaponFamily.Kinetic, WeaponFamily.Missile, "kvm"),
            (WeaponFamily.Energy, WeaponFamily.Missile, "evm"),
            (WeaponFamily.Kinetic, WeaponFamily.Energy, "kve"),
        };
        var orders = new[]
        {
            Tl1IntegratedMovementOrder.SideAFirst,
            Tl1IntegratedMovementOrder.SideBFirst,
        };
        string[] packages =
        {
            "clear-normal",
            "clear-overload",
            "jammed-no-counter",
            "jammed-eccm",
        };

        foreach (string profileId in expectedProfiles.Keys)
        foreach ((WeaponFamily familyA, WeaponFamily familyB, string _) in pairings)
        foreach (Tl1IntegratedMovementOrder order in orders)
        foreach (string package in packages)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] matches = study.Variants.Where(v =>
                v.SensorEwProfileId == profileId &&
                v.SideAFamily == familyA && v.SideBFamily == familyB &&
                v.MovementOrder == order &&
                Tl1SensorEwCandidatePackage(v) == package).ToArray();
            if (matches.Length != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 69 candidate matrix mismatch for {profileId}/{familyA}/{familyB}/{order}/{package}.");
            }
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            if (string.IsNullOrWhiteSpace(v.SensorEwProfileId) ||
                !expectedProfiles.ContainsKey(v.SensorEwProfileId) ||
                v.SideABuildId != "balanced_generalist_ew_major" ||
                v.SideBBuildId != "balanced_generalist_ew_major" ||
                v.SideAProfileId != "tl1-production" || v.SideBProfileId != "tl1-production" ||
                v.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.MovementMode != Tl1IntegratedMovementMode.TrackAwareOpponentRange ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.TacticalMapRadius != 5 || v.InitialRangeHexes != 4 ||
                v.StartingFuel != 100 || v.MovementFuelPerHex != 2 ||
                v.EvasiveManeuverFuelCost != 1 ||
                v.ProtectedCompartmentation || !(v.BaseShieldRechargeEnabled ?? true) ||
                v.EvasiveManeuversEnabled != false || v.PdsEnabled != true ||
                v.EscapeDisengagementEnabled != false ||
                v.SideABackgroundTacticalPowerCommitment != 0 ||
                v.SideBBackgroundTacticalPowerCommitment != 0 ||
                v.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideAReactorOutputOverride != 5 || v.SideBReactorOutputOverride != 5 ||
                v.SideANetEwRangePenalty != 0 || v.SideBNetEwRangePenalty != 0 ||
                v.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 69 fixed-control mismatch in variant '{v.Id}'.");
            }
        }
    }

    private static void ValidateTl1EcmPowerCostCounterplayCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (study.Variants.Count != RequiredTl1EcmPowerCostCounterplayVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 70 requires exactly {RequiredTl1EcmPowerCostCounterplayVariantCount} ECM power-cost counterplay variants.");
        }
        if (study.Builds.Count != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 70 requires exactly one fixed 35-Space EW-capable combat fixture.");
        }

        Tl1IntegratedShipBuildDocument build = study.Builds.Single();
        if (build.Id != "balanced_generalist_ew_major" ||
            build.MainWeaponCount != 1 || build.MainReactorCount != 1 ||
            !build.ActiveSensor || !build.ShieldGenerator ||
            build.KineticPdsCount != 1 || !build.EcmSuite || !build.EccmSuite ||
            build.UsedSpace != 35 || build.FreeSupportSpace != 0)
        {
            throw new InvalidOperationException(
                "Checkpoint 70 must hold the accepted 35-Space EW-capable fixture constant.");
        }
        if (!technologyProfiles.TryGetValue("tl1-production", out TechnologyCombatProfile? production) ||
            production is null || production.TechnologyLevel != 1 || production.ReactorOutput != 5 ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1"))
        {
            throw new InvalidOperationException(
                "Checkpoint 70 requires the accepted TL1 5-TP production profile and zero-effect AUX control.");
        }
        if (!sensorEwProfiles.TryGetValue("balanced-0", out SensorEwFoundationProfile? profile) ||
            profile.PassiveFirmRange != 1 || profile.PassiveApproximateRange != 3 ||
            profile.ActiveFirmRange != 3 || profile.ActiveApproximateRange != 4 ||
            profile.ActivePowerCost != 1 || profile.ActiveOverloadAdditionalPowerCost != 1 ||
            profile.ActiveOverloadFirmBonus != 1 || profile.ActiveOverloadApproximateBonus != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 70 requires Balanced-0 (Passive 1/3, Active 3/4, Overload 4/5) as the fixed Sensor/EW envelope.");
        }

        var operationalContexts = new (WeaponFamily A, WeaponFamily B, string Code, Tl1IntegratedMovementOrder Order)[]
        {
            (WeaponFamily.Kinetic, WeaponFamily.Missile, "kvm", Tl1IntegratedMovementOrder.SideAFirst),
            (WeaponFamily.Kinetic, WeaponFamily.Missile, "kvm", Tl1IntegratedMovementOrder.SideBFirst),
            (WeaponFamily.Energy, WeaponFamily.Missile, "evm", Tl1IntegratedMovementOrder.SideAFirst),
            (WeaponFamily.Energy, WeaponFamily.Missile, "evm", Tl1IntegratedMovementOrder.SideBFirst),
            (WeaponFamily.Kinetic, WeaponFamily.Energy, "kve", Tl1IntegratedMovementOrder.SideAFirst),
            (WeaponFamily.Kinetic, WeaponFamily.Energy, "kve", Tl1IntegratedMovementOrder.SideBFirst),
        };
        var pointBlankContexts = new (WeaponFamily A, WeaponFamily B, string Code)[]
        {
            (WeaponFamily.Kinetic, WeaponFamily.Missile, "kvm"),
            (WeaponFamily.Kinetic, WeaponFamily.Energy, "kve"),
            (WeaponFamily.Energy, WeaponFamily.Kinetic, "evk"),
        };

        foreach (var contextDefinition in operationalContexts)
        {
            WeaponFamily familyA = contextDefinition.A;
            WeaponFamily familyB = contextDefinition.B;
            Tl1IntegratedMovementOrder order = contextDefinition.Order;
            Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants.Where(v =>
                Tl1EcmPowerSweepGeometry(v) == "operational" &&
                v.SideAFamily == familyA && v.SideBFamily == familyB &&
                v.MovementOrder == order).ToArray();
            ValidateTl1EcmPowerSweepContext(context, $"operational/{familyA}/{familyB}/{order}");
        }
        foreach (var contextDefinition in pointBlankContexts)
        {
            WeaponFamily familyA = contextDefinition.A;
            WeaponFamily familyB = contextDefinition.B;
            Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants.Where(v =>
                Tl1EcmPowerSweepGeometry(v) == "point-blank" &&
                v.SideAFamily == familyA && v.SideBFamily == familyB).ToArray();
            ValidateTl1EcmPowerSweepContext(context, $"point-blank/{familyA}/{familyB}");
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            bool pointBlank = Tl1EcmPowerSweepGeometry(v) == "point-blank";
            if (v.SensorEwProfileId != "balanced-0" ||
                v.SideABuildId != "balanced_generalist_ew_major" ||
                v.SideBBuildId != "balanced_generalist_ew_major" ||
                v.SideAProfileId != "tl1-production" || v.SideBProfileId != "tl1-production" ||
                v.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.TacticalMapRadius != 5 || v.StartingFuel != 100 ||
                v.MovementFuelPerHex != 2 || v.EvasiveManeuverFuelCost != 1 ||
                v.ProtectedCompartmentation || !(v.BaseShieldRechargeEnabled ?? true) ||
                v.EvasiveManeuversEnabled != false || v.PdsEnabled != true ||
                v.EscapeDisengagementEnabled != false ||
                v.SideABackgroundTacticalPowerCommitment != 0 ||
                v.SideBBackgroundTacticalPowerCommitment != 0 ||
                v.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideAReactorOutputOverride != 5 || v.SideBReactorOutputOverride != 5 ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideANetEwRangePenalty != 0 || v.SideBNetEwRangePenalty != 0 ||
                v.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                v.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                v.SideAEcmNormalPowerCostOverride is not null ||
                v.SideBEccmNormalPowerCostOverride is not null)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 70 fixed-control mismatch in variant '{v.Id}'.");
            }

            if (pointBlank)
            {
                if (v.MovementMode != Tl1IntegratedMovementMode.HoldRange2 ||
                    v.InitialRangeHexes != 0 || v.SideAStlMovementHexes != 0 ||
                    v.SideBStlMovementHexes != 0 ||
                    v.MovementOrder != Tl1IntegratedMovementOrder.Simultaneous)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 70 point-blank geometry drifted in variant '{v.Id}'.");
                }
            }
            else if (v.MovementMode != Tl1IntegratedMovementMode.TrackAwareOpponentRange ||
                v.InitialRangeHexes != 4 || v.SideAStlMovementHexes != 1 ||
                v.SideBStlMovementHexes != 1 ||
                v.MovementOrder == Tl1IntegratedMovementOrder.Simultaneous)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 70 operational geometry drifted in variant '{v.Id}'.");
            }
        }
    }

    private static void ValidateTl1SensorDiscriminationBurnthroughCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (study.Variants.Count != RequiredTl1SensorDiscriminationBurnthroughVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 71 requires exactly {RequiredTl1SensorDiscriminationBurnthroughVariantCount} Sensor discrimination/burn-through variants.");
        }
        if (study.Builds.Count != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 71 requires exactly one fixed 35-Space EW-capable combat fixture.");
        }

        Tl1IntegratedShipBuildDocument build = study.Builds.Single();
        if (build.Id != "balanced_generalist_ew_major" ||
            build.MainWeaponCount != 1 || build.MainReactorCount != 1 ||
            !build.ActiveSensor || !build.ShieldGenerator ||
            build.KineticPdsCount != 1 || !build.EcmSuite || !build.EccmSuite ||
            build.UsedSpace != 35 || build.FreeSupportSpace != 0)
        {
            throw new InvalidOperationException(
                "Checkpoint 71 must hold the accepted 35-Space EW-capable fixture constant.");
        }
        if (!technologyProfiles.TryGetValue("tl1-production", out TechnologyCombatProfile? production) ||
            production is null || production.TechnologyLevel != 1 || production.ReactorOutput != 5 ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1"))
        {
            throw new InvalidOperationException(
                "Checkpoint 71 requires the accepted TL1 5-TP production profile and zero-effect AUX control.");
        }
        if (!sensorEwProfiles.TryGetValue("balanced-0", out SensorEwFoundationProfile? profile) ||
            profile.PassiveFirmRange != 1 || profile.PassiveApproximateRange != 3 ||
            profile.ActiveFirmRange != 3 || profile.ActiveApproximateRange != 4 ||
            profile.ActivePowerCost != 1 || profile.ActiveOverloadAdditionalPowerCost != 1 ||
            profile.ActiveOverloadFirmBonus != 1 || profile.ActiveOverloadApproximateBonus != 1 ||
            profile.DiscriminationResistance != 0 ||
            profile.PointBlankBurnThroughResistance != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 71 requires Balanced-0 with Discrimination Resistance 0 and same-hex Burn-through +1.");
        }

        var operationalContexts = new (WeaponFamily A, WeaponFamily B, Tl1IntegratedMovementOrder Order)[]
        {
            (WeaponFamily.Kinetic, WeaponFamily.Missile, Tl1IntegratedMovementOrder.SideAFirst),
            (WeaponFamily.Kinetic, WeaponFamily.Missile, Tl1IntegratedMovementOrder.SideBFirst),
            (WeaponFamily.Energy, WeaponFamily.Missile, Tl1IntegratedMovementOrder.SideAFirst),
            (WeaponFamily.Energy, WeaponFamily.Missile, Tl1IntegratedMovementOrder.SideBFirst),
            (WeaponFamily.Kinetic, WeaponFamily.Energy, Tl1IntegratedMovementOrder.SideAFirst),
            (WeaponFamily.Kinetic, WeaponFamily.Energy, Tl1IntegratedMovementOrder.SideBFirst),
        };
        var pointBlankContexts = new (WeaponFamily A, WeaponFamily B)[]
        {
            (WeaponFamily.Kinetic, WeaponFamily.Missile),
            (WeaponFamily.Kinetic, WeaponFamily.Energy),
            (WeaponFamily.Energy, WeaponFamily.Kinetic),
        };

        foreach (var definition in operationalContexts)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants.Where(v =>
                Tl1EcmPowerSweepGeometry(v) == "operational" &&
                v.SideAFamily == definition.A && v.SideBFamily == definition.B &&
                v.MovementOrder == definition.Order).ToArray();
            ValidateTl1BurnthroughContext(context,
                $"operational/{definition.A}/{definition.B}/{definition.Order}");
        }
        foreach (var definition in pointBlankContexts)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants.Where(v =>
                Tl1EcmPowerSweepGeometry(v) == "point-blank" &&
                v.SideAFamily == definition.A && v.SideBFamily == definition.B).ToArray();
            ValidateTl1BurnthroughContext(context,
                $"point-blank/{definition.A}/{definition.B}");
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            bool pointBlank = Tl1EcmPowerSweepGeometry(v) == "point-blank";
            string package = Tl1EcmPowerSweepPackage(v);
            if (v.SensorEwProfileId != "balanced-0" ||
                v.SideABuildId != "balanced_generalist_ew_major" ||
                v.SideBBuildId != "balanced_generalist_ew_major" ||
                v.SideAProfileId != "tl1-production" || v.SideBProfileId != "tl1-production" ||
                v.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.TacticalMapRadius != 5 || v.StartingFuel != 100 ||
                v.MovementFuelPerHex != 2 || v.EvasiveManeuverFuelCost != 1 ||
                v.ProtectedCompartmentation || !(v.BaseShieldRechargeEnabled ?? true) ||
                v.EvasiveManeuversEnabled != false || v.PdsEnabled != true ||
                v.EscapeDisengagementEnabled != false ||
                v.SideABackgroundTacticalPowerCommitment != 0 ||
                v.SideBBackgroundTacticalPowerCommitment != 0 ||
                v.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideAReactorOutputOverride != 5 || v.SideBReactorOutputOverride != 5 ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideANetEwRangePenalty != 0 || v.SideBNetEwRangePenalty != 0 ||
                v.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                v.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                v.SideAEcmNormalPowerCostOverride is not null ||
                v.SideBEccmNormalPowerCostOverride is not null ||
                (package != "clear" && package != "jam-p1" &&
                    package != "counter-p1"))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 71 fixed-control mismatch in variant '{v.Id}'.");
            }

            if (pointBlank)
            {
                if (v.MovementMode != Tl1IntegratedMovementMode.HoldRange2 ||
                    v.InitialRangeHexes != 0 || v.SideAStlMovementHexes != 0 ||
                    v.SideBStlMovementHexes != 0 ||
                    v.MovementOrder != Tl1IntegratedMovementOrder.Simultaneous)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 71 point-blank geometry drifted in variant '{v.Id}'.");
                }
            }
            else if (v.MovementMode != Tl1IntegratedMovementMode.TrackAwareOpponentRange ||
                v.InitialRangeHexes != 4 || v.SideAStlMovementHexes != 1 ||
                v.SideBStlMovementHexes != 1 ||
                v.MovementOrder == Tl1IntegratedMovementOrder.Simultaneous)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 71 operational geometry drifted in variant '{v.Id}'.");
            }
        }
    }

    private static void ValidateTl1ReactiveEwSubphaseCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (study.Variants.Count != RequiredTl1ReactiveEwSubphaseVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 72 requires exactly {RequiredTl1ReactiveEwSubphaseVariantCount} reactive EW sub-phase variants.");
        }
        if (study.Builds.Count != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 72 requires exactly one fixed 35-Space EW-capable combat fixture.");
        }

        Tl1IntegratedShipBuildDocument build = study.Builds.Single();
        if (build.Id != "balanced_generalist_ew_major" ||
            build.MainWeaponCount != 1 || build.MainReactorCount != 1 ||
            !build.ActiveSensor || !build.ShieldGenerator ||
            build.KineticPdsCount != 1 || !build.EcmSuite || !build.EccmSuite ||
            build.UsedSpace != 35 || build.FreeSupportSpace != 0)
        {
            throw new InvalidOperationException(
                "Checkpoint 72 must hold the accepted 35-Space EW-capable fixture constant.");
        }
        if (!technologyProfiles.TryGetValue("tl1-production", out TechnologyCombatProfile? production) ||
            production is null || production.TechnologyLevel != 1 || production.ReactorOutput != 5 ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1"))
        {
            throw new InvalidOperationException(
                "Checkpoint 72 requires the accepted TL1 5-TP production profile and zero-effect AUX control.");
        }
        if (!sensorEwProfiles.TryGetValue("balanced-0", out SensorEwFoundationProfile? profile) ||
            profile.PassiveFirmRange != 1 || profile.PassiveApproximateRange != 3 ||
            profile.ActiveFirmRange != 3 || profile.ActiveApproximateRange != 4 ||
            profile.ActivePowerCost != 1 || profile.ActiveOverloadAdditionalPowerCost != 1 ||
            profile.ActiveOverloadFirmBonus != 1 || profile.ActiveOverloadApproximateBonus != 1 ||
            profile.DiscriminationResistance != 0 ||
            profile.PointBlankBurnThroughResistance != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 72 requires the accepted CP71 Balanced-0 EW foundation unchanged.");
        }

        if (study.Variants.Count(v => Tl1ReactiveEwGeometry(v) == "operational") != 30 ||
            study.Variants.Count(v => Tl1ReactiveEwGeometry(v) == "point-blank") != 9)
        {
            throw new InvalidOperationException(
                "Checkpoint 72 requires 30 operational and 9 fixed point-blank variants.");
        }
        var expectedPackages = new Dictionary<string, int>(StringComparer.Ordinal)
        {
            ["clear"] = 9,
            ["unilateral-auto"] = 9,
            ["unilateral-reactive"] = 9,
            ["bilateral-auto"] = 6,
            ["bilateral-reactive"] = 6,
        };
        foreach ((string package, int expected) in expectedPackages)
        {
            int actual = study.Variants.Count(v => Tl1ReactiveEwPackage(v) == package);
            if (actual != expected)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 72 package '{package}' requires {expected} variants; found {actual}.");
            }
        }

        var operationalContexts = new (WeaponFamily A, WeaponFamily B, Tl1IntegratedMovementOrder Order)[]
        {
            (WeaponFamily.Kinetic, WeaponFamily.Missile, Tl1IntegratedMovementOrder.SideAFirst),
            (WeaponFamily.Kinetic, WeaponFamily.Missile, Tl1IntegratedMovementOrder.SideBFirst),
            (WeaponFamily.Energy, WeaponFamily.Missile, Tl1IntegratedMovementOrder.SideAFirst),
            (WeaponFamily.Energy, WeaponFamily.Missile, Tl1IntegratedMovementOrder.SideBFirst),
            (WeaponFamily.Kinetic, WeaponFamily.Energy, Tl1IntegratedMovementOrder.SideAFirst),
            (WeaponFamily.Kinetic, WeaponFamily.Energy, Tl1IntegratedMovementOrder.SideBFirst),
        };
        foreach (var definition in operationalContexts)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] unilateral = study.Variants.Where(v =>
                Tl1ReactiveEwGeometry(v) == "operational" &&
                v.SideAFamily == definition.A && v.SideBFamily == definition.B &&
                v.MovementOrder == definition.Order &&
                Tl1ReactiveEwPackage(v) is "clear" or "unilateral-auto" or "unilateral-reactive")
                .ToArray();
            if (unilateral.Length != 3 ||
                unilateral.Count(v => Tl1ReactiveEwPackage(v) == "clear") != 1 ||
                unilateral.Count(v => Tl1ReactiveEwPackage(v) == "unilateral-auto") != 1 ||
                unilateral.Count(v => Tl1ReactiveEwPackage(v) == "unilateral-reactive") != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 72 operational unilateral context {definition.A}/{definition.B}/{definition.Order} is incomplete.");
            }

            Tl1IntegratedTacticalCombatVariantDocument[] bilateral = study.Variants.Where(v =>
                Tl1ReactiveEwGeometry(v) == "operational" &&
                v.SideAFamily == definition.A && v.SideBFamily == definition.B &&
                v.MovementOrder == definition.Order &&
                Tl1ReactiveEwPackage(v) is "bilateral-auto" or "bilateral-reactive")
                .ToArray();
            if (bilateral.Length != 2 ||
                bilateral.Count(v => Tl1ReactiveEwPackage(v) == "bilateral-auto") != 1 ||
                bilateral.Count(v => Tl1ReactiveEwPackage(v) == "bilateral-reactive") != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 72 operational bilateral context {definition.A}/{definition.B}/{definition.Order} is incomplete.");
            }
        }

        var pointBlankContexts = new (WeaponFamily A, WeaponFamily B)[]
        {
            (WeaponFamily.Kinetic, WeaponFamily.Missile),
            (WeaponFamily.Kinetic, WeaponFamily.Energy),
            (WeaponFamily.Energy, WeaponFamily.Kinetic),
        };
        foreach (var definition in pointBlankContexts)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants.Where(v =>
                Tl1ReactiveEwGeometry(v) == "point-blank" &&
                v.SideAFamily == definition.A && v.SideBFamily == definition.B).ToArray();
            if (context.Length != 3 ||
                context.Count(v => Tl1ReactiveEwPackage(v) == "clear") != 1 ||
                context.Count(v => Tl1ReactiveEwPackage(v) == "unilateral-auto") != 1 ||
                context.Count(v => Tl1ReactiveEwPackage(v) == "unilateral-reactive") != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 72 point-blank context {definition.A}/{definition.B} is incomplete.");
            }
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            string package = Tl1ReactiveEwPackage(v);
            bool pointBlank = Tl1ReactiveEwGeometry(v) == "point-blank";
            if (package == "invalid" ||
                v.SensorEwProfileId != "balanced-0" ||
                v.SideABuildId != "balanced_generalist_ew_major" ||
                v.SideBBuildId != "balanced_generalist_ew_major" ||
                v.SideAProfileId != "tl1-production" || v.SideBProfileId != "tl1-production" ||
                v.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.TacticalMapRadius != 5 || v.StartingFuel != 100 ||
                v.MovementFuelPerHex != 2 || v.EvasiveManeuverFuelCost != 1 ||
                v.ProtectedCompartmentation || !(v.BaseShieldRechargeEnabled ?? true) ||
                v.EvasiveManeuversEnabled != false || v.PdsEnabled != true ||
                v.EscapeDisengagementEnabled != false ||
                v.SideABackgroundTacticalPowerCommitment != 0 ||
                v.SideBBackgroundTacticalPowerCommitment != 0 ||
                v.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideAReactorOutputOverride != 5 || v.SideBReactorOutputOverride != 5 ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideANetEwRangePenalty != 0 || v.SideBNetEwRangePenalty != 0 ||
                v.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 72 fixed-control mismatch in variant '{v.Id}'.");
            }

            if (pointBlank)
            {
                if (v.MovementMode != Tl1IntegratedMovementMode.HoldRange2 ||
                    v.InitialRangeHexes != 0 || v.SideAStlMovementHexes != 0 ||
                    v.SideBStlMovementHexes != 0 ||
                    v.MovementOrder != Tl1IntegratedMovementOrder.Simultaneous)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 72 point-blank geometry drifted in variant '{v.Id}'.");
                }
            }
            else if (v.MovementMode != Tl1IntegratedMovementMode.TrackAwareOpponentRange ||
                v.InitialRangeHexes != 4 || v.SideAStlMovementHexes != 1 ||
                v.SideBStlMovementHexes != 1 ||
                v.MovementOrder == Tl1IntegratedMovementOrder.Simultaneous)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 72 operational geometry drifted in variant '{v.Id}'.");
            }
        }
    }

    private static void ValidateApproximateDirectFireControl(
        string variantId,
        string side,
        bool enabled,
        int penalty)
    {
        if (penalty is < 0 or > 100 ||
            (enabled && penalty == 0) ||
            (!enabled && penalty != 0))
        {
            throw new InvalidOperationException(
                $"Variant '{variantId}' has an invalid Side {side} Approximate-track direct-fire trait/penalty pairing.");
        }
    }

    private static void ValidateTl1ApproximateTrackDegradedFireCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (study.Variants.Count != RequiredTl1ApproximateTrackDegradedFireVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 74 requires exactly {RequiredTl1ApproximateTrackDegradedFireVariantCount} degraded-fire variants.");
        }
        string[] pairings = { "Kinetic|Energy", "Energy|Kinetic" };
        int[] ranges = { 2, 3 };
        string[] modes = { "firm-reference", "approx-firm-only", "approx-p10", "approx-p20", "approx-p30" };
        foreach (string pairing in pairings)
        {
            string[] parts = pairing.Split('|');
            foreach (int range in ranges)
            {
                string group = $"c74-{parts[0].ToLowerInvariant()[0]}v{parts[1].ToLowerInvariant()[0]}-r{range}";
                Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants
                    .Where(v => string.Equals(v.ComparisonGroup, group, StringComparison.Ordinal))
                    .ToArray();
                if (context.Length != modes.Length)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 74 context '{group}' must contain exactly five control/penalty variants.");
                }
                foreach (string mode in modes)
                {
                    if (context.Count(v => string.Equals(v.ProfileLabel, mode, StringComparison.Ordinal)) != 1)
                    {
                        throw new InvalidOperationException(
                            $"Checkpoint 74 context '{group}' is missing unique mode '{mode}'.");
                    }
                }
            }
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument variant in study.Variants)
        {
            if (variant.SideAFamily is WeaponFamily.Missile ||
                variant.SideBFamily is WeaponFamily.Missile ||
                variant.SideASecondaryFamily is not null ||
                variant.SideBSecondaryFamily is not null)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 74 variant '{variant.Id}' must isolate single-bay Kinetic/Energy direct fire; missiles remain outside degraded-fire rules.");
            }
            if (variant.SensorEwProfileId != "balanced-0" ||
                variant.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                variant.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                variant.SideANetEwRangePenalty != 0 || variant.SideBNetEwRangePenalty != 0 ||
                variant.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                variant.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 74 variant '{variant.Id}' drifted from the controlled Balanced-0/no-overload Sensor/EW fixture.");
            }
            bool firmReference = variant.ProfileLabel == "firm-reference";
            bool firmOnlyApprox = variant.ProfileLabel == "approx-firm-only";
            if (firmReference)
            {
                if (variant.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideAAllowsApproximateDirectFire || variant.SideBAllowsApproximateDirectFire)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 74 firm reference '{variant.Id}' must be unjammed and Firm-only.");
                }
            }
            else
            {
                if (variant.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.Normal ||
                    variant.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.Normal ||
                    variant.SideAEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.None)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 74 Approximate-track variant '{variant.Id}' must use bilateral normal ECM with no ECCM response.");
                }
                if (firmOnlyApprox &&
                    (variant.SideAAllowsApproximateDirectFire || variant.SideBAllowsApproximateDirectFire))
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 74 Firm-only Approximate control '{variant.Id}' must leave the degraded-fire trait disabled.");
                }
            }
        }

        _ = technologyProfiles;
        _ = auxiliaryProfiles;
        _ = sensorEwProfiles;
    }

    private static void ValidateTl1AppliedDegradedFireFamilyCandidateCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (study.Variants.Count != RequiredTl1AppliedDegradedFireFamilyCandidateVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 75 requires exactly {RequiredTl1AppliedDegradedFireFamilyCandidateVariantCount} applied degraded-fire variants.");
        }

        string[] pairings = { "Kinetic|Energy", "Energy|Kinetic" };
        int[] ranges = { 2, 3 };
        string[] modes =
        {
            "firm-reference",
            "approx-firm-only",
            "kinetic-p20",
            "kinetic-p25",
            "energy-p20",
            "energy-p25",
            "both-p20",
            "both-p25",
            "kinetic-p20-energy-p25",
            "kinetic-p25-energy-p20",
        };
        foreach (string pairing in pairings)
        {
            string[] parts = pairing.Split('|');
            foreach (int range in ranges)
            {
                string group = $"c75-{parts[0].ToLowerInvariant()[0]}v{parts[1].ToLowerInvariant()[0]}-r{range}";
                Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants
                    .Where(v => string.Equals(v.ComparisonGroup, group, StringComparison.Ordinal))
                    .ToArray();
                if (context.Length != modes.Length)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 75 context '{group}' must contain exactly ten control/family-package variants.");
                }
                WeaponFamily expectedA = Enum.Parse<WeaponFamily>(parts[0]);
                WeaponFamily expectedB = Enum.Parse<WeaponFamily>(parts[1]);
                Tl1IntegratedMovementMode expectedMovementMode = range == 2
                    ? Tl1IntegratedMovementMode.HoldRange2
                    : Tl1IntegratedMovementMode.HoldRange3;
                if (context.Any(v =>
                        v.SideAFamily != expectedA ||
                        v.SideBFamily != expectedB ||
                        v.InitialRangeHexes != range ||
                        v.MovementMode != expectedMovementMode))
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 75 context '{group}' has a weapon-family, initial-range, or fixed-range movement-mode mismatch.");
                }
                foreach (string mode in modes)
                {
                    if (context.Count(v => string.Equals(v.ProfileLabel, mode, StringComparison.Ordinal)) != 1)
                    {
                        throw new InvalidOperationException(
                            $"Checkpoint 75 context '{group}' is missing unique mode '{mode}'.");
                    }
                }
            }
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument variant in study.Variants)
        {
            if (variant.SideAFamily is WeaponFamily.Missile ||
                variant.SideBFamily is WeaponFamily.Missile ||
                variant.SideASecondaryFamily is not null ||
                variant.SideBSecondaryFamily is not null)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 75 variant '{variant.Id}' must isolate single-bay Kinetic/Energy direct fire; missiles remain outside degraded-fire rules.");
            }
            if (variant.SensorEwProfileId != "balanced-0" ||
                variant.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                variant.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                variant.SideANetEwRangePenalty != 0 || variant.SideBNetEwRangePenalty != 0 ||
                variant.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                variant.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 75 variant '{variant.Id}' drifted from the controlled Balanced-0/no-overload Sensor/EW fixture.");
            }

            bool firmReference = variant.ProfileLabel == "firm-reference";
            bool firmOnlyApprox = variant.ProfileLabel == "approx-firm-only";
            if (firmReference)
            {
                if (variant.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideAEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideAAllowsApproximateDirectFire || variant.SideBAllowsApproximateDirectFire)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 75 firm reference '{variant.Id}' must be unjammed and Firm-only.");
                }
            }
            else
            {
                if (variant.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.Normal ||
                    variant.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.Normal ||
                    variant.SideAEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.None)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 75 Approximate-track variant '{variant.Id}' must use bilateral normal ECM with no ECCM response.");
                }
                if (firmOnlyApprox &&
                    (variant.SideAAllowsApproximateDirectFire || variant.SideBAllowsApproximateDirectFire))
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 75 Firm-only Approximate control '{variant.Id}' must leave degraded fire disabled.");
                }
            }

            if (!firmReference && !firmOnlyApprox)
            {
                ValidateCheckpoint75FamilyPenalty(variant, WeaponFamily.Kinetic, "kinetic-p20", 20);
                ValidateCheckpoint75FamilyPenalty(variant, WeaponFamily.Kinetic, "kinetic-p25", 25);
                ValidateCheckpoint75FamilyPenalty(variant, WeaponFamily.Energy, "energy-p20", 20);
                ValidateCheckpoint75FamilyPenalty(variant, WeaponFamily.Energy, "energy-p25", 25);
            }
        }

        _ = technologyProfiles;
        _ = auxiliaryProfiles;
        _ = sensorEwProfiles;
    }

    private static void ValidateCheckpoint75FamilyPenalty(
        Tl1IntegratedTacticalCombatVariantDocument variant,
        WeaponFamily family,
        string singleFamilyLabel,
        int penalty)
    {
        int ExpectedPenalty(WeaponFamily sideFamily)
        {
            string label = variant.ProfileLabel ?? string.Empty;
            if (label == singleFamilyLabel)
            {
                return sideFamily == family ? penalty : 0;
            }
            if (label == $"both-p{penalty}")
            {
                return penalty;
            }
            if (label == "kinetic-p20-energy-p25")
            {
                return sideFamily == WeaponFamily.Kinetic ? 20 : 25;
            }
            if (label == "kinetic-p25-energy-p20")
            {
                return sideFamily == WeaponFamily.Kinetic ? 25 : 20;
            }
            return -1;
        }

        int expectedA = ExpectedPenalty(variant.SideAFamily);
        int expectedB = ExpectedPenalty(variant.SideBFamily);
        if (expectedA < 0 && expectedB < 0)
        {
            return;
        }
        if (variant.SideAApproximateDirectFireAccuracyPenalty != expectedA ||
            variant.SideBApproximateDirectFireAccuracyPenalty != expectedB ||
            variant.SideAAllowsApproximateDirectFire != (expectedA > 0) ||
            variant.SideBAllowsApproximateDirectFire != (expectedB > 0))
        {
            throw new InvalidOperationException(
                $"Checkpoint 75 variant '{variant.Id}' does not match its weapon-family degraded-fire package definition.");
        }
    }

    private static void ValidateTl1DegradedFireEccmValueCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles,
        LoadedTl1AiDoctrineRegistry? aiDoctrineRegistry)
    {
        if (study.Variants.Count != RequiredTl1DegradedFireEccmValueVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 76 requires exactly {RequiredTl1DegradedFireEccmValueVariantCount} degraded-fire/ECCM counterplay variants.");
        }

        string[] groups =
        {
            "c76-kvm-r3",
            "c76-evm-r3",
            "c76-kvm-afirst",
            "c76-kvm-bfirst",
            "c76-evm-afirst",
            "c76-evm-bfirst",
        };
        string[] modes =
        {
            "firm-reference",
            "jammed-firm-only-no-eccm",
            "jammed-firm-only-reactive-eccm",
            "p20-no-eccm",
            "p20-reactive-eccm",
            "p20-aggressive-eccm",
            "p25-no-eccm",
            "p25-reactive-eccm",
            "p25-aggressive-eccm",
        };
        foreach (string group in groups)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants
                .Where(v => string.Equals(v.ComparisonGroup, group, StringComparison.Ordinal))
                .ToArray();
            if (context.Length != modes.Length)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 76 context '{group}' must contain exactly nine ECCM/degraded-fire packages.");
            }
            foreach (string mode in modes)
            {
                if (context.Count(v => string.Equals(v.ProfileLabel, mode, StringComparison.Ordinal)) != 1)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 76 context '{group}' is missing unique mode '{mode}'.");
                }
            }

            bool energy = group.StartsWith("c76-evm-", StringComparison.Ordinal);
            WeaponFamily expectedA = energy ? WeaponFamily.Energy : WeaponFamily.Kinetic;
            if (context.Any(v => v.SideAFamily != expectedA || v.SideBFamily != WeaponFamily.Missile))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 76 context '{group}' must keep Side A as the declared direct-fire family and Side B as Missile.");
            }
            bool fixedRange = group.EndsWith("-r3", StringComparison.Ordinal);
            Tl1IntegratedMovementOrder expectedOrder = group.EndsWith("-afirst", StringComparison.Ordinal)
                ? Tl1IntegratedMovementOrder.SideAFirst
                : group.EndsWith("-bfirst", StringComparison.Ordinal)
                    ? Tl1IntegratedMovementOrder.SideBFirst
                    : Tl1IntegratedMovementOrder.Simultaneous;
            if (context.Any(v =>
                    v.InitialRangeHexes != (fixedRange ? 3 : 4) ||
                    v.MovementMode != (fixedRange
                        ? Tl1IntegratedMovementMode.HoldRange3
                        : Tl1IntegratedMovementMode.TrackAwareOpponentRange) ||
                    v.MovementOrder != expectedOrder))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 76 context '{group}' has an initial-range, movement-mode, or movement-order mismatch.");
            }
        }

        if (aiDoctrineRegistry is null ||
            study.AiDoctrineCatalog != "docs/archive/ai/pre-cp165-active/ai_doctrine_registry_v0_2.json" ||
            aiDoctrineRegistry.Document.RegistryVersion != "0.2")
        {
            throw new InvalidOperationException(
                "Checkpoint 76 requires accepted AI Doctrine Registry v0.2 for the operational EW counterplay study.");
        }
        string[] requiredDoctrineIds =
        {
            "tl1-ew-none-v1",
            "tl1-ew-reactive-eccm-v1",
            "tl1-ew-preserve-combat-package-v1",
        };
        if (requiredDoctrineIds.Any(id => !aiDoctrineRegistry.ById.ContainsKey(id)))
        {
            throw new InvalidOperationException(
                "Checkpoint 76 is missing a required accepted/control EW doctrine from Registry v0.2.");
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument variant in study.Variants)
        {
            if (variant.SideASecondaryFamily is not null ||
                variant.SideBSecondaryFamily is not null ||
                variant.SideBFamily != WeaponFamily.Missile ||
                (variant.SideAFamily != WeaponFamily.Kinetic &&
                 variant.SideAFamily != WeaponFamily.Energy))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 76 variant '{variant.Id}' must isolate one direct-fire battery against one Missile battery.");
            }
            if (variant.SensorEwProfileId != "balanced-0" ||
                variant.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                variant.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                variant.SideANetEwRangePenalty != 0 || variant.SideBNetEwRangePenalty != 0 ||
                variant.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                variant.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                variant.SideAReactorOutputOverride != 5 || variant.SideBReactorOutputOverride != 5 ||
                variant.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                variant.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                variant.PdsEnabled != true || variant.StartingFuel != 100)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 76 variant '{variant.Id}' drifted from the accepted 5-TP Balanced-0 operational combat fixture.");
            }
            if (variant.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                variant.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                variant.SideBAllowsApproximateDirectFire ||
                variant.SideBApproximateDirectFireAccuracyPenalty != 0)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 76 variant '{variant.Id}' must isolate hostile Side-B ECM against Side-A direct fire; Missile degraded fire remains unimplemented.");
            }

            string mode = variant.ProfileLabel ?? string.Empty;
            bool firmReference = mode == "firm-reference";
            bool firmOnly = mode.StartsWith("jammed-firm-only-", StringComparison.Ordinal);
            int expectedPenalty = mode.StartsWith("p20-", StringComparison.Ordinal) ? 20 :
                mode.StartsWith("p25-", StringComparison.Ordinal) ? 25 : 0;
            bool reactive = mode.EndsWith("-reactive-eccm", StringComparison.Ordinal);
            bool aggressive = mode.EndsWith("-aggressive-eccm", StringComparison.Ordinal);
            Tl1IntegratedEwPowerPolicy expectedEccm = reactive
                ? Tl1IntegratedEwPowerPolicy.ReactiveNormal
                : aggressive
                    ? Tl1IntegratedEwPowerPolicy.Normal
                    : Tl1IntegratedEwPowerPolicy.None;
            string? expectedDoctrineA = reactive
                ? "tl1-ew-reactive-eccm-v1"
                : aggressive ? null : "tl1-ew-none-v1";
            string expectedDoctrineB = firmReference
                ? "tl1-ew-none-v1"
                : "tl1-ew-preserve-combat-package-v1";
            if (!string.Equals(variant.SideAAiDoctrineId, expectedDoctrineA, StringComparison.Ordinal) ||
                !string.Equals(variant.SideBAiDoctrineId, expectedDoctrineB, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 76 package '{variant.Id}' has an AI-doctrine binding mismatch.");
            }
            if (firmReference)
            {
                if (variant.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideAEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideAAllowsApproximateDirectFire ||
                    variant.SideAApproximateDirectFireAccuracyPenalty != 0)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 76 firm reference '{variant.Id}' must remain unjammed, Firm-only, and ECCM-off.");
                }
            }
            else
            {
                if (variant.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.Normal ||
                    variant.SideAEccmPolicy != expectedEccm)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 76 jammed package '{variant.Id}' has an ECM/ECCM policy mismatch.");
                }
                bool shouldAllowApproximate = expectedPenalty > 0;
                if (variant.SideAAllowsApproximateDirectFire != shouldAllowApproximate ||
                    variant.SideAApproximateDirectFireAccuracyPenalty != expectedPenalty ||
                    (firmOnly && shouldAllowApproximate))
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 76 package '{variant.Id}' does not match its explicit per-weapon degraded-fire definition.");
                }
            }
        }

        _ = technologyProfiles;
        _ = auxiliaryProfiles;
        _ = sensorEwProfiles;
    }

    private static void ValidateTl2SensorEwDiscriminationIsolationCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (study.Variants.Count != RequiredTl2SensorEwDiscriminationIsolationVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 79 requires exactly {RequiredTl2SensorEwDiscriminationIsolationVariantCount} TL2 Sensor/EW isolation variants.");
        }
        if (study.TechnologyProfileCatalog is not null ||
            study.SensorEwProfileCatalog !=
                "src/StarCluster.ScenarioRunner/Scenarios/SensorEw/tl2-sew01-sensor-discrimination-isolation.json")
        {
            throw new InvalidOperationException(
                "Checkpoint 79 must retain TL1 production combat profiles while using only the dedicated TL2 Sensor/EW diagnostic catalog.");
        }
        if (study.Builds.Count != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 79 requires exactly one fixed 35-Space EW-capable combat fixture.");
        }
        Tl1IntegratedShipBuildDocument build = study.Builds.Single();
        if (build.Id != "balanced_generalist_ew_major" ||
            build.MainWeaponCount != 1 || build.MainReactorCount != 1 ||
            !build.ActiveSensor || !build.ShieldGenerator ||
            build.KineticPdsCount != 1 || !build.EcmSuite || !build.EccmSuite ||
            build.UsedSpace != 35 || build.FreeSupportSpace != 0)
        {
            throw new InvalidOperationException(
                "Checkpoint 79 fixed combat fixture drifted from the accepted 35-Space EW major build.");
        }

        if (sensorEwProfiles.Count != 2 ||
            !sensorEwProfiles.TryGetValue("tl1-balanced-0-control", out SensorEwFoundationProfile? tl1Sensor) ||
            !sensorEwProfiles.TryGetValue("tl2-discrimination-1-candidate", out SensorEwFoundationProfile? tl2Sensor))
        {
            throw new InvalidOperationException(
                "Checkpoint 79 requires exactly the TL1 Balanced-0 control and TL2 DR-1 candidate Sensor/EW profiles.");
        }
        static bool HasHeldBalancedZeroEnvelope(SensorEwFoundationProfile profile) =>
            profile.PassiveFirmRange == 1 &&
            profile.PassiveApproximateRange == 3 &&
            profile.ActiveFirmRange == 3 &&
            profile.ActiveApproximateRange == 4 &&
            profile.ActivePowerCost == 1 &&
            profile.ActiveOverloadAdditionalPowerCost == 1 &&
            profile.ActiveOverloadFirmBonus == 1 &&
            profile.ActiveOverloadApproximateBonus == 1 &&
            profile.PointBlankBurnThroughResistance == 1;
        if (!HasHeldBalancedZeroEnvelope(tl1Sensor) ||
            !HasHeldBalancedZeroEnvelope(tl2Sensor) ||
            tl1Sensor.DiscriminationResistance != 0 ||
            tl2Sensor.DiscriminationResistance != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 79 must isolate Sensor Discrimination Resistance 0 versus 1 while holding reach, power, overload, and point-blank burn-through constant.");
        }

        string[] groups =
        {
            "c79-kvm-r3",
            "c79-evm-r3",
            "c79-kvm-afirst",
            "c79-kvm-bfirst",
            "c79-evm-afirst",
            "c79-evm-bfirst",
        };
        string[] packages =
        {
            "firm-reference",
            "tl1-ecm1-eccm1-control",
            "tl1-vs-ecm2-firm-only-no-eccm",
            "tl1-vs-ecm2-eccm1",
            "tl1-vs-ecm2-eccm2",
            "tl1-vs-ecm2-p25-no-eccm",
            "tl2dr1-vs-ecm1-no-eccm",
            "tl2dr1-vs-ecm2-firm-only-no-eccm",
            "tl2dr1-vs-ecm2-eccm1",
        };

        foreach (string group in groups)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants
                .Where(v => string.Equals(v.ComparisonGroup, group, StringComparison.Ordinal))
                .ToArray();
            if (context.Length != packages.Length)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 79 context '{group}' must contain exactly nine TL2 isolation packages.");
            }
            foreach (string package in packages)
            {
                if (context.Count(v => string.Equals(v.ProfileLabel, package, StringComparison.Ordinal)) != 1)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 79 context '{group}' is missing unique package '{package}'.");
                }
            }

            bool energy = group.StartsWith("c79-evm-", StringComparison.Ordinal);
            WeaponFamily expectedA = energy ? WeaponFamily.Energy : WeaponFamily.Kinetic;
            bool fixedRange = group.EndsWith("-r3", StringComparison.Ordinal);
            Tl1IntegratedMovementOrder expectedOrder = group.EndsWith("-afirst", StringComparison.Ordinal)
                ? Tl1IntegratedMovementOrder.SideAFirst
                : group.EndsWith("-bfirst", StringComparison.Ordinal)
                    ? Tl1IntegratedMovementOrder.SideBFirst
                    : Tl1IntegratedMovementOrder.Simultaneous;
