                if (context.Count(v => string.Equals(v.ProfileLabel, package, StringComparison.Ordinal)) != 1)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 80 context '{group}' is missing unique package '{package}'.");
                }
