            Tl1IntegratedMovementOrder expectedOrder = group.EndsWith("-afirst", StringComparison.Ordinal)
                ? Tl1IntegratedMovementOrder.SideAFirst
                : group.EndsWith("-bfirst", StringComparison.Ordinal)
                    ? Tl1IntegratedMovementOrder.SideBFirst
                    : Tl1IntegratedMovementOrder.Simultaneous;
            if (context.Any(v =>
                    v.SideAFamily != expectedA || v.SideBFamily != expectedB ||
                    v.SideASecondaryFamily is not null || v.SideBSecondaryFamily is not null ||
                    v.InitialRangeHexes != (fixedRange ? 3 : 4) ||
                    v.MovementMode != (fixedRange
