            }

            string label = variant.ProfileLabel ?? string.Empty;
            bool tall = label.StartsWith("tall-dr1-eccm1-", StringComparison.Ordinal);
            bool wide = label.StartsWith("wide-eccm2-", StringComparison.Ordinal);
            bool degraded = label == "degraded-p25-5tp";
            bool firmReference = label == "firm-reference-5tp";
            bool sixPower = label.EndsWith("6tp-sensitivity", StringComparison.Ordinal);
            string expectedSensor = tall
