            tl1.ShieldCapacity != 2 || tl1.ShieldBaseRecharge != 1 ||
            tl1.ShieldArmor != 0 || tl1.ReactorOutput != 5 ||
            tl1.Kinetic.ArmorPenetration != 0 ||
            tl1.Energy.ArmorPenetration != 1 ||
            tl1.Missile.ArmorPenetration != 2)
        {
            throw new InvalidOperationException(
                "Checkpoint 85 requires the accepted TL1 AP0/AI4 armor, Shield 2, Reactor 5, and K/E/M APEN 0/1/2 reference.");
        }
        if (sensorEwProfiles.Count != 2 ||
            !sensorEwProfiles.TryGetValue("tl1-balanced-0-control", out SensorEwFoundationProfile? tl1Sensor) ||
            !sensorEwProfiles.TryGetValue("tl2-discrimination-1-candidate", out SensorEwFoundationProfile? tl2Sensor) ||
            tl1Sensor.DiscriminationResistance != 0 ||
            tl2Sensor.DiscriminationResistance != 1 ||
            tl1Sensor.PassiveFirmRange != tl2Sensor.PassiveFirmRange ||
            tl1Sensor.PassiveApproximateRange != tl2Sensor.PassiveApproximateRange ||
            tl1Sensor.ActiveFirmRange != tl2Sensor.ActiveFirmRange ||
            tl1Sensor.ActiveApproximateRange != tl2Sensor.ActiveApproximateRange ||
            tl1Sensor.ActivePowerCost != tl2Sensor.ActivePowerCost)
        {
            throw new InvalidOperationException(
                "Checkpoint 85 must preserve accepted DR0/DR1 Sensor isolation while holding physical reach and Active power constant.");
        }

        string[] groups =
        {
            "c85-kvk-r3", "c85-kvk-afirst", "c85-kvk-bfirst",
            "c85-kve-r3", "c85-kve-afirst", "c85-kve-bfirst",
            "c85-kvm-r3", "c85-kvm-afirst", "c85-kvm-bfirst",
            "c85-evk-r3", "c85-evk-afirst", "c85-evk-bfirst",
            "c85-eve-r3", "c85-eve-afirst", "c85-eve-bfirst",
            "c85-evm-r3", "c85-evm-afirst", "c85-evm-bfirst",
        };
        string[] environments = { "firm-reference", "tall-dr1-eccm1" };
        int[] shields = { 2, 3 };
        (int Ap, int Ai)[] armorPackages =
        {
            (0, 4), (0, 5), (1, 4), (1, 5),
        };
        foreach (string group in groups)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants
                .Where(v => string.Equals(v.ComparisonGroup, group, StringComparison.Ordinal))
                .ToArray();
            if (context.Length != environments.Length * shields.Length * armorPackages.Length)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 85 context '{group}' must contain exactly sixteen environment/shield/armor permutations.");
            }
            foreach (string environment in environments)
            foreach (int shield in shields)
            foreach ((int ap, int ai) in armorPackages)
            {
                string label = $"{environment}-s{shield}-ap{ap}-ai{ai}";
                if (context.Count(v => string.Equals(v.ProfileLabel, label, StringComparison.Ordinal)) != 1)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 85 context '{group}' is missing unique permutation '{label}'.");
                }
            }
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument variant in study.Variants)
        {
            string label = variant.ProfileLabel ?? string.Empty;
            bool tall = label.StartsWith("tall-dr1-eccm1-", StringComparison.Ordinal);
            bool firm = label.StartsWith("firm-reference-", StringComparison.Ordinal);
            string expectedSensor = tall
                ? "tl2-discrimination-1-candidate"
                : "tl1-balanced-0-control";
            if ((!tall && !firm) ||
                variant.SideAProfileId != "tl1-production" ||
                variant.SideBProfileId != "tl1-production" ||
                variant.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                variant.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                variant.SideASensorEwProfileId != expectedSensor ||
                variant.SideBSensorEwProfileId != "tl1-balanced-0-control" ||
                variant.SideAShieldCapacityOverride is not (2 or 3) ||
                variant.SideBShieldCapacityOverride != 2 ||
                variant.SideAPrimaryArmorProtectionOverride is not (0 or 1) ||
                variant.SideAPrimaryArmorIntegrityOverride is not (4 or 5) ||
                variant.SideBPrimaryArmorProtectionOverride != 0 ||
                variant.SideBPrimaryArmorIntegrityOverride != 4 ||
                variant.SideAReactorOutputOverride != 6 ||
                variant.SideBReactorOutputOverride != 5 ||
                variant.SideATacticalComputerTargetingBonusOverride != 12 ||
                variant.SideBTacticalComputerTargetingBonusOverride != 10 ||
                variant.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                variant.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                variant.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                variant.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                variant.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                variant.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                variant.BaseShieldRechargeEnabled != true || variant.PdsEnabled != true ||
                variant.EvasiveManeuversEnabled != false || variant.StartingFuel != 100 ||
                variant.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                variant.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                variant.SideAEcmNormalPowerCostOverride != 1 ||
                variant.SideBEcmNormalPowerCostOverride != 1 ||
                variant.SideAEccmNormalPowerCostOverride != 1 ||
                variant.SideBEccmNormalPowerCostOverride != 1 ||
                variant.SideAAllowsApproximateDirectFire ||
                variant.SideBAllowsApproximateDirectFire ||
                variant.SideAApproximateDirectFireAccuracyPenalty != 0 ||
                variant.SideBApproximateDirectFireAccuracyPenalty != 0)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 85 variant '{variant.Id}' drifted from the isolated Armor AP/AI x Shield fixture.");
            }
            if (firm && (variant.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideAEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideBEcmNormalRatingOverride != 1 ||
                    variant.SideAEccmNormalRatingOverride != 1))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 85 Firm-reference variant '{variant.Id}' is EW-contaminated.");
            }
            if (tall && (variant.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.Normal ||
                    variant.SideAEccmPolicy != Tl1IntegratedEwPowerPolicy.ReactiveNormal ||
                    variant.SideBEcmNormalRatingOverride != 2 ||
                    variant.SideAEccmNormalRatingOverride != 1))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 85 tall variant '{variant.Id}' must use ECM2 vs DR1 + reactive ECCM1.");
            }
        }
        _ = auxiliaryProfiles;
    }

    private static void ValidateTl2WeaponPenetrationLayeredDefenseCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (study.Variants.Count != RequiredTl2WeaponPenetrationLayeredDefenseVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 86 requires exactly {RequiredTl2WeaponPenetrationLayeredDefenseVariantCount} weapon-penetration x layered-defense permutations.");
        }
        if (study.TechnologyProfileCatalog is not null ||
            study.SensorEwProfileCatalog !=
                "src/StarCluster.ScenarioRunner/Scenarios/SensorEw/tl2-sew01-sensor-discrimination-isolation.json")
        {
            throw new InvalidOperationException(
                "Checkpoint 86 must retain the TL1 weapon source profile and accepted DR0/DR1 Sensor/EW catalog.");
        }
        if (!technologyProfiles.TryGetValue("tl1-production", out TechnologyCombatProfile? tl1) ||
            tl1 is null || tl1.Kinetic.Damage != 4 || tl1.Kinetic.ShieldPenetration != 1 ||
            tl1.Kinetic.ArmorPenetration != 0 || tl1.Energy.Damage != 3 ||
            tl1.Energy.ShieldPenetration != 1 || tl1.Energy.ArmorPenetration != 1 ||
            tl1.Missile.Damage != 5 || tl1.Missile.ShieldPenetration != 1 ||
            tl1.Missile.ArmorPenetration != 2 || tl1.ArmorIntegrity != 4 ||
            tl1.ArmorProtection != 0 || tl1.ShieldCapacity != 2 || tl1.ReactorOutput != 5)
        {
            throw new InvalidOperationException(
                "Checkpoint 86 requires the accepted K/E/M damage and SPEN/APEN references plus TL1 defensive/power baselines.");
        }
        if (study.AuxiliaryProfileCatalog !=
                "src/StarCluster.ScenarioRunner/Scenarios/ArchitectureTechnology/tl1-tl2-auxiliary-runtime-profiles-v0_3.json" ||
            study.Builds.Count != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 86 must preserve the accepted auxiliary catalog and one fixed 35-Space EW-capable combat fixture.");
        }
        Tl1IntegratedShipBuildDocument build = study.Builds.Single();
        if (build.Id != "balanced_generalist_ew_major" ||
            build.MainWeaponCount != 1 || build.MainReactorCount != 1 ||
            !build.ActiveSensor || !build.ShieldGenerator ||
            build.KineticPdsCount != 1 || !build.EcmSuite || !build.EccmSuite ||
            build.UsedSpace != 35 || build.FreeSupportSpace != 0)
        {
            throw new InvalidOperationException(
                "Checkpoint 86 fixed combat fixture drifted from the accepted 35-Space EW major build.");
        }
        if (sensorEwProfiles.Count != 2 ||
            !sensorEwProfiles.TryGetValue("tl1-balanced-0-control", out SensorEwFoundationProfile? tl1Sensor) ||
            !sensorEwProfiles.TryGetValue("tl2-discrimination-1-candidate", out SensorEwFoundationProfile? tl2Sensor) ||
            tl1Sensor.DiscriminationResistance != 0 || tl2Sensor.DiscriminationResistance != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 86 must preserve the accepted DR0/DR1 information-control isolation profiles.");
        }
        string[] groups =
        {
            "c86-k-r3", "c86-k-afirst", "c86-k-bfirst",
            "c86-e-r3", "c86-e-afirst", "c86-e-bfirst",
            "c86-m-r3", "c86-m-afirst", "c86-m-bfirst",
        };
        string[] environments = { "firm-reference", "tall-dr1-eccm1" };
        string[] penetrationLabels = { "control", "apen", "spen", "combined" };
        foreach (string group in groups)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants
                .Where(v => string.Equals(v.ComparisonGroup, group, StringComparison.Ordinal))
                .ToArray();
            if (context.Length != 32)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 86 context '{group}' must contain exactly 32 environment/penetration/defense permutations.");
            }
            foreach (string environment in environments)
            foreach (int shield in new[] { 2, 3 })
            foreach (int ap in new[] { 0, 1 })
            foreach (string penetrationLabel in penetrationLabels)
            {
                string label = $"{environment}-{penetrationLabel}-s{shield}-ap{ap}-ai5";
                if (context.Count(v => string.Equals(v.ProfileLabel, label, StringComparison.Ordinal)) != 1)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 86 context '{group}' is missing unique permutation '{label}'.");
                }
            }
        }
        foreach (Tl1IntegratedTacticalCombatVariantDocument variant in study.Variants)
        {
            string label = variant.ProfileLabel ?? string.Empty;
            bool tall = label.StartsWith("tall-dr1-eccm1-", StringComparison.Ordinal);
            bool firm = label.StartsWith("firm-reference-", StringComparison.Ordinal);
            string penetrationLabel = penetrationLabels.SingleOrDefault(candidate =>
                    label.Contains($"-{candidate}-", StringComparison.Ordinal))
                ?? throw new InvalidOperationException(
                    $"Checkpoint 86 variant '{variant.Id}' has an invalid penetration label.");
            (int ControlSpen, int ControlApen) = variant.SideAFamily switch
            {
                WeaponFamily.Kinetic => (1, 0),
                WeaponFamily.Energy => (1, 1),
                WeaponFamily.Missile => (1, 2),
                _ => throw new InvalidOperationException(
                    $"Checkpoint 86 variant '{variant.Id}' uses an unsupported weapon family."),
            };
            int expectedSpen = ControlSpen + (penetrationLabel is "spen" or "combined" ? 1 : 0);
            int expectedApen = ControlApen + (penetrationLabel is "apen" or "combined" ? 1 : 0);
            if ((!firm && !tall) || variant.SideAFamily != variant.SideBFamily ||
                variant.SideAProfileId != "tl1-production" || variant.SideBProfileId != "tl1-production" ||
                variant.SideAReactorOutputOverride != 6 || variant.SideBReactorOutputOverride != 6 ||
                variant.SideAShieldCapacityOverride != 3 || variant.SideBShieldCapacityOverride is not (2 or 3) ||
                variant.SideAPrimaryArmorProtectionOverride != 0 || variant.SideAPrimaryArmorIntegrityOverride != 5 ||
                variant.SideBPrimaryArmorProtectionOverride is not (0 or 1) || variant.SideBPrimaryArmorIntegrityOverride != 5 ||
                variant.SideAWeaponShieldPenetrationOverride != expectedSpen ||
                variant.SideAWeaponArmorPenetrationOverride != expectedApen ||
                variant.SideBWeaponShieldPenetrationOverride != ControlSpen ||
                variant.SideBWeaponArmorPenetrationOverride != ControlApen ||
                variant.SideATacticalComputerTargetingBonusOverride != 12 ||
                variant.SideBTacticalComputerTargetingBonusOverride != 10 ||
                variant.SideASensorEwProfileId != (tall ? "tl2-discrimination-1-candidate" : "tl1-balanced-0-control") ||
                variant.SideBSensorEwProfileId != "tl1-balanced-0-control" ||
                variant.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                variant.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                variant.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                variant.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                variant.BaseShieldRechargeEnabled != true || variant.PdsEnabled != true ||
                variant.EvasiveManeuversEnabled != false || variant.StartingFuel != 100 ||
                variant.SideAAllowsApproximateDirectFire || variant.SideBAllowsApproximateDirectFire ||
                variant.SideAApproximateDirectFireAccuracyPenalty != 0 ||
                variant.SideBApproximateDirectFireAccuracyPenalty != 0)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 86 variant '{variant.Id}' drifted from the penetration/layered-defense isolation fixture.");
            }
            if (firm && (variant.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideAEccmPolicy != Tl1IntegratedEwPowerPolicy.None))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 86 Firm-reference variant '{variant.Id}' is EW-contaminated.");
            }
            if (tall && (variant.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.Normal ||
                    variant.SideBEcmNormalRatingOverride != 2 ||
                    variant.SideAEccmPolicy != Tl1IntegratedEwPowerPolicy.ReactiveNormal ||
                    variant.SideAEccmNormalRatingOverride != 1))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 86 tall variant '{variant.Id}' must use ECM2 vs DR1 + reactive ECCM1.");
            }
        }
        _ = auxiliaryProfiles;
    }

    private static void ValidateCrossTlBuildPermutationScreeningCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (study.Variants.Count != RequiredCrossTlBuildPermutationScreeningVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 87 requires exactly {RequiredCrossTlBuildPermutationScreeningVariantCount} generated cross-TL screening variants.");
        }
        if (study.Builds.Count != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 87 generated screen requires exactly one common 35-Space physical shell.");
        }
        Tl1IntegratedShipBuildDocument shell = study.Builds[0];
        if (shell.Id != "cross_tl_exact_fill_shell" || shell.MainWeaponCount != 1 ||
            shell.MainReactorCount != 1 || !shell.ActiveSensor || !shell.ShieldGenerator ||
            shell.KineticPdsCount != 1 || !shell.EcmSuite || !shell.EccmSuite ||
            shell.UsedSpace != 35 || shell.FreeSupportSpace != 0)
        {
            throw new InvalidOperationException(
                "Checkpoint 87 generated physical shell must remain the exact-fill 35-Space one-main/one-reactor Sensor/Shield/PDS/ECM/ECCM cruiser shell.");
        }
        if (!technologyProfiles.ContainsKey("tl1-production") ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1") ||
            !sensorEwProfiles.ContainsKey("tl1-balanced-0-control") ||
            !sensorEwProfiles.ContainsKey("tl2-discrimination-1-candidate"))
        {
            throw new InvalidOperationException(
                "Checkpoint 87 generated screen is missing a required runtime catalog binding.");
        }

        string[] groups = study.Variants.Select(v => v.ComparisonGroup ?? string.Empty)
            .Distinct(StringComparer.Ordinal).ToArray();
        if (groups.Length != 64 || groups.Any(string.IsNullOrWhiteSpace))
        {
            throw new InvalidOperationException(
                $"Checkpoint 87 requires exactly 64 non-empty logical comparison groups; found {groups.Length}.");
        }
        foreach (string group in groups)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] variants = study.Variants
                .Where(v => v.ComparisonGroup == group).ToArray();
            if (variants.Length != 3 ||
                variants.Count(v => v.MovementMode == Tl1IntegratedMovementMode.HoldRange3 &&
                    v.MovementOrder == Tl1IntegratedMovementOrder.Simultaneous) != 1 ||
                variants.Count(v => v.MovementMode == Tl1IntegratedMovementMode.TrackAwareOpponentRange &&
                    v.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst) != 1 ||
                variants.Count(v => v.MovementMode == Tl1IntegratedMovementMode.TrackAwareOpponentRange &&
                    v.MovementOrder == Tl1IntegratedMovementOrder.SideBFirst) != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 87 comparison group '{group}' must contain fixed Range-3 plus both TrackAware dynamic movement-order contexts.");
            }
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            if (v.InitialRangeHexes != 3 || v.TacticalMapRadius != 5 ||
                v.StartingFuel != 100 || v.MovementFuelPerHex != 2 ||
                v.SideABuildId != shell.Id || v.SideBBuildId != shell.Id ||
                v.SideAProfileId != "tl1-production" || v.SideBProfileId != "tl1-production" ||
                v.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.SideAReactorOutputOverride is not (5 or 6) ||
                v.SideBReactorOutputOverride is not (5 or 6) ||
                v.SideATacticalComputerTargetingBonusOverride is not (10 or 12) ||
                v.SideBTacticalComputerTargetingBonusOverride is not (10 or 12) ||
                v.SideAShieldCapacityOverride is not (2 or 3) ||
                v.SideBShieldCapacityOverride is not (2 or 3) ||
                v.SideAPrimaryArmorProtectionOverride != 0 ||
                v.SideBPrimaryArmorProtectionOverride != 0 ||
                v.SideAPrimaryArmorIntegrityOverride is not (4 or 5) ||
                v.SideBPrimaryArmorIntegrityOverride is not (4 or 5) ||
                v.SideAEcmNormalRatingOverride is not (1 or 2) ||
                v.SideBEcmNormalRatingOverride is not (1 or 2) ||
                v.SideAEccmNormalRatingOverride is not (1 or 2) ||
                v.SideBEccmNormalRatingOverride is not (1 or 2) ||
                v.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.Normal ||
                v.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.Normal ||
                v.SideAEccmPolicy != Tl1IntegratedEwPowerPolicy.ReactiveNormal ||
                v.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.ReactiveNormal ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideAAllowsApproximateDirectFire || v.SideBAllowsApproximateDirectFire ||
                !(v.BaseShieldRechargeEnabled ?? false) || !(v.PdsEnabled ?? false) ||
                (v.EvasiveManeuversEnabled ?? true) || (v.EscapeDisengagementEnabled ?? true))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 87 variant '{v.Id}' drifted from the generated cross-TL screening shell/runtime contract.");
            }
            if (v.SideASensorEwProfileId is not ("tl1-balanced-0-control" or "tl2-discrimination-1-candidate") ||
                v.SideBSensorEwProfileId is not ("tl1-balanced-0-control" or "tl2-discrimination-1-candidate"))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 87 variant '{v.Id}' uses a sensor profile outside the TL1/TL2 working envelope.");
            }
            ValidateCrossTlWeaponProfile(v.Id, "A", v.SideAFamily,
                v.SideAWeaponShieldPenetrationOverride, v.SideAWeaponArmorPenetrationOverride);
            ValidateCrossTlWeaponProfile(v.Id, "B", v.SideBFamily,
                v.SideBWeaponShieldPenetrationOverride, v.SideBWeaponArmorPenetrationOverride);
        }
    }

