                v.SideBPrimaryArmorProtectionOverride != 0 ||
                v.SideAPrimaryArmorIntegrityOverride is not (4 or 5) ||
                v.SideBPrimaryArmorIntegrityOverride is not (4 or 5) ||
                v.SideAEcmNormalRatingOverride is not (1 or 2) ||
                v.SideBEcmNormalRatingOverride is not (1 or 2) ||
                v.SideAEccmNormalRatingOverride is not (1 or 2) ||
                v.SideBEccmNormalRatingOverride is not (1 or 2) ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideAAllowsApproximateDirectFire || v.SideBAllowsApproximateDirectFire ||
                !(v.BaseShieldRechargeEnabled ?? false) || !(v.PdsEnabled ?? false) ||
                (v.EvasiveManeuversEnabled ?? true) || (v.EscapeDisengagementEnabled ?? true))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 88 variant '{v.Id}' drifted from the power-aware generated screening contract.");
            }
            if (v.SideASensorEwProfileId is not ("tl1-balanced-0-control" or "tl2-discrimination-1-candidate") ||
                v.SideBSensorEwProfileId is not ("tl1-balanced-0-control" or "tl2-discrimination-1-candidate"))
            {
                throw new InvalidOperationException($"Checkpoint 88 variant '{v.Id}' uses a sensor profile outside the working envelope.");
            }
            ValidateCrossTlWeaponProfile(v.Id, "A", v.SideAFamily,
                v.SideAWeaponShieldPenetrationOverride, v.SideAWeaponArmorPenetrationOverride);
            ValidateCrossTlWeaponProfile(v.Id, "B", v.SideBFamily,
                v.SideBWeaponShieldPenetrationOverride, v.SideBWeaponArmorPenetrationOverride);
        }
    }

    private static void ValidateCrossTlGeneralizedLegalBuildScreeningCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (study.Variants.Count != RequiredCrossTlGeneralizedLegalBuildScreeningVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 90 requires exactly {RequiredCrossTlGeneralizedLegalBuildScreeningVariantCount} generated generalized cross-TL screening variants.");
        }
        if (study.AiDoctrineCatalog != "docs/archive/ai/pre-cp165-active/ai_doctrine_registry_v0_2.json")
        {
            throw new InvalidOperationException("Checkpoint 90 generated screen must bind the accepted AI doctrine registry v0.2.");
        }
        if (!technologyProfiles.ContainsKey("tl1-production") ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1") ||
            !sensorEwProfiles.ContainsKey("tl1-balanced-0-control") ||
            !sensorEwProfiles.ContainsKey("tl2-discrimination-1-candidate"))
        {
            throw new InvalidOperationException("Checkpoint 90 generated screen is missing a required runtime catalog binding.");
        }
        if (study.Builds.Count == 0 || study.Builds.Select(build => build.Id).Distinct(StringComparer.Ordinal).Count() != study.Builds.Count)
        {
            throw new InvalidOperationException("Checkpoint 90 requires a non-empty set of unique physical build documents.");
        }
        foreach (Tl1IntegratedShipBuildDocument build in study.Builds)
        {
            if (build.MainWeaponCount is < 1 or > 2 || build.MainReactorCount is < 1 or > 2 ||
                (build.MainWeaponCount == 2 && build.MainReactorCount == 2) ||
                build.KineticPdsCount is < 0 or > 1 || build.UsedSpace is < 25 or > 35 ||
                build.FreeSupportSpace != 35 - build.UsedSpace ||
                build.AdvancedComponentCount is null or < 0 ||
                string.IsNullOrWhiteSpace(build.CrossTlCompositionClass))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 90 physical build '{build.Id}' violates the generalized 35-Space construction contract.");
            }
            if (build.EcmSuite != (build.EcmSuiteRatings.Count > 0) ||
                build.EccmSuite != (build.EccmSuiteRatings.Count > 0) ||
                build.EcmSuiteRatings.Count > 2 || build.EccmSuiteRatings.Count > 2 ||
                build.EcmSuiteRatings.Any(rating => rating is < 1 or > 2) ||
                build.EccmSuiteRatings.Any(rating => rating is < 1 or > 2))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 90 physical build '{build.Id}' violates non-additive ECM/ECCM multiplicity bounds.");
            }
        }
        if (!study.Builds.Any(build => build.MainWeaponCount == 2) ||
            !study.Builds.Any(build => build.MainReactorCount == 2) ||
            !study.Builds.Any(build => build.EcmSuiteRatings.Count == 2) ||
            !study.Builds.Any(build => build.EccmSuiteRatings.Count == 2) ||
            !study.Builds.Any(build => build.EcmSuiteRatings.SequenceEqual(new[] { 1, 2 })) ||
            !study.Builds.Any(build => build.EccmSuiteRatings.SequenceEqual(new[] { 1, 2 })))
        {
            throw new InvalidOperationException(
                "Checkpoint 90 executed build slice must include optional second Main Weapon/Reactor, duplicate ECM/ECCM, and mixed-rating EW redundancy examples.");
        }
        var builds = study.Builds.ToDictionary(build => build.Id, StringComparer.Ordinal);
        string[] groups = study.Variants.Select(v => v.ComparisonGroup ?? string.Empty)
            .Distinct(StringComparer.Ordinal).ToArray();
        if (groups.Length != 144 || groups.Any(string.IsNullOrWhiteSpace))
        {
            throw new InvalidOperationException(
                $"Checkpoint 90 requires exactly 144 non-empty logical comparison groups; found {groups.Length}.");
        }
        foreach (string group in groups)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] variants = study.Variants
                .Where(v => v.ComparisonGroup == group).ToArray();
            if (variants.Length != 3 ||
                variants.Count(v => v.MovementMode == Tl1IntegratedMovementMode.HoldRange3 &&
                    v.MovementOrder == Tl1IntegratedMovementOrder.Simultaneous) != 1 ||
                variants.Count(v => v.MovementMode == Tl1IntegratedMovementMode.TrackAwareOpponentRange &&
                    v.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst) != 1 ||
                variants.Count(v => v.MovementMode == Tl1IntegratedMovementMode.TrackAwareOpponentRange &&
                    v.MovementOrder == Tl1IntegratedMovementOrder.SideBFirst) != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 90 comparison group '{group}' must contain fixed Range-3 plus both TrackAware dynamic movement-order contexts.");
            }
        }
        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            if (v.InitialRangeHexes != 3 || v.TacticalMapRadius != 5 ||
                v.StartingFuel != 100 || v.MovementFuelPerHex != 2 ||
                string.IsNullOrWhiteSpace(v.SideABuildId) || string.IsNullOrWhiteSpace(v.SideBBuildId) ||
                v.SideAProfileId != "tl1-production" || v.SideBProfileId != "tl1-production" ||
                v.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.SideAAiDoctrineId != "tl1-ew-preserve-combat-package-v1" ||
                v.SideBAiDoctrineId != "tl1-ew-preserve-combat-package-v1" ||
                v.SideAReactorOutputOverride is not (5 or 6) ||
                v.SideBReactorOutputOverride is not (5 or 6) ||
                v.SideATacticalComputerTargetingBonusOverride is not (10 or 12) ||
                v.SideBTacticalComputerTargetingBonusOverride is not (10 or 12) ||
                v.SideAShieldCapacityOverride is not (0 or 2 or 3) ||
                v.SideBShieldCapacityOverride is not (0 or 2 or 3) ||
                v.SideAPrimaryArmorProtectionOverride != 0 ||
                v.SideBPrimaryArmorProtectionOverride != 0 ||
                v.SideAPrimaryArmorIntegrityOverride is not (4 or 5) ||
                v.SideBPrimaryArmorIntegrityOverride is not (4 or 5) ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideAAllowsApproximateDirectFire || v.SideBAllowsApproximateDirectFire ||
                !(v.BaseShieldRechargeEnabled ?? false) || !(v.PdsEnabled ?? false) ||
                (v.EvasiveManeuversEnabled ?? true) || (v.EscapeDisengagementEnabled ?? true))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 90 variant '{v.Id}' drifted from the generalized legal-build screening contract.");
            }
            if (!builds.TryGetValue(v.SideABuildId!, out Tl1IntegratedShipBuildDocument? buildA) || buildA is null ||
                !builds.TryGetValue(v.SideBBuildId!, out Tl1IntegratedShipBuildDocument? buildB) || buildB is null)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 90 variant '{v.Id}' references an unknown generated build ID.");
            }
            if ((buildA.MainWeaponCount == 2) != (v.SideASecondaryFamily == v.SideAFamily) ||
                (buildB.MainWeaponCount == 2) != (v.SideBSecondaryFamily == v.SideBFamily) ||
                buildA.MainReactorCount < 1 || buildB.MainReactorCount < 1 ||
                buildA.ShieldGenerator != (v.SideAShieldCapacityOverride > 0) ||
                buildB.ShieldGenerator != (v.SideBShieldCapacityOverride > 0) ||
                (buildA.EcmSuiteRatings.Count == 0 && v.SideAEcmNormalRatingOverride is not null) ||
                (buildA.EcmSuiteRatings.Count > 0 && v.SideAEcmNormalRatingOverride is null) ||
                (buildB.EcmSuiteRatings.Count == 0 && v.SideBEcmNormalRatingOverride is not null) ||
                (buildB.EcmSuiteRatings.Count > 0 && v.SideBEcmNormalRatingOverride is null) ||
                (buildA.EccmSuiteRatings.Count == 0 && v.SideAEccmNormalRatingOverride is not null) ||
                (buildA.EccmSuiteRatings.Count > 0 && v.SideAEccmNormalRatingOverride is null) ||
                (buildB.EccmSuiteRatings.Count == 0 && v.SideBEccmNormalRatingOverride is not null) ||
                (buildB.EccmSuiteRatings.Count > 0 && v.SideBEccmNormalRatingOverride is null))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 90 variant '{v.Id}' is inconsistent with its referenced physical build multiplicity/installation state.");
            }
            if ((buildA.EcmSuiteRatings.Count > 0 && v.SideAEcmNormalRatingOverride != buildA.EcmSuiteRatings.Max()) ||
                (buildB.EcmSuiteRatings.Count > 0 && v.SideBEcmNormalRatingOverride != buildB.EcmSuiteRatings.Max()) ||
                (buildA.EccmSuiteRatings.Count > 0 && v.SideAEccmNormalRatingOverride != buildA.EccmSuiteRatings.Max()) ||
                (buildB.EccmSuiteRatings.Count > 0 && v.SideBEccmNormalRatingOverride != buildB.EccmSuiteRatings.Max()))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 90 variant '{v.Id}' must expose only the highest installed ECM/ECCM rating; duplicate ratings are never additive.");
            }
            if (v.SideASensorEwProfileId is not ("tl1-balanced-0-control" or "tl2-discrimination-1-candidate") ||
                v.SideBSensorEwProfileId is not ("tl1-balanced-0-control" or "tl2-discrimination-1-candidate"))
            {
                throw new InvalidOperationException($"Checkpoint 90 variant '{v.Id}' uses a sensor profile outside the working envelope.");
            }
            ValidateCrossTlWeaponProfile(v.Id, "A", v.SideAFamily,
                v.SideAWeaponShieldPenetrationOverride, v.SideAWeaponArmorPenetrationOverride);
            ValidateCrossTlWeaponProfile(v.Id, "B", v.SideBFamily,
                v.SideBWeaponShieldPenetrationOverride, v.SideBWeaponArmorPenetrationOverride);
        }
    }

