                buildB.ShieldGenerator != (v.SideBShieldCapacityOverride > 0) ||
                (buildA.EcmSuiteRatings.Count == 0 && v.SideAEcmNormalRatingOverride is not null) ||
                (buildA.EcmSuiteRatings.Count > 0 && v.SideAEcmNormalRatingOverride is null) ||
                (buildB.EcmSuiteRatings.Count == 0 && v.SideBEcmNormalRatingOverride is not null) ||
                (buildB.EcmSuiteRatings.Count > 0 && v.SideBEcmNormalRatingOverride is null) ||
                (buildA.EccmSuiteRatings.Count == 0 && v.SideAEccmNormalRatingOverride is not null) ||
                (buildA.EccmSuiteRatings.Count > 0 && v.SideAEccmNormalRatingOverride is null) ||
                (buildB.EccmSuiteRatings.Count == 0 && v.SideBEccmNormalRatingOverride is not null) ||
                (buildB.EccmSuiteRatings.Count > 0 && v.SideBEccmNormalRatingOverride is null))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 94 variant '{v.Id}' is inconsistent with its referenced physical build multiplicity/installation state.");
            }
            if ((buildA.EcmSuiteRatings.Count > 0 && v.SideAEcmNormalRatingOverride != buildA.EcmSuiteRatings.Max()) ||
                (buildB.EcmSuiteRatings.Count > 0 && v.SideBEcmNormalRatingOverride != buildB.EcmSuiteRatings.Max()) ||
                (buildA.EccmSuiteRatings.Count > 0 && v.SideAEccmNormalRatingOverride != buildA.EccmSuiteRatings.Max()) ||
                (buildB.EccmSuiteRatings.Count > 0 && v.SideBEccmNormalRatingOverride != buildB.EccmSuiteRatings.Max()))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 94 variant '{v.Id}' must expose only the highest installed ECM/ECCM rating; duplicate ratings are never additive.");
            }
            if (v.SideASensorEwProfileId is not ("tl1-balanced-0-control" or "tl2-discrimination-1-candidate") ||
                v.SideBSensorEwProfileId is not ("tl1-balanced-0-control" or "tl2-discrimination-1-candidate"))
            {
                throw new InvalidOperationException($"Checkpoint 94 variant '{v.Id}' uses a sensor profile outside the working envelope.");
            }
            string label = v.ProfileLabel ?? string.Empty;
            if (!label.Contains("source=", StringComparison.Ordinal) ||
                !label.Contains("bundle=", StringComparison.Ordinal) ||
                !label.Contains("orientation=", StringComparison.Ordinal) ||
                !label.Contains("progressionMagnitude=", StringComparison.Ordinal) ||
                !label.Contains("spacePair=", StringComparison.Ordinal) ||
                !label.Contains("familyPair=", StringComparison.Ordinal) ||
                !label.Contains("infoDirection=", StringComparison.Ordinal) ||
                !label.Contains("infoBand=", StringComparison.Ordinal) ||
                !label.Contains("readinessA=", StringComparison.Ordinal) ||
                !label.Contains("readinessB=", StringComparison.Ordinal) ||
                !label.Contains("readyRangeA=", StringComparison.Ordinal) ||
                !label.Contains("readyRangeB=", StringComparison.Ordinal) ||
                !label.Contains("populationCount=", StringComparison.Ordinal) ||
                !label.Contains("populationSampleCount=", StringComparison.Ordinal) ||
                !label.Contains("populationRepresentativeWeight=", StringComparison.Ordinal) ||
                !label.Contains("secondaryKey=", StringComparison.Ordinal) ||
                !label.Contains("geometry=", StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 94 variant '{v.Id}' is missing matched/readiness/Space/population analysis metadata.");
            }
            string source = CrossTlLabelValue(label, "source");
            if (source is not ("named" or "statistical" or "diversity"))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 94 variant '{v.Id}' uses unknown sampling role '{source}'.");
            }
            if (source == "statistical" &&
                (int.Parse(CrossTlLabelValue(label, "populationSampleCount"), CultureInfo.InvariantCulture) <= 0 ||
                 double.Parse(CrossTlLabelValue(label, "populationRepresentativeWeight"), CultureInfo.InvariantCulture) <= 0.0))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 94 statistical variant '{v.Id}' must carry a positive population sample count and representative weight.");
            }
            if (source == "diversity" &&
                (int.Parse(CrossTlLabelValue(label, "populationSampleCount"), CultureInfo.InvariantCulture) != 0 ||
                 Math.Abs(double.Parse(CrossTlLabelValue(label, "populationRepresentativeWeight"), CultureInfo.InvariantCulture)) > 0.000001))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 94 diversity variant '{v.Id}' must carry zero population-inference weight.");
            }
            ValidateCrossTlWeaponProfile(v.Id, "A", v.SideAFamily,
                v.SideAWeaponShieldPenetrationOverride, v.SideAWeaponArmorPenetrationOverride);
            ValidateCrossTlWeaponProfile(v.Id, "B", v.SideBFamily,
                v.SideBWeaponShieldPenetrationOverride, v.SideBWeaponArmorPenetrationOverride);
        }
    }

    private static void ValidateCrossTlWeaponProfile(
        string variantId,
        string side,
        WeaponFamily family,
        int? shieldPenetration,
        int? armorPenetration)
    {
        bool valid = family switch
        {
            WeaponFamily.Kinetic => shieldPenetration == 1 && armorPenetration is 0 or 1,
            WeaponFamily.Energy => shieldPenetration == 1 && armorPenetration == 1,
            WeaponFamily.Missile => shieldPenetration == 1 && armorPenetration == 2,
            _ => false,
        };
        if (!valid)
        {
            throw new InvalidOperationException(
                $"Cross-TL variant '{variantId}' Side {side} uses a penetration profile outside the carried family-specific working envelope.");
        }
    }

    private static void ValidateAdaptiveEngageEncounterCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles,
        LoadedTl1AiDoctrineRegistry? aiDoctrineRegistry)
    {
        if (!IsSingleSourcePolicyTelemetryStudy(study.Id))
        {
            throw new InvalidOperationException(
                "CP97 Engage actual-consumer preflight must classify Adaptive Engage as a single-source policy telemetry study.");
        }

        if (study.MasterSeed != 970100UL || study.TrialsPerVariant != 3000)
        {
            throw new InvalidOperationException(
                "CP97 Engage foundation must preserve its bounded 3,000-trial / seed-970100 study definition.");
        }
        string[] requiredBuildIds =
        {
            "cp97-no-ew",
            "cp97-counter-eccm1",
            "cp97-jammer-ecm2",
            "cp97-jammer-ecm3-diagnostic",
        };
        if (study.Builds.Count != requiredBuildIds.Length ||
            !requiredBuildIds.All(id => study.Builds.Any(build => build.Id == id)))
        {
            throw new InvalidOperationException(
                "CP97 Engage foundation requires the four declared no-EW/ECCM/ECM harness builds.");
        }

        Tl1IntegratedShipBuildDocument noEw = study.Builds.Single(build => build.Id == "cp97-no-ew");
        Tl1IntegratedShipBuildDocument counter = study.Builds.Single(build => build.Id == "cp97-counter-eccm1");
        Tl1IntegratedShipBuildDocument jammer2 = study.Builds.Single(build => build.Id == "cp97-jammer-ecm2");
        Tl1IntegratedShipBuildDocument jammer3 = study.Builds.Single(build => build.Id == "cp97-jammer-ecm3-diagnostic");
        if (noEw.EcmSuite || noEw.EccmSuite || !noEw.ActiveSensor ||
            noEw.EcmSuiteRatings.Count != 0 || noEw.EccmSuiteRatings.Count != 0 ||
            counter.EcmSuite || !counter.EccmSuite || !counter.ActiveSensor ||
            !counter.EccmSuiteRatings.SequenceEqual(new[] { 1 }) ||
            !jammer2.EcmSuite || jammer2.EccmSuite || jammer2.ActiveSensor ||
            !jammer2.EcmSuiteRatings.SequenceEqual(new[] { 2 }) ||
            !jammer3.EcmSuite || jammer3.EccmSuite || jammer3.ActiveSensor ||
            !jammer3.EcmSuiteRatings.SequenceEqual(new[] { 3 }))
        {
            throw new InvalidOperationException(
                "CP97 Engage EW harness builds do not match the declared normal-EW and diagnostic-overload roles.");
        }

        foreach (Tl1IntegratedShipBuildDocument build in study.Builds)
        {
            int usedSpace = 13 + 6 * build.MainWeaponCount +
                6 * build.MainReactorCount + (build.ActiveSensor ? 3 : 0) +
                (build.ShieldGenerator ? 3 : 0) + 2 * build.KineticPdsCount +
                (build.EcmSuite ? 1 : 0) + (build.EccmSuite ? 1 : 0);
            if (build.UsedSpace != usedSpace ||
                build.FreeSupportSpace != 35 - usedSpace)
            {
                throw new InvalidOperationException(
                    $"CP97 Engage harness build '{build.Id}' Space accounting drifted.");
            }
        }

        if (!technologyProfiles.ContainsKey("tl1-production") ||
            !technologyProfiles.ContainsKey("tl2-production") ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1") ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl2"))
        {
            throw new InvalidOperationException(
                "CP97 Engage foundation requires the accepted TL1/TL2 production and no-AUX controls.");
        }

        static bool MatchesSensor(
            SensorEwFoundationProfile p,
            int passiveFirm, int passiveApproximate,
            int activeFirm, int activeApproximate,
            int discriminationResistance) =>
            p.PassiveFirmRange == passiveFirm &&
            p.PassiveApproximateRange == passiveApproximate &&
            p.ActiveFirmRange == activeFirm &&
            p.ActiveApproximateRange == activeApproximate &&
            p.ActivePowerCost == 1 &&
            p.ActiveOverloadAdditionalPowerCost == 1 &&
            p.ActiveOverloadFirmBonus == 1 &&
            p.ActiveOverloadApproximateBonus == 1 &&
            p.DiscriminationResistance == discriminationResistance &&
            p.PointBlankBurnThroughResistance == 1;

        if (!sensorEwProfiles.TryGetValue("cp97-tl1-balanced-0-control", out SensorEwFoundationProfile? tl1Sensor) ||
            tl1Sensor is null ||
            !MatchesSensor(tl1Sensor, 1, 3, 3, 4, 0) ||
            !sensorEwProfiles.TryGetValue("cp97-tl2-dr1-control", out SensorEwFoundationProfile? tl2Sensor) ||
            tl2Sensor is null ||
            !MatchesSensor(tl2Sensor, 1, 3, 3, 4, 1) ||
            !sensorEwProfiles.TryGetValue("cp97-active-overload-probe", out SensorEwFoundationProfile? overloadProbe) ||
            overloadProbe is null ||
            !MatchesSensor(overloadProbe, 1, 4, 3, 4, 0) ||
            !sensorEwProfiles.TryGetValue("cp97-standoff-passive-firm4-control", out SensorEwFoundationProfile? standoffControl) ||
            standoffControl is null ||
            !MatchesSensor(standoffControl, 4, 4, 4, 5, 0))
        {
            throw new InvalidOperationException(
                "CP97 Engage Sensor/EW controls or harness-only overload fixtures drifted from the declared envelopes.");
        }

        if (aiDoctrineRegistry is null)
        {
            throw new InvalidOperationException(
                "CP97 Engage foundation requires the accepted AI doctrine registry.");
        }
        string[] requiredDoctrines =
        {
            "tl1-ew-none-v1",
            "tl1-ew-reactive-eccm-v1",
            "tl1-ew-always-ecm-reactive-eccm-v1",
        };
        if (!requiredDoctrines.All(aiDoctrineRegistry.ById.ContainsKey))
        {
            throw new InvalidOperationException(
                "CP97 Engage foundation is missing a required accepted EW doctrine.");
        }

        if (study.Variants.Any(v =>
                v.MovementMode != Tl1IntegratedMovementMode.EngageAdaptive ||
                v.InitialRangeHexes != 10 ||
                v.TacticalMapRadius != 5 ||
                v.StartingFuel != 100 ||
                v.MovementFuelPerHex != 2 ||
                v.EvasiveManeuverFuelCost != 1 ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideAAllowsApproximateDirectFire || v.SideBAllowsApproximateDirectFire ||
                v.EvasiveManeuversEnabled != false || v.PdsEnabled != false ||
                v.EscapeDisengagementEnabled != false))
        {
            throw new InvalidOperationException(
                "CP97 Engage variants must start at opposite radius-5 edges and delegate search/closure/overload decisions to EngageAdaptive.");
        }

        var groups = study.Variants.GroupBy(v => v.ComparisonGroup, StringComparer.Ordinal).ToArray();
        if (groups.Length != 18 || groups.Any(group =>
                group.Count() != 2 ||
                group.Count(v => v.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst) != 1 ||
                group.Count(v => v.MovementOrder == Tl1IntegratedMovementOrder.SideBFirst) != 1))
        {
            throw new InvalidOperationException(
                "CP97 Engage foundation requires 18 paired lanes mirrored across Side-A-first and Side-B-first movement order.");
        }
        if (study.Variants.Any(v => v.MovementOrder == Tl1IntegratedMovementOrder.Simultaneous))
        {
            throw new InvalidOperationException(
                "CP97 Engage foundation intentionally bounds unresolved initiative with mirrored sequential mover orders.");
        }
        if (!Enum.GetValues<WeaponFamily>().Where(f => f is WeaponFamily.Kinetic or WeaponFamily.Energy or WeaponFamily.Missile)
                .All(f => study.Variants.Any(v => v.SideAFamily == f || v.SideBFamily == f)) ||
            !study.Variants.Any(v => v.SideAProfileId == "tl1-production" && v.SideBProfileId == "tl2-production") ||
            !study.Variants.Any(v => v.SideAProfileId == "tl2-production" && v.SideBProfileId == "tl1-production"))
        {
            throw new InvalidOperationException(
                "CP97 Engage foundation must cover all three weapon families and both TL1->TL2 orientations.");
        }

        Tl1IntegratedTacticalCombatVariantDocument[] eccmProbes = study.Variants
            .Where(v => string.Equals(v.ProfileLabel, "cp97-eccm_overload_probe", StringComparison.Ordinal))
            .ToArray();
        Tl1IntegratedTacticalCombatVariantDocument[] sensorProbes = study.Variants
            .Where(v => string.Equals(v.ProfileLabel, "cp97-active_sensor_overload_probe", StringComparison.Ordinal))
            .ToArray();
        if (eccmProbes.Length != 4 || sensorProbes.Length != 4 ||
            eccmProbes.Any(v => v.SideABuildId != "cp97-jammer-ecm3-diagnostic" &&
                                v.SideBBuildId != "cp97-jammer-ecm3-diagnostic") ||
            sensorProbes.Any(v =>
                v.SideASensorEwProfileId is not ("cp97-active-overload-probe" or "cp97-standoff-passive-firm4-control") ||
                v.SideBSensorEwProfileId is not ("cp97-active-overload-probe" or "cp97-standoff-passive-firm4-control")))
        {
            throw new InvalidOperationException(
                "CP97 Engage diagnostic overload fixtures must remain isolated to their declared four-variant probe lanes.");
        }
        if (study.Variants.Where(v => !string.Equals(v.ProfileLabel, "cp97-eccm_overload_probe", StringComparison.Ordinal))
                .Any(v => v.SideABuildId == "cp97-jammer-ecm3-diagnostic" || v.SideBBuildId == "cp97-jammer-ecm3-diagnostic") ||
            study.Variants.Where(v => !string.Equals(v.ProfileLabel, "cp97-active_sensor_overload_probe", StringComparison.Ordinal))
                .Any(v => v.SideASensorEwProfileId is "cp97-active-overload-probe" or "cp97-standoff-passive-firm4-control" ||
                          v.SideBSensorEwProfileId is "cp97-active-overload-probe" or "cp97-standoff-passive-firm4-control"))
        {
            throw new InvalidOperationException(
                "CP97 harness-only overload fixtures leaked into ordinary evidence lanes.");
        }

        if (study.Variants.Any(v =>
                string.IsNullOrWhiteSpace(v.SideAAiDoctrineId) ||
                string.IsNullOrWhiteSpace(v.SideBAiDoctrineId) ||
                !aiDoctrineRegistry.ById.ContainsKey(v.SideAAiDoctrineId) ||
                !aiDoctrineRegistry.ById.ContainsKey(v.SideBAiDoctrineId)))
        {
            throw new InvalidOperationException(
                "CP97 Engage variants must resolve only accepted AI doctrine IDs.");
        }
    }

    private static void ValidateCrossTlAdaptiveEngageProgressionCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles,
        LoadedTl1AiDoctrineRegistry? aiDoctrineRegistry)
    {
        if (!IsSingleSourcePolicyTelemetryStudy(study.Id))
        {
            throw new InvalidOperationException(
                "CP98 actual-consumer preflight must classify the cross-TL Adaptive Engage screen as a single-source policy telemetry study.");
        }
        if (study.MasterSeed != 980100UL || study.TrialsPerVariant != 250)
        {
            throw new InvalidOperationException(
                "CP98 cross-progression screen must preserve seed 980100 and 250 trials per substantive variant.");
        }
        if (study.Variants.Count != RequiredCrossTlAdaptiveEngageProgressionScreeningVariantCount)
        {
            throw new InvalidOperationException(
                $"CP98 requires exactly {RequiredCrossTlAdaptiveEngageProgressionScreeningVariantCount} generated Adaptive Engage variants.");
        }
        if (study.AiDoctrineCatalog != "docs/archive/ai/pre-cp165-active/ai_doctrine_registry_v0_2.json" ||
            aiDoctrineRegistry is null ||
            !aiDoctrineRegistry.ById.ContainsKey("tl1-ew-preserve-combat-package-v1"))
        {
            throw new InvalidOperationException(
                "CP98 generated screen must bind the accepted AI doctrine registry and preserve-combat-package doctrine.");
        }
        if (!technologyProfiles.ContainsKey("tl1-production") ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1") ||
            !sensorEwProfiles.ContainsKey("tl1-balanced-0-control") ||
            !sensorEwProfiles.ContainsKey("tl2-discrimination-1-candidate"))
        {
            throw new InvalidOperationException(
                "CP98 generated screen is missing a required TL1 baseline, no-AUX, or TL1/TL2 Sensor/EW runtime binding.");
        }
        if (study.Builds.Count == 0 ||
            study.Builds.Select(build => build.Id).Distinct(StringComparer.Ordinal).Count() != study.Builds.Count)
        {
            throw new InvalidOperationException(
                "CP98 requires a non-empty set of unique generated physical build documents.");
        }

        foreach (Tl1IntegratedShipBuildDocument build in study.Builds)
        {
            if (build.MainWeaponCount is < 1 or > 2 ||
                build.MainReactorCount is < 1 or > 2 ||
                (build.MainWeaponCount == 2 && build.MainReactorCount == 2) ||
                build.KineticPdsCount is < 0 or > 1 ||
                build.UsedSpace is < 25 or > 35 ||
                build.FreeSupportSpace != 35 - build.UsedSpace ||
                build.AdvancedComponentCount is null or < 0 ||
                string.IsNullOrWhiteSpace(build.CrossTlCompositionClass))
            {
                throw new InvalidOperationException(
                    $"CP98 physical build '{build.Id}' violates the accepted generalized 35-Space construction contract.");
            }
            if (build.EcmSuite != (build.EcmSuiteRatings.Count > 0) ||
                build.EccmSuite != (build.EccmSuiteRatings.Count > 0) ||
                build.EcmSuiteRatings.Count > 2 || build.EccmSuiteRatings.Count > 2 ||
                build.EcmSuiteRatings.Any(rating => rating is < 1 or > 2) ||
                build.EccmSuiteRatings.Any(rating => rating is < 1 or > 2))
            {
                throw new InvalidOperationException(
                    $"CP98 physical build '{build.Id}' violates non-additive ECM/ECCM multiplicity bounds.");
            }
        }

        var builds = study.Builds.ToDictionary(build => build.Id, StringComparer.Ordinal);
        string[] groups = study.Variants
            .Select(v => v.ComparisonGroup ?? string.Empty)
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        if (groups.Length != 480 || groups.Any(string.IsNullOrWhiteSpace))
        {
            throw new InvalidOperationException(
                $"CP98 requires exactly 480 non-empty logical comparison groups; found {groups.Length}.");
        }
        foreach (string group in groups)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] variants = study.Variants
                .Where(v => v.ComparisonGroup == group)
                .ToArray();
            if (variants.Length != 2 ||
                variants.Count(v => v.MovementMode == Tl1IntegratedMovementMode.EngageAdaptive &&
                    v.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst &&
                    v.InitialRangeHexes == 10) != 1 ||
                variants.Count(v => v.MovementMode == Tl1IntegratedMovementMode.EngageAdaptive &&
                    v.MovementOrder == Tl1IntegratedMovementOrder.SideBFirst &&
                    v.InitialRangeHexes == 10) != 1)
            {
                throw new InvalidOperationException(
                    $"CP98 comparison group '{group}' must contain exactly the mirrored A-first/B-first range-10 Adaptive Engage pair.");
            }
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            if (v.MovementMode != Tl1IntegratedMovementMode.EngageAdaptive ||
                v.InitialRangeHexes != 10 || v.TacticalMapRadius != 5 ||
                v.StartingFuel != 100 || v.MovementFuelPerHex != 2 ||
                v.EvasiveManeuverFuelCost != 1 ||
                v.MovementOrder == Tl1IntegratedMovementOrder.Simultaneous ||
                string.IsNullOrWhiteSpace(v.SideABuildId) || string.IsNullOrWhiteSpace(v.SideBBuildId) ||
                v.SideAProfileId != "tl1-production" || v.SideBProfileId != "tl1-production" ||
                v.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.SideAAiDoctrineId != "tl1-ew-preserve-combat-package-v1" ||
                v.SideBAiDoctrineId != "tl1-ew-preserve-combat-package-v1" ||
                v.SideAReactorOutputOverride is not (5 or 6) ||
                v.SideBReactorOutputOverride is not (5 or 6) ||
                v.SideATacticalComputerTargetingBonusOverride is not (10 or 12) ||
                v.SideBTacticalComputerTargetingBonusOverride is not (10 or 12) ||
                v.SideAShieldCapacityOverride is not (0 or 2 or 3) ||
                v.SideBShieldCapacityOverride is not (0 or 2 or 3) ||
                v.SideAPrimaryArmorProtectionOverride != 0 ||
                v.SideBPrimaryArmorProtectionOverride != 0 ||
                v.SideAPrimaryArmorIntegrityOverride is not (4 or 5) ||
                v.SideBPrimaryArmorIntegrityOverride is not (4 or 5) ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideAAllowsApproximateDirectFire || v.SideBAllowsApproximateDirectFire ||
                !(v.BaseShieldRechargeEnabled ?? false) || !(v.PdsEnabled ?? false) ||
                (v.EvasiveManeuversEnabled ?? true) || (v.EscapeDisengagementEnabled ?? true))
            {
                throw new InvalidOperationException(
                    $"CP98 variant '{v.Id}' drifted from the Adaptive Engage cross-progression consumer contract.");
            }

            if (!builds.TryGetValue(v.SideABuildId!, out Tl1IntegratedShipBuildDocument? buildA) || buildA is null ||
                !builds.TryGetValue(v.SideBBuildId!, out Tl1IntegratedShipBuildDocument? buildB) || buildB is null)
            {
                throw new InvalidOperationException(
                    $"CP98 variant '{v.Id}' references an unknown generated physical build.");
            }
            if ((buildA.MainWeaponCount == 2) != (v.SideASecondaryFamily == v.SideAFamily) ||
                (buildB.MainWeaponCount == 2) != (v.SideBSecondaryFamily == v.SideBFamily) ||
                buildA.ShieldGenerator != (v.SideAShieldCapacityOverride > 0) ||
                buildB.ShieldGenerator != (v.SideBShieldCapacityOverride > 0) ||
                (buildA.EcmSuiteRatings.Count == 0 && v.SideAEcmNormalRatingOverride is not null) ||
                (buildA.EcmSuiteRatings.Count > 0 && v.SideAEcmNormalRatingOverride != buildA.EcmSuiteRatings.Max()) ||
                (buildB.EcmSuiteRatings.Count == 0 && v.SideBEcmNormalRatingOverride is not null) ||
                (buildB.EcmSuiteRatings.Count > 0 && v.SideBEcmNormalRatingOverride != buildB.EcmSuiteRatings.Max()) ||
                (buildA.EccmSuiteRatings.Count == 0 && v.SideAEccmNormalRatingOverride is not null) ||
                (buildA.EccmSuiteRatings.Count > 0 && v.SideAEccmNormalRatingOverride != buildA.EccmSuiteRatings.Max()) ||
                (buildB.EccmSuiteRatings.Count == 0 && v.SideBEccmNormalRatingOverride is not null) ||
                (buildB.EccmSuiteRatings.Count > 0 && v.SideBEccmNormalRatingOverride != buildB.EccmSuiteRatings.Max()))
            {
                throw new InvalidOperationException(
                    $"CP98 variant '{v.Id}' is inconsistent with its physical build or non-additive EW resolution.");
            }
            if (v.SideASensorEwProfileId is not ("tl1-balanced-0-control" or "tl2-discrimination-1-candidate") ||
                v.SideBSensorEwProfileId is not ("tl1-balanced-0-control" or "tl2-discrimination-1-candidate"))
            {
                throw new InvalidOperationException(
                    $"CP98 variant '{v.Id}' uses a Sensor/EW profile outside the accepted working TL1/TL2 envelope.");
            }

            string label = v.ProfileLabel ?? string.Empty;
            string[] requiredLabelKeys =
            {
                "source", "bundle", "orientation", "composition", "progression",
                "distance", "progressionMagnitude", "spacePair", "spaceDelta",
                "spaceAbsDelta", "familyPair", "infoDirection", "infoDistance",
                "infoBand", "readinessA", "readinessB", "readyRangeA", "readyRangeB",
                "populationCell", "populationCount", "populationSampleCount",
                "populationRepresentativeWeight", "secondaryKey", "geometry",
            };
            if (requiredLabelKeys.Any(key => !label.Contains($"{key}=", StringComparison.Ordinal)))
            {
                throw new InvalidOperationException(
                    $"CP98 variant '{v.Id}' is missing carried cross-progression population/readiness metadata.");
            }
            string source = CrossTlLabelValue(label, "source");
            string geometry = CrossTlLabelValue(label, "geometry");
            if (source is not ("named" or "statistical" or "diversity") ||
                geometry is not ("adaptive-a-first" or "adaptive-b-first"))
            {
                throw new InvalidOperationException(
                    $"CP98 variant '{v.Id}' uses an unknown sampling role or adaptive geometry.");
            }
            if (source == "statistical" &&
                (int.Parse(CrossTlLabelValue(label, "populationSampleCount"), CultureInfo.InvariantCulture) <= 0 ||
                 double.Parse(CrossTlLabelValue(label, "populationRepresentativeWeight"), CultureInfo.InvariantCulture) <= 0.0))
            {
                throw new InvalidOperationException(
                    $"CP98 statistical variant '{v.Id}' must carry positive population-inference weight.");
            }
            if (source == "diversity" &&
                (int.Parse(CrossTlLabelValue(label, "populationSampleCount"), CultureInfo.InvariantCulture) != 0 ||
                 Math.Abs(double.Parse(CrossTlLabelValue(label, "populationRepresentativeWeight"), CultureInfo.InvariantCulture)) > 0.000001))
            {
                throw new InvalidOperationException(
                    $"CP98 diversity variant '{v.Id}' must carry zero population-inference weight.");
            }
            ValidateCrossTlWeaponProfile(v.Id, "A", v.SideAFamily,
                v.SideAWeaponShieldPenetrationOverride, v.SideAWeaponArmorPenetrationOverride);
            ValidateCrossTlWeaponProfile(v.Id, "B", v.SideBFamily,
                v.SideBWeaponShieldPenetrationOverride, v.SideBWeaponArmorPenetrationOverride);
        }
    }

    private static void ValidateCrossTlExactEdgeProgressionCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles,
        LoadedTl1AiDoctrineRegistry? aiDoctrineRegistry)
    {
        if (!IsSingleSourcePolicyTelemetryStudy(study.Id))
        {
            throw new InvalidOperationException(
                "CP99 actual-consumer preflight must classify the exact-edge Adaptive Engage screen as a single-source policy telemetry study.");
        }
        if (study.MasterSeed != 990100UL || study.TrialsPerVariant != 250 ||
            study.Variants.Count != RequiredCrossTlExactEdgeProgressionScreeningVariantCount)
        {
            throw new InvalidOperationException(
                $"CP99 exact-edge screen requires seed 990100, 250 trials per variant, and exactly {RequiredCrossTlExactEdgeProgressionScreeningVariantCount} variants.");
        }
        if (study.AiDoctrineCatalog != "docs/archive/ai/pre-cp165-active/ai_doctrine_registry_v0_2.json" ||
            aiDoctrineRegistry is null ||
            !aiDoctrineRegistry.ById.ContainsKey("tl1-ew-preserve-combat-package-v1"))
        {
            throw new InvalidOperationException(
                "CP99 generated screen must bind the accepted AI doctrine registry and preserve-combat-package doctrine.");
        }
        if (!technologyProfiles.ContainsKey("tl1-production") ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1") ||
            !sensorEwProfiles.ContainsKey("tl1-balanced-0-control") ||
            !sensorEwProfiles.ContainsKey("tl2-discrimination-1-candidate"))
        {
            throw new InvalidOperationException(
                "CP99 generated screen is missing a required TL1 baseline, no-AUX, or TL1/TL2 Sensor/EW runtime binding.");
        }
        if (study.Builds.Count == 0 ||
            study.Builds.Select(build => build.Id).Distinct(StringComparer.Ordinal).Count() != study.Builds.Count ||
            study.Builds.Any(build => !build.ActiveSensor || build.MainWeaponCount is < 1 or > 2 ||
                build.MainReactorCount is < 1 or > 2 ||
                (build.MainWeaponCount == 2 && build.MainReactorCount == 2) ||
                build.UsedSpace is < 28 or > 35 || build.FreeSupportSpace != 35 - build.UsedSpace ||
                build.AdvancedComponentCount is null or < 0 || string.IsNullOrWhiteSpace(build.CrossTlCompositionClass)))
        {
            throw new InvalidOperationException(
                "CP99 physical build set must be unique, Sensor-equipped, and remain inside the accepted 35-Space generalized construction envelope.");
        }
        if (study.Builds.Any(build =>
                build.EcmSuite != (build.EcmSuiteRatings.Count > 0) ||
                build.EccmSuite != (build.EccmSuiteRatings.Count > 0) ||
                build.EcmSuiteRatings.Count > 2 || build.EccmSuiteRatings.Count > 2 ||
                build.EcmSuiteRatings.Any(rating => rating is < 1 or > 2) ||
                build.EccmSuiteRatings.Any(rating => rating is < 1 or > 2)))
        {
            throw new InvalidOperationException(
                "CP99 physical builds violate non-additive ECM/ECCM multiplicity bounds.");
        }

        var builds = study.Builds.ToDictionary(build => build.Id, StringComparer.Ordinal);
        var groups = study.Variants.GroupBy(v => v.ComparisonGroup ?? string.Empty, StringComparer.Ordinal).ToArray();
        if (groups.Length != 362 || groups.Any(group => string.IsNullOrWhiteSpace(group.Key) || group.Count() != 2 ||
            group.Count(v => v.MovementMode == Tl1IntegratedMovementMode.EngageAdaptive &&
                v.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst && v.InitialRangeHexes == 10) != 1 ||
            group.Count(v => v.MovementMode == Tl1IntegratedMovementMode.EngageAdaptive &&
                v.MovementOrder == Tl1IntegratedMovementOrder.SideBFirst && v.InitialRangeHexes == 10) != 1))
        {
            throw new InvalidOperationException(
                "CP99 requires exactly 362 exact-edge comparison groups, each mirrored across Side-A-first and Side-B-first range-10 Adaptive Engage geometry.");
        }

        var transitionCounts = new Dictionary<string, int>(StringComparer.Ordinal);
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantDocument> group in groups)
        {
            Tl1IntegratedTacticalCombatVariantDocument first = group.First();
            if (group.Any(v => v.SideABuildId != first.SideABuildId || v.SideBBuildId != first.SideBBuildId ||
                v.ProfileLabel is null || first.ProfileLabel is null ||
                CrossTlLabelValue(v.ProfileLabel, "transition") != CrossTlLabelValue(first.ProfileLabel, "transition") ||
                CrossTlLabelValue(v.ProfileLabel, "expectedAdvancedDelta") != CrossTlLabelValue(first.ProfileLabel, "expectedAdvancedDelta")))
            {
                throw new InvalidOperationException(
                    $"CP99 comparison group '{group.Key}' does not preserve an identical lower/higher exact-edge pair across mover-order mirrors.");
            }
            string transition = CrossTlLabelValue(first.ProfileLabel!, "transition");
            transitionCounts[transition] = transitionCounts.GetValueOrDefault(transition) + 1;
        }
        if (transitionCounts.Count != 12 || transitionCounts.Values.Sum() != 362)
        {
            throw new InvalidOperationException(
                $"CP99 exact-edge screen must cover all 12 progression transition classes across 362 logical pairs; observed {transitionCounts.Count} classes / {transitionCounts.Values.Sum()} pairs.");
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            if (v.MovementMode != Tl1IntegratedMovementMode.EngageAdaptive ||
                v.InitialRangeHexes != 10 || v.TacticalMapRadius != 5 ||
                v.StartingFuel != 100 || v.MovementFuelPerHex != 2 ||
                v.EvasiveManeuverFuelCost != 1 || v.MovementOrder == Tl1IntegratedMovementOrder.Simultaneous ||
                string.IsNullOrWhiteSpace(v.SideABuildId) || string.IsNullOrWhiteSpace(v.SideBBuildId) ||
                v.SideAProfileId != "tl1-production" || v.SideBProfileId != "tl1-production" ||
                v.SideAAuxiliaryProfileId != "aux-r53-none-tl1" || v.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.SideAAiDoctrineId != "tl1-ew-preserve-combat-package-v1" ||
                v.SideBAiDoctrineId != "tl1-ew-preserve-combat-package-v1" ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideAAllowsApproximateDirectFire || v.SideBAllowsApproximateDirectFire ||
                !(v.BaseShieldRechargeEnabled ?? false) || !(v.PdsEnabled ?? false) ||
                (v.EvasiveManeuversEnabled ?? true) || (v.EscapeDisengagementEnabled ?? true))
            {
                throw new InvalidOperationException(
                    $"CP99 variant '{v.Id}' drifted from the exact-edge Adaptive Engage consumer contract.");
            }
            if (!builds.TryGetValue(v.SideABuildId!, out Tl1IntegratedShipBuildDocument? lower) || lower is null ||
                !builds.TryGetValue(v.SideBBuildId!, out Tl1IntegratedShipBuildDocument? higher) || higher is null ||
                !lower.ActiveSensor || !higher.ActiveSensor || lower.UsedSpace != higher.UsedSpace)
            {
                throw new InvalidOperationException(
                    $"CP99 variant '{v.Id}' must reference Sensor-equipped same-Space lower/higher physical builds.");
            }
            string label = v.ProfileLabel ?? string.Empty;
            string[] requiredLabelKeys =
            {
                "source", "transition", "expectedAdvancedDelta", "composition", "progression",
                "distance", "spaceDelta", "familyPair", "readinessA", "readinessB",
                "readyRangeA", "readyRangeB", "geometry",
            };
            if (requiredLabelKeys.Any(key => !label.Contains($"{key}=", StringComparison.Ordinal)) ||
                CrossTlLabelValue(label, "source") != "exact_progression_edge" ||
                CrossTlLabelValue(label, "geometry") is not ("adaptive-a-first" or "adaptive-b-first"))
            {
                throw new InvalidOperationException(
                    $"CP99 variant '{v.Id}' is missing exact-edge/readiness metadata or uses an unknown sampling role/geometry.");
            }
            int expectedDelta = int.Parse(CrossTlLabelValue(label, "expectedAdvancedDelta"), CultureInfo.InvariantCulture);
            if (expectedDelta is not (1 or 2) ||
                higher.AdvancedComponentCount.GetValueOrDefault() - lower.AdvancedComponentCount.GetValueOrDefault() != expectedDelta)
            {
                throw new InvalidOperationException(
                    $"CP99 variant '{v.Id}' does not preserve the declared exact-edge advanced-component delta.");
            }
            if (v.SideASensorEwProfileId is not ("tl1-balanced-0-control" or "tl2-discrimination-1-candidate") ||
                v.SideBSensorEwProfileId is not ("tl1-balanced-0-control" or "tl2-discrimination-1-candidate"))
            {
                throw new InvalidOperationException(
                    $"CP99 variant '{v.Id}' uses a Sensor/EW profile outside the accepted working TL1/TL2 envelope.");
            }
            ValidateCrossTlWeaponProfile(v.Id, "A", v.SideAFamily,
                v.SideAWeaponShieldPenetrationOverride, v.SideAWeaponArmorPenetrationOverride);
            ValidateCrossTlWeaponProfile(v.Id, "B", v.SideBFamily,
                v.SideBWeaponShieldPenetrationOverride, v.SideBWeaponArmorPenetrationOverride);
        }
    }

    private static void ValidateTl3Cp102TransitionSmokeCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles,
        LoadedTl1AiDoctrineRegistry? aiDoctrineRegistry)
    {
        if (!IsAdaptiveEncounterStudy(study.Id) ||
            !IsSingleSourcePolicyTelemetryStudy(study.Id) ||
            !IsStatefulAuxiliaryStudy(study.Id))
        {
            throw new InvalidOperationException(
                "CP102 transition smoke must be registered for Adaptive Engage, single-source policy telemetry, and stateful build-level auxiliary/power handling.");
        }
        if (study.MasterSeed != 1020200UL || study.TrialsPerVariant != 1 ||
            study.Variants.Count != RequiredTl3Cp102TransitionSmokeVariantCount)
        {
            throw new InvalidOperationException(
                $"CP102 transition smoke requires seed 1020200, one trial per variant, and exactly {RequiredTl3Cp102TransitionSmokeVariantCount} variants.");
        }
        if (study.TechnologyProfileCatalog !=
                "src/StarCluster.ScenarioRunner/Scenarios/ArchitectureTechnology/tl1-tl3-standard-runtime-profiles-v0_4.json" ||
            study.AuxiliaryProfileCatalog !=
                "src/StarCluster.ScenarioRunner/Scenarios/ArchitectureTechnology/tl1-tl2-auxiliary-runtime-profiles-v0_3.json" ||
            study.SensorEwProfileCatalog !=
                "src/StarCluster.ScenarioRunner/Scenarios/SensorEw/tl2-sew01-sensor-discrimination-isolation.json" ||
            study.AiDoctrineCatalog != "docs/archive/ai/pre-cp165-active/ai_doctrine_registry_v0_2.json")
        {
            throw new InvalidOperationException(
                "CP102 generated transition smoke drifted from its accepted runtime-profile, auxiliary, Sensor/EW, or AI-doctrine bindings.");
        }
        if (!technologyProfiles.ContainsKey("tl2-cp102-integration-reference") ||
            !technologyProfiles.ContainsKey("tl3-cp102-executable-candidate") ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1") ||
            !sensorEwProfiles.ContainsKey("tl2-discrimination-1-candidate") ||
            aiDoctrineRegistry is null ||
            !aiDoctrineRegistry.ById.ContainsKey("tl1-ew-preserve-combat-package-v1"))
        {
            throw new InvalidOperationException(
                "CP102 generated transition smoke is missing a required TL2/TL3 runtime, no-AUX, Sensor/EW, or AI-doctrine binding.");
        }
        if (study.Builds.Count != 22 ||
            study.Builds.Select(build => build.Id).Distinct(StringComparer.Ordinal).Count() != study.Builds.Count ||
            study.Builds.Any(build => build.MainWeaponCount != 1 || build.MainReactorCount != 1 ||
                !build.ActiveSensor || !build.ShieldGenerator || build.UsedSpace is < 33 or > 35 ||
                build.FreeSupportSpace < 0 || build.UsedSpace + build.FreeSupportSpace is < 35 or > 36))
        {
            throw new InvalidOperationException(
                "CP102 generated transition smoke must contain 22 unique legal one-main/one-reactor Sensor-equipped named builds inside the 35/36-Space envelope.");
        }

        string[] expectedTransitions =
        {
            "hull-h2-to-h3",
            "computer-c2-to-c3",
            "sensor-s2-to-s3",
            "ecm-ecm2-to-ecm3",
            "eccm-eccm2-to-eccm3",
            "reactor-r2-to-r3",
            "stl-stl2-to-stl3",
            "ftl-ftl2-to-ftl3",
            "shield-sh2-to-tl3-hardener-unlock",
            "armor-a2-to-a3",
            "weapon-k2-to-k3",
            "weapon-e2-to-e3",
            "weapon-m2-to-m3",
            "pds-k2-to-k3",
            "pds-e2-to-e3",
            "pds-amm2-to-amm3",
        };
        IGrouping<string, Tl1IntegratedTacticalCombatVariantDocument>[] groups = study.Variants
            .GroupBy(variant => variant.ComparisonGroup ?? string.Empty, StringComparer.Ordinal)
            .ToArray();
        if (groups.Length != 16 || groups.Any(group => string.IsNullOrWhiteSpace(group.Key) ||
                group.Count() != 2 ||
                group.Count(variant => variant.MovementMode == Tl1IntegratedMovementMode.EngageAdaptive &&
                    variant.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst &&
                    variant.InitialRangeHexes == 10 && variant.TacticalMapRadius == 5) != 1 ||
                group.Count(variant => variant.MovementMode == Tl1IntegratedMovementMode.EngageAdaptive &&
                    variant.MovementOrder == Tl1IntegratedMovementOrder.SideBFirst &&
                    variant.InitialRangeHexes == 10 && variant.TacticalMapRadius == 5) != 1))
        {
            throw new InvalidOperationException(
                "CP102 generated transition smoke requires exactly 16 comparison groups mirrored across Side-A-first and Side-B-first range-10 Adaptive Engage geometry.");
        }

        var builds = study.Builds.ToDictionary(build => build.Id, StringComparer.Ordinal);
        var observedTransitions = new HashSet<string>(StringComparer.Ordinal);
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantDocument> group in groups)
        {
            Tl1IntegratedTacticalCombatVariantDocument first = group.First();
            string transition = CrossTlLabelValue(first.ProfileLabel ?? string.Empty, "transition");
            if (string.IsNullOrWhiteSpace(transition) || !observedTransitions.Add(transition) ||
                group.Any(variant => variant.SideABuildId != first.SideABuildId ||
                    variant.SideBBuildId != first.SideBBuildId ||
                    CrossTlLabelValue(variant.ProfileLabel ?? string.Empty, "transition") != transition ||
                    CrossTlLabelValue(variant.ProfileLabel ?? string.Empty, "source") != "named" ||
                    CrossTlLabelValue(variant.ProfileLabel ?? string.Empty, "geometry") is not
                        ("adaptive-a-first" or "adaptive-b-first")))
            {
                throw new InvalidOperationException(
                    $"CP102 comparison group '{group.Key}' does not preserve one named transition pair across the two mover-order geometries.");
            }
            if (string.IsNullOrWhiteSpace(first.SideABuildId) || string.IsNullOrWhiteSpace(first.SideBBuildId) ||
                !builds.TryGetValue(first.SideABuildId, out Tl1IntegratedShipBuildDocument? lower) || lower is null ||
                !builds.TryGetValue(first.SideBBuildId, out Tl1IntegratedShipBuildDocument? higher) || higher is null ||
                string.Equals(lower.Id, higher.Id, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    $"CP102 comparison group '{group.Key}' must reference distinct lower/higher generated build endpoints.");
            }
            foreach (Tl1IntegratedTacticalCombatVariantDocument variant in group)
            {
                if (variant.SideAProfileId != "tl2-cp102-integration-reference" ||
                    variant.SideBProfileId != "tl3-cp102-executable-candidate" ||
                    variant.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                    variant.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                    variant.SideAAiDoctrineId != "tl1-ew-preserve-combat-package-v1" ||
                    variant.SideBAiDoctrineId != "tl1-ew-preserve-combat-package-v1" ||
                    variant.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                    variant.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                    variant.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                    variant.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                    variant.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                    variant.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                    variant.StartingFuel != 100 || variant.MovementFuelPerHex != 2 ||
                    variant.EvasiveManeuverFuelCost != 1 ||
                    variant.BaseShieldRechargeEnabled != true || variant.PdsEnabled != true ||
                    variant.EvasiveManeuversEnabled != false || variant.EscapeDisengagementEnabled != false ||
                    variant.SideAAllowsApproximateDirectFire || variant.SideBAllowsApproximateDirectFire)
                {
                    throw new InvalidOperationException(
                        $"CP102 variant '{variant.Id}' drifted from the bounded generated actual-consumer smoke contract.");
                }
                ValidateCrossTlWeaponProfile(variant.Id, "A", variant.SideAFamily,
                    variant.SideAWeaponShieldPenetrationOverride, variant.SideAWeaponArmorPenetrationOverride);
                ValidateCrossTlWeaponProfile(variant.Id, "B", variant.SideBFamily,
                    variant.SideBWeaponShieldPenetrationOverride, variant.SideBWeaponArmorPenetrationOverride);
            }
        }
        if (!expectedTransitions.OrderBy(id => id, StringComparer.Ordinal)
                .SequenceEqual(observedTransitions.OrderBy(id => id, StringComparer.Ordinal), StringComparer.Ordinal))
        {
            throw new InvalidOperationException(
                $"CP102 transition smoke must cover exactly the 16 registered TL2->TL3 transitions; observed {observedTransitions.Count} unique transitions.");
        }

        (int zeroSpent, int zeroSpendable) = SpendAttackPowerForSelfTest(6, 0);
        (int oneSpent, int oneSpendable) = SpendAttackPowerForSelfTest(6, 1);
        if (zeroSpent != 0 || zeroSpendable != 6 || oneSpent != 1 || oneSpendable != 5)
        {
            throw new InvalidOperationException(
                "CP102 zero-cost ordinary weapon fire must consume no Tactical Power while positive-cost fire must retain ordinary ledger semantics.");
        }

        bool runtimeSurfaceComplete =
            study.Builds.Any(build => build.UsedSpace + build.FreeSupportSpace == 36) &&
            study.Builds.Any(build => build.Id.Contains("_r-r3_", StringComparison.Ordinal) &&
                build.UsedSpace == 34 && build.FreeSupportSpace == 1) &&
            study.Builds.Any(build => build.TacticalComputerEvasiveCompensation == 5) &&
            study.Variants.Any(variant => variant.SideBSensorActiveHighFirmRangeOverride == 4 &&
                variant.SideBSensorActiveHighApproximateRangeOverride == 5 &&
                variant.SideBSensorActiveHighPowerCostOverride == 2) &&
            study.Variants.Any(variant => variant.SideBEcmFullStrengthNormalPowerCostOverride == 1) &&
            study.Variants.Any(variant => variant.SideBEccmFullStrengthNormalPowerCostOverride == 1) &&
            study.Variants.Any(variant => variant.SideBStlMovementHexes == 3) &&
            study.Builds.Any(build => build.FtlStrategicMove == 3) &&
            study.Builds.Any(build => build.ShieldHardener && build.ShieldHardenerArmor == 1 &&
                build.ShieldHardenerPowerCost == 1) &&
            study.Variants.Any(variant => variant.SideBPrimaryArmorProtectionOverride == 1 &&
                variant.SideBPrimaryArmorIntegrityOverride == 5) &&
            study.Variants.Any(variant => variant.SideBFamily == WeaponFamily.Kinetic &&
                variant.SideBPrimaryWeaponPowerCostOverride == 0) &&
            study.Variants.Any(variant => variant.SideBFamily == WeaponFamily.Energy &&
                variant.SideBPrimaryWeaponDamageOverride == 4 &&
                variant.SideBPrimaryWeaponPowerCostOverride == 3) &&
            study.Variants.Any(variant => variant.SideBFamily == WeaponFamily.Missile &&
                variant.SideBMissileSpeedHexesPerTurnOverride == 4) &&
            study.Builds.Any(build => build.StandardOnboardMissileNavigationSensor) &&
            study.Builds.Any(build => build.Id.Contains("_p-kpds3", StringComparison.Ordinal) &&
                build.PdsFamily == "Kinetic" && build.PdsPowerCost == 1 &&
                build.PdsReactionCapacity == 1 && build.PdsAmmunition == 60) &&
            study.Builds.Any(build => build.Id.Contains("_p-epds3", StringComparison.Ordinal) &&
                build.PdsFamily == "Energy" && build.PdsPowerCost == 1 &&
                build.PdsReactionCapacity == 1 && build.PdsAmmunition is null) &&
            study.Builds.Any(build => build.Id.Contains("_p-ammpds3", StringComparison.Ordinal) &&
                build.PdsFamily == "AMM" && build.PdsPowerCost == 2 &&
                build.PdsReactionCapacity == 2 && build.PdsFallbackPowerCost == 1 &&
                build.PdsFallbackReactionCapacity == 1 && build.PdsAmmunition == 25);
        if (!runtimeSurfaceComplete)
        {
            throw new InvalidOperationException(
                "CP102 generated transition smoke did not carry every required TL3 executable field through the actual integrated-combat document surface.");
        }
    }

    private static void ValidateTl2ShieldCapacityPowerIntegrationCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (study.Variants.Count != RequiredTl2ShieldCapacityPowerIntegrationVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 84 requires exactly {RequiredTl2ShieldCapacityPowerIntegrationVariantCount} Shield-capacity/Power permutations.");
        }
        if (study.TechnologyProfileCatalog is not null ||
            study.SensorEwProfileCatalog !=
                "src/StarCluster.ScenarioRunner/Scenarios/SensorEw/tl2-sew01-sensor-discrimination-isolation.json")
        {
            throw new InvalidOperationException(
                "Checkpoint 84 must retain the TL1 combat profile and reuse the accepted DR0/DR1 Sensor/EW catalog.");
        }
        if (study.Builds.Count != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 84 requires exactly one fixed 35-Space EW-capable combat fixture.");
        }
        Tl1IntegratedShipBuildDocument build = study.Builds.Single();
        if (build.Id != "balanced_generalist_ew_major" ||
            build.MainWeaponCount != 1 || build.MainReactorCount != 1 ||
            !build.ActiveSensor || !build.ShieldGenerator ||
            build.KineticPdsCount != 1 || !build.EcmSuite || !build.EccmSuite ||
            build.UsedSpace != 35 || build.FreeSupportSpace != 0)
        {
            throw new InvalidOperationException(
                "Checkpoint 84 fixed combat fixture drifted from the accepted 35-Space EW major build.");
        }
        if (!technologyProfiles.TryGetValue("tl1-production", out TechnologyCombatProfile? tl1) ||
            tl1 is null || tl1.ShieldCapacity != 2 || tl1.ShieldBaseRecharge != 1 ||
            tl1.ShieldArmor != 0 || tl1.ReactorOutput != 5)
        {
            throw new InvalidOperationException(
                "Checkpoint 84 requires the accepted TL1 Shield 2/Base Recharge 1/Reactor 5 production reference.");
        }
        if (sensorEwProfiles.Count != 2 ||
            !sensorEwProfiles.TryGetValue("tl1-balanced-0-control", out SensorEwFoundationProfile? tl1Sensor) ||
            !sensorEwProfiles.TryGetValue("tl2-discrimination-1-candidate", out SensorEwFoundationProfile? tl2Sensor) ||
            tl1Sensor.DiscriminationResistance != 0 ||
            tl2Sensor.DiscriminationResistance != 1 ||
            tl1Sensor.PassiveFirmRange != tl2Sensor.PassiveFirmRange ||
            tl1Sensor.PassiveApproximateRange != tl2Sensor.PassiveApproximateRange ||
            tl1Sensor.ActiveFirmRange != tl2Sensor.ActiveFirmRange ||
            tl1Sensor.ActiveApproximateRange != tl2Sensor.ActiveApproximateRange ||
            tl1Sensor.ActivePowerCost != tl2Sensor.ActivePowerCost)
        {
            throw new InvalidOperationException(
                "Checkpoint 84 must preserve the accepted DR0/DR1 Sensor isolation while holding physical reach and Active power constant.");
        }

        string[] groups =
        {
            "c84-kvk-r3", "c84-kvk-afirst", "c84-kvk-bfirst",
            "c84-kve-r3", "c84-kve-afirst", "c84-kve-bfirst",
            "c84-kvm-r3", "c84-kvm-afirst", "c84-kvm-bfirst",
            "c84-evk-r3", "c84-evk-afirst", "c84-evk-bfirst",
            "c84-eve-r3", "c84-eve-afirst", "c84-eve-bfirst",
            "c84-evm-r3", "c84-evm-afirst", "c84-evm-bfirst",
        };
        string[] environments = { "firm-reference", "tall-dr1-eccm1" };
        int[] shields = { 2, 3, 4 };
        int[] reactors = { 5, 6 };
        foreach (string group in groups)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants
                .Where(v => string.Equals(v.ComparisonGroup, group, StringComparison.Ordinal))
                .ToArray();
            if (context.Length != environments.Length * shields.Length * reactors.Length)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 84 context '{group}' must contain exactly twelve environment/shield/reactor permutations.");
            }
            foreach (string environment in environments)
            foreach (int shield in shields)
            foreach (int reactor in reactors)
            {
                string label = $"{environment}-s{shield}-r{reactor}";
                if (context.Count(v => string.Equals(v.ProfileLabel, label, StringComparison.Ordinal)) != 1)
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 84 context '{group}' is missing unique permutation '{label}'.");
                }
            }
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument variant in study.Variants)
        {
            string label = variant.ProfileLabel ?? string.Empty;
            bool tall = label.StartsWith("tall-dr1-eccm1-", StringComparison.Ordinal);
            bool firm = label.StartsWith("firm-reference-", StringComparison.Ordinal);
            string expectedSensor = tall
                ? "tl2-discrimination-1-candidate"
                : "tl1-balanced-0-control";
            if ((!tall && !firm) ||
                variant.SideAProfileId != "tl1-production" ||
                variant.SideBProfileId != "tl1-production" ||
                variant.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                variant.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                variant.SideASensorEwProfileId != expectedSensor ||
                variant.SideBSensorEwProfileId != "tl1-balanced-0-control" ||
                variant.SideAShieldCapacityOverride is not (2 or 3 or 4) ||
                variant.SideBShieldCapacityOverride != 2 ||
                variant.SideAReactorOutputOverride is not (5 or 6) ||
                variant.SideBReactorOutputOverride != 5 ||
                variant.SideATacticalComputerTargetingBonusOverride != 12 ||
                variant.SideBTacticalComputerTargetingBonusOverride != 10 ||
                variant.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                variant.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                variant.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                variant.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                variant.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                variant.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                variant.BaseShieldRechargeEnabled != true || variant.PdsEnabled != true ||
                variant.EvasiveManeuversEnabled != false || variant.StartingFuel != 100 ||
                variant.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                variant.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                variant.SideAEcmNormalPowerCostOverride != 1 ||
                variant.SideBEcmNormalPowerCostOverride != 1 ||
                variant.SideAEccmNormalPowerCostOverride != 1 ||
                variant.SideBEccmNormalPowerCostOverride != 1 ||
                variant.SideAAllowsApproximateDirectFire ||
                variant.SideBAllowsApproximateDirectFire ||
                variant.SideAApproximateDirectFireAccuracyPenalty != 0 ||
                variant.SideBApproximateDirectFireAccuracyPenalty != 0)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 84 variant '{variant.Id}' drifted from the isolated Shield-capacity/Power fixture.");
            }
            if (firm && (variant.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideAEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                    variant.SideBEcmNormalRatingOverride != 1 ||
                    variant.SideAEccmNormalRatingOverride != 1))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 84 Firm-reference variant '{variant.Id}' is EW-contaminated.");
            }
            if (tall && (variant.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.Normal ||
                    variant.SideAEccmPolicy != Tl1IntegratedEwPowerPolicy.ReactiveNormal ||
                    variant.SideBEcmNormalRatingOverride != 2 ||
                    variant.SideAEccmNormalRatingOverride != 1))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 84 tall variant '{variant.Id}' must use ECM2 vs DR1 + reactive ECCM1.");
            }
        }
    }

    private static void ValidateTl2PowerReactorProgressionPermutationCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles)
    {
        if (study.Variants.Count != RequiredTl2PowerReactorProgressionPermutationVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 83 requires exactly {RequiredTl2PowerReactorProgressionPermutationVariantCount} Power/Reactor permutation variants.");
        }
        if (study.TechnologyProfileCatalog is not null ||
            study.SensorEwProfileCatalog !=
                "src/StarCluster.ScenarioRunner/Scenarios/SensorEw/tl2-sew01-sensor-discrimination-isolation.json")
        {
            throw new InvalidOperationException(
                "Checkpoint 83 must retain the TL1 combat profile and reuse the accepted DR0/DR1 Sensor/EW candidate catalog.");
        }
        if (study.Builds.Count != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 83 requires exactly one fixed 35-Space EW-capable combat fixture.");
        }
        Tl1IntegratedShipBuildDocument build = study.Builds.Single();
        if (build.Id != "balanced_generalist_ew_major" ||
            build.MainWeaponCount != 1 || build.MainReactorCount != 1 ||
            !build.ActiveSensor || !build.ShieldGenerator ||
            build.KineticPdsCount != 1 || !build.EcmSuite || !build.EccmSuite ||
            build.UsedSpace != 35 || build.FreeSupportSpace != 0)
        {
            throw new InvalidOperationException(
                "Checkpoint 83 fixed combat fixture drifted from the accepted 35-Space EW major build.");
        }
        if (sensorEwProfiles.Count != 2 ||
            !sensorEwProfiles.TryGetValue("tl1-balanced-0-control", out SensorEwFoundationProfile? tl1Sensor) ||
            !sensorEwProfiles.TryGetValue("tl2-discrimination-1-candidate", out SensorEwFoundationProfile? tl2Sensor) ||
            tl1Sensor.DiscriminationResistance != 0 ||
            tl2Sensor.DiscriminationResistance != 1 ||
            tl1Sensor.PassiveFirmRange != tl2Sensor.PassiveFirmRange ||
            tl1Sensor.PassiveApproximateRange != tl2Sensor.PassiveApproximateRange ||
            tl1Sensor.ActiveFirmRange != tl2Sensor.ActiveFirmRange ||
            tl1Sensor.ActiveApproximateRange != tl2Sensor.ActiveApproximateRange ||
            tl1Sensor.ActivePowerCost != tl2Sensor.ActivePowerCost ||
            tl1Sensor.PointBlankBurnThroughResistance != tl2Sensor.PointBlankBurnThroughResistance)
        {
            throw new InvalidOperationException(
                "Checkpoint 83 must preserve the accepted DR0/DR1 Sensor isolation while holding reach, Active power, and burn-through constant.");
        }

        string[] groups =
        {
            "c83-kvm-r3", "c83-kvm-afirst", "c83-kvm-bfirst",
            "c83-kvk-r3", "c83-kvk-afirst", "c83-kvk-bfirst",
            "c83-evm-r3", "c83-evm-afirst", "c83-evm-bfirst",
            "c83-evk-r3", "c83-evk-afirst", "c83-evk-bfirst",
        };
        string[] packages =
        {
            "firm-reference",
            "wide-eccm2",
            "tall-dr1-eccm1",
            "degraded-p25",
        };
        string[] reactors = { "r5", "r6" };
        foreach (string group in groups)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] context = study.Variants
                .Where(v => string.Equals(v.ComparisonGroup, group, StringComparison.Ordinal))
                .ToArray();
            if (context.Length != packages.Length * reactors.Length)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 83 context '{group}' must contain exactly eight package/reactor permutations.");
            }
            foreach (string package in packages)
            {
                foreach (string reactor in reactors)
                {
                    string label = $"{package}-{reactor}";
                    if (context.Count(v => string.Equals(v.ProfileLabel, label, StringComparison.Ordinal)) != 1)
                    {
                        throw new InvalidOperationException(
                            $"Checkpoint 83 context '{group}' is missing unique permutation '{label}'.");
                    }
                }
            }

            bool energy = group.StartsWith("c83-ev", StringComparison.Ordinal);
            bool missileOpponent = group.Contains("vm-", StringComparison.Ordinal);
            WeaponFamily expectedA = energy ? WeaponFamily.Energy : WeaponFamily.Kinetic;
            WeaponFamily expectedB = missileOpponent ? WeaponFamily.Missile : WeaponFamily.Kinetic;
            bool fixedRange = group.EndsWith("-r3", StringComparison.Ordinal);
            Tl1IntegratedMovementOrder expectedOrder = group.EndsWith("-afirst", StringComparison.Ordinal)
                ? Tl1IntegratedMovementOrder.SideAFirst
                : group.EndsWith("-bfirst", StringComparison.Ordinal)
                    ? Tl1IntegratedMovementOrder.SideBFirst
                    : Tl1IntegratedMovementOrder.Simultaneous;
            if (context.Any(v =>
                    v.SideAFamily != expectedA || v.SideBFamily != expectedB ||
                    v.SideASecondaryFamily is not null || v.SideBSecondaryFamily is not null ||
                    v.InitialRangeHexes != (fixedRange ? 3 : 4) ||
                    v.MovementMode != (fixedRange
                        ? Tl1IntegratedMovementMode.HoldRange3
                        : Tl1IntegratedMovementMode.TrackAwareOpponentRange) ||
                    v.MovementOrder != expectedOrder))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 83 context '{group}' has a family, geometry, or movement-order mismatch.");
            }
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument variant in study.Variants)
        {
            if (variant.SideAProfileId != "tl1-production" ||
                variant.SideBProfileId != "tl1-production" ||
                variant.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                variant.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                variant.SensorEwProfileId is not null ||
                variant.SideBSensorEwProfileId != "tl1-balanced-0-control" ||
                variant.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                variant.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                variant.SideANetEwRangePenalty != 0 || variant.SideBNetEwRangePenalty != 0 ||
                variant.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                variant.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                variant.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                (variant.SideAReactorOutputOverride != 5 && variant.SideAReactorOutputOverride != 6) ||
                variant.SideBReactorOutputOverride != 5 ||
                variant.SideATacticalComputerTargetingBonusOverride != 12 ||
                variant.SideBTacticalComputerTargetingBonusOverride != 10 ||
                variant.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                variant.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                variant.PdsEnabled != true || variant.StartingFuel != 100 ||
                variant.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                variant.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                variant.SideAEcmNormalPowerCostOverride != 1 ||
                variant.SideBEcmNormalPowerCostOverride != 1 ||
                variant.SideAEccmNormalPowerCostOverride != 1 ||
                variant.SideBEccmNormalPowerCostOverride != 1 ||
                variant.SideAEcmNormalRatingOverride != 1 ||
                variant.SideBEccmNormalRatingOverride != 1 ||
                variant.SideBAllowsApproximateDirectFire ||
                variant.SideBApproximateDirectFireAccuracyPenalty != 0 ||
                !string.IsNullOrWhiteSpace(variant.SideAAiDoctrineId) ||
                !string.IsNullOrWhiteSpace(variant.SideBAiDoctrineId))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 83 variant '{variant.Id}' drifted from the frozen combat/information-control fixture.");
            }

            string label = variant.ProfileLabel ?? string.Empty;
            bool reactor6 = label.EndsWith("-r6", StringComparison.Ordinal);
            string package = label.EndsWith("-r5", StringComparison.Ordinal) ||
                    label.EndsWith("-r6", StringComparison.Ordinal)
                ? label[..^3]
                : string.Empty;
            bool tall = package == "tall-dr1-eccm1";
            bool wide = package == "wide-eccm2";
            bool degraded = package == "degraded-p25";
            bool firmReference = package == "firm-reference";
            string expectedSensor = tall
                ? "tl2-discrimination-1-candidate"
                : "tl1-balanced-0-control";
            Tl1IntegratedEwPowerPolicy expectedEcm = firmReference
                ? Tl1IntegratedEwPowerPolicy.None
                : Tl1IntegratedEwPowerPolicy.Normal;
            Tl1IntegratedEwPowerPolicy expectedEccm = wide || tall
                ? Tl1IntegratedEwPowerPolicy.ReactiveNormal
                : Tl1IntegratedEwPowerPolicy.None;
            int expectedEccmRating = wide ? 2 : 1;
            if (variant.SideAReactorOutputOverride != (reactor6 ? 6 : 5) ||
                variant.SideASensorEwProfileId != expectedSensor ||
                variant.SideBEcmPolicy != expectedEcm ||
                variant.SideBEcmNormalRatingOverride != (firmReference ? 1 : 2) ||
                variant.SideAEccmPolicy != expectedEccm ||
                variant.SideAEccmNormalRatingOverride != expectedEccmRating ||
                variant.SideAAllowsApproximateDirectFire != degraded ||
                variant.SideAApproximateDirectFireAccuracyPenalty != (degraded ? 25 : 0))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 83 permutation '{variant.Id}' does not match its Power/Sensor/EW/degraded-fire definition.");
            }
        }

        _ = technologyProfiles;
        _ = auxiliaryProfiles;
    }

    private static void ValidateTl1EwAiDoctrineCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        IReadOnlyDictionary<string, SensorEwFoundationProfile> sensorEwProfiles,
        LoadedTl1AiDoctrineRegistry? aiDoctrineRegistry)
    {
        if (study.Variants.Count != RequiredTl1EwAiDoctrineVariantCount)
        {
            throw new InvalidOperationException(
                $"Checkpoint 73 requires exactly {RequiredTl1EwAiDoctrineVariantCount} AI-doctrine variants.");
        }
        if (aiDoctrineRegistry is null ||
            study.AiDoctrineCatalog != "docs/archive/ai/pre-cp165-active/ai_doctrine_registry_v0_1.json")
        {
            throw new InvalidOperationException(
                "Checkpoint 73 requires the authoritative AI doctrine registry v0.1.");
        }
        Tl1AiDoctrineRegistryDocument registry = aiDoctrineRegistry.Document;
        if (registry.RegistryVersion != "0.1" ||
            registry.Dependencies.Select(d => d.Id).Distinct(StringComparer.Ordinal).Count() !=
                registry.Dependencies.Count ||
            registry.Doctrines.Select(d => d.Id).Distinct(StringComparer.Ordinal).Count() !=
                registry.Doctrines.Count ||
            registry.Evidence.Select(e => e.Id).Distinct(StringComparer.Ordinal).Count() !=
                registry.Evidence.Count)
        {
            throw new InvalidOperationException(
                "Checkpoint 73 AI doctrine registry identity or uniqueness contract failed.");
        }
        var dependencyIds = registry.Dependencies.Select(d => d.Id)
            .ToHashSet(StringComparer.Ordinal);
        if (registry.Doctrines.Any(d => d.InformationPolicy.UsesHiddenEnemyRatings ||
                d.Dependencies.Any(dep => !dependencyIds.Contains(dep))))
        {
            throw new InvalidOperationException(
                "Checkpoint 73 doctrines may not use hidden enemy ratings and all dependencies must be registered.");
        }
        Tl1AiDoctrineDefinitionDocument acceptedReactive = ResolveAiDoctrine(
            aiDoctrineRegistry, "tl1-ew-reactive-eccm-v1", "registry", "accepted");
        if (acceptedReactive.Status != "accepted" ||
            acceptedReactive.AcceptedCheckpoint != "72" ||
            acceptedReactive.EcmHeuristic != EcmActivationHeuristic.Never ||
            acceptedReactive.EccmHeuristic != EccmActivationHeuristic.ReactiveOnFirmDegradation ||
            !acceptedReactive.EvidenceIds.Contains("cp72-reactive-eccm-accepted", StringComparer.Ordinal))
        {
            throw new InvalidOperationException(
                "Checkpoint 73 must preserve CP72 reactive ECCM as accepted doctrine evidence.");
        }
        Tl1AiDoctrineEvidenceDocument cp72Evidence = registry.Evidence.SingleOrDefault(e =>
            e.Id == "cp72-reactive-eccm-accepted") ??
            throw new InvalidOperationException(
                "Checkpoint 73 registry is missing CP72 reactive ECCM evidence.");
        if (cp72Evidence.Checkpoint != "72" ||
            cp72Evidence.StudyId != Tl1ReactiveEwSubphaseStudyId ||
            cp72Evidence.Status != "accepted" ||
            cp72Evidence.ResultSha256 !=
                "cb30e4d3800a0474aaed0447390cd18542962915676cd710bd28db23b5cc4f04")
        {
            throw new InvalidOperationException(
                "Checkpoint 73 CP72 doctrine evidence provenance drifted.");
        }

        string[] studyDoctrineIds =
        {
            "tl1-ew-none-v1",
            "tl1-ew-always-ecm-reactive-eccm-v1",
            "tl1-ew-preserve-offense-v1",
            "tl1-ew-preserve-combat-package-v1",
        };
        foreach (string id in studyDoctrineIds)
        {
            if (!aiDoctrineRegistry.ById.ContainsKey(id) ||
                study.Variants.Count(v => v.SideAAiDoctrineId == id &&
                    v.SideBAiDoctrineId == id) != 6)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 73 doctrine '{id}' must exist and occupy exactly six paired contexts.");
            }
        }
        if (ResolveAiDoctrine(aiDoctrineRegistry,
                "tl1-ew-always-ecm-reactive-eccm-v1", "registry", "candidate").Status != "experimental" ||
            ResolveAiDoctrine(aiDoctrineRegistry,
                "tl1-ew-preserve-offense-v1", "registry", "candidate").Status != "experimental" ||
            ResolveAiDoctrine(aiDoctrineRegistry,
                "tl1-ew-preserve-combat-package-v1", "registry", "candidate").Status != "experimental")
        {
            throw new InvalidOperationException(
                "Checkpoint 73 ECM doctrines must remain experimental until native results are reviewed.");
        }

        if (study.Builds.Count != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 73 requires exactly one fixed EW-capable combat fixture.");
        }
        Tl1IntegratedShipBuildDocument build = study.Builds.Single();
        if (build.Id != "balanced_generalist_ew_major" ||
            build.MainWeaponCount != 1 || build.MainReactorCount != 1 ||
            !build.ActiveSensor || !build.ShieldGenerator ||
            build.KineticPdsCount != 1 || !build.EcmSuite || !build.EccmSuite ||
            build.UsedSpace != 35 || build.FreeSupportSpace != 0)
        {
            throw new InvalidOperationException(
                "Checkpoint 73 must hold the accepted 35-Space EW fixture constant.");
        }
        if (!technologyProfiles.TryGetValue("tl1-production", out TechnologyCombatProfile? production) ||
            production is null || production.TechnologyLevel != 1 || production.ReactorOutput != 5 ||
            !auxiliaryProfiles.ContainsKey("aux-r53-none-tl1"))
        {
            throw new InvalidOperationException(
                "Checkpoint 73 requires the accepted TL1 5-TP production profile and zero-effect AUX control.");
        }
        if (!sensorEwProfiles.TryGetValue("balanced-0", out SensorEwFoundationProfile? profile) ||
            profile.PassiveFirmRange != 1 || profile.PassiveApproximateRange != 3 ||
            profile.ActiveFirmRange != 3 || profile.ActiveApproximateRange != 4 ||
            profile.ActivePowerCost != 1 || profile.DiscriminationResistance != 0 ||
            profile.PointBlankBurnThroughResistance != 1)
        {
            throw new InvalidOperationException(
                "Checkpoint 73 requires the accepted CP71/72 Balanced-0 EW foundation unchanged.");
        }

        var contexts = new (WeaponFamily A, WeaponFamily B, Tl1IntegratedMovementOrder Order)[]
        {
            (WeaponFamily.Kinetic, WeaponFamily.Missile, Tl1IntegratedMovementOrder.SideAFirst),
            (WeaponFamily.Kinetic, WeaponFamily.Missile, Tl1IntegratedMovementOrder.SideBFirst),
            (WeaponFamily.Energy, WeaponFamily.Missile, Tl1IntegratedMovementOrder.SideAFirst),
            (WeaponFamily.Energy, WeaponFamily.Missile, Tl1IntegratedMovementOrder.SideBFirst),
            (WeaponFamily.Kinetic, WeaponFamily.Energy, Tl1IntegratedMovementOrder.SideAFirst),
            (WeaponFamily.Kinetic, WeaponFamily.Energy, Tl1IntegratedMovementOrder.SideBFirst),
        };
        foreach (var context in contexts)
        {
            Tl1IntegratedTacticalCombatVariantDocument[] variants = study.Variants.Where(v =>
                v.SideAFamily == context.A && v.SideBFamily == context.B &&
                v.MovementOrder == context.Order).ToArray();
            if (variants.Length != 4 ||
                studyDoctrineIds.Any(id => variants.Count(v => v.SideAAiDoctrineId == id) != 1))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 73 doctrine context {context.A}/{context.B}/{context.Order} is incomplete.");
            }
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            if (v.SideAAiDoctrineId != v.SideBAiDoctrineId ||
                string.IsNullOrWhiteSpace(v.SideAAiDoctrineId) ||
                v.SensorEwProfileId != "balanced-0" ||
                v.SideABuildId != "balanced_generalist_ew_major" ||
                v.SideBBuildId != "balanced_generalist_ew_major" ||
                v.SideAProfileId != "tl1-production" || v.SideBProfileId != "tl1-production" ||
                v.SideAAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.SideBAuxiliaryProfileId != "aux-r53-none-tl1" ||
                v.TacticalMapRadius != 5 || v.InitialRangeHexes != 4 ||
                v.StartingFuel != 100 || v.MovementFuelPerHex != 2 ||
                v.EvasiveManeuverFuelCost != 1 || v.ProtectedCompartmentation ||
                !(v.BaseShieldRechargeEnabled ?? true) ||
                v.EvasiveManeuversEnabled != false || v.PdsEnabled != true ||
                v.EscapeDisengagementEnabled != false ||
                v.SideABackgroundTacticalPowerCommitment != 0 ||
                v.SideBBackgroundTacticalPowerCommitment != 0 ||
                v.SideATacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideBTacticalPowerDoctrine != Tl1TacticalPowerDoctrine.FullVolleyFirst ||
                v.SideAReactorOutputOverride != 5 || v.SideBReactorOutputOverride != 5 ||
                v.SideATrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideBTrackPolicy != Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive ||
                v.SideASensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideBSensorOverloadPolicy != Tl1IntegratedSensorOverloadPolicy.None ||
                v.SideANetEwRangePenalty != 0 || v.SideBNetEwRangePenalty != 0 ||
                v.SideAStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideBStlOverloadPolicy != Tl1IntegratedStlOverloadPolicy.None ||
                v.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                v.SideBEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                v.SideAEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                v.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.None ||
                v.SideAEcmNormalPowerCostOverride != 1 ||
                v.SideBEcmNormalPowerCostOverride != 1 ||
                v.SideAEccmNormalPowerCostOverride != 1 ||
                v.SideBEccmNormalPowerCostOverride != 1 ||
                v.MovementMode != Tl1IntegratedMovementMode.TrackAwareOpponentRange ||
                v.SideAStlMovementHexes != 1 || v.SideBStlMovementHexes != 1 ||
                v.MovementOrder == Tl1IntegratedMovementOrder.Simultaneous)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 73 fixed-control or doctrine binding mismatch in variant '{v.Id}'.");
            }
        }
    }

    private static void ValidateTl1BurnthroughContext(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantDocument> context,
        string label)
    {
        if (context.Count != 3 ||
            context.Count(v => Tl1EcmPowerSweepPackage(v) == "clear") != 1 ||
            context.Count(v => Tl1EcmPowerSweepPackage(v) == "jam-p1") != 1 ||
            context.Count(v => Tl1EcmPowerSweepPackage(v) == "counter-p1") != 1)
        {
            throw new InvalidOperationException(
                $"Checkpoint 71 context '{label}' requires exactly clear, jam-p1, and counter-p1 variants.");
        }
    }

    private static void ValidateTl1EcmPowerSweepContext(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantDocument> context,
        string label)
    {
        if (context.Count != 11)
        {
            throw new InvalidOperationException(
                $"Checkpoint 70 context '{label}' requires exactly 11 variants.");
        }
        if (context.Count(v => Tl1EcmPowerSweepPackage(v) == "clear") != 1)
        {
            throw new InvalidOperationException(
                $"Checkpoint 70 context '{label}' requires exactly one clear control.");
        }
        foreach (int cost in Enumerable.Range(1, 5))
        {
            if (context.Count(v => Tl1EcmPowerSweepPackage(v) == $"jam-p{cost}") != 1 ||
                context.Count(v => Tl1EcmPowerSweepPackage(v) == $"counter-p{cost}") != 1)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 70 context '{label}' requires one jammed and one ECCM-countered variant at ECM cost {cost} TP.");
            }
        }
    }

    private static string Tl1ReactiveEwGeometry(
        Tl1IntegratedTacticalCombatVariantDocument variant) =>
        Tl1EcmPowerSweepGeometry(variant);

    private static string Tl1ReactiveEwPackage(
        Tl1IntegratedTacticalCombatVariantDocument variant)
    {
        bool aEcm = variant.SideAEcmPolicy == Tl1IntegratedEwPowerPolicy.Normal;
        bool bEcm = variant.SideBEcmPolicy == Tl1IntegratedEwPowerPolicy.Normal;
        bool aNoEcm = variant.SideAEcmPolicy == Tl1IntegratedEwPowerPolicy.None;
        bool bNoEcm = variant.SideBEcmPolicy == Tl1IntegratedEwPowerPolicy.None;
        bool aEccmNone = variant.SideAEccmPolicy == Tl1IntegratedEwPowerPolicy.None;
        bool bEccmNone = variant.SideBEccmPolicy == Tl1IntegratedEwPowerPolicy.None;
        bool aEccmAuto = variant.SideAEccmPolicy == Tl1IntegratedEwPowerPolicy.Normal;
        bool bEccmAuto = variant.SideBEccmPolicy == Tl1IntegratedEwPowerPolicy.Normal;
        bool aEccmReactive = variant.SideAEccmPolicy == Tl1IntegratedEwPowerPolicy.ReactiveNormal;
        bool bEccmReactive = variant.SideBEccmPolicy == Tl1IntegratedEwPowerPolicy.ReactiveNormal;

        if (aNoEcm && bNoEcm && aEccmNone && bEccmNone &&
            variant.SideAEcmNormalPowerCostOverride is null &&
            variant.SideBEcmNormalPowerCostOverride is null &&
            variant.SideAEccmNormalPowerCostOverride is null &&
            variant.SideBEccmNormalPowerCostOverride is null)
        {
            return "clear";
        }
        if (aNoEcm && bEcm && aEccmAuto && bEccmNone &&
            variant.SideBEcmNormalPowerCostOverride == 1 &&
            variant.SideAEccmNormalPowerCostOverride == 1 &&
            variant.SideAEcmNormalPowerCostOverride is null &&
            variant.SideBEccmNormalPowerCostOverride is null)
        {
            return "unilateral-auto";
        }
        if (aNoEcm && bEcm && aEccmReactive && bEccmNone &&
            variant.SideBEcmNormalPowerCostOverride == 1 &&
            variant.SideAEccmNormalPowerCostOverride == 1 &&
            variant.SideAEcmNormalPowerCostOverride is null &&
            variant.SideBEccmNormalPowerCostOverride is null)
        {
            return "unilateral-reactive";
        }
        if (aEcm && bEcm && aEccmAuto && bEccmAuto &&
            variant.SideAEcmNormalPowerCostOverride == 1 &&
            variant.SideBEcmNormalPowerCostOverride == 1 &&
            variant.SideAEccmNormalPowerCostOverride == 1 &&
            variant.SideBEccmNormalPowerCostOverride == 1)
        {
            return "bilateral-auto";
        }
        if (aEcm && bEcm && aEccmReactive && bEccmReactive &&
            variant.SideAEcmNormalPowerCostOverride == 1 &&
            variant.SideBEcmNormalPowerCostOverride == 1 &&
            variant.SideAEccmNormalPowerCostOverride == 1 &&
            variant.SideBEccmNormalPowerCostOverride == 1)
        {
            return "bilateral-reactive";
        }
        return "invalid";
    }

    private static string Tl1EcmPowerSweepGeometry(
        Tl1IntegratedTacticalCombatVariantDocument variant) =>
        variant.InitialRangeHexes == 0 &&
        variant.SideAStlMovementHexes == 0 &&
        variant.SideBStlMovementHexes == 0
            ? "point-blank"
            : "operational";

    private static string Tl1EcmPowerSweepPackage(
        Tl1IntegratedTacticalCombatVariantDocument variant)
    {
        if (variant.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
            variant.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.None)
        {
            return "invalid";
        }
        if (variant.SideBEcmPolicy == Tl1IntegratedEwPowerPolicy.None &&
            variant.SideAEccmPolicy == Tl1IntegratedEwPowerPolicy.None &&
            variant.SideBEcmNormalPowerCostOverride is null &&
            variant.SideAEccmNormalPowerCostOverride is null)
        {
            return "clear";
        }
        int cost = variant.SideBEcmNormalPowerCostOverride ?? 0;
        if (cost is < 1 or > 5)
        {
            return "invalid";
        }
        if (variant.SideBEcmPolicy == Tl1IntegratedEwPowerPolicy.Normal &&
            variant.SideAEccmPolicy == Tl1IntegratedEwPowerPolicy.None &&
            variant.SideAEccmNormalPowerCostOverride is null)
        {
            return $"jam-p{cost}";
        }
        if (variant.SideBEcmPolicy == Tl1IntegratedEwPowerPolicy.Normal &&
            variant.SideAEccmPolicy == Tl1IntegratedEwPowerPolicy.Normal &&
            variant.SideAEccmNormalPowerCostOverride == 1)
        {
            return $"counter-p{cost}";
        }
        return "invalid";
    }

    private static string Tl1SensorEwCandidatePackage(
        Tl1IntegratedTacticalCombatVariantDocument variant)
    {
        if (variant.SideAEcmPolicy != Tl1IntegratedEwPowerPolicy.None ||
            variant.SideBEccmPolicy != Tl1IntegratedEwPowerPolicy.None)
        {
            return "invalid";
        }
        if (variant.SideBEcmPolicy == Tl1IntegratedEwPowerPolicy.None &&
            variant.SideAEccmPolicy == Tl1IntegratedEwPowerPolicy.None &&
            variant.SideASensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.None &&
            variant.SideBSensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.None)
        {
            return "clear-normal";
        }
        if (variant.SideBEcmPolicy == Tl1IntegratedEwPowerPolicy.None &&
            variant.SideAEccmPolicy == Tl1IntegratedEwPowerPolicy.None &&
            variant.SideASensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded &&
            variant.SideBSensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded)
        {
            return "clear-overload";
        }
        if (variant.SideBEcmPolicy == Tl1IntegratedEwPowerPolicy.Normal &&
            variant.SideAEccmPolicy == Tl1IntegratedEwPowerPolicy.None &&
            variant.SideASensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded &&
            variant.SideBSensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded)
        {
            return "jammed-no-counter";
        }
        if (variant.SideBEcmPolicy == Tl1IntegratedEwPowerPolicy.Normal &&
            variant.SideAEccmPolicy == Tl1IntegratedEwPowerPolicy.Normal &&
            variant.SideASensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded &&
            variant.SideBSensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded)
        {
            return "jammed-eccm";
        }
        return "invalid";
    }

    private static WeaponFamily[] RequiredWeaponFamiliesForStudy(string studyId)
    {
        return studyId is Tl1ApproximateTrackDegradedFireStudyId or
                Tl1AppliedDegradedFireFamilyCandidateStudyId
            ? new[] { WeaponFamily.Kinetic, WeaponFamily.Energy }
            : new[] { WeaponFamily.Kinetic, WeaponFamily.Energy, WeaponFamily.Missile };
    }

    private static IReadOnlyList<Tl1IntegratedTacticalCombatGate> BuildGates(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        Tl1SensorEnvelope sensorEnvelope)
    {
        const double tolerance = 0.000001;
        int requiredCount = RequiredVariantCountForStudy(study.Id);
        var gates = new List<Tl1IntegratedTacticalCombatGate>
        {
            new(
                "variant-count",
                results.Count == requiredCount,
                $"Expected {requiredCount}; observed {results.Count}."),
            new(
                "no-trial-errors",
                results.All(result => result.TrialErrors == 0),
                "Every integrated tactical-combat trial must complete without exception."),
            new(
                "weapon-family-coverage",
                RequiredWeaponFamiliesForStudy(study.Id)
                    .All(family => study.Variants.Any(variant =>
                        variant.SideAFamily == family ||
                        variant.SideBFamily == family ||
                        variant.SideASecondaryFamily == family ||
                        variant.SideBSecondaryFamily == family)),
                $"Required weapon-family coverage for study '{study.Id}': " +
                    string.Join(", ", RequiredWeaponFamiliesForStudy(study.Id)) + "."),
            new(
                "fixed-range-holds",
                results.Where(result => result.MovementMode is
                        Tl1IntegratedMovementMode.HoldRange2 or
                        Tl1IntegratedMovementMode.HoldRange3 or
                        Tl1IntegratedMovementMode.HoldRange4 or
                        Tl1IntegratedMovementMode.HoldRange5)
                    .All(result => Math.Abs(result.MeanRangeChanges) <= tolerance),
                "Hold scenarios must not change relative range."),
            new(
                "dynamic-range-observed",
                !results.Any(result => result.MovementMode is
                        Tl1IntegratedMovementMode.ScriptedPursuit or
                        Tl1IntegratedMovementMode.PreferredRange or
                        Tl1IntegratedMovementMode.OpponentAwareRange or
                        Tl1IntegratedMovementMode.TrackAwareOpponentRange or
                        Tl1IntegratedMovementMode.EngageAdaptive) ||
                results.Where(result => result.MovementMode is
                        Tl1IntegratedMovementMode.ScriptedPursuit or
                        Tl1IntegratedMovementMode.PreferredRange or
                        Tl1IntegratedMovementMode.OpponentAwareRange or
                        Tl1IntegratedMovementMode.TrackAwareOpponentRange or
                        Tl1IntegratedMovementMode.EngageAdaptive)
                    .Any(result => result.MeanRangeChanges > 0.0),
                "Dynamic policy scenarios must produce actual range changes."),
            new(
                "no-same-turn-immobile-bonus",
                results.All(result => result.SameTurnImmobileBonusViolations == 0),
                "STL loss during a damage window must not alter attacks already committed."),
            new(
                "missile-travel-bounded",
                results.All(result =>
                    result.MaximumObservedMissileDistanceTraveled <=
                        result.MissileMaximumTravelHexes),
                "Each missile must remain within its variant-specific travel budget."),
            new(
                "normal-three-kit-profile",
                results.Where(result => result.DamageControl ==
                        Tl1IntegratedDamageControlMode.ComponentFirstReserveOne)
                    .All(result => result.MinimumCombinedKitsRemaining >= 0 &&
                        result.MeanCombinedKitsRemaining <=
                            (study.Id == AuxiliaryPerformanceScreeningStudyId
                                ? 8.0
                                : 6.0) + tolerance),
                study.Id == AuxiliaryPerformanceScreeningStudyId
                    ? "Checkpoint 48 permits one Repair Drone Bay kit bonus per ship; all other profiles retain the normal three-kit baseline."
                    : "Integrated Damage Control must use the normal three-kit profile per ship."),
            new(
                "normal-missile-logistics",
                results.All(result => result.MeanMissileLaunches <=
                    2.0 * Math.Max(
                        result.SideAMissileMagazineCapacity,
                        result.SideBMissileMagazineCapacity) + tolerance),
                "No integrated engagement may average more launches than the two configured missile magazines."),
            new(
                "no-invalid-repair-attempts",
                results.All(result => result.InvalidRepairAttempts == 0),
                "No integrated trial may attempt an ineligible repair."),
            new(
                "disengagement-requires-withdrawal-objective",
                results.Where(result => result.MovementMode !=
                        Tl1IntegratedMovementMode.ScriptedPursuit)
                    .All(result => Math.Abs(result.DisengagementPercent) <= tolerance),
                "Only the scripted withdrawal objective may resolve as Disengagement."),
            new(
                "disengagement-disabled-control",
                results.Where(result => !result.EscapeDisengagementEnabled)
                    .All(result => Math.Abs(result.DisengagementPercent) <= tolerance),
                "Variants with disengagement disabled must record no Disengagement outcomes."),
            new(
                "resolution-accounting",
                results.All(result => Math.Abs(
                    result.SideAWinsPercent +
                    result.SideBWinsPercent +
                    result.MutualPercent +
                    result.UnresolvedPercent - 100.0) <= 0.0001),
                "Side A, Side B, mutual, and unresolved outcomes must total 100%."),
            new(
                "tl2-profile-coverage",
                (study.Id != Tl2CandidateStudyId &&
                 study.Id != Tl2AttributionStudyId &&
                 study.Id != Tl2DefensiveRefinementStudyId &&
                 study.Id != Tl2DynamicWeaponChoiceStudyId &&
                 study.Id != Tl2OpponentAwareRangeStudyId &&
                 study.Id != AuxiliaryPerformanceScreeningStudyId &&
                 study.Id != ArchitectureDerivedAuxiliaryStudyId &&
                 study.Id != StatefulAuxiliaryTuningStudyId &&
                 study.Id != AuxiliaryRefinementStudyId &&
                 study.Id != Tl2AblativeCandidateStudyId &&
                 study.Id != AuxiliaryPowerStressStudyId) ||
                technologyProfiles.Keys.Where(id => id.StartsWith(
                        "tl2-", StringComparison.Ordinal))
                    .All(id => results.Any(result =>
                        result.SideAProfileId == id || result.SideBProfileId == id)),
                "Every TL2 candidate or attribution profile must appear in its Monte Carlo grid."),
            new(
                "tl2-recommended-review-computed",
                study.Id != Tl2CandidateStudyId ||
                    RecommendedTl2ConditionalWinPercent(results) is double share &&
                    share >= 0.0 && share <= 100.0,
                study.Id == Tl2CandidateStudyId
                    ? $"Identity-preserving conditional TL2 win share " +
                        $"{RecommendedTl2ConditionalWinPercent(results):F2}% " +
                        "(57-64% is a non-blocking review band)."
                    : "Not a TL2 candidate study."),
            new(
                "bounded-p90",
                results.All(result => result.P90Turns <= MaximumTurns + tolerance),
                $"P90 must remain within the {MaximumTurns}-turn simulation bound."),
            new(
                "policy-telemetry",
                results.All(result => result.MeanOrderRequests > 0.0) &&
                    (IsSingleSourcePolicyTelemetryStudy(study.Id) ||
                        (results.Any(result =>
                            result.MeanPreferredPolicyRequests > 0.0) &&
                         results.Any(result =>
                            result.MeanScriptedOrderRequests > 0.0))),
                (study.Id is AuxiliaryPerformanceScreeningStudyId or
                    ArchitectureDerivedAuxiliaryStudyId or
                    StatefulAuxiliaryTuningStudyId or
                    AuxiliaryRefinementStudyId or
                    Tl2AblativeCandidateStudyId or
                    AuxiliaryPowerStressStudyId) ||
                    study.Id == Tl1ComposedShipStudyId ||
                    study.Id == Tl1PowerDoctrineStudyId ||
                    study.Id == Tl1OperationalSensorStudyId ||
                    study.Id == Tl1TrackAwareAcquisitionStudyId ||
                    study.Id == Tl1BilateralTacticalGeometryStudyId ||
                    study.Id == Tl1ScriptedOverloadTacticsStudyId ||
                      study.Id == Tl1BilateralOverloadCounterplayStudyId ||
                      study.Id == Tl1SensorEwCandidateCombatStudyId ||
                      study.Id == Tl1EcmPowerCostCounterplayStudyId ||
                      study.Id == Tl1SensorDiscriminationBurnthroughStudyId ||
                      study.Id == Tl1ReactiveEwSubphaseStudyId ||
                      study.Id == Tl1EwAiDoctrineStudyId ||
                      study.Id == Tl1ApproximateTrackDegradedFireStudyId ||
                      study.Id == Tl1AppliedDegradedFireFamilyCandidateStudyId ||
                      study.Id == Tl1DegradedFireEccmValueStudyId ||
                      study.Id == Tl2SensorEwDiscriminationIsolationStudyId ||
                      study.Id == Tl2EwPowerPressureTallViabilityStudyId ||
                      study.Id == Tl2TacticalComputerEwPermutationStudyId ||
                      study.Id == Tl2PowerReactorProgressionPermutationStudyId ||
                      study.Id == Tl2ShieldCapacityPowerIntegrationStudyId ||
                      study.Id == Tl2ArmorApAiShieldIntegrationStudyId ||
                    study.Id == Tl2WeaponPenetrationLayeredDefenseStudyId ||
                    study.Id == CrossTlBuildPermutationScreeningStudyId ||
                      study.Id == CrossTlPowerAwareInformationControlScreeningStudyId ||
                      study.Id == CrossTlGeneralizedLegalBuildScreeningStudyId ||
                      study.Id == CrossTlMatchedReadinessSpaceScreeningStudyId ||
                    IsTl3CandidateStudy(study.Id) ||
                    IsTl3LowTechCapstoneStudy(study.Id) ||
                    IsCheckpoint56Study(study.Id) ||
                    IsCheckpoint57Study(study.Id) ||
                    IsCheckpoint58Study(study.Id)
                    ? "AUX, composed-ship, Sensor/EW, and TL3/TL4 screening studies record opponent-aware order requests while keeping each screen free of mixed policy aggregation."
                    : "Requested orders must be recorded; policy studies must also record their source."),
            new(
                "attack-layer-telemetry",
                (study.Id == CrossTlMatchedReadinessSpaceScreeningStudyId
                    ? results.Any(result =>
                        result.MeanDirectActionOpportunities +
                        result.MeanMissileLaunchOpportunities > 0.0) &&
                      results.All(result =>
                        result.MeanDirectActionOpportunities >= 0.0 &&
                        result.MeanMissileLaunchOpportunities >= 0.0)
                    : results.All(result =>
                        result.MeanDirectActionOpportunities +
                        result.MeanMissileLaunchOpportunities > 0.0)) &&
                results.Any(result => result.MeanShieldAbsorption > 0.0) &&
                results.Any(result => result.MeanHullDamage > 0.0),
                study.Id == CrossTlMatchedReadinessSpaceScreeningStudyId
                    ? "CP93 all-legal screening permits structurally engagement-denied variants while requiring nonnegative attack telemetry, at least one active-combat variant, and layer-by-layer damage somewhere in the study."
                    : "Attack opportunities and layer-by-layer damage must be recorded."),
            new(
                "order-resolution-status-telemetry",
                results.Any(result => result.MeanOrderNoMovementRequired > 0.0) &&
                results.All(result => result.MeanOrderThrottles >= 0.0 &&
                    result.MeanStlUnavailableCoercions >= 0.0 &&
                    result.MeanNoMovementResolved >= 0.0),
                "Ordinary no-movement, throttling, and genuine coercions must be reported separately."),
        };

        if (study.Id == Tl1ComposedShipStudyId)
        {
            var byId = study.Builds.ToDictionary(build => build.Id, StringComparer.Ordinal);
            gates.Add(new(
                "tl1-c61-build-coverage",
                byId.Count == 6 && results.Count == RequiredTl1ComposedShipVariantCount,
                "Checkpoint 61 must evaluate all six legal Checkpoint 60 build packages across the 3x3 family matrix."));
            gates.Add(new(
                "tl1-c61-second-main-executes",
                results.Where(result => study.Variants.Any(variant =>
                        variant.Id == result.Id &&
                        variant.SideASecondaryFamily is not null))
                    .Any(result => result.MeanDirectActionOpportunities +
                        result.MeanMissileLaunchOpportunities > 2.0),
                "At least one dual-main composed build must expose genuine second-main attack opportunities."));
            gates.Add(new(
                "tl1-c61-pds-concentration-telemetry",
                results.Where(result => study.Variants.Any(variant =>
                        variant.Id == result.Id &&
                        (variant.SideABuildId is "pds_saturator" or
                            "shielded_pds_fortress" or "dual_main_dual_pds") &&
                        variant.SideBFamily == WeaponFamily.Missile))
                    .Any(result => result.MeanPdsAttempts > 0.0),
                "Multi-PDS composed builds must record terminal-defense attempts against missile opponents."));
            gates.Add(new(
                "tl1-c61-power-pressure-telemetry",
                results.Any(result => result.MeanPreventedInsufficientPower > 0.0),
                "At least one legal odd build must expose a real Tactical Power opportunity cost under combat load."));
            gates.Add(new(
                "tl1-c61-outcomes-review-only",
                true,
                "Checkpoint 61 win shares, pacing, and matchup spreads are diagnostic evidence only; no target win rate is a release gate."));
        }

        if (study.Id == Tl1PowerDoctrineStudyId)
        {
            var variantsById = study.Variants.ToDictionary(
                variant => variant.Id, StringComparer.Ordinal);
            gates.Add(new(
                "tl1-c62-doctrine-coverage",
                Enum.GetValues<Tl1TacticalPowerDoctrine>().All(doctrine =>
                    study.Variants.Any(variant =>
                        variant.SideATacticalPowerDoctrine == doctrine)),
                "Checkpoint 62 must exercise DefenseFirst, PrimaryFireFirst, and FullVolleyFirst."));
            gates.Add(new(
                "tl1-c62-reactor-sensitivity-coverage",
                new[] { 4, 5, 6 }.All(output => study.Variants.Any(variant =>
                    variant.SideAReactorOutputOverride == output)),
                "Checkpoint 62 must exercise 4/5/6 TP per-main-reactor sensitivity without changing the production 5-TP profile."));
            gates.Add(new(
                "tl1-c62-power-pressure-observed",
                results.Any(result => result.MeanPreventedInsufficientPower > 0.0),
                "At least one power-sensitive composed build must still expose Tactical Power contention."));
            bool pdsSensitivityObserved = results
                .GroupBy(result => new
                {
                    Build = variantsById[result.Id].SideABuildId,
                    Family = result.SideAFamily,
                })
                .Any(group => group.Select(result => result.MeanPdsAttempts)
                    .Distinct().Count() > 1);
            gates.Add(new(
                "tl1-c62-pds-allocation-sensitivity-observed",
                pdsSensitivityObserved,
                "At least one paired build/family lane must change PDS reaction usage across doctrine/reactor settings."));
            gates.Add(new(
                "tl1-c62-outcomes-review-only",
                true,
                "Doctrine/reactor outcomes are sensitivity evidence only. Reactor output 5 remains the accepted TL1 production value and no weapon family is promoted or demoted from this study alone."));
        }

        if (study.Id == Tl1OperationalSensorStudyId)
        {
            var variantsById = study.Variants.ToDictionary(
                variant => variant.Id, StringComparer.Ordinal);
            gates.Add(new(
                "tl1-c63-operational-sensor-coverage",
                results.Count == RequiredTl1OperationalSensorVariantCount &&
                    new[]
                    {
                        Tl1OperationalTrackPolicy.EstablishedFirm,
                        Tl1OperationalTrackPolicy.PassiveOnly,
                        Tl1OperationalTrackPolicy.AutoActive,
                    }.All(policy => study.Variants.Any(variant =>
                        variant.SideATrackPolicy == policy)),
                "Checkpoint 63 must exercise established-Firm, passive-only, and automatic active-sensor acquisition across all six accepted build packages."));
            gates.Add(new(
                "tl1-c63-established-control-preserved",
                results.Where(result => variantsById[result.Id].SideATrackPolicy ==
                        Tl1OperationalTrackPolicy.EstablishedFirm)
                    .All(result => result.MeanPreventedTrackUnavailable == 0.0 &&
                        result.MeanActiveSensorPowerCommittedA == 0.0),
                "Established-Firm controls must preserve the prior combat isolation without sensor power or track-denial events."));
            gates.Add(new(
                "tl1-c63-active-sensor-exercised",
                results.Where(result =>
                        variantsById[result.Id].SideATrackPolicy == Tl1OperationalTrackPolicy.AutoActive &&
                        variantsById[result.Id].SideANetEwRangePenalty == 0 &&
                        study.Builds.Single(build => build.Id == variantsById[result.Id].SideABuildId).ActiveSensor)
                    .Any(result => result.MeanActiveSensorPowerCommittedA > 0.0),
                "At least one active-sensor-equipped build must commit Tactical Power to extend its operational Firm envelope."));
            Tl1IntegratedTacticalCombatVariantSummary[] passiveSensorlessResults =
                results.Where(result =>
                        variantsById[result.Id].SideATrackPolicy ==
                            Tl1OperationalTrackPolicy.PassiveOnly &&
                        !study.Builds.Single(build =>
                            build.Id == variantsById[result.Id].SideABuildId).ActiveSensor)
                    .ToArray();
            string[] sensorlessBuildIds = study.Builds
                .Where(build => !build.ActiveSensor)
                .Select(build => build.Id)
                .ToArray();
            bool passiveCoreNotBlind =
                sensorEnvelope.PassiveFirmRange > 0 &&
                sensorEnvelope.PassiveApproximateRange >=
                    sensorEnvelope.PassiveFirmRange &&
                passiveSensorlessResults.All(result =>
                    result.MeanSensorEvaluationsA > 0.0 &&
                    Math.Abs(result.MeanActiveSensorPowerCommittedA) <= tolerance) &&
                sensorlessBuildIds.All(buildId =>
                    passiveSensorlessResults
                        .Where(result => variantsById[result.Id].SideABuildId == buildId)
                        .Any(result => result.MeanFirmTrackEvaluationsA +
                            result.MeanApproximateTrackEvaluationsA > 0.0));
            gates.Add(new(
                "tl1-c63-passive-core-not-blind",
                passiveCoreNotBlind,
                "Builds without the optional active-sensor suite must retain the accepted passive envelope and evaluate it without active power. A lane may legitimately remain NoTrack for an entire engagement when geometry stays outside passive range."));

            bool sensorlessParity = true;
            foreach (Tl1IntegratedShipBuildDocument build in study.Builds.Where(build => !build.ActiveSensor))
            foreach (WeaponFamily family in new[]
                { WeaponFamily.Kinetic, WeaponFamily.Energy, WeaponFamily.Missile })
            {
                Tl1IntegratedTacticalCombatVariantSummary passive = results.Single(result =>
                    variantsById[result.Id].SideABuildId == build.Id &&
                    result.SideAFamily == family &&
                    variantsById[result.Id].ProfileLabel == "operational-passive-clear");
                Tl1IntegratedTacticalCombatVariantSummary automatic = results.Single(result =>
                    variantsById[result.Id].SideABuildId == build.Id &&
                    result.SideAFamily == family &&
                    variantsById[result.Id].ProfileLabel == "operational-auto-active-clear");
                sensorlessParity &= Math.Abs(passive.SideAWinsPercent - automatic.SideAWinsPercent) <= tolerance &&
                    Math.Abs(passive.SideBWinsPercent - automatic.SideBWinsPercent) <= tolerance &&
                    Math.Abs(passive.MeanTurns - automatic.MeanTurns) <= tolerance &&
                    Math.Abs(passive.MeanPreventedTrackUnavailable - automatic.MeanPreventedTrackUnavailable) <= tolerance &&
                    Math.Abs(automatic.MeanActiveSensorPowerCommittedA) <= tolerance;
            }
            gates.Add(new(
                "tl1-c63-sensorless-auto-passive-parity",
                sensorlessParity,
                "With paired random streams, AutoActive must collapse exactly to PassiveOnly when the build has no active-sensor suite."));
            gates.Add(new(
                "tl1-c63-ew-pressure-exercised",
                results.Where(result =>
                        variantsById[result.Id].ProfileLabel == "operational-auto-active-ew1")
                    .Any(result => result.MeanPreventedTrackUnavailable > 0.0 ||
                        result.MeanApproximateTrackEvaluationsA > 0.0 ||
                        result.MeanNoTrackEvaluationsA > 0.0),
                "The one-point net EW stress lane must measurably pressure Side A track quality in at least one paired case."));
            gates.Add(new(
                "tl1-c63-opponent-firm-control",
                results.All(result => result.MeanSensorEvaluationsB > 0.0 &&
                    result.MeanApproximateTrackEvaluationsB == 0.0 &&
                    result.MeanNoTrackEvaluationsB == 0.0 &&
                    result.MeanActiveSensorPowerCommittedB == 0.0),
                "Side B remains an established-Firm control so Checkpoint 63 isolates Side A acquisition consequences."));
            gates.Add(new(
                "tl1-c63-outcomes-review-only",
                true,
                "Sensor/acquisition win shares are diagnostic evidence only. No target win rate, weapon-family promotion/demotion, or active-sensor balance target is a release gate."));
        }

        if (study.Id == Tl1TrackAwareAcquisitionStudyId)
        {
            var variantsById = study.Variants.ToDictionary(
                variant => variant.Id, StringComparer.Ordinal);
            var buildsById = study.Builds.ToDictionary(
                build => build.Id, StringComparer.Ordinal);
            gates.Add(new(
                "tl1-c64-track-aware-coverage",
                results.Count == RequiredTl1TrackAwareAcquisitionVariantCount &&
                    study.Variants.Count(variant =>
                        variant.MovementMode == Tl1IntegratedMovementMode.TrackAwareOpponentRange &&
                        variant.SideATrackPolicy == Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive) == 36,
                "Checkpoint 64 must exercise 18 clear and 18 EW1 track-aware/acquisition-first lanes alongside the paired legacy and established-Firm controls."));
            gates.Add(new(
                "tl1-c64-production-controls-preserved",
                study.Variants.All(variant =>
                    variant.SideATacticalPowerDoctrine == Tl1TacticalPowerDoctrine.FullVolleyFirst &&
                    variant.SideBTacticalPowerDoctrine == Tl1TacticalPowerDoctrine.FullVolleyFirst &&
                    variant.SideAReactorOutputOverride == 5 &&
                    variant.SideBReactorOutputOverride == 5),
                "Checkpoint 64 must hold the accepted 5-TP production reactor and FullVolleyFirst power doctrine fixed."));
            gates.Add(new(
                "tl1-c64-acquisition-first-active-sensor-exercised",
                results.Where(result =>
                        variantsById[result.Id].SideATrackPolicy ==
                            Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive &&
                        buildsById[variantsById[result.Id].SideABuildId!].ActiveSensor)
                    .Any(result => result.MeanActiveSensorPowerCommittedA > 0.0),
                "At least one track-aware active-sensor build must commit Tactical Power under acquisition-first control."));
            gates.Add(new(
                "tl1-c64-sensorless-never-fakes-active-power",
                results.Where(result =>
                        variantsById[result.Id].SideATrackPolicy ==
                            Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive &&
                        !buildsById[variantsById[result.Id].SideABuildId!].ActiveSensor)
                    .All(result => Math.Abs(result.MeanActiveSensorPowerCommittedA) <= tolerance),
                "Track-aware sensorless builds must continue to rely on the accepted passive core and may never synthesize active-sensor power."));

            bool pairedOperationalResponse = false;
            foreach (var group in
                results.GroupBy(result => result.ComparisonGroup))
            {
                Tl1IntegratedTacticalCombatVariantSummary legacyClear = group.Single(result =>
                    variantsById[result.Id].ProfileLabel == "legacy-auto-active-clear");
                Tl1IntegratedTacticalCombatVariantSummary trackClear = group.Single(result =>
                    variantsById[result.Id].ProfileLabel == "track-aware-auto-active-clear");
                Tl1IntegratedTacticalCombatVariantSummary legacyEw = group.Single(result =>
                    variantsById[result.Id].ProfileLabel == "legacy-auto-active-ew1");
                Tl1IntegratedTacticalCombatVariantSummary trackEw = group.Single(result =>
                    variantsById[result.Id].ProfileLabel == "track-aware-auto-active-ew1");
                pairedOperationalResponse |=
                    trackClear.MeanPreventedTrackUnavailable + tolerance <
                        legacyClear.MeanPreventedTrackUnavailable ||
                    trackEw.MeanPreventedTrackUnavailable + tolerance <
                        legacyEw.MeanPreventedTrackUnavailable ||
                    trackClear.MeanFirmTrackEvaluationsA >
                        legacyClear.MeanFirmTrackEvaluationsA + tolerance ||
                    trackEw.MeanFirmTrackEvaluationsA >
                        legacyEw.MeanFirmTrackEvaluationsA + tolerance;
            }
            gates.Add(new(
                "tl1-c64-track-aware-response-observed",
                pairedOperationalResponse,
                "At least one paired lane must respond to track-aware movement/acquisition with fewer track-denied attacks or more Firm evaluations; sensorless ships are not required to defeat equal-speed standoff."));
            gates.Add(new(
                "tl1-c64-opponent-firm-control",
                results.All(result => result.MeanSensorEvaluationsB > 0.0 &&
                    result.MeanApproximateTrackEvaluationsB == 0.0 &&
                    result.MeanNoTrackEvaluationsB == 0.0 &&
                    result.MeanActiveSensorPowerCommittedB == 0.0),
                "Side B remains an established-Firm control so Checkpoint 64 isolates Side A movement/acquisition consequences."));
            gates.Add(new(
                "tl1-c64-standoff-remains-valid",
                true,
                "A track-aware ship may still fail to obtain Firm when an equal-or-faster opponent successfully preserves standoff; release gates must not force sensorless parity."));
            gates.Add(new(
                "tl1-c64-outcomes-review-only",
                true,
                "Track-aware movement/acquisition outcomes are diagnostic evidence only. No target win rate, sensor Space-cost change, EW retune, reactor change, or weapon-family rebalance is a release gate."));
        }

        if (study.Id == Tl1BilateralTacticalGeometryStudyId)
        {
            var variantsById = study.Variants.ToDictionary(
                variant => variant.Id, StringComparer.Ordinal);
            gates.Add(new(
                "tl1-c65-bilateral-geometry-coverage",
                results.Count == RequiredTl1BilateralTacticalGeometryVariantCount &&
                    results.Select(result => result.ComparisonGroup)
                        .Distinct(StringComparer.Ordinal).Count() == 27 &&
                    results.GroupBy(result => result.ComparisonGroup)
                        .All(group => group.Count() == 2),
                "Checkpoint 65 must exercise 27 paired family/regime lanes with mirrored Side-A-first and Side-B-first movement order."));
            gates.Add(new(
                "tl1-c65-finite-map-contract",
                results.All(result => result.TacticalMapRadius == 5 &&
                    result.InitialRangeHexes == 4 &&
                    result.MovementOrder is Tl1IntegratedMovementOrder.SideAFirst or
                        Tl1IntegratedMovementOrder.SideBFirst),
                "Checkpoint 65 must use the production radius-5 finite tactical map and explicit mirrored movement order."));
            gates.Add(new(
                "tl1-c65-fuel-accounting",
                results.All(result =>
                    Math.Abs(result.MeanFuelSpentA -
                        result.MeanMovementHexesA * result.MovementFuelPerHex) <= tolerance &&
                    Math.Abs(result.MeanFuelSpentB -
                        result.MeanMovementHexesB * result.MovementFuelPerHex) <= tolerance &&
                    result.MeanFuelRemainingA >= -tolerance &&
                    result.MeanFuelRemainingB >= -tolerance),
                "With EvM disabled in the geometry study, fuel spent must equal two fuel per traversed ship hex and may never become negative."));
            gates.Add(new(
                "tl1-c65-finite-range-bounds",
                results.All(result => result.MeanFinalRange >= -tolerance &&
                    result.MeanFinalRange <= 10.0 + tolerance &&
                    result.MeanMinimumRange >= -tolerance &&
                    result.MeanMinimumRange <= 10.0 + tolerance &&
                    result.MeanMaximumRange >= -tolerance &&
                    result.MeanMaximumRange <= 10.0 + tolerance) &&
                    results.Any(result => result.MeanMovementHexesA > 0.0 ||
                        result.MeanMovementHexesB > 0.0),
                "Finite-map combat ranges must remain inside the radius-5 map's 0-10 separation bound while movement is actually exercised; boundary-turn telemetry remains diagnostic rather than a required combat outcome."));
            gates.Add(new(
                "tl1-c65-bilateral-operational-sensing",
                results.Where(result => variantsById[result.Id].SideATrackPolicy ==
                        Tl1OperationalTrackPolicy.AcquisitionFirstAutoActive)
                    .All(result => result.MeanSensorEvaluationsA > 0.0 &&
                        result.MeanSensorEvaluationsB > 0.0),
                "Operational clear/EW lanes must evaluate sensing on both ships rather than retaining a one-sided established-Firm opponent."));
            gates.Add(new(
                "tl1-c65-established-firm-bilateral-control",
                results.Where(result => variantsById[result.Id].SideATrackPolicy ==
                        Tl1OperationalTrackPolicy.EstablishedFirm)
                    .All(result => result.MeanApproximateTrackEvaluationsA == 0.0 &&
                        result.MeanNoTrackEvaluationsA == 0.0 &&
                        result.MeanApproximateTrackEvaluationsB == 0.0 &&
                        result.MeanNoTrackEvaluationsB == 0.0),
                "Established-Firm controls must remain a bilateral ceiling rather than a one-sided advantage."));
            gates.Add(new(
                "tl1-c65-production-controls-preserved",
                study.Variants.All(variant =>
                    variant.SideAReactorOutputOverride == 5 &&
                    variant.SideBReactorOutputOverride == 5 &&
                    variant.SideATacticalPowerDoctrine == Tl1TacticalPowerDoctrine.FullVolleyFirst &&
                    variant.SideBTacticalPowerDoctrine == Tl1TacticalPowerDoctrine.FullVolleyFirst &&
                    !(variant.EvasiveManeuversEnabled ?? true) &&
                    !(variant.EscapeDisengagementEnabled ?? true)),
                "Checkpoint 65 must hold the accepted 5-TP reactor, FullVolleyFirst isolation doctrine, EvM-off control, and no-disengagement arena fixed."));
            gates.Add(new(
                "tl1-c65-final-position-combat-geometry",
                true,
                "Ordinary post-Movement combat uses final HexCoord separation; traversed-path closest approach is diagnostic/Movement-phase evidence only and grants no normal historical-position attack."));
            gates.Add(new(
                "tl1-c65-overload-ai-deferred",
                true,
                "Existing Concept overload/Strain rules remain authoritative, but Checkpoint 65 does not add a full reactive overload AI or retroactive Movement-phase power changes."));
            gates.Add(new(
                "tl1-c65-outcomes-review-only",
                true,
                "Finite-map movement-order, fuel, sensing, missile intercept, and win-share outcomes are diagnostic evidence only; no target win rate or component rebalance is a release gate."));
        }



        if (study.Id == Tl1ScriptedOverloadTacticsStudyId)
        {
            gates.Add(new(
                "tl1-c66-variant-coverage",
                results.Count == RequiredTl1ScriptedOverloadTacticsVariantCount &&
                    results.All(result => result.TrialErrors == 0),
                "Checkpoint 66 must complete all 80 scripted-overload variants without trial errors."));
            Tl1IntegratedTacticalCombatVariantSummary[] controls = results
                .Where(result =>
                {
                    Tl1IntegratedTacticalCombatVariantDocument v = study.Variants.Single(x => x.Id == result.Id);
                    return v.SideAStlOverloadPolicy == Tl1IntegratedStlOverloadPolicy.None &&
                        v.SideASensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.None;
                }).ToArray();
            gates.Add(new(
                "tl1-c66-no-overload-control-clean",
                controls.All(result =>
                    Math.Abs(result.MeanStlOverloadActivationsA) <= tolerance &&
                    Math.Abs(result.MeanSensorOverloadActivationsA) <= tolerance &&
                    Math.Abs(result.MeanStlOverloadActivationsB) <= tolerance &&
                    Math.Abs(result.MeanSensorOverloadActivationsB) <= tolerance),
                "No-overload controls must record no overload activations."));
            gates.Add(new(
                "tl1-c66-side-b-control-clean",
                results.All(result =>
                    Math.Abs(result.MeanStlOverloadActivationsB) <= tolerance &&
                    Math.Abs(result.MeanSensorOverloadActivationsB) <= tolerance),
                "Side B is the non-overload control and must never activate overload."));
            gates.Add(new(
                "tl1-c66-safe-strain-bounds",
                results.All(result =>
                    result.MeanStlOverloadActivationsA <= 2.0 + tolerance &&
                    result.MeanSensorOverloadActivationsA <= 2.0 + tolerance),
                "Safe-only doctrine must stop before a third +1-Strain overload would require Forced Overload."));
            gates.Add(new(
                "tl1-c66-stl-overload-exercised",
                results.Any(result =>
                {
                    Tl1IntegratedTacticalCombatVariantDocument v = study.Variants.Single(x => x.Id == result.Id);
                    return v.SideAStlOverloadPolicy == Tl1IntegratedStlOverloadPolicy.SafeRangePressure &&
                        result.MeanStlOverloadActivationsA > tolerance;
                }),
                "At least one scripted STL-overload lane must exercise the pre-Movement overload."));
            gates.Add(new(
                "tl1-c66-sensor-overload-exercised",
                results.Any(result =>
                {
                    Tl1IntegratedTacticalCombatVariantDocument v = study.Variants.Single(x => x.Id == result.Id);
                    return v.SideASensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.SafeWhenNeeded &&
                        v.SideAFamily == WeaponFamily.Missile &&
                        v.SideANetEwRangePenalty == 1 &&
                        result.MeanSensorOverloadActivationsA > tolerance;
                }),
                "At least one EW1 Missile lane must exercise the later-window Active Sensor overload."));
            gates.Add(new(
                "tl1-c66-fuel-accounting",
                results.All(result =>
                    Math.Abs(result.MeanFuelSpentA -
                        (2.0 * result.MeanMovementHexesA +
                         StlDriveOverloadProfile.Tl1.ExtraFuelCost *
                            result.MeanStlOverloadActivationsA)) <= 0.00001 &&
                    Math.Abs(result.MeanFuelSpentB -
                        2.0 * result.MeanMovementHexesB) <= 0.00001),
                "Fuel must equal two per traversed hex plus the listed STL-overload extra fuel on Side A."));
            gates.Add(new(
                "tl1-c66-balance-signals-nonblocking",
                true,
                "Overload value, win shares, initiative effects, and family advantages are review evidence rather than target-win gates."));
        }

        if (study.Id == Tl1BilateralOverloadCounterplayStudyId)
        {
            var variantsById = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
            gates.Add(new(
                "tl1-c67-variant-coverage",
                results.Count == RequiredTl1BilateralOverloadCounterplayVariantCount &&
                    results.All(result => result.TrialErrors == 0),
                "Checkpoint 67 must complete all 60 bilateral overload/EW counterplay variants without trial errors."));
            gates.Add(new(
                "tl1-c67-fuel-100-accounting",
                results.All(result => result.StartingFuel == 100 &&
                    Math.Abs(result.MeanFuelSpentA -
                        (2.0 * result.MeanMovementHexesA +
                         StlDriveOverloadProfile.Tl1.ExtraFuelCost * result.MeanStlOverloadActivationsA)) <= 0.00001 &&
                    Math.Abs(result.MeanFuelSpentB -
                        (2.0 * result.MeanMovementHexesB +
                         StlDriveOverloadProfile.Tl1.ExtraFuelCost * result.MeanStlOverloadActivationsB)) <= 0.00001 &&
                    result.MeanFuelRemainingA >= -tolerance && result.MeanFuelRemainingB >= -tolerance),
                "Checkpoint 67 must use the new 100-fuel baseline while preserving two fuel per traversed hex and listed STL-overload extra fuel."));
            gates.Add(new(
                "tl1-c67-safe-overload-bounds",
                results.All(result =>
                    result.MeanStlOverloadActivationsA <= 2.0 + tolerance &&
                    result.MeanStlOverloadActivationsB <= 2.0 + tolerance &&
                    result.MeanSensorOverloadActivationsA <= 2.0 + tolerance &&
                    result.MeanSensorOverloadActivationsB <= 2.0 + tolerance &&
                    result.MeanEcmOverloadActivationsA <= 2.0 + tolerance &&
                    result.MeanEcmOverloadActivationsB <= 2.0 + tolerance &&
                    result.MeanEccmOverloadActivationsA <= 2.0 + tolerance &&
                    result.MeanEccmOverloadActivationsB <= 2.0 + tolerance),
                "Safe-only scripted counterplay must stop before a third +1-Strain overload would require Forced Overload."));
            gates.Add(new(
                "tl1-c67-request-activation-telemetry",
                results.All(result =>
                    result.MeanStlOverloadActivationsA <= result.MeanStlOverloadRequestsA + tolerance &&
                    result.MeanStlOverloadActivationsB <= result.MeanStlOverloadRequestsB + tolerance &&
                    result.MeanSensorOverloadActivationsA <= result.MeanSensorOverloadRequestsA + tolerance &&
                    result.MeanSensorOverloadActivationsB <= result.MeanSensorOverloadRequestsB + tolerance &&
                    result.MeanEcmOverloadActivationsA <= result.MeanEcmOverloadRequestsA + tolerance &&
                    result.MeanEcmOverloadActivationsB <= result.MeanEcmOverloadRequestsB + tolerance &&
                    result.MeanEccmOverloadActivationsA <= result.MeanEccmOverloadRequestsA + tolerance &&
                    result.MeanEccmOverloadActivationsB <= result.MeanEccmOverloadRequestsB + tolerance),
                "Overload telemetry must distinguish requests from actual activations; activations may never exceed requests."));
            Tl1IntegratedTacticalCombatVariantSummary[] noOverload = results.Where(result =>
            {
                Tl1IntegratedTacticalCombatVariantDocument v = variantsById[result.Id];
                return v.SideAStlOverloadPolicy == Tl1IntegratedStlOverloadPolicy.None &&
                    v.SideBStlOverloadPolicy == Tl1IntegratedStlOverloadPolicy.None &&
                    v.SideASensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.None &&
                    v.SideBSensorOverloadPolicy == Tl1IntegratedSensorOverloadPolicy.None &&
                    v.SideAEcmPolicy == Tl1IntegratedEwPowerPolicy.None &&
                    v.SideBEcmPolicy == Tl1IntegratedEwPowerPolicy.None &&
                    v.SideAEccmPolicy == Tl1IntegratedEwPowerPolicy.None &&
                    v.SideBEccmPolicy == Tl1IntegratedEwPowerPolicy.None;
            }).ToArray();
            gates.Add(new(
                "tl1-c67-denial-telemetry-accounting",
                results.All(result =>
                    result.MeanOverloadDeniedPowerA + result.MeanOverloadDeniedStrainA <=
                        result.MeanStlOverloadRequestsA + result.MeanSensorOverloadRequestsA +
                        result.MeanEcmOverloadRequestsA + result.MeanEccmOverloadRequestsA + tolerance &&
                    result.MeanOverloadDeniedPowerB + result.MeanOverloadDeniedStrainB <=
                        result.MeanStlOverloadRequestsB + result.MeanSensorOverloadRequestsB +
                        result.MeanEcmOverloadRequestsB + result.MeanEccmOverloadRequestsB + tolerance),
                "Power/Strain denial telemetry must be a bounded subset of explicit overload requests; condition/fuel denials may remain in the request-minus-activation remainder."));
            gates.Add(new(
                "tl1-c67-no-overload-controls-clean",
                noOverload.All(result =>
                    result.MeanStlOverloadActivationsA <= tolerance &&
                    result.MeanStlOverloadActivationsB <= tolerance &&
                    result.MeanSensorOverloadActivationsA <= tolerance &&
                    result.MeanSensorOverloadActivationsB <= tolerance &&
                    result.MeanEcmOverloadActivationsA <= tolerance &&
                    result.MeanEcmOverloadActivationsB <= tolerance &&
                    result.MeanEccmOverloadActivationsA <= tolerance &&
                    result.MeanEccmOverloadActivationsB <= tolerance),
                "Control lanes with no overload policies must record no overload activations."));
            gates.Add(new(
                "tl1-c67-bilateral-stl-exercised",
                results.Any(result => variantsById[result.Id].SideAStlOverloadPolicy ==
                        Tl1IntegratedStlOverloadPolicy.SafeRangePressure &&
                    result.MeanStlOverloadRequestsA > tolerance) &&
                results.Any(result => variantsById[result.Id].SideBStlOverloadPolicy ==
                        Tl1IntegratedStlOverloadPolicy.SafeRangePressure &&
                    result.MeanStlOverloadRequestsB > tolerance),
                "The mirrored STL matrix must exercise pre-Movement overload requests on both sides without retroactive commitment."));
            gates.Add(new(
                "tl1-c67-post-movement-ew-exercised",
                results.Any(result => result.MeanEcmOverloadActivationsB > tolerance) &&
                results.Any(result => result.MeanEccmOverloadActivationsA > tolerance) &&
                results.Any(result => result.MeanSensorOverloadRequestsA > tolerance),
                "The post-Movement response matrix must exercise defending ECM overload, attacking ECCM overload, and reactive sensor-overload requests."));
            gates.Add(new(
                "tl1-c67-ew-power-installed-only",
                results.Where(result =>
                        variantsById[result.Id].SideABuildId == "balanced_generalist_major")
                    .All(result => result.MeanEcmPowerCommittedA <= tolerance &&
                        result.MeanEcmPowerCommittedB <= tolerance &&
                        result.MeanEccmPowerCommittedA <= tolerance &&
                        result.MeanEccmPowerCommittedB <= tolerance),
                "The 33-Space STL-control fixture has no explicit ECM/ECCM installation and must never synthesize EW power."));
            gates.Add(new(
                "tl1-c67-outcomes-review-only",
                true,
                "Overload request rates, counterplay, initiative effects, fuel usage, geometry, and win shares are diagnostic evidence only; no target win rate or component rebalance is a release gate."));
        }

        if (study.Id == Tl1SensorEwCandidateCombatStudyId)
        {
            var variantsById = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
            gates.Add(new(
                "tl1-c69-variant-coverage",
                results.Count == RequiredTl1SensorEwCandidateCombatVariantCount &&
                    results.All(result => result.TrialErrors == 0),
                "Checkpoint 69 must complete all 72 Sensor/EW candidate combat variants without trial errors."));
            gates.Add(new(
                "tl1-c69-candidate-coverage",
                new[] { "balanced-0", "balanced-1", "balanced-2" }.All(profileId =>
                    study.Variants.Count(v => v.SensorEwProfileId == profileId) == 24),
                "Balanced-0, Balanced-1, and Balanced-2 must each receive the same 24-variant operational combat matrix."));
            gates.Add(new(
                "tl1-c69-package-coverage",
                new[] { "clear-normal", "clear-overload", "jammed-no-counter", "jammed-eccm" }.All(package =>
                    study.Variants.Count(v => Tl1SensorEwCandidatePackage(v) == package) == 18),
                "Normal, sensor-overload, jammed, and ECCM-countered packages must each receive 18 matched variants."));
            gates.Add(new(
                "tl1-c69-fuel-100-accounting",
                results.All(result => result.StartingFuel == 100 &&
                    Math.Abs(result.MeanFuelSpentA - 2.0 * result.MeanMovementHexesA) <= 0.00001 &&
                    Math.Abs(result.MeanFuelSpentB - 2.0 * result.MeanMovementHexesB) <= 0.00001 &&
                    result.MeanFuelRemainingA >= -tolerance && result.MeanFuelRemainingB >= -tolerance),
                "Checkpoint 69 holds STL overload off, so fuel must equal two per traversed hex from the accepted 100-fuel baseline."));
            Tl1IntegratedTacticalCombatVariantSummary[] clearNormal = results.Where(result =>
                Tl1SensorEwCandidatePackage(variantsById[result.Id]) == "clear-normal").ToArray();
            gates.Add(new(
                "tl1-c69-normal-active-power-bounded",
                clearNormal.All(result =>
                    Math.Abs(result.MeanActiveSensorPowerCommittedA -
                        result.MeanActiveSensorPoweredTurnsA) <= tolerance &&
                    Math.Abs(result.MeanActiveSensorPowerCommittedB -
                        result.MeanActiveSensorPoweredTurnsB) <= tolerance),
                "Forward TL1 candidates use one 1-TP normal Active Sensor mode; in clear-normal lanes cumulative active-sensor TP must equal the number of powered sensor evaluations, proving a 1-TP normal-mode cost without confusing per-trial cumulative power with per-use power."));
            gates.Add(new(
                "tl1-c69-safe-sensor-overload-bounds",
                results.All(result =>
                    result.MeanSensorOverloadActivationsA <= 2.0 + tolerance &&
                    result.MeanSensorOverloadActivationsB <= 2.0 + tolerance),
                "Safe Sensor overload doctrine must stop before a third +1-Strain overload would require Forced Overload."));
            Tl1IntegratedTacticalCombatVariantSummary[] jammed = results.Where(result =>
                Tl1SensorEwCandidatePackage(variantsById[result.Id]) == "jammed-no-counter").ToArray();
            Tl1IntegratedTacticalCombatVariantSummary[] countered = results.Where(result =>
                Tl1SensorEwCandidatePackage(variantsById[result.Id]) == "jammed-eccm").ToArray();
            gates.Add(new(
                "tl1-c69-ecm-package-exercised",
                jammed.Any(result => result.MeanEcmPowerCommittedB > tolerance),
                "The jammed-no-counter package must actually power defending ECM in at least one operational lane."));
            gates.Add(new(
                "tl1-c69-eccm-package-exercised",
                countered.Any(result => result.MeanEcmPowerCommittedB > tolerance) &&
                    countered.Any(result => result.MeanEccmPowerCommittedA > tolerance),
                "The jammed-ECCM package must actually exercise both defending ECM and attacking ECCM."));
            gates.Add(new(
                "tl1-c69-no-static-ew-range-penalty",
                study.Variants.All(v => v.SideANetEwRangePenalty == 0 && v.SideBNetEwRangePenalty == 0),
                "Checkpoint 69 must use the causal Sensor/EW resolver rather than the historical static/dynamic range-subtraction abstraction."));
            gates.Add(new(
                "tl1-c69-outcomes-review-only",
                true,
                "Candidate information value, attack eligibility, overload use, ECM/ECCM counterplay, geometry, and win shares are diagnostic evidence only; no target win rate is a release gate."));
        }

        if (study.Id == Tl1EcmPowerCostCounterplayStudyId)
        {
            var variantsById = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
            gates.Add(new(
                "tl1-c70-variant-coverage",
                results.Count == RequiredTl1EcmPowerCostCounterplayVariantCount &&
