            gates.Add(new(
                "tl1-c70-geometry-coverage",
                study.Variants.Count(v => Tl1EcmPowerSweepGeometry(v) == "operational") == 66 &&
                    study.Variants.Count(v => Tl1EcmPowerSweepGeometry(v) == "point-blank") == 33,
