            gates.Add(new(
                "tl1-c70-cost-sweep-coverage",
                Enumerable.Range(1, 5).All(cost =>
                    study.Variants.Count(v => v.SideBEcmNormalPowerCostOverride == cost) == 18),
                "Each ECM normal-power cost from 1 through 5 TP must receive exactly 18 matched variants."));
            gates.Add(new(
                "tl1-c70-clear-control-coverage",
                study.Variants.Count(v => Tl1EcmPowerSweepPackage(v) == "clear") == 9,
                "Checkpoint 70 requires one no-EW clear control for each of the nine geometry/family contexts."));
            gates.Add(new(
                "tl1-c70-point-blank-geometry-locked",
                results.Where(result =>
                        Tl1EcmPowerSweepGeometry(variantsById[result.Id]) == "point-blank")
                    .All(result =>
                        Math.Abs(result.MeanFinalRange) <= tolerance &&
                        Math.Abs(result.MeanMinimumRange) <= tolerance &&
                        Math.Abs(result.MeanMaximumRange) <= tolerance &&
                        Math.Abs(result.MeanMovementHexesA) <= tolerance &&
                        Math.Abs(result.MeanMovementHexesB) <= tolerance),
                "Point-blank lanes must remain at range zero with no movement so same-hex ECM effects are not confounded by geometry."));
            gates.Add(new(
                "tl1-c70-normal-active-power-accounting",
                results.All(result =>
                    Math.Abs(result.MeanActiveSensorPowerCommittedA -
                        result.MeanActiveSensorPoweredTurnsA) <= tolerance &&
                    Math.Abs(result.MeanActiveSensorPowerCommittedB -
                        result.MeanActiveSensorPoweredTurnsB) <= tolerance),
                "Balanced-0 uses one 1-TP normal Active Sensor mode and CP70 forbids Sensor overload; cumulative Active Sensor TP must equal powered evaluations."));
            gates.Add(new(
                "tl1-c70-clear-ew-clean",
                results.Where(result => Tl1EcmPowerSweepPackage(variantsById[result.Id]) == "clear")
                    .All(result => result.MeanEcmPowerCommittedA <= tolerance &&
                        result.MeanEcmPowerCommittedB <= tolerance &&
                        result.MeanEccmPowerCommittedA <= tolerance &&
                        result.MeanEccmPowerCommittedB <= tolerance),
                "Clear controls must not synthesize ECM or ECCM power."));
            gates.Add(new(
                "tl1-c70-ecm-costs-exercised",
