                "Checkpoint 71 must retain 18 operational and 9 fixed same-hex variants."));
            gates.Add(new(
                "tl1-c71-package-coverage",
                new[] { "clear", "jam-p1", "counter-p1" }.All(package =>
                    study.Variants.Count(v => Tl1EcmPowerSweepPackage(v) == package) == 9),
                "Each of the nine contexts must contain clear, ECM-1, and matched ECCM-1 packages."));
            gates.Add(new(
                "tl1-c71-point-blank-geometry-locked",
                results.Where(result =>
                        Tl1EcmPowerSweepGeometry(variantsById[result.Id]) == "point-blank")
                    .All(result =>
                        Math.Abs(result.MeanFinalRange) <= tolerance &&
                        Math.Abs(result.MeanMinimumRange) <= tolerance &&
                        Math.Abs(result.MeanMaximumRange) <= tolerance &&
                        Math.Abs(result.MeanMovementHexesA) <= tolerance &&
