                    bool preservesDirect = !fixedDirectActive || dynamic.MeanDirectShotsFired > 0.01;
                    bool preservesMissile = !fixedMissileActive || dynamic.MeanMissileLaunches > 0.01;
                    if (!preservesDirect || !preservesMissile)
