            {
                Tl1IntegratedTacticalCombatVariantDocument variant = cp95VariantsById[result.Id];
                string label = variant.ProfileLabel ?? string.Empty;
                string source = CrossTlLabelValue(label, "source");
                if (source != "statistical" && source != "diversity") return true;
                int readyRangeA = int.Parse(CrossTlLabelValue(label, "readyRangeA"), CultureInfo.InvariantCulture);
                int readyRangeB = int.Parse(CrossTlLabelValue(label, "readyRangeB"), CultureInfo.InvariantCulture);
                return variant.SideAEngagementReadinessClass == CrossTlLabelValue(label, "readinessA") &&
                    variant.SideBEngagementReadinessClass == CrossTlLabelValue(label, "readinessB") &&
                    variant.SideAMaximumReadyRangeHexes == readyRangeA &&
                    variant.SideBMaximumReadyRangeHexes == readyRangeB;
            });
            gates.Add(new(
                "cross-tl-cp95-explicit-readiness-metadata",
                explicitReadinessMetadataConsistent,
                "CP95 generated variants must carry explicit side-specific readiness class/range metadata identical to the human-readable profile-label metadata."));

            bool sideSpecificConsistent = results.All(result =>
                Math.Abs(result.MeanDirectActionOpportunities -
                    (result.MeanDirectActionOpportunitiesA + result.MeanDirectActionOpportunitiesB)) <= telemetryTolerance &&
                Math.Abs(result.MeanDirectShotsFired -
                    (result.MeanDirectShotsFiredA + result.MeanDirectShotsFiredB)) <= telemetryTolerance &&
                Math.Abs(result.MeanMissileLaunchOpportunities -
                    (result.MeanMissileLaunchOpportunitiesA + result.MeanMissileLaunchOpportunitiesB)) <= telemetryTolerance &&
                Math.Abs(result.MeanMissileLaunches -
                    (result.MeanMissileLaunchesA + result.MeanMissileLaunchesB)) <= telemetryTolerance);
            gates.Add(new(
                "cross-tl-cp95-side-specific-activity-telemetry",
                sideSpecificConsistent,
                "CP95 Side-A/Side-B direct-fire and missile-launch telemetry must sum exactly to the pre-existing aggregate counters."));

            var firingWindowTelemetryFailures = new List<string>();
            foreach (Tl1IntegratedTacticalCombatVariantSummary result in results)
            {
                bool pathOrderingConsistent =
                    result.MeanMinimumRange <= result.MeanMinimumPostMovementRange + telemetryTolerance;
                bool windowCountersConsistent =
                    result.MeanPostMovementFiringWindows >= -telemetryTolerance &&
                    result.MeanPostMovementReadyWindowsA >= -telemetryTolerance &&
                    result.MeanPostMovementReadyWindowsB >= -telemetryTolerance &&
                    result.MeanPostMovementReadyWindowsMutual >= -telemetryTolerance &&
                    result.MeanPostMovementReadyWindowsA <= result.MeanPostMovementFiringWindows + telemetryTolerance &&
                    result.MeanPostMovementReadyWindowsB <= result.MeanPostMovementFiringWindows + telemetryTolerance &&
                    result.MeanPostMovementReadyWindowsMutual <= result.MeanPostMovementReadyWindowsA + telemetryTolerance &&
                    result.MeanPostMovementReadyWindowsMutual <= result.MeanPostMovementReadyWindowsB + telemetryTolerance;
                bool trialPercentagesConsistent =
                    result.PostMovementReadyTrialsPercentA >= -telemetryTolerance && result.PostMovementReadyTrialsPercentA <= 100.0 + telemetryTolerance &&
                    result.PostMovementReadyTrialsPercentB >= -telemetryTolerance && result.PostMovementReadyTrialsPercentB <= 100.0 + telemetryTolerance &&
                    result.PostMovementReadyTrialsPercentMutual >= -telemetryTolerance && result.PostMovementReadyTrialsPercentMutual <= 100.0 + telemetryTolerance &&
                    result.PostMovementReadyTrialsPercentMutual <= result.PostMovementReadyTrialsPercentA + telemetryTolerance &&
                    result.PostMovementReadyTrialsPercentMutual <= result.PostMovementReadyTrialsPercentB + telemetryTolerance;
                if (pathOrderingConsistent && windowCountersConsistent && trialPercentagesConsistent) continue;
                firingWindowTelemetryFailures.Add(
                    $"{result.Id}:pathOrdering={pathOrderingConsistent}:windowCounters={windowCountersConsistent}:trialPercentages={trialPercentagesConsistent}:" +
                    $"pathMin={result.MeanMinimumRange:F6}:postMoveMin={result.MeanMinimumPostMovementRange:F6}:" +
                    $"windows={result.MeanPostMovementFiringWindows:F6}:readyA={result.MeanPostMovementReadyWindowsA:F6}:" +
                    $"readyB={result.MeanPostMovementReadyWindowsB:F6}:readyMutual={result.MeanPostMovementReadyWindowsMutual:F6}:" +
                    $"readyTrialsA={result.PostMovementReadyTrialsPercentA:F6}%:readyTrialsB={result.PostMovementReadyTrialsPercentB:F6}%:" +
                    $"readyTrialsMutual={result.PostMovementReadyTrialsPercentMutual:F6}%");
            }
            bool firingWindowTelemetryConsistent = firingWindowTelemetryFailures.Count == 0;
            gates.Add(new(
                "cross-tl-cp95-firing-window-telemetry",
                firingWindowTelemetryConsistent,
                firingWindowTelemetryConsistent
                    ? "CP95 path closest approach ordering, side/mutual firing-window counters, and per-trial reach percentages are internally bounded and reconciled."
                    : "CP95 firing-window telemetry invariant failure(s): " +
                        string.Join(" | ", firingWindowTelemetryFailures.Take(12))));

            // Structural maximum-ready-range metadata is a screening estimate derived from
            // the declared Sensor/EW context. Runtime EW doctrine can legally produce a Firm
            // solution outside that static estimate (for example when the opponent does not
            // activate ECM). Preserve that divergence as review telemetry; it is not a
            // firing-window counter-integrity failure.
            var runtimeActionOutsideStructuralReadyEstimate = new List<string>();
            foreach (Tl1IntegratedTacticalCombatVariantSummary result in results)
            {
                Tl1IntegratedTacticalCombatVariantDocument variant = cp95VariantsById[result.Id];
                string label = variant.ProfileLabel ?? string.Empty;
                string source = CrossTlLabelValue(label, "source");
                if (source != "statistical" && source != "diversity") continue;

                void Capture(string side, WeaponFamily family, double readyTrialPercent,
                    double directShots, double missileLaunches)
                {
                    double actions = family == WeaponFamily.Missile ? missileLaunches : directShots;
                    if (!RuntimeActionOutsideStructuralReadyEstimate(actions, readyTrialPercent)) return;
                    runtimeActionOutsideStructuralReadyEstimate.Add(
                        $"{result.Id}/Side{side}:family={family}:actions={actions:F3}:readyTrials={readyTrialPercent:F3}%:" +
                        $"pathMin={result.MeanMinimumRange:F3}:postMoveMin={result.MeanMinimumPostMovementRange:F3}");
                }

                Capture("A", result.SideAFamily, result.PostMovementReadyTrialsPercentA,
                    result.MeanDirectShotsFiredA, result.MeanMissileLaunchesA);
                Capture("B", result.SideBFamily, result.PostMovementReadyTrialsPercentB,
                    result.MeanDirectShotsFiredB, result.MeanMissileLaunchesB);
            }
            gates.Add(new(
                "cross-tl-cp95-runtime-action-vs-structural-readiness-review",
                true,
                runtimeActionOutsideStructuralReadyEstimate.Count == 0
                    ? "No runtime family-appropriate action occurred outside the precomputed structural maximum-ready-range estimate."
                    : $"{runtimeActionOutsideStructuralReadyEstimate.Count} side-variant(s) produced legal runtime family-appropriate action outside the precomputed structural ready-range estimate; retained as review evidence rather than a telemetry-integrity failure: " +
                        string.Join(" | ", runtimeActionOutsideStructuralReadyEstimate.Take(12))));

            var fixedReferenceTelemetryFailures = new List<string>();
            var activityGroups = new Dictionary<string, (int Variants, double Opportunities, double Actions)>(StringComparer.Ordinal);
            var movementExcludedSides = new List<string>();
            foreach (Tl1IntegratedTacticalCombatVariantSummary result in results)
            {
                Tl1IntegratedTacticalCombatVariantDocument variant = cp95VariantsById[result.Id];
                string label = variant.ProfileLabel ?? string.Empty;
                string source = CrossTlLabelValue(label, "source");
                if (source != "statistical" && source != "diversity") continue;
                string geometry = CrossTlLabelValue(label, "geometry");
                bool dynamic = geometry.StartsWith("dynamic-", StringComparison.Ordinal);
                void AddSide(
                    string side,
                    WeaponFamily family,
                    string readiness,
                    double readyTrialPercent,
                    double directOpportunities,
                    double directShots,
                    double missileOpportunities,
                    double missileLaunches)
                {
                    bool structurallyExpected = CrossTlReadinessIsActive(readiness, geometry);
                    if (!structurallyExpected) return;
                    if (readyTrialPercent <= telemetryTolerance)
                    {
                        string detail =
                            $"{result.Id}/Side{side}:postMovementReadyTrials={readyTrialPercent:F3}%:pathMin={result.MeanMinimumRange:F3}:postMoveMin={result.MeanMinimumPostMovementRange:F3}";
                        if (dynamic)
                        {
                            movementExcludedSides.Add(detail);
                        }
                        else
                        {
                            fixedReferenceTelemetryFailures.Add(detail);
                        }
                        return;
                    }
                    double opportunities = family == WeaponFamily.Missile ? missileOpportunities : directOpportunities;
                    double actions = family == WeaponFamily.Missile ? missileLaunches : directShots;
                    string key = string.Join("|", geometry, side, family.ToString(), readiness);
                    (int Variants, double Opportunities, double Actions) current = activityGroups.GetValueOrDefault(key);
                    activityGroups[key] = (
                        current.Variants + 1,
                        current.Opportunities + opportunities,
                        current.Actions + actions);
                }

                AddSide("A", result.SideAFamily, variant.SideAEngagementReadinessClass ?? string.Empty,
                    result.PostMovementReadyTrialsPercentA,
                    result.MeanDirectActionOpportunitiesA, result.MeanDirectShotsFiredA,
                    result.MeanMissileLaunchOpportunitiesA, result.MeanMissileLaunchesA);
                AddSide("B", result.SideBFamily, variant.SideBEngagementReadinessClass ?? string.Empty,
                    result.PostMovementReadyTrialsPercentB,
                    result.MeanDirectActionOpportunitiesB, result.MeanDirectShotsFiredB,
                    result.MeanMissileLaunchOpportunitiesB, result.MeanMissileLaunchesB);
            }
            gates.Add(new(
                "cross-tl-cp95-fixed-reference-firing-window-observed",
                fixedReferenceTelemetryFailures.Count == 0,
                fixedReferenceTelemetryFailures.Count == 0
                    ? "Every structurally ready fixed Range-3 side recorded at least one actual post-Movement firing-window-ready trial."
                    : "Fixed structural readiness was not observed in post-Movement firing-window telemetry: " +
                        string.Join(" | ", fixedReferenceTelemetryFailures.Take(12))));

            string[] deadActivityGroups = activityGroups
                .Where(pair => pair.Value.Variants > 0 && pair.Value.Actions <= activityTolerance)
                .Select(pair => $"{pair.Key}: variants={pair.Value.Variants}, opportunities={pair.Value.Opportunities:F3}, actions={pair.Value.Actions:F3}")
                .ToArray();
            gates.Add(new(
                "cross-tl-cp95-contextual-combat-activity",
                activityGroups.Count > 0 && deadActivityGroups.Length == 0,
                deadActivityGroups.Length == 0
                    ? $"All {activityGroups.Count} family/geometry/readiness/side cohorts with an observed post-Movement ready firing window produced side-specific combat activity; {movementExcludedSides.Count} dynamic side-variants remain explicit movement/readiness diagnostics."
                    : "Ready-firing-window family/side cohorts produced zero family-appropriate combat activity: " +
                        string.Join(" | ", deadActivityGroups.Take(12))));

            var individualDiagnostics = new List<string>();
            var blockingInactive = new List<string>();
            foreach (Tl1IntegratedTacticalCombatVariantSummary result in results)
            {
                Tl1IntegratedTacticalCombatVariantDocument variant = cp95VariantsById[result.Id];
                string label = variant.ProfileLabel ?? string.Empty;
                string source = CrossTlLabelValue(label, "source");
                if (source != "statistical" && source != "diversity") continue;
                string geometry = CrossTlLabelValue(label, "geometry");
                string readinessA = variant.SideAEngagementReadinessClass ?? string.Empty;
                string readinessB = variant.SideBEngagementReadinessClass ?? string.Empty;
                if (!CrossTlReadinessIsActive(readinessA, geometry) || !CrossTlReadinessIsActive(readinessB, geometry)) continue;

                double actionsA = result.SideAFamily == WeaponFamily.Missile
                    ? result.MeanMissileLaunchesA : result.MeanDirectShotsFiredA;
                double actionsB = result.SideBFamily == WeaponFamily.Missile
                    ? result.MeanMissileLaunchesB : result.MeanDirectShotsFiredB;
                if (actionsA > activityTolerance && actionsB > activityTolerance) continue;

                string diagnosis = DiagnoseCrossTlObservedEngagementForSelfTest(
                    geometry, readinessA, readinessB, actionsA, actionsB,
                    result.PostMovementReadyTrialsPercentMutual);
                string detail =
                    $"{result.Id}:{diagnosis}:pathMin={result.MeanMinimumRange:F3}:postMoveMin={result.MeanMinimumPostMovementRange:F3}:mutualReadyTrials={result.PostMovementReadyTrialsPercentMutual:F3}%:actionsA={actionsA:F3}:actionsB={actionsB:F3}";
                individualDiagnostics.Add(detail);
                if ((diagnosis == "ready_geometry_reached_but_no_actions" ||
                     diagnosis == "fixed_reference_ready_geometry_not_observed") && result.Trials > 1)
                {
                    blockingInactive.Add(detail);
                }
            }
            gates.Add(new(
                "cross-tl-cp95-individual-observed-engagement",
                blockingInactive.Count == 0,
                blockingInactive.Count == 0
                    ? individualDiagnostics.Count == 0
                        ? "Every structurally mutual-ready statistical/diversity variant produced family-appropriate combat activity."
                        : $"No reached-firing-window zero-action variant was found; {individualDiagnostics.Count} movement/readiness or partial-activity diagnostics remain review evidence: {string.Join(" | ", individualDiagnostics.Take(8))}"
                    : "Structurally mutual-ready variants reached their actual post-Movement firing window but still produced zero family-appropriate actions, or a fixed structural-ready reference failed to record its firing window: " +
                        string.Join(" | ", blockingInactive.Take(12))));
            gates.Add(new(
                "cross-tl-cp95-instrumentation-and-mover-analysis-review-only",
                true,
                "Post-Movement firing-window telemetry, path closest approach, adaptive sampling, diagnostic diversity coverage, mover-order-neutral estimates, initiative sensitivity, population weighting, and technology progression remain human-review screening evidence; CP96 does not automatically promote or retune candidates."));
        }

        if (IsCheckpoint57Study(study.Id))
        {
            gates.Add(new(
                "tl4-foundation-two-main-telemetry",
                study.Id == Tl4FoundationTransitionStudyId
                    ? results.Where(r => r.ProfileLabel == "tl4-r57-dual-main-transition")
                        .Any(r => r.MeanDirectActionOpportunities + r.MeanMissileLaunchOpportunities > 2.0)
                    : results.Any(r => r.MeanDirectActionOpportunities + r.MeanMissileLaunchOpportunities > 2.0),
                "Checkpoint 57 must expose genuine second-main attack opportunities without artificial fire-control suppression."));
        }

        if (IsCheckpoint58Study(study.Id))
        {
            gates.Add(new(
                "tl4-r58-single-main-contract",
                study.Variants.All(v => v.SideASecondaryFamily is null && v.SideBSecondaryFamily is null),
                "Checkpoint 58 standard-player TL4 screens must remain single-main on both sides."));
            gates.Add(new(
                "tl4-r58-telemetry-observed",
                results.Any(r => r.MeanDirectActionOpportunities + r.MeanMissileLaunchOpportunities > 0.0) &&
                    results.All(r => r.MeanPreventedInsufficientPower >= 0.0 &&
                        r.MeanShieldArmorPrevented >= 0.0 &&
                        r.MeanArmorDamagePrevented >= 0.0),
                "Checkpoint 58 must retain combat, power-pressure, shield-hardening, and armor-prevention telemetry."));
        }

        if (IsTl3CandidateStudy(study.Id))
        {
            gates.Add(new(
                "tl3-candidate-profile-coverage",
                study.Id != Tl3StandardProfileStudyId ||
                    new[] { "tl3-capacity-control", "tl3-balanced-candidate", "tl3-output-forward-control" }
                        .All(id => results.Any(result =>
                            result.SideAProfileId == id || result.SideBProfileId == id)),
                "Checkpoint 54 standard-profile screening must exercise all three TL3 candidate vectors; later TL3 studies may use the balanced candidate or explicit structural control only."));
            if (study.Id != Tl3StandardProfileStudyId)
            {
                gates.Add(new(
                    "tl3-second-bay-action-telemetry",
                    results.Any(result =>
                        result.MeanDirectActionOpportunities +
                        result.MeanMissileLaunchOpportunities > 2.0),
                    "At least one Checkpoint 54 two-bay variant must expose more than the one-bay pair's two attack opportunities per turn on average."));
            }
        }

        if (IsTl3LowTechCapstoneStudy(study.Id))
        {
            gates.Add(new(
                "tl3-lowtech-one-main-contract",
                study.Variants.All(variant =>
                    variant.SideASecondaryFamily is null &&
                    variant.SideBSecondaryFamily is null),
                "Checkpoint 55 TL3 low-tech-capstone studies must remain single-main; the second main-weapon foundation moves to provisional TL4."));
            gates.Add(new(
                "tl3-lowtech-profile-coverage",
                study.Id != Tl3LowTechProfileStudyId ||
                    new[]
                    {
                        "tl3-lowtech-control",
                        "tl3-offense-refinement",
                        "tl3-defense-refinement",
                        "tl3-mature-lowtech-candidate",
                    }.All(id => results.Any(result =>
                        result.SideAProfileId == id || result.SideBProfileId == id)),
                "Checkpoint 55 profile screening must exercise the control, offense-only, defense-only, and conservative mature low-tech vectors."));
        }

        if (study.Id == PrimaryStudyId)
        {
            Tl1IntegratedMovementMode[] requiredModes =
            {
                Tl1IntegratedMovementMode.HoldRange2,
                Tl1IntegratedMovementMode.HoldRange4,
                Tl1IntegratedMovementMode.ScriptedPursuit,
                Tl1IntegratedMovementMode.PreferredRange,
            };
            gates.Add(new(
                "movement-mode-coverage",
                requiredModes.All(mode =>
                    results.Any(result => result.MovementMode == mode)),
                "The retained fixed, scripted-pursuit, and preferred-range modes must run."));
            gates.Add(new(
                "immobile-order-coercion-observed",
                results.Sum(result => result.MeanStlUnavailableCoercions) > 0.0,
                "At least one damaged STL drive must produce a genuine movement coercion."));
        }
        else if (study.Id == DiagnosticStudyId)
        {
            gates.Add(new(
                "diagnostic-profile-coverage",
                new[]
                {
                    "production-1-2",
                    "godot-3-2",
                    "legacy-4-1",
                    "overload-equivalent-2-2",
                }.All(profile => results.Any(result => result.ProfileLabel == profile)),
                "Production, Godot, legacy, and overload-equivalent movement profiles must run."));
            gates.Add(new(
                "kinetic-knob-coverage",
                new[] { (3, 0), (4, 0), (5, 0), (4, 1) }
                    .All(arm => results.Any(result =>
                        result.KineticDamage == arm.Item1 &&
                        result.KineticArmorPenetration == arm.Item2 &&
                        result.PrimaryArmorProtection == 1)),
                "DAM 3, DAM 4, DAM 5, and DAM 4/APEN 1 kinetic arms must run against the AP 1 diagnostic armor fixture."));
            gates.Add(new(
                "defense-control-coverage",
                new[] { (true, true), (false, true), (true, false), (false, false) }
                    .All(arm => results.Any(result =>
                        result.BaseShieldRechargeEnabled == arm.Item1 &&
                        result.EvasiveManeuversEnabled == arm.Item2)),
                "Shield-recharge and EvM on/off controls must all run."));
            gates.Add(new(
                "disengagement-observed",
                results.Any(result => result.DisengagementPercent > 0.0),
                "At least one pursuit lane must resolve through successful disengagement."));
            gates.Add(new(
                "production-tl-law",
                results.Where(result => result.ProfileLabel == "production-1-2")
                    .All(result => result.SideAStlMovementHexes == 1 &&
                        result.SideBStlMovementHexes == 1 &&
                        result.MissileSpeedHexesPerTurn == 2),
                "Production TL1 lanes must use ship Move 1 and missile Move 2."));
        }
        else if (study.Id == MinimalTacticsStudyId)
        {
            gates.Add(new(
                "minimal-range-grid-coverage",
                new[]
                {
                    Tl1IntegratedMovementMode.HoldRange2,
                    Tl1IntegratedMovementMode.HoldRange3,
                    Tl1IntegratedMovementMode.HoldRange4,
                    Tl1IntegratedMovementMode.HoldRange5,
                }.All(mode => results.Count(result =>
                    result.ProfileLabel == "minimal-primary-ap0" &&
                    result.MovementMode == mode) == 9),
                "The primary AP 0 grid must contain all nine ordered family pairings at Ranges 2-5."));
            gates.Add(new(
                "minimal-primary-no-adaptation",
                results.Where(result =>
                        result.ProfileLabel == "minimal-primary-ap0")
                    .All(result =>
                        result.DamageControl == Tl1IntegratedDamageControlMode.None &&
                        !result.ProtectedCompartmentation &&
                        !result.EvasiveManeuversEnabled &&
                        result.BaseShieldRechargeEnabled &&
                        result.PdsEnabled &&
                        Math.Abs(result.MeanRangeChanges) <= tolerance &&
                        Math.Abs(result.DisengagementPercent) <= tolerance),
                "Primary minimal-tactics lanes must hold range and avoid DamCon, EvM, Protected Compartmentation, and withdrawal adaptation."));
            gates.Add(new(
                "ap1-completeness-grid",
                results.Count(result => result.ProfileLabel == "control-ap1" &&
                    result.PrimaryArmorProtection == 1) == 36,
                "The AP 1 completeness control must repeat the full Range 2-5 family grid."));
            gates.Add(new(
                "single-factor-control-coverage",
                new[]
                {
                    "control-damcon",
                    "control-evm",
                    "control-protected",
                    "control-shield-off",
                }.All(label => results.Count(result =>
                    result.ProfileLabel == label) == 9) &&
                results.Count(result =>
                    result.ProfileLabel == "control-pds-off") == 5,
                "Range 4 single-factor controls must cover DamCon, EvM, Protected Compartmentation, Shield recharge, and missile-facing PDS."));
            gates.Add(new(
                "pds-disable-control",
                results.Where(result => result.ProfileLabel == "control-pds-off")
                    .All(result => !result.PdsEnabled &&
                        Math.Abs(result.MeanPdsAttempts) <= tolerance &&
                        Math.Abs(result.MeanPdsIntercepts) <= tolerance),
                "PDS-disabled controls must produce no PDS attempts or interceptions."));
            gates.Add(new(
                "minimal-production-values",
                results.Where(result => result.ProfileLabel == "minimal-primary-ap0")
                    .All(result =>
                        result.KineticDamage == 4 &&
                        result.KineticArmorPenetration == 0 &&
                        result.PrimaryArmorProtection == 0 &&
                        result.SideAStlMovementHexes == 1 &&
                        result.SideBStlMovementHexes == 1 &&
                        result.MissileSpeedHexesPerTurn == 2),
                "The primary grid must retain Kinetic DAM 4/APEN 0, Armor AP 0, ship Move 1, and missile Move 2."));
        }
        else if (study.Id == Tl2CandidateStudyId)
        {
            string[] candidateIds = technologyProfiles.Keys
                .Where(id => id.StartsWith("tl2-", StringComparison.Ordinal))
                .OrderBy(id => id, StringComparer.Ordinal)
                .ToArray();
            Tl1IntegratedMovementMode[] candidateRanges =
            {
                Tl1IntegratedMovementMode.HoldRange2,
                Tl1IntegratedMovementMode.HoldRange3,
                Tl1IntegratedMovementMode.HoldRange4,
                Tl1IntegratedMovementMode.HoldRange5,
            };
            gates.Add(new(
                "tl2-candidate-comparison-coverage",
                candidateIds.All(candidate =>
                    results.Count(result =>
                        result.SideAProfileId == candidate &&
                        result.SideBProfileId == candidate) == 36 &&
                    results.Count(result =>
                        result.SideAProfileId == candidate &&
                        result.SideBProfileId == "tl1-production") == 36 &&
                    results.Count(result =>
                        result.SideAProfileId == "tl1-production" &&
                        result.SideBProfileId == candidate) == 36),
                "Each TL2 candidate must run 36 same-TL, 36 TL2-vs-TL1, and 36 reciprocal TL1-vs-TL2 variants."));
            gates.Add(new(
                "tl2-candidate-range-grid-coverage",
                candidateRanges.All(mode =>
                    results.Count(result => result.MovementMode == mode) == 81),
                "The TL2 candidate study must contain 81 variants at each fixed range from 2 through 5."));
            gates.Add(new(
                "tl2-candidate-minimal-tactics-contract",
                results.All(result =>
                    result.DamageControl == Tl1IntegratedDamageControlMode.None &&
                    !result.ProtectedCompartmentation &&
                    !result.EvasiveManeuversEnabled &&
                    result.BaseShieldRechargeEnabled &&
                    result.PdsEnabled &&
                    !result.EscapeDisengagementEnabled &&
                    Math.Abs(result.MeanRangeChanges) <= tolerance &&
                    Math.Abs(result.DisengagementPercent) <= tolerance),
                "TL2 candidate lanes must hold range and avoid DamCon, EvM, Protected Compartmentation, and withdrawal adaptation."));
        }
        else if (study.Id == Tl2AttributionStudyId)
        {
            double nullShare = ProfileConditionalWinPercent(
                results,
                "tl2-attr-null-control",
                result => IsFixedRange(result.MovementMode));
            gates.Add(new(
                "tl2-attribution-fixed-cross-coverage",
                RequiredTl2AttributionProfileIds.All(profileId =>
                    CrossProfileResults(results, profileId, IsFixedRange).Count == 72),
                "Every attribution profile must run 72 paired fixed-range cross-TL variants."));
            gates.Add(new(
                "tl2-attribution-movement-coverage",
                Tl2AttributionMovementProfileIds.All(profileId =>
                    CrossProfileResults(results, profileId, IsDynamicMode).Count == 36),
                "The seven movement-aware profiles must run 36 paired dynamic-policy variants each."));
            gates.Add(new(
                "tl2-attribution-same-tl-coverage",
                Tl2AttributionSameTlProfileIds.All(profileId =>
                    results.Count(result =>
                        result.SideAProfileId == profileId &&
                        result.SideBProfileId == profileId &&
                        IsFixedRange(result.MovementMode)) == 36),
                "The identity source and three refinement probes must each run a 36-variant same-TL identity grid."));
            gates.Add(new(
                "tl2-attribution-null-control-neutrality",
                nullShare >= 49.0 && nullShare <= 51.0,
                $"TL2 null-vector fixed-range conditional win share {nullShare:F2}% (expected 49-51%)."));
            gates.Add(new(
                "tl2-attribution-review-computed",
                RequiredTl2AttributionProfileIds.All(profileId =>
                    ProfileConditionalWinPercent(
                        results,
                        profileId,
                        result => IsFixedRange(result.MovementMode)) is double share &&
                    share >= 0.0 && share <= 100.0),
                "Every attribution profile must produce a bounded fixed-range conditional win share."));
            gates.Add(new(
                "tl2-refinement-review-computed",
                Tl2AttributionSameTlProfileIds.All(profileId =>
                    ProfileConditionalWinPercent(
                        results,
                        profileId,
                        result => IsFixedRange(result.MovementMode)) is double fixedShare &&
                    fixedShare >= 0.0 && fixedShare <= 100.0 &&
