                    : (int?)null,
            opponentAwareRangeVariantCount =
                study.Id == Tl2OpponentAwareRangeStudyId
                    ? RequiredTl2OpponentAwareRangeVariantCount
                    : (int?)null,
            opponentAwareRangePolicyVariantCount =
                study.Id == Tl2OpponentAwareRangeStudyId
                    ? 72
                    : (int?)null,
            opponentAwareRangePreferredControlVariantCount =
                study.Id == Tl2OpponentAwareRangeStudyId
                    ? 72
                    : (int?)null,
            opponentAwareRangeFixedRange5ControlVariantCount =
                study.Id == Tl2OpponentAwareRangeStudyId
                    ? 4
                    : (int?)null,
            opponentAwareRangeLeadingProfileId =
                study.Id == Tl2OpponentAwareRangeStudyId
                    ? "tl2-r45-armor-step-conservative-direct-fire"
                    : null,
            opponentAwareRangePromotionAutomatic =
                study.Id == Tl2OpponentAwareRangeStudyId
                    ? false
                    : (bool?)null,
            failedGates = gates.Count(gate => !gate.Passed),
            gates,
            variants = results,
        };
        string json = JsonSerializer.Serialize(
            summary,
            new JsonSerializerOptions
            {
                WriteIndented = true,
                Converters = { new JsonStringEnumConverter() },
            });
        File.WriteAllText(
            Path.Combine(outputDirectory, "summary.json"),
            json,
            new UTF8Encoding(false));
        string hash = Convert.ToHexString(
                SHA256.HashData(Encoding.UTF8.GetBytes(json)))
            .ToLowerInvariant();
        File.WriteAllText(
            Path.Combine(outputDirectory, "result.sha256.txt"),
            $"{hash}  summary.json{Environment.NewLine}",
            new UTF8Encoding(false));
        if (study.Id == Tl1EwAiDoctrineStudyId)
        {
            WriteTl1EwAiDoctrineEvidenceDraft(
                study, results, aiDoctrineRegistry, trials, hash, outputDirectory);
        }
    }

    private static bool IsAuxiliaryLegalMatrix(
        Tl1IntegratedTacticalCombatVariantSummary result) =>
        result.ProfileLabel is "aux-r48-legal-matrix" or
            "aux-r51-architecture-legal-matrix" or
            "aux-r52-stateful-legal-matrix" or
            "aux-r53-refined-legal-matrix";

    private static bool IsNoAuxiliaryDiagnostic(
        Tl1IntegratedTacticalCombatVariantSummary result) =>
        result.ProfileLabel is "aux-r48-no-aux-diagnostic" or
            "aux-r51-no-aux-diagnostic" or
            "aux-r52-no-aux-diagnostic" or
            "aux-r53-no-aux-diagnostic";


    private static void ValidateTl2AblativeCandidateCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        if (!technologyProfiles.ContainsKey("tl2-production"))
        {
            throw new InvalidOperationException("TL2 Ablative candidate study requires the accepted TL2 production profile.");
        }
        string[] candidateIds =
        {
            "aux-r53-abl-ap0-ai2",
            "aux-r53-abl-ap0-ai3",
            "aux-r53-abl-ap1-ai1",
            "aux-r53-abl-ap1-ai2-control",
        };
        foreach (string id in candidateIds)
        {
            if (!auxiliaryProfiles.TryGetValue(id, out AuxiliaryCombatProfile? profile) ||
                profile is null || profile.TechnologyLevel != 2 || profile.CapacityCost != 1)
            {
                throw new InvalidOperationException($"Missing legal TL2 Ablative candidate '{id}'.");
            }
        }
        if (!auxiliaryProfiles.TryGetValue("aux-r53-abl-none-tl2", out AuxiliaryCombatProfile? none) ||
            none is null || !none.Counterfactual || none.TechnologyLevel != 2 ||
            !auxiliaryProfiles.ContainsKey("aux-r53-abl-evasion-control"))
        {
            throw new InvalidOperationException("TL2 Ablative candidate study requires no-AUX and Evasion controls.");
        }
        string[] labels =
        {
            "aux-r53-ablative-vs-none",
            "aux-r53-ablative-vs-evasion",
            "aux-r53-ablative-head-to-head",
            "aux-r53-ablative-mirror",
        };
        int[] expectedCounts = { 24, 24, 36, 12 };
        for (int i = 0; i < labels.Length; i++)
        {
            if (study.Variants.Count(v => v.ProfileLabel == labels[i]) != expectedCounts[i])
            {
                throw new InvalidOperationException($"TL2 Ablative candidate lane '{labels[i]}' has an unexpected count.");
            }
        }
        if (study.Variants.Any(v =>
            v.SideAProfileId != "tl2-production" || v.SideBProfileId != "tl2-production" ||
            v.SideAFamily != v.SideBFamily ||
            v.MovementMode != Tl1IntegratedMovementMode.OpponentAwareRange ||
            v.InitialRangeHexes != (v.SideAFamily == WeaponFamily.Kinetic ? 3 :
                v.SideAFamily == WeaponFamily.Energy ? 4 : 5) ||
            v.ProtectedCompartmentation ||
            v.DamageControl != Tl1IntegratedDamageControlMode.ComponentFirstReserveOne ||
            !(v.BaseShieldRechargeEnabled ?? true) || !(v.EvasiveManeuversEnabled ?? true) ||
            !(v.PdsEnabled ?? true) || (v.EscapeDisengagementEnabled ?? true) ||
            v.SideABackgroundTacticalPowerCommitment != 0 ||
            v.SideBBackgroundTacticalPowerCommitment != 0))
        {
            throw new InvalidOperationException("TL2 Ablative candidate variants must use the standard same-family opponent-aware combat controls.");
        }
    }

    private static void ValidateAuxiliaryPowerStressCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        string[] requiredProfiles =
        {
            "aux-r53-none-tl1", "aux-r53-none-tl2",
            "aux-r53-tl1-combat-battery", "aux-r53-tl2-combat-battery",
            "aux-r53-tl2-power-capacitor",
        };
        if (requiredProfiles.Any(id => !auxiliaryProfiles.ContainsKey(id)))
        {
            throw new InvalidOperationException("Checkpoint 53 power-stress study is missing a required power-support profile.");
        }
        if (study.Variants.Count(v => v.ProfileLabel == "aux-r53-power-normal-control") != 39 ||
            study.Variants.Count(v => v.ProfileLabel == "aux-r53-power-sustained-stress") != 39)
        {
            throw new InvalidOperationException("Checkpoint 53 power-stress study requires 39 normal and 39 sustained-load variants.");
        }
        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            int tlA = technologyProfiles[v.SideAProfileId!].TechnologyLevel;
            int tlB = technologyProfiles[v.SideBProfileId!].TechnologyLevel;
            if (tlA != tlB || v.SideAFamily != v.SideBFamily ||
                v.MovementMode != Tl1IntegratedMovementMode.OpponentAwareRange ||
                v.DamageControl != Tl1IntegratedDamageControlMode.None ||
                v.ProtectedCompartmentation ||
                !(v.BaseShieldRechargeEnabled ?? true) ||
                (v.EscapeDisengagementEnabled ?? true))
            {
                throw new InvalidOperationException($"Power-stress variant '{v.Id}' violates the diagnostic control contract.");
            }
            int expectedRange = v.SideAFamily == WeaponFamily.Kinetic ? 3 :
                v.SideAFamily == WeaponFamily.Energy ? 4 : 5;
            if (v.InitialRangeHexes != expectedRange)
            {
                throw new InvalidOperationException($"Power-stress variant '{v.Id}' uses the wrong family range.");
            }
            bool stress = v.ProfileLabel == "aux-r53-power-sustained-stress";
            int expectedCommitment = stress ? (tlA == 1 ? 3 : 4) : 0;
            if (v.SideABackgroundTacticalPowerCommitment != expectedCommitment ||
                v.SideBBackgroundTacticalPowerCommitment != expectedCommitment)
            {
                throw new InvalidOperationException($"Power-stress variant '{v.Id}' uses an unexpected sustained load.");
            }
        }
    }

    private static void ValidateTl3CandidateCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        string[] tl3Profiles =
        {
            "tl3-capacity-control",
            "tl3-balanced-candidate",
            "tl3-output-forward-control",
        };
        if (tl3Profiles.Any(id =>
                !technologyProfiles.TryGetValue(id, out TechnologyCombatProfile? p) ||
                p.TechnologyLevel != 3))
        {
            throw new InvalidOperationException(
                "Checkpoint 54 requires the exact three TL3 candidate technology profiles.");
        }
        if (!technologyProfiles.ContainsKey("tl1-production") ||
            !technologyProfiles.ContainsKey("tl2-production") ||
            !auxiliaryProfiles.ContainsKey("aux-r54-none-tl2") ||
            !auxiliaryProfiles.ContainsKey("aux-r54-none-tl3"))
        {
            throw new InvalidOperationException(
                "Checkpoint 54 requires frozen TL1/TL2 controls and the TL3 no-AUX diagnostic.");
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            TechnologyCombatProfile a = technologyProfiles[v.SideAProfileId!];
            TechnologyCombatProfile b = technologyProfiles[v.SideBProfileId!];
            if (v.MovementMode != Tl1IntegratedMovementMode.OpponentAwareRange ||
                v.ProtectedCompartmentation ||
                !(v.BaseShieldRechargeEnabled ?? true) ||
                !(v.EvasiveManeuversEnabled ?? true) ||
                !(v.PdsEnabled ?? true) ||
                (v.EscapeDisengagementEnabled ?? true))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 54 variant '{v.Id}' violates the registered tactical-control contract.");
            }
            if ((v.SideASecondaryFamily is not null && a.TechnologyLevel != 3) ||
                (v.SideBSecondaryFamily is not null && b.TechnologyLevel != 3))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 54 variant '{v.Id}' gives a second weapon bay to a non-TL3 ship.");
            }
        }

        if (study.Id == Tl3StandardProfileStudyId)
        {
            if (study.Variants.Any(v =>
                    v.SideASecondaryFamily is not null ||
                    v.SideBSecondaryFamily is not null ||
                    !auxiliaryProfiles[v.SideAAuxiliaryProfileId!].Counterfactual ||
                    auxiliaryProfiles[v.SideAAuxiliaryProfileId!].CapacityCost != 0 ||
                    !auxiliaryProfiles[v.SideBAuxiliaryProfileId!].Counterfactual ||
                    auxiliaryProfiles[v.SideBAuxiliaryProfileId!].CapacityCost != 0 ||
                    v.DamageControl != Tl1IntegratedDamageControlMode.ComponentFirstReserveOne ||
                    v.SideABackgroundTacticalPowerCommitment != 0 ||
                    v.SideBBackgroundTacticalPowerCommitment != 0))
            {
                throw new InvalidOperationException(
                    "TL3 standard-profile screening must isolate numerical progression with one weapon bay and no AUX effects.");
            }
            foreach (string id in tl3Profiles)
            {
                if (!study.Variants.Any(v =>
                        v.SideAProfileId == id || v.SideBProfileId == id))
                {
                    throw new InvalidOperationException(
                        $"TL3 standard-profile screening does not exercise '{id}'.");
                }
            }
            return;
        }

        if (study.Id == Tl3TwoBayLoadoutStudyId)
        {
            if (study.Variants.Any(v =>
                    !auxiliaryProfiles[v.SideAAuxiliaryProfileId!].Counterfactual ||
                    auxiliaryProfiles[v.SideAAuxiliaryProfileId!].CapacityCost != 0 ||
                    !auxiliaryProfiles[v.SideBAuxiliaryProfileId!].Counterfactual ||
                    auxiliaryProfiles[v.SideBAuxiliaryProfileId!].CapacityCost != 0 ||
                    v.DamageControl != Tl1IntegratedDamageControlMode.ComponentFirstReserveOne ||
                    (technologyProfiles[v.SideAProfileId!].TechnologyLevel == 3) !=
                        (v.SideASecondaryFamily is not null) ||
                    (technologyProfiles[v.SideBProfileId!].TechnologyLevel == 3) !=
                        (v.SideBSecondaryFamily is not null)))
            {
                throw new InvalidOperationException(
                    "TL3 two-bay screening requires exactly two weapon bays on each TL3 side and one bay on each TL2 control side.");
            }
            return;
        }

        if (study.Id == Tl3AuxiliaryLoadoutStudyId)
        {
            string[] normal = auxiliaryProfiles.Values
                .Where(p => p.TechnologyLevel == 3 && !p.Counterfactual &&
                    !p.LegacyIntegratedSuite)
                .Select(p => p.Id)
                .OrderBy(id => id, StringComparer.Ordinal)
                .ToArray();
            if (normal.Length != 13 ||
                normal.Any(id => auxiliaryProfiles[id].CapacityCost != 2) ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r54-aux-legal-matrix") != 507 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r54-aux-no-aux-diagnostic") != 78 ||
                study.Variants.Any(v =>
                    v.SideAProfileId != "tl3-balanced-candidate" ||
                    v.SideBProfileId != "tl3-balanced-candidate" ||
                    v.SideASecondaryFamily != v.SideAFamily ||
                    v.SideBSecondaryFamily != v.SideBFamily ||
                    v.DamageControl != Tl1IntegratedDamageControlMode.ComponentFirstReserveOne))
            {
                throw new InvalidOperationException(
                    "TL3 AUX screening requires thirteen capacity-2 normal loadouts, 507 legal variants, and 78 no-AUX diagnostics in twin-family two-bay combat.");
            }
            return;
        }

        if (study.Id == Tl3PowerEnvelopeStudyId)
        {
            string[] supports =
            {
                "aux-r54-battery-evasion",
                "aux-r54-capacitor-epds",
                "aux-r54-auxiliary-reactor",
            };
            if (supports.Any(id => !auxiliaryProfiles.ContainsKey(id)) ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r54-power-normal") != 24 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r54-power-stress") != 24 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r54-power-stress-pairwise") != 24 ||
                study.Variants.Any(v =>
                    v.SideAProfileId != "tl3-balanced-candidate" ||
                    v.SideBProfileId != "tl3-balanced-candidate" ||
                    v.SideASecondaryFamily is null ||
                    v.SideBSecondaryFamily is null ||
                    v.DamageControl != Tl1IntegratedDamageControlMode.None ||
                    v.SideABackgroundTacticalPowerCommitment !=
                        v.SideBBackgroundTacticalPowerCommitment ||
                    (v.SideABackgroundTacticalPowerCommitment != 0 &&
                     v.SideABackgroundTacticalPowerCommitment != 3)))
            {
                throw new InvalidOperationException(
                    "TL3 power-envelope screening must use the balanced two-bay profile with 24 normal, 24 stressed-vs-none, and 24 stressed pairwise variants.");
            }
        }
    }

    private static void ValidateTl3LowTechCapstoneCoverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        string[] tl3Profiles =
        {
            "tl3-lowtech-control",
            "tl3-offense-refinement",
            "tl3-defense-refinement",
            "tl3-mature-lowtech-candidate",
        };
        if (tl3Profiles.Any(id =>
                !technologyProfiles.TryGetValue(id, out TechnologyCombatProfile? p) ||
                p.TechnologyLevel != 3) ||
            !technologyProfiles.ContainsKey("tl2-production") ||
            !auxiliaryProfiles.ContainsKey("aux-r55-none-tl2") ||
            !auxiliaryProfiles.ContainsKey("aux-r55-none-tl3"))
        {
            throw new InvalidOperationException(
                "Checkpoint 55 requires frozen TL2 controls, the exact four TL3 low-tech candidate profiles, and TL2/TL3 no-AUX diagnostics.");
        }

        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            if (v.SideASecondaryFamily is not null ||
                v.SideBSecondaryFamily is not null)
            {
                throw new InvalidOperationException(
                    $"Checkpoint 55 variant '{v.Id}' violates the single-main TL3 low-tech-capstone contract.");
            }
            if (v.MovementMode != Tl1IntegratedMovementMode.OpponentAwareRange ||
                v.ProtectedCompartmentation ||
                !(v.BaseShieldRechargeEnabled ?? true) ||
                !(v.EvasiveManeuversEnabled ?? true) ||
                !(v.PdsEnabled ?? true) ||
                (v.EscapeDisengagementEnabled ?? true))
            {
                throw new InvalidOperationException(
                    $"Checkpoint 55 variant '{v.Id}' violates the registered tactical-control contract.");
            }
        }

        if (study.Id == Tl3LowTechProfileStudyId)
        {
            if (study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r55-standard-vs-tl2") != 72 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r55-mature-cross-family") != 18 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r55-maturity-attribution") != 12 ||
                study.Variants.Any(v =>
                    !auxiliaryProfiles[v.SideAAuxiliaryProfileId!].Counterfactual ||
                    auxiliaryProfiles[v.SideAAuxiliaryProfileId!].CapacityCost != 0 ||
                    !auxiliaryProfiles[v.SideBAuxiliaryProfileId!].Counterfactual ||
                    auxiliaryProfiles[v.SideBAuxiliaryProfileId!].CapacityCost != 0 ||
                    v.DamageControl != Tl1IntegratedDamageControlMode.ComponentFirstReserveOne ||
                    v.SideABackgroundTacticalPowerCommitment != 0 ||
                    v.SideBBackgroundTacticalPowerCommitment != 0))
            {
                throw new InvalidOperationException(
                    "Checkpoint 55 TL3 profile screening must use 72 TL3-vs-TL2 controls, 18 mature cross-family variants, 12 maturity-attribution variants, one main weapon, and no AUX effects.");
            }
            foreach (string id in tl3Profiles)
            {
                if (!study.Variants.Any(v =>
                        v.SideAProfileId == id || v.SideBProfileId == id))
                {
                    throw new InvalidOperationException(
                        $"Checkpoint 55 TL3 profile screening does not exercise '{id}'.");
                }
            }
            return;
        }

        if (study.Id == Tl3LowTechAuxStudyId)
        {
            string[] normal =
            {
                "aux-r55-kpds-shield-battery",
                "aux-r55-epds-shield-battery",
                "aux-r55-amm-shield-battery",
                "aux-r55-ablative-kpds",
                "aux-r55-ablative-evasion",
                "aux-r55-battery-evasion",
                "aux-r55-capacitor-epds",
                "aux-r55-booster-kpds",
                "aux-r55-stabilizer-epds",
                "aux-r55-kinetic-mag-battery",
                "aux-r55-missile-mag-amm",
                "aux-r55-auxiliary-reactor",
                "aux-r55-battery-amm",
            };
            if (normal.Any(id =>
                    !auxiliaryProfiles.ContainsKey(id) ||
                    auxiliaryProfiles[id].CapacityCost != 2 ||
                    auxiliaryProfiles[id].Counterfactual) ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r55-aux-legal-matrix") != 507 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r55-aux-no-aux-diagnostic") != 78 ||
                study.Variants.Any(v =>
                    v.SideAProfileId != "tl3-mature-lowtech-candidate" ||
                    v.SideBProfileId != "tl3-mature-lowtech-candidate" ||
                    v.DamageControl != Tl1IntegratedDamageControlMode.ComponentFirstReserveOne))
            {
                throw new InvalidOperationException(
                    "Checkpoint 55 TL3 AUX screening requires thirteen legal capacity-2 loadouts, 507 legal comparisons, 78 no-AUX diagnostics, and the mature single-main TL3 profile.");
            }
            return;
        }

        if (study.Id == Tl3LowTechAuxIsolationStudyId)
        {
            string[] isolated =
            {
                "aux-r55-kpds", "aux-r55-epds", "aux-r55-amm",
                "aux-r55-combat-battery", "aux-r55-power-capacitor",
                "aux-r55-ablative", "aux-r55-evasion",
                "aux-r55-shield-battery", "aux-r55-shield-booster",
                "aux-r55-shield-stabilizer", "aux-r55-kinetic-mag",
                "aux-r55-missile-mag", "aux-r55-auxiliary-reactor",
            };
            if (isolated.Any(id => !auxiliaryProfiles.ContainsKey(id)) ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r55-aux-component-isolation") != 78 ||
                study.Variants.Any(v =>
                    v.SideAProfileId != "tl3-mature-lowtech-candidate" ||
                    v.SideBProfileId != "tl3-mature-lowtech-candidate" ||
                    v.DamageControl != Tl1IntegratedDamageControlMode.ComponentFirstReserveOne))
            {
                throw new InvalidOperationException(
                    "Checkpoint 55 TL3 component-isolation screening requires thirteen isolated AUX candidates versus no-AUX controls in both orientations and all three weapon contexts.");
            }
            return;
        }

        if (study.Id == Tl3LowTechPowerStudyId)
        {
            string[] supports =
            {
                "aux-r55-combat-battery",
                "aux-r55-power-capacitor",
                "aux-r55-auxiliary-reactor",
            };
            if (supports.Any(id => !auxiliaryProfiles.ContainsKey(id)) ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r55-power-normal") != 18 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r55-power-stress") != 18 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r55-power-stress-pairwise") != 18 ||
                study.Variants.Any(v =>
                    v.SideAProfileId != "tl3-mature-lowtech-candidate" ||
                    v.SideBProfileId != "tl3-mature-lowtech-candidate" ||
                    v.DamageControl != Tl1IntegratedDamageControlMode.None ||
                    v.SideABackgroundTacticalPowerCommitment !=
                        v.SideBBackgroundTacticalPowerCommitment ||
                    (v.SideABackgroundTacticalPowerCommitment != 0 &&
                     v.SideABackgroundTacticalPowerCommitment != 5)))
            {
                throw new InvalidOperationException(
                    "Checkpoint 55 TL3 power-envelope screening requires isolated Battery, Capacitor, and Auxiliary Reactor profiles with 18 normal, 18 stressed-vs-none, and 18 stressed pairwise variants under a five-point sustained diagnostic load.");
            }
        }
    }

    private static void ValidateCheckpoint56Coverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        string[] requiredProfiles =
        {
            "tl2-production", "tl3-offense-refinement",
            "tl3-offense-plus-hull1", "tl3-offense-plus-ai1",
            "tl3-offense-plus-shield1",
        };
        if (requiredProfiles.Any(id => !technologyProfiles.ContainsKey(id)))
        {
            throw new InvalidOperationException(
                "Checkpoint 56 technology profile catalog is incomplete.");
        }
        if (study.Variants.Any(v =>
                v.SideASecondaryFamily is not null ||
                v.SideBSecondaryFamily is not null))
        {
            throw new InvalidOperationException(
                "Checkpoint 56 TL3 screening remains single-main only.");
        }

        if (study.Id == Tl3DefensiveMicrostepStudyId)
        {
            if (study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-micro-vs-tl2") != 72 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-micro-attribution") != 18 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-micro-pairwise") != 18)
            {
                throw new InvalidOperationException(
                    "Checkpoint 56 defensive microstep matrix shape mismatch.");
            }
            return;
        }

        if (study.Id == Tl3AuxiliaryRetestStudyId)
        {
            if (study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-aux-legal-matrix") != 507 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-aux-no-aux-diagnostic") != 78 ||
                study.Variants.Any(v =>
                    v.SideAProfileId != "tl3-offense-refinement" ||
                    v.SideBProfileId != "tl3-offense-refinement"))
            {
                throw new InvalidOperationException(
                    "Checkpoint 56 two-AUX retest must use the offense-only TL3 base.");
            }
            return;
        }

        if (study.Id == Tl3ShieldBreakpointStudyId)
        {
            if (study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-shield-vs-none") != 48 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-booster-vs-stabilizer") != 24)
            {
                throw new InvalidOperationException(
                    "Checkpoint 56 shield-breakpoint matrix shape mismatch.");
            }
            return;
        }

        if (study.Id == Tl3CrossTlAuxStudyId)
        {
            if (study.Variants.Count != RequiredTl3CrossTlAuxVariantCount ||
                study.Variants.Any(v =>
                    !((v.SideAProfileId == "tl3-offense-refinement" &&
                       v.SideBProfileId == "tl2-production") ||
                      (v.SideBProfileId == "tl3-offense-refinement" &&
                       v.SideAProfileId == "tl2-production"))))
            {
                throw new InvalidOperationException(
                    "Checkpoint 56 cross-TL AUX progression matrix shape mismatch.");
            }
            return;
        }

        if (study.Id == Tl3PowerCharacteristicStudyId)
        {
            string[] atomic =
            {
                "aux-r56-b3g1", "aux-r56-b4g1",
                "aux-r56-b3g2", "aux-r56-b4g2",
                "aux-r56-c2d1", "aux-r56-c3d1",
                "aux-r56-c2d2", "aux-r56-c3d2",
            };
            if (atomic.Any(id => !auxiliaryProfiles.ContainsKey(id)) ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-power-atomic-normal-vs-none") != 48 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-power-atomic-stress-vs-none") != 48 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-battery-characteristic-pairwise") != 36 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-capacitor-characteristic-pairwise") != 36 ||
                atomic.Any(id => auxiliaryProfiles[id].PowerComponents.Count != 1))
            {
                throw new InvalidOperationException(
                    "Checkpoint 56 atomic power-component sweep shape mismatch.");
            }
            return;
        }

        if (study.Id == Tl3EqualCapacityPowerStudyId)
        {
            AuxiliaryCombatProfile[] normal = auxiliaryProfiles.Values
                .Where(p => p.TechnologyLevel == 3 && !p.Counterfactual &&
                    p.CapacityCost == 2)
                .ToArray();
            if (!auxiliaryProfiles.ContainsKey("aux-r56-auxiliary-reactor") ||
                normal.Length != 25 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-equal-cap-vs-reactor-normal") != 144 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-equal-cap-vs-reactor-stress") != 144 ||
                study.Variants.Count(v => v.ProfileLabel ==
                    "tl3-r56-equal-cap-representative-pairwise") != 72 ||
                normal.Where(p => p.Id != "aux-r56-auxiliary-reactor")
                    .Any(p => p.PowerComponents.Count != 2))
            {
                throw new InvalidOperationException(
                    "Checkpoint 56 equal-capacity power matrix must compare twenty-four independent two-component power builds against the two-slot Auxiliary Reactor.");
            }
        }
    }

    private static void ValidateCheckpoint57Coverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        if (!technologyProfiles.TryGetValue("tl3-production", out TechnologyCombatProfile? tl3) ||
            tl3 is null || tl3.TechnologyLevel != 3 ||
            !technologyProfiles.TryGetValue("tl4-foundation-control", out TechnologyCombatProfile? tl4) ||
            tl4 is null || tl4.TechnologyLevel != 4)
        {
            throw new InvalidOperationException("Checkpoint 57 requires frozen TL3 production and TL4 foundation-control profiles.");
        }
        if (tl3.Hull != tl4.Hull || tl3.ArmorIntegrity != tl4.ArmorIntegrity ||
            tl3.ArmorProtection != tl4.ArmorProtection || tl3.ShieldCapacity != tl4.ShieldCapacity ||
            tl3.ShieldBaseRecharge != tl4.ShieldBaseRecharge || tl3.ShieldArmor != tl4.ShieldArmor ||
            tl3.ReactorOutput != tl4.ReactorOutput || tl3.TargetingBonus != tl4.TargetingBonus ||
            tl3.EffectivePdsChance != tl4.EffectivePdsChance || tl3.PdsPower != tl4.PdsPower ||
            tl3.StandardCombatPowerCommitment != tl4.StandardCombatPowerCommitment ||
            tl3.ShipMove != tl4.ShipMove || tl3.MissileMove != tl4.MissileMove ||
            tl3.Kinetic != tl4.Kinetic || tl3.Energy != tl4.Energy || tl3.Missile != tl4.Missile)
        {
            throw new InvalidOperationException("Checkpoint 57 TL4 foundation control must copy TL3 component statistics exactly.");
        }
        if (!auxiliaryProfiles.ContainsKey("aux-r57-none-tl3") ||
            !auxiliaryProfiles.ContainsKey("aux-r57-none-tl4") ||
            !auxiliaryProfiles.ContainsKey("aux-r57-reactor") ||
            !auxiliaryProfiles.ContainsKey("aux-r57-bb") ||
            !auxiliaryProfiles.ContainsKey("aux-r57-cc") ||
            !auxiliaryProfiles.ContainsKey("aux-r57-bc"))
        {
            throw new InvalidOperationException("Checkpoint 57 production AUX catalog is incomplete.");
        }
        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            if (v.MovementMode != Tl1IntegratedMovementMode.OpponentAwareRange ||
                v.ProtectedCompartmentation || !(v.BaseShieldRechargeEnabled ?? true) ||
                !(v.EvasiveManeuversEnabled ?? true) || !(v.PdsEnabled ?? true) ||
                (v.EscapeDisengagementEnabled ?? true) ||
                v.SideABackgroundTacticalPowerCommitment != 0 ||
                v.SideBBackgroundTacticalPowerCommitment != 0)
            {
                throw new InvalidOperationException($"Checkpoint 57 variant '{v.Id}' violates the natural-load tactical-control contract.");
            }
            TechnologyCombatProfile a = technologyProfiles[v.SideAProfileId!];
            TechnologyCombatProfile b = technologyProfiles[v.SideBProfileId!];
            if ((v.SideASecondaryFamily is not null && a.TechnologyLevel != 4) ||
                (v.SideBSecondaryFamily is not null && b.TechnologyLevel != 4))
            {
                throw new InvalidOperationException($"Checkpoint 57 variant '{v.Id}' gives a second main weapon to a non-TL4 ship.");
            }
        }
        if (study.Id == Tl4FoundationTransitionStudyId)
        {
            if (study.Variants.Count(v => v.ProfileLabel == "tl4-r57-capacity-control") != 18 ||
                study.Variants.Count(v => v.ProfileLabel == "tl4-r57-dual-main-transition") != 162)
                throw new InvalidOperationException("Checkpoint 57 TL4 foundation-transition matrix shape mismatch.");
            return;
        }
        if (study.Id == Tl4TwoBayLoadoutStudyId)
        {
            if (study.Variants.Count != RequiredTl4TwoBayLoadoutVariantCount ||
                study.Variants.Any(v => v.SideASecondaryFamily is null || v.SideBSecondaryFamily is null))
                throw new InvalidOperationException("Checkpoint 57 TL4 two-bay loadout matrix shape mismatch.");
            return;
        }
        if (study.Id == Tl4SpecializationResistanceStudyId)
        {
            if (study.Variants.Count != RequiredTl4SpecializationResistanceVariantCount ||
                study.Variants.Any(v =>
                    !((v.SideAProfileId == "tl4-foundation-control" && v.SideBProfileId == "tl3-production") ||
                      (v.SideBProfileId == "tl4-foundation-control" && v.SideAProfileId == "tl3-production"))))
                throw new InvalidOperationException("Checkpoint 57 specialization-resistance matrix shape mismatch.");
            return;
        }
        if (study.Id == Tl4NaturalPowerStudyId)
        {
            string[] full = { "aux-r57-reactor", "aux-r57-bb", "aux-r57-cc", "aux-r57-bc" };
            if (study.Variants.Count(v => v.ProfileLabel == "tl4-r57-power-vs-none") != 48 ||
                study.Variants.Count(v => v.ProfileLabel == "tl4-r57-power-pairwise") != 72 ||
                full.Any(id => !auxiliaryProfiles.ContainsKey(id)))
                throw new InvalidOperationException("Checkpoint 57 natural two-bay power matrix shape mismatch.");
            return;
        }
        if (study.Id == Tl4MixedPowerStudyId)
        {
            if (study.Variants.Count(v => v.ProfileLabel == "tl4-r57-mixed-vs-reactor") != 72 ||
                study.Variants.Count(v => v.ProfileLabel == "tl4-r57-mixed-vs-none") != 72)
                throw new InvalidOperationException("Checkpoint 57 mixed power-flexibility matrix shape mismatch.");
        }
    }

    private static void ValidateCheckpoint58Coverage(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles)
    {
        if (!technologyProfiles.TryGetValue("tl3-production", out TechnologyCombatProfile? tl3) ||
            tl3 is null || tl3.TechnologyLevel != 3 ||
            !technologyProfiles.TryGetValue("tl4-single-control", out TechnologyCombatProfile? tl4Control) ||
            tl4Control is null || tl4Control.TechnologyLevel != 4)
        {
            throw new InvalidOperationException("Checkpoint 58 requires frozen TL3 production and TL4 single-main control profiles.");
        }
        if (tl3.Hull != tl4Control.Hull || tl3.ArmorIntegrity != tl4Control.ArmorIntegrity ||
            tl3.ArmorProtection != tl4Control.ArmorProtection || tl3.ShieldCapacity != tl4Control.ShieldCapacity ||
            tl3.ShieldBaseRecharge != tl4Control.ShieldBaseRecharge || tl3.ShieldArmor != tl4Control.ShieldArmor ||
            tl3.ReactorOutput != tl4Control.ReactorOutput || tl3.TargetingBonus != tl4Control.TargetingBonus ||
            tl3.EffectivePdsChance != tl4Control.EffectivePdsChance || tl3.PdsPower != tl4Control.PdsPower ||
            tl3.StandardCombatPowerCommitment != tl4Control.StandardCombatPowerCommitment ||
            tl3.ShipMove != tl4Control.ShipMove || tl3.MissileMove != tl4Control.MissileMove ||
            tl3.Kinetic != tl4Control.Kinetic || tl3.Energy != tl4Control.Energy || tl3.Missile != tl4Control.Missile)
        {
            throw new InvalidOperationException("Checkpoint 58 TL4 single-main control must copy frozen TL3 component statistics exactly.");
        }

        string[] requiredAux =
        {
            "aux-r57-none-tl3", "aux-r57-none-tl4", "aux-r57-reactor", "aux-r57-bb", "aux-r57-cc", "aux-r57-bc",
            "aux-r58-shield-hardener-s1-p1", "aux-r58-shield-hardener-s1-p2", "aux-r58-shield-hardener-s2-p2",
            "aux-r58-energized-armor-a1-p1", "aux-r58-energized-armor-a1-p2", "aux-r58-energized-armor-a2-p2",
            "aux-r58-shield-hardener-battery", "aux-r58-shield-hardener-capacitor",
            "aux-r58-energized-armor-battery", "aux-r58-energized-armor-capacitor",
        };
        if (requiredAux.Any(id => !auxiliaryProfiles.ContainsKey(id)))
        {
            throw new InvalidOperationException("Checkpoint 58 production/powered-defense AUX catalog is incomplete.");
        }
        foreach (Tl1IntegratedTacticalCombatVariantDocument v in study.Variants)
        {
            if (v.SideASecondaryFamily is not null || v.SideBSecondaryFamily is not null)
            {
                throw new InvalidOperationException($"Checkpoint 58 variant '{v.Id}' violates the one-main standard-player contract.");
            }
            if (v.MovementMode != Tl1IntegratedMovementMode.OpponentAwareRange ||
                v.ProtectedCompartmentation || !(v.BaseShieldRechargeEnabled ?? true) ||
                !(v.EvasiveManeuversEnabled ?? true) || !(v.PdsEnabled ?? true) ||
                (v.EscapeDisengagementEnabled ?? true) ||
                v.SideABackgroundTacticalPowerCommitment != 0 ||
                v.SideBBackgroundTacticalPowerCommitment != 0)
            {
                throw new InvalidOperationException($"Checkpoint 58 variant '{v.Id}' violates the natural-load tactical-control contract.");
            }
        }

        if (study.Id == Tl4SingleMainAxisStudyId)
        {
            string[] expected =
            {
                "tl4-single-control", "tl4-fire-control-foundation", "tl4-output-power-foundation", "tl4-reactor-foundation",
                "tl4-structure-foundation", "tl4-armor-protection-foundation", "tl4-shield-foundation", "tl4-mobility-foundation",
            };
            if (expected.Any(id => study.Variants.Count(v => v.SideAProfileId == id || v.SideBProfileId == id) != 18))
                throw new InvalidOperationException("Checkpoint 58 TL4 axis-screening matrix shape mismatch.");
            return;
        }
        if (study.Id == Tl4FoundationPackageStudyId)
        {
            string[] expected =
            {
                "tl4-package-firecontrol-reactor", "tl4-package-firepower-reactor", "tl4-package-structure-reactor",
                "tl4-package-firepower-structure-reactor", "tl4-package-firepower-ap-reactor", "tl4-package-firepower-mobility-reactor",
            };
            if (expected.Any(id => study.Variants.Count(v => v.SideAProfileId == id || v.SideBProfileId == id) != 18))
                throw new InvalidOperationException("Checkpoint 58 TL4 foundation-package matrix shape mismatch.");
            return;
        }
        if (study.Id == Tl4SingleMainSpecializationResistanceStudyId)
        {
            if (study.Variants.Count != RequiredTl4SingleMainSpecializationResistanceVariantCount ||
                study.Variants.Any(v =>
                    !((technologyProfiles[v.SideAProfileId!].TechnologyLevel == 4 && v.SideBProfileId == "tl3-production") ||
                      (technologyProfiles[v.SideBProfileId!].TechnologyLevel == 4 && v.SideAProfileId == "tl3-production"))))
                throw new InvalidOperationException("Checkpoint 58 TL3 specialization-resistance matrix shape mismatch.");
            return;
        }
        if (study.Id == Tl4PoweredDefenseIsolationStudyId)
        {
            string[] expected =
            {
                "aux-r58-shield-hardener-s1-p1", "aux-r58-shield-hardener-s1-p2", "aux-r58-shield-hardener-s2-p2",
                "aux-r58-energized-armor-a1-p1", "aux-r58-energized-armor-a1-p2", "aux-r58-energized-armor-a2-p2",
            };
            if (expected.Any(id => study.Variants.Count(v => v.SideAAuxiliaryProfileId == id || v.SideBAuxiliaryProfileId == id) != 6))
                throw new InvalidOperationException("Checkpoint 58 powered-defense isolation matrix shape mismatch.");
            return;
        }
        if (study.Id == Tl4PoweredDefensePowerPairingStudyId)
        {
            if (study.Variants.Count != RequiredTl4PoweredDefensePowerPairingVariantCount ||
                study.Variants.Count(v => v.ProfileLabel?.StartsWith("r58-defpair-none-", StringComparison.Ordinal) == true) != 36 ||
                study.Variants.Count(v => v.ProfileLabel?.StartsWith("r58-defpair-base-", StringComparison.Ordinal) == true) != 24)
                throw new InvalidOperationException("Checkpoint 58 powered-defense power-pairing matrix shape mismatch.");
            return;
        }
        if (study.Id == Tl4SingleMainNaturalPowerStudyId)
        {
            string[] full = { "aux-r57-reactor", "aux-r57-bb", "aux-r57-cc", "aux-r57-bc" };
            if (study.Variants.Count != RequiredTl4SingleMainNaturalPowerVariantCount ||
                full.Any(id => !auxiliaryProfiles.ContainsKey(id)) ||
                study.Variants.Count(v => v.ProfileLabel == "r58-power-tl4-output-power-foundation") != 42 ||
                study.Variants.Count(v => v.ProfileLabel == "r58-power-tl4-package-firepower-reactor") != 42)
                throw new InvalidOperationException("Checkpoint 58 single-main natural-power matrix shape mismatch.");
        }
    }

    private static void WriteCheckpoint58AuxiliaryConfigurations(
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> profiles,
        string outputDirectory)
    {
        var lines = new List<string>
        {
            "auxiliary_profile_id,display_name,capacity_cost,auxiliary_reactor_output,shield_hardener_strength,shield_hardener_power,energized_armor_bonus,energized_armor_power,power_component_count,battery_count,battery_charges,battery_gain,capacitor_count,capacitor_capacity,capacitor_charge_rate,capacitor_discharge_rate"
        };
        foreach (AuxiliaryCombatProfile profile in profiles.Values
            .Where(p => p.Id.StartsWith("aux-r58-", StringComparison.Ordinal) ||
                p.Id is "aux-r57-none-tl4" or "aux-r57-reactor" or "aux-r57-bb" or "aux-r57-cc" or "aux-r57-bc")
            .OrderBy(p => p.Id, StringComparer.Ordinal))
        {
            AuxiliaryPowerComponentProfile[] batteries = profile.PowerComponents.Where(c => c.Kind == AuxiliaryPowerComponentKind.CombatBattery).ToArray();
            AuxiliaryPowerComponentProfile[] capacitors = profile.PowerComponents.Where(c => c.Kind == AuxiliaryPowerComponentKind.PowerCapacitor).ToArray();
            lines.Add(string.Join(',', new[]
            {
                CsvQuote(profile.Id), CsvQuote(profile.DisplayName), profile.CapacityCost.ToString(CultureInfo.InvariantCulture),
                profile.AuxiliaryReactorOutput.ToString(CultureInfo.InvariantCulture),
                profile.ShieldHardenerStrength.ToString(CultureInfo.InvariantCulture), profile.ShieldHardenerPower.ToString(CultureInfo.InvariantCulture),
                profile.EnergizedArmorProtectionBonus.ToString(CultureInfo.InvariantCulture), profile.EnergizedArmorPower.ToString(CultureInfo.InvariantCulture),
                profile.PowerComponents.Count.ToString(CultureInfo.InvariantCulture), batteries.Length.ToString(CultureInfo.InvariantCulture),
                batteries.Length == 0 ? string.Empty : string.Join("+", batteries.Select(c => c.CombatBatteryCharges)),
                batteries.Length == 0 ? string.Empty : string.Join("+", batteries.Select(c => c.CombatBatteryGain)),
                capacitors.Length.ToString(CultureInfo.InvariantCulture),
                capacitors.Length == 0 ? string.Empty : string.Join("+", capacitors.Select(c => c.CapacitorCapacity)),
                capacitors.Length == 0 ? string.Empty : string.Join("+", capacitors.Select(c => c.CapacitorChargeRate)),
                capacitors.Length == 0 ? string.Empty : string.Join("+", capacitors.Select(c => c.CapacitorDischargeRate)),
            }));
        }
        File.WriteAllLines(Path.Combine(outputDirectory, "checkpoint-58-auxiliary-configurations.csv"), lines, new UTF8Encoding(false));
    }

