    private static void WriteTl2AblativeCandidateReview(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> profiles,
        string outputDirectory)
    {
        string[] candidates =
        {
            "aux-r53-abl-ap0-ai2", "aux-r53-abl-ap0-ai3",
            "aux-r53-abl-ap1-ai1", "aux-r53-abl-ap1-ai2-control",
        };
        var lines = new List<string>
        {
            "candidate_id,weapon_family,ablative_ap,ablative_ai,conditional_win_vs_no_aux,conditional_win_vs_evasion,automatic_promotion"
        };
        foreach (string candidate in candidates)
        foreach (WeaponFamily family in new[] { WeaponFamily.Kinetic, WeaponFamily.Energy, WeaponFamily.Missile })
        {
            double vsNone = OrientedConditionalWinPercent(results, candidate, "aux-r53-abl-none-tl2", family);
            double vsEvasion = OrientedConditionalWinPercent(results, candidate, "aux-r53-abl-evasion-control", family);
            AuxiliaryCombatProfile p = profiles[candidate];
            lines.Add(string.Join(',', new[]
            {
                CsvQuote(candidate), family.ToString(), p.AblativeProtection.ToString(CultureInfo.InvariantCulture),
                p.AblativeIntegrity.ToString(CultureInfo.InvariantCulture), F(vsNone), F(vsEvasion), "false",
            }));
        }
        File.WriteAllLines(Path.Combine(outputDirectory, "ablative-candidate-review.csv"), lines, new UTF8Encoding(false));
    }

    private static void WriteAuxiliaryPowerStressReview(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> profiles,
        string outputDirectory)
    {
        var lines = new List<string>
        {
            "profile_label,technology_level,weapon_family,auxiliary_id,conditional_win_vs_no_aux,mean_prevented_insufficient_power,automatic_promotion"
        };
        foreach (string label in new[] { "aux-r53-power-normal-control", "aux-r53-power-sustained-stress" })
        foreach (int tl in new[] { 1, 2 })
        foreach (WeaponFamily family in new[] { WeaponFamily.Kinetic, WeaponFamily.Energy, WeaponFamily.Missile })
        {
            string noneId = $"aux-r53-none-tl{tl}";
            string[] ids = tl == 1
                ? new[] { "aux-r53-tl1-combat-battery" }
                : new[] { "aux-r53-tl2-combat-battery", "aux-r53-tl2-power-capacitor" };
            foreach (string id in ids)
            {
                var lane = results.Where(r => r.ProfileLabel == label && r.SideAFamily == family &&
                    ((r.SideAAuxiliaryProfileId == id && r.SideBAuxiliaryProfileId == noneId) ||
                     (r.SideBAuxiliaryProfileId == id && r.SideAAuxiliaryProfileId == noneId))).ToArray();
                double conditional = OrientedConditionalWinPercent(lane, id, noneId, family);
                double prevented = lane.Length == 0 ? 0.0 : lane.Average(r => r.MeanPreventedInsufficientPower);
                lines.Add(string.Join(',', new[]
                {
                    CsvQuote(label), tl.ToString(CultureInfo.InvariantCulture), family.ToString(), CsvQuote(id),
                    F(conditional), F(prevented), "false",
                }));
            }
        }
        File.WriteAllLines(Path.Combine(outputDirectory, "power-stress-review.csv"), lines, new UTF8Encoding(false));
    }

    private static double OrientedConditionalWinPercent(
        IEnumerable<Tl1IntegratedTacticalCombatVariantSummary> source,
        string candidateId,
        string opponentId,
        WeaponFamily family)
    {
        double wins = 0.0;
        double decisive = 0.0;
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in source.Where(r => r.SideAFamily == family))
        {
            if (result.SideAAuxiliaryProfileId == candidateId && result.SideBAuxiliaryProfileId == opponentId)
            {
                wins += result.SideAWinsPercent;
                decisive += result.SideAWinsPercent + result.SideBWinsPercent;
            }
            else if (result.SideBAuxiliaryProfileId == candidateId && result.SideAAuxiliaryProfileId == opponentId)
            {
                wins += result.SideBWinsPercent;
                decisive += result.SideAWinsPercent + result.SideBWinsPercent;
            }
        }
        return decisive <= 0.000001 ? 0.0 : 100.0 * wins / decisive;
    }

    private static void WriteAuxiliaryPerformanceScreeningOutputs(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
        string outputDirectory)
    {
        WriteAuxiliaryProfiles(auxiliaryProfiles, outputDirectory);
        WriteAuxiliaryCoverage(results, outputDirectory);
        WriteAuxiliaryPairwiseSummary(results, auxiliaryProfiles, outputDirectory);
        WriteAuxiliaryChoiceOverview(results, auxiliaryProfiles, outputDirectory);
        WriteSameAuxiliaryMirrorReview(results, auxiliaryProfiles, outputDirectory);
        WriteNoAuxiliaryMirrorReview(results, auxiliaryProfiles, outputDirectory);
        WriteCrossTlAuxiliaryEffectSpace(results, auxiliaryProfiles, outputDirectory);
        WriteNoAuxiliaryDiagnostics(results, auxiliaryProfiles, outputDirectory);
        WriteAuxiliaryEntryFloorReview(results, auxiliaryProfiles, outputDirectory);
    }

