    private static void WriteAuxiliaryPairwiseSummary(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> profiles,
        string outputDirectory)
    {
        var lines = new List<string>
        {
            "technology_band,weapon_family,comparison_group,first_auxiliary_profile_id,first_display_name,second_auxiliary_profile_id,second_display_name,orientation_variant_count,total_trials,decisive_coverage_percent,first_conditional_win_percent,second_conditional_win_percent,mutual_percent,unresolved_percent,maximum_orientation_gap_points,balance_signal"
        };
