            new UTF8Encoding(false));
    }

    private static void WriteAuxiliaryChoiceOverview(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> profiles,
        string outputDirectory)
    {
        var pairRows = results
            .Where(result => IsAuxiliaryLegalMatrix(result))
            .GroupBy(result => result.ComparisonGroup, StringComparer.Ordinal)
            .Select(group =>
            {
                Tl1IntegratedTacticalCombatVariantSummary sample = group.First();
                string firstId = CanonicalFirstAuxiliary(sample, profiles);
                string secondId = CanonicalSecondAuxiliary(sample, profiles);
                return new
                {
                    Band = TechnologyBand(sample),
                    Family = sample.SideAFamily,
                    FirstId = firstId,
                    SecondId = secondId,
                    Aggregate = AggregateAuxiliaryPair(group, firstId, secondId),
                };
            })
            .ToArray();
        var lines = new List<string>
        {
            "technology_band,weapon_family,auxiliary_profile_id,family_id,display_name,valuation_class,opponent_count,pooled_conditional_win_percent,best_pairwise_percent,worst_pairwise_percent,broad_advantage_count,broad_disadvantage_count,compulsory_choice_signal,practical_irrelevance_signal,interpretation"
        };
        foreach (var bandFamily in pairRows.GroupBy(row => (row.Band, row.Family)))
        {
            string[] ids = bandFamily.SelectMany(row => new[]
                { row.FirstId, row.SecondId })
                .Distinct(StringComparer.Ordinal)
                .OrderBy(id => id, StringComparer.Ordinal)
                .ToArray();
            foreach (string id in ids)
            {
                var shares = new List<double>();
                double wins = 0.0;
                double decisive = 0.0;
                int advantages = 0;
                int disadvantages = 0;
                foreach (var row in bandFamily.Where(row =>
                    row.FirstId == id || row.SecondId == id))
                {
                    double share = row.FirstId == id
                        ? row.Aggregate.FirstConditionalWinPercent
                        : row.Aggregate.SecondConditionalWinPercent;
                    shares.Add(share);
                    double pairDecisive = row.Aggregate.DecisiveTrials;
                    wins += pairDecisive * share / 100.0;
                    decisive += pairDecisive;
                    if (share >= 75.0) advantages++;
                    if (share <= 25.0) disadvantages++;
                }
                double pooled = decisive <= 0.0 ? 0.0 : 100.0 * wins / decisive;
                int opponentCount = shares.Count;
                bool compulsory = opponentCount > 0 && pooled >= 70.0 &&
                    advantages >= Math.Max(2, (int)Math.Ceiling(opponentCount / 2.0)) &&
                    disadvantages == 0;
                bool irrelevant = opponentCount > 0 && pooled <= 30.0 &&
                    disadvantages >= Math.Max(2, (int)Math.Ceiling(opponentCount / 2.0)) &&
                    advantages == 0;
                AuxiliaryCombatProfile profile = profiles[id];
                lines.Add(string.Join(',', new[]
                {
                    bandFamily.Key.Band,
                    bandFamily.Key.Family.ToString(),
                    CsvQuote(id),
                    CsvQuote(profile.FamilyId),
                    CsvQuote(profile.DisplayName),
                    CsvQuote(profile.ValuationClass),
                    opponentCount.ToString(CultureInfo.InvariantCulture),
                    F(pooled),
                    F(shares.Count == 0 ? 0.0 : shares.Max()),
                    F(shares.Count == 0 ? 0.0 : shares.Min()),
                    advantages.ToString(CultureInfo.InvariantCulture),
                    disadvantages.ToString(CultureInfo.InvariantCulture),
                    compulsory.ToString(CultureInfo.InvariantCulture),
                    irrelevant.ToString(CultureInfo.InvariantCulture),
                    CsvQuote("Review role expression and opportunity cost; exact parity is not required."),
                }));
            }
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "auxiliary-choice-overview.csv"),
            lines,
            new UTF8Encoding(false));
    }

    private static void WriteSameAuxiliaryMirrorReview(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> profiles,
        string outputDirectory)
    {
        var lines = new List<string>
        {
            "technology_band,weapon_family,auxiliary_profile_id,display_name,trials,side_a_wins_percent,side_b_wins_percent,orientation_difference_points,mutual_percent,unresolved_percent,status"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .Where(result => IsAuxiliaryLegalMatrix(result) &&
                result.SideAProfileId == result.SideBProfileId &&
                result.SideAAuxiliaryProfileId == result.SideBAuxiliaryProfileId)
            .OrderBy(result => TechnologyBand(result), StringComparer.Ordinal)
            .ThenBy(result => result.SideAFamily)
            .ThenBy(result => result.SideAAuxiliaryProfileId, StringComparer.Ordinal))
        {
            double gap = Math.Abs(result.SideAWinsPercent - result.SideBWinsPercent);
            lines.Add(string.Join(',', new[]
            {
                TechnologyBand(result),
                result.SideAFamily.ToString(),
                CsvQuote(result.SideAAuxiliaryProfileId),
                CsvQuote(profiles[result.SideAAuxiliaryProfileId].DisplayName),
                result.Trials.ToString(CultureInfo.InvariantCulture),
                F(result.SideAWinsPercent),
                F(result.SideBWinsPercent),
                F(gap),
                F(result.MutualPercent),
                F(result.UnresolvedPercent),
                gap <= 2.0 ? "stable" : "review_orientation_variance",
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "same-aux-mirror-review.csv"),
            lines,
            new UTF8Encoding(false));
    }

    private static void WriteNoAuxiliaryMirrorReview(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> profiles,
        string outputDirectory)
    {
        var lines = new List<string>
