            "technology_band,weapon_family,no_auxiliary_profile_id,trials,side_a_wins_percent,side_b_wins_percent,orientation_difference_points,mutual_percent,unresolved_percent,status"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .Where(result => IsNoAuxiliaryDiagnostic(result) &&
                profiles[result.SideAAuxiliaryProfileId].Counterfactual &&
                profiles[result.SideBAuxiliaryProfileId].Counterfactual)
            .OrderBy(result => TechnologyBand(result), StringComparer.Ordinal)
            .ThenBy(result => result.SideAFamily))
        {
            double gap = Math.Abs(result.SideAWinsPercent - result.SideBWinsPercent);
            lines.Add(string.Join(',', new[]
            {
                TechnologyBand(result),
                result.SideAFamily.ToString(),
                CsvQuote(result.SideAAuxiliaryProfileId),
                result.Trials.ToString(CultureInfo.InvariantCulture),
                F(result.SideAWinsPercent),
                F(result.SideBWinsPercent),
                F(gap),
                F(result.MutualPercent),
                F(result.UnresolvedPercent),
                gap <= 2.0 ? "stable_counterfactual_baseline" :
                    "review_counterfactual_orientation_variance",
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "no-aux-mirror-review.csv"),
            lines,
            new UTF8Encoding(false));
    }

    private static void WriteCrossTlAuxiliaryEffectSpace(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> profiles,
        string outputDirectory)
    {
        var lines = new List<string>
        {
            "weapon_family,comparison_group,tl1_auxiliary_profile_id,tl1_display_name,tl2_auxiliary_profile_id,tl2_display_name,total_trials,decisive_coverage_percent,tl2_conditional_win_percent,tl1_conditional_win_percent,maximum_orientation_gap_points,progression_signal"
        };
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> group in
            results.Where(result => IsAuxiliaryLegalMatrix(result) &&
                    result.SideAProfileId != result.SideBProfileId)
                .GroupBy(result => result.ComparisonGroup, StringComparer.Ordinal)
                .OrderBy(group => group.Key, StringComparer.Ordinal))
        {
            Tl1IntegratedTacticalCombatVariantSummary sample = group.First();
            string tl1Id = sample.SideAProfileId == "tl1-production"
                ? sample.SideAAuxiliaryProfileId
                : sample.SideBAuxiliaryProfileId;
            string tl2Id = sample.SideAProfileId == "tl2-production"
                ? sample.SideAAuxiliaryProfileId
                : sample.SideBAuxiliaryProfileId;
            AuxiliaryPairAggregate aggregate = AggregateAuxiliaryPair(
                group, tl2Id, tl1Id);
            string signal = aggregate.FirstConditionalWinPercent >= 75.0
                ? "strong_tl2_advantage_review_aux_interaction"
                : aggregate.FirstConditionalWinPercent >= 55.0
                    ? "expected_tl2_advantage"
                    : aggregate.FirstConditionalWinPercent >= 45.0
                        ? "near_even_aux_offsets_tl_step"
                        : "tl1_aux_overcomes_tl_step_review";
            lines.Add(string.Join(',', new[]
            {
                sample.SideAFamily.ToString(),
                CsvQuote(group.Key),
                CsvQuote(tl1Id),
                CsvQuote(profiles[tl1Id].DisplayName),
                CsvQuote(tl2Id),
                CsvQuote(profiles[tl2Id].DisplayName),
                aggregate.TotalTrials.ToString(CultureInfo.InvariantCulture),
                F(aggregate.DecisiveCoveragePercent),
                F(aggregate.FirstConditionalWinPercent),
                F(aggregate.SecondConditionalWinPercent),
                F(aggregate.MaximumOrientationGapPoints),
                signal,
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "cross-tl-auxiliary-effect-space.csv"),
            lines,
            new UTF8Encoding(false));
    }

    private static void WriteNoAuxiliaryDiagnostics(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> profiles,
        string outputDirectory)
    {
        var lines = new List<string>
        {
            "technology_band,weapon_family,comparison_group,auxiliary_profile_id,display_name,total_trials,decisive_coverage_percent,auxiliary_conditional_win_percent,no_aux_conditional_win_percent,maximum_orientation_gap_points,standard_balance_aggregate,interpretation"
        };
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> group in
            results.Where(result => IsNoAuxiliaryDiagnostic(result))
                .GroupBy(result => result.ComparisonGroup, StringComparer.Ordinal)
                .Where(group => group.Any(row =>
                    !profiles[row.SideAAuxiliaryProfileId].Counterfactual ||
                    !profiles[row.SideBAuxiliaryProfileId].Counterfactual))
                .OrderBy(group => group.Key, StringComparer.Ordinal))
        {
            Tl1IntegratedTacticalCombatVariantSummary sample = group.First();
            string auxId = new[]
            {
                sample.SideAAuxiliaryProfileId,
                sample.SideBAuxiliaryProfileId,
            }.First(id => !profiles[id].Counterfactual);
            string noneId = new[]
            {
                sample.SideAAuxiliaryProfileId,
                sample.SideBAuxiliaryProfileId,
            }.First(id => profiles[id].Counterfactual);
            AuxiliaryPairAggregate aggregate = AggregateAuxiliaryPair(
                group, auxId, noneId);
            lines.Add(string.Join(',', new[]
            {
                TechnologyBand(sample),
                sample.SideAFamily.ToString(),
                CsvQuote(group.Key),
                CsvQuote(auxId),
                CsvQuote(profiles[auxId].DisplayName),
                aggregate.TotalTrials.ToString(CultureInfo.InvariantCulture),
                F(aggregate.DecisiveCoveragePercent),
                F(aggregate.FirstConditionalWinPercent),
                F(aggregate.SecondConditionalWinPercent),
                F(aggregate.MaximumOrientationGapPoints),
                false.ToString(CultureInfo.InvariantCulture),
                CsvQuote("Counterfactual absolute-effect diagnostic only; excluded from legal choice balance."),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "no-aux-diagnostics.csv"),
            lines,
            new UTF8Encoding(false));
    }

    private static void WriteAuxiliaryEntryFloorReview(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> profiles,
        string outputDirectory)
    {
        var legal = results.Where(result => IsAuxiliaryLegalMatrix(result)).ToArray();
        var lines = new List<string>
        {
            "auxiliary_family_id,technology_level,profile_id,display_name,valuation_class,legal_variant_appearances,weapon_context_count,counterfactual_variant_appearances,candidate_floor_action,status"
        };
        foreach (AuxiliaryCombatProfile profile in profiles.Values
            .Where(profile => !profile.LegacyIntegratedSuite &&
                !profile.Counterfactual)
            .OrderBy(profile => profile.TechnologyLevel)
            .ThenBy(profile => profile.Id, StringComparer.Ordinal))
        {
            int legalAppearances = legal.Count(result =>
                result.SideAAuxiliaryProfileId == profile.Id ||
                result.SideBAuxiliaryProfileId == profile.Id);
            int weaponContexts = legal.Where(result =>
                    result.SideAAuxiliaryProfileId == profile.Id ||
                    result.SideBAuxiliaryProfileId == profile.Id)
                .Select(result => result.SideAFamily)
                .Distinct()
                .Count();
            int diagnosticAppearances = results.Count(result =>
                IsNoAuxiliaryDiagnostic(result) &&
                (result.SideAAuxiliaryProfileId == profile.Id ||
                 result.SideBAuxiliaryProfileId == profile.Id));
            lines.Add(string.Join(',', new[]
            {
                CsvQuote(profile.FamilyId),
                profile.TechnologyLevel.ToString(CultureInfo.InvariantCulture),
                CsvQuote(profile.Id),
                CsvQuote(profile.DisplayName),
                CsvQuote(profile.ValuationClass),
                legalAppearances.ToString(CultureInfo.InvariantCulture),
                weaponContexts.ToString(CultureInfo.InvariantCulture),
                diagnosticAppearances.ToString(CultureInfo.InvariantCulture),
                "review_results_raise_floor_before_identity_reduction_if_overpowered",
                "candidate_only_not_promoted",
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "auxiliary-entry-floor-review.csv"),
            lines,
            new UTF8Encoding(false));
    }

    private static string TechnologyBand(
        Tl1IntegratedTacticalCombatVariantSummary result) =>
        result.SideAProfileId == result.SideBProfileId
            ? result.SideAProfileId == "tl1-production" ? "TL1v1" : "TL2v2"
            : "TL1v2";

    private static string CanonicalFirstAuxiliary(
        Tl1IntegratedTacticalCombatVariantSummary result,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> profiles)
    {
        if (result.SideAProfileId != result.SideBProfileId)
        {
            return result.SideAProfileId == "tl2-production"
                ? result.SideAAuxiliaryProfileId
                : result.SideBAuxiliaryProfileId;
        }
        return string.Compare(
            result.SideAAuxiliaryProfileId,
            result.SideBAuxiliaryProfileId,
            StringComparison.Ordinal) <= 0
                ? result.SideAAuxiliaryProfileId
                : result.SideBAuxiliaryProfileId;
    }

    private static string CanonicalSecondAuxiliary(
        Tl1IntegratedTacticalCombatVariantSummary result,
        IReadOnlyDictionary<string, AuxiliaryCombatProfile> profiles)
    {
        string first = CanonicalFirstAuxiliary(result, profiles);
        return result.SideAAuxiliaryProfileId == first
            ? result.SideBAuxiliaryProfileId
            : result.SideAAuxiliaryProfileId;
    }

    private static AuxiliaryPairAggregate AggregateAuxiliaryPair(
        IEnumerable<Tl1IntegratedTacticalCombatVariantSummary> rows,
        string firstId,
        string secondId)
    {
        double firstWins = 0.0;
        double secondWins = 0.0;
        double mutual = 0.0;
        double unresolved = 0.0;
        long trials = 0;
        var orientationShares = new List<double>();
        foreach (Tl1IntegratedTacticalCombatVariantSummary row in rows)
        {
            double firstPercent;
            double secondPercent;
            if (firstId == secondId)
            {
                firstPercent = row.SideAWinsPercent;
                secondPercent = row.SideBWinsPercent;
            }
            else
            {
                firstPercent = row.SideAAuxiliaryProfileId == firstId
                    ? row.SideAWinsPercent
                    : row.SideBWinsPercent;
                secondPercent = row.SideAAuxiliaryProfileId == secondId
                    ? row.SideAWinsPercent
                    : row.SideBWinsPercent;
            }
            firstWins += row.Trials * firstPercent / 100.0;
            secondWins += row.Trials * secondPercent / 100.0;
            mutual += row.Trials * row.MutualPercent / 100.0;
            unresolved += row.Trials * row.UnresolvedPercent / 100.0;
            trials += row.Trials;
            double decisivePercent = firstPercent + secondPercent;
            if (decisivePercent > 0.0)
            {
                orientationShares.Add(100.0 * firstPercent / decisivePercent);
            }
        }
        double decisive = firstWins + secondWins;
        double firstShare = decisive <= 0.0 ? 0.0 : 100.0 * firstWins / decisive;
        double secondShare = decisive <= 0.0 ? 0.0 : 100.0 * secondWins / decisive;
        double maxGap = orientationShares.Count <= 1
            ? 0.0
            : orientationShares.Max() - orientationShares.Min();
        return new AuxiliaryPairAggregate(
            trials,
            decisive,
            trials <= 0 ? 0.0 : 100.0 * decisive / trials,
            firstShare,
            secondShare,
            trials <= 0 ? 0.0 : 100.0 * mutual / trials,
            trials <= 0 ? 0.0 : 100.0 * unresolved / trials,
            maxGap);
    }

    private static string AuxiliaryBalanceSignal(AuxiliaryPairAggregate aggregate) =>
        aggregate.DecisiveCoveragePercent < 50.0
            ? "insufficient_decisive_coverage"
            : aggregate.FirstConditionalWinPercent >= 75.0
                ? "first_broad_advantage_review"
                : aggregate.SecondConditionalWinPercent >= 75.0
                    ? "second_broad_advantage_review"
                    : "credible_pairing_or_situational_edge";

    private sealed record AuxiliaryPairAggregate(
        long TotalTrials,
        double DecisiveTrials,
        double DecisiveCoveragePercent,
        double FirstConditionalWinPercent,
        double SecondConditionalWinPercent,
        double MutualPercent,
        double UnresolvedPercent,
        double MaximumOrientationGapPoints);

