    private static void WriteTl2CandidateReview(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var lines = new List<string>
        {
            "candidate_id,comparison_type,mean_candidate_conditional_win_percent,target_percent,within_57_64_review_band,strongest_same_tl_conditional_edge_percent,large_same_tl_edge_variant_count,mean_turns,mean_over_18_turns_percent,mean_mutual_percent,mean_unresolved_percent,variant_count"
        };
        string[] candidates = results
            .SelectMany(result => new[]
            {
                result.SideAProfileId, result.SideBProfileId,
            })
            .Where(id => id.StartsWith("tl2-", StringComparison.Ordinal))
            .Distinct(StringComparer.Ordinal)
            .OrderBy(id => id, StringComparer.Ordinal)
            .ToArray();
        foreach (string candidate in candidates)
        {
            Tl1IntegratedTacticalCombatVariantSummary[] sameTl = results.Where(result =>
                result.SideAProfileId == candidate &&
                result.SideBProfileId == candidate).ToArray();
            double strongestSameTl = 0.0;
            int largeSameTlEdges = 0;
            foreach (Tl1IntegratedTacticalCombatVariantSummary result in sameTl)
            {
                double decisive = result.SideAWinsPercent + result.SideBWinsPercent;
                if (decisive <= 0.0) continue;
                double edge = 100.0 * Math.Max(
                    result.SideAWinsPercent, result.SideBWinsPercent) / decisive;
                strongestSameTl = Math.Max(strongestSameTl, edge);
                if (edge > 80.0) largeSameTlEdges++;
            }
            foreach (string comparisonType in new[] { "same-tl", "tl2-vs-tl1" })
            {
                Tl1IntegratedTacticalCombatVariantSummary[] selected =
                    comparisonType == "same-tl"
                        ? sameTl
                        : results.Where(result =>
                            (result.SideAProfileId == candidate &&
                             result.SideBProfileId == "tl1-production") ||
                            (result.SideBProfileId == candidate &&
                             result.SideAProfileId == "tl1-production")).ToArray();
                if (selected.Length == 0) continue;
                var conditional = new List<double>();
                foreach (Tl1IntegratedTacticalCombatVariantSummary result in selected)
                {
                    double decisive = result.SideAWinsPercent + result.SideBWinsPercent;
                    if (decisive <= 0.0) continue;
                    double wins = comparisonType == "same-tl"
                        ? result.SideAWinsPercent
                        : result.SideAProfileId == candidate
                            ? result.SideAWinsPercent
                            : result.SideBWinsPercent;
                    conditional.Add(wins / decisive * 100.0);
                }
                double meanShare = conditional.Count == 0
                    ? 0.0
                    : conditional.Average();
                lines.Add(string.Join(',', new[]
                {
                    CsvQuote(candidate),
                    comparisonType,
                    F(meanShare),
                    F(60.0),
                    (comparisonType == "tl2-vs-tl1" &&
                        meanShare >= 57.0 && meanShare <= 64.0)
                        .ToString(CultureInfo.InvariantCulture),
                    F(strongestSameTl),
                    largeSameTlEdges.ToString(CultureInfo.InvariantCulture),
                    F(selected.Average(item => item.MeanTurns)),
                    F(selected.Average(item => item.Over18TurnsPercent)),
                    F(selected.Average(item => item.MutualPercent)),
                    F(selected.Average(item => item.UnresolvedPercent)),
                    selected.Length.ToString(CultureInfo.InvariantCulture),
                }));
            }
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "candidate-review.csv"),
            lines,
            new UTF8Encoding(false));
    }

    private static void WriteTl2AttributionOutputs(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        double nullFixed = ProfileConditionalWinPercent(
            results,
            "tl2-attr-null-control",
            result => IsFixedRange(result.MovementMode));
        double identityFixed = ProfileConditionalWinPercent(
            results,
            "tl2-identity-preserving-refinement",
            result => IsFixedRange(result.MovementMode));
        var reviewLines = new List<string>
        {
            "profile_id,analysis_role,attribution_group,fixed_conditional_win_percent,dynamic_conditional_win_percent,fixed_delta_from_null_pp,fixed_delta_from_identity_pp,mean_fixed_turns,mean_dynamic_turns,mean_fixed_over_18_turns_percent,mean_dynamic_over_18_turns_percent,mean_fixed_unresolved_percent,mean_dynamic_unresolved_percent,fixed_variant_count,dynamic_variant_count"
        };
        foreach (string profileId in RequiredTl2AttributionProfileIds)
        {
            IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> fixedRows =
                CrossProfileResults(results, profileId, IsFixedRange);
            IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> dynamicRows =
                CrossProfileResults(results, profileId, IsDynamicMode);
            double fixedShare = ProfileConditionalWinPercent(
                results,
                profileId,
                result => IsFixedRange(result.MovementMode));
            string dynamicShare = dynamicRows.Count == 0
                ? string.Empty
                : F(ProfileConditionalWinPercent(
                    results,
                    profileId,
                    result => IsDynamicMode(result.MovementMode)));
            (string role, string group) = AttributionRole(profileId);
            reviewLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId),
                role,
                group,
                F(fixedShare),
                dynamicShare,
                F(fixedShare - nullFixed),
                F(fixedShare - identityFixed),
                fixedRows.Count == 0
                    ? string.Empty
                    : F(fixedRows.Average(item => item.MeanTurns)),
                dynamicRows.Count == 0
                    ? string.Empty
                    : F(dynamicRows.Average(item => item.MeanTurns)),
                fixedRows.Count == 0
                    ? string.Empty
                    : F(fixedRows.Average(item => item.Over18TurnsPercent)),
                dynamicRows.Count == 0
                    ? string.Empty
                    : F(dynamicRows.Average(item => item.Over18TurnsPercent)),
                fixedRows.Count == 0
                    ? string.Empty
                    : F(fixedRows.Average(item => item.UnresolvedPercent)),
                dynamicRows.Count == 0
                    ? string.Empty
                    : F(dynamicRows.Average(item => item.UnresolvedPercent)),
                fixedRows.Count.ToString(CultureInfo.InvariantCulture),
                dynamicRows.Count.ToString(CultureInfo.InvariantCulture),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "attribution-review.csv"),
            reviewLines,
            new UTF8Encoding(false));

        var effectRows = new List<(string Group, string Line, double Rank)>();
        foreach (string group in Tl2AttributionGroups)
        {
            string addId = $"tl2-attr-add-{group}";
            string removeId = $"tl2-attr-remove-{group}";
            double addShare = ProfileConditionalWinPercent(
                results,
                addId,
                result => IsFixedRange(result.MovementMode));
            double removeShare = ProfileConditionalWinPercent(
                results,
                removeId,
                result => IsFixedRange(result.MovementMode));
            double additiveEffect = addShare - nullFixed;
            double removalEffect = identityFixed - removeShare;
            IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> addDynamic =
                CrossProfileResults(results, addId, IsDynamicMode);
            IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> removeDynamic =
                CrossProfileResults(results, removeId, IsDynamicMode);
            string addDynamicEffect = string.Empty;
            string removeDynamicEffect = string.Empty;
            if (addDynamic.Count > 0 && removeDynamic.Count > 0)
            {
                double nullDynamic = ProfileConditionalWinPercent(
                    results,
                    "tl2-attr-null-control",
                    result => IsDynamicMode(result.MovementMode));
                double identityDynamic = ProfileConditionalWinPercent(
                    results,
                    "tl2-identity-preserving-refinement",
                    result => IsDynamicMode(result.MovementMode));
                addDynamicEffect = F(ProfileConditionalWinPercent(
                    results,
                    addId,
                    result => IsDynamicMode(result.MovementMode)) - nullDynamic);
                removeDynamicEffect = F(identityDynamic -
                    ProfileConditionalWinPercent(
                        results,
                        removeId,
                        result => IsDynamicMode(result.MovementMode)));
            }
            double average = (additiveEffect + removalEffect) / 2.0;
            string line = string.Join(',', new[]
            {
                group,
                CsvQuote(addId),
                CsvQuote(removeId),
                F(addShare),
                F(removeShare),
                F(additiveEffect),
                F(removalEffect),
                F(average),
                F(removalEffect - additiveEffect),
                addDynamicEffect,
                removeDynamicEffect,
            });
            effectRows.Add((group, line, Math.Abs(average)));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "group-effects.csv"),
            new[]
            {
                "group_id,additive_profile_id,leave_one_out_profile_id,additive_fixed_win_percent,leave_one_out_fixed_win_percent,additive_fixed_effect_pp,leave_one_out_fixed_effect_pp,average_fixed_marginal_pp,interaction_asymmetry_pp,additive_dynamic_effect_pp,leave_one_out_dynamic_effect_pp"
            }.Concat(effectRows
                .OrderByDescending(item => item.Rank)
                .ThenBy(item => item.Group, StringComparer.Ordinal)
                .Select(item => item.Line)),
            new UTF8Encoding(false));

        var refinementLines = new List<string>
        {
            "profile_id,fixed_conditional_win_percent,dynamic_conditional_win_percent,within_fixed_57_64_review_band,within_dynamic_57_64_review_band,strongest_same_tl_conditional_edge_percent,large_same_tl_edge_variant_count,mean_fixed_turns,mean_dynamic_turns,mean_fixed_over_18_turns_percent,mean_dynamic_over_18_turns_percent,mean_fixed_unresolved_percent,mean_dynamic_unresolved_percent"
        };
        foreach (string profileId in Tl2AttributionSameTlProfileIds)
        {
            IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> fixedRows =
                CrossProfileResults(results, profileId, IsFixedRange);
            IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> dynamicRows =
                CrossProfileResults(results, profileId, IsDynamicMode);
            double fixedShare = ProfileConditionalWinPercent(
                results,
                profileId,
                result => IsFixedRange(result.MovementMode));
            double dynamicShare = ProfileConditionalWinPercent(
                results,
                profileId,
                result => IsDynamicMode(result.MovementMode));
            refinementLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId),
                F(fixedShare),
                F(dynamicShare),
                (fixedShare >= 57.0 && fixedShare <= 64.0).ToString(
                    CultureInfo.InvariantCulture),
                (dynamicShare >= 57.0 && dynamicShare <= 64.0).ToString(
                    CultureInfo.InvariantCulture),
                F(StrongestSameTlConditionalEdge(results, profileId)),
                LargeSameTlEdgeCount(results, profileId).ToString(
                    CultureInfo.InvariantCulture),
                F(fixedRows.Average(item => item.MeanTurns)),
                F(dynamicRows.Average(item => item.MeanTurns)),
                F(fixedRows.Average(item => item.Over18TurnsPercent)),
                F(dynamicRows.Average(item => item.Over18TurnsPercent)),
                F(fixedRows.Average(item => item.UnresolvedPercent)),
                F(dynamicRows.Average(item => item.UnresolvedPercent)),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "refinement-review.csv"),
            refinementLines,
            new UTF8Encoding(false));

        var rangeLines = new List<string>
        {
            "profile_id,movement_mode,conditional_win_percent,mean_turns,mean_over_18_turns_percent,mean_mutual_percent,mean_unresolved_percent,variant_count"
        };
        foreach (string profileId in RequiredTl2AttributionProfileIds)
        foreach (Tl1IntegratedMovementMode mode in new[]
        {
            Tl1IntegratedMovementMode.HoldRange2,
            Tl1IntegratedMovementMode.HoldRange3,
            Tl1IntegratedMovementMode.HoldRange4,
            Tl1IntegratedMovementMode.HoldRange5,
            Tl1IntegratedMovementMode.ScriptedPursuit,
            Tl1IntegratedMovementMode.PreferredRange,
        })
        {
            IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> selected =
                CrossProfileResults(results, profileId, item => item == mode);
            if (selected.Count == 0) continue;
            double share = ProfileConditionalWinPercent(
                results,
                profileId,
                result => result.MovementMode == mode);
            rangeLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId),
                mode.ToString(),
                F(share),
                F(selected.Average(item => item.MeanTurns)),
                F(selected.Average(item => item.Over18TurnsPercent)),
                F(selected.Average(item => item.MutualPercent)),
                F(selected.Average(item => item.UnresolvedPercent)),
                selected.Count.ToString(CultureInfo.InvariantCulture),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "range-and-policy-breakdown.csv"),
            rangeLines,
            new UTF8Encoding(false));
    }

    private static PooledOutcomeAggregate PooledProfileOutcomes(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string profileId,
        Func<Tl1IntegratedTacticalCombatVariantSummary, bool> predicate)
    {
        Tl1IntegratedTacticalCombatVariantSummary[] selected = results
            .Where(predicate)
            .Where(result =>
                (result.SideAProfileId == profileId &&
                 result.SideBProfileId == "tl1-production") ||
                (result.SideBProfileId == profileId &&
                 result.SideAProfileId == "tl1-production"))
            .ToArray();
        double profileWins = 0.0;
        double opponentWins = 0.0;
        double mutual = 0.0;
        double unresolved = 0.0;
        long trials = 0;
        var variantShares = new List<double>();
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in selected)
        {
            trials += result.Trials;
            double sideAWins = result.Trials * result.SideAWinsPercent / 100.0;
            double sideBWins = result.Trials * result.SideBWinsPercent / 100.0;
            double candidateWins = result.SideAProfileId == profileId
                ? sideAWins
                : sideBWins;
            double controlWins = result.SideAProfileId == profileId
                ? sideBWins
                : sideAWins;
            profileWins += candidateWins;
            opponentWins += controlWins;
            mutual += result.Trials * result.MutualPercent / 100.0;
            unresolved += result.Trials * result.UnresolvedPercent / 100.0;
            double decisive = candidateWins + controlWins;
            if (decisive > 0.0)
            {
                variantShares.Add(100.0 * candidateWins / decisive);
            }
        }
        double allDecisive = profileWins + opponentWins;
        return new PooledOutcomeAggregate(
            selected.Length,
            trials,
            profileWins,
            opponentWins,
            mutual,
            unresolved,
            trials == 0 ? 0.0 : 100.0 * allDecisive / trials,
            allDecisive <= 0.0 ? 0.0 : 100.0 * profileWins / allDecisive,
            variantShares.Count == 0 ? 0.0 : variantShares.Average(),
            selected.Length == 0 ? 0.0 : selected.Average(item => item.MeanTurns),
            selected.Length == 0 ? 0.0 :
                selected.Average(item => item.Over18TurnsPercent),
            selected.Length == 0 ? 0.0 :
                selected.Average(item => item.DisengagementPercent));
    }

    private static int PairwiseWeaponDifferenceMinimum(
        TechnologyCombatProfile profile)
    {
        ScalingWeaponProfile[] weapons =
        {
            profile.Kinetic,
            profile.Energy,
            profile.Missile,
        };
        int minimum = int.MaxValue;
        for (int first = 0; first < weapons.Length; first++)
        for (int second = first + 1; second < weapons.Length; second++)
        {
            ScalingWeaponProfile a = weapons[first];
            ScalingWeaponProfile b = weapons[second];
            int differences = 0;
            if (a.Damage != b.Damage) differences++;
            int controlA = a.Family == WeaponFamily.Missile
                ? a.GuidanceChance
                : a.AccuracyBonus;
            int controlB = b.Family == WeaponFamily.Missile
                ? b.GuidanceChance
                : b.AccuracyBonus;
            if (controlA != controlB) differences++;
            if (a.MaximumRange != b.MaximumRange) differences++;
            if (a.ShieldPenetration != b.ShieldPenetration) differences++;
            if (a.ArmorPenetration != b.ArmorPenetration) differences++;
            if (a.PowerCost != b.PowerCost) differences++;
            if (a.Ammunition != b.Ammunition) differences++;
            minimum = Math.Min(minimum, differences);
        }
        return minimum == int.MaxValue ? 0 : minimum;
    }

    private static string CoverageClassification(double decisiveCoverage) =>
        decisiveCoverage < 50.0
            ? "insufficient-decisive-coverage"
            : decisiveCoverage < 80.0
                ? "review-low-combat-coverage"
                : "adequate-combat-coverage";

    private static void WriteTl2DefensiveRefinementOutputs(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        IReadOnlyDictionary<string, TechnologyCombatProfile> profiles,
        string outputDirectory)
    {
        var combatLines = new List<string>
        {
            "profile_id,lane,variant_count,total_trials,profile_win_trials,tl1_win_trials,mutual_trials,unresolved_trials,decisive_coverage_percent,pooled_conditional_win_percent,equal_weight_variant_conditional_percent,mean_turns,mean_over_18_turns_percent,coverage_classification,review_note"
        };
        foreach (string profileId in RequiredTl2DefensiveRefinementProfileIds)
        foreach ((string Lane, Func<Tl1IntegratedTacticalCombatVariantSummary, bool> Predicate) lane in
            new (string, Func<Tl1IntegratedTacticalCombatVariantSummary, bool>)[]
            {
                ("fixed-all", result => IsFixedRange(result.MovementMode)),
                ("preferred-range", result => result.MovementMode ==
                    Tl1IntegratedMovementMode.PreferredRange),
                ("pursuit-combat", result => result.ProfileLabel ==
                    "tl2-r45-pursuit-combat"),
            })
        {
            PooledOutcomeAggregate aggregate = PooledProfileOutcomes(
                results, profileId, lane.Predicate);
            combatLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId),
                lane.Lane,
                aggregate.VariantCount.ToString(CultureInfo.InvariantCulture),
                aggregate.Trials.ToString(CultureInfo.InvariantCulture),
                F(aggregate.ProfileWins),
                F(aggregate.OpponentWins),
                F(aggregate.Mutual),
                F(aggregate.Unresolved),
                F(aggregate.DecisiveCoveragePercent),
                F(aggregate.PooledConditionalWinPercent),
                F(aggregate.EqualWeightVariantConditionalPercent),
                F(aggregate.MeanTurns),
                F(aggregate.MeanOver18TurnsPercent),
                CoverageClassification(aggregate.DecisiveCoveragePercent),
                CsvQuote("Review for feel, broad dominance, and choice viability; no exact parity requirement."),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "combat-outcome-review.csv"),
            combatLines,
            new UTF8Encoding(false));

        var movementLines = new List<string>
        {
            "profile_id,lane,profile_orientation,variant_count,total_trials,profile_win_trials,tl1_win_trials,mutual_trials,unresolved_trials,decisive_coverage_percent,pooled_conditional_win_percent,disengagement_percent,mean_final_range,coverage_classification,aggregate_use"
        };
        foreach (string profileId in RequiredTl2DefensiveRefinementProfileIds)
        foreach ((string Lane, string Orientation,
            Func<Tl1IntegratedTacticalCombatVariantSummary, bool> Predicate,
            string AggregateUse) lane in
            new (string, string,
                Func<Tl1IntegratedTacticalCombatVariantSummary, bool>, string)[]
            {
                ("preferred-range", "both-orientations",
                    result => result.MovementMode ==
                        Tl1IntegratedMovementMode.PreferredRange,
                    "ordinary-combat-review"),
                ("pursuit-combat", "profile-side-a-pursuer",
                    result => result.ProfileLabel ==
                        "tl2-r45-pursuit-combat",
                    "ordinary-combat-review"),
                ("escape-control", "profile-side-b-withdrawer",
                    result => result.ProfileLabel ==
                        "tl2-r45-escape-control",
                    "escape-only-excluded-from-combat-aggregate"),
            })
        {
            PooledOutcomeAggregate aggregate = PooledProfileOutcomes(
                results, profileId, lane.Predicate);
            Tl1IntegratedTacticalCombatVariantSummary[] selected = results
                .Where(lane.Predicate)
                .Where(result =>
                    (result.SideAProfileId == profileId &&
                     result.SideBProfileId == "tl1-production") ||
                    (result.SideBProfileId == profileId &&
                     result.SideAProfileId == "tl1-production"))
                .ToArray();
            movementLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId), lane.Lane, lane.Orientation,
                aggregate.VariantCount.ToString(CultureInfo.InvariantCulture),
                aggregate.Trials.ToString(CultureInfo.InvariantCulture),
                F(aggregate.ProfileWins), F(aggregate.OpponentWins),
                F(aggregate.Mutual), F(aggregate.Unresolved),
                F(aggregate.DecisiveCoveragePercent),
                F(aggregate.PooledConditionalWinPercent),
                F(aggregate.MeanDisengagementPercent),
                selected.Length == 0 ? string.Empty :
                    F(selected.Average(item => item.MeanFinalRange)),
                CoverageClassification(aggregate.DecisiveCoveragePercent),
                lane.AggregateUse,
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "movement-outcome-coverage.csv"),
            movementLines,
            new UTF8Encoding(false));

        var progressionLines = new List<string>
        {
            "profile_id,family,fixed_variant_count,fixed_decisive_coverage_percent,fixed_pooled_conditional_win_percent,preferred_decisive_coverage_percent,preferred_pooled_conditional_win_percent,pursuit_decisive_coverage_percent,pursuit_pooled_conditional_win_percent,excessive_same_family_progression_signal,interpretation"
        };
        foreach (string profileId in RequiredTl2DefensiveRefinementProfileIds)
        foreach (WeaponFamily family in new[]
        {
            WeaponFamily.Kinetic,
            WeaponFamily.Energy,
            WeaponFamily.Missile,
        })
        {
            PooledOutcomeAggregate fixedAggregate = PooledProfileOutcomes(
                results,
                profileId,
                result => IsFixedRange(result.MovementMode) &&
                    result.SideAFamily == family &&
                    result.SideBFamily == family);
            PooledOutcomeAggregate preferredAggregate = PooledProfileOutcomes(
                results,
                profileId,
                result => result.MovementMode ==
                        Tl1IntegratedMovementMode.PreferredRange &&
                    result.SideAFamily == family &&
                    result.SideBFamily == family);
            PooledOutcomeAggregate pursuitAggregate = PooledProfileOutcomes(
                results,
                profileId,
                result => result.ProfileLabel ==
                        "tl2-r45-pursuit-combat" &&
                    result.SideAFamily == family &&
                    result.SideBFamily == family);
            bool excessive = fixedAggregate.DecisiveCoveragePercent >= 50.0 &&
                fixedAggregate.PooledConditionalWinPercent > 80.0;
            progressionLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId),
                family.ToString(),
                fixedAggregate.VariantCount.ToString(CultureInfo.InvariantCulture),
                F(fixedAggregate.DecisiveCoveragePercent),
                F(fixedAggregate.PooledConditionalWinPercent),
                F(preferredAggregate.DecisiveCoveragePercent),
                F(preferredAggregate.PooledConditionalWinPercent),
                F(pursuitAggregate.DecisiveCoveragePercent),
                F(pursuitAggregate.PooledConditionalWinPercent),
                excessive.ToString(CultureInfo.InvariantCulture),
                CsvQuote("Era-specific strength is acceptable; review only if broad enough to make alternatives irrelevant."),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "same-family-progression.csv"),
            progressionLines,
            new UTF8Encoding(false));

        var choiceLines = new List<string>
        {
            "profile_id,family,opponent_family,mutual_envelope_variant_count,total_trials,decisive_coverage_percent,pooled_family_win_percent,dominance_signal,irrelevance_signal,choice_viability_classification"
        };
        foreach (string profileId in Tl2DefensiveRefinementSameTlProfileIds)
        foreach (WeaponFamily family in new[]
        {
            WeaponFamily.Kinetic,
            WeaponFamily.Energy,
            WeaponFamily.Missile,
        })
        {
            WeaponFamily[] opponents = new[]
            {
                WeaponFamily.Kinetic,
                WeaponFamily.Energy,
                WeaponFamily.Missile,
            }.Where(item => item != family).ToArray();
            foreach (WeaponFamily? opponent in opponents
                .Select(item => (WeaponFamily?)item)
                .Append(null))
            {
                Tl1IntegratedTacticalCombatVariantSummary[] selected = results
                    .Where(result => result.SideAProfileId == profileId &&
                        result.SideBProfileId == profileId &&
                        IsFixedRange(result.MovementMode) &&
                        result.SideAFamily != result.SideBFamily &&
                        (result.SideAFamily == family ||
                         result.SideBFamily == family) &&
                        (!opponent.HasValue ||
                         result.SideAFamily == opponent.Value ||
                         result.SideBFamily == opponent.Value) &&
                        InitialRange(result.MovementMode) <=
                            WeaponRange(profiles[profileId], result.SideAFamily) &&
                        InitialRange(result.MovementMode) <=
                            WeaponRange(profiles[profileId], result.SideBFamily))
                    .ToArray();
                double familyWins = 0.0;
                double otherWins = 0.0;
                long totalTrials = 0;
                foreach (Tl1IntegratedTacticalCombatVariantSummary result in selected)
                {
                    totalTrials += result.Trials;
                    double sideAWins = result.Trials *
                        result.SideAWinsPercent / 100.0;
                    double sideBWins = result.Trials *
                        result.SideBWinsPercent / 100.0;
                    familyWins += result.SideAFamily == family
                        ? sideAWins
                        : sideBWins;
                    otherWins += result.SideAFamily == family
                        ? sideBWins
                        : sideAWins;
                }
                double decisive = familyWins + otherWins;
                double coverage = totalTrials == 0
                    ? 0.0
                    : 100.0 * decisive / totalTrials;
                double share = decisive <= 0.0
                    ? 0.0
                    : 100.0 * familyWins / decisive;
                bool dominance = coverage >= 50.0 && share > 75.0;
                bool irrelevance = coverage >= 50.0 && share < 25.0;
                string classification = coverage < 50.0
                    ? "insufficient-evidence"
                    : dominance
                        ? "broad-dominance-review"
                        : irrelevance
                            ? "irrelevance-review"
                            : "credible-choice-range";
                choiceLines.Add(string.Join(',', new[]
                {
                    CsvQuote(profileId),
                    family.ToString(),
                    opponent?.ToString() ?? "AllAlternatives",
                    selected.Length.ToString(CultureInfo.InvariantCulture),
                    totalTrials.ToString(CultureInfo.InvariantCulture),
                    F(coverage), F(share),
                    dominance.ToString(CultureInfo.InvariantCulture),
                    irrelevance.ToString(CultureInfo.InvariantCulture),
                    classification,
                }));
            }
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "family-choice-viability.csv"),
            choiceLines,
            new UTF8Encoding(false));

        var rangeLines = new List<string>
        {
            "profile_id,range,variant_count,total_trials,decisive_coverage_percent,pooled_conditional_win_percent,equal_weight_variant_conditional_percent,mean_turns,mean_mutual_percent,mean_unresolved_percent"
        };
        foreach (string profileId in RequiredTl2DefensiveRefinementProfileIds)
        foreach (Tl1IntegratedMovementMode mode in new[]
        {
            Tl1IntegratedMovementMode.HoldRange2,
            Tl1IntegratedMovementMode.HoldRange3,
            Tl1IntegratedMovementMode.HoldRange4,
            Tl1IntegratedMovementMode.HoldRange5,
        })
        {
            PooledOutcomeAggregate aggregate = PooledProfileOutcomes(
                results,
                profileId,
                result => result.MovementMode == mode);
            Tl1IntegratedTacticalCombatVariantSummary[] selected = results
                .Where(result => result.MovementMode == mode)
                .Where(result =>
                    (result.SideAProfileId == profileId &&
                     result.SideBProfileId == "tl1-production") ||
                    (result.SideBProfileId == profileId &&
                     result.SideAProfileId == "tl1-production"))
                .ToArray();
            rangeLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId),
                InitialRange(mode).ToString(CultureInfo.InvariantCulture),
                aggregate.VariantCount.ToString(CultureInfo.InvariantCulture),
                aggregate.Trials.ToString(CultureInfo.InvariantCulture),
                F(aggregate.DecisiveCoveragePercent),
                F(aggregate.PooledConditionalWinPercent),
                F(aggregate.EqualWeightVariantConditionalPercent),
                F(aggregate.MeanTurns),
                selected.Length == 0 ? string.Empty :
                    F(selected.Average(item => item.MutualPercent)),
                selected.Length == 0 ? string.Empty :
                    F(selected.Average(item => item.UnresolvedPercent)),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "range-breakdown.csv"),
            rangeLines,
            new UTF8Encoding(false));
    }

    private sealed record SameProfileFamilyOutcomeAggregate(
        int VariantCount,
        long Trials,
        double FamilyOneWins,
        double FamilyTwoWins,
        double Mutual,
        double Unresolved,
        double DecisiveCoveragePercent,
        double FamilyOneConditionalWinPercent,
        double MeanTurns,
        double MeanFinalRange,
        double MeanMinimumRange,
        double MeanMaximumRange,
        double MeanRangeChanges);

    private static SameProfileFamilyOutcomeAggregate SameProfileFamilyAggregate(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string profileId,
        WeaponFamily? familyOne,
        WeaponFamily? familyTwo,
        Func<Tl1IntegratedTacticalCombatVariantSummary, bool> predicate)
    {
        Tl1IntegratedTacticalCombatVariantSummary[] selected = results
            .Where(result =>
                result.SideAProfileId == profileId &&
                result.SideBProfileId == profileId &&
                predicate(result) &&
                (!familyOne.HasValue || !familyTwo.HasValue ||
                    ((result.SideAFamily == familyOne.Value &&
                      result.SideBFamily == familyTwo.Value) ||
                     (result.SideAFamily == familyTwo.Value &&
                      result.SideBFamily == familyOne.Value))))
            .ToArray();
        long trials = selected.Sum(result => (long)result.Trials);
        double firstWins = 0.0;
        double secondWins = 0.0;
        double mutual = 0.0;
        double unresolved = 0.0;
        double weightedTurns = 0.0;
        double weightedFinalRange = 0.0;
        double weightedMinimumRange = 0.0;
        double weightedMaximumRange = 0.0;
        double weightedRangeChanges = 0.0;
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in selected)
        {
            double sideAWins = result.Trials * result.SideAWinsPercent / 100.0;
            double sideBWins = result.Trials * result.SideBWinsPercent / 100.0;
            if (familyOne.HasValue)
            {
                firstWins += result.SideAFamily == familyOne.Value
                    ? sideAWins
                    : sideBWins;
                secondWins += result.SideAFamily == familyOne.Value
                    ? sideBWins
                    : sideAWins;
            }
            else
            {
                firstWins += sideAWins;
                secondWins += sideBWins;
            }
            mutual += result.Trials * result.MutualPercent / 100.0;
            unresolved += result.Trials * result.UnresolvedPercent / 100.0;
            weightedTurns += result.Trials * result.MeanTurns;
            weightedFinalRange += result.Trials * result.MeanFinalRange;
            weightedMinimumRange += result.Trials * result.MeanMinimumRange;
            weightedMaximumRange += result.Trials * result.MeanMaximumRange;
            weightedRangeChanges += result.Trials * result.MeanRangeChanges;
        }
        double decisive = firstWins + secondWins;
        return new SameProfileFamilyOutcomeAggregate(
            selected.Length,
            trials,
            firstWins,
            secondWins,
            mutual,
            unresolved,
            trials == 0 ? 0.0 : 100.0 * decisive / trials,
            decisive <= 0.0 ? 0.0 : 100.0 * firstWins / decisive,
            trials == 0 ? 0.0 : weightedTurns / trials,
            trials == 0 ? 0.0 : weightedFinalRange / trials,
            trials == 0 ? 0.0 : weightedMinimumRange / trials,
            trials == 0 ? 0.0 : weightedMaximumRange / trials,
            trials == 0 ? 0.0 : weightedRangeChanges / trials);
    }

    private static string RangeChoiceClassification(
        double coverage,
        double familyOneShare,
        WeaponFamily familyOne,
        WeaponFamily familyTwo)
    {
        if (coverage < 50.0) return "insufficient-decisive-evidence";
        if (familyOneShare >= 75.0) return $"{familyOne}-dominant-at-start";
        if (familyOneShare <= 25.0) return $"{familyTwo}-dominant-at-start";
        if (familyOneShare >= 60.0) return $"{familyOne}-advantage";
        if (familyOneShare <= 40.0) return $"{familyTwo}-advantage";
        return "competitive-band";
    }

    private static void WriteTl2DynamicWeaponChoiceOutputs(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var startingRangeLines = new List<string>
        {
            "profile_id,family_one,family_two,starting_range,variant_count,total_trials,decisive_coverage_percent,family_one_pooled_conditional_win_percent,family_two_pooled_conditional_win_percent,mean_turns,mean_final_range,mean_minimum_range,mean_maximum_range,mean_range_changes,range_choice_classification"
        };
        foreach (string profileId in RequiredTl2DynamicWeaponChoiceProfileIds)
        foreach ((WeaponFamily familyOne, WeaponFamily familyTwo) in
            Tl2DynamicWeaponChoicePairs)
        foreach (int initialRange in Enumerable.Range(1, 6))
        {
            SameProfileFamilyOutcomeAggregate aggregate =
                SameProfileFamilyAggregate(
                    results,
                    profileId,
                    familyOne,
                    familyTwo,
                    result => result.ProfileLabel ==
                            "tl2-r46-dynamic-preferred-range" &&
                        result.InitialRangeHexes == initialRange);
            startingRangeLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId),
                familyOne.ToString(),
                familyTwo.ToString(),
                initialRange.ToString(CultureInfo.InvariantCulture),
                aggregate.VariantCount.ToString(CultureInfo.InvariantCulture),
                aggregate.Trials.ToString(CultureInfo.InvariantCulture),
                F(aggregate.DecisiveCoveragePercent),
                F(aggregate.FamilyOneConditionalWinPercent),
                F(100.0 - aggregate.FamilyOneConditionalWinPercent),
                F(aggregate.MeanTurns),
                F(aggregate.MeanFinalRange),
                F(aggregate.MeanMinimumRange),
                F(aggregate.MeanMaximumRange),
                F(aggregate.MeanRangeChanges),
                RangeChoiceClassification(
                    aggregate.DecisiveCoveragePercent,
                    aggregate.FamilyOneConditionalWinPercent,
                    familyOne,
                    familyTwo),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "starting-range-choice-review.csv"),
            startingRangeLines,
            new UTF8Encoding(false));

        var pairSummaryLines = new List<string>
        {
            "profile_id,family_one,family_two,variant_count,total_trials,decisive_coverage_percent,family_one_pooled_conditional_win_percent,family_two_pooled_conditional_win_percent,family_one_credible_start_count,family_two_credible_start_count,family_one_advantage_start_count,family_two_advantage_start_count,family_one_dominant_start_count,family_two_dominant_start_count,competitive_start_count,range_sensitivity_pp,broad_dominance_signal,irrelevance_signal,choice_viability_classification"
        };
        foreach (string profileId in RequiredTl2DynamicWeaponChoiceProfileIds)
        foreach ((WeaponFamily familyOne, WeaponFamily familyTwo) in
            Tl2DynamicWeaponChoicePairs)
        {
            SameProfileFamilyOutcomeAggregate all = SameProfileFamilyAggregate(
                results,
                profileId,
                familyOne,
                familyTwo,
                result => result.ProfileLabel ==
                    "tl2-r46-dynamic-preferred-range");
            var shares = new List<double>();
            var coverages = new List<double>();
            foreach (int initialRange in Enumerable.Range(1, 6))
            {
                SameProfileFamilyOutcomeAggregate atRange =
                    SameProfileFamilyAggregate(
                        results,
                        profileId,
                        familyOne,
                        familyTwo,
                        result => result.ProfileLabel ==
                                "tl2-r46-dynamic-preferred-range" &&
                            result.InitialRangeHexes == initialRange);
                shares.Add(atRange.FamilyOneConditionalWinPercent);
                coverages.Add(atRange.DecisiveCoveragePercent);
            }
            int familyOneCredible = shares.Zip(coverages)
                .Count(item => item.Second >= 50.0 && item.First >= 25.0);
            int familyTwoCredible = shares.Zip(coverages)
                .Count(item => item.Second >= 50.0 && item.First <= 75.0);
            int familyOneAdvantage = shares.Zip(coverages)
                .Count(item => item.Second >= 50.0 && item.First >= 60.0);
            int familyTwoAdvantage = shares.Zip(coverages)
                .Count(item => item.Second >= 50.0 && item.First <= 40.0);
            int familyOneDominant = shares.Zip(coverages)
                .Count(item => item.Second >= 50.0 && item.First >= 75.0);
            int familyTwoDominant = shares.Zip(coverages)
                .Count(item => item.Second >= 50.0 && item.First <= 25.0);
            int competitive = shares.Zip(coverages)
                .Count(item => item.Second >= 50.0 &&
                    item.First > 40.0 && item.First < 60.0);
            double sensitivity = shares.Count == 0
                ? 0.0
                : shares.Max() - shares.Min();
            bool broadDominance = all.DecisiveCoveragePercent >= 50.0 &&
                ((all.FamilyOneConditionalWinPercent > 75.0 &&
                  familyOneDominant >= 4) ||
                 (all.FamilyOneConditionalWinPercent < 25.0 &&
                  familyTwoDominant >= 4));
            bool irrelevance = all.DecisiveCoveragePercent >= 50.0 &&
                (familyOneCredible == 0 || familyTwoCredible == 0);
            string classification = all.DecisiveCoveragePercent < 50.0
                ? "insufficient-decisive-evidence"
                : broadDominance
                    ? "broad-dominance-review"
                    : irrelevance
                        ? "irrelevance-review"
                        : familyOneAdvantage > 0 && familyTwoAdvantage > 0
                            ? "range-defined-asymmetry"
                            : all.FamilyOneConditionalWinPercent is >= 25.0 and <= 75.0
                                ? "credible-asymmetric-choice"
                                : "concentrated-edge-review";
            pairSummaryLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId), familyOne.ToString(), familyTwo.ToString(),
                all.VariantCount.ToString(CultureInfo.InvariantCulture),
                all.Trials.ToString(CultureInfo.InvariantCulture),
                F(all.DecisiveCoveragePercent),
                F(all.FamilyOneConditionalWinPercent),
                F(100.0 - all.FamilyOneConditionalWinPercent),
                familyOneCredible.ToString(CultureInfo.InvariantCulture),
                familyTwoCredible.ToString(CultureInfo.InvariantCulture),
                familyOneAdvantage.ToString(CultureInfo.InvariantCulture),
                familyTwoAdvantage.ToString(CultureInfo.InvariantCulture),
                familyOneDominant.ToString(CultureInfo.InvariantCulture),
                familyTwoDominant.ToString(CultureInfo.InvariantCulture),
                competitive.ToString(CultureInfo.InvariantCulture),
                F(sensitivity),
                broadDominance.ToString(CultureInfo.InvariantCulture),
                irrelevance.ToString(CultureInfo.InvariantCulture),
                classification,
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "pairwise-choice-summary.csv"),
            pairSummaryLines,
            new UTF8Encoding(false));

        var roleLines = new List<string>
        {
            "profile_id,family,range_band,variant_count,total_trials,decisive_coverage_percent,pooled_family_win_percent,advantage_signal,dominance_signal,irrelevance_signal,role_expression_classification"
        };
        foreach (string profileId in RequiredTl2DynamicWeaponChoiceProfileIds)
        foreach (WeaponFamily family in new[]
        {
            WeaponFamily.Kinetic,
            WeaponFamily.Energy,
            WeaponFamily.Missile,
        })
        foreach ((string Band, int Minimum, int Maximum) band in new[]
        {
            ("close-1-2", 1, 2),
            ("middle-3-4", 3, 4),
            ("standoff-5-6", 5, 6),
            ("all-1-6", 1, 6),
        })
        {
            Tl1IntegratedTacticalCombatVariantSummary[] selected = results
                .Where(result => result.SideAProfileId == profileId &&
                    result.SideBProfileId == profileId &&
                    result.ProfileLabel ==
                        "tl2-r46-dynamic-preferred-range" &&
                    result.InitialRangeHexes >= band.Minimum &&
                    result.InitialRangeHexes <= band.Maximum &&
                    (result.SideAFamily == family ||
                     result.SideBFamily == family))
                .ToArray();
            long trials = selected.Sum(result => (long)result.Trials);
            double familyWins = 0.0;
            double opponentWins = 0.0;
            foreach (Tl1IntegratedTacticalCombatVariantSummary result in selected)
            {
                double sideAWins = result.Trials *
                    result.SideAWinsPercent / 100.0;
                double sideBWins = result.Trials *
                    result.SideBWinsPercent / 100.0;
                familyWins += result.SideAFamily == family
                    ? sideAWins
                    : sideBWins;
                opponentWins += result.SideAFamily == family
                    ? sideBWins
                    : sideAWins;
            }
            double decisive = familyWins + opponentWins;
            double coverage = trials == 0
                ? 0.0
                : 100.0 * decisive / trials;
            double share = decisive <= 0.0
                ? 0.0
                : 100.0 * familyWins / decisive;
            bool advantage = coverage >= 50.0 && share >= 60.0;
            bool dominance = coverage >= 50.0 && share >= 75.0;
            bool irrelevance = coverage >= 50.0 && share <= 25.0;
            string classification = coverage < 50.0
                ? "insufficient-decisive-evidence"
                : dominance
                    ? "strong-role-expression-review"
                    : irrelevance
                        ? "weak-role-expression-review"
                        : advantage
                            ? "family-advantage"
                            : share >= 40.0
                                ? "credible-role"
                                : "situational-role";
            roleLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId), family.ToString(), band.Band,
                selected.Length.ToString(CultureInfo.InvariantCulture),
                trials.ToString(CultureInfo.InvariantCulture),
                F(coverage), F(share),
                advantage.ToString(CultureInfo.InvariantCulture),
                dominance.ToString(CultureInfo.InvariantCulture),
                irrelevance.ToString(CultureInfo.InvariantCulture),
                classification,
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "family-role-expression.csv"),
            roleLines,
            new UTF8Encoding(false));

        var orientationLines = new List<string>
        {
            "profile_id,family_one,family_two,starting_range,family_one_as_side_a_conditional_win_percent,family_one_as_side_b_conditional_win_percent,absolute_orientation_difference_pp,side_a_orientation_decisive_coverage_percent,side_b_orientation_decisive_coverage_percent,orientation_review_signal"
        };
        foreach (string profileId in RequiredTl2DynamicWeaponChoiceProfileIds)
        foreach ((WeaponFamily familyOne, WeaponFamily familyTwo) in
            Tl2DynamicWeaponChoicePairs)
        foreach (int initialRange in Enumerable.Range(1, 6))
        {
            Tl1IntegratedTacticalCombatVariantSummary asA = results.Single(result =>
                result.SideAProfileId == profileId &&
                result.SideBProfileId == profileId &&
                result.ProfileLabel == "tl2-r46-dynamic-preferred-range" &&
                result.InitialRangeHexes == initialRange &&
                result.SideAFamily == familyOne &&
                result.SideBFamily == familyTwo);
            Tl1IntegratedTacticalCombatVariantSummary asB = results.Single(result =>
                result.SideAProfileId == profileId &&
                result.SideBProfileId == profileId &&
                result.ProfileLabel == "tl2-r46-dynamic-preferred-range" &&
                result.InitialRangeHexes == initialRange &&
                result.SideAFamily == familyTwo &&
                result.SideBFamily == familyOne);
            double decisiveA = asA.SideAWinsPercent + asA.SideBWinsPercent;
            double decisiveB = asB.SideAWinsPercent + asB.SideBWinsPercent;
            double shareAsA = decisiveA <= 0.0
                ? 0.0
                : 100.0 * asA.SideAWinsPercent / decisiveA;
            double shareAsB = decisiveB <= 0.0
                ? 0.0
                : 100.0 * asB.SideBWinsPercent / decisiveB;
            double difference = Math.Abs(shareAsA - shareAsB);
            orientationLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId), familyOne.ToString(), familyTwo.ToString(),
                initialRange.ToString(CultureInfo.InvariantCulture),
                F(shareAsA), F(shareAsB), F(difference),
                F(decisiveA), F(decisiveB),
                difference > 5.0 ? "orientation-effect-review" : "orientation-stable",
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "orientation-review.csv"),
            orientationLines,
            new UTF8Encoding(false));

        var fixedLines = new List<string>
        {
            "profile_id,family_one,family_two,range,variant_count,total_trials,decisive_coverage_percent,family_one_pooled_conditional_win_percent,family_two_pooled_conditional_win_percent,mean_turns,fixed_control_classification"
        };
        foreach (string profileId in RequiredTl2DynamicWeaponChoiceProfileIds)
        foreach ((WeaponFamily familyOne, WeaponFamily familyTwo) in
            Tl2DynamicWeaponChoicePairs)
        foreach (int range in new[] { 2, 3, 4 })
        {
            SameProfileFamilyOutcomeAggregate aggregate =
                SameProfileFamilyAggregate(
                    results,
                    profileId,
                    familyOne,
                    familyTwo,
                    result => result.ProfileLabel ==
                            "tl2-r46-fixed-mutual-control" &&
                        result.InitialRangeHexes == range);
            fixedLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId), familyOne.ToString(), familyTwo.ToString(),
                range.ToString(CultureInfo.InvariantCulture),
                aggregate.VariantCount.ToString(CultureInfo.InvariantCulture),
                aggregate.Trials.ToString(CultureInfo.InvariantCulture),
                F(aggregate.DecisiveCoveragePercent),
                F(aggregate.FamilyOneConditionalWinPercent),
                F(100.0 - aggregate.FamilyOneConditionalWinPercent),
                F(aggregate.MeanTurns),
                RangeChoiceClassification(
                    aggregate.DecisiveCoveragePercent,
                    aggregate.FamilyOneConditionalWinPercent,
                    familyOne,
                    familyTwo),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "fixed-mutual-control.csv"),
            fixedLines,
            new UTF8Encoding(false));

        var overviewLines = new List<string>
        {
            "profile_id,analysis_role,fixed_variant_count,dynamic_variant_count,dynamic_total_trials,dynamic_decisive_coverage_percent,broad_dominance_pair_count,irrelevance_pair_count,range_defined_pair_count,status,interpretation"
        };
        foreach (string profileId in RequiredTl2DynamicWeaponChoiceProfileIds)
        {
            SameProfileFamilyOutcomeAggregate dynamic =
                SameProfileFamilyAggregate(
                    results,
                    profileId,
                    null,
                    null,
                    result => result.ProfileLabel ==
                        "tl2-r46-dynamic-preferred-range");
            PairViabilityAssessment[] assessments = Tl2DynamicWeaponChoicePairs
                .Select(pair => AssessDynamicPair(
                    results,
                    profileId,
                    pair.First,
                    pair.Second,
                    "tl2-r46-dynamic-preferred-range"))
                .ToArray();
            int dominanceCount = assessments.Count(item => item.BroadDominance);
            int irrelevanceCount = assessments.Count(item => item.Irrelevance);
            int rangeDefinedCount = assessments.Count(
                item => item.RangeDefinedAsymmetry);
            overviewLines.Add(string.Join(',', new[]
            {
                CsvQuote(profileId),
                profileId == "tl2-r45-armor-step-conservative-direct-fire"
                    ? "leading-provisional-reference"
                    : "hull-step-control",
                results.Count(result => result.SideAProfileId == profileId &&
                    result.ProfileLabel ==
                        "tl2-r46-fixed-mutual-control")
                    .ToString(CultureInfo.InvariantCulture),
                dynamic.VariantCount.ToString(CultureInfo.InvariantCulture),
                dynamic.Trials.ToString(CultureInfo.InvariantCulture),
                F(dynamic.DecisiveCoveragePercent),
                dominanceCount.ToString(CultureInfo.InvariantCulture),
                irrelevanceCount.ToString(CultureInfo.InvariantCulture),
                rangeDefinedCount.ToString(CultureInfo.InvariantCulture),
                "candidate-only-not-promoted",
                CsvQuote("Assess whether every family retains a credible tactical role; do not require exact parity."),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "profile-choice-overview.csv"),
            overviewLines,
            new UTF8Encoding(false));
    }

    private sealed record PairViabilityAssessment(
        SameProfileFamilyOutcomeAggregate Aggregate,
        int FamilyOneCredibleStartCount,
        int FamilyTwoCredibleStartCount,
        int FamilyOneAdvantageStartCount,
        int FamilyTwoAdvantageStartCount,
        int FamilyOneDominantStartCount,
        int FamilyTwoDominantStartCount,
        int CompetitiveStartCount,
        double RangeSensitivityPoints,
        bool BroadDominance,
        bool Irrelevance,
        bool RangeDefinedAsymmetry,
        string Classification);

    private static PairViabilityAssessment AssessDynamicPair(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string profileId,
        WeaponFamily familyOne,
        WeaponFamily familyTwo,
        string profileLabel)
    {
        SameProfileFamilyOutcomeAggregate all = SameProfileFamilyAggregate(
            results,
            profileId,
            familyOne,
            familyTwo,
            result => result.ProfileLabel == profileLabel);
        var shares = new List<double>();
        var coverages = new List<double>();
        foreach (int initialRange in Enumerable.Range(1, 6))
        {
            SameProfileFamilyOutcomeAggregate atRange =
                SameProfileFamilyAggregate(
                    results,
                    profileId,
                    familyOne,
                    familyTwo,
                    result => result.ProfileLabel == profileLabel &&
                        result.InitialRangeHexes == initialRange);
            shares.Add(atRange.FamilyOneConditionalWinPercent);
            coverages.Add(atRange.DecisiveCoveragePercent);
        }
        int familyOneCredible = shares.Zip(coverages)
            .Count(item => item.Second >= 50.0 && item.First >= 25.0);
        int familyTwoCredible = shares.Zip(coverages)
            .Count(item => item.Second >= 50.0 && item.First <= 75.0);
        int familyOneAdvantage = shares.Zip(coverages)
            .Count(item => item.Second >= 50.0 && item.First >= 60.0);
        int familyTwoAdvantage = shares.Zip(coverages)
            .Count(item => item.Second >= 50.0 && item.First <= 40.0);
        int familyOneDominant = shares.Zip(coverages)
            .Count(item => item.Second >= 50.0 && item.First >= 75.0);
        int familyTwoDominant = shares.Zip(coverages)
            .Count(item => item.Second >= 50.0 && item.First <= 25.0);
        int competitive = shares.Zip(coverages)
            .Count(item => item.Second >= 50.0 &&
                item.First > 40.0 && item.First < 60.0);
        double sensitivity = shares.Count == 0
            ? 0.0
            : shares.Max() - shares.Min();
        bool broadDominance = all.DecisiveCoveragePercent >= 50.0 &&
            ((all.FamilyOneConditionalWinPercent >= 75.0 &&
              familyOneDominant >= 4) ||
             (all.FamilyOneConditionalWinPercent <= 25.0 &&
              familyTwoDominant >= 4));
        bool irrelevance = familyOneCredible == 0 || familyTwoCredible == 0;
        bool rangeDefined = familyOneAdvantage > 0 && familyTwoAdvantage > 0;
        string classification = all.DecisiveCoveragePercent < 50.0
            ? "insufficient-decisive-evidence"
            : broadDominance
                ? "broad-dominance-review"
                : irrelevance
                    ? "irrelevance-review"
                    : rangeDefined
                        ? "range-defined-asymmetry"
                        : competitive > 0
                            ? "mixed-competitive-choice"
                            : "situational-choice-review";
        return new PairViabilityAssessment(
            all,
            familyOneCredible,
            familyTwoCredible,
            familyOneAdvantage,
            familyTwoAdvantage,
            familyOneDominant,
            familyTwoDominant,
            competitive,
            sensitivity,
            broadDominance,
            irrelevance,
            rangeDefined,
            classification);
    }

    private static OpponentAwareRangeSelection OpponentAwareSelectionFor(
        WeaponFamily ownFamily,
        WeaponFamily targetFamily)
    {
        RangeDecisionDoctrine targetDoctrine = DoctrineFor(targetFamily);
        return OpponentAwareRangeTacticalPolicy.SelectRange(
            DoctrineFor(ownFamily),
            new ObservedTargetSnapshot(
                "target",
                true,
                false,
                true,
                targetDoctrine.PreferredMinimumRangeHexes,
                targetDoctrine.MaximumUsefulWeaponRangeHexes));
    }

