            {
                CsvQuote(profileId),
                profileId == "tl2-r45-armor-step-conservative-direct-fire"
                    ? "leading-provisional-reference"
                    : "hull-step-control",
                results.Count(result => result.SideAProfileId == profileId &&
                    result.ProfileLabel == controlLabel)
                    .ToString(CultureInfo.InvariantCulture),
                dynamic.VariantCount.ToString(CultureInfo.InvariantCulture),
                results.Count(result => result.SideAProfileId == profileId &&
                    result.ProfileLabel == fixedLabel)
                    .ToString(CultureInfo.InvariantCulture),
                dynamic.Trials.ToString(CultureInfo.InvariantCulture),
                F(dynamic.DecisiveCoveragePercent),
                assessments.Count(item => item.BroadDominance)
                    .ToString(CultureInfo.InvariantCulture),
                assessments.Count(item => item.Irrelevance)
                    .ToString(CultureInfo.InvariantCulture),
                assessments.Count(item => item.RangeDefinedAsymmetry)
                    .ToString(CultureInfo.InvariantCulture),
                kineticEnergy.FamilyTwoCredibleStartCount.ToString(
                    CultureInfo.InvariantCulture),
                F(100.0 - fixedRange5.FamilyOneConditionalWinPercent),
                "candidate-only-promotion-decision-pending",
                CsvQuote("Use game feel and meaningful-choice evidence; do not require exact parity or promote automatically."),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "promotion-decision-overview.csv"),
            overviewLines,
            new UTF8Encoding(false));
    }

    private static double WeightedMean(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        Func<Tl1IntegratedTacticalCombatVariantSummary, double> selector)
    {
        long trials = results.Sum(result => (long)result.Trials);
        return trials == 0
            ? 0.0
            : results.Sum(result => result.Trials * selector(result)) / trials;
    }

    private static int WeaponRange(
        TechnologyCombatProfile profile,
        WeaponFamily family) => family switch
    {
        WeaponFamily.Kinetic => profile.Kinetic.MaximumRange,
        WeaponFamily.Energy => profile.Energy.MaximumRange,
        WeaponFamily.Missile => profile.Missile.MaximumRange,
        _ => 0,
    };

    private sealed record PooledOutcomeAggregate(
        int VariantCount,
        long Trials,
        double ProfileWins,
        double OpponentWins,
        double Mutual,
        double Unresolved,
        double DecisiveCoveragePercent,
        double PooledConditionalWinPercent,
        double EqualWeightVariantConditionalPercent,
        double MeanTurns,
        double MeanOver18TurnsPercent,
        double MeanDisengagementPercent);

    private static (string Role, string Group) AttributionRole(string profileId)
    {
        if (profileId == "tl2-attr-null-control")
        {
            return ("null-control", string.Empty);
        }
        const string addPrefix = "tl2-attr-add-";
        if (profileId.StartsWith(addPrefix, StringComparison.Ordinal))
        {
            return ("additive", profileId[addPrefix.Length..]);
        }
        const string removePrefix = "tl2-attr-remove-";
        if (profileId.StartsWith(removePrefix, StringComparison.Ordinal))
        {
            return ("leave-one-out", profileId[removePrefix.Length..]);
        }
        if (profileId == "tl2-identity-preserving-refinement")
        {
            return ("identity-source", string.Empty);
        }
        return ("refinement-probe", string.Empty);
    }

    private static void WriteTl1ComposedShipReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(variant => variant.Id, StringComparer.Ordinal);
        var builds = study.Builds.ToDictionary(build => build.Id, StringComparer.Ordinal);
        var matrix = new List<string>
        {
            "variant_id,side_a_build_id,side_b_build_id,side_a_primary,side_a_secondary,side_b_primary,main_weapons,main_reactors,active_sensor,shield_generator,kinetic_pds_count,used_space,free_support_space,side_a_win_percent,side_b_win_percent,mutual_percent,unresolved_percent,side_a_conditional_win_percent,mean_turns,over_18_turns_percent,mean_direct_opportunities,mean_missile_launch_opportunities,mean_prevented_insufficient_power,mean_pds_attempts,mean_pds_intercepts,mean_shield_absorption,mean_hull_damage"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results)
        {
            Tl1IntegratedTacticalCombatVariantDocument variant = variants[result.Id];
            Tl1IntegratedShipBuildDocument build = builds[variant.SideABuildId!];
            double decisive = result.SideAWinsPercent + result.SideBWinsPercent;
            double conditional = decisive <= 0.0
                ? 0.0
                : 100.0 * result.SideAWinsPercent / decisive;
            matrix.Add(string.Join(',', new[]
            {
                CsvQuote(result.Id),
                CsvQuote(variant.SideABuildId ?? string.Empty),
                CsvQuote(variant.SideBBuildId ?? string.Empty),
                result.SideAFamily.ToString(),
                variant.SideASecondaryFamily?.ToString() ?? string.Empty,
                result.SideBFamily.ToString(),
                build.MainWeaponCount.ToString(CultureInfo.InvariantCulture),
                build.MainReactorCount.ToString(CultureInfo.InvariantCulture),
                build.ActiveSensor.ToString(CultureInfo.InvariantCulture),
                build.ShieldGenerator.ToString(CultureInfo.InvariantCulture),
                build.KineticPdsCount.ToString(CultureInfo.InvariantCulture),
                build.UsedSpace.ToString(CultureInfo.InvariantCulture),
                build.FreeSupportSpace.ToString(CultureInfo.InvariantCulture),
                F(result.SideAWinsPercent), F(result.SideBWinsPercent),
                F(result.MutualPercent), F(result.UnresolvedPercent), F(conditional),
                F(result.MeanTurns), F(result.Over18TurnsPercent),
                F(result.MeanDirectActionOpportunities),
                F(result.MeanMissileLaunchOpportunities),
                F(result.MeanPreventedInsufficientPower),
                F(result.MeanPdsAttempts), F(result.MeanPdsIntercepts),
                F(result.MeanShieldAbsorption), F(result.MeanHullDamage),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "composed-build-matrix.csv"),
            matrix,
            new UTF8Encoding(false));

        var rollup = new List<string>
        {
            "side_a_build_id,main_weapons,main_reactors,active_sensor,shield_generator,kinetic_pds_count,used_space,free_support_space,variant_count,mean_side_a_win_percent,mean_side_a_conditional_win_percent,mean_unresolved_percent,mean_turns,mean_over_18_turns_percent,mean_attack_opportunities,mean_prevented_insufficient_power,mean_pds_attempts,mean_pds_intercepts,mean_shield_absorption,mean_hull_damage"
        };
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> group in results
            .GroupBy(result => variants[result.Id].SideABuildId ?? string.Empty)
            .OrderBy(group => group.Key, StringComparer.Ordinal))
        {
            string buildId = group.Key;
            Tl1IntegratedShipBuildDocument build = builds[buildId];
            double meanConditional = group.Average(result =>
            {
                double decisive = result.SideAWinsPercent + result.SideBWinsPercent;
                return decisive <= 0.0 ? 0.0 :
                    100.0 * result.SideAWinsPercent / decisive;
            });
            rollup.Add(string.Join(',', new[]
            {
                CsvQuote(buildId),
                build.MainWeaponCount.ToString(CultureInfo.InvariantCulture),
                build.MainReactorCount.ToString(CultureInfo.InvariantCulture),
                build.ActiveSensor.ToString(CultureInfo.InvariantCulture),
                build.ShieldGenerator.ToString(CultureInfo.InvariantCulture),
                build.KineticPdsCount.ToString(CultureInfo.InvariantCulture),
                build.UsedSpace.ToString(CultureInfo.InvariantCulture),
                build.FreeSupportSpace.ToString(CultureInfo.InvariantCulture),
                group.Count().ToString(CultureInfo.InvariantCulture),
                F(group.Average(result => result.SideAWinsPercent)),
                F(meanConditional),
                F(group.Average(result => result.UnresolvedPercent)),
                F(group.Average(result => result.MeanTurns)),
                F(group.Average(result => result.Over18TurnsPercent)),
                F(group.Average(result => result.MeanDirectActionOpportunities +
                    result.MeanMissileLaunchOpportunities)),
                F(group.Average(result => result.MeanPreventedInsufficientPower)),
                F(group.Average(result => result.MeanPdsAttempts)),
                F(group.Average(result => result.MeanPdsIntercepts)),
                F(group.Average(result => result.MeanShieldAbsorption)),
                F(group.Average(result => result.MeanHullDamage)),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "composed-build-rollup.csv"),
            rollup,
            new UTF8Encoding(false));

        var familyRollup = new List<string>
        {
            "side_a_build_id,side_a_family,variant_count,mean_side_a_win_percent,mean_side_a_conditional_win_percent,mean_unresolved_percent,mean_turns,mean_attack_opportunities,mean_prevented_insufficient_power,mean_pds_attempts,mean_pds_intercepts"
        };
        foreach (var group in results
            .GroupBy(result => new
            {
                BuildId = variants[result.Id].SideABuildId ?? string.Empty,
                Family = result.SideAFamily,
            })
            .OrderBy(group => group.Key.BuildId, StringComparer.Ordinal)
            .ThenBy(group => group.Key.Family))
        {
            double meanConditional = group.Average(result =>
            {
                double decisive = result.SideAWinsPercent + result.SideBWinsPercent;
                return decisive <= 0.0 ? 0.0 :
                    100.0 * result.SideAWinsPercent / decisive;
            });
            familyRollup.Add(string.Join(',', new[]
            {
                CsvQuote(group.Key.BuildId),
                group.Key.Family.ToString(),
                group.Count().ToString(CultureInfo.InvariantCulture),
                F(group.Average(result => result.SideAWinsPercent)),
                F(meanConditional),
                F(group.Average(result => result.UnresolvedPercent)),
                F(group.Average(result => result.MeanTurns)),
                F(group.Average(result => result.MeanDirectActionOpportunities +
                    result.MeanMissileLaunchOpportunities)),
                F(group.Average(result => result.MeanPreventedInsufficientPower)),
                F(group.Average(result => result.MeanPdsAttempts)),
                F(group.Average(result => result.MeanPdsIntercepts)),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "composed-build-family-rollup.csv"),
            familyRollup,
            new UTF8Encoding(false));
    }

