        };
        foreach (var group in results.GroupBy(result => result.ComparisonGroup)
            .OrderBy(group => group.Key, StringComparer.Ordinal))
        {
            Tl1IntegratedTacticalCombatVariantSummary established = group.Single(result =>
                variants[result.Id].ProfileLabel == "established-firm-control");
            Tl1IntegratedTacticalCombatVariantSummary passive = group.Single(result =>
                variants[result.Id].ProfileLabel == "operational-passive-clear");
            Tl1IntegratedTacticalCombatVariantSummary active = group.Single(result =>
                variants[result.Id].ProfileLabel == "operational-auto-active-clear");
