                ? "installed-active-sensor-value-and-power-cost"
                : "passive-only-build-control-auto-must-collapse-to-passive";
            paired.Add(string.Join(',', new[]
            {
                CsvQuote(group.Key), CsvQuote(v.SideABuildId ?? string.Empty),
                established.SideAFamily.ToString(),
                F(Conditional(established)), F(Conditional(passive)),
                F(Conditional(active)), F(Conditional(ew)),
                F(passive.MeanPreventedTrackUnavailable),
                F(active.MeanPreventedTrackUnavailable),
                F(ew.MeanPreventedTrackUnavailable),
                F(active.MeanActiveSensorPowerCommittedA),
                F(ew.MeanActiveSensorPowerCommittedA),
                interpretation,
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "operational-sensor-paired-review.csv"),
            paired,
            new UTF8Encoding(false));
    }

