            Path.Combine(outputDirectory, "track-aware-acquisition-matrix.csv"),
            matrix,
            new UTF8Encoding(false));

        var paired = new List<string>
        {
            "comparison_group,side_a_build_id,side_a_family,active_sensor_installed,established_conditional_win_percent,legacy_clear_conditional_win_percent,track_aware_clear_conditional_win_percent,legacy_ew1_conditional_win_percent,track_aware_ew1_conditional_win_percent,legacy_clear_final_range,track_aware_clear_final_range,legacy_ew1_final_range,track_aware_ew1_final_range,legacy_clear_track_denials,track_aware_clear_track_denials,legacy_ew1_track_denials,track_aware_ew1_track_denials,legacy_clear_firm_evaluations,track_aware_clear_firm_evaluations,legacy_ew1_firm_evaluations,track_aware_ew1_firm_evaluations,track_aware_clear_sensor_power,track_aware_ew1_sensor_power,track_aware_clear_power_preventions,track_aware_ew1_power_preventions,interpretation"
        };
        foreach (var group in results.GroupBy(result => result.ComparisonGroup)
            .OrderBy(group => group.Key, StringComparer.Ordinal))
        {
            Tl1IntegratedTacticalCombatVariantSummary established = group.Single(result =>
                variants[result.Id].ProfileLabel == "established-firm-control");
            Tl1IntegratedTacticalCombatVariantSummary legacyClear = group.Single(result =>
                variants[result.Id].ProfileLabel == "legacy-auto-active-clear");
            Tl1IntegratedTacticalCombatVariantSummary trackClear = group.Single(result =>
                variants[result.Id].ProfileLabel == "track-aware-auto-active-clear");
            Tl1IntegratedTacticalCombatVariantSummary legacyEw = group.Single(result =>
                variants[result.Id].ProfileLabel == "legacy-auto-active-ew1");
            Tl1IntegratedTacticalCombatVariantSummary trackEw = group.Single(result =>
                variants[result.Id].ProfileLabel == "track-aware-auto-active-ew1");
            Tl1IntegratedTacticalCombatVariantDocument variant = variants[established.Id];
            bool installed = builds[variant.SideABuildId!].ActiveSensor;
            string interpretation = installed
                ? "active-sensor-track-aware-range-and-acquisition-first"
                : "passive-core-standoff-cost-no-forced-parity";
            paired.Add(string.Join(',', new[]
            {
                CsvQuote(group.Key), CsvQuote(variant.SideABuildId ?? string.Empty),
                established.SideAFamily.ToString(),
                installed.ToString(CultureInfo.InvariantCulture),
                F(Conditional(established)), F(Conditional(legacyClear)),
                F(Conditional(trackClear)), F(Conditional(legacyEw)),
                F(Conditional(trackEw)), F(legacyClear.MeanFinalRange),
                F(trackClear.MeanFinalRange), F(legacyEw.MeanFinalRange),
                F(trackEw.MeanFinalRange),
                F(legacyClear.MeanPreventedTrackUnavailable),
                F(trackClear.MeanPreventedTrackUnavailable),
                F(legacyEw.MeanPreventedTrackUnavailable),
                F(trackEw.MeanPreventedTrackUnavailable),
                F(legacyClear.MeanFirmTrackEvaluationsA),
                F(trackClear.MeanFirmTrackEvaluationsA),
                F(legacyEw.MeanFirmTrackEvaluationsA),
                F(trackEw.MeanFirmTrackEvaluationsA),
                F(trackClear.MeanActiveSensorPowerCommittedA),
                F(trackEw.MeanActiveSensorPowerCommittedA),
                F(trackClear.MeanPreventedInsufficientPower),
                F(trackEw.MeanPreventedInsufficientPower),
                interpretation,
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "track-aware-acquisition-paired-review.csv"),
            paired,
            new UTF8Encoding(false));
    }

    private static void WriteTl1BilateralTacticalGeometryReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(
            variant => variant.Id, StringComparer.Ordinal);
        static double Conditional(Tl1IntegratedTacticalCombatVariantSummary result)
        {
            double decisive = result.SideAWinsPercent + result.SideBWinsPercent;
            return decisive <= 0.0 ? 0.0 :
                100.0 * result.SideAWinsPercent / decisive;
        }

        var lines = new List<string>
        {
            "comparison_group,side_a_family,side_b_family,regime,a_first_conditional_win_percent,b_first_conditional_win_percent,a_first_mean_final_range,b_first_mean_final_range,a_first_closest_approach,b_first_closest_approach,a_first_fuel_spent_a,a_first_fuel_spent_b,b_first_fuel_spent_a,b_first_fuel_spent_b,a_first_boundary_turns_a,a_first_boundary_turns_b,b_first_boundary_turns_a,b_first_boundary_turns_b,a_first_combined_track_denials,a_first_no_track_evaluations_b,b_first_combined_track_denials,b_first_no_track_evaluations_b,a_first_missiles_range_exhausted,b_first_missiles_range_exhausted,review_note"
        };
        foreach (var group in results.GroupBy(result => result.ComparisonGroup)
            .OrderBy(group => group.Key, StringComparer.Ordinal))
        {
            Tl1IntegratedTacticalCombatVariantSummary aFirst = group.Single(result =>
                result.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst);
            Tl1IntegratedTacticalCombatVariantSummary bFirst = group.Single(result =>
                result.MovementOrder == Tl1IntegratedMovementOrder.SideBFirst);
            Tl1IntegratedTacticalCombatVariantDocument variant = variants[aFirst.Id];
            string regime = variant.SideATrackPolicy == Tl1OperationalTrackPolicy.EstablishedFirm
                ? "established-firm"
                : variant.SideANetEwRangePenalty == 0
                    ? "bilateral-operational-clear"
                    : "bilateral-operational-ew1";
            lines.Add(string.Join(',', new[]
            {
                CsvQuote(group.Key),
                aFirst.SideAFamily.ToString(),
                aFirst.SideBFamily.ToString(),
                regime,
                F(Conditional(aFirst)), F(Conditional(bFirst)),
                F(aFirst.MeanFinalRange), F(bFirst.MeanFinalRange),
                F(aFirst.MeanMinimumRange), F(bFirst.MeanMinimumRange),
                F(aFirst.MeanFuelSpentA), F(aFirst.MeanFuelSpentB),
                F(bFirst.MeanFuelSpentA), F(bFirst.MeanFuelSpentB),
                F(aFirst.MeanBoundaryTurnsA), F(aFirst.MeanBoundaryTurnsB),
                F(bFirst.MeanBoundaryTurnsA), F(bFirst.MeanBoundaryTurnsB),
                F(aFirst.MeanPreventedTrackUnavailable),
                F(aFirst.MeanNoTrackEvaluationsB),
                F(bFirst.MeanPreventedTrackUnavailable),
                F(bFirst.MeanNoTrackEvaluationsB),
                F(aFirst.MeanMissilesRangeExhausted),
                F(bFirst.MeanMissilesRangeExhausted),
                "movement-order-bound-diagnostic-no-target-win-gate",
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "bilateral-geometry-movement-order-paired-review.csv"),
            lines,
            new UTF8Encoding(false));
    }

