    private static void WriteTl1ApproximateTrackDegradedFireReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        var lines = new List<string>
        {
            "variant_id,comparison_group,profile_label,side_a_family,side_b_family,range_hexes,allows_approximate_fire,accuracy_penalty,mean_firm_track_a,mean_firm_track_b,mean_approximate_track_a,mean_approximate_track_b,mean_prevented_track_unavailable,mean_direct_shots,mean_direct_final_hit_chance,direct_hit_percent,side_a_conditional_win_percent,unresolved_percent,mean_turns,mean_shield_absorption,mean_hull_damage,review_note"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(r => DegradedFireProfileOrder(variants[r.Id].ProfileLabel)))
        {
            Tl1IntegratedTacticalCombatVariantDocument variant = variants[result.Id];
            int penalty = Math.Max(
                variant.SideAApproximateDirectFireAccuracyPenalty,
                variant.SideBApproximateDirectFireAccuracyPenalty);
            string note = variant.ProfileLabel switch
            {
                "firm-reference" => "Unjammed Firm-track reference; production direct-fire behavior unchanged.",
                "approx-firm-only" => "Bilateral ECM forces Approximate tracks; Firm-only weapons must remain unable to fire.",
                _ => $"Diagnostic trait permits Approximate-track direct fire at -{penalty} percentage points; candidate value is review-only."
            };
            lines.Add(string.Join(',',
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup), CsvQuote(variant.ProfileLabel ?? string.Empty),
                result.SideAFamily, result.SideBFamily, result.InitialRangeHexes.ToString(CultureInfo.InvariantCulture),
                (variant.SideAAllowsApproximateDirectFire && variant.SideBAllowsApproximateDirectFire).ToString(CultureInfo.InvariantCulture),
                penalty.ToString(CultureInfo.InvariantCulture),
                F(result.MeanFirmTrackEvaluationsA), F(result.MeanFirmTrackEvaluationsB),
                F(result.MeanApproximateTrackEvaluationsA), F(result.MeanApproximateTrackEvaluationsB),
                F(result.MeanPreventedTrackUnavailable), F(result.MeanDirectShotsFired),
                F(result.MeanDirectFinalHitChance), F(result.DirectHitPercent),
                F(ConditionalSideAWinPercent(result)), F(result.UnresolvedPercent), F(result.MeanTurns),
                F(result.MeanShieldAbsorption), F(result.MeanHullDamage), CsvQuote(note)));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "degraded-fire-review.csv"),
            lines,
            new UTF8Encoding(false));
    }

