        var lines = new List<string>
        {
            "variant_id,comparison_group,geometry,profile_label,side_a_family,movement_order,approximate_fire_penalty,side_a_ai_doctrine_id,side_b_ai_doctrine_id,side_a_raw_eccm_policy,side_b_raw_ecm_policy,side_a_conditional_win_percent,side_a_wins_percent,side_b_wins_percent,mutual_percent,unresolved_percent,mean_turns,mean_final_range,mean_minimum_range,mean_maximum_range,mean_firm_track_a,mean_approximate_track_a,mean_no_track_a,mean_ecm_power_b,mean_eccm_power_a,mean_active_sensor_power_a,mean_prevented_track_unavailable,mean_prevented_insufficient_power,mean_direct_shots_a,mean_direct_final_hit_chance_a,direct_hit_percent_a,mean_missile_launches_b,mean_pds_attempts_a,mean_pds_intercepts_a,mean_shield_absorption,mean_hull_damage,review_note"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(r => DegradedFireEccmProfileOrder(variants[r.Id].ProfileLabel)))
        {
            Tl1IntegratedTacticalCombatVariantDocument variant = variants[result.Id];
            string geometry = variant.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                ? "fixed-range-3"
                : "dynamic-track-aware";
            string note = variant.ProfileLabel switch
            {
                "firm-reference" => "Operational Firm reference with no hostile ECM.",
                "jammed-firm-only-no-eccm" => "Firm-only hard-block control under hostile ECM; no ECCM response.",
                "jammed-firm-only-reactive-eccm" => "Firm-only control using reactive ECCM to restore legal direct fire.",
                "p20-no-eccm" or "p25-no-eccm" => "Explicit weapon-specific degraded-fire fallback; compare combat penalty against ECCM restoration.",
                "p20-reactive-eccm" or "p25-reactive-eccm" => "Degraded-fire-capable weapon with accepted reactive ECCM response behavior.",
                _ => "Aggressive normal ECCM diagnostic; compare power/PDS opportunity cost with reactive response.",
            };
            lines.Add(string.Join(',',
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup), CsvQuote(geometry),
                CsvQuote(variant.ProfileLabel ?? string.Empty), result.SideAFamily,
                result.MovementOrder,
                variant.SideAApproximateDirectFireAccuracyPenalty.ToString(CultureInfo.InvariantCulture),
                CsvQuote(variant.SideAAiDoctrineId ?? string.Empty),
                CsvQuote(variant.SideBAiDoctrineId ?? string.Empty),
                variant.SideAEccmPolicy, variant.SideBEcmPolicy,
                F(ConditionalSideAWinPercent(result)), F(result.SideAWinsPercent), F(result.SideBWinsPercent),
                F(result.MutualPercent), F(result.UnresolvedPercent), F(result.MeanTurns),
                F(result.MeanFinalRange), F(result.MeanMinimumRange), F(result.MeanMaximumRange),
                F(result.MeanFirmTrackEvaluationsA), F(result.MeanApproximateTrackEvaluationsA),
                F(result.MeanNoTrackEvaluationsA), F(result.MeanEcmPowerCommittedB),
                F(result.MeanEccmPowerCommittedA), F(result.MeanActiveSensorPowerCommittedA),
                F(result.MeanPreventedTrackUnavailable), F(result.MeanPreventedInsufficientPower),
                F(result.MeanDirectShotsFired), F(result.MeanDirectFinalHitChance), F(result.DirectHitPercent),
                F(result.MeanMissileLaunches), F(result.MeanPdsAttempts), F(result.MeanPdsIntercepts),
                F(result.MeanShieldAbsorption), F(result.MeanHullDamage), CsvQuote(note)));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "degraded-fire-eccm-value-review.csv"),
            lines,
            new UTF8Encoding(false));
    }

    private static void WriteTl2TacticalComputerEwPermutationReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        var lines = new List<string>
        {
            "variant_id,comparison_group,geometry,environment,computer_targeting_bonus_pp,side_a_family,side_b_family,movement_order,side_a_sensor_profile,side_b_ecm_rating,side_a_eccm_rating,approximate_fire_penalty_pp,side_a_conditional_win_percent,side_a_wins_percent,side_b_wins_percent,mutual_percent,unresolved_percent,mean_turns,mean_firm_track_a,mean_approximate_track_a,mean_ecm_power_b,mean_eccm_power_a,mean_prevented_insufficient_power,mean_direct_shots_a,mean_direct_final_hit_chance_a,direct_hit_percent_a,mean_pds_attempts_a,mean_pds_intercepts_a,review_note"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(r => Tl2TacticalComputerPermutationEnvironmentOrder(variants[r.Id].ProfileLabel))
            .ThenBy(r => variants[r.Id].SideATacticalComputerTargetingBonusOverride ?? 10))
        {
            Tl1IntegratedTacticalCombatVariantDocument variant = variants[result.Id];
            string label = variant.ProfileLabel ?? string.Empty;
            string environment = label.EndsWith("-c10", StringComparison.Ordinal) || label.EndsWith("-c12", StringComparison.Ordinal)
                ? label[..^4]
                : label;
            string geometry = variant.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                ? "fixed-range-3"
                : variant.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst
                    ? "dynamic-side-a-first"
                    : "dynamic-side-b-first";
            string note = environment switch
            {
                "firm-reference" => "Clean Firm reference; isolates ordinary Tactical Computer assistance without ECM/ECCM power competition.",
                "wide-eccm2" => "Old Sensor + ECCM2 brute-force Firm restoration at 5 TP; exposes Computer benefit under maximum EW power pressure.",
                "tall-dr1-eccm1" => "Contemporary DR1 + ECCM1 Firm-restoring path at 5 TP; primary TL2 integration comparison.",
                _ => "Explicit study-only -25 degraded-fire fallback under ECM2; penalty remains owned by the computer profile and unchanged between +10/+12 ordinary targeting candidates.",
            };
            lines.Add(string.Join(',',
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup), CsvQuote(geometry), CsvQuote(environment),
                (variant.SideATacticalComputerTargetingBonusOverride ?? 10).ToString(CultureInfo.InvariantCulture),
                result.SideAFamily, result.SideBFamily, result.MovementOrder,
                CsvQuote(variant.SideASensorEwProfileId ?? variant.SensorEwProfileId ?? string.Empty),
                (variant.SideBEcmNormalRatingOverride ?? 1).ToString(CultureInfo.InvariantCulture),
                (variant.SideAEccmNormalRatingOverride ?? 1).ToString(CultureInfo.InvariantCulture),
                variant.SideAApproximateDirectFireAccuracyPenalty.ToString(CultureInfo.InvariantCulture),
                F(ConditionalSideAWinPercent(result)), F(result.SideAWinsPercent), F(result.SideBWinsPercent),
                F(result.MutualPercent), F(result.UnresolvedPercent), F(result.MeanTurns),
                F(result.MeanFirmTrackEvaluationsA), F(result.MeanApproximateTrackEvaluationsA),
                F(result.MeanEcmPowerCommittedB), F(result.MeanEccmPowerCommittedA),
                F(result.MeanPreventedInsufficientPower), F(result.MeanDirectShotsFired),
                F(result.MeanDirectFinalHitChance), F(result.DirectHitPercent),
                F(result.MeanPdsAttempts), F(result.MeanPdsIntercepts), CsvQuote(note)));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "tl2-tactical-computer-ew-integration-permutations-review.csv"),
            lines,
            new UTF8Encoding(false));

        var deltaLines = new List<string>
        {
            "comparison_group,geometry,environment,side_a_family,side_b_family,conditional_win_delta_pp,mean_turns_delta,mean_direct_final_hit_chance_delta_pp,direct_hit_delta_pp,mean_pds_attempts_delta,mean_pds_intercepts_delta"
        };
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> context in results
            .GroupBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .OrderBy(g => g.Key, StringComparer.Ordinal))
        {
            foreach (string environment in new[] { "firm-reference", "wide-eccm2", "tall-dr1-eccm1", "degraded-p25" })
            {
                Tl1IntegratedTacticalCombatVariantSummary? c10 = context.SingleOrDefault(r =>
                    string.Equals(variants[r.Id].ProfileLabel, environment + "-c10", StringComparison.Ordinal));
                Tl1IntegratedTacticalCombatVariantSummary? c12 = context.SingleOrDefault(r =>
                    string.Equals(variants[r.Id].ProfileLabel, environment + "-c12", StringComparison.Ordinal));
                if (c10 is null || c12 is null)
                {
                    continue;
                }
                Tl1IntegratedTacticalCombatVariantDocument variant = variants[c10.Id];
                string geometry = variant.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                    ? "fixed-range-3"
                    : variant.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst
                        ? "dynamic-side-a-first"
                        : "dynamic-side-b-first";
                deltaLines.Add(string.Join(',',
                    CsvQuote(context.Key), CsvQuote(geometry), CsvQuote(environment),
                    c10.SideAFamily, c10.SideBFamily,
                    F(ConditionalSideAWinPercent(c12) - ConditionalSideAWinPercent(c10)),
                    F(c12.MeanTurns - c10.MeanTurns),
                    F(c12.MeanDirectFinalHitChance - c10.MeanDirectFinalHitChance),
                    F(c12.DirectHitPercent - c10.DirectHitPercent),
                    F(c12.MeanPdsAttempts - c10.MeanPdsAttempts),
                    F(c12.MeanPdsIntercepts - c10.MeanPdsIntercepts)));
            }
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "tl2-tactical-computer-ew-integration-permutations-paired-deltas.csv"),
            deltaLines,
            new UTF8Encoding(false));
    }

    private static int Tl2TacticalComputerPermutationEnvironmentOrder(string? profileLabel)
    {
        string label = profileLabel ?? string.Empty;
        if (label.StartsWith("firm-reference-", StringComparison.Ordinal)) return 0;
        if (label.StartsWith("tall-dr1-eccm1-", StringComparison.Ordinal)) return 1;
        if (label.StartsWith("wide-eccm2-", StringComparison.Ordinal)) return 2;
        if (label.StartsWith("degraded-p25-", StringComparison.Ordinal)) return 3;
        return 99;
    }

    private static void WriteTl2WeaponPenetrationLayeredDefenseReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        var lines = new List<string>
        {
            "variant_id,comparison_group,geometry,environment,weapon_family,penetration_profile,side_a_spen,side_a_apen,target_shield,target_ap,target_ai,side_a_conditional_win_percent,side_a_wins_percent,side_b_wins_percent,mutual_percent,unresolved_percent,mean_turns,mean_shield_absorption,mean_armor_damage_prevented,mean_armor_integrity_damage,mean_armor_protection_damage,mean_hull_damage,mean_tactical_recharge_power_a,mean_prevented_insufficient_power,mean_pds_attempts,mean_direct_shots,mean_missile_launches"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(r => variants[r.Id].ProfileLabel, StringComparer.Ordinal))
        {
            Tl1IntegratedTacticalCombatVariantDocument v = variants[result.Id];
            string label = v.ProfileLabel ?? string.Empty;
            string environment = label.StartsWith("tall-dr1-eccm1-", StringComparison.Ordinal)
                ? "tall-dr1-eccm1" : "firm-reference";
            string penetrationProfile = new[] { "control", "apen", "spen", "combined" }
                .Single(x => label.Contains($"-{x}-", StringComparison.Ordinal));
            string geometry = v.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                ? "fixed-range-3"
                : v.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst
                    ? "dynamic-side-a-first" : "dynamic-side-b-first";
            lines.Add(string.Join(',',
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup), CsvQuote(geometry), CsvQuote(environment),
                result.SideAFamily, CsvQuote(penetrationProfile),
                (v.SideAWeaponShieldPenetrationOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                (v.SideAWeaponArmorPenetrationOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                (v.SideBShieldCapacityOverride ?? 2).ToString(CultureInfo.InvariantCulture),
                (v.SideBPrimaryArmorProtectionOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                (v.SideBPrimaryArmorIntegrityOverride ?? 4).ToString(CultureInfo.InvariantCulture),
                F(ConditionalSideAWinPercent(result)), F(result.SideAWinsPercent), F(result.SideBWinsPercent),
                F(result.MutualPercent), F(result.UnresolvedPercent), F(result.MeanTurns),
                F(result.MeanShieldAbsorption), F(result.MeanArmorDamagePrevented),
                F(result.MeanArmorIntegrityDamage), F(result.MeanArmorProtectionDamage), F(result.MeanHullDamage),
                F(result.MeanTacticalShieldRechargePowerSpentA), F(result.MeanPreventedInsufficientPower),
                F(result.MeanPdsAttempts), F(result.MeanDirectShotsFired), F(result.MeanMissileLaunches)));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "tl2-weapon-penetration-layered-defense-review.csv"),
            lines,
            new UTF8Encoding(false));

        var deltaLines = new List<string>
        {
            "comparison_group,geometry,environment,weapon_family,target_shield,target_ap,target_ai,delta_type,from_spen,from_apen,to_spen,to_apen,conditional_win_delta_pp,mean_turns_delta,mean_shield_absorption_delta,mean_armor_damage_prevented_delta,mean_armor_integrity_damage_delta,mean_armor_protection_damage_delta,mean_hull_damage_delta,mean_tactical_recharge_power_a_delta,mean_prevented_insufficient_power_delta,mean_pds_attempts_delta,mean_direct_shots_delta,mean_missile_launches_delta"
        };
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> context in results
            .GroupBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .OrderBy(g => g.Key, StringComparer.Ordinal))
        foreach (string environment in new[] { "firm-reference", "tall-dr1-eccm1" })
        foreach (int shield in new[] { 2, 3 })
        foreach (int ap in new[] { 0, 1 })
        {
            var byProfile = context.Where(r =>
                (variants[r.Id].ProfileLabel ?? string.Empty).StartsWith(environment + "-", StringComparison.Ordinal) &&
                variants[r.Id].SideBShieldCapacityOverride == shield &&
                variants[r.Id].SideBPrimaryArmorProtectionOverride == ap)
                .ToDictionary(r => new[] { "control", "apen", "spen", "combined" }
                    .Single(x => (variants[r.Id].ProfileLabel ?? string.Empty).Contains($"-{x}-", StringComparison.Ordinal)), StringComparer.Ordinal);
            if (!byProfile.TryGetValue("control", out Tl1IntegratedTacticalCombatVariantSummary? control)) continue;
            foreach (string profile in new[] { "apen", "spen", "combined" })
            {
                if (!byProfile.TryGetValue(profile, out Tl1IntegratedTacticalCombatVariantSummary? candidate)) continue;
                Tl1IntegratedTacticalCombatVariantDocument fromV = variants[control.Id];
                Tl1IntegratedTacticalCombatVariantDocument toV = variants[candidate.Id];
                string geometry = fromV.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                    ? "fixed-range-3"
                    : fromV.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst
                        ? "dynamic-side-a-first" : "dynamic-side-b-first";
                deltaLines.Add(string.Join(',', CsvQuote(context.Key), CsvQuote(geometry), CsvQuote(environment),
                    control.SideAFamily, shield.ToString(CultureInfo.InvariantCulture), ap.ToString(CultureInfo.InvariantCulture), "5",
                    CsvQuote(profile + "-minus-control"),
                    (fromV.SideAWeaponShieldPenetrationOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                    (fromV.SideAWeaponArmorPenetrationOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                    (toV.SideAWeaponShieldPenetrationOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                    (toV.SideAWeaponArmorPenetrationOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                    F(ConditionalSideAWinPercent(candidate) - ConditionalSideAWinPercent(control)),
                    F(candidate.MeanTurns - control.MeanTurns), F(candidate.MeanShieldAbsorption - control.MeanShieldAbsorption),
                    F(candidate.MeanArmorDamagePrevented - control.MeanArmorDamagePrevented),
                    F(candidate.MeanArmorIntegrityDamage - control.MeanArmorIntegrityDamage),
                    F(candidate.MeanArmorProtectionDamage - control.MeanArmorProtectionDamage),
                    F(candidate.MeanHullDamage - control.MeanHullDamage),
                    F(candidate.MeanTacticalShieldRechargePowerSpentA - control.MeanTacticalShieldRechargePowerSpentA),
                    F(candidate.MeanPreventedInsufficientPower - control.MeanPreventedInsufficientPower),
                    F(candidate.MeanPdsAttempts - control.MeanPdsAttempts),
                    F(candidate.MeanDirectShotsFired - control.MeanDirectShotsFired),
                    F(candidate.MeanMissileLaunches - control.MeanMissileLaunches)));
            }
            if (byProfile.TryGetValue("apen", out Tl1IntegratedTacticalCombatVariantSummary? apen) &&
                byProfile.TryGetValue("spen", out Tl1IntegratedTacticalCombatVariantSummary? spen) &&
                byProfile.TryGetValue("combined", out Tl1IntegratedTacticalCombatVariantSummary? combined))
            {
                Tl1IntegratedTacticalCombatVariantDocument fromV = variants[control.Id];
                Tl1IntegratedTacticalCombatVariantDocument toV = variants[combined.Id];
                string geometry = fromV.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                    ? "fixed-range-3"
                    : fromV.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst
                        ? "dynamic-side-a-first" : "dynamic-side-b-first";
                double interaction = ConditionalSideAWinPercent(combined) - ConditionalSideAWinPercent(control) -
                    (ConditionalSideAWinPercent(apen) - ConditionalSideAWinPercent(control)) -
                    (ConditionalSideAWinPercent(spen) - ConditionalSideAWinPercent(control));
                deltaLines.Add(string.Join(',', CsvQuote(context.Key), CsvQuote(geometry), CsvQuote(environment),
                    control.SideAFamily, shield.ToString(CultureInfo.InvariantCulture), ap.ToString(CultureInfo.InvariantCulture), "5",
                    CsvQuote("apen-spen-interaction"),
                    (fromV.SideAWeaponShieldPenetrationOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                    (fromV.SideAWeaponArmorPenetrationOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                    (toV.SideAWeaponShieldPenetrationOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                    (toV.SideAWeaponArmorPenetrationOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                    F(interaction), "0.000000", "0.000000", "0.000000", "0.000000", "0.000000", "0.000000", "0.000000", "0.000000", "0.000000", "0.000000", "0.000000"));
            }
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "tl2-weapon-penetration-layered-defense-paired-deltas.csv"),
            deltaLines,
            new UTF8Encoding(false));
    }

