    private static void WriteCrossTlGeneralizedLegalBuildReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        var builds = study.Builds.ToDictionary(build => build.Id, StringComparer.Ordinal);
        var lines = new List<string>
        {
            "variant_id,comparison_group,source,composition_class,progression_direction,progression_distance,progression_stratum,geometry,side_a_build,side_a_used_space,side_a_advanced_components,side_a_main_weapons,side_a_reactors,side_a_ecm_ratings,side_a_eccm_ratings,side_b_build,side_b_used_space,side_b_advanced_components,side_b_main_weapons,side_b_reactors,side_b_ecm_ratings,side_b_eccm_ratings,side_a_family,side_b_family,side_a_conditional_win_percent,unresolved_percent,mean_turns,mean_direct_shots,mean_missile_launches,mean_track_preventions,mean_power_preventions,mean_pds_attempts"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(r => r.MovementOrder))
        {
            Tl1IntegratedTacticalCombatVariantDocument variant = variants[result.Id];
            Tl1IntegratedShipBuildDocument a = builds[variant.SideABuildId!];
            Tl1IntegratedShipBuildDocument b = builds[variant.SideBBuildId!];
            string label = variant.ProfileLabel ?? string.Empty;
            lines.Add(string.Join(",", new[]
            {
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup), CsvQuote(CrossTlLabelValue(label, "source")),
                CsvQuote(CrossTlLabelValue(label, "composition")), CsvQuote(CrossTlLabelValue(label, "progression")),
                CsvQuote(CrossTlLabelValue(label, "distance")), CsvQuote(CrossTlLabelValue(label, "stratum")),
                CsvQuote(CrossTlLabelValue(label, "geometry")), CsvQuote(a.Id), a.UsedSpace.ToString(CultureInfo.InvariantCulture),
                (a.AdvancedComponentCount ?? 0).ToString(CultureInfo.InvariantCulture), a.MainWeaponCount.ToString(CultureInfo.InvariantCulture),
                a.MainReactorCount.ToString(CultureInfo.InvariantCulture), CsvQuote(string.Join("+", a.EcmSuiteRatings)), CsvQuote(string.Join("+", a.EccmSuiteRatings)),
                CsvQuote(b.Id), b.UsedSpace.ToString(CultureInfo.InvariantCulture), (b.AdvancedComponentCount ?? 0).ToString(CultureInfo.InvariantCulture),
                b.MainWeaponCount.ToString(CultureInfo.InvariantCulture), b.MainReactorCount.ToString(CultureInfo.InvariantCulture),
                CsvQuote(string.Join("+", b.EcmSuiteRatings)), CsvQuote(string.Join("+", b.EccmSuiteRatings)), result.SideAFamily.ToString(), result.SideBFamily.ToString(),
                F(ConditionalSideAWinPercent(result)), F(result.UnresolvedPercent), F(result.MeanTurns), F(result.MeanDirectShotsFired),
                F(result.MeanMissileLaunches), F(result.MeanPreventedTrackUnavailable), F(result.MeanPreventedInsufficientPower), F(result.MeanPdsAttempts),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "cross-tl-generalized-build-review.csv"),
            lines, new UTF8Encoding(false));

        var aggregate = new List<string>
        {
            "source,composition_class,progression_stratum,variant_count,mean_side_a_conditional_win_percent,mean_unresolved_percent,mean_turns,mean_track_preventions,mean_power_preventions"
        };
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> group in results.GroupBy(result =>
        {
            string label = variants[result.Id].ProfileLabel ?? string.Empty;
            return string.Join("|", CrossTlLabelValue(label, "source"), CrossTlLabelValue(label, "composition"), CrossTlLabelValue(label, "stratum"));
        }, StringComparer.Ordinal).OrderBy(group => group.Key, StringComparer.Ordinal))
        {
            string[] parts = group.Key.Split('|');
            aggregate.Add(string.Join(",", CsvQuote(parts[0]), CsvQuote(parts[1]), CsvQuote(parts[2]),
                group.Count().ToString(CultureInfo.InvariantCulture), F(group.Average(result => ConditionalSideAWinPercent(result))),
                F(group.Average(result => result.UnresolvedPercent)), F(group.Average(result => result.MeanTurns)),
                F(group.Average(result => result.MeanPreventedTrackUnavailable)), F(group.Average(result => result.MeanPreventedInsufficientPower))));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "cross-tl-generalized-strata-review.csv"),
            aggregate, new UTF8Encoding(false));
    }


    private static void WriteCrossTlMatchedReadinessSpaceReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        var builds = study.Builds.ToDictionary(build => build.Id, StringComparer.Ordinal);
        Tl1IntegratedTacticalCombatVariantSummary[] matched = results
            .Where(result => CrossTlLabelValue(variants[result.Id].ProfileLabel ?? string.Empty, "source")
                is "statistical" or "diversity")
            .ToArray();

        static double ConditionalB(Tl1IntegratedTacticalCombatVariantSummary result)
        {
            double decisive = result.SideAWinsPercent + result.SideBWinsPercent;
            return decisive <= 0.0 ? 0.0 : 100.0 * result.SideBWinsPercent / decisive;
        }
        static double FamilyActions(Tl1IntegratedTacticalCombatVariantSummary result, bool sideA)
        {
            WeaponFamily family = sideA ? result.SideAFamily : result.SideBFamily;
            return family == WeaponFamily.Missile
                ? sideA ? result.MeanMissileLaunchesA : result.MeanMissileLaunchesB
                : sideA ? result.MeanDirectShotsFiredA : result.MeanDirectShotsFiredB;
        }
        static string SensitivityClass(double gap) => gap < 5.0
            ? "low"
            : gap < 15.0
                ? "moderate"
                : gap < 30.0
                    ? "high"
                    : "extreme";

        var pairedRows = new List<(
            string Bundle,
            string Source,
            string Geometry,
            string Composition,
            string ProgressionMagnitude,
            string SpacePair,
            string FamilyPair,
            string InformationDirection,
            int InformationDistance,
            string InformationBand,
            string PopulationCell,
            long PopulationCount,
            int PopulationSampleCount,
            double RepresentativeWeight,
            string SecondaryKey,
            string BuildX,
            string BuildY,
            int SpaceX,
            int SpaceY,
            int AdvancedX,
            int AdvancedY,
            string ReadinessX,
            string ReadinessY,
            int ReadyRangeX,
            int ReadyRangeY,
            bool ReferenceContextMutualReady,
            bool ObservedReferenceReadyWindow,
            bool RuntimeBilateralActive,
            string ReferenceRuntimeRelation,
            double RuntimeActionsX,
            double RuntimeActionsY,
            double MatchedXWin,
            double MatchedYWin,
            double OrientationGap,
            double? HigherAdvancedWin,
            double Unresolved,
            double MeanTurns,
            double MeanAttacks,
            double MeanTrackPreventions,
            double MeanPowerPreventions,
            double MeanPathClosestApproachRange,
            double MeanMinimumPostMovementRange,
            double MeanPostMovementFiringWindows,
            double MeanPostMovementReadyWindowsX,
            double MeanPostMovementReadyWindowsY,
            double MeanPostMovementReadyWindowsMutual,
            double PostMovementReadyTrialsPercentX,
            double PostMovementReadyTrialsPercentY,
            double PostMovementReadyTrialsPercentMutual,
            string ObservedEngagementDiagnosis) >();

        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> group in matched
            .GroupBy(result =>
            {
                string label = variants[result.Id].ProfileLabel ?? string.Empty;
                return CrossTlLabelValue(label, "bundle") + "|" + CrossTlLabelValue(label, "geometry");
            }, StringComparer.Ordinal)
            .OrderBy(group => group.Key, StringComparer.Ordinal))
        {
            Tl1IntegratedTacticalCombatVariantSummary[] rows = group.ToArray();
            if (rows.Length != 2)
            {
                throw new InvalidOperationException(
                    $"CP96 matched bundle/geometry '{group.Key}' must contain exactly two orientations; observed {rows.Length}.");
            }
            Tl1IntegratedTacticalCombatVariantSummary forward = rows.Single(result =>
                CrossTlLabelValue(variants[result.Id].ProfileLabel ?? string.Empty, "orientation") == "forward");
            Tl1IntegratedTacticalCombatVariantSummary reverse = rows.Single(result =>
                CrossTlLabelValue(variants[result.Id].ProfileLabel ?? string.Empty, "orientation") == "reverse");
            Tl1IntegratedTacticalCombatVariantDocument forwardVariant = variants[forward.Id];
            Tl1IntegratedTacticalCombatVariantDocument reverseVariant = variants[reverse.Id];
            if (!string.Equals(forwardVariant.SideABuildId, reverseVariant.SideBBuildId, StringComparison.Ordinal) ||
                !string.Equals(forwardVariant.SideBBuildId, reverseVariant.SideABuildId, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    $"CP96 matched bundle/geometry '{group.Key}' is not an exact A/B orientation mirror.");
            }
            Tl1IntegratedShipBuildDocument x = builds[forwardVariant.SideABuildId!];
            Tl1IntegratedShipBuildDocument y = builds[forwardVariant.SideBBuildId!];
            string label = forwardVariant.ProfileLabel ?? string.Empty;
            string geometry = CrossTlLabelValue(label, "geometry");
            string readinessX = CrossTlLabelValue(label, "readinessA");
            string readinessY = CrossTlLabelValue(label, "readinessB");
            int readyRangeX = int.Parse(CrossTlLabelValue(label, "readyRangeA"), CultureInfo.InvariantCulture);
            int readyRangeY = int.Parse(CrossTlLabelValue(label, "readyRangeB"), CultureInfo.InvariantCulture);
            double xForward = ConditionalSideAWinPercent(forward);
            double xReverse = ConditionalB(reverse);
            double matchedX = (xForward + xReverse) / 2.0;
            double matchedY = (ConditionalB(forward) + ConditionalSideAWinPercent(reverse)) / 2.0;
            double? higherAdvancedWin = (x.AdvancedComponentCount ?? 0) == (y.AdvancedComponentCount ?? 0)
                ? null
                : (x.AdvancedComponentCount ?? 0) > (y.AdvancedComponentCount ?? 0)
                    ? matchedX
                    : matchedY;
            long populationCount = long.Parse(
                CrossTlLabelValue(label, "populationCount"), CultureInfo.InvariantCulture);
            int populationSampleCount = int.Parse(
                CrossTlLabelValue(label, "populationSampleCount"), CultureInfo.InvariantCulture);
            double representativeWeight = double.Parse(
                CrossTlLabelValue(label, "populationRepresentativeWeight"), CultureInfo.InvariantCulture);
            double actionsX = (FamilyActions(forward, true) + FamilyActions(reverse, false)) / 2.0;
            double actionsY = (FamilyActions(forward, false) + FamilyActions(reverse, true)) / 2.0;
            double meanActions = actionsX + actionsY;
            double meanPathClosestApproachRange = (forward.MeanMinimumRange + reverse.MeanMinimumRange) / 2.0;
            double meanMinimumPostMovementRange = (forward.MeanMinimumPostMovementRange + reverse.MeanMinimumPostMovementRange) / 2.0;
            double meanPostMovementFiringWindows = (forward.MeanPostMovementFiringWindows + reverse.MeanPostMovementFiringWindows) / 2.0;
            double meanPostMovementReadyWindowsX = (forward.MeanPostMovementReadyWindowsA + reverse.MeanPostMovementReadyWindowsB) / 2.0;
            double meanPostMovementReadyWindowsY = (forward.MeanPostMovementReadyWindowsB + reverse.MeanPostMovementReadyWindowsA) / 2.0;
            double meanPostMovementReadyWindowsMutual = (forward.MeanPostMovementReadyWindowsMutual + reverse.MeanPostMovementReadyWindowsMutual) / 2.0;
            double postMovementReadyTrialsPercentX = (forward.PostMovementReadyTrialsPercentA + reverse.PostMovementReadyTrialsPercentB) / 2.0;
            double postMovementReadyTrialsPercentY = (forward.PostMovementReadyTrialsPercentB + reverse.PostMovementReadyTrialsPercentA) / 2.0;
            double postMovementReadyTrialsPercentMutual = (forward.PostMovementReadyTrialsPercentMutual + reverse.PostMovementReadyTrialsPercentMutual) / 2.0;
            bool referenceContextMutualReady = CrossTlReadinessIsActive(readinessX, geometry) && CrossTlReadinessIsActive(readinessY, geometry);
            bool observedReferenceReadyWindow = CrossTlObservedReferenceReadyWindow(postMovementReadyTrialsPercentMutual);
            bool runtimeBilateralActive = CrossTlRuntimeBilateralActive(actionsX, actionsY);
            string referenceRuntimeRelation = CrossTlReferenceRuntimeRelation(referenceContextMutualReady, runtimeBilateralActive);
            pairedRows.Add((
                CrossTlLabelValue(label, "bundle"),
                CrossTlLabelValue(label, "source"),
                geometry,
                CrossTlLabelValue(label, "composition"),
                CrossTlLabelValue(label, "progressionMagnitude"),
                CrossTlLabelValue(label, "spacePair"),
                CrossTlLabelValue(label, "familyPair"),
                CrossTlLabelValue(label, "infoDirection"),
                int.Parse(CrossTlLabelValue(label, "infoDistance"), CultureInfo.InvariantCulture),
                CrossTlLabelValue(label, "infoBand"),
                CrossTlLabelValue(label, "populationCell"),
                populationCount,
                populationSampleCount,
                representativeWeight,
                CrossTlLabelValue(label, "secondaryKey"),
                x.Id,
                y.Id,
                x.UsedSpace,
                y.UsedSpace,
                x.AdvancedComponentCount ?? 0,
                y.AdvancedComponentCount ?? 0,
                readinessX,
                readinessY,
                readyRangeX,
                readyRangeY,
                referenceContextMutualReady,
                observedReferenceReadyWindow,
                runtimeBilateralActive,
                referenceRuntimeRelation,
                actionsX,
                actionsY,
                matchedX,
                matchedY,
                Math.Abs(xForward - xReverse),
                higherAdvancedWin,
                (forward.UnresolvedPercent + reverse.UnresolvedPercent) / 2.0,
                (forward.MeanTurns + reverse.MeanTurns) / 2.0,
                meanActions,
                (forward.MeanPreventedTrackUnavailable + reverse.MeanPreventedTrackUnavailable) / 2.0,
                (forward.MeanPreventedInsufficientPower + reverse.MeanPreventedInsufficientPower) / 2.0,
                meanPathClosestApproachRange,
                meanMinimumPostMovementRange,
                meanPostMovementFiringWindows,
                meanPostMovementReadyWindowsX,
                meanPostMovementReadyWindowsY,
                meanPostMovementReadyWindowsMutual,
                postMovementReadyTrialsPercentX,
                postMovementReadyTrialsPercentY,
                postMovementReadyTrialsPercentMutual,
                DiagnoseCrossTlObservedEngagementForSelfTest(
                    geometry, readinessX, readinessY, actionsX, actionsY, postMovementReadyTrialsPercentMutual)));
        }

        var pairedLines = new List<string>
        {
            "bundle_id,sample_role,geometry,composition_class,progression_magnitude,space_pair_stratum,weapon_family_pair,information_control_direction,information_control_distance,information_control_band,population_cell,population_unordered_distinct_count,population_sample_count,population_representative_weight,secondary_coverage_key,build_x,build_y,used_space_x,used_space_y,advanced_components_x,advanced_components_y,readiness_x,readiness_y,ready_range_x,ready_range_y,reference_context_mutual_ready,observed_reference_ready_window,runtime_bilateral_active,reference_runtime_relation,runtime_actions_x,runtime_actions_y,legacy_cp95_observed_engagement_diagnosis,matched_x_conditional_win_percent,matched_y_conditional_win_percent,orientation_gap_pp,higher_advanced_side_conditional_win_percent,mean_unresolved_percent,mean_turns,mean_total_main_actions,mean_track_preventions,mean_power_preventions,mean_path_closest_approach_range,mean_minimum_post_movement_range,mean_post_movement_firing_windows,mean_post_movement_ready_windows_x,mean_post_movement_ready_windows_y,mean_post_movement_ready_windows_mutual,post_movement_ready_trials_percent_x,post_movement_ready_trials_percent_y,post_movement_ready_trials_percent_mutual"
        };
        foreach (var row in pairedRows
            .OrderBy(row => row.Bundle, StringComparer.Ordinal)
            .ThenBy(row => row.Geometry, StringComparer.Ordinal))
        {
            pairedLines.Add(string.Join(',',
                CsvQuote(row.Bundle), CsvQuote(row.Source), CsvQuote(row.Geometry), CsvQuote(row.Composition),
                CsvQuote(row.ProgressionMagnitude), CsvQuote(row.SpacePair), CsvQuote(row.FamilyPair),
                CsvQuote(row.InformationDirection), row.InformationDistance.ToString(CultureInfo.InvariantCulture),
                CsvQuote(row.InformationBand), CsvQuote(row.PopulationCell), row.PopulationCount.ToString(CultureInfo.InvariantCulture),
                row.PopulationSampleCount.ToString(CultureInfo.InvariantCulture), row.RepresentativeWeight.ToString("R", CultureInfo.InvariantCulture),
                CsvQuote(row.SecondaryKey), CsvQuote(row.BuildX), CsvQuote(row.BuildY),
                row.SpaceX.ToString(CultureInfo.InvariantCulture), row.SpaceY.ToString(CultureInfo.InvariantCulture),
                row.AdvancedX.ToString(CultureInfo.InvariantCulture), row.AdvancedY.ToString(CultureInfo.InvariantCulture),
                CsvQuote(row.ReadinessX), CsvQuote(row.ReadinessY), row.ReadyRangeX.ToString(CultureInfo.InvariantCulture),
                row.ReadyRangeY.ToString(CultureInfo.InvariantCulture), row.ReferenceContextMutualReady ? "true" : "false",
                row.ObservedReferenceReadyWindow ? "true" : "false", row.RuntimeBilateralActive ? "true" : "false",
                CsvQuote(row.ReferenceRuntimeRelation), F(row.RuntimeActionsX), F(row.RuntimeActionsY),
                CsvQuote(row.ObservedEngagementDiagnosis), F(row.MatchedXWin), F(row.MatchedYWin), F(row.OrientationGap),
                row.HigherAdvancedWin is double higherAdvancedWin ? F(higherAdvancedWin) : string.Empty,
                F(row.Unresolved), F(row.MeanTurns), F(row.MeanAttacks), F(row.MeanTrackPreventions),
                F(row.MeanPowerPreventions), F(row.MeanPathClosestApproachRange),
                F(row.MeanMinimumPostMovementRange), F(row.MeanPostMovementFiringWindows),
                F(row.MeanPostMovementReadyWindowsX), F(row.MeanPostMovementReadyWindowsY),
                F(row.MeanPostMovementReadyWindowsMutual), F(row.PostMovementReadyTrialsPercentX),
                F(row.PostMovementReadyTrialsPercentY), F(row.PostMovementReadyTrialsPercentMutual)));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "cross-tl-cp96-paired-review.csv"),
            pairedLines, new UTF8Encoding(false));

        double totalPopulation = pairedRows
            .Where(row => row.Source == "statistical" && row.Geometry == "fixed-r3")
            .Sum(row => row.RepresentativeWeight);
        var weightedLines = new List<string>
        {
            "geometry,cohort,statistical_bundle_count,population_representative_weight_sum,population_weight_fraction_percent,raw_mean_unresolved_percent,population_weighted_mean_unresolved_percent,raw_mean_turns,population_weighted_mean_turns,raw_mean_total_main_actions,population_weighted_mean_total_main_actions,higher_advanced_bundle_count,raw_mean_higher_advanced_side_conditional_win_percent,population_weighted_mean_higher_advanced_side_conditional_win_percent,interpretation"
        };
        foreach (string geometry in new[] { "fixed-r3", "dynamic-a-first", "dynamic-b-first" })
        {
            var geometryRows = pairedRows.Where(row => row.Source == "statistical" && row.Geometry == geometry).ToArray();
            foreach (string cohort in new[] { "all_legal", "reference_context_mutual_ready", "observed_reference_ready_window", "runtime_bilateral_active", "legacy_cp95_reference_expected_runtime_active" })
            {
                var rows = geometryRows.Where(row => cohort switch
                {
                    "reference_context_mutual_ready" => row.ReferenceContextMutualReady,
                    "observed_reference_ready_window" => row.ObservedReferenceReadyWindow,
                    "runtime_bilateral_active" => row.RuntimeBilateralActive,
                    "legacy_cp95_reference_expected_runtime_active" => row.ObservedEngagementDiagnosis == "active",
                    _ => true,
                }).ToArray();
                double weight = rows.Sum(row => row.RepresentativeWeight);
                double weightedUnresolved = weight <= 0.0 ? 0.0
                    : rows.Sum(row => row.Unresolved * row.RepresentativeWeight) / weight;
                double weightedTurns = weight <= 0.0 ? 0.0
                    : rows.Sum(row => row.MeanTurns * row.RepresentativeWeight) / weight;
                double weightedActions = weight <= 0.0 ? 0.0
                    : rows.Sum(row => row.MeanAttacks * row.RepresentativeWeight) / weight;
                var higher = rows.Where(row => row.HigherAdvancedWin.HasValue).ToArray();
                double higherWeight = higher.Sum(row => row.RepresentativeWeight);
                double higherWeighted = higherWeight <= 0.0
                    ? 0.0
                    : higher.Sum(row => row.HigherAdvancedWin!.Value * row.RepresentativeWeight) / higherWeight;
                weightedLines.Add(string.Join(',',
                    CsvQuote(geometry), CsvQuote(cohort), rows.Length.ToString(CultureInfo.InvariantCulture),
                    weight.ToString("R", CultureInfo.InvariantCulture),
                    totalPopulation <= 0.0 ? "0.000000" : F(100.0 * weight / totalPopulation),
                    rows.Length == 0 ? "0.000000" : F(rows.Average(row => row.Unresolved)), F(weightedUnresolved),
                    rows.Length == 0 ? "0.000000" : F(rows.Average(row => row.MeanTurns)), F(weightedTurns),
                    rows.Length == 0 ? "0.000000" : F(rows.Average(row => row.MeanAttacks)), F(weightedActions),
                    higher.Length.ToString(CultureInfo.InvariantCulture),
                    higher.Length == 0 ? "0.000000" : F(higher.Average(row => row.HigherAdvancedWin!.Value)), F(higherWeighted),
                    CsvQuote(cohort == "all_legal"
                        ? "Adaptive statistical-screen estimate over all sampled legal pairs. Cell population weight is divided among that cell's statistical representatives; diversity and named diagnostics are excluded from inference."
                        : cohort == "reference_context_mutual_ready"
                            ? "Adaptive statistical-screen estimate restricted to sampled pairs expected to be mutually ready under the static reference Sensor/EW context for this geometry."
                            : cohort == "observed_reference_ready_window"
                                ? "Adaptive statistical-screen estimate restricted to sampled pairs that actually observed at least one post-Movement firing window satisfying both sides' static reference-context ready ranges."
                                : cohort == "runtime_bilateral_active"
                                    ? "Adaptive statistical-screen estimate restricted only by true runtime bilateral family-appropriate combat activity, independent of the static reference-context readiness estimate."
                                    : "Compatibility bridge matching the CP95 observed_active semantics: static reference-context mutual readiness plus runtime bilateral activity.")));
            }
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "cross-tl-cp96-population-weighted-review.csv"),
            weightedLines, new UTF8Encoding(false));

        var activityLines = new List<string>
        {
            "variant_id,comparison_group,sample_role,bundle_id,orientation,geometry,side_a_family,side_b_family,side_a_readiness,side_b_readiness,side_a_ready_range,side_b_ready_range,side_a_reference_context_expected,side_b_reference_context_expected,reference_context_mutual_ready,observed_reference_ready_window,runtime_bilateral_active,reference_runtime_relation,legacy_cp95_observed_engagement_diagnosis,mean_path_closest_approach_range,mean_minimum_post_movement_range,mean_post_movement_firing_windows,mean_post_movement_ready_windows_a,mean_post_movement_ready_windows_b,mean_post_movement_ready_windows_mutual,post_movement_ready_trials_percent_a,post_movement_ready_trials_percent_b,post_movement_ready_trials_percent_mutual,side_a_direct_opportunities,side_a_direct_shots,side_a_missile_opportunities,side_a_missile_launches,side_b_direct_opportunities,side_b_direct_shots,side_b_missile_opportunities,side_b_missile_launches,aggregate_direct_opportunities,aggregate_direct_shots,aggregate_missile_opportunities,aggregate_missile_launches,side_a_action_outside_structural_ready_estimate,side_b_action_outside_structural_ready_estimate"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(result => result.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(result => result.Id, StringComparer.Ordinal))
        {
            string label = variants[result.Id].ProfileLabel ?? string.Empty;
            string source = CrossTlLabelValue(label, "source");
            string geometry = CrossTlLabelValue(label, "geometry");
            string readinessA = CrossTlLabelValue(label, "readinessA");
            string readinessB = CrossTlLabelValue(label, "readinessB");
            int readyRangeA = int.TryParse(CrossTlLabelValue(label, "readyRangeA"), NumberStyles.Integer,
                CultureInfo.InvariantCulture, out int parsedA) ? parsedA : -1;
            int readyRangeB = int.TryParse(CrossTlLabelValue(label, "readyRangeB"), NumberStyles.Integer,
                CultureInfo.InvariantCulture, out int parsedB) ? parsedB : -1;
            double actionsA = FamilyActions(result, true);
            double actionsB = FamilyActions(result, false);
            string diagnosis = source == "statistical" || source == "diversity"
                ? DiagnoseCrossTlObservedEngagementForSelfTest(
                    geometry, readinessA, readinessB, actionsA, actionsB, result.PostMovementReadyTrialsPercentMutual)
                : "named_diagnostic";
            activityLines.Add(string.Join(',',
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup), CsvQuote(source),
                CsvQuote(CrossTlLabelValue(label, "bundle")), CsvQuote(CrossTlLabelValue(label, "orientation")),
                CsvQuote(geometry), result.SideAFamily, result.SideBFamily, CsvQuote(readinessA), CsvQuote(readinessB),
                readyRangeA.ToString(CultureInfo.InvariantCulture), readyRangeB.ToString(CultureInfo.InvariantCulture),
                CrossTlReadinessIsActive(readinessA, geometry) ? "true" : "false",
                CrossTlReadinessIsActive(readinessB, geometry) ? "true" : "false",
                (CrossTlReadinessIsActive(readinessA, geometry) && CrossTlReadinessIsActive(readinessB, geometry)) ? "true" : "false",
                CrossTlObservedReferenceReadyWindow(result.PostMovementReadyTrialsPercentMutual) ? "true" : "false",
                CrossTlRuntimeBilateralActive(actionsA, actionsB) ? "true" : "false",
                CsvQuote(CrossTlReferenceRuntimeRelation(
                    CrossTlReadinessIsActive(readinessA, geometry) && CrossTlReadinessIsActive(readinessB, geometry),
                    CrossTlRuntimeBilateralActive(actionsA, actionsB))), CsvQuote(diagnosis),
                F(result.MeanMinimumRange), F(result.MeanMinimumPostMovementRange),
                F(result.MeanPostMovementFiringWindows), F(result.MeanPostMovementReadyWindowsA),
                F(result.MeanPostMovementReadyWindowsB), F(result.MeanPostMovementReadyWindowsMutual),
                F(result.PostMovementReadyTrialsPercentA), F(result.PostMovementReadyTrialsPercentB),
                F(result.PostMovementReadyTrialsPercentMutual), F(result.MeanDirectActionOpportunitiesA), F(result.MeanDirectShotsFiredA),
                F(result.MeanMissileLaunchOpportunitiesA), F(result.MeanMissileLaunchesA),
                F(result.MeanDirectActionOpportunitiesB), F(result.MeanDirectShotsFiredB),
                F(result.MeanMissileLaunchOpportunitiesB), F(result.MeanMissileLaunchesB),
                F(result.MeanDirectActionOpportunities), F(result.MeanDirectShotsFired),
                F(result.MeanMissileLaunchOpportunities), F(result.MeanMissileLaunches),
                RuntimeActionOutsideStructuralReadyEstimate(actionsA, result.PostMovementReadyTrialsPercentA) ? "true" : "false",
                RuntimeActionOutsideStructuralReadyEstimate(actionsB, result.PostMovementReadyTrialsPercentB) ? "true" : "false"));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "cross-tl-cp96-activity-review.csv"),
            activityLines, new UTF8Encoding(false));

        var moverRows = new List<(
            string Bundle,
            string Source,
            string PopulationCell,
            double RepresentativeWeight,
            string FamilyPair,
            string InformationBand,
            string ProgressionMagnitude,
            string SpacePair,
            string BuildX,
            string BuildY,
            int AdvancedX,
            int AdvancedY,
            string ReadinessX,
            string ReadinessY,
            int ReadyRangeX,
            int ReadyRangeY,
            bool ReferenceContextMutualReady,
            bool ObservedReferenceReadyWindow,
            bool RuntimeBilateralActive,
            string ReferenceRuntimeRelation,
            double RuntimeActionsX,
            double RuntimeActionsY,
            string ObservedDiagnosis,
            double XFirstWin,
            double XSecondWin,
            double XNeutralWin,
            double YNeutralWin,
            double? HigherAdvancedNeutralWin,
            double InitiativeGap,
            string SensitivityClass,
            double MeanActions,
            double MeanPathClosestApproachRange,
            double MeanMinimumPostMovementRange,
            double PostMovementReadyTrialsPercentMutual) >();
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> bundleGroup in matched
            .Where(result => CrossTlLabelValue(variants[result.Id].ProfileLabel ?? string.Empty, "geometry").StartsWith("dynamic-", StringComparison.Ordinal))
            .GroupBy(result => CrossTlLabelValue(variants[result.Id].ProfileLabel ?? string.Empty, "bundle"), StringComparer.Ordinal)
            .OrderBy(group => group.Key, StringComparer.Ordinal))
        {
            Tl1IntegratedTacticalCombatVariantSummary[] rows = bundleGroup.ToArray();
            if (rows.Length != 4)
            {
                throw new InvalidOperationException(
                    $"CP96 mover-neutral bundle '{bundleGroup.Key}' must contain two orientations across both dynamic movement orders; observed {rows.Length} variants.");
            }
            Tl1IntegratedTacticalCombatVariantSummary Get(string orientation, string geometry) => rows.Single(result =>
            {
                string label = variants[result.Id].ProfileLabel ?? string.Empty;
                return CrossTlLabelValue(label, "orientation") == orientation && CrossTlLabelValue(label, "geometry") == geometry;
            });
            Tl1IntegratedTacticalCombatVariantSummary forwardA = Get("forward", "dynamic-a-first");
            Tl1IntegratedTacticalCombatVariantSummary forwardB = Get("forward", "dynamic-b-first");
            Tl1IntegratedTacticalCombatVariantSummary reverseA = Get("reverse", "dynamic-a-first");
            Tl1IntegratedTacticalCombatVariantSummary reverseB = Get("reverse", "dynamic-b-first");
            string label = variants[forwardA.Id].ProfileLabel ?? string.Empty;
            Tl1IntegratedShipBuildDocument x = builds[variants[forwardA.Id].SideABuildId!];
            Tl1IntegratedShipBuildDocument y = builds[variants[forwardA.Id].SideBBuildId!];
            double xFirst = (ConditionalSideAWinPercent(forwardA) + ConditionalB(reverseB)) / 2.0;
            double xSecond = (ConditionalSideAWinPercent(forwardB) + ConditionalB(reverseA)) / 2.0;
            double yFirst = (ConditionalB(forwardB) + ConditionalSideAWinPercent(reverseA)) / 2.0;
            double ySecond = (ConditionalB(forwardA) + ConditionalSideAWinPercent(reverseB)) / 2.0;
            double xNeutral = (xFirst + xSecond) / 2.0;
            double yNeutral = (yFirst + ySecond) / 2.0;
            double? higherNeutral = (x.AdvancedComponentCount ?? 0) == (y.AdvancedComponentCount ?? 0)
                ? null
                : (x.AdvancedComponentCount ?? 0) > (y.AdvancedComponentCount ?? 0) ? xNeutral : yNeutral;
            string readinessX = CrossTlLabelValue(label, "readinessA");
            string readinessY = CrossTlLabelValue(label, "readinessB");
            int readyRangeX = int.Parse(CrossTlLabelValue(label, "readyRangeA"), CultureInfo.InvariantCulture);
            int readyRangeY = int.Parse(CrossTlLabelValue(label, "readyRangeB"), CultureInfo.InvariantCulture);
            double actionsX = (FamilyActions(forwardA, true) + FamilyActions(forwardB, true) +
                FamilyActions(reverseA, false) + FamilyActions(reverseB, false)) / 4.0;
            double actionsY = (FamilyActions(forwardA, false) + FamilyActions(forwardB, false) +
                FamilyActions(reverseA, true) + FamilyActions(reverseB, true)) / 4.0;
            double meanActions = actionsX + actionsY;
            double meanPathClosestApproachRange = rows.Average(result => result.MeanMinimumRange);
            double meanMinimumPostMovementRange = rows.Average(result => result.MeanMinimumPostMovementRange);
            double postMovementReadyTrialsPercentMutual = rows.Average(result => result.PostMovementReadyTrialsPercentMutual);
            string diagnosis = DiagnoseCrossTlObservedEngagementForSelfTest(
                "dynamic-neutral", readinessX, readinessY, actionsX, actionsY, postMovementReadyTrialsPercentMutual);
            double gap = Math.Abs(xFirst - xSecond);
            moverRows.Add((
                bundleGroup.Key, CrossTlLabelValue(label, "source"), CrossTlLabelValue(label, "populationCell"),
                double.Parse(CrossTlLabelValue(label, "populationRepresentativeWeight"), CultureInfo.InvariantCulture),
                CrossTlLabelValue(label, "familyPair"), CrossTlLabelValue(label, "infoBand"),
                CrossTlLabelValue(label, "progressionMagnitude"), CrossTlLabelValue(label, "spacePair"),
                x.Id, y.Id, x.AdvancedComponentCount ?? 0, y.AdvancedComponentCount ?? 0,
                readinessX, readinessY, readyRangeX, readyRangeY,
                CrossTlReadinessIsActive(readinessX, "dynamic-neutral") && CrossTlReadinessIsActive(readinessY, "dynamic-neutral"),
                CrossTlObservedReferenceReadyWindow(postMovementReadyTrialsPercentMutual),
                CrossTlRuntimeBilateralActive(actionsX, actionsY),
                CrossTlReferenceRuntimeRelation(
                    CrossTlReadinessIsActive(readinessX, "dynamic-neutral") && CrossTlReadinessIsActive(readinessY, "dynamic-neutral"),
                    CrossTlRuntimeBilateralActive(actionsX, actionsY)),
                actionsX, actionsY, diagnosis, xFirst, xSecond, xNeutral, yNeutral, higherNeutral, gap, SensitivityClass(gap), meanActions,
                meanPathClosestApproachRange, meanMinimumPostMovementRange, postMovementReadyTrialsPercentMutual));
        }
        var moverLines = new List<string>
        {
            "bundle_id,sample_role,population_cell,population_representative_weight,weapon_family_pair,information_control_band,progression_magnitude,space_pair_stratum,build_x,build_y,advanced_components_x,advanced_components_y,readiness_x,readiness_y,ready_range_x,ready_range_y,reference_context_mutual_ready,observed_reference_ready_window,runtime_bilateral_active,reference_runtime_relation,runtime_actions_x,runtime_actions_y,legacy_cp95_observed_engagement_diagnosis,x_first_conditional_win_percent,x_second_conditional_win_percent,x_mover_neutral_conditional_win_percent,y_mover_neutral_conditional_win_percent,higher_advanced_mover_neutral_conditional_win_percent,initiative_gap_pp,initiative_sensitivity_class,mean_total_main_actions,mean_path_closest_approach_range,mean_minimum_post_movement_range,post_movement_ready_trials_percent_mutual"
        };
        foreach (var row in moverRows.OrderBy(row => row.Bundle, StringComparer.Ordinal))
        {
            moverLines.Add(string.Join(',',
                CsvQuote(row.Bundle), CsvQuote(row.Source), CsvQuote(row.PopulationCell),
                row.RepresentativeWeight.ToString("R", CultureInfo.InvariantCulture), CsvQuote(row.FamilyPair),
                CsvQuote(row.InformationBand), CsvQuote(row.ProgressionMagnitude), CsvQuote(row.SpacePair),
                CsvQuote(row.BuildX), CsvQuote(row.BuildY), row.AdvancedX.ToString(CultureInfo.InvariantCulture),
                row.AdvancedY.ToString(CultureInfo.InvariantCulture), CsvQuote(row.ReadinessX), CsvQuote(row.ReadinessY),
                row.ReadyRangeX.ToString(CultureInfo.InvariantCulture), row.ReadyRangeY.ToString(CultureInfo.InvariantCulture),
                row.ReferenceContextMutualReady ? "true" : "false", row.ObservedReferenceReadyWindow ? "true" : "false",
                row.RuntimeBilateralActive ? "true" : "false", CsvQuote(row.ReferenceRuntimeRelation),
                F(row.RuntimeActionsX), F(row.RuntimeActionsY), CsvQuote(row.ObservedDiagnosis), F(row.XFirstWin), F(row.XSecondWin),
                F(row.XNeutralWin), F(row.YNeutralWin), row.HigherAdvancedNeutralWin is double higherAdvancedNeutralWin ? F(higherAdvancedNeutralWin) : string.Empty,
                F(row.InitiativeGap), CsvQuote(row.SensitivityClass), F(row.MeanActions),
                F(row.MeanPathClosestApproachRange), F(row.MeanMinimumPostMovementRange),
                F(row.PostMovementReadyTrialsPercentMutual)));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "cross-tl-cp96-mover-neutral-review.csv"),
            moverLines, new UTF8Encoding(false));

        var moverSummaryLines = new List<string>
        {
            "cohort,statistical_bundle_count,population_representative_weight_sum,population_weight_fraction_percent,higher_advanced_bundle_count,raw_mean_higher_advanced_mover_neutral_win_percent,population_weighted_mean_higher_advanced_mover_neutral_win_percent,raw_mean_initiative_gap_pp,population_weighted_mean_initiative_gap_pp,low_sensitivity_count,moderate_sensitivity_count,high_sensitivity_count,extreme_sensitivity_count"
        };
        foreach (string cohort in new[] { "all_legal", "reference_context_mutual_ready", "observed_reference_ready_window", "runtime_bilateral_active", "legacy_cp95_reference_expected_runtime_active" })
        {
            var rows = moverRows.Where(row => row.Source == "statistical" && (cohort switch
            {
                "reference_context_mutual_ready" => row.ReferenceContextMutualReady,
                "observed_reference_ready_window" => row.ObservedReferenceReadyWindow,
                "runtime_bilateral_active" => row.RuntimeBilateralActive,
                "legacy_cp95_reference_expected_runtime_active" => row.ObservedDiagnosis == "active",
                _ => true,
            })).ToArray();
            double weight = rows.Sum(row => row.RepresentativeWeight);
            var higher = rows.Where(row => row.HigherAdvancedNeutralWin.HasValue).ToArray();
            double higherWeight = higher.Sum(row => row.RepresentativeWeight);
            double weightedHigher = higherWeight <= 0.0 ? 0.0 :
                higher.Sum(row => row.HigherAdvancedNeutralWin!.Value * row.RepresentativeWeight) / higherWeight;
            double weightedGap = weight <= 0.0 ? 0.0 :
                rows.Sum(row => row.InitiativeGap * row.RepresentativeWeight) / weight;
            moverSummaryLines.Add(string.Join(',',
                CsvQuote(cohort), rows.Length.ToString(CultureInfo.InvariantCulture), weight.ToString("R", CultureInfo.InvariantCulture),
                totalPopulation <= 0.0 ? "0.000000" : F(100.0 * weight / totalPopulation),
                higher.Length.ToString(CultureInfo.InvariantCulture),
                higher.Length == 0 ? "0.000000" : F(higher.Average(row => row.HigherAdvancedNeutralWin!.Value)), F(weightedHigher),
                rows.Length == 0 ? "0.000000" : F(rows.Average(row => row.InitiativeGap)), F(weightedGap),
                rows.Count(row => row.SensitivityClass == "low").ToString(CultureInfo.InvariantCulture),
                rows.Count(row => row.SensitivityClass == "moderate").ToString(CultureInfo.InvariantCulture),
                rows.Count(row => row.SensitivityClass == "high").ToString(CultureInfo.InvariantCulture),
                rows.Count(row => row.SensitivityClass == "extreme").ToString(CultureInfo.InvariantCulture)));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "cross-tl-cp96-mover-neutral-summary.csv"),
            moverSummaryLines, new UTF8Encoding(false));

        // CP96 preserves one review queue while making the reference-context/runtime boundary explicit.
        // Reference-context readiness is an estimate; true runtime bilateral activity is independent evidence. These rows are diagnostic; the blocking
        // semantics remain owned by the explicit gates above.
        var outlierLines = new List<string>
        {
            "outlier_type,bundle_id,sample_role,geometry,population_cell,population_representative_weight,legacy_cp95_observed_engagement_diagnosis,initiative_sensitivity_class,initiative_gap_pp,mean_path_closest_approach_range,mean_minimum_post_movement_range,post_movement_ready_trials_percent_mutual,mean_total_main_actions,review_priority,variant_id,side,post_movement_ready_trials_percent_side,mean_side_main_actions"
        };
        foreach (var row in pairedRows
            .Where(row => row.Source is "statistical" or "diversity")
            .OrderByDescending(row => row.RepresentativeWeight)
            .ThenBy(row => row.Bundle, StringComparer.Ordinal)
            .ThenBy(row => row.Geometry, StringComparer.Ordinal))
        {
            if (row.ReferenceContextMutualReady && !row.RuntimeBilateralActive)
            {
                string priority = row.ObservedEngagementDiagnosis is "ready_geometry_reached_but_no_actions" or "fixed_reference_ready_geometry_not_observed"
                    ? "blocking" : "review";
                outlierLines.Add(string.Join(',',
                    CsvQuote("reference_expected_runtime_inactive"), CsvQuote(row.Bundle), CsvQuote(row.Source), CsvQuote(row.Geometry),
                    CsvQuote(row.PopulationCell), row.RepresentativeWeight.ToString("R", CultureInfo.InvariantCulture),
                    CsvQuote(row.ObservedEngagementDiagnosis), string.Empty, string.Empty,
                    F(row.MeanPathClosestApproachRange), F(row.MeanMinimumPostMovementRange),
                    F(row.PostMovementReadyTrialsPercentMutual), F(row.MeanAttacks), CsvQuote(priority), string.Empty, string.Empty, string.Empty, string.Empty));
            }
            if (!row.ReferenceContextMutualReady && row.RuntimeBilateralActive)
            {
                outlierLines.Add(string.Join(',',
                    CsvQuote("reference_not_expected_runtime_bilateral_active"), CsvQuote(row.Bundle), CsvQuote(row.Source), CsvQuote(row.Geometry),
                    CsvQuote(row.PopulationCell), row.RepresentativeWeight.ToString("R", CultureInfo.InvariantCulture),
                    CsvQuote(row.ObservedEngagementDiagnosis), string.Empty, string.Empty,
                    F(row.MeanPathClosestApproachRange), F(row.MeanMinimumPostMovementRange),
                    F(row.PostMovementReadyTrialsPercentMutual), F(row.MeanAttacks), CsvQuote("review"), string.Empty, string.Empty, string.Empty, string.Empty));
            }
            if (row.MeanMinimumPostMovementRange - row.MeanPathClosestApproachRange > 0.01)
            {
                outlierLines.Add(string.Join(',',
                    CsvQuote("path_vs_post_movement_divergence"), CsvQuote(row.Bundle), CsvQuote(row.Source), CsvQuote(row.Geometry),
                    CsvQuote(row.PopulationCell), row.RepresentativeWeight.ToString("R", CultureInfo.InvariantCulture),
                    CsvQuote(row.ObservedEngagementDiagnosis), string.Empty, string.Empty,
                    F(row.MeanPathClosestApproachRange), F(row.MeanMinimumPostMovementRange),
                    F(row.PostMovementReadyTrialsPercentMutual), F(row.MeanAttacks), CsvQuote("review"), string.Empty, string.Empty, string.Empty, string.Empty));
            }
        }
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in matched
            .OrderBy(result => result.Id, StringComparer.Ordinal))
        {
            string label = variants[result.Id].ProfileLabel ?? string.Empty;
            string source = CrossTlLabelValue(label, "source");
            string geometry = CrossTlLabelValue(label, "geometry");
            string bundle = CrossTlLabelValue(label, "bundle");
            string populationCell = CrossTlLabelValue(label, "populationCell");
            double representativeWeight = double.TryParse(
                CrossTlLabelValue(label, "populationRepresentativeWeight"),
                NumberStyles.Float, CultureInfo.InvariantCulture, out double parsedWeight)
                ? parsedWeight : 0.0;
            double actionsA = FamilyActions(result, true);
            double actionsB = FamilyActions(result, false);
            double totalActions = actionsA + actionsB;
            string diagnosis = DiagnoseCrossTlObservedEngagementForSelfTest(
                geometry,
                variants[result.Id].SideAEngagementReadinessClass ?? string.Empty,
                variants[result.Id].SideBEngagementReadinessClass ?? string.Empty,
                actionsA, actionsB, result.PostMovementReadyTrialsPercentMutual);

            void AddRuntimeDivergence(string side, double readyTrialPercent, double sideActions)
            {
                if (!RuntimeActionOutsideStructuralReadyEstimate(sideActions, readyTrialPercent)) return;
                outlierLines.Add(string.Join(',',
                    CsvQuote("runtime_action_outside_structural_ready_estimate"), CsvQuote(bundle), CsvQuote(source), CsvQuote(geometry),
                    CsvQuote(populationCell), representativeWeight.ToString("R", CultureInfo.InvariantCulture),
                    CsvQuote(diagnosis), string.Empty, string.Empty,
                    F(result.MeanMinimumRange), F(result.MeanMinimumPostMovementRange),
                    F(result.PostMovementReadyTrialsPercentMutual), F(totalActions), CsvQuote("review"),
                    CsvQuote(result.Id), CsvQuote(side), F(readyTrialPercent), F(sideActions)));
            }

            AddRuntimeDivergence("A", result.PostMovementReadyTrialsPercentA, actionsA);
            AddRuntimeDivergence("B", result.PostMovementReadyTrialsPercentB, actionsB);
        }
        foreach (var row in moverRows
            .Where(row => (row.Source is "statistical" or "diversity") &&
                (row.SensitivityClass is "high" or "extreme"))
            .OrderByDescending(row => row.InitiativeGap)
            .ThenBy(row => row.Bundle, StringComparer.Ordinal))
        {
            outlierLines.Add(string.Join(',',
                CsvQuote("initiative_sensitivity"), CsvQuote(row.Bundle), CsvQuote(row.Source), CsvQuote("dynamic-neutral"),
                CsvQuote(row.PopulationCell), row.RepresentativeWeight.ToString("R", CultureInfo.InvariantCulture),
                CsvQuote(row.ObservedDiagnosis), CsvQuote(row.SensitivityClass), F(row.InitiativeGap),
                F(row.MeanPathClosestApproachRange), F(row.MeanMinimumPostMovementRange),
                F(row.PostMovementReadyTrialsPercentMutual), F(row.MeanActions), CsvQuote("review"), string.Empty, string.Empty, string.Empty, string.Empty));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "cross-tl-cp96-outlier-review.csv"),
            outlierLines, new UTF8Encoding(false));
    }

    private static bool CrossTlObservedReferenceReadyWindow(double mutualReadyTrialPercent) =>
        mutualReadyTrialPercent > 0.000001;

    internal static bool CrossTlObservedReferenceReadyWindowForSelfTest(double mutualReadyTrialPercent) =>
        CrossTlObservedReferenceReadyWindow(mutualReadyTrialPercent);

    private static bool CrossTlRuntimeBilateralActive(double actionsA, double actionsB) =>
        actionsA > 0.000001 && actionsB > 0.000001;

    internal static bool CrossTlRuntimeBilateralActiveForSelfTest(double actionsA, double actionsB) =>
        CrossTlRuntimeBilateralActive(actionsA, actionsB);

    private static string CrossTlReferenceRuntimeRelation(bool referenceContextMutualReady, bool runtimeBilateralActive) =>
        referenceContextMutualReady
            ? runtimeBilateralActive ? "reference_expected_runtime_active" : "reference_expected_runtime_inactive"
            : runtimeBilateralActive ? "reference_not_expected_runtime_active" : "reference_not_expected_runtime_inactive";

    internal static string CrossTlReferenceRuntimeRelationForSelfTest(bool referenceContextMutualReady, bool runtimeBilateralActive) =>
        CrossTlReferenceRuntimeRelation(referenceContextMutualReady, runtimeBilateralActive);

    private static bool RuntimeActionOutsideStructuralReadyEstimate(
        double familyAppropriateActions,
        double structuralReadyTrialPercent) =>
        familyAppropriateActions > 0.01 && structuralReadyTrialPercent <= 0.000001;

    internal static bool RuntimeActionOutsideStructuralReadyEstimateForSelfTest(
        double familyAppropriateActions,
        double structuralReadyTrialPercent) =>
        RuntimeActionOutsideStructuralReadyEstimate(
            familyAppropriateActions, structuralReadyTrialPercent);

    private static bool PostMovementReadyWindowReached(
        int currentRange,
        int? maximumReadyRangeHexes) =>
        maximumReadyRangeHexes is int readyRange && readyRange >= 0 && currentRange <= readyRange;

    internal static bool PostMovementReadyWindowReachedForSelfTest(
        int currentRange,
        int? maximumReadyRangeHexes) =>
        PostMovementReadyWindowReached(currentRange, maximumReadyRangeHexes);

    private static bool CrossTlReadinessIsActive(string readiness, string geometry) =>
        readiness == "reference_ready" ||
        (geometry.StartsWith("dynamic-", StringComparison.Ordinal) && readiness == "closing_ready");

    internal static string DiagnoseCrossTlObservedEngagementForSelfTest(
        string geometry,
        string readinessA,
        string readinessB,
        double actionsA,
        double actionsB,
        double mutualPostMovementReadyTrialPercent)
    {
        bool mutualExpected = CrossTlReadinessIsActive(readinessA, geometry) &&
            CrossTlReadinessIsActive(readinessB, geometry);
        if (!mutualExpected) return "not_mutually_expected";
        if (actionsA > 0.01 && actionsB > 0.01) return "active";
        if (mutualPostMovementReadyTrialPercent <= 0.000001)
        {
            return geometry.StartsWith("dynamic-", StringComparison.Ordinal)
                ? "movement_did_not_reach_mutual_ready_range"
                : "fixed_reference_ready_geometry_not_observed";
        }
        return actionsA <= 0.01 && actionsB <= 0.01
            ? "ready_geometry_reached_but_no_actions"
            : "ready_geometry_reached_but_one_side_inactive";
    }

    private static string CrossTlLabelValue(string label, string key)
    {
        string prefix = key + "=";
        string? part = label.Split('|').FirstOrDefault(value => value.StartsWith(prefix, StringComparison.Ordinal));
        return part is null ? string.Empty : part[prefix.Length..];
    }

    private static void WriteTl2ArmorApAiShieldIntegrationReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        var lines = new List<string>
        {
            "variant_id,comparison_group,geometry,environment,side_a_shield_capacity,side_a_armor_protection,side_a_armor_integrity,side_a_reactor_output,side_a_family,side_b_family,opponent_apen_reference,movement_order,side_a_conditional_win_percent,side_a_wins_percent,side_b_wins_percent,mutual_percent,unresolved_percent,mean_turns,mean_shield_absorption,mean_armor_damage_prevented,mean_armor_integrity_damage,mean_armor_protection_damage,mean_hull_damage,mean_tactical_shield_recharge_power_spent_a,mean_tactical_shield_recharge_denied_by_reserve_a,mean_prevented_insufficient_power,mean_eccm_power_a,mean_pds_attempts,mean_pds_intercepts,mean_direct_shots,mean_missile_launches,review_note"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(r => (variants[r.Id].ProfileLabel ?? string.Empty).StartsWith("firm-reference-", StringComparison.Ordinal) ? 0 : 1)
            .ThenBy(r => variants[r.Id].SideAShieldCapacityOverride ?? 2)
            .ThenBy(r => variants[r.Id].SideAPrimaryArmorProtectionOverride ?? 0)
            .ThenBy(r => variants[r.Id].SideAPrimaryArmorIntegrityOverride ?? 4))
        {
            Tl1IntegratedTacticalCombatVariantDocument variant = variants[result.Id];
            string label = variant.ProfileLabel ?? string.Empty;
            string environment = label.StartsWith("tall-dr1-eccm1-", StringComparison.Ordinal)
                ? "tall-dr1-eccm1" : "firm-reference";
            string geometry = variant.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                ? "fixed-range-3"
                : variant.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst
                    ? "dynamic-side-a-first" : "dynamic-side-b-first";
            int shield = variant.SideAShieldCapacityOverride ?? 2;
            int ap = variant.SideAPrimaryArmorProtectionOverride ?? 0;
            int ai = variant.SideAPrimaryArmorIntegrityOverride ?? 4;
            int opponentApen = result.SideBFamily switch
            {
                WeaponFamily.Kinetic => 0,
                WeaponFamily.Energy => 1,
                WeaponFamily.Missile => 2,
                _ => -1,
            };
            string note = (ap, ai) switch
            {
                (0, 4) => "Accepted TL1 AP0/AI4 armor control.",
                (0, 5) => "Integrity-only AI5 candidate; tests one additional sacrificial armor point without Protection.",
                (1, 4) => "Protection-only AP1 candidate; tests persistent reduction against packets whose APEN does not cancel it.",
                _ => "Combined AP1/AI5 upper/integration sensitivity; not an automatic TL2 bundle.",
            };
            lines.Add(string.Join(',',
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup), CsvQuote(geometry), CsvQuote(environment),
                shield.ToString(CultureInfo.InvariantCulture), ap.ToString(CultureInfo.InvariantCulture),
                ai.ToString(CultureInfo.InvariantCulture),
                (variant.SideAReactorOutputOverride ?? 6).ToString(CultureInfo.InvariantCulture),
                result.SideAFamily, result.SideBFamily, opponentApen.ToString(CultureInfo.InvariantCulture),
                result.MovementOrder, F(ConditionalSideAWinPercent(result)), F(result.SideAWinsPercent),
                F(result.SideBWinsPercent), F(result.MutualPercent), F(result.UnresolvedPercent), F(result.MeanTurns),
                F(result.MeanShieldAbsorption), F(result.MeanArmorDamagePrevented),
                F(result.MeanArmorIntegrityDamage), F(result.MeanArmorProtectionDamage), F(result.MeanHullDamage),
                F(result.MeanTacticalShieldRechargePowerSpentA), F(result.MeanTacticalShieldRechargeDeniedByReserveA),
                F(result.MeanPreventedInsufficientPower), F(result.MeanEccmPowerCommittedA),
                F(result.MeanPdsAttempts), F(result.MeanPdsIntercepts), F(result.MeanDirectShotsFired),
                F(result.MeanMissileLaunches), CsvQuote(note)));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "tl2-armor-ap-ai-shield-integration-review.csv"),
            lines,
            new UTF8Encoding(false));

        var deltaLines = new List<string>
        {
            "comparison_group,geometry,environment,side_a_family,side_b_family,shield_capacity,delta_type,from_ap,from_ai,to_ap,to_ai,conditional_win_delta_pp,mean_turns_delta,mean_shield_absorption_delta,mean_armor_damage_prevented_delta,mean_armor_integrity_damage_delta,mean_armor_protection_damage_delta,mean_hull_damage_delta,mean_tactical_recharge_power_delta_a,mean_prevented_insufficient_power_delta,mean_pds_attempts_delta,mean_direct_shots_delta"
        };
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> context in results
            .GroupBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .OrderBy(g => g.Key, StringComparer.Ordinal))
        {
            foreach (string environment in new[] { "firm-reference", "tall-dr1-eccm1" })
            foreach (int shield in new[] { 2, 3 })
            {
                Tl1IntegratedTacticalCombatVariantSummary? control = FindTl2ArmorResult(
                    context, variants, environment, shield, 0, 4);
                if (control is null) continue;
                foreach ((string deltaType, int ap, int ai) in new[]
                {
                    ("integrity-ai5-minus-control", 0, 5),
                    ("protection-ap1-minus-control", 1, 4),
                    ("combined-ap1-ai5-minus-control", 1, 5),
                })
                {
                    Tl1IntegratedTacticalCombatVariantSummary? candidate = FindTl2ArmorResult(
                        context, variants, environment, shield, ap, ai);
                    if (candidate is null) continue;
                    AppendTl2ArmorDelta(deltaLines, context.Key, variants[control.Id], environment,
                        control, candidate, shield, deltaType, 0, 4, ap, ai);
                }
                Tl1IntegratedTacticalCombatVariantSummary? ai5 = FindTl2ArmorResult(
                    context, variants, environment, shield, 0, 5);
                Tl1IntegratedTacticalCombatVariantSummary? ap1 = FindTl2ArmorResult(
                    context, variants, environment, shield, 1, 4);
                Tl1IntegratedTacticalCombatVariantSummary? combined = FindTl2ArmorResult(
                    context, variants, environment, shield, 1, 5);
                if (ai5 is not null && ap1 is not null && combined is not null)
                {
                    double interaction = ConditionalSideAWinPercent(combined) - ConditionalSideAWinPercent(ap1) -
                        ConditionalSideAWinPercent(ai5) + ConditionalSideAWinPercent(control);
                    deltaLines.Add(string.Join(',', CsvQuote(context.Key),
                        CsvQuote(GeometryLabel(variants[control.Id])), CsvQuote(environment),
                        control.SideAFamily, control.SideBFamily, shield.ToString(CultureInfo.InvariantCulture),
                        CsvQuote("ap-ai-interaction-term"), "0", "4", "1", "5", F(interaction),
                        "0.000000", "0.000000", "0.000000", "0.000000", "0.000000", "0.000000",
                        "0.000000", "0.000000", "0.000000", "0.000000"));
                }
            }
        }
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> context in results
            .GroupBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .OrderBy(g => g.Key, StringComparer.Ordinal))
        {
            foreach (string environment in new[] { "firm-reference", "tall-dr1-eccm1" })
            foreach ((int ap, int ai) in new[] { (0, 4), (0, 5), (1, 4), (1, 5) })
            {
                Tl1IntegratedTacticalCombatVariantSummary? s2 = FindTl2ArmorResult(
                    context, variants, environment, 2, ap, ai);
                Tl1IntegratedTacticalCombatVariantSummary? s3 = FindTl2ArmorResult(
                    context, variants, environment, 3, ap, ai);
                if (s2 is null || s3 is null) continue;
                AppendTl2ArmorDelta(deltaLines, context.Key, variants[s2.Id], environment,
                    s2, s3, 3, "shield3-minus-shield2", ap, ai, ap, ai);
            }
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "tl2-armor-ap-ai-shield-integration-paired-deltas.csv"),
            deltaLines,
            new UTF8Encoding(false));
    }

    private static Tl1IntegratedTacticalCombatVariantSummary? FindTl2ArmorResult(
        IEnumerable<Tl1IntegratedTacticalCombatVariantSummary> context,
        IReadOnlyDictionary<string, Tl1IntegratedTacticalCombatVariantDocument> variants,
        string environment,
        int shield,
        int ap,
        int ai) =>
        context.SingleOrDefault(r =>
            (variants[r.Id].ProfileLabel ?? string.Empty).StartsWith(environment + "-", StringComparison.Ordinal) &&
            variants[r.Id].SideAShieldCapacityOverride == shield &&
            variants[r.Id].SideAPrimaryArmorProtectionOverride == ap &&
            variants[r.Id].SideAPrimaryArmorIntegrityOverride == ai);

    private static string GeometryLabel(Tl1IntegratedTacticalCombatVariantDocument variant) =>
        variant.MovementMode == Tl1IntegratedMovementMode.HoldRange3
            ? "fixed-range-3"
            : variant.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst
                ? "dynamic-side-a-first" : "dynamic-side-b-first";

    private static void AppendTl2ArmorDelta(
        ICollection<string> lines,
        string comparisonGroup,
        Tl1IntegratedTacticalCombatVariantDocument variant,
        string environment,
        Tl1IntegratedTacticalCombatVariantSummary from,
        Tl1IntegratedTacticalCombatVariantSummary to,
        int shield,
        string deltaType,
        int fromAp,
        int fromAi,
        int toAp,
        int toAi)
    {
        lines.Add(string.Join(',', CsvQuote(comparisonGroup), CsvQuote(GeometryLabel(variant)),
            CsvQuote(environment), from.SideAFamily, from.SideBFamily,
            shield.ToString(CultureInfo.InvariantCulture), CsvQuote(deltaType),
            fromAp.ToString(CultureInfo.InvariantCulture), fromAi.ToString(CultureInfo.InvariantCulture),
            toAp.ToString(CultureInfo.InvariantCulture), toAi.ToString(CultureInfo.InvariantCulture),
            F(ConditionalSideAWinPercent(to) - ConditionalSideAWinPercent(from)),
            F(to.MeanTurns - from.MeanTurns), F(to.MeanShieldAbsorption - from.MeanShieldAbsorption),
            F(to.MeanArmorDamagePrevented - from.MeanArmorDamagePrevented),
            F(to.MeanArmorIntegrityDamage - from.MeanArmorIntegrityDamage),
            F(to.MeanArmorProtectionDamage - from.MeanArmorProtectionDamage),
            F(to.MeanHullDamage - from.MeanHullDamage),
            F(to.MeanTacticalShieldRechargePowerSpentA - from.MeanTacticalShieldRechargePowerSpentA),
            F(to.MeanPreventedInsufficientPower - from.MeanPreventedInsufficientPower),
            F(to.MeanPdsAttempts - from.MeanPdsAttempts), F(to.MeanDirectShotsFired - from.MeanDirectShotsFired)));
    }

    private static void WriteTl2ShieldCapacityPowerIntegrationReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        var lines = new List<string>
        {
            "variant_id,comparison_group,geometry,environment,side_a_shield_capacity,side_a_reactor_output,side_a_family,side_b_family,movement_order,side_a_conditional_win_percent,side_a_wins_percent,side_b_wins_percent,mutual_percent,unresolved_percent,mean_turns,mean_shield_absorption,mean_hull_damage,mean_tactical_shield_recharge_opportunities_a,mean_tactical_shield_recharge_power_spent_a,mean_tactical_shield_recharge_denied_by_reserve_a,mean_prevented_insufficient_power,mean_eccm_power_a,mean_pds_attempts,mean_pds_intercepts,mean_direct_shots,mean_missile_launches,review_note"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(r => (variants[r.Id].ProfileLabel ?? string.Empty).StartsWith("firm-reference-", StringComparison.Ordinal) ? 0 : 1)
            .ThenBy(r => variants[r.Id].SideAShieldCapacityOverride ?? 2)
            .ThenBy(r => variants[r.Id].SideAReactorOutputOverride ?? 5))
        {
            Tl1IntegratedTacticalCombatVariantDocument variant = variants[result.Id];
            string label = variant.ProfileLabel ?? string.Empty;
            string environment = label.StartsWith("tall-dr1-eccm1-", StringComparison.Ordinal)
                ? "tall-dr1-eccm1" : "firm-reference";
            string geometry = variant.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                ? "fixed-range-3"
                : variant.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst
                    ? "dynamic-side-a-first" : "dynamic-side-b-first";
            int shield = variant.SideAShieldCapacityOverride ?? 2;
            string note = shield switch
            {
                2 => "Accepted TL1 Shield-capacity control.",
                3 => "Primary TL2 Shield-capacity candidate; capacity only, no recharge/hardening/Space bundle.",
                _ => "Upper Shield 4 sensitivity used to identify nonlinear defensive breakpoints; not a promotion candidate by default.",
            };
            lines.Add(string.Join(',',
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup), CsvQuote(geometry), CsvQuote(environment),
                shield.ToString(CultureInfo.InvariantCulture),
                (variant.SideAReactorOutputOverride ?? 5).ToString(CultureInfo.InvariantCulture),
                result.SideAFamily, result.SideBFamily, result.MovementOrder,
                F(ConditionalSideAWinPercent(result)), F(result.SideAWinsPercent), F(result.SideBWinsPercent),
                F(result.MutualPercent), F(result.UnresolvedPercent), F(result.MeanTurns),
                F(result.MeanShieldAbsorption), F(result.MeanHullDamage),
                F(result.MeanTacticalShieldRechargeOpportunitiesA),
                F(result.MeanTacticalShieldRechargePowerSpentA),
                F(result.MeanTacticalShieldRechargeDeniedByReserveA),
                F(result.MeanPreventedInsufficientPower), F(result.MeanEccmPowerCommittedA),
                F(result.MeanPdsAttempts), F(result.MeanPdsIntercepts),
                F(result.MeanDirectShotsFired), F(result.MeanMissileLaunches), CsvQuote(note)));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "tl2-shield-capacity-power-integration-review.csv"),
            lines,
            new UTF8Encoding(false));

        var deltaLines = new List<string>
        {
            "comparison_group,geometry,environment,side_a_family,side_b_family,reactor_from_output,reactor_to_output,delta_type,from_shield_capacity,to_shield_capacity,conditional_win_delta_pp,mean_turns_delta,mean_shield_absorption_delta,mean_hull_damage_delta,mean_tactical_recharge_opportunity_delta_a,mean_tactical_recharge_power_delta_a,mean_tactical_recharge_denied_delta_a,mean_prevented_insufficient_power_delta,mean_pds_attempts_delta,mean_direct_shots_delta"
        };
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> context in results
            .GroupBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .OrderBy(g => g.Key, StringComparer.Ordinal))
        {
            foreach (string environment in new[] { "firm-reference", "tall-dr1-eccm1" })
            {
                foreach (int reactor in new[] { 5, 6 })
                {
                    var byShield = context.Where(r =>
                        (variants[r.Id].ProfileLabel ?? string.Empty).StartsWith(environment + "-", StringComparison.Ordinal) &&
                        variants[r.Id].SideAReactorOutputOverride == reactor)
                        .ToDictionary(r => variants[r.Id].SideAShieldCapacityOverride ?? 2);
                    if (!byShield.TryGetValue(2, out Tl1IntegratedTacticalCombatVariantSummary? s2)) continue;
                    foreach (int shield in new[] { 3, 4 })
                    {
                        if (!byShield.TryGetValue(shield, out Tl1IntegratedTacticalCombatVariantSummary? sx)) continue;
                        Tl1IntegratedTacticalCombatVariantDocument variant = variants[s2.Id];
                        string geometry = variant.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                            ? "fixed-range-3"
                            : variant.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst
                                ? "dynamic-side-a-first" : "dynamic-side-b-first";
                        deltaLines.Add(string.Join(',', CsvQuote(context.Key), CsvQuote(geometry), CsvQuote(environment),
                            s2.SideAFamily, s2.SideBFamily, reactor.ToString(CultureInfo.InvariantCulture),
                            reactor.ToString(CultureInfo.InvariantCulture), CsvQuote("shield-capacity"),
                            "2", shield.ToString(CultureInfo.InvariantCulture),
                            F(ConditionalSideAWinPercent(sx) - ConditionalSideAWinPercent(s2)),
                            F(sx.MeanTurns - s2.MeanTurns), F(sx.MeanShieldAbsorption - s2.MeanShieldAbsorption),
                            F(sx.MeanHullDamage - s2.MeanHullDamage),
                            F(sx.MeanTacticalShieldRechargeOpportunitiesA - s2.MeanTacticalShieldRechargeOpportunitiesA),
                            F(sx.MeanTacticalShieldRechargePowerSpentA - s2.MeanTacticalShieldRechargePowerSpentA),
                            F(sx.MeanTacticalShieldRechargeDeniedByReserveA - s2.MeanTacticalShieldRechargeDeniedByReserveA),
                            F(sx.MeanPreventedInsufficientPower - s2.MeanPreventedInsufficientPower),
                            F(sx.MeanPdsAttempts - s2.MeanPdsAttempts), F(sx.MeanDirectShotsFired - s2.MeanDirectShotsFired)));
                    }
                }
                foreach (int shield in new[] { 2, 3, 4 })
                {
                    Tl1IntegratedTacticalCombatVariantSummary? r5 = context.SingleOrDefault(r =>
                        variants[r.Id].SideAShieldCapacityOverride == shield &&
                        variants[r.Id].SideAReactorOutputOverride == 5 &&
                        (variants[r.Id].ProfileLabel ?? string.Empty).StartsWith(environment + "-", StringComparison.Ordinal));
                    Tl1IntegratedTacticalCombatVariantSummary? r6 = context.SingleOrDefault(r =>
                        variants[r.Id].SideAShieldCapacityOverride == shield &&
                        variants[r.Id].SideAReactorOutputOverride == 6 &&
                        (variants[r.Id].ProfileLabel ?? string.Empty).StartsWith(environment + "-", StringComparison.Ordinal));
                    if (r5 is null || r6 is null) continue;
                    Tl1IntegratedTacticalCombatVariantDocument variant = variants[r5.Id];
                    string geometry = variant.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                        ? "fixed-range-3"
                        : variant.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst
                            ? "dynamic-side-a-first" : "dynamic-side-b-first";
                    deltaLines.Add(string.Join(',', CsvQuote(context.Key), CsvQuote(geometry), CsvQuote(environment),
                        r5.SideAFamily, r5.SideBFamily, "5", "6", CsvQuote("reactor-r6-minus-r5"),
                        shield.ToString(CultureInfo.InvariantCulture), shield.ToString(CultureInfo.InvariantCulture),
                        F(ConditionalSideAWinPercent(r6) - ConditionalSideAWinPercent(r5)),
                        F(r6.MeanTurns - r5.MeanTurns), F(r6.MeanShieldAbsorption - r5.MeanShieldAbsorption),
                        F(r6.MeanHullDamage - r5.MeanHullDamage),
                        F(r6.MeanTacticalShieldRechargeOpportunitiesA - r5.MeanTacticalShieldRechargeOpportunitiesA),
                        F(r6.MeanTacticalShieldRechargePowerSpentA - r5.MeanTacticalShieldRechargePowerSpentA),
                        F(r6.MeanTacticalShieldRechargeDeniedByReserveA - r5.MeanTacticalShieldRechargeDeniedByReserveA),
                        F(r6.MeanPreventedInsufficientPower - r5.MeanPreventedInsufficientPower),
                        F(r6.MeanPdsAttempts - r5.MeanPdsAttempts), F(r6.MeanDirectShotsFired - r5.MeanDirectShotsFired)));
                }
            }
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "tl2-shield-capacity-power-integration-paired-deltas.csv"),
            deltaLines,
            new UTF8Encoding(false));
    }

    private static void WriteTl2PowerReactorProgressionPermutationReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        var lines = new List<string>
        {
            "variant_id,comparison_group,geometry,environment,side_a_reactor_output,side_a_family,side_b_family,movement_order,side_a_sensor_profile,side_b_ecm_rating,side_a_eccm_rating,approximate_fire_penalty,side_a_conditional_win_percent,side_a_wins_percent,side_b_wins_percent,mutual_percent,unresolved_percent,mean_turns,mean_firm_track_a,mean_approximate_track_a,mean_ecm_power_b,mean_eccm_power_a,mean_active_sensor_power_a,mean_prevented_insufficient_power,mean_direct_shots_a,mean_direct_final_hit_chance_a,direct_hit_percent_a,mean_missile_launches_b,mean_pds_attempts_a,mean_pds_intercepts_a,mean_shield_absorption,mean_hull_damage,review_note"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(r => Tl2PowerReactorPermutationEnvironmentOrder(variants[r.Id].ProfileLabel))
            .ThenBy(r => variants[r.Id].SideAReactorOutputOverride ?? 5))
        {
            Tl1IntegratedTacticalCombatVariantDocument variant = variants[result.Id];
            string label = variant.ProfileLabel ?? string.Empty;
            string environment = label.EndsWith("-r5", StringComparison.Ordinal) ||
                    label.EndsWith("-r6", StringComparison.Ordinal)
                ? label[..^3]
                : label;
            string geometry = variant.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                ? "fixed-range-3"
                : variant.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst
                    ? "dynamic-side-a-first"
                    : "dynamic-side-b-first";
            string note = environment switch
            {
                "firm-reference" => "Clean Firm package; reveals whether extra reactor output is idle or creates a meaningful low-pressure benefit.",
                "wide-eccm2" => "Old Sensor + ECCM2 brute-force Firm restoration; primary support-pressure case for the 6-TP Early Fusion candidate.",
                "tall-dr1-eccm1" => "Validated contemporary DR1 + ECCM1 path; tests whether added reactor output broadens the package without making support choices irrelevant.",
                _ => "Explicit study-only -25 degraded-fire fallback; tests whether extra power changes opportunity costs without weakening the fixed degraded-fire penalty.",
            };
            lines.Add(string.Join(',',
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup), CsvQuote(geometry), CsvQuote(environment),
                (variant.SideAReactorOutputOverride ?? 5).ToString(CultureInfo.InvariantCulture),
                result.SideAFamily, result.SideBFamily, result.MovementOrder,
                CsvQuote(variant.SideASensorEwProfileId ?? variant.SensorEwProfileId ?? string.Empty),
                (variant.SideBEcmNormalRatingOverride ?? 1).ToString(CultureInfo.InvariantCulture),
                (variant.SideAEccmNormalRatingOverride ?? 1).ToString(CultureInfo.InvariantCulture),
                variant.SideAApproximateDirectFireAccuracyPenalty.ToString(CultureInfo.InvariantCulture),
                F(ConditionalSideAWinPercent(result)), F(result.SideAWinsPercent), F(result.SideBWinsPercent),
                F(result.MutualPercent), F(result.UnresolvedPercent), F(result.MeanTurns),
                F(result.MeanFirmTrackEvaluationsA), F(result.MeanApproximateTrackEvaluationsA),
                F(result.MeanEcmPowerCommittedB), F(result.MeanEccmPowerCommittedA),
                F(result.MeanActiveSensorPowerCommittedA), F(result.MeanPreventedInsufficientPower),
                F(result.MeanDirectShotsFired), F(result.MeanDirectFinalHitChance), F(result.DirectHitPercent),
                F(result.MeanMissileLaunches), F(result.MeanPdsAttempts), F(result.MeanPdsIntercepts),
                F(result.MeanShieldAbsorption), F(result.MeanHullDamage), CsvQuote(note)));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "tl2-power-reactor-progression-permutations-review.csv"),
            lines,
            new UTF8Encoding(false));

        var deltaLines = new List<string>
        {
            "comparison_group,geometry,environment,side_a_family,side_b_family,conditional_win_delta_pp_r6_minus_r5,mean_turns_delta,mean_prevented_insufficient_power_delta,mean_direct_shots_delta,mean_direct_final_hit_chance_delta_pp,mean_pds_attempts_delta,mean_pds_intercepts_delta,mean_eccm_power_delta,mean_active_sensor_power_delta"
        };
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> context in results
            .GroupBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .OrderBy(g => g.Key, StringComparer.Ordinal))
        {
            foreach (string environment in new[] { "firm-reference", "wide-eccm2", "tall-dr1-eccm1", "degraded-p25" })
            {
                Tl1IntegratedTacticalCombatVariantSummary? r5 = context.SingleOrDefault(r =>
                    string.Equals(variants[r.Id].ProfileLabel, environment + "-r5", StringComparison.Ordinal));
                Tl1IntegratedTacticalCombatVariantSummary? r6 = context.SingleOrDefault(r =>
                    string.Equals(variants[r.Id].ProfileLabel, environment + "-r6", StringComparison.Ordinal));
                if (r5 is null || r6 is null)
                {
                    continue;
                }
                Tl1IntegratedTacticalCombatVariantDocument variant = variants[r5.Id];
                string geometry = variant.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                    ? "fixed-range-3"
                    : variant.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst
                        ? "dynamic-side-a-first"
                        : "dynamic-side-b-first";
                deltaLines.Add(string.Join(',',
                    CsvQuote(context.Key), CsvQuote(geometry), CsvQuote(environment),
                    r5.SideAFamily, r5.SideBFamily,
                    F(ConditionalSideAWinPercent(r6) - ConditionalSideAWinPercent(r5)),
                    F(r6.MeanTurns - r5.MeanTurns),
                    F(r6.MeanPreventedInsufficientPower - r5.MeanPreventedInsufficientPower),
                    F(r6.MeanDirectShotsFired - r5.MeanDirectShotsFired),
                    F(r6.MeanDirectFinalHitChance - r5.MeanDirectFinalHitChance),
                    F(r6.MeanPdsAttempts - r5.MeanPdsAttempts),
                    F(r6.MeanPdsIntercepts - r5.MeanPdsIntercepts),
                    F(r6.MeanEccmPowerCommittedA - r5.MeanEccmPowerCommittedA),
                    F(r6.MeanActiveSensorPowerCommittedA - r5.MeanActiveSensorPowerCommittedA)));
            }
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "tl2-power-reactor-progression-permutations-paired-deltas.csv"),
            deltaLines,
            new UTF8Encoding(false));
    }

    private static int Tl2PowerReactorPermutationEnvironmentOrder(string? profileLabel)
    {
        string label = profileLabel ?? string.Empty;
        if (label.StartsWith("firm-reference-", StringComparison.Ordinal)) return 0;
        if (label.StartsWith("tall-dr1-eccm1-", StringComparison.Ordinal)) return 1;
        if (label.StartsWith("wide-eccm2-", StringComparison.Ordinal)) return 2;
        if (label.StartsWith("degraded-p25-", StringComparison.Ordinal)) return 3;
        return 99;
    }

