    private static void WriteTl2SensorEwDiscriminationIsolationReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        var lines = new List<string>
        {
            "variant_id,comparison_group,geometry,profile_label,side_a_family,movement_order,side_a_sensor_profile,side_b_sensor_profile,side_b_ecm_policy,side_b_ecm_normal_rating,side_a_eccm_policy,side_a_eccm_normal_rating,approximate_fire_penalty,side_a_conditional_win_percent,side_a_wins_percent,side_b_wins_percent,mutual_percent,unresolved_percent,mean_turns,mean_final_range,mean_minimum_range,mean_maximum_range,mean_firm_track_a,mean_approximate_track_a,mean_no_track_a,mean_ecm_power_b,mean_eccm_power_a,mean_active_sensor_power_a,mean_prevented_track_unavailable,mean_prevented_insufficient_power,mean_direct_shots_a,mean_direct_final_hit_chance_a,direct_hit_percent_a,mean_missile_launches_b,mean_pds_attempts_a,mean_pds_intercepts_a,review_note"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(r => Tl2SensorEwIsolationProfileOrder(variants[r.Id].ProfileLabel)))
        {
            Tl1IntegratedTacticalCombatVariantDocument variant = variants[result.Id];
            string geometry = variant.MovementMode == Tl1IntegratedMovementMode.HoldRange3
                ? "fixed-range-3"
                : "dynamic-track-aware";
            string note = variant.ProfileLabel switch
            {
                "firm-reference" => "Unjammed TL1 Firm reference; TL2 Computer targeting remains deliberately excluded.",
                "tl1-ecm1-eccm1-control" => "Accepted TL1 rating-1 ECM/ECCM consumer control.",
                "tl1-vs-ecm2-firm-only-no-eccm" => "TL1 Sensor DR 0 against candidate ECM 2 without ECCM; Firm-only hard-block diagnostic.",
                "tl1-vs-ecm2-eccm1" => "TL1 Sensor DR 0 plus rating-1 ECCM against candidate ECM 2; expected insufficient-margin diagnostic.",
                "tl1-vs-ecm2-eccm2" => "Wide path: TL1 Sensor DR 0 plus candidate ECCM 2 against candidate ECM 2; review TP/PDS opportunity cost.",
                "tl1-vs-ecm2-p25-no-eccm" => "Explicit study-only -25 degraded-fire fallback; no production weapon promotion.",
                "tl2dr1-vs-ecm1-no-eccm" => "Tall path: candidate Sensor DR 1 against ordinary TL1 ECM 1 without ECCM.",
                "tl2dr1-vs-ecm2-firm-only-no-eccm" => "Candidate Sensor DR 1 alone against contemporary ECM 2; Firm-only hard-block diagnostic.",
                _ => "Tall-plus-support path: candidate Sensor DR 1 plus rating-1 ECCM against candidate ECM 2.",
            };
            lines.Add(string.Join(',',
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup), CsvQuote(geometry),
                CsvQuote(variant.ProfileLabel ?? string.Empty), result.SideAFamily, result.MovementOrder,
                CsvQuote(variant.SideASensorEwProfileId ?? variant.SensorEwProfileId ?? string.Empty),
                CsvQuote(variant.SideBSensorEwProfileId ?? variant.SensorEwProfileId ?? string.Empty),
                variant.SideBEcmPolicy,
                (variant.SideBEcmNormalRatingOverride ?? 1).ToString(CultureInfo.InvariantCulture),
                variant.SideAEccmPolicy,
                (variant.SideAEccmNormalRatingOverride ?? 1).ToString(CultureInfo.InvariantCulture),
                variant.SideAApproximateDirectFireAccuracyPenalty.ToString(CultureInfo.InvariantCulture),
                F(ConditionalSideAWinPercent(result)), F(result.SideAWinsPercent), F(result.SideBWinsPercent),
                F(result.MutualPercent), F(result.UnresolvedPercent), F(result.MeanTurns),
                F(result.MeanFinalRange), F(result.MeanMinimumRange), F(result.MeanMaximumRange),
                F(result.MeanFirmTrackEvaluationsA), F(result.MeanApproximateTrackEvaluationsA),
                F(result.MeanNoTrackEvaluationsA), F(result.MeanEcmPowerCommittedB),
                F(result.MeanEccmPowerCommittedA), F(result.MeanActiveSensorPowerCommittedA),
                F(result.MeanPreventedTrackUnavailable), F(result.MeanPreventedInsufficientPower),
                F(result.MeanDirectShotsFired), F(result.MeanDirectFinalHitChance), F(result.DirectHitPercent),
                F(result.MeanMissileLaunches), F(result.MeanPdsAttempts), F(result.MeanPdsIntercepts),
                CsvQuote(note)));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "tl2-sensor-ew-discrimination-isolation-review.csv"),
            lines,
            new UTF8Encoding(false));
    }

