    internal static bool Tl1ApproximateTrackFirmReferenceIsClean(
        double meanFirmTrackA,
        double meanFirmTrackB,
        double meanEcmPowerA,
        double meanEcmPowerB,
        double meanEccmPowerA,
        double meanEccmPowerB,
        double meanDirectShots,
        double tolerance = 1e-9) =>
        meanFirmTrackA > tolerance &&
        meanFirmTrackB > tolerance &&
        meanEcmPowerA <= tolerance &&
        meanEcmPowerB <= tolerance &&
        meanEccmPowerA <= tolerance &&
        meanEccmPowerB <= tolerance &&
        meanDirectShots > tolerance;

    private static double ConditionalSideAWinPercent(
        Tl1IntegratedTacticalCombatVariantSummary result)
    {
        double decisive = result.SideAWinsPercent + result.SideBWinsPercent;
        return decisive <= 0.0
            ? 0.0
            : 100.0 * result.SideAWinsPercent / decisive;
    }

