        "approx-p30" => 4,
        _ => 99,
    };

    private static void WriteTl1EwAiDoctrineReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        LoadedTl1AiDoctrineRegistry? aiDoctrineRegistry,
        string outputDirectory)
    {
        if (aiDoctrineRegistry is null)
        {
            throw new InvalidOperationException(
                "Checkpoint 73 review output requires the AI doctrine registry.");
        }
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        static double Conditional(Tl1IntegratedTacticalCombatVariantSummary result)
        {
            double decisive = result.SideAWinsPercent + result.SideBWinsPercent;
            return decisive <= 0.0 ? 0.0 : 100.0 * result.SideAWinsPercent / decisive;
        }
        var lines = new List<string>
        {
            "variant_id,comparison_group,ai_doctrine_id,registry_status,ecm_heuristic,eccm_heuristic,uses_hidden_enemy_ratings,side_a_family,side_b_family,movement_order,conditional_side_a_win_percent,side_a_wins_percent,side_b_wins_percent,mutual_percent,unresolved_percent,mean_turns,mean_final_range,mean_firm_track_a,mean_firm_track_b,mean_approximate_track_a,mean_approximate_track_b,mean_ecm_power_a,mean_ecm_power_b,mean_eccm_power_a,mean_eccm_power_b,mean_active_sensor_power_a,mean_active_sensor_power_b,mean_track_denials,mean_power_denials,mean_direct_shots,mean_missile_launches,mean_pds_attempts,review_note"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(result => result.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(result => variants[result.Id].SideAAiDoctrineId, StringComparer.Ordinal))
        {
            Tl1IntegratedTacticalCombatVariantDocument v = variants[result.Id];
            Tl1AiDoctrineDefinitionDocument doctrine = ResolveAiDoctrine(
                aiDoctrineRegistry, v.SideAAiDoctrineId, v.Id, "review");
            lines.Add(string.Join(',', new[]
            {
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup),
                CsvQuote(doctrine.Id), CsvQuote(doctrine.Status),
                doctrine.EcmHeuristic.ToString(), doctrine.EccmHeuristic.ToString(),
                doctrine.InformationPolicy.UsesHiddenEnemyRatings.ToString(CultureInfo.InvariantCulture),
                result.SideAFamily.ToString(), result.SideBFamily.ToString(),
                result.MovementOrder.ToString(), F(Conditional(result)),
                F(result.SideAWinsPercent), F(result.SideBWinsPercent),
                F(result.MutualPercent), F(result.UnresolvedPercent), F(result.MeanTurns),
                F(result.MeanFinalRange), F(result.MeanFirmTrackEvaluationsA),
                F(result.MeanFirmTrackEvaluationsB), F(result.MeanApproximateTrackEvaluationsA),
                F(result.MeanApproximateTrackEvaluationsB), F(result.MeanEcmPowerCommittedA),
                F(result.MeanEcmPowerCommittedB), F(result.MeanEccmPowerCommittedA),
                F(result.MeanEccmPowerCommittedB), F(result.MeanActiveSensorPowerCommittedA),
                F(result.MeanActiveSensorPowerCommittedB), F(result.MeanPreventedTrackUnavailable),
                F(result.MeanPreventedInsufficientPower), F(result.MeanDirectShotsFired),
                F(result.MeanMissileLaunches), F(result.MeanPdsAttempts),
                "ai-doctrine-candidate-evidence-no-automatic-promotion",
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "ew-ai-doctrine-review.csv"),
            lines,
            new UTF8Encoding(false));
    }

    private static void WriteTl1EwAiDoctrineEvidenceDraft(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        LoadedTl1AiDoctrineRegistry? aiDoctrineRegistry,
        int trials,
        string studyResultSha256,
        string outputDirectory)
    {
        if (aiDoctrineRegistry is null)
        {
            throw new InvalidOperationException(
                "Checkpoint 73 evidence capture requires the AI doctrine registry.");
        }
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        static double Conditional(Tl1IntegratedTacticalCombatVariantSummary result)
        {
            double decisive = result.SideAWinsPercent + result.SideBWinsPercent;
            return decisive <= 0.0 ? 0.0 : 100.0 * result.SideAWinsPercent / decisive;
        }

        string[] candidateDoctrineIds =
        {
            "tl1-ew-always-ecm-reactive-eccm-v1",
            "tl1-ew-preserve-offense-v1",
            "tl1-ew-preserve-combat-package-v1",
        };
        string[] allStudyDoctrineIds =
        {
            "tl1-ew-none-v1",
            candidateDoctrineIds[0],
            candidateDoctrineIds[1],
            candidateDoctrineIds[2],
        };

        var doctrineSummaries = allStudyDoctrineIds.Select(doctrineId =>
        {
            Tl1AiDoctrineDefinitionDocument doctrine = ResolveAiDoctrine(
                aiDoctrineRegistry, doctrineId, "evidence", "aggregate");
            Tl1IntegratedTacticalCombatVariantSummary[] doctrineResults = results.Where(result =>
                variants[result.Id].SideAAiDoctrineId == doctrineId).ToArray();
            return new
            {
                doctrineId,
                registryStatus = doctrine.Status,
                ecmHeuristic = doctrine.EcmHeuristic.ToString(),
                eccmHeuristic = doctrine.EccmHeuristic.ToString(),
                usesHiddenEnemyRatings = doctrine.InformationPolicy.UsesHiddenEnemyRatings,
                variantCount = doctrineResults.Length,
                meanEcmPowerPerShip = doctrineResults.Length == 0 ? 0.0 :
                    doctrineResults.Average(result =>
                        (result.MeanEcmPowerCommittedA + result.MeanEcmPowerCommittedB) / 2.0),
                meanEccmPowerPerShip = doctrineResults.Length == 0 ? 0.0 :
                    doctrineResults.Average(result =>
                        (result.MeanEccmPowerCommittedA + result.MeanEccmPowerCommittedB) / 2.0),
                meanActiveSensorPowerPerShip = doctrineResults.Length == 0 ? 0.0 :
                    doctrineResults.Average(result =>
                        (result.MeanActiveSensorPowerCommittedA +
                         result.MeanActiveSensorPowerCommittedB) / 2.0),
                meanPowerDenials = doctrineResults.Length == 0 ? 0.0 :
                    doctrineResults.Average(result => result.MeanPreventedInsufficientPower),
                meanTrackDenials = doctrineResults.Length == 0 ? 0.0 :
                    doctrineResults.Average(result => result.MeanPreventedTrackUnavailable),
                meanPdsAttempts = doctrineResults.Length == 0 ? 0.0 :
                    doctrineResults.Average(result => result.MeanPdsAttempts),
                meanDirectShots = doctrineResults.Length == 0 ? 0.0 :
                    doctrineResults.Average(result => result.MeanDirectShotsFired),
                meanMissileLaunches = doctrineResults.Length == 0 ? 0.0 :
                    doctrineResults.Average(result => result.MeanMissileLaunches),
                meanUnresolvedPercent = doctrineResults.Length == 0 ? 0.0 :
                    doctrineResults.Average(result => result.UnresolvedPercent),
                meanTurns = doctrineResults.Length == 0 ? 0.0 :
                    doctrineResults.Average(result => result.MeanTurns),
            };
        }).ToArray();

        var contexts = results.OrderBy(result => result.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(result => variants[result.Id].SideAAiDoctrineId, StringComparer.Ordinal)
            .Select(result =>
            {
                Tl1IntegratedTacticalCombatVariantDocument variant = variants[result.Id];
                return new
                {
                    variantId = result.Id,
                    comparisonGroup = result.ComparisonGroup,
                    doctrineId = variant.SideAAiDoctrineId,
                    sideAFamily = result.SideAFamily.ToString(),
                    sideBFamily = result.SideBFamily.ToString(),
                    movementOrder = result.MovementOrder.ToString(),
                    conditionalSideAWinPercent = Conditional(result),
                    sideAWinsPercent = result.SideAWinsPercent,
                    sideBWinsPercent = result.SideBWinsPercent,
                    mutualPercent = result.MutualPercent,
                    unresolvedPercent = result.UnresolvedPercent,
                    meanTurns = result.MeanTurns,
                    meanEcmPowerCommittedA = result.MeanEcmPowerCommittedA,
                    meanEcmPowerCommittedB = result.MeanEcmPowerCommittedB,
                    meanEccmPowerCommittedA = result.MeanEccmPowerCommittedA,
                    meanEccmPowerCommittedB = result.MeanEccmPowerCommittedB,
                    meanActiveSensorPowerCommittedA = result.MeanActiveSensorPowerCommittedA,
                    meanActiveSensorPowerCommittedB = result.MeanActiveSensorPowerCommittedB,
                    meanPreventedTrackUnavailable = result.MeanPreventedTrackUnavailable,
                    meanPreventedInsufficientPower = result.MeanPreventedInsufficientPower,
                    meanDirectShotsFired = result.MeanDirectShotsFired,
                    meanMissileLaunches = result.MeanMissileLaunches,
                    meanPdsAttempts = result.MeanPdsAttempts,
                    trialErrors = result.TrialErrors,
                };
            }).ToArray();

        string[] acceptedDoctrineIds = aiDoctrineRegistry.Document.Doctrines
            .Where(doctrine => doctrine.Status == "accepted")
            .Select(doctrine => doctrine.Id)
            .OrderBy(id => id, StringComparer.Ordinal)
            .ToArray();
        Tl1AiDoctrineDefinitionDocument acceptedBaselineDoctrine = ResolveAiDoctrine(
            aiDoctrineRegistry, "tl1-ew-reactive-eccm-v1", "evidence", "accepted-baseline");
        string[] acceptedBaselineEvidenceIds = acceptedBaselineDoctrine.EvidenceIds
            .OrderBy(id => id, StringComparer.Ordinal)
            .ToArray();
        Tl1AiDoctrineEvidenceDocument acceptedBaselineEvidence =
            aiDoctrineRegistry.Document.Evidence.Single(evidence =>
                evidence.Id == "cp72-reactive-eccm-accepted");
        string[] dependencyIds = candidateDoctrineIds
            .Select(id => ResolveAiDoctrine(aiDoctrineRegistry, id, "evidence", "dependencies"))
            .SelectMany(doctrine => doctrine.Dependencies)
            .Distinct(StringComparer.Ordinal)
            .OrderBy(id => id, StringComparer.Ordinal)
            .ToArray();

        var evidenceDraft = new
        {
            schemaVersion = "star-cluster-ai-doctrine-evidence-draft-v1",
            checkpoint = "73",
            studyId = study.Id,
            studyResultSha256,
            trialsPerVariant = trials,
            isSmoke = trials == 1,
            registryVersion = aiDoctrineRegistry.Document.RegistryVersion,
            registrySha256 = aiDoctrineRegistry.Sha256,
            promotionAutomatic = false,
            humanReviewRequired = true,
            acceptedBaselineDoctrineId = "tl1-ew-reactive-eccm-v1",
            acceptedBaselineCheckpoint = acceptedBaselineDoctrine.AcceptedCheckpoint,
            acceptedBaselineEvidenceIds,
            acceptedBaselineEvidenceResultSha256 = acceptedBaselineEvidence.ResultSha256,
            acceptedDoctrineIds,
            candidateDoctrineIds,
            dependencyIds,
            capturePurpose = "Persist CP73 doctrine evidence so future checkpoints can reuse accepted heuristics and revalidate only when declared dependencies change.",
            reviewQuestions = new[]
            {
                "Does preserving ready offense avoid the family-specific TP cliffs seen in CP72 always-on bilateral EW?",
                "Does additionally preserving planned PDS improve Missile-threat survivability without making ECM effectively unused?",
                "Which experimental ECM heuristic, if any, deserves promotion to accepted status after native-result review?",
            },
            doctrineSummaries,
            contexts,
        };
        string json = JsonSerializer.Serialize(
            evidenceDraft,
            new JsonSerializerOptions
            {
                WriteIndented = true,
                Converters = { new JsonStringEnumConverter() },
            });
        string path = Path.Combine(outputDirectory, "ai-doctrine-evidence-draft.json");
        File.WriteAllText(path, json, new UTF8Encoding(false));
        string hash = Convert.ToHexString(
                SHA256.HashData(Encoding.UTF8.GetBytes(json)))
            .ToLowerInvariant();
        File.WriteAllText(
            Path.Combine(outputDirectory, "ai-doctrine-evidence-draft.sha256.txt"),
            $"{hash}  ai-doctrine-evidence-draft.json{Environment.NewLine}",
            new UTF8Encoding(false));
    }

