            lines.Add(string.Join(',', new[]
            {
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup),
                Tl1EcmPowerSweepGeometry(v), Tl1EcmPowerSweepPackage(v),
                (v.SideBEcmNormalPowerCostOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                (v.SideAEccmNormalPowerCostOverride ?? 0).ToString(CultureInfo.InvariantCulture),
                result.SideAFamily.ToString(), result.SideBFamily.ToString(),
                result.MovementOrder.ToString(), F(Conditional(result)),
                F(result.SideAWinsPercent), F(result.SideBWinsPercent),
                F(result.MutualPercent), F(result.UnresolvedPercent), F(result.MeanTurns),
                F(result.MeanFinalRange), F(result.MeanMinimumRange), F(result.MeanMaximumRange),
                F(result.MeanFirmTrackEvaluationsA), F(result.MeanApproximateTrackEvaluationsA),
                F(result.MeanNoTrackEvaluationsA), F(result.MeanFirmTrackEvaluationsB),
                F(result.MeanEcmPowerCommittedB), F(result.MeanEccmPowerCommittedA),
                F(result.MeanActiveSensorPowerCommittedA), F(result.MeanActiveSensorPowerCommittedB),
                F(result.MeanPreventedTrackUnavailable), F(result.MeanPreventedInsufficientPower),
                F(result.MeanDirectShotsFired), F(result.MeanMissileLaunches),
                F(result.MeanPdsAttempts), F(result.MeanFuelSpentA), F(result.MeanFuelSpentB),
                "ecm-power-sweep-diagnostic-no-target-win-gate",
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "ecm-power-cost-point-blank-counterplay-review.csv"),
            lines,
            new UTF8Encoding(false));
    }

    private static void WriteCrossTlAdaptiveEngageProgressionReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        var builds = study.Builds.ToDictionary(build => build.Id, StringComparer.Ordinal);
        static double ConditionalSideA(Tl1IntegratedTacticalCombatVariantSummary result)
        {
            double decisive = result.SideAWinsPercent + result.SideBWinsPercent;
            return decisive <= 0.0 ? 0.0 : 100.0 * result.SideAWinsPercent / decisive;
        }
        static int ParseIntLabel(string label, string key) =>
            int.TryParse(CrossTlLabelValue(label, key), NumberStyles.Integer,
                CultureInfo.InvariantCulture, out int value) ? value : 0;
        static double ParseDoubleLabel(string label, string key) =>
            double.TryParse(CrossTlLabelValue(label, key), NumberStyles.Float,
                CultureInfo.InvariantCulture, out double value) ? value : 0.0;

        var lines = new List<string>
        {
            "variant_id,comparison_group,sample_role,bundle_id,orientation,geometry,composition,progression_direction,progression_distance,progression_magnitude,space_pair,space_delta,family_pair,information_direction,information_distance,information_band,population_cell,population_representative_weight,side_a_build,side_b_build,side_a_advanced_count,side_b_advanced_count,side_a_used_space,side_b_used_space,side_a_family,side_b_family,movement_order,conditional_side_a_win_percent,side_a_wins_percent,side_b_wins_percent,unresolved_percent,mean_turns,mean_final_range,mean_path_closest_approach,mean_post_movement_minimum_range,mean_range_changes,mean_movement_a,mean_movement_b,mean_track_denials,mean_power_denials,mean_direct_shots_a,mean_direct_shots_b,mean_missile_launches_a,mean_missile_launches_b,mean_ecm_power_a,mean_ecm_power_b,mean_eccm_power_a,mean_eccm_power_b,mean_eccm_overload_activations_a,mean_eccm_overload_activations_b,mean_sensor_overload_activations_a,mean_sensor_overload_activations_b,mean_overload_denied_power_a,mean_overload_denied_power_b,mean_overload_denied_strain_a,mean_overload_denied_strain_b,review_note"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .ThenBy(r => r.MovementOrder))
        {
            Tl1IntegratedTacticalCombatVariantDocument v = variants[result.Id];
            string label = v.ProfileLabel ?? string.Empty;
            Tl1IntegratedShipBuildDocument buildA = builds[v.SideABuildId!];
            Tl1IntegratedShipBuildDocument buildB = builds[v.SideBBuildId!];
            lines.Add(string.Join(',', new[]
            {
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup),
                CsvQuote(CrossTlLabelValue(label, "source")),
                CsvQuote(CrossTlLabelValue(label, "bundle")),
                CsvQuote(CrossTlLabelValue(label, "orientation")),
                CsvQuote(CrossTlLabelValue(label, "geometry")),
                CsvQuote(CrossTlLabelValue(label, "composition")),
                CsvQuote(CrossTlLabelValue(label, "progression")),
                ParseIntLabel(label, "distance").ToString(CultureInfo.InvariantCulture),
                CsvQuote(CrossTlLabelValue(label, "progressionMagnitude")),
                CsvQuote(CrossTlLabelValue(label, "spacePair")),
                ParseIntLabel(label, "spaceDelta").ToString(CultureInfo.InvariantCulture),
                CsvQuote(CrossTlLabelValue(label, "familyPair")),
                CsvQuote(CrossTlLabelValue(label, "infoDirection")),
                ParseIntLabel(label, "infoDistance").ToString(CultureInfo.InvariantCulture),
                CsvQuote(CrossTlLabelValue(label, "infoBand")),
                CsvQuote(CrossTlLabelValue(label, "populationCell")),
                ParseDoubleLabel(label, "populationRepresentativeWeight").ToString("R", CultureInfo.InvariantCulture),
                CsvQuote(v.SideABuildId ?? string.Empty), CsvQuote(v.SideBBuildId ?? string.Empty),
                buildA.AdvancedComponentCount.GetValueOrDefault().ToString(CultureInfo.InvariantCulture),
                buildB.AdvancedComponentCount.GetValueOrDefault().ToString(CultureInfo.InvariantCulture),
                buildA.UsedSpace.ToString(CultureInfo.InvariantCulture),
                buildB.UsedSpace.ToString(CultureInfo.InvariantCulture),
                result.SideAFamily.ToString(), result.SideBFamily.ToString(), result.MovementOrder.ToString(),
                F(ConditionalSideA(result)), F(result.SideAWinsPercent), F(result.SideBWinsPercent),
                F(result.UnresolvedPercent), F(result.MeanTurns), F(result.MeanFinalRange),
                F(result.MeanMinimumRange), F(result.MeanMinimumPostMovementRange), F(result.MeanRangeChanges),
                F(result.MeanMovementHexesA), F(result.MeanMovementHexesB),
                F(result.MeanPreventedTrackUnavailable), F(result.MeanPreventedInsufficientPower),
                F(result.MeanDirectShotsFiredA), F(result.MeanDirectShotsFiredB),
                F(result.MeanMissileLaunchesA), F(result.MeanMissileLaunchesB),
                F(result.MeanEcmPowerCommittedA), F(result.MeanEcmPowerCommittedB),
                F(result.MeanEccmPowerCommittedA), F(result.MeanEccmPowerCommittedB),
                F(result.MeanEccmOverloadActivationsA), F(result.MeanEccmOverloadActivationsB),
                F(result.MeanSensorOverloadActivationsA), F(result.MeanSensorOverloadActivationsB),
                F(result.MeanOverloadDeniedPowerA), F(result.MeanOverloadDeniedPowerB),
                F(result.MeanOverloadDeniedStrainA), F(result.MeanOverloadDeniedStrainB),
                CsvQuote("Adaptive Engage cross-progression screening evidence; no automatic technology promotion"),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "cross-tl-cp98-adaptive-progression-review.csv"),
            lines, new UTF8Encoding(false));

        var moverLines = new List<string>
        {
            "comparison_group,sample_role,bundle_id,orientation,composition,progression_direction,progression_distance,progression_magnitude,space_pair,family_pair,information_band,population_cell,population_representative_weight,side_a_build,side_b_build,side_a_advanced_count,side_b_advanced_count,side_a_family,side_b_family,a_first_conditional_side_a_win_percent,b_first_conditional_side_a_win_percent,b_first_minus_a_first_pp,mean_unresolved_percent,mean_turns,mean_final_range,mean_path_closest_approach,mean_post_movement_minimum_range,mean_track_denials,mean_power_denials,mean_overload_denied_strain,interpretation"
        };
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> group in results
            .GroupBy(r => r.ComparisonGroup, StringComparer.Ordinal)
            .OrderBy(group => group.Key, StringComparer.Ordinal))
        {
            Tl1IntegratedTacticalCombatVariantSummary aFirst = group.Single(r =>
                r.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst);
            Tl1IntegratedTacticalCombatVariantSummary bFirst = group.Single(r =>
                r.MovementOrder == Tl1IntegratedMovementOrder.SideBFirst);
            Tl1IntegratedTacticalCombatVariantDocument v = variants[aFirst.Id];
            string label = v.ProfileLabel ?? string.Empty;
            Tl1IntegratedShipBuildDocument buildA = builds[v.SideABuildId!];
            Tl1IntegratedShipBuildDocument buildB = builds[v.SideBBuildId!];
            double conditionalAFirst = ConditionalSideA(aFirst);
            double conditionalBFirst = ConditionalSideA(bFirst);
            moverLines.Add(string.Join(',', new[]
            {
                CsvQuote(group.Key), CsvQuote(CrossTlLabelValue(label, "source")),
                CsvQuote(CrossTlLabelValue(label, "bundle")), CsvQuote(CrossTlLabelValue(label, "orientation")),
                CsvQuote(CrossTlLabelValue(label, "composition")), CsvQuote(CrossTlLabelValue(label, "progression")),
                ParseIntLabel(label, "distance").ToString(CultureInfo.InvariantCulture),
                CsvQuote(CrossTlLabelValue(label, "progressionMagnitude")),
                CsvQuote(CrossTlLabelValue(label, "spacePair")), CsvQuote(CrossTlLabelValue(label, "familyPair")),
                CsvQuote(CrossTlLabelValue(label, "infoBand")), CsvQuote(CrossTlLabelValue(label, "populationCell")),
                ParseDoubleLabel(label, "populationRepresentativeWeight").ToString("R", CultureInfo.InvariantCulture),
                CsvQuote(v.SideABuildId ?? string.Empty), CsvQuote(v.SideBBuildId ?? string.Empty),
                buildA.AdvancedComponentCount.GetValueOrDefault().ToString(CultureInfo.InvariantCulture),
                buildB.AdvancedComponentCount.GetValueOrDefault().ToString(CultureInfo.InvariantCulture),
                aFirst.SideAFamily.ToString(), aFirst.SideBFamily.ToString(),
                F(conditionalAFirst), F(conditionalBFirst), F(conditionalBFirst - conditionalAFirst),
                F(group.Average(r => r.UnresolvedPercent)), F(group.Average(r => r.MeanTurns)),
                F(group.Average(r => r.MeanFinalRange)), F(group.Average(r => r.MeanMinimumRange)),
                F(group.Average(r => r.MeanMinimumPostMovementRange)),
                F(group.Average(r => r.MeanPreventedTrackUnavailable)),
                F(group.Average(r => r.MeanPreventedInsufficientPower)),
                F(group.Average(r => r.MeanOverloadDeniedStrainA + r.MeanOverloadDeniedStrainB)),
                CsvQuote("Mover-neutral review pair; initiative difference is diagnostic, not a balance gate"),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "cross-tl-cp98-mover-neutral-review.csv"),
            moverLines, new UTF8Encoding(false));
    }

    private static void WriteCrossTlExactEdgeProgressionReview(
        Tl1IntegratedTacticalCombatStudyDocument study,
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var variants = study.Variants.ToDictionary(v => v.Id, StringComparer.Ordinal);
        var builds = study.Builds.ToDictionary(build => build.Id, StringComparer.Ordinal);
        var lines = new List<string>
        {
            "variant_id,comparison_group,transition_id,expected_advanced_component_delta,weapon_family,composition_class,space_class,movement_order,lower_build,higher_build,used_space,lower_advanced_components,higher_advanced_components,lower_wins_percent,higher_wins_percent,unresolved_percent,mean_turns,mean_final_range,mean_post_movement_minimum_range,mean_track_denials,mean_power_denials,mean_strain_denials,review_note"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .OrderBy(r => r.ComparisonGroup, StringComparer.Ordinal).ThenBy(r => r.MovementOrder))
        {
            Tl1IntegratedTacticalCombatVariantDocument v = variants[result.Id];
            Tl1IntegratedShipBuildDocument lower = builds[v.SideABuildId!];
            Tl1IntegratedShipBuildDocument higher = builds[v.SideBBuildId!];
            string label = v.ProfileLabel ?? string.Empty;
            lines.Add(string.Join(',', new[]
            {
                CsvQuote(result.Id), CsvQuote(result.ComparisonGroup),
                CsvQuote(CrossTlLabelValue(label, "transition")),
                CsvQuote(CrossTlLabelValue(label, "expectedAdvancedDelta")),
                result.SideAFamily.ToString(), CsvQuote(lower.CrossTlCompositionClass ?? string.Empty),
                CsvQuote(lower.UsedSpace == 35 ? "exact_fill" : lower.UsedSpace >= 32 ? "near_fill" : "underfilled"),
                result.MovementOrder.ToString(), CsvQuote(lower.Id), CsvQuote(higher.Id),
                lower.UsedSpace.ToString(CultureInfo.InvariantCulture),
                lower.AdvancedComponentCount.GetValueOrDefault().ToString(CultureInfo.InvariantCulture),
                higher.AdvancedComponentCount.GetValueOrDefault().ToString(CultureInfo.InvariantCulture),
                F(result.SideAWinsPercent), F(result.SideBWinsPercent), F(result.UnresolvedPercent),
                F(result.MeanTurns), F(result.MeanFinalRange), F(result.MeanMinimumPostMovementRange),
                F(result.MeanPreventedTrackUnavailable), F(result.MeanPreventedInsufficientPower),
                F(result.MeanOverloadDeniedStrainA + result.MeanOverloadDeniedStrainB),
                CsvQuote("Exact same-Space one-axis lower->higher comparison; mover order remains diagnostic"),
            }));
        }
        File.WriteAllLines(Path.Combine(outputDirectory, "cross-tl-cp99-exact-edge-review.csv"), lines, new UTF8Encoding(false));

        var moverLines = new List<string>
        {
            "comparison_group,transition_id,expected_advanced_component_delta,weapon_family,composition_class,space_class,lower_build,higher_build,lower_advanced_components,higher_advanced_components,higher_win_when_lower_moves_first,higher_win_when_higher_moves_first,mover_order_delta,mean_unresolved_percent,mean_turns,mean_final_range,mean_track_denials,review_note"
        };
        foreach (IGrouping<string, Tl1IntegratedTacticalCombatVariantSummary> group in results
            .GroupBy(r => r.ComparisonGroup, StringComparer.Ordinal).OrderBy(g => g.Key, StringComparer.Ordinal))
        {
            Tl1IntegratedTacticalCombatVariantSummary aFirst = group.Single(r => r.MovementOrder == Tl1IntegratedMovementOrder.SideAFirst);
            Tl1IntegratedTacticalCombatVariantSummary bFirst = group.Single(r => r.MovementOrder == Tl1IntegratedMovementOrder.SideBFirst);
            Tl1IntegratedTacticalCombatVariantDocument v = variants[aFirst.Id];
            Tl1IntegratedShipBuildDocument lower = builds[v.SideABuildId!];
            Tl1IntegratedShipBuildDocument higher = builds[v.SideBBuildId!];
            string label = v.ProfileLabel ?? string.Empty;
            double higherWhenLowerMovesFirst = aFirst.SideBWinsPercent;
            double higherWhenHigherMovesFirst = bFirst.SideBWinsPercent;
            moverLines.Add(string.Join(',', new[]
            {
                CsvQuote(group.Key), CsvQuote(CrossTlLabelValue(label, "transition")),
                CsvQuote(CrossTlLabelValue(label, "expectedAdvancedDelta")), aFirst.SideAFamily.ToString(),
                CsvQuote(lower.CrossTlCompositionClass ?? string.Empty),
                CsvQuote(lower.UsedSpace == 35 ? "exact_fill" : lower.UsedSpace >= 32 ? "near_fill" : "underfilled"),
                CsvQuote(lower.Id), CsvQuote(higher.Id),
                lower.AdvancedComponentCount.GetValueOrDefault().ToString(CultureInfo.InvariantCulture),
                higher.AdvancedComponentCount.GetValueOrDefault().ToString(CultureInfo.InvariantCulture),
                F(higherWhenLowerMovesFirst), F(higherWhenHigherMovesFirst),
                F(higherWhenHigherMovesFirst - higherWhenLowerMovesFirst),
                F(group.Average(r => r.UnresolvedPercent)), F(group.Average(r => r.MeanTurns)),
                F(group.Average(r => r.MeanFinalRange)), F(group.Average(r => r.MeanPreventedTrackUnavailable)),
                CsvQuote("Mover-order pair for marginal upgrade review; no automatic promotion threshold"),
            }));
        }
        File.WriteAllLines(Path.Combine(outputDirectory, "cross-tl-cp99-exact-edge-mover-neutral-review.csv"), moverLines, new UTF8Encoding(false));
    }

