    private static void WriteMinimalTacticsReviewGrid(
        IReadOnlyList<Tl1IntegratedTacticalCombatVariantSummary> results,
        string outputDirectory)
    {
        var lines = new List<string>
        {
            "variant_id,range,side_a_family,side_b_family,mean_turns,over_18_turns_percent,side_a_wins_percent,side_b_wins_percent,unresolved_percent,advantage_band,pacing_flag,review_note"
        };
        foreach (Tl1IntegratedTacticalCombatVariantSummary result in results
            .Where(item => item.ProfileLabel == "minimal-primary-ap0")
            .OrderBy(item => InitialRange(item.MovementMode))
            .ThenBy(item => item.SideAFamily)
            .ThenBy(item => item.SideBFamily))
        {
            double strongestWin = Math.Max(
                result.SideAWinsPercent,
                result.SideBWinsPercent);
            string advantageBand = strongestWin switch
            {
                <= 55.0 => "essentially-even",
                <= 65.0 => "soft-advantage",
                <= 75.0 => "strong-advantage-review",
                <= 80.0 => "large-advantage-review",
                _ => "likely-baseline-gap-review",
            };
            string pacingFlag = result.UnresolvedPercent > 5.0
                ? "unresolved-review"
                : result.MeanTurns > LongCombatThreshold ||
                    result.Over18TurnsPercent > 50.0
                    ? "long-combat-review"
                    : "within-review-band";
            string note = result.SideAFamily != WeaponFamily.Missile &&
                result.SideBFamily != WeaponFamily.Missile &&
                result.MeanDirectShotsFired <= 0.000001
                ? "range-envelope-control"
                : advantageBand.Contains("review", StringComparison.Ordinal) ||
                    pacingFlag.Contains("review", StringComparison.Ordinal)
                    ? "inspect; non-blocking balance signal"
                    : "no large baseline signal";
            lines.Add(string.Join(',', new[]
            {
                CsvQuote(result.Id),
                InitialRange(result.MovementMode).ToString(
                    CultureInfo.InvariantCulture),
                result.SideAFamily.ToString(),
                result.SideBFamily.ToString(),
                F(result.MeanTurns),
                F(result.Over18TurnsPercent),
                F(result.SideAWinsPercent),
                F(result.SideBWinsPercent),
                F(result.UnresolvedPercent),
                advantageBand,
                pacingFlag,
                CsvQuote(note),
            }));
        }
        File.WriteAllLines(
            Path.Combine(outputDirectory, "review-grid.csv"),
            lines,
            new UTF8Encoding(false));
    }

