    private static JsonSerializerOptions JsonOptions()
    {
        var options = new JsonSerializerOptions
        {
            PropertyNameCaseInsensitive = false,
        };
        options.Converters.Add(new JsonStringEnumConverter());
        return options;
    }

    private static string F(double value) =>
        value.ToString("0.000000", CultureInfo.InvariantCulture);

    private static bool IsSingleSourcePolicyTelemetryStudy(string studyId) =>
        studyId == MinimalTacticsStudyId ||
        studyId == Tl2CandidateStudyId ||
        studyId == AuxiliaryPerformanceScreeningStudyId ||
        studyId == ArchitectureDerivedAuxiliaryStudyId ||
        studyId == StatefulAuxiliaryTuningStudyId ||
        studyId == AuxiliaryRefinementStudyId ||
        studyId == Tl2AblativeCandidateStudyId ||
        studyId == AuxiliaryPowerStressStudyId ||
        studyId == Tl1ComposedShipStudyId ||
        studyId == Tl1PowerDoctrineStudyId ||
        studyId == Tl1OperationalSensorStudyId ||
        studyId == Tl1TrackAwareAcquisitionStudyId ||
        studyId == Tl1BilateralTacticalGeometryStudyId ||
        studyId == Tl1ScriptedOverloadTacticsStudyId ||
        studyId == Tl1BilateralOverloadCounterplayStudyId ||
        studyId == Tl1SensorEwCandidateCombatStudyId ||
        studyId == Tl1EcmPowerCostCounterplayStudyId ||
        studyId == Tl1SensorDiscriminationBurnthroughStudyId ||
        studyId == Tl1ReactiveEwSubphaseStudyId ||
        studyId == Tl1EwAiDoctrineStudyId ||
        studyId == Tl1ApproximateTrackDegradedFireStudyId ||
        studyId == Tl1AppliedDegradedFireFamilyCandidateStudyId ||
        studyId == Tl1DegradedFireEccmValueStudyId ||
        studyId == Tl2SensorEwDiscriminationIsolationStudyId ||
        studyId == Tl2EwPowerPressureTallViabilityStudyId ||
        studyId == Tl2TacticalComputerEwPermutationStudyId ||
        studyId == Tl2PowerReactorProgressionPermutationStudyId ||
        studyId == Tl2ShieldCapacityPowerIntegrationStudyId ||
        studyId == Tl2ArmorApAiShieldIntegrationStudyId ||
        studyId == Tl2WeaponPenetrationLayeredDefenseStudyId ||
        studyId == CrossTlBuildPermutationScreeningStudyId ||
        studyId == CrossTlPowerAwareInformationControlScreeningStudyId ||
        studyId == CrossTlGeneralizedLegalBuildScreeningStudyId ||
        studyId == CrossTlMatchedReadinessSpaceScreeningStudyId ||
        IsAdaptiveEncounterStudy(studyId) ||
        IsTl3CandidateStudy(studyId) ||
        IsTl3LowTechCapstoneStudy(studyId) ||
        IsCheckpoint56Study(studyId) ||
        IsCheckpoint57Study(studyId) ||
        IsCheckpoint58Study(studyId);

    private static bool IsStatefulAuxiliaryStudy(string studyId) =>
        studyId == Tl2ShieldCapacityPowerIntegrationStudyId ||
        studyId == Tl2ArmorApAiShieldIntegrationStudyId ||
        studyId == Tl2WeaponPenetrationLayeredDefenseStudyId ||
        studyId == CrossTlBuildPermutationScreeningStudyId ||
        studyId == CrossTlPowerAwareInformationControlScreeningStudyId ||
        studyId == CrossTlGeneralizedLegalBuildScreeningStudyId ||
        studyId == CrossTlMatchedReadinessSpaceScreeningStudyId ||
        studyId == CrossTlAdaptiveEngageProgressionScreeningStudyId ||
        studyId == CrossTlExactEdgeProgressionScreeningStudyId ||
        studyId == Tl3Cp102TransitionSmokeStudyId ||
        (studyId is StatefulAuxiliaryTuningStudyId or
            AuxiliaryRefinementStudyId or
            Tl2AblativeCandidateStudyId or
            AuxiliaryPowerStressStudyId) ||
        IsTl3CandidateStudy(studyId) ||
        IsTl3LowTechCapstoneStudy(studyId) ||
        IsCheckpoint56Study(studyId) ||
        IsCheckpoint57Study(studyId) ||
        IsCheckpoint58Study(studyId);

    private static bool IsTl3CandidateStudy(string studyId) =>
        studyId is Tl3StandardProfileStudyId or
            Tl3TwoBayLoadoutStudyId or
            Tl3AuxiliaryLoadoutStudyId or
            Tl3PowerEnvelopeStudyId;

    private static bool IsTl3LowTechCapstoneStudy(string studyId) =>
        studyId is Tl3LowTechProfileStudyId or
            Tl3LowTechAuxStudyId or
            Tl3LowTechAuxIsolationStudyId or
            Tl3LowTechPowerStudyId;

    private static bool IsCheckpoint56Study(string studyId) =>
        studyId is Tl3DefensiveMicrostepStudyId or
            Tl3AuxiliaryRetestStudyId or
            Tl3ShieldBreakpointStudyId or
            Tl3CrossTlAuxStudyId or
            Tl3PowerCharacteristicStudyId or
            Tl3EqualCapacityPowerStudyId;

    private static bool IsCheckpoint57Study(string studyId) =>
        studyId is Tl4FoundationTransitionStudyId or
            Tl4TwoBayLoadoutStudyId or
            Tl4SpecializationResistanceStudyId or
            Tl4NaturalPowerStudyId or
            Tl4MixedPowerStudyId;

    private static bool IsCheckpoint58Study(string studyId) =>
        studyId is Tl4SingleMainAxisStudyId or
            Tl4FoundationPackageStudyId or
            Tl4SingleMainSpecializationResistanceStudyId or
            Tl4PoweredDefenseIsolationStudyId or
            Tl4PoweredDefensePowerPairingStudyId or
            Tl4SingleMainNaturalPowerStudyId;

    private static string CsvQuote(string value) =>
        "\"" + value.Replace("\"", "\"\"") + "\"";

