        public void Add(IntegratedTrialOutcome outcome)
        {
            _turns.Add(outcome.Turns);
            _longCombats += outcome.Over18Turns ? 1 : 0;
            _sideAWins += outcome.Winner == IntegratedWinner.SideA ? 1 : 0;
            _sideBWins += outcome.Winner == IntegratedWinner.SideB ? 1 : 0;
            _mutual += outcome.Winner == IntegratedWinner.Mutual ? 1 : 0;
            _unresolved += outcome.Winner == IntegratedWinner.Unresolved ? 1 : 0;
            _destruction += outcome.ResolutionCause ==
                IntegratedResolutionCause.Destruction ? 1 : 0;
            _offensiveMissionKill += outcome.ResolutionCause ==
                IntegratedResolutionCause.OffensiveMissionKill ? 1 : 0;
            _mobilityMissionKill += outcome.ResolutionCause ==
                IntegratedResolutionCause.MobilityMissionKill ? 1 : 0;
            _disengagement += outcome.ResolutionCause ==
                IntegratedResolutionCause.Disengagement ? 1 : 0;
            _finalRange += outcome.FinalRange;
            _minimumRange += outcome.MinimumRange;
            _maximumRange += outcome.MaximumRange;
            _minimumPostMovementRange += outcome.MinimumPostMovementRange;
            _postMovementFiringWindows += outcome.PostMovementFiringWindows;
            _postMovementReadyWindowsA += outcome.PostMovementReadyWindowsA;
            _postMovementReadyWindowsB += outcome.PostMovementReadyWindowsB;
            _postMovementReadyWindowsMutual += outcome.PostMovementReadyWindowsMutual;
            _postMovementReadyTrialsA += outcome.PostMovementReadyWindowsA > 0 ? 1 : 0;
            _postMovementReadyTrialsB += outcome.PostMovementReadyWindowsB > 0 ? 1 : 0;
            _postMovementReadyTrialsMutual += outcome.PostMovementReadyWindowsMutual > 0 ? 1 : 0;
            _rangeChanges += outcome.RangeChanges;
            _orderRequests += outcome.OrderRequests;
            _orderCoercions += outcome.OrderCoercions;
            _scriptedRequests += outcome.ScriptedRequests;
            _preferredRequests += outcome.PreferredRequests;
            _movementA += outcome.MovementA;
            _movementB += outcome.MovementB;
            _fuelSpentA += outcome.FuelSpentA;
            _fuelSpentB += outcome.FuelSpentB;
            _fuelRemainingA += outcome.FuelRemainingA;
            _fuelRemainingB += outcome.FuelRemainingB;
            _boundaryTurnsA += outcome.BoundaryTurnsA;
            _boundaryTurnsB += outcome.BoundaryTurnsB;
            _immobileMovementCoercions += outcome.ImmobileMovementCoercions;
            _missileReroutes += outcome.MissileReroutes;
            _targetMovementReroutes += outcome.TargetMovementReroutes;
            _missileDistanceTraveled += outcome.MissileDistanceTraveled;
            _maximumObservedMissileDistance = Math.Max(
                _maximumObservedMissileDistance,
                outcome.MaximumObservedMissileDistance);
            _missileLaunches += outcome.MissileLaunches;
            _missileTerminalAttacks += outcome.MissileTerminalAttacks;
            _missileHits += outcome.MissileHits;
            _missilesRangeExhausted += outcome.MissilesRangeExhausted;
            _pdsAttempts += outcome.PdsAttempts;
            _pdsIntercepts += outcome.PdsIntercepts;
            _immobileBonusAttacks += outcome.ImmobileBonusAttacks;
            _sameTurnViolations += outcome.SameTurnImmobileBonusViolations;
            _criticalSelections += outcome.CriticalSelections;
            if (outcome.FirstCriticalTurn is int firstCritical)
            {
                _firstCriticalTurns += firstCritical;
                _firstCriticalObservations++;
            }
            if (outcome.FirstConsequentialTurn is int firstConsequential)
            {
                _firstConsequentialTurns += firstConsequential;
                _firstConsequentialObservations++;
            }
            _mobilityLossObserved += outcome.MobilityLossObserved ? 1 : 0;
            _repairAttempts += outcome.RepairAttempts;
            _repairActivations += outcome.RepairActivations;
            _invalidRepairAttempts += outcome.InvalidRepairAttempts;
            _combinedKitsRemaining += outcome.CombinedKitsRemaining;
            _minimumCombinedKitsRemaining = Math.Min(
                _minimumCombinedKitsRemaining,
                outcome.CombinedKitsRemaining);
            _combinedHullAtEnd += outcome.CombinedHullAtEnd;

            IntegratedDiagnosticTelemetry d = outcome.Diagnostics;
            _directActionOpportunities += d.DirectActionOpportunities;
            _directShotsFired += d.DirectShotsFired;
            _directActionOpportunitiesA += d.DirectActionOpportunitiesA;
            _directActionOpportunitiesB += d.DirectActionOpportunitiesB;
            _directShotsFiredA += d.DirectShotsFiredA;
            _directShotsFiredB += d.DirectShotsFiredB;
            _directHits += d.DirectHits;
            _directHitChanceTotal += d.DirectHitChanceTotal;
            _directHitChanceObservations += d.DirectHitChanceObservations;
            _missileLaunchOpportunities += d.MissileLaunchOpportunities;
            _missileLaunchOpportunitiesA += d.MissileLaunchOpportunitiesA;
            _missileLaunchOpportunitiesB += d.MissileLaunchOpportunitiesB;
            _missileLaunchesA += d.MissileLaunchesA;
            _missileLaunchesB += d.MissileLaunchesB;
            _missileTerminalHitChanceTotal += d.MissileTerminalHitChanceTotal;
            _missileTerminalHitChanceObservations +=
                d.MissileTerminalHitChanceObservations;
            _preventedOutOfRange += d.PreventedOutOfRange;
            _preventedSystemUnavailable += d.PreventedSystemUnavailable;
            _preventedRecycling += d.PreventedRecycling;
            _preventedSupportUnavailable += d.PreventedSupportUnavailable;
            _preventedInsufficientPower += d.PreventedInsufficientPower;
            _preventedTrackUnavailable += d.PreventedTrackUnavailable;
            _sensorEvaluationsA += d.SensorEvaluationsA;
            _firmTrackEvaluationsA += d.FirmTrackEvaluationsA;
            _approximateTrackEvaluationsA += d.ApproximateTrackEvaluationsA;
            _noTrackEvaluationsA += d.NoTrackEvaluationsA;
            _activeSensorPowerCommittedA += d.ActiveSensorPowerCommittedA;
            _activeSensorPoweredTurnsA += d.ActiveSensorPoweredTurnsA;
            _unfundedActiveSensorRequestsA += d.UnfundedActiveSensorRequestsA;
            _sensorEvaluationsB += d.SensorEvaluationsB;
            _firmTrackEvaluationsB += d.FirmTrackEvaluationsB;
            _approximateTrackEvaluationsB += d.ApproximateTrackEvaluationsB;
            _noTrackEvaluationsB += d.NoTrackEvaluationsB;
            _activeSensorPowerCommittedB += d.ActiveSensorPowerCommittedB;
            _activeSensorPoweredTurnsB += d.ActiveSensorPoweredTurnsB;
            _unfundedActiveSensorRequestsB += d.UnfundedActiveSensorRequestsB;
            _stlOverloadActivationsA += d.StlOverloadActivationsA;
            _stlOverloadActivationsB += d.StlOverloadActivationsB;
            _sensorOverloadActivationsA += d.SensorOverloadActivationsA;
            _sensorOverloadActivationsB += d.SensorOverloadActivationsB;
            _stlOverloadRequestsA += d.StlOverloadRequestsA;
            _stlOverloadRequestsB += d.StlOverloadRequestsB;
            _sensorOverloadPlanningOpportunitiesA += d.SensorOverloadPlanningOpportunitiesA;
            _sensorOverloadPlanningOpportunitiesB += d.SensorOverloadPlanningOpportunitiesB;
            _sensorOverloadRequestsA += d.SensorOverloadRequestsA;
            _sensorOverloadRequestsB += d.SensorOverloadRequestsB;
            _ecmPowerCommittedA += d.EcmPowerCommittedA;
            _ecmPowerCommittedB += d.EcmPowerCommittedB;
            _eccmPowerCommittedA += d.EccmPowerCommittedA;
            _eccmPowerCommittedB += d.EccmPowerCommittedB;
            _ecmOverloadRequestsA += d.EcmOverloadRequestsA;
            _ecmOverloadRequestsB += d.EcmOverloadRequestsB;
            _ecmOverloadActivationsA += d.EcmOverloadActivationsA;
            _ecmOverloadActivationsB += d.EcmOverloadActivationsB;
            _eccmOverloadRequestsA += d.EccmOverloadRequestsA;
            _eccmOverloadRequestsB += d.EccmOverloadRequestsB;
            _eccmOverloadActivationsA += d.EccmOverloadActivationsA;
            _eccmOverloadActivationsB += d.EccmOverloadActivationsB;
            _overloadDeniedPowerA += d.OverloadDeniedPowerA;
            _overloadDeniedPowerB += d.OverloadDeniedPowerB;
            _overloadDeniedStrainA += d.OverloadDeniedStrainA;
            _overloadDeniedStrainB += d.OverloadDeniedStrainB;
            _baseShieldRestored += d.BaseShieldRestored;
            _tacticalShieldRestored += d.TacticalShieldRestored;
            _tacticalShieldRechargeOpportunitiesA += d.TacticalShieldRechargeOpportunitiesA;
            _tacticalShieldRechargeOpportunitiesB += d.TacticalShieldRechargeOpportunitiesB;
            _tacticalShieldRechargePowerSpentA += d.TacticalShieldRechargePowerSpentA;
            _tacticalShieldRechargePowerSpentB += d.TacticalShieldRechargePowerSpentB;
            _tacticalShieldRechargeDeniedByReserveA += d.TacticalShieldRechargeDeniedByReserveA;
            _tacticalShieldRechargeDeniedByReserveB += d.TacticalShieldRechargeDeniedByReserveB;
            _shieldlessShipTurns += d.ShieldlessShipTurns;
            _shieldAbsorption += d.ShieldAbsorption;
            _shieldArmorPrevented += d.ShieldArmorPrevented;
            _armorDamagePrevented += d.ArmorDamagePrevented;
            _armorIntegrityDamage += d.ArmorIntegrityDamage;
            _armorProtectionDamage += d.ArmorProtectionDamage;
            _hullDamage += d.HullDamage;
            _orderNoMovementRequired += d.OrderNoMovementRequired;
            _orderThrottles += d.OrderThrottles;
            _orderStlUnavailableCoercions += d.OrderStlUnavailableCoercions;
            _orderNoMovementResolved += d.OrderNoMovementResolved;
        }

        public void AddError() => _errors++;

        private static int MissileAmmunitionCapacity(
            WeaponFamily primaryFamily,
            WeaponFamily? secondaryFamily,
            TechnologyCombatProfile technology,
            AuxiliaryCombatProfile auxiliary,
            Tl1IntegratedShipBuildDocument? build)
        {
            int perBay = (technology.Missile.Ammunition ?? 0) +
                auxiliary.MissileAmmunitionBonus;
            if (build is null)
            {
                return perBay;
            }
            int missileBayCount = (primaryFamily == WeaponFamily.Missile ? 1 : 0) +
                (secondaryFamily == WeaponFamily.Missile ? 1 : 0);
            return missileBayCount * perBay;
        }

        public Tl1IntegratedTacticalCombatVariantSummary ToSummary(
            Tl1IntegratedTacticalCombatVariantDocument variant,
            IReadOnlyDictionary<string, TechnologyCombatProfile> technologyProfiles,
            IReadOnlyDictionary<string, AuxiliaryCombatProfile> auxiliaryProfiles,
            Tl1IntegratedShipBuildDocument? buildA,
            Tl1IntegratedShipBuildDocument? buildB,
            int trials)
        {
            int completed = _turns.Count;
            int denominatorInt = Math.Max(1, trials);
            double denominator = denominatorInt;
            var orderedTurns = _turns.OrderBy(value => value).ToArray();
            IntegratedCombatProfile profile = ResolveProfile(
                variant, technologyProfiles, auxiliaryProfiles);
            return new Tl1IntegratedTacticalCombatVariantSummary(
                variant.Id,
                variant.ComparisonGroup ?? string.Empty,
                profile.Label,
                profile.SideA.Id,
                profile.SideB.Id,
                profile.SideAAuxiliary.Id,
                profile.SideBAuxiliary.Id,
                variant.SideAFamily,
                variant.SideBFamily,
                variant.MovementMode,
                variant.InitialRangeHexes ?? InitialRange(variant.MovementMode),
                variant.MovementOrder,
                variant.TacticalMapRadius ?? 0,
                variant.StartingFuel ?? TacticalFuelRules.Baseline.StartingFuel,
                variant.MovementFuelPerHex ?? TacticalFuelRules.Baseline.FuelPerTraversedHex,
                variant.EvasiveManeuverFuelCost ?? TacticalFuelRules.Baseline.EvasiveManeuverFuelCost,
                variant.ProtectedCompartmentation,
                variant.DamageControl,
                profile.SideA.ShipMove,
                profile.SideB.ShipMove,
                Math.Max(profile.SideA.MissileMove, profile.SideB.MissileMove),
                Math.Max(
                    profile.SideA.Missile.MaximumRange,
                    profile.SideB.Missile.MaximumRange),
                MissileAmmunitionCapacity(
                    variant.SideAFamily,
                    variant.SideASecondaryFamily,
                    profile.SideA,
                    profile.SideAAuxiliary,
                    buildA),
                MissileAmmunitionCapacity(
                    variant.SideBFamily,
                    variant.SideBSecondaryFamily,
                    profile.SideB,
                    profile.SideBAuxiliary,
                    buildB),
                profile.SideA.Kinetic.Damage,
                profile.SideA.Kinetic.ArmorPenetration,
                profile.SideA.ArmorProtection,
                profile.BaseShieldRechargeEnabled,
                profile.EvasiveManeuversEnabled,
                profile.PdsEnabled,
                profile.EscapeDisengagementEnabled,
                trials,
                completed == 0 ? 0.0 : _turns.Average(),
                Percentile(orderedTurns, 0.50),
                Percentile(orderedTurns, 0.75),
                Percentile(orderedTurns, 0.90),
                100.0 * _longCombats / denominator,
                100.0 * _sideAWins / denominator,
                100.0 * _sideBWins / denominator,
                100.0 * _mutual / denominator,
                100.0 * (_unresolved + _errors) / denominator,
                100.0 * _destruction / denominator,
                100.0 * _offensiveMissionKill / denominator,
                100.0 * _mobilityMissionKill / denominator,
                100.0 * _disengagement / denominator,
                _finalRange / denominator,
                _minimumRange / denominator,
                _maximumRange / denominator,
                _minimumPostMovementRange / denominator,
                _postMovementFiringWindows / denominator,
                _postMovementReadyWindowsA / denominator,
                _postMovementReadyWindowsB / denominator,
                _postMovementReadyWindowsMutual / denominator,
                100.0 * _postMovementReadyTrialsA / denominator,
                100.0 * _postMovementReadyTrialsB / denominator,
                100.0 * _postMovementReadyTrialsMutual / denominator,
                _rangeChanges / denominator,
                _orderRequests / denominator,
                _orderCoercions / denominator,
                _orderNoMovementRequired / denominator,
                _orderThrottles / denominator,
                _orderStlUnavailableCoercions / denominator,
                _orderNoMovementResolved / denominator,
                _scriptedRequests / denominator,
                _preferredRequests / denominator,
                _movementA / denominator,
                _movementB / denominator,
                _fuelSpentA / denominator,
                _fuelSpentB / denominator,
                _fuelRemainingA / denominator,
                _fuelRemainingB / denominator,
                _boundaryTurnsA / denominator,
                _boundaryTurnsB / denominator,
                _immobileMovementCoercions / denominator,
                _missileReroutes / denominator,
                _targetMovementReroutes / denominator,
                _missileDistanceTraveled / denominator,
                _maximumObservedMissileDistance,
                _directActionOpportunities / denominator,
                _directShotsFired / denominator,
                _directHits / denominator,
                MeanObserved(_directHitChanceTotal, _directHitChanceObservations),
                Percent(_directHits, _directShotsFired),
                _missileLaunchOpportunities / denominator,
                _missileLaunches / denominator,
                _directActionOpportunitiesA / denominator,
                _directActionOpportunitiesB / denominator,
                _directShotsFiredA / denominator,
                _directShotsFiredB / denominator,
                _missileLaunchOpportunitiesA / denominator,
                _missileLaunchOpportunitiesB / denominator,
                _missileLaunchesA / denominator,
                _missileLaunchesB / denominator,
                _missileTerminalAttacks / denominator,
                _missileHits / denominator,
                MeanObserved(
                    _missileTerminalHitChanceTotal,
                    _missileTerminalHitChanceObservations),
                Percent(_missileHits, _missileTerminalAttacks),
                _missilesRangeExhausted / denominator,
                _preventedOutOfRange / denominator,
                _preventedSystemUnavailable / denominator,
                _preventedRecycling / denominator,
                _preventedSupportUnavailable / denominator,
                _preventedInsufficientPower / denominator,
                _pdsAttempts / denominator,
                _pdsIntercepts / denominator,
                _immobileBonusAttacks / denominator,
                _sameTurnViolations,
                _criticalSelections / denominator,
                MeanObserved(_firstCriticalTurns, _firstCriticalObservations),
                MeanObserved(
                    _firstConsequentialTurns,
                    _firstConsequentialObservations),
                100.0 * _mobilityLossObserved / denominator,
                _baseShieldRestored / denominator,
                _tacticalShieldRestored / denominator,
                _tacticalShieldRechargeOpportunitiesA / denominator,
                _tacticalShieldRechargeOpportunitiesB / denominator,
                _tacticalShieldRechargePowerSpentA / denominator,
                _tacticalShieldRechargePowerSpentB / denominator,
                _tacticalShieldRechargeDeniedByReserveA / denominator,
                _tacticalShieldRechargeDeniedByReserveB / denominator,
                _shieldlessShipTurns / denominator,
                _shieldAbsorption / denominator,
                _shieldArmorPrevented / denominator,
                _armorDamagePrevented / denominator,
                _armorIntegrityDamage / denominator,
                _armorProtectionDamage / denominator,
                _hullDamage / denominator,
                _repairAttempts / denominator,
                _repairActivations / denominator,
                _invalidRepairAttempts,
                _combinedKitsRemaining / denominator,
                _minimumCombinedKitsRemaining == int.MaxValue
                    ? 0
                    : _minimumCombinedKitsRemaining,
                _combinedHullAtEnd / denominator,
                _preventedTrackUnavailable / denominator,
                _sensorEvaluationsA / denominator,
                _firmTrackEvaluationsA / denominator,
                _approximateTrackEvaluationsA / denominator,
                _noTrackEvaluationsA / denominator,
                _activeSensorPowerCommittedA / denominator,
                _activeSensorPoweredTurnsA / denominator,
                _unfundedActiveSensorRequestsA / denominator,
                _sensorEvaluationsB / denominator,
                _firmTrackEvaluationsB / denominator,
                _approximateTrackEvaluationsB / denominator,
                _noTrackEvaluationsB / denominator,
                _activeSensorPowerCommittedB / denominator,
                _activeSensorPoweredTurnsB / denominator,
                _unfundedActiveSensorRequestsB / denominator,
                _stlOverloadActivationsA / denominator,
                _stlOverloadActivationsB / denominator,
                _sensorOverloadActivationsA / denominator,
                _sensorOverloadActivationsB / denominator,
                _stlOverloadRequestsA / denominator,
                _stlOverloadRequestsB / denominator,
                _sensorOverloadPlanningOpportunitiesA / denominator,
                _sensorOverloadPlanningOpportunitiesB / denominator,
                _sensorOverloadRequestsA / denominator,
                _sensorOverloadRequestsB / denominator,
                _ecmPowerCommittedA / denominator,
                _ecmPowerCommittedB / denominator,
                _eccmPowerCommittedA / denominator,
                _eccmPowerCommittedB / denominator,
                _ecmOverloadRequestsA / denominator,
                _ecmOverloadRequestsB / denominator,
                _ecmOverloadActivationsA / denominator,
                _ecmOverloadActivationsB / denominator,
                _eccmOverloadRequestsA / denominator,
                _eccmOverloadRequestsB / denominator,
                _eccmOverloadActivationsA / denominator,
                _eccmOverloadActivationsB / denominator,
                _overloadDeniedPowerA / denominator,
                _overloadDeniedPowerB / denominator,
                _overloadDeniedStrainA / denominator,
                _overloadDeniedStrainB / denominator,
                _errors);
        }

        private static double MeanObserved(long total, long observations) =>
            observations == 0 ? 0.0 : (double)total / observations;

        private static double Percent(long numerator, long denominator) =>
            denominator == 0 ? 0.0 : 100.0 * numerator / denominator;

        private static double Percentile(
            IReadOnlyList<int> ordered,
            double percentile)
        {
            if (ordered.Count == 0) return 0.0;
            double position = percentile * (ordered.Count - 1);
            int lower = (int)Math.Floor(position);
            int upper = (int)Math.Ceiling(position);
            if (lower == upper) return ordered[lower];
            double fraction = position - lower;
            return ordered[lower] +
                (ordered[upper] - ordered[lower]) * fraction;
        }
    }

