    private sealed class IntegratedSide
    {
        public IntegratedSide(
            string id,
            WeaponFamily family,
            WeaponFamily? secondaryFamily,
            ShipDamageState ship,
            TacticalPowerLedger power,
            IntegratedCombatProfile profile,
            TechnologyCombatProfile technology,
            AuxiliaryCombatProfile auxiliary,
            Tl1IntegratedShipBuildDocument? build,
            int normalStlMovement,
            int backgroundTacticalPowerCommitment,
            Tl1TacticalPowerDoctrine powerDoctrine,
            int reactorOutputPerMain)
        {
            Id = id;
            Family = family;
            SecondaryFamily = secondaryFamily;
            Ship = ship;
            Power = power;
            Profile = profile;
            Technology = technology;
            Auxiliary = auxiliary;
            Build = build;
            NormalStlMovement = normalStlMovement;
            BackgroundTacticalPowerCommitment = backgroundTacticalPowerCommitment;
            PowerDoctrine = powerDoctrine;
            ReactorOutputPerMain = reactorOutputPerMain;
            PdsAmmunitionRemaining = build is not null
                ? InitialBuildPdsAmmunition(
                    build.KineticPdsCount, build.PdsFamily, build.PdsAmmunition)
                : auxiliary.PdsAmmunition;
            CombatBatteryChargesRemaining = auxiliary.CombatBatteryCharges;
            CapacitorStoredPower = auxiliary.CapacitorCapacity;
            ShieldBatteryChargesRemaining = auxiliary.ShieldBatteryCharges;
            IndependentCombatBatteries = auxiliary.PowerComponents
                .Where(component => component.Kind ==
                    AuxiliaryPowerComponentKind.CombatBattery)
                .Select(component => new IndependentCombatBatteryInstallation(
                    $"power-aux-{component.Id}",
                    new CombatBatteryState(
                        component.CombatBatteryCharges,
                        component.CombatBatteryGain,
                        1)))
                .ToArray();
            IndependentCapacitors = auxiliary.PowerComponents
                .Where(component => component.Kind ==
                    AuxiliaryPowerComponentKind.PowerCapacitor)
                .Select(component => new IndependentCapacitorInstallation(
                    $"power-aux-{component.Id}",
                    new CapacitorBankState(
                        component.CapacitorCapacity,
                        component.CapacitorChargeRate,
                        component.CapacitorDischargeRate,
                        component.CapacitorCapacity)))
                .ToArray();
            StatefulCombatBattery = !auxiliary.HasIndependentPowerComponents &&
                    auxiliary.HasCombatBattery
                ? new CombatBatteryState(
                    auxiliary.CombatBatteryCharges,
                    auxiliary.CombatBatteryGain,
                    1)
                : null;
            StatefulCapacitor = !auxiliary.HasIndependentPowerComponents &&
                    auxiliary.HasPowerCapacitor && auxiliary.CapacitorChargeRate > 0
                ? new CapacitorBankState(
                    auxiliary.CapacitorCapacity,
                    auxiliary.CapacitorChargeRate,
                    auxiliary.CapacitorDischargeRate,
                    auxiliary.CapacitorCapacity)
                : null;
        }

