        public void RecordDirectAction(string sideId, DirectCommit commit)
        {
            if (!commit.Opportunity) return;
            bool sideA = sideId switch
            {
                "A" => true,
                "B" => false,
                _ => throw new ArgumentOutOfRangeException(nameof(sideId), "Integrated diagnostic telemetry side must be A or B."),
            };
            DirectActionOpportunities++;
            if (sideA) DirectActionOpportunitiesA++; else DirectActionOpportunitiesB++;
            if (commit.Fired)
            {
                DirectShotsFired++;
                if (sideA) DirectShotsFiredA++; else DirectShotsFiredB++;
                DirectHitChanceTotal += commit.FinalHitChance;
                DirectHitChanceObservations++;
                if (commit.Hit) DirectHits++;
            }
            else
            {
                RecordPrevention(commit.PreventionReason);
            }
        }

        public void RecordMissileLaunch(string sideId, MissileLaunchCommit commit)
        {
            if (!commit.Opportunity) return;
            bool sideA = sideId switch
            {
                "A" => true,
                "B" => false,
                _ => throw new ArgumentOutOfRangeException(nameof(sideId), "Integrated diagnostic telemetry side must be A or B."),
            };
            MissileLaunchOpportunities++;
            if (sideA) MissileLaunchOpportunitiesA++; else MissileLaunchOpportunitiesB++;
            if (commit.Launched)
            {
                if (sideA) MissileLaunchesA++; else MissileLaunchesB++;
            }
            else
            {
                RecordPrevention(commit.PreventionReason);
            }
        }

        public void RecordMissileTerminalAttack(int chance)
        {
            MissileTerminalAttacks++;
            MissileTerminalHitChanceTotal += chance;
            MissileTerminalHitChanceObservations++;
        }

        public void RecordSensorEvaluation(
            string sideId,
            SensorTurnState state,
            IntegratedTrackQuality quality)
        {
            bool sideA = sideId == "A";
            if (sideA)
            {
                SensorEvaluationsA++;
                if (quality == IntegratedTrackQuality.Firm) FirmTrackEvaluationsA++;
                else if (quality == IntegratedTrackQuality.Approximate) ApproximateTrackEvaluationsA++;
                else NoTrackEvaluationsA++;
                ActiveSensorPowerCommittedA += state.ActivePower;
                if (state.ActivePower > 0) ActiveSensorPoweredTurnsA++;
                if (state.UnfundedActiveRequest) UnfundedActiveSensorRequestsA++;
                if (state.Overloaded) SensorOverloadActivationsA++;
            }
            else
            {
                SensorEvaluationsB++;
                if (quality == IntegratedTrackQuality.Firm) FirmTrackEvaluationsB++;
                else if (quality == IntegratedTrackQuality.Approximate) ApproximateTrackEvaluationsB++;
                else NoTrackEvaluationsB++;
                ActiveSensorPowerCommittedB += state.ActivePower;
                if (state.ActivePower > 0) ActiveSensorPoweredTurnsB++;
                if (state.UnfundedActiveRequest) UnfundedActiveSensorRequestsB++;
                if (state.Overloaded) SensorOverloadActivationsB++;
            }
        }

        public void RecordStlOverload(string sideId)
        {
            if (sideId == "A") StlOverloadActivationsA++;
            else StlOverloadActivationsB++;
        }

        public void RecordStlOverloadRequest(string sideId)
        {
            if (sideId == "A") StlOverloadRequestsA++;
            else StlOverloadRequestsB++;
        }

        public void RecordSensorOverloadPlanningOpportunity(string sideId)
