            else SensorOverloadRequestsB++;
        }

        public void RecordEwPower(string sideId, bool isEcm, int power)
        {
            if (sideId == "A")
            {
                if (isEcm) EcmPowerCommittedA += power;
                else EccmPowerCommittedA += power;
            }
            else
            {
                if (isEcm) EcmPowerCommittedB += power;
                else EccmPowerCommittedB += power;
            }
        }

