        public void RecordShieldRecharge(
            string sideId,
            ShieldRechargeResult recharge,
            bool tacticalOpportunity,
            bool deniedByReserve)
        {
            BaseShieldRestored += recharge.BaseRestored;
            TacticalShieldRestored += recharge.TacticalRestored;
            bool sideA = sideId == "A";
            if (sideA)
            {
                if (tacticalOpportunity) TacticalShieldRechargeOpportunitiesA++;
                TacticalShieldRechargePowerSpentA += recharge.TacticalPowerSpent;
                if (deniedByReserve) TacticalShieldRechargeDeniedByReserveA++;
            }
            else
            {
                if (tacticalOpportunity) TacticalShieldRechargeOpportunitiesB++;
                TacticalShieldRechargePowerSpentB += recharge.TacticalPowerSpent;
                if (deniedByReserve) TacticalShieldRechargeDeniedByReserveB++;
            }
        }

        public void RecordDamage(DamageApplication damage)
        {
            ShieldAbsorption += damage.ShieldAbsorption;
            ShieldArmorPrevented += damage.ShieldArmorPrevented;
            ArmorDamagePrevented += damage.ArmorDamagePrevented;
            ArmorIntegrityDamage += damage.ArmorIntegrityDamage;
            ArmorProtectionDamage += damage.ArmorProtectionDamage;
            HullDamage += damage.HullDamage;
        }

        public void RecordOrderStatus(RangeOrderResolutionStatus status)
        {
            switch (status)
            {
                case RangeOrderResolutionStatus.NoMovementRequired:
                    OrderNoMovementRequired++;
                    break;
                case RangeOrderResolutionStatus.Throttled:
                    OrderThrottles++;
                    break;
                case RangeOrderResolutionStatus.StlUnavailable:
                    OrderStlUnavailableCoercions++;
                    break;
                case RangeOrderResolutionStatus.NoMovementResolved:
                    OrderNoMovementResolved++;
                    break;
            }
        }

        private void RecordPrevention(WeaponActionPreventionReason reason)
        {
            switch (reason)
            {
                case WeaponActionPreventionReason.OutOfRange:
                    PreventedOutOfRange++;
                    break;
                case WeaponActionPreventionReason.SystemUnavailable:
                    PreventedSystemUnavailable++;
                    break;
                case WeaponActionPreventionReason.Recycling:
                    PreventedRecycling++;
                    break;
                case WeaponActionPreventionReason.SupportUnavailable:
                    PreventedSupportUnavailable++;
                    break;
                case WeaponActionPreventionReason.InsufficientPower:
                    PreventedInsufficientPower++;
                    break;
                case WeaponActionPreventionReason.TrackUnavailable:
                    PreventedTrackUnavailable++;
                    break;
            }
        }
    }

